['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

#define INITIAL_CAPACITY 10000
#define HASH_SEED 5381

// Hash function to map keys to indices
unsigned int hash(int key, size_t capacity) {
    unsigned long hash = HASH_SEED;
    hash = ((hash << 5) + hash) + key; // hash * 33 + key
    return (unsigned int)(hash % capacity);
}

RecordCollection* create_record_collection() {
    RecordCollection* rc = malloc(sizeof(RecordCollection));
    if (!rc) return NULL;

    rc->capacity = INITIAL_CAPACITY;
    rc->table = calloc(rc->capacity, sizeof(Node*));
    if (!rc->table) {
        free(rc->table);
        free(rc);
        return NULL;
    }

    rc->size = 0;
    pthread_mutex_init(&rc->lock, NULL);
    return rc;
}

void log_message(const char* message) {
    printf("LOG: %s\n", message); // Simple logging mechanism
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

int add_record(RecordCollection* rc, long offset, int key, Record record) {
    pthread_mutex_lock(&rc->lock);

    unsigned int index = hash(key, rc->capacity);
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        log_message("Failed to allocate memory for new node");
        pthread_mutex_unlock(&rc->lock);
        return -1;
    }

    newNode->offset = offset;
    newNode->key = key;
    newNode->record = record;
    newNode->next = rc->table[index];
    rc->table[index] = newNode;

    if (rc->size >= rc->capacity / 2) {
        // Resize table
        size_t new_capacity = rc->capacity * 2;
        Node** new_table = calloc(new_capacity, sizeof(Node*));
        if (!new_table) {
            free_node(newNode);
            log_message("Failed to allocate memory for resized table");
            pthread_mutex_unlock(&rc->lock);
            return -1;
        }

        for (size_t i = 0; i < rc->capacity; ++i) {
            Node* head = rc->table[i];
            while (head) {
                Node* next = head->next;
                unsigned int new_index = hash(head->key, new_capacity);
                head->next = new_table[new_index];
                new_table[new_index] = head;
                head = next;
            }
        }

        free(rc->table);
        rc->table = new_table;
        rc->capacity = new_capacity;
    }

    rc->size++;
    pthread_mutex_unlock(&rc->lock);

    log_message("Record added successfully");
    return 0;
}

int remove_record(RecordCollection* rc, int key) {
    pthread_mutex_lock(&rc->lock);

    unsigned int index = hash(key, rc->capacity);
    Node *head = rc->table[index], *prev = NULL;

    while (head && head->key != key) {
        prev = head;
        head = head->next;
    }

    if (!head) {
        pthread_mutex_unlock(&rc->lock);
        log_message("Record not found");
        return -1;
    }

    if (prev) {
        prev->next = head->next;
    } else {
        rc->table[index] = head->next;
    }

    free_node(head);
    rc->size--;

    pthread_mutex_unlock(&rc->lock);

    log_message("Record removed successfully");
    return 0;
}

Record* get_record(RecordCollection* rc, int key) {
    unsigned int index = hash(key, rc->capacity);
    Node* node = rc->table[index];

    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&rc->lock);
            return &(node->record);
        }
        node = node->next;
    }

    log_message("Record not found");
    return NULL; // Record not found
}

void free_record_collection(RecordCollection* rc) {
    if (!rc) return;

    for (size_t i = 0; i < rc->capacity; ++i) {
        Node* head = rc->table[i];
        while (head) {
            Node* temp = head;
            head = head->next;
            free_node(temp);
        }
    }

    free(rc->table);
    pthread_mutex_destroy(&rc->lock);
    free(rc);

    log_message("Record collection freed successfully");
}

// Usage Example
/*
int main() {
    RecordCollection* rc = create_record_collection();

    Record record1 = {42};
    add_record(rc, 1000L, 1, record1);

    Record* result = get_record(rc, 1);
    if (result) printf("Record found: %d\n", result->value);

    remove_record(rc, 1);
    free_record_collection(rc);

    return 0;
}
*/
```']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUFFER_SIZE 4096

void log_message(const char *message, const char *log_dir);
void display_usage();

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Error: Not enough arguments provided.\n");
        display_usage();
        return EXIT_FAILURE;
    }

    int count_lines = 0, count_chars = 0, count_words = 0;
    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        log_message("Error: Unable to open input file.", NULL);
        fprintf(stderr, "Error: Unable to open input file.\n");
        return EXIT_FAILURE;
    }

    char *output_path = NULL;
    for (int i = 2; i < argc; ++i) {
        if (strcmp(argv[i], "-l") == 0) count_lines = 1;
        else if (strcmp(argv[i], "-c") == 0) count_chars = 1;
        else if (strcmp(argv[i], "-w") == 0) count_words = 1;
        else if (strncmp(argv[i], "-o ", 3) == 0) {
            output_path = strdup(argv[i] + 3);
        } else if (strcmp(argv[i], "--help") == 0) {
            display_usage();
            return EXIT_SUCCESS;
        }
    }

    FILE *output_file;
    if (output_path)
        output_file = fopen(output_path, "w");
    else
        output_file = stdout;

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input_file)) {
        if (count_lines) count_lines++;
        if (count_chars) count_chars += strlen(buffer);
        if (count_words) {
            int line_word_count = 0;
            char *token = strtok(buffer, " \t\n");
            while (token) {
                line_word_count++;
                token = strtok(NULL, " \t\n");
            }
            count_words += line_word_count;
        }

        fputs(buffer, output_file);
    }

    if (output_path)
        fclose(output_file);

    fprintf(output_file, "\nTotal Lines: %d\n", count_lines ? count_lines : 0);
    fprintf(output_file, "Total Characters: %d\n", count_chars ? count_chars : 0);
    fprintf(output_file, "Total Words: %d\n", count_words ? count_words : 0);

    fclose(input_file);

    if (output_path) {
        free(output_path);
    }

    return EXIT_SUCCESS;
}

void log_message(const char *message, const char *log_dir) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    if (!log_dir || !*log_dir)
        log_dir = ".";

    FILE *log_file = fopen(strcat(log_dir, "/process_log.txt"), "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

void display_usage() {
    printf("Usage: text_processor <input_file> [options]\n"
           "Options:\n"
           "  -l       Count the number of lines.\n"
           "  -c       Count the number of characters in each line.\n"
           "  -w       Count the number of words in each line.\n"
           "  -o <file> Redirect output to a specified file.\n"
           "  --help   Display this help message.\n");
}
```

### Key Points:
- **Buffering**: The program reads input files using a buffer size of 4096 bytes, optimizing memory usage for large files.
- **Command-Line Parsing**: It processes command-line arguments to enable or disable specific counting features and specify output redirection.
- **Logging**: Errors are logged with timestamps. You can extend this by providing a log directory as an argument or environment variable.
- **Usage Instructions**: The `--help` option provides usage instructions.
- **Error Handling**: The program checks for file open errors, prints error messages to stderr, and logs them.

This code is designed to be efficient in terms of memory and performance, adhering to typical requirements for text processing tools. Adjust logging paths and buffer sizes as needed based on specific system constraints or additional requirements.']

['Below is a C code implementation for the described task. This code utilizes multiple libraries such as `libjson-c` for JSON parsing, `yaml-cpp` for YAML parsing, and POSIX threads for concurrent processing. It also uses efficient I/O operations to handle large files.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>
#include <yaml-cpp/yaml.h>

#define MAX_EVENTS 10000

typedef struct {
    const char *input_file;
    const char *output_dir;
    json_object *initial_rules;
    YAML::Node additional_config;
    int worker_pool_size;
} LogProcessorConfig;

typedef struct {
    pthread_t thread_id;
    LogProcessorConfig config;
    int start_event;
    int end_event;
} WorkerData;

pthread_mutex_t output_mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_log_file(void *arg) {
    WorkerData *worker_data = (WorkerData*) arg;
    LogProcessorConfig config = worker_data->config;

    // Open input file
    FILE *file = fopen(config.input_file, "rb");
    if (!file) {
        perror("Failed to open log file");
        pthread_exit(NULL);
    }

    // Allocate buffer for reading events (adjust size as necessary)
    char event_buffer[1024];
    size_t bytes_read;

    for (int i = worker_data->start_event; i <= worker_data->end_event && !feof(file); ++i) {
        // Read and parse each event
        bytes_read = fread(event_buffer, 1, sizeof(event_buffer), file);

        if (bytes_read > 0) {
            // Apply initial rules from JSON
            // Example rule application (implement specific logic)
            json_object *parsed_event = json_tokener_parse(event_buffer);
            if (json_object_array_length(parsed_event)) {
                // Further processing with additional YAML config
                // Example: config.additional_config["rule"].as<std::string>();

                // Write processed event to output
                pthread_mutex_lock(&output_mutex);

                char output_path[256];
                snprintf(output_path, sizeof(output_path), "%s/event_%d.txt", config.output_dir, i);
                FILE *out_file = fopen(output_path, "a");
                if (out_file) {
                    fwrite(event_buffer, 1, bytes_read, out_file);
                    fclose(out_file);
                }
                pthread_mutex_unlock(&output_mutex);
            }

            json_object_put(parsed_event); // Free memory
        } else {
            break;
        }
    }

    fclose(file);
    pthread_exit(NULL);
}

void process_large_log(const char *input_file, const char *output_dir, const char *json_rules, const char *yaml_config_path, int worker_pool_size) {
    // Load JSON rules
    json_object *initial_rules = json_tokener_parse(json_rules);

    // Load YAML config
    YAML::Node additional_config;
    if (yaml_config_path) {
        additional_config = YAML::LoadFile(yaml_config_path);
    }

    LogProcessorConfig config = { input_file, output_dir, initial_rules, additional_config, worker_pool_size };

    pthread_t *threads = malloc(sizeof(pthread_t) * worker_pool_size);
    WorkerData *workers = malloc(sizeof(WorkerData) * worker_pool_size);

    // Divide the file into chunks for each worker
    int total_events = 1000000; // Example: Assume we know number of events or find out dynamically
    int chunk_size = total_events / worker_pool_size;

    for (int i = 0; i < worker_pool_size; ++i) {
        workers[i].config = config;
        workers[i].start_event = i * chunk_size + 1;
        workers[i].end_event = (i == worker_pool_size - 1) ? total_events : (i + 1) * chunk_size;

        pthread_create(&threads[i], NULL, process_log_file, &workers[i]);
    }

    for (int i = 0; i < worker_pool_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(workers);
    json_object_put(initial_rules); // Free JSON memory
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_dir> <json_rules> <yaml_config_path> <worker_pool_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_dir = argv[2];
    const char *json_rules = argv[3];
    const char *yaml_config_path = argv[4];
    int worker_pool_size = atoi(argv[5]);

    process_large_log(input_file, output_dir, json_rules, yaml_config_path, worker_pool_size);

    return EXIT_SUCCESS;
}
```

### Notes:

- The code assumes that the number of events is known or can be determined dynamically. Adjust `total_events` accordingly.
- Proper error handling and specific rule application logic need to be implemented as per actual use cases.
- Thread safety is ensured using a mutex when writing to output files.
- Memory management for JSON objects is handled with `json_object_put`.
- Consider adding more advanced logging or monitoring features for large-scale failures.']

