#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define BUFFER_SIZE 1024
#define CACHE_SIZE 10

typedef struct {
    char hostname[BUFFER_SIZE];
    struct in_addr ip;
} DnsCacheEntry;

DnsCacheEntry dns_cache[CACHE_SIZE];

int resolve_dns(const char *hostname, struct in_addr *ip) {
    int i;

    // Check cache first
    for (i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            *ip = dns_cache[i].ip;
            return 1;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        perror("getaddrinfo failed");
        return 0;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip->s_addr = ipv4->sin_addr.s_addr;

        // Add to cache
        for (i = 0; i < CACHE_SIZE; ++i) {
            if (dns_cache[i].hostname[0] == '\0') { // Find empty slot
                strncpy(dns_cache[i].hostname, hostname, BUFFER_SIZE);
                dns_cache[i].ip = *ip;
                break;
            }
        }

        freeaddrinfo(res);
        return 1;
    }

    freeaddrinfo(res);
    return 0;
}

double calculate_average(char *line) {
    int num_count = 0;
    double sum = 0, last_two_sum = 0;
    char *token = strtok(line, " ");

    while (token != NULL) {
        if (sscanf(token, "%lf", &sum) == 1) {
            if (num_count >= 2) {
                last_two_sum = sum + *(--(double[]){strtok(NULL, " "), 0});
            }
            num_count++;
        }
        token = strtok(NULL, " ");
    }

    return num_count >= 2 ? last_two_sum / 2 : 0;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        // Remove newline character
        buffer[strcspn(buffer, "\n")] = '\0';

        double avg = calculate_average(buffer);
        printf("%s,%.2f\n", buffer, avg);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <hostname> <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct in_addr ip;
    if (!resolve_dns(argv[1], &ip)) {
        fprintf(stderr, "DNS resolution failed for %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    printf("Resolved IP: %s\n", inet_ntoa(ip));

    process_file(argv[2]);

    return EXIT_SUCCESS;
}
