['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
    size_t max_size;
    char filename[256];
} Logger;

Logger logger;

void init_logger(const char *filename, size_t max_size) {
    pthread_mutex_init(&logger.lock, NULL);
    snprintf(logger.filename, sizeof(logger.filename), "%s.log", filename);
    logger.file = fopen(logger.filename, "a");
    if (!logger.file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    logger.max_size = max_size;
}

void rotate_log_file() {
    fclose(logger.file);
    char new_filename[256];
    time_t now = time(NULL);
    snprintf(new_filename, sizeof(new_filename), "%s.%ld", logger.filename, (long)now);
    rename(logger.filename, new_filename);
    logger.file = fopen(logger.filename, "a");
}

void log_message(int level, const char *format, ...) {
    pthread_mutex_lock(&logger.lock);

    if (!logger.file || feof(logger.file)) {
        rotate_log_file();
    }

    // Check file size for rotation
    fseek(logger.file, 0, SEEK_END);
    long current_size = ftell(logger.file);
    if (current_size > logger.max_size) {
        rotate_log_file();
    }

    va_list args;
    va_start(args, format);

    char log_entry[1024];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_buffer[20];
    strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    int written = snprintf(log_entry, sizeof(log_entry),
                           "[%s] [Level %d] ", time_buffer, level);
    vsnprintf(log_entry + written, sizeof(log_entry) - written, format, args);

    fwrite(log_entry, 1, strlen(log_entry), logger.file);
    fflush(logger.file);

    va_end(args);

    pthread_mutex_unlock(&logger.lock);
}

void cleanup_logger() {
    if (logger.file) {
        fclose(logger.file);
    }
    pthread_mutex_destroy(&logger.lock);
}
```

This code defines a `Logger` structure that manages file operations and locking for thread safety. It includes functions to initialize the logger, log messages at different levels using variadic arguments, rotate logs based on size limits, and clean up resources. The use of mutexes ensures that multiple threads can safely write to the log concurrently.']

