['Below is an outline for a modular cryptographic library in C, focusing on dynamic module loading/unloading, unified interface, and other considerations as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <pthread.h>

// Define the structure to hold function pointers and configurations
typedef struct {
    void* handle;
    int (*init)(void);
    void (*cleanup)(void);
    void (*hash)(const unsigned char *data, size_t length, unsigned char *digest, size_t digest_length);
    void (*encrypt)(const unsigned char *plaintext, size_t length, unsigned char *ciphertext, size_t block_size, const unsigned char *key, size_t key_length, int mode);
} CryptoModule;

// Unified interface for cryptographic operations
typedef struct {
    CryptoModule* module;
    pthread_mutex_t lock; // Mutex for thread-safety
} CryptoContext;

// Function prototypes
CryptoContext* crypto_create_context(const char* module_path);
int crypto_load_module(CryptoContext* context, const char* module_path);
void crypto_unload_module(CryptoContext* context);
void crypto_hash(const CryptoContext* context, const unsigned char *data, size_t length, unsigned char *digest, size_t digest_length);
void crypto_encrypt(const CryptoContext* context, const unsigned char *plaintext, size_t length, unsigned char *ciphertext, size_t block_size, const unsigned char *key, size_t key_length, int mode);
void crypto_destroy_context(CryptoContext* context);

// Implementations
CryptoContext* crypto_create_context(const char* module_path) {
    CryptoContext* ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    if (!ctx) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_init(&ctx->lock, NULL);
    if (!crypto_load_module(ctx, module_path)) {
        crypto_destroy_context(ctx);
        return NULL;
    }

    ctx->module = malloc(sizeof(CryptoModule));
    if (!ctx->module) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&ctx->lock);
        free(ctx);
        return NULL;
    }

    return ctx;
}

int crypto_load_module(CryptoContext* context, const char* module_path) {
    context->module->handle = dlopen(module_path, RTLD_LAZY);
    if (!context->module->handle) {
        fprintf(stderr, "Error loading module: %s\n", dlerror());
        return 0;
    }

    // Load functions from the module
    context->module->init = (int (*)(void))dlsym(context->module->handle, "init");
    context->module->cleanup = (void (*)(void))dlsym(context->module->handle, "cleanup");
    context->module->hash = (void (*)(const unsigned char*, size_t, unsigned char*, size_t))dlsym(context->module->handle, "hash");
    context->module->encrypt = (void (*)(const unsigned char*, size_t, unsigned char*, size_t, const unsigned char*, size_t, int))dlsym(context->module->handle, "encrypt");

    if (!context->module->init || !context->module->cleanup || !context->module->hash || !context->module->encrypt) {
        fprintf(stderr, "Error loading functions: %s\n", dlerror());
        dlclose(context->module->handle);
        return 0;
    }

    return context->module->init();
}

void crypto_unload_module(CryptoContext* context) {
    if (context && context->module) {
        if (context->module->cleanup) {
            context->module->cleanup();
        }

        dlclose(context->module->handle);
    }
}

void crypto_hash(const CryptoContext* context, const unsigned char *data, size_t length, unsigned char *digest, size_t digest_length) {
    pthread_mutex_lock(&context->lock);

    if (context && context->module && context->module->hash) {
        context->module->hash(data, length, digest, digest_length);
    }

    pthread_mutex_unlock(&context->lock);
}

void crypto_encrypt(const CryptoContext* context, const unsigned char *plaintext, size_t length, unsigned char *ciphertext, size_t block_size, const unsigned char *key, size_t key_length, int mode) {
    pthread_mutex_lock(&context->lock);

    if (context && context->module && context->module->encrypt) {
        context->module->encrypt(plaintext, length, ciphertext, block_size, key, key_length, mode);
    }

    pthread_mutex_unlock(&context->lock);
}

void crypto_destroy_context(CryptoContext* context) {
    if (!context) return;

    crypto_unload_module(context);

    free(context->module);
    pthread_mutex_destroy(&context->lock);
    free(context);
}

int main() {
    const char* module_path = "./crypto_module.so";
    CryptoContext* ctx = crypto_create_context(module_path);

    if (ctx) {
        unsigned char data[] = "Sample Data for Hashing";
        unsigned char digest[32]; // Example hash size

        crypto_hash(ctx, data, sizeof(data), digest, sizeof(digest));

        unsigned char plaintext[] = "Sample Plaintext";
        unsigned char ciphertext[64];
        unsigned char key[] = "examplekey";

        crypto_encrypt(ctx, plaintext, sizeof(plaintext), ciphertext, 16, key, sizeof(key), 1); // Example mode

        crypto_destroy_context(ctx);
    }

    return 0;
}
```

### Key Considerations:
- **Dynamic Module Loading**: Uses `dlopen` and `dlsym` for loading shared libraries.
- **Thread Safety**: Mutexes are used to ensure thread safety in multi-threaded environments.
- **Resource Management**: Properly loads, unloads modules, and manages memory using `malloc`, `free`, and `dlclose`.
- **Error Handling & Logging**: Uses standard error output for logging errors; this can be enhanced with more sophisticated logging mechanisms.

This framework allows you to load cryptographic algorithms as dynamic libraries, providing flexibility and performance optimization. It uses a unified interface for hashing and encryption operations, making it easy to integrate new modules.']

