#include <forward_list>
#include <algorithm>
#include <mutex>

std::mutex mtx; // Mutex for ensuring thread safety

void insertAndSort(std::forward_list<int>& flist, int targetValue, int newValue, int sortOrder) {
    std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety

    auto pos = flist.before_begin();
    bool found = false;

    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == targetValue) {
            pos = it;
            found = true;
            break;
        }
    }

    if (!found) {
        flist.push_back(newValue);
    } else {
        flist.insert_after(pos, newValue);
    }

    if (sortOrder == 1) { // Ascending
        std::forward_list<int> sortedList(flist);
        sortedList.sort();
        flist = std::move(sortedList);
    } else if (sortOrder == 2) { // Descending
        std::forward_list<int> sortedList(flist);
        sortedList.sort(std::greater<int>());
        flist = std::move(sortedList);
    }
}
