#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <boost/algorithm/string/predicate.hpp>
#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <functional>
#include <thread>
#include <atomic>
#include <chrono>

namespace net = boost::asio;          // from <boost/asio.hpp>
using tcp = net::ip::tcp;             // from <boost/asio/ip/tcp.hpp>
namespace beast = boost::beast;       // from <boost/beast.hpp>
using http = beast::http;             // from <boost/beast/http.hpp>

class ThreadPool {
public:
    ThreadPool(size_t numThreads);
    ~ThreadPool();
    template<class F> void enqueue(F f);

private:
    std::vector<std::thread> workers;
    net::mutex queueMutex;
    net::condition_variable condition;
    bool stop;
};

ThreadPool::ThreadPool(size_t numThreads)
    : stop(false) {
    for (size_t i = 0; i < numThreads; ++i) {
        workers.emplace_back([this] {
            while (true) {
                std::function<void()> task;
                {
                    net::unique_lock<net::mutex> lock(this->queueMutex);
                    this->condition.wait(lock, [this] { return this->stop || !tasks.empty(); });
                    if (this->stop && tasks.empty())
                        return;
                    task = std::move(tasks.front());
                    tasks.pop();
                }
                task();
            }
        });
    }
}

ThreadPool::~ThreadPool() {
    {
        net::unique_lock<net::mutex> lock(queueMutex);
        stop = true;
    }
    condition.notify_all();
    for (std::thread &worker : workers)
        worker.join();
}

template<class F>
void ThreadPool::enqueue(F f) {
    {
        net::unique_lock<net::mutex> lock(queueMutex);
        tasks.emplace(std::move(f));
    }
    condition.notify_one();
}

class HttpClient {
public:
    HttpClient(net::io_context& ioc, ThreadPool& pool, size_t maxRetries = 3);
    void run(const std::string& targetHost, const std::string& path);

private:
    net::io_context& ioc_;
    tcp::resolver resolver_;
    ThreadPool& pool_;
    int maxRetries_;

    void sendRequest(beast::tcp_stream& stream, beast::http::request<beast::http::string_body>& req);
    void handleResponse(beast::tcp_stream& stream, beast::flat_buffer buffer, const std::function<void(const http::response<http::dynamic_body>&)>& handler);

    static void logError(std::string error);
};

HttpClient::HttpClient(net::io_context& ioc, ThreadPool& pool, size_t maxRetries)
    : ioc_(ioc), resolver_(ioc_), pool_(pool), maxRetries_(maxRetries) {}

void HttpClient::run(const std::string& targetHost, const std::string& path) {
    auto const results = resolver_.resolve(targetHost, "http");
    for (auto const& result : results) {
        beast::tcp_stream stream(ioc_);
        try {
            stream.connect(result);
            http::request<http::string_body> req{http::verb::get, path, 11};
            sendRequest(stream, req);
        } catch (...) {
            logError("Connection failed");
        }
    }
}

void HttpClient::sendRequest(beast::tcp_stream& stream, beast::http::request<beast::http::string_body>& req) {
    pool_.enqueue([this, &stream, req = std::move(req)](int retriesRemaining) mutable {
        if (retriesRemaining <= 0) return;

        try {
            http::write(stream, req);
            beast::flat_buffer buffer;
            handleResponse(stream, buffer,
                [this](const http::response<http::dynamic_body>& res) {
                    std::cout << "Response: " << res.result() << "\n";
                });
        } catch (std::exception const& e) {
            logError(std::string("Send request error: ") + e.what());
            sendRequest(stream, req, retriesRemaining - 1);
        }
    }(maxRetries_));
}

void HttpClient::handleResponse(beast::tcp_stream& stream, beast::flat_buffer buffer,
                                const std::function<void(const http::response<http::dynamic_body>&)>& handler) {
    pool_.enqueue([this, &stream, buffer = std::move(buffer), handler](int retriesRemaining) mutable {
        if (retriesRemaining <= 0) return;

        try {
            beast::error_code ec;
            http::response<http::dynamic_body> res;
            http::read(stream, buffer, res, ec);

            if (ec && ec != http::error::end_of_stream)
                throw beast::system_error{ec};

            handler(res);
        } catch (std::exception const& e) {
            logError(std::string("Response error: ") + e.what());
            handleResponse(stream, buffer, handler, retriesRemaining - 1);
        }
    }(maxRetries_));
}

void HttpClient::logError(std::string error) {
    std::cerr << "ERROR: " << error << "\n";
}

int main(int argc, char* argv[]) {
    try {
        if (argc != 3)
            return EXIT_FAILURE;

        net::io_context ioc{1};
        size_t threadPoolSize = std::thread::hardware_concurrency();
        ThreadPool pool(threadPoolSize);

        HttpClient client(ioc, pool);
        client.run(argv[1], argv[2]);

        ioc.run();
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

