#include <boost/thread/shared_mutex.hpp>
#include <queue>
#include <chrono>

namespace logging = boost::log;
namespace src = boost::log::sources;
namespace sinks = boost::log::sinks;
namespace keywords = boost::log::keywords;

enum class LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    FATAL
};

class LogBuffer {
public:
    void log(const std::string& message) {
        std::unique_lock lock(mutex_);
        buffer_.push(message);
        cv_.notify_one();
    }

    bool try_pop(std::string& message) {
        std::unique_lock lock(mutex_);
        if (buffer_.empty()) return false;
        message = buffer_.front();
        buffer_.pop();
        return true;
    }

    void flush() {
        std::unique_lock lock(mutex_);
        while (!buffer_.empty()) {
            auto msg = buffer_.front();
            buffer_.pop();
            // Send to backend (omitted for brevity)
        }
    }

private:
    mutable boost::shared_mutex mutex_;
    std::queue<std::string> buffer_;
    std::condition_variable cv_;
};

class LoggingFramework {
public:
    LoggingFramework() {
        logging::add_common_attributes();

        auto backend = boost::make_shared<sinks::synchronous_sink<sinks::text_ostream_backend>>();
        backend->locked_backend()->add_stream(
            &std::cout, keywords::format = "[%TimeStamp%] [%Severity%]: %Message%"
        );

        sink_ = std::move(backend);

        logger_ = logging::core::get()->add_sink(sink_);
    }

    void log(LogLevel level, const std::string& message) {
        switch (level) {
            case LogLevel::DEBUG: BOOST_LOG_SEV(logger_, logging::trivial::debug) << message; break;
            case LogLevel::INFO:  BOOST_LOG_SEV(logger_, logging::trivial::info) << message; break;
            case LogLevel::WARNING: BOOST_LOG_SEV(logger_, logging::trivial::warning) << message; break;
            case LogLevel::ERROR:  BOOST_LOG_SEV(logger_, logging::trivial::error) << message; break;
            case LogLevel::FATAL:  BOOST_LOG_SEV(logger_, logging::trivial::fatal) << message; break;
        }
    }

private:
    sinks::synchronous_sink<sinks::text_ostream_backend> sink_;
    src::severity_logger<logging::trivial::severity_level> logger_;

public:
    static LoggingFramework& instance() {
        static LoggingFramework framework;
        return framework;
    }

    LogBuffer& get_log_buffer() {
        return log_buffer_;
    }
};

class LogManager {
public:
    void start_logging_thread() {
        logging_thread_ = std::thread([this] { process_logs(); });
    }

    ~LogManager() {
        if (logging_thread_.joinable()) {
            logging_thread_.join();
        }
    }

private:
    void process_logs() {
        while (!stop_processing_) {
            std::string message;
            if (LoggingFramework::instance().get_log_buffer().try_pop(message)) {
                LoggingFramework::instance().log(LogLevel::INFO, message); // Example log level
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    bool stop_processing_ = false;
    std::thread logging_thread_;
};

int main() {
    LogManager manager;
    manager.start_logging_thread();

    LoggingFramework& logger = LoggingFramework::instance();
    LogBuffer& log_buffer = logger.get_log_buffer();

    log_buffer.log("This is a test message.");
    logger.log(LogLevel::INFO, "Another test message.");

    std::this_thread::sleep_for(std::chrono::seconds(1));

    return 0;
}
