using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public interface IDataSourceConfiguration { /* Configuration properties */ }
public interface IDataFetcher<T> 
{
    Task<IEnumerable<T>> FetchDataAsync(int pageNumber, int pageSize);
}

public class DataProcessor<T>
{
    private readonly ILogger<DataProcessor<T>> _logger;

    public DataProcessor(ILogger<DataProcessor<T>> logger)
    {
        _logger = logger;
    }

    public async IAsyncEnumerable<IEnumerable<T>> ProcessDataAsync(
        IEnumerable<IDataFetcher<T>> dataFetchers, 
        Func<T, bool> filter,
        int pageSize, 
        int totalPagesPerSource)
    {
        var tasks = new List<Task<IEnumerable<IEnumerable<T>>>>();

        foreach (var fetcher in dataFetchers)
        {
            tasks.Add(ProcessSingleSourceAsync(fetcher, filter, pageSize, totalPagesPerSource));
        }

        await Task.WhenAll(tasks);

        foreach (var task in tasks)
        {
            var result = await task;
            foreach (var chunk in result)
            {
                yield return chunk.Where(filter);
            }
        }
    }

    private async Task<IEnumerable<IEnumerable<T>>> ProcessSingleSourceAsync(
        IDataFetcher<T> fetcher, 
        Func<T, bool> filter,
        int pageSize, 
        int totalPageCount)
    {
        var pages = new List<IEnumerable<T>>();

        for (int i = 0; i < totalPageCount; i++)
        {
            try
            {
                var pageData = await fetcher.FetchDataAsync(i, pageSize);
                _logger.LogInformation($"Fetched page {i} with {pageData.Count()} items.");

                pages.Add(pageData.Where(filter));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error fetching data for page {i}. Retrying...");
                await Task.Delay(1000); // simple retry delay
                i--; // retry the same page
            }
        }

        return pages;
    }
}
