public class ConfigurationLoader
{
    private string _configFilePath;
    private Dictionary<string, GameObject> _gameObjectsCache;

    public ConfigurationLoader(string configFilePath)
    {
        _configFilePath = configFilePath;
        _gameObjectsCache = new Dictionary<string, GameObject>();
    }

    public async Task LoadConfigurationAsync()
    {
        try
        {
            var jsonContent = await File.ReadAllTextAsync(_configFilePath);
            var gameObjects = JsonConvert.DeserializeObject<List<GameObject>>(jsonContent);

            if (gameObjects == null) throw new JsonException("Invalid configuration format.");

            foreach (var gameObject in gameObjects)
            {
                if (!gameObject.Validate()) continue;

                _gameObjectsCache[gameObject.Id] = gameObject;
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions like file not found, invalid JSON, etc.
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }
    }

    public void UpdateObjectProperty(string id, string propertyName, object value)
    {
        if (_gameObjectsCache.TryGetValue(id, out var gameObject))
        {
            gameObject.Properties[propertyName] = value;
        }
    }

    public GameObject GetGameObject(string id) => _gameObjectsCache.GetValueOrDefault(id);

    public async Task MonitorConfigurationChangesAsync()
    {
        FileSystemWatcher watcher = new FileSystemWatcher(Path.GetDirectoryName(_configFilePath), Path.GetFileName(_configFilePath));

        watcher.Changed += (sender, args) =>
        {
            Console.WriteLine("Configuration file changed. Reloading...");
            LoadConfigurationAsync().Wait();
        };

        watcher.EnableRaisingEvents = true;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        ConfigurationLoader loader = new ConfigurationLoader("path/to/config.json");

        await loader.LoadConfigurationAsync();
        var gameObject = loader.GetGameObject("someId");

        // Update properties dynamically if needed
        loader.UpdateObjectProperty("someId", "propertyKey", "newValue");

        // Start monitoring configuration changes for real-time updates
        await loader.MonitorConfigurationChangesAsync();

        Console.WriteLine("Press any key to exit...");
        Console.ReadKey();
    }
}
