using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;
using System.Threading;

class XPathElementFinder
{
    private static readonly object LockObject = new object();
    private const string EnvironmentVariableName = "MY_APP_DATA_PATH";
    private static readonly string DefaultDirectoryName = "DefaultDataDir";

    public XElement FindFirstMatchingXmlElement(string xmlFilePath, string elementName)
    {
        string directoryPath = GetOrCreateDirectory();

        // Load XML document
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(xmlFilePath);

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathExpression expression = navigator.Compile($"/*/{elementName}");

        XPathNodeIterator nodes = navigator.Select(expression);

        if (nodes.Count == 0)
            throw new ElementNotFoundException($"No element found with name: {elementName}");
        if (nodes.Count > 1)
            throw new MultipleElementsFoundException("Multiple elements found with the given name.");

        return nodes.MoveNext() ? XElement.Load(nodes.Current.OuterXml) : null;
    }

    private string GetOrCreateDirectory()
    {
        lock (LockObject)
        {
            // Retrieve or create directory path
            if (!Environment.GetEnvironmentVariable(EnvironmentVariableName).IsValidPath())
            {
                var newDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, DefaultDirectoryName);

                try
                {
                    Directory.CreateDirectory(newDir);

                    SetEnvironmentVariableSafely(EnvironmentVariableName, newDir);
                }
                catch (Exception ex)
                {
                    throw new DirectoryCreationException("Failed to create directory.", ex);
                }
            }

            return Environment.GetEnvironmentVariable(EnvironmentVariableName);
        }
    }

    private bool IsValidPath(string path)
    {
        try
        {
            Uri result = new Uri(path, UriKind.Absolute);
            return (result.Scheme == Uri.UriSchemeFile || result.Scheme == Uri.UriSchemeFtp ||
                    result.Scheme == Uri.UriSchemeGopher || result.Scheme == Uri.UriSchemeHttp ||
                    result.Scheme == Uri.UriSchemeHttps || result.Scheme == Uri.UriSchemeMailto ||
                    result.Scheme == Uri.UriSchemeNews || result.Scheme == Uri.UriSchemeNntp ||
                    result.Scheme == Uri.UriSchemeSftp || result.Scheme == Uri.UriSchemeSmb);
        }
        catch (Exception)
        {
            return false;
        }
    }

    private void SetEnvironmentVariableSafely(string variable, string value)
    {
        try
        {
            Environment.SetEnvironmentVariable(variable, value, EnvironmentVariableTarget.Machine);
        }
        catch (UnauthorizedAccessException ex)
        {
            throw new UnauthorizedAccessException("Insufficient permissions to set environment variable.", ex);
        }
    }

    // Custom exceptions for specific scenarios
    public class ElementNotFoundException : Exception
    {
        public ElementNotFoundException(string message) : base(message) { }
    }

    public class MultipleElementsFoundException : Exception
    {
        public MultipleElementsFoundException(string message) : base(message) { }
    }

    public class DirectoryCreationException : Exception
    {
        public DirectoryCreationException(string message, Exception inner) : base(message, inner) { }
    }
}
