class AccountManager {

    private $db; // Assume a database connection instance is available

    public function __construct($databaseConnection) {
        $this->db = $databaseConnection;
    }

    public function manageAccount($_REQUEST) {
        try {
            $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;
            $name = $_REQUEST['name'];
            $email = $_REQUEST['email'];
            $password = $_REQUEST['password'];
            $sub_action = $_REQUEST['sub_action'];

            if (!in_array($sub_action, ['create', 'update', 'delete', 'suspend'])) {
                return json_encode(['status' => 'error', 'message' => 'Invalid sub-action.']);
            }

            $accountData = [];
            if ($id) {
                $accountData = $this->get($id);
            }

            switch ($sub_action) {
                case 'create':
                    $errors = $this->validate(['name' => $name, 'email' => $email, 'password' => $password], false);
                    if (!empty($errors)) {
                        return json_encode(['status' => 'error', 'message' => implode(', ', $errors)]);
                    }
                    if (!$this->isEmailUnique($email)) {
                        return json_encode(['status' => 'error', 'message' => 'Email already exists.']);
                    }
                    $hashedPassword = password_hash($password, PASSWORD_BCRYPT);
                    $this->save(['name' => $name, 'email' => $email, 'password' => $hashedPassword], true);
