                        return json_encode(['status' => 'error', 'message' => 'Unauthorized update.']);
                    }
                    $errors = $this->validate(['name' => $name, 'email' => $email, 'password' => $password], true);
                    if (!empty($errors)) {
                        return json_encode(['status' => 'error', 'message' => implode(', ', $errors)]);
                    }
                    if ($accountData['email'] !== $email && !$this->isEmailUnique($email)) {
                        return json_encode(['status' => 'error', 'message' => 'Email already exists.']);
                    }
                    $hashedPassword = password_hash($password, PASSWORD_BCRYPT);
                    $this->save(['name' => $name, 'email' => $email, 'password' => $hashedPassword], false, $id);
                    break;

                case 'delete':
                    if ($accountData['balance'] !== 0 || !$this->isAccountActive($id)) {
                        return json_encode(['status' => 'error', 'message' => 'Cannot delete account.']);
                    }
                    $this->save([], false, $id, true);
                    break;

                case 'suspend':
                    if (!$this->canSuspend($accountData)) {
                        return json_encode(['status' => 'error', 'message' => 'Account cannot be suspended.']);
                    }
                    $this->updateStatus($id, 'suspended');
                    break;
            }

            // Log the operation
            $this->logOperation($_REQUEST);

            return json_encode(['status' => 'success', 'message' => 'Operation completed successfully.']);

        } catch (Exception $e) {
            return json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

