}

// Implement a simple in-memory rate limiter (for demonstration purposes)
public class RateLimiter
{
    private readonly int _maxRequests;
    private readonly TimeSpan _timeSpan;
    private readonly IMemoryCache _cache;

    public RateLimiter(int maxRequests, TimeSpan timeSpan, IMemoryCache cache)
    {
        _maxRequests = maxRequests;
        _timeSpan = timeSpan;
        _cache = cache;
    }

    public bool AllowRequest(string key)
    {
        if (!_cache.TryGetValue(key, out int requestCount))
        {
            requestCount = 0;
        }

        if (requestCount < _maxRequests)
        {
            _cache.Set(key, ++requestCount, _timeSpan);
            return true;
        }

        return false;
    }
}

// Define a controller to handle HTTP POST requests
