const EventEmitter = require('events');
const { performance } = require('perf_hooks');

class TestRunner extends EventEmitter {
  constructor() {
    super();
    this.module = null;
    this.mockingLibrary = require('blueslip'); // Assuming 'blueslip' is already installed
  }

  async loadModule(modulePath) {
    try {
      this.module = require(modulePath);
    } catch (error) {
      console.error(`Error loading module: ${modulePath}`, error.message);
      throw new Error(`Failed to load module: ${modulePath}`);
    }
  }

  async runTest(label, f, config) {
    let startTime;
    try {
      startTime = performance.now();

      // Reset the mocking library before each test
      this.mockingLibrary.reset();

      await f.call(this.module, config);

      const duration = performance.now() - startTime;
      console.log(`Module: ${this.module.name}, Test: ${label}, Duration: ${duration.toFixed(2)}ms`);
    } catch (error) {
      const duration = performance.now() - startTime;
      console.error(`Module: ${this.module.name}, Test: ${label}, Error:`, error.message);
      console.error(`Execution Time before Failure: ${duration.toFixed(2)}ms`);

      // Emitting failure event for external handlers
      this.emit('testFailure', { label, duration });
    } finally {
      // Resource cleanup and reporting metrics if needed
    }
  }

  async runSuite(tests, modulePath, config) {
    try {
      await this.loadModule(modulePath);

      const testPromises = tests.map(({ label, f }) => 
        new Promise((resolve, reject) => {
          this.runTest(label, f, config).then(() => resolve()).catch(reject);
        })
      );

      // Running tests in parallel
      await Promise.allSettled(testPromises);

      console.log('All tests completed.');
    } catch (error) {
      console.error('An error occurred during test suite execution:', error.message);
    }
  }

  async integrateWithTestRunnerService(results, serviceConfig) {
    // Placeholder for integration with an external test runner service
    // This function should be modular to allow future backend changes
    try {
      const reportData = {
        results,
        timestamp: new Date().toISOString()
        // Add other metrics as necessary
      };

      console.log('Sending results to Test Runner Service:', reportData);

      // Implement actual logic for service communication here
    } catch (error) {
      console.error('Failed to integrate with test runner service:', error.message);
    }
  }

  async execute(tests, modulePath, config, serviceConfig = {}) {
    const results = [];

    await this.runSuite(tests, modulePath, config);

    // Collect and log test results
    this.on('testFailure', (result) => results.push({ ...result, status: 'failed' }));
    this.emit('testSuccess', { label: `Test Suite`, duration: null });

    // Integrate with external test runner service
    await this.integrateWithTestRunnerService(results, serviceConfig);
  }
}

// Example usage:
const tests = [
  { label: 'Test1', f: async (config) => {/* Test logic here */} },
  { label: 'Test2', f: async (config) => {/* Test logic here */} }
];

const config = {
  timeout: 5000, // in milliseconds
  resourceLimits: /* specify limits if needed */
};

const serviceConfig = {
  endpoint: 'https://test-runner-service.example.com/report',
  apiKey: 'your-api-key'
};

(async () => {
  const runner = new TestRunner();
