const EventEmitter = require('events');
const axios = require('axios'); // To simulate network requests

class SensorService extends EventEmitter {
  constructor(instanceId, configServiceUrl) {
    super();
    this.instanceId = instanceId;
    this.configServiceUrl = configServiceUrl;
    this.buffer = [];
    this.paused = false;
    this.isRunning = true;
    this.currentConfig = {};

    // Initialize configuration
    this.fetchConfig();

    // Start listening for data
    setInterval(() => {
      if (this.isRunning && !this.paused) {
        this.collectData();
      }
    }, 1000); // Adjust frequency as needed

    // Handle graceful shutdowns
    process.on('SIGINT', () => this.stop());
  }

  async fetchConfig() {
    try {
      const response = await axios.get(this.configServiceUrl);
      this.currentConfig = response.data;
    } catch (error) {
      console.error(`Failed to fetch config for instance ${this.instanceId}:`, error);
    }
  }

  collectData() {
    // Simulate data collection
    const sensorData = this.simulateSensorData();

    if (sensorData) {
      this.handleMissingData(sensorData);
      this.buffer.push(sensorData);

      // Emit an event for collected data processing
      this.emit('dataCollected', sensorData);

      // Check buffer size and offload to persistent storage if necessary
      if (this.buffer.length >= this.currentConfig.maxBufferSize) {
        this.offloadData();
      }
    } else {
      console.warn(`No data received from instance ${this.instanceId}. Possible network issue.`);
    }
  }

  simulateSensorData() {
    // Simulate sensor data or fetch real-time data
    return { timestamp: Date.now(), value: Math.random() }; // Replace with actual sensor fetching logic
  }

  handleMissingData(data) {
    const expectedInterval = this.currentConfig.dataSamplingRate;
    if (this.buffer.length > 0 && data.timestamp - this.buffer[this.buffer.length - 1].timestamp > expectedInterval * 2) {
      console.warn(`Gap detected in instance ${this.instanceId}.`);
      // Implement logic to handle missing data, e.g., interpolation
    }
  }

  offloadData() {
    // Simulate offloading data (e.g., saving to a database)
    const dataToOffload = this.buffer.splice(0, this.currentConfig.offloadBatchSize);
    console.log(`Instance ${this.instanceId} offloaded data:`, dataToOffload);

    // Emit an event for successful offloading
    this.emit('dataOffloaded', dataToOffload);
  }

  pause() {
    this.paused = true;
    console.log(`Instance ${this.instanceId} paused.`);
  }

  resume() {
    if (this.paused) {
      this.paused = false;
      console.log(`Instance ${this.instanceId} resumed.`);
    }
  }

  stop() {
    this.isRunning = false;
    console.log(`Instance ${this.instanceId} stopped. Sending status update to the event bus.`);

    // Simulate sending a status update
    this.sendStatusUpdate();
  }

  sendStatusUpdate() {
    // Implement logic to send status updates (e.g., through an external message bus)
    console.log(`Status update for instance ${this.instanceId} sent.`);
  }
}

// Usage example:
const service1 = new SensorService('serviceInstance1', 'http://config-service/config');
const service2 = new SensorService('serviceInstance2', 'http://config-service/config');

// To pause and resume services
setTimeout(() => {
  service1.pause();
}, 5000);

setTimeout(() => {
  service1.resume();
}, 10000);

// Graceful shutdown simulation
setTimeout(() => {
  service1.stop();
}, 15000);
```

### Key Features:
- **Modular Architecture:** Each instance of `SensorService` is independent and can be started/stopped individually.
- **Dynamic Configuration Fetching:** Configurations are fetched from an external service, allowing dynamic adjustment of parameters like sampling rates and buffer sizes.
- **Pause/Resume Functionality:** Instances can be paused and resumed without losing data.
- **Missing Data Handling:** Detects gaps in data collection and logs warnings.
- **Graceful Shutdowns:** Sends status updates to a simulated message bus upon stopping, ensuring other services are informed."]

