async function traverseDOM(node, selector, cache = new Map(), result = [], positionFilter = null) {
  if (!node || !node.nodeType === Node.ELEMENT_NODE) return result;

  const elements = Array.from(node.querySelectorAll(selector));

  for (let element of elements) {
    // Apply metadata fetching with caching
    let metadata;
    if (cache.has(element.id)) {
      metadata = cache.get(element.id);
    } else {
      metadata = await fetchElementMetadata(element);
      cache.set(element.id, metadata);
    }

    // Check position filter conditions
    const parent = element.parentNode;
    const children = Array.from(parent.children);
    const index = children.indexOf(element);

    let isValidPosition = true;
    if (positionFilter) {
      switch (positionFilter.type) {
        case 'first-child':
          isValidPosition = index === 0;
          break;
        case 'last-child':
          isValidPosition = index === children.length - 1;
          break;
        case 'nth-child':
          isValidPosition = index + 1 === positionFilter.nth;
          break;
      }
    }

    if (isValidPosition && metadata) {
      // Transform element if needed via callback
      const transformedElement = transformElement(element, metadata);

      // Add valid and transformed elements to result list
      result.push(transformedElement);
    }
  }

  for (let child of node.children) {
    await traverseDOM(child, selector, cache, result, positionFilter); 
  }

  return result;
}

function transformElement(element, metadata) {
  // Example transformation based on fetched metadata
  if (metadata && metadata.transformations) {
    element.className += ` ${metadata.transformations.class}`;
  }
  return element;
}

// Usage example:
(async () => {
  const selector = '.target-class';
  const positionFilter = { type: 'nth-child', nth: 2 };

  const matchingElements = await traverseDOM(document.body, selector, new Map(), [], positionFilter);

  console.log('Matching Elements:', matchingElements);
})();
