// C Code: filename_modifier.c

#include <stdio.h>
#include <string.h>

const char* modifyExtension(const char* originalFilename) {
    // Logic to determine new file extension based on the criteria
    const char *dotPosition = strrchr(originalFilename, '.');

    if (!dotPosition || dotPosition == originalFilename) {
        return NULL;
    }

    size_t len = strlen(dotPosition);
    int digitCount = 0;

    for (size_t i = 1; i < len; ++i) {
        if (isdigit(dotPosition[i])) {
            ++digitCount;
        } else {
            break;
        }
    }

    // Example logic: append '_mod' and number of digits in extension
    size_t newLen = strlen(originalFilename) + 4 + digitCount;
    char *newFilename = malloc(newLen + 1); // +1 for null-terminator

    if (!newFilename) {
        return NULL; // Allocation failed
    }

    strcpy(newFilename, originalFilename);
    strcat(newFilename, "_mod");

    char digitsStr[digitCount + 1];
    snprintf(digitsStr, sizeof(digitsStr), "%d", digitCount);

    strcat(newFilename, digitsStr);
    strcat(newFilename, ".js"); // Assuming .js for simplicity

    return newFilename;
}

