import java.io.IOException;
import java.nio.file.*;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DirectoryProcessor {

    private static final Logger logger = LoggerFactory.getLogger(DirectoryProcessor.class);
    private static final int RATE_LIMIT = 5; // requests per second
    private static final String PATH_SEPARATOR = File.separator;

    public static int countUniqueDirectories(List<String> filePaths) throws InterruptedException, ExecutionException {
        Set<Path> uniqueDirs = ConcurrentHashMap.newKeySet();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        Semaphore rateLimiter = new Semaphore(RATE_LIMIT);

        for (String filePath : filePaths) {
            executor.submit(() -> {
                try {
                    Path resolvedPath = resolveAndNormalize(filePath);
                    if (!uniqueDirs.contains(resolvedPath.getParent())) {
                        synchronized (rateLimiter) {
                            rateLimiter.acquire();
                        }
                        fetchDirectoryMetadata(resolvedPath); // Simulate API call
                        synchronized (rateLimiter) {
                            rateLimiter.release();
                        }
                        uniqueDirs.add(resolvedPath.getParent());
                    }
                } catch (IOException | InterruptedException e) {
                    logger.error("Error processing path: " + filePath, e);
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);

        return uniqueDirs.size();
    }

    private static Path resolveAndNormalize(String filePath) throws IOException {
        long startTime = System.currentTimeMillis();
        Path path = Paths.get(filePath).toRealPath(LinkOption.NOFOLLOW_LINKS);
        long endTime = System.currentTimeMillis();
        logger.info("Resolved and normalized path: {} in {} ms", path, (endTime - startTime));
        return path;
    }

    private static void fetchDirectoryMetadata(Path directory) {
        // Simulate fetching metadata with rate limiting
        long startTime = System.currentTimeMillis();
        try {
            Thread.sleep(200); // simulate network delay
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        logger.info("Fetched metadata for: {} in {} ms", directory, (System.currentTimeMillis() - startTime));
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<String> filePaths = List.of(
                "/path/to/file1.txt",
                "/path/to/anotherfile.txt",
                "C:\\path\\to\\file3.txt"
        );
        int uniqueDirsCount = countUniqueDirectories(filePaths);
        logger.info("Number of unique directories: {}", uniqueDirsCount);
    }
}
