```python
import os
import threading
from PIL import Image
from queue import Queue
import requests
import logging

# Setup centralized logging system
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ThemeCacheManager:
    def __init__(self, cache_root_dir, default_theme_url):
        self.cache_root_dir = cache_root_dir
        self.default_theme_url = default_theme_url
        self.theme_lock = threading.Lock()
        self.current_theme = None
        self.theme_queue = Queue()

    def get_cached_themes(self):
        with self.theme_lock:
            try:
                theme_files = sorted(
                    [f for f in os.listdir(self.cache_root_dir) if f.endswith('.png')],
                    key=lambda x: os.path.getmtime(os.path.join(self.cache_root_dir, x)),
                    reverse=True
                )
                return theme_files
            except Exception as e:
                logger.error(f"Error accessing directory {self.cache_root_dir}: {e}")
                return []

    def set_theme(self):
        with self.theme_lock:
            try:
                themes = self.get_cached_themes()
                if not themes and self.is_network_available():
                    self.download_default_theme()
                    themes = self.get_cached_themes()

                if themes:
                    theme_path = os.path.join(self.cache_root_dir, themes[0])
                    self.current_theme = Image.open(theme_path)
            except Exception as e:
                logger.error(f"Error setting theme: {e}")

    def download_default_theme(self):
        try:
            response = requests.get(self.default_theme_url)
            if response.status_code == 200:
                with open(os.path.join(self.cache_root_dir, 'default.png'), 'wb') as f:
                    f.write(response.content)
                logger.info("Default theme downloaded and saved.")
            else:
                logger.error(f"Failed to download default theme. Status code: {response.status_code}")
        except Exception as e:
            logger.error(f"Error downloading default theme: {e}")

    def is_network_available(self):
        try:
            requests.get('https://www.google.com', timeout=5)
            return True
        except requests.ConnectionError:
            return False

    def validate_theme_files(self):
        with self.theme_lock:
            for theme_file in os.listdir(self.cache_root_dir):
                file_path = os.path.join(self.cache_root_dir, theme_file)
                try:
                    if not Image.open(file_path).verify():
                        logger.warning(f"Theme file {file_path} is corrupted. Re-downloading default theme.")
                        self.download_default_theme()
                except Exception as e:
                    logger.error(f"Error validating theme file {file_path}: {e}")

    def parse_and_update_themes(self):
        with self.theme_lock:
            themes = self.get_cached_themes()
            if not themes:
                return
            latest_theme_file = os.path.join(self.cache_root_dir, themes[0])
            self.current_theme = Image.open(latest_theme_file)
            # Process theme file as necessary

    def start_periodic_update(self):
        threading.Thread(target=self.periodic_task).start()

    def periodic_task(self):
        while True:
            try:
                self.validate_theme_files()
                if self.is_network_available():
                    self.download_default_theme()
                self.set_theme()
            except Exception as e:
                logger.error(f"Error in periodic task: {e}")
            finally:
                # Sleep or wait for a certain interval before next execution
                threading.Event().wait(3600)  # Example: check every hour

# Unit tests (using unittest framework)
import unittest
from unittest.mock import patch, mock_open, MagicMock

class TestThemeCacheManager(unittest.TestCase):
    @patch('os.listdir')
    @patch('requests.get')
    def test_get_cached_themes(self, mock_requests_get, mock_listdir):
        # Mock directory listing and network request for tests
        mock_listdir.return_value = ['theme2.png', 'theme1.png']
        manager = ThemeCacheManager('/cache/dir', 'http://example.com/default_theme.png')
        themes = manager.get_cached_themes()
        self.assertEqual(themes, ['theme2.png', 'theme1.png'])

    @patch('requests.get')
    def test_download_default_theme_success(self, mock_requests_get):
        # Simulate successful network request
        mock_response = MagicMock()
        mock_response.status_code = 200
        mock_response.content = b'\x89PNG\r\n\x1a\n...'
        mock_requests_get.return_value = mock_response

        manager = ThemeCacheManager('/cache/dir', 'http://example.com/default_theme.png')
        with patch('builtins.open', mock_open()):
            manager.download_default_theme()
            # Assert file was created (using mock_open instance's write method)
            mock_open().return_value.write.assert_called_once_with(mock_response.content)

    @patch('requests.get')
    def test_download_default_theme_failure(self, mock_requests_get):
        # Simulate failed network request
