import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private volatile boolean running = true;
    private static final int CPU_LIMIT = 80; // Example CPU limit in percentage
    private static final long MEMORY_LIMIT_MB = 512L; // Example memory limit in MB

    public void start() {
        try {
            sendStatusUpdate("Starting service...");
            if (!initializeResources()) {
                throw new RuntimeException("Failed to initialize resources");
            }
            scheduler.scheduleAtFixedRate(this::monitorRuntime, 0, 5, TimeUnit.SECONDS);
            System.out.println("Service started successfully.");
        } catch (Exception e) {
            handleError(e);
        }
    }

    private boolean initializeResources() {
        // Initialize resources and check for errors
        return true; // Return false if initialization fails
    }

    private void monitorRuntime() {
        double cpuUsage = getCPUUsage();
        long memoryUsageMb = getMemoryUsageMb();

        if (cpuUsage > CPU_LIMIT || memoryUsageMb > MEMORY_LIMIT_MB) {
            sendStatusUpdate("Resource limits exceeded: CPU " + cpuUsage + "%, Memory " + memoryUsageMb + "MB");
        }

        // Additional runtime monitoring logic
    }

    private double getCPUUsage() {
        // Implement logic to calculate current CPU usage
        return 50.0; // Placeholder value
    }

    private long getMemoryUsageMb() {
        // Implement logic to calculate current memory usage in MB
        return 256L; // Placeholder value
    }

    public void shutdown() {
        running = false;
        sendStatusUpdate("Shutting down service...");
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(5, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
        System.out.println("Service shut down gracefully.");
    }

    private void sendStatusUpdate(String message) {
        // Integrate with a messaging system to send status updates
        System.out.println("Status: " + message);
    }

    private void handleError(Exception e) {
        sendErrorReport(e.getMessage());
        shutdown();
    }

    private void sendErrorReport(String errorMessage) {
        // Integrate with a messaging system to report errors
        System.err.println("Error: " + errorMessage);
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        Runtime.getRuntime().addShutdownHook(new Thread(manager::shutdown));
        manager.start();

        // Simulate service running indefinitely
        while (manager.running) {
            try {
                TimeUnit.SECONDS.sleep(1);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
```

