            $this->triggerAlert("CPU usage exceeded: {$cpuUsage}%");
        }

        if ($memoryUsage > self::THRESHOLDS['memory']) {
            $this->triggerAlert("Memory usage exceeded: {$memoryUsage}MB");
        }
    }

    private function triggerAlert($message) {
        // Placeholder for alerting logic, e.g., sending email or using an API
        error_log("ALERT: {$message}");
    }

    public function getConfig() {
        return $this->config;
    }
}

interface CacheInterface {
    public function set($key, $value);
    public function get($key);
    public function has($key);
}

class APCUCache implements CacheInterface {
    public function set($key, $value) {
        apcu_store($key, $value);
    }

    public function get($key) {
        return apcu_fetch($key);
    }

    public function has($key) {
        return apcu_exists($key);
    }
}

class FileCache implements CacheInterface {
    private $cacheDir = '/path/to/cache/';

    public function __construct() {
        if (!file_exists($this->cacheDir)) {
            mkdir($this->cacheDir, 0777, true);
        }
    }

    public function set($key, $value) {
        file_put_contents($this->cacheDir . md5($key), serialize($value));
    }

    public function get($key) {
        if ($this->has($key)) {
            return unserialize(file_get_contents($this->cacheDir . md5($key)));
        }
        return null;
    }

    public function has($key) {
        return file_exists($this->cacheDir . md5($key));
    }
}

// Usage
try {
    $configManager = new ConfigurationManager();
    $appConfig = $configManager->getConfig();

    // Use $appConfig for application logic
} catch (Exception $e) {
    error_log("Error: " . $e->getMessage());
}
