<?php

class TokenGenerator {
    private $charset;

    public function __construct($charset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
        if (!$this->isValidCharset($charset)) {
            throw new InvalidArgumentException('Invalid character set');
        }
        $this->charset = $charset;
    }

    private function isValidCharset($charset) {
        return preg_match('/^[a-zA-Z0-9]+$/', $charset);
    }

    public function generateToken($length = 32) {
        $token = '';
        for ($i = 0; $i < $length; $i++) {
            $index = random_int(0, strlen($this->charset) - 1);
            $token .= $this->charset[$index];
        }
        return $token;
    }

    public function hashPassword($password, $algorithm = PASSWORD_DEFAULT) {
        if (!in_array($algorithm, ['PASSWORD_BCRYPT', 'PASSWORD_ARGON2I'])) {
            throw new InvalidArgumentException('Unsupported hashing algorithm');
        }
        return password_hash($password, $algorithm);
    }
}

// Unit Tests (using PHPUnit)
class TokenGeneratorTest extends \PHPUnit\Framework\TestCase {
    public function testTokenGeneration() {
        $generator = new TokenGenerator();
        $token = $generator->generateToken(16);
        $this->assertEquals(16, strlen($token));
    }

    public function testInvalidCharset() {
        $this->expectException(InvalidArgumentException::class);
        new TokenGenerator('@#%');
    }

    public function testPasswordHashing() {
        $password = 'securePassword123';
        $generator = new TokenGenerator();
        $hash = $generator->hashPassword($password, PASSWORD_BCRYPT);
        $this->assertNotEmpty($hash);
    }

    public function testUnsupportedAlgorithm() {
        $this->expectException(InvalidArgumentException::class);
        (new TokenGenerator())->hashPassword('test', 'INVALID_ALGO');
    }
}

