const fs = require('fs').promises;
const path = require('path');

async function readImageFiles(directory) {
    try {
        const files = await fs.readdir(directory);
        const imageFiles = [];

        for (let file of files) {
            const filePath = path.join(directory, file);
            const stats = await fs.stat(filePath);

            if (stats.isFile() && /\.(jpg|jpeg|png|gif)$/i.test(file)) {
                imageFiles.push(filePath);
            }
        }

        return imageFiles;
    } catch (error) {
        console.error('Error reading directory:', error.message);
        throw error; // Re-throw after logging
    }
}

async function generateToken(length = 32, charset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    if (!/^[a-zA-Z0-9]+$/.test(charset)) {
        throw new Error('Invalid character set');
    }

    let token = '';
    for (let i = 0; i < length; i++) {
        const randomIndex = Math.floor(Math.random() * charset.length);
        token += charset[randomIndex];
    }

    return token;
}

// Unit Tests (using Jest)
test('should read valid image files', async () => {
    const images = await readImageFiles('./images');
    expect(images).toEqual(expect.arrayContaining(['./images/sample.jpg']));
});

test('generateToken should produce a token of specified length with valid charset', async () => {
    const token = await generateToken(16);
    expect(token.length).toBe(16);
});

test('should throw error for invalid directory path', async () => {
    await expect(readImageFiles('./nonexistent')).rejects.toThrow();
});

test('generateToken should throw error for invalid charset', async () => {
    await expect(generateToken(16, '@#%')).rejects.toThrow();
});
```

