async function fetchAndSaveCertificate(oAuthRequest) {
    const sources = determineSourcesBasedOnScope(oAuthRequest.scope);
    let currentSourceIndex = 0;

    async function fetchDataFromSource(source) {
        try {
            return await new Promise((resolve, reject) => {
                source.fetchStream()
                    .on('data', chunk => buffer.push(chunk))
                    .on('end', () => resolve(Buffer.concat(buffer)))
                    .on('error', err => reject(err));
            });
        } catch (error) {
            console.error(`Error fetching from source ${source.url}:`, error);
            throw new Error(`Failed to fetch data from source: ${source.url}`);
        }
    }

    async function attemptFetch() {
        while (currentSourceIndex < sources.length) {
            const currentSource = sources[currentSourceIndex];
            try {
                buffer = [];
                return await fetchDataFromSource(currentSource);
            } catch (error) {
                console.warn(`Switching to next source due to error: ${error.message}`);
                currentSourceIndex++;
            }
        }
        throw new Error('All data sources failed.');
    }

    function determineSourcesBasedOnScope(scope) {
        // Logic to dynamically choose sources based on the OAuth request's scope
        return [
            { url: 'https://api1.example.com/certificate', fetchStream: () => /* stream for source 1 */ },
            { url: 'https://api2.example.com/certificate', fetchStream: () => /* stream for source 2 */ }
        ];
    }

    const buffer = [];

    try {
        const certificateData = await attemptFetch();
        return certificateData.toString('utf8');
    } catch (error) {
        console.error('Failed to retrieve and save certificate:', error);
        throw new Error('Certificate retrieval failed.');
    }
}
