#include <iostream>
#include <vector>
#include <mutex>
#include <cstddef>

class OctreeNode {
public:
    int featureSize;
    bool isLeaf;
    std::unique_ptr<OctreeNode> children[8];

    OctreeNode(int size) : featureSize(size), isLeaf(false) {}
};

class MemoryLogger {
public:
    static void logFailure(size_t attemptedSize) {
        std::cerr << "Memory allocation failed for size: " << attemptedSize << std::endl;
    }
};

class OctreeAllocator {
private:
    static constexpr size_t initialAlignment = 64;

public:
    template<typename T>
    static T* alignedAlloc(size_t size, size_t alignment = initialAlignment) {
        void* ptr = nullptr;
#ifdef _WIN32
        if (posix_memalign(&ptr, alignment, size)) {
            return nullptr; // Allocation failed
        }
#else
        if ((ptr = std::aligned_alloc(alignment, size)) == nullptr) {
            return nullptr; // Allocation failed
        }
#endif
        return new(ptr) T;
    }

    template<typename T>
    static void alignedDealloc(T* ptr) {
#ifdef _WIN32
        ptr->~T();
#else
        if (ptr != nullptr) {
            ptr->~T(); // Call the destructor explicitly
            std::free(static_cast<void*>(static_cast<std::uintptr_t>(ptr)));
        }
#endif
