};

class Octree {
public:
    OctreeNode* root = nullptr;
    size_t totalMemoryUsage = 0;
    std::mutex mtx;

    ~Octree() {
        deleteTree(root);
    }

private:
    void deleteTree(OctreeNode* node) {
        if (node == nullptr) return;

        for (int i = 0; i < 8; ++i) {
            deleteTree(node->children[i].get());
        }
        OctreeAllocator::alignedDealloc<OctreeNode>(node);
    }

public:
    bool initialize(int featureSize, size_t numLeafNodes, size_t dataCapacity) {
        if (numLeafNodes == 0 || dataCapacity <= 0) return false;

        std::lock_guard<std::mutex> lock(mtx);

        try {
            root = allocateOctreeRoot(featureSize);
            totalMemoryUsage += sizeof(OctreeNode); // Initial node

            auto leaves = reserveLeaves(numLeafNodes, featureSize);
            if (!leaves) return false; // Allocation failed

            totalMemoryUsage += numLeafNodes * sizeof(OctreeNode);
        } catch (...) {
            cleanup();
            return false;
        }

        return true;
    }

private:
    OctreeNode* allocateOctreeRoot(int featureSize) {
        size_t alignment = 64;
        while (true) {
            OctreeNode* root = OctreeAllocator::alignedAlloc<OctreeNode>(sizeof(OctreeNode), alignment);
            if (root != nullptr) {
                return root;
            }
            MemoryLogger::logFailure(sizeof(OctreeNode));
            alignment /= 2; // Reduce alignment on failure
        }
    }

    bool reserveLeaves(size_t numLeafNodes, int featureSize) {
        size_t alignment = 64;
        while (true) {
            std::vector<std::unique_ptr<OctreeNode>> leaves;
            for (size_t i = 0; i < numLeafNodes; ++i) {
                OctreeNode* leaf = OctreeAllocator::alignedAlloc<OctreeNode>(sizeof(OctreeNode), alignment);
                if (!leaf) {
                    MemoryLogger::logFailure(sizeof(OctreeNode));
                    cleanupLeaves(leaves);
                    alignment /= 2; // Reduce alignment on failure
                    break;
                }
                leaves.push_back(std::unique_ptr<OctreeNode>(leaf));
            }

            if (leaves.size() == numLeafNodes) {
                return true; // All leaves allocated successfully
            }
        }
    }

    void cleanupLeaves(std::vector<std::unique_ptr<OctreeNode>>& leaves) {
        for (auto& leaf : leaves) {
            OctreeAllocator::alignedDealloc(leaf.release());
        }
    }

    void cleanup() {
        deleteTree(root);
        root = nullptr;
    }
};

std::pair<size_t, bool> initializeOctree(int featureSize, size_t numLeafNodes, size_t dataCapacity) {
    Octree octree;
    bool success = octree.initialize(featureSize, numLeafNodes, dataCapacity);
    return {octree.totalMemoryUsage, success};
}
