#include <stdio.h>
#include <stdlib.h>
import math

#define MAX_DEVICES 100
#define WINDOW_SIZE 10

typedef struct {
    double values[WINDOW_SIZE];
    int index;
    double sum;
} DeviceWindow;

typedef struct {
    double average;
    double stddev;
    int anomaly_count;
} Metrics;

typedef struct {
    DeviceWindow windows[MAX_DEVICES];
    Metrics metrics[MAX_DEVICES];
    int data_rate[MAX_DEVICES];
    int connection_status[MAX_DEVICES]; // 1 for connected, 0 for disconnected
    int threshold[MAX_DEVICES];
} SensorDataProcessor;

void update_window(DeviceWindow *window, double new_value) {
    window->sum -= window->values[window->index];
    window->values[window->index] = new_value;
    window->sum += new_value;
    window->index = (window->index + 1) % WINDOW_SIZE;
}

double calculate_average(DeviceWindow *window, int count) {
    return window->sum / count;
}

double calculate_stddev(DeviceWindow *window, double average, int count) {
    double variance = 0.0;
    for (int i = 0; i < count; ++i) {
        variance += pow(window->values[i] - average, 2);
    }
    return sqrt(variance / count);
}

void process_sensor_data(SensorDataProcessor *processor, int device_id, double value) {
    if (device_id < 0 || device_id >= MAX_DEVICES || processor->connection_status[device_id] == 0) {
        return; // Handle lost connection or invalid device ID
    }

    DeviceWindow *window = &processor->windows[device_id];
    update_window(window, value);

    int count = (window->index < WINDOW_SIZE) ? window->index : WINDOW_SIZE;
    double average = calculate_average(window, count);
    double stddev = calculate_stddev(window, average, count);

    processor->metrics[device_id].average = average;
    processor->metrics[device_id].stddev = stddev;

    if (fabs(value - average) > processor->threshold[device_id]) {
        processor->metrics[device_id].anomaly_count++;
    }
}

int find_highest_stddev(SensorDataProcessor *processor, int *highest_device_id) {
    double max_stddev = 0.0;
    for (int i = 0; i < MAX_DEVICES; ++i) {
        if (processor->connection_status[i] && processor->metrics[i].stddev > max_stddev) {
            max_stddev = processor->metrics[i].stddev;
            *highest_device_id = i;
        }
    }
    return (*highest_device_id != -1);
}

int main() {
    SensorDataProcessor processor = {0};

    // Example initialization
    for (int i = 0; i < MAX_DEVICES; ++i) {
        processor.connection_status[i] = 1; // Assume all devices are initially connected
        processor.threshold[i] = 5.0; // Example threshold
    }

    int highest_device_id = -1;
    if (find_highest_stddev(&processor, &highest_device_id)) {
        printf("Device ID with highest stddev: %d\n", highest_device_id);
        printf("Average: %.2f, Stddev: %.2f, Anomalies: %d\n",
               processor.metrics[highest_device_id].average,
               processor.metrics[highest_device_id].stddev,
               processor.metrics[highest_device_id].anomaly_count);
    } else {
        printf("No connected devices with data.\n");
    }

    return 0;
}
```

This code provides a basic framework for processing real-time sensor data, handling intermittent network connections, and computing moving averages and standard deviations. It includes error handling for lost connections and updates metrics structures accordingly.']

['```cpp
#include <iostream>
#include <mutex>
#include <unordered_map>
#include <thread>
#include <chrono>
#include <condition_variable>

class AttackManager {
public:
    struct CooldownData {
        int lastUsed;
        int cooldownPeriod;
    };

private:
    std::unordered_map<int, CooldownData> characterCooldowns;
    std::mutex mtx;

public:
    // Initialize the attack manager with default cooldown periods
    AttackManager() : attacks({{1, 9}, {2, 7}, {3, 10}}) {}

    // Function to select and execute an attack for a given character
    int selectAttack(int characterId) {
        std::unique_lock<std::mutex> lock(mtx);

        auto currentTime = std::chrono::steady_clock::now().time_since_epoch().count();

        CooldownData cooldowns[3];
        for (int i = 1; i <= 3; ++i) {
            if (characterCooldowns.count(characterId * 10 + i)) {
                cooldowns[i - 1] = characterCooldowns[characterId * 10 + i];
            } else {
                cooldowns[i - 1] = {currentTime, attacks[i]};
            }
        }

        int selectedAttack = -1;
        int minTimeLeft = std::numeric_limits<int>::max();

        for (int i = 0; i < 3; ++i) {
            auto timeLeft = cooldowns[i].cooldownPeriod + cooldowns[i].lastUsed - currentTime;
            if (timeLeft <= 0 && timeLeft < minTimeLeft) { // Ensure no consecutive use
                selectedAttack = i + 1;
                minTimeLeft = timeLeft;
            }
        }

        if (selectedAttack != -1) {
            characterCooldowns[characterId * 10 + selectedAttack] = {currentTime, attacks[selectedAttack]};
        }

        return selectedAttack; // Return the attack ID or -1 if none available
    }

private:
    std::unordered_map<int, int> attacks;
};

int main() {
    AttackManager manager;

    auto characterTask = [&](int characterId) {
        while (true) {
            int attack = manager.selectAttack(characterId);
            if (attack != -1) {
                std::cout << "Character " << characterId << " used Attack " << attack << "\n";
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    };

    std::vector<std::thread> characters;
    for (int i = 0; i < 5; ++i) {
        characters.emplace_back(characterTask, i);
    }

    for (auto& t : characters) {
        t.join();
    }

    return 0;
}
```

### Key Features
- The `AttackManager` class handles cooldown management in a thread-safe manner using mutexes.
- Each character's attacks are tracked separately with a unique key combining the character ID and attack number.
- Attack selection ensures no consecutive use by checking the time left before an attack can be used again.
- The solution scales well as more characters are added, thanks to efficient lock management.']

['```csharp
using System;
using System.Threading;

public sealed class DynamicValueGenerator
{
    private readonly float _minValue;
    private readonly float _maxValue;
    private static readonly Random _globalRandom = new Random();
    private static readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public DynamicValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    private Random GetThreadRandom()
    {
        return new Random(_globalRandom.Next());
    }

    public float GetRandomFloat()
    {
        float result;
        using (var threadRandom = GetThreadRandom())
        {
            _lock.EnterReadLock();
            try
            {
                result = (float)threadRandom.NextDouble() * (_maxValue - _minValue + 1.0f) + _minValue;
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }

        return result;
    }

    public int GetRandomInt()
    {
        int result;
        using (var threadRandom = GetThreadRandom())
        {
            _lock.EnterReadLock();
            try
            {
                result = threadRandom.Next((int)_minValue, (int)_maxValue + 1);
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }

        return result;
    }

    public void AdjustRange(float newMin, float newMax)
    {
        if (newMin > newMax || newMin < _minValue || newMax < _maxValue) throw new ArgumentException("Invalid range values.");

        _lock.EnterWriteLock();
        try
        {
            _minValue = newMin;
            _maxValue = newMax;
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public float GetRandomFloatExclusive(float exclusiveMin, float exclusiveMax)
    {
        if (exclusiveMin >= exclusiveMax) throw new ArgumentException("Exclusive min must be less than exclusive max.");

        float result;
        using (var threadRandom = GetThreadRandom())
        {
            _lock.EnterReadLock();
            try
            {
                result = (float)threadRandom.NextDouble() * (exclusiveMax - exclusiveMin) + exclusiveMin;
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }

        return result;
    }

    public override string ToString()
    {
        return $"[{_minValue}, {_maxValue}]";
    }
}
