class AsyncAggregator {
  constructor(config) {
    this.config = config;
    this.operations = {
      sum: async (arr) => arr.reduce((acc, val) => acc + Number(val), 0),
      product: async (arr) => arr.reduce((acc, val) => acc * Number(val), 1),
      average: async (arr) => arr.length ? (await this.operations.sum(arr)) / arr.length : 0,
      max: async (arr) => Math.max(...arr.map(Number))
    };
  }

  isValidOperation(operation) {
    return Object.keys(this.operations).includes(operation);
  }

  async execute() {
    const { array, operations } = this.config;

    if (!Array.isArray(array)) throw new Error("Input must be an array.");

    const results = {};
    const tasks = [];

    for (const operation of operations) {
      if (!this.isValidOperation(operation)) {
        return Promise.reject(new Error(`Unsupported operation: ${operation}`));
      }

      tasks.push(
        this.operations[operation](array)
          .then(result => {
            results[operation] = result;
          })
          .catch(error => {
            console.error(`Error processing operation '${operation}':`, error);
            results[operation] = null; // Set to null or appropriate default on failure
          })
      );
    }

    await Promise.all(tasks);

    return results;
  }
}

// Usage Example
(async () => {
  const aggregator = new AsyncAggregator({
    array: [1, 2, 3, 4, 5],
    operations: ['sum', 'product', 'average', 'max']
  });

  try {
    const result = await aggregator.execute();
    console.log(result);
  } catch (error) {
    console.error(error.message);
  }
})();
