#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    TYPE_INT,
    TYPE_FLOAT,
    TYPE_STRING,
    TYPE_ARRAY
} ParamType;

typedef struct {
    char *name;
    union {
        int iVal;
        float fVal;
        char *sVal;
        char **aVal;  // Array of strings
    } value;
    ParamType type;
} Parameter;

typedef struct {
    Parameter *params;
    size_t count;
} ParametersList;

// Forward declarations for helper functions
static char* trimWhitespace(char* str);
static int parseValue(const char* valueStr, void** value, ParamType* type);

ParametersList loadConfigFile(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (!file) return (ParametersList){NULL, 0};

    ParametersList paramsList = {NULL, 0};
    char lineBuffer[1024];

    size_t capacity = 10;
    paramsList.params = malloc(capacity * sizeof(Parameter));
    if (!paramsList.params) {
        fclose(file);
        return (ParametersList){NULL, 0}; // Memory allocation failed
    }

    while (fgets(lineBuffer, sizeof(lineBuffer), file)) {
        if (strlen(paramsList.params) >= capacity) {
            capacity *= 2;
            paramsList.params = realloc(paramsList.params, capacity * sizeof(Parameter));
            if (!paramsList.params) break; // Handle reallocation failure
        }

        char* name = strtok(lineBuffer, "=");
        if (!name) continue; // Malformed line

        name = trimWhitespace(name);

        char* valueStr = strtok(NULL, "\n");
        if (!valueStr) continue;

        valueStr = trimWhitespace(valueStr);

        void* parsedValue;
        ParamType type;
        int parseSuccess = parseValue(valueStr, &parsedValue, &type);
        if (!parseSuccess) {
            // Handle parsing error gracefully (e.g., log it or skip this parameter)
            continue;
        }

        paramsList.params[paramsList.count].name = strdup(name);
        switch (type) {
            case TYPE_INT:
                paramsList.params[paramsList.count].value.iVal = *(int*)parsedValue;
                break;
            case TYPE_FLOAT:
                paramsList.params[paramsList.count].value.fVal = *(float*)parsedValue;
                break;
            case TYPE_STRING:
                paramsList.params[paramsList.count].value.sVal = strdup((char*)parsedValue);
                break;
            case TYPE_ARRAY: {
                char** arrayValues = (char**)parsedValue;
                size_t arraySize = 0, index = 0;
                while(arrayValues[index]) {
                    ++arraySize;
                    ++index;
                }
                paramsList.params[paramsList.count].value.aVal =
                    malloc((arraySize + 1) * sizeof(char*)); // +1 for NULL terminator
                if (!paramsList.params[paramsList.count].value.aVal) break; // Memory allocation failed

                memcpy(paramsList.params[paramsList.count].value.aVal, arrayValues, arraySize * sizeof(char*));
                paramsList.params[paramsList.count].value.aVal[arraySize] = NULL;
            }
                break;
        }

        paramsList.params[paramsList.count].type = type;
        ++paramsList.count;

        free(parsedValue);
    }

    if (ferror(file)) {
        // Handle I/O error, e.g., log it
    }

    fclose(file);

    return paramsList;
}

static char* trimWhitespace(char* str) {
    char *end;

    while (*str == ' ') str++;
    if (*str == 0) return str;

    end = str + strlen(str) - 1;
    while (end > str && *end == ' ') end--;

    *(end+1) = '\0';
    return str;
}

static int parseValue(const char* valueStr, void** value, ParamType* type) {
    // Example parsing logic; you may expand to handle more complex data types
    if (strstr(valueStr, ",")) {
        size_t arraySize = 0;
        char *token = strtok((char*)valueStr, ",");
        while(token != NULL) {
            ++arraySize;
            token = strtok(NULL, ",");
        }

        char** arrayValues = malloc(arraySize * sizeof(char*));
        if (!arrayValues) return 0;

        size_t index = 0;
        token = strtok((char*)valueStr, ",");
        while (token != NULL) {
            arrayValues[index++] = strdup(token);
            token = strtok(NULL, ",");
        }

        arrayValues[arraySize] = NULL; // Null-terminate the array
        *type = TYPE_ARRAY;
        *value = arrayValues;
    } else if (strchr(valueStr, '.')) {
        float fVal;
        sscanf(valueStr, "%f", &fVal);
        *type = TYPE_FLOAT;
        float* floatPtr = malloc(sizeof(float));
        if (!floatPtr) return 0;
        *floatPtr = fVal;
        *value = floatPtr;
    } else {
        int iVal;
        if (sscanf(valueStr, "%d", &iVal) == 1) {
            *type = TYPE_INT;
            int* intPtr = malloc(sizeof(int));
            if (!intPtr) return 0;
            *intPtr = iVal;
            *value = intPtr;
        } else {
            *type = TYPE_STRING;
            char* strPtr = strdup(valueStr);
            if (!strPtr) return 0;
            *value = strPtr;
        }
    }

    return 1; // Success
}

void freeParametersList(ParametersList paramsList) {
    for (size_t i = 0; i < paramsList.count; ++i) {
        switch (paramsList.params[i].type) {
            case TYPE_STRING:
                free(paramsList.params[i].value.sVal);
                break;
            case TYPE_ARRAY:
                for (char** p = paramsList.params[i].value.aVal; *p != NULL; ++p)
                    free(*p);
                free(paramsList.params[i].value.aVal);
                break;
        }
        free(paramsList.params[i].name);
    }
    free(paramsList.params);
}
