Setting* loadConfiguration(const char *filename, int *settingCount) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    Setting *settings = NULL;
    *settingCount = 0;
    char line[256];

    while (fgets(line, sizeof(line), file)) {
        settings = realloc(settings, ++(*settingCount) * sizeof(Setting));
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        settings[*settingCount - 1].key = strdup(key ? key : "default_key");
        settings[*settingCount - 1].value = value ? strdup(value) : strdup("default_value");
    }

    fclose(file);
