#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>

// Custom data structure to hold metadata and hash
typedef struct {
    int extraSamples;
    char* sampleInfo;
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    char errorMessage[256];
} ProcessResult;

ProcessResult processImageAndString(const char* tiffFilePath, const char* inputString) {
    ProcessResult result = {0};
    TIFF* tif = TIFFOpen(tiffFilePath, "r");

    if (!tif) {
        snprintf(result.errorMessage, sizeof(result.errorMessage), "Error opening file: %s", tiffFilePath);
        return result;
    }

    uint32 w, h, sampcount;
    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &w) &&
        TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &h) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &sampcount)) {

        uint32 bitspersample;
        TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, &bitspersample);

        if (bitspersample != 1 && bitspersample != 2 && bitspersample != 4 &&
            bitspersample != 8 && bitspersample != 16) {

            snprintf(result.errorMessage, sizeof(result.errorMessage), "Unsupported bit depth: %u", bitspersample);
            TIFFClose(tif);
            return result;
        }

        if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &result.extraSamples)) {
            char* info = malloc(TIFFNumberOfExtraSamples(tif) * sizeof(char));
            if (info) {
                TIFFGetFieldAsString(tif, TIFFTAG_EXTRASAMPLES, info);
                result.sampleInfo = strdup(info);
                free(info);
            } else {
                snprintf(result.errorMessage, sizeof(result.errorMessage), "Memory allocation error");
                TIFFClose(tif);
                return result;
            }
        } else {
            result.extraSamples = 0;
            result.sampleInfo = NULL;
        }
    } else {
        snprintf(result.errorMessage, sizeof(result.errorMessage), "Error reading image metadata");
        TIFFClose(tif);
        return result;
    }

    // MD5 hash computation
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), hash);
    memcpy(result.md5Hash, hash, MD5_DIGEST_LENGTH);

    TIFFClose(tif);
    return result;
}

int main() {
    const char* tiffFilePath = "example.tiff";
    const char* inputString = "Sample string for hashing";

    ProcessResult result = processImageAndString(tiffFilePath, inputString);

    if (result.sampleInfo) {
        printf("Extra Samples: %d\n", result.extraSamples);
        printf("Sample Info: %s\n", result.sampleInfo);
        free(result.sampleInfo);
    }

    if (!*result.errorMessage) {
        printf("MD5 Hash: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            printf("%02x", result.md5Hash[i]);
        }
        printf("\n");
    } else {
        fprintf(stderr, "Error: %s\n", result.errorMessage);
    }

    return 0;
}
```

