    int processed_count = 0;

    while (scanf("%255s", filename) != EOF) {
        if (!check_system_dependencies()) {
            fprintf(stderr, "Error: Missing system dependencies.\n");
            continue;
        }

        size_t len = strlen(filename);
        char new_filename[MAX_FILENAME_LENGTH] = {0};

        // Handle filenames shorter than three characters
        if (len < 3) {
            snprintf(new_filename, sizeof(new_filename), "%s", filename);
            printf("Processed: %s\n", new_filename);
            continue;
        }

        // Truncate to last three characters for type derivation
        char potential_type[4] = {0};
        strncpy(potential_type, filename + len - 3, 3);

        // Check if the file has a valid extension and preserve it
        int has_valid_extension = (strncmp(filename + len - 4, ".txt", 4) == 0 ||
                                   strncmp(filename + len - 4, ".jpg", 4) == 0);

        char new_type[4] = {0};
        if (!has_valid_extension) {
            // Append "_new" to the type
            snprintf(new_type, sizeof(new_type), "%s_new", potential_type);
        } else {
            strncpy(new_type, potential_type, 3);
        }

        // Check for numeric characters in the filename
        int has_numeric = 0;
        for (size_t i = 0; i < len; ++i) {
            if (isdigit((unsigned char)filename[i])) {
                has_numeric = 1;
                break;
            }
        }

        if (!has_numeric) {
            snprintf(new_filename, sizeof(new_filename), "%s_123", filename);
        } else {
            snprintf(new_filename, sizeof(new_filename), "%s", filename);
        }

        // Append new type information
        strncat(new_filename, new_type, 3);

        // Ensure the new filename does not exceed MAX_FILENAME_LENGTH
        if (strlen(new_filename) > MAX_FILENAME_LENGTH - 1) {
            fprintf(stderr, "Error: New filename exceeds maximum length.\n");
            continue;
        }

        printf("Processed: %s\n", new_filename);
        processed_count++;
    }

    printf("Total filenames processed: %d\n", processed_count);
}

int main() {
    process_filenames();
    return 0;
}
