#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define AES_BLOCK_SIZE 16
#define SHA1_DIGEST_LENGTH 20

typedef struct {
    unsigned char *iv;
    EVP_CIPHER_CTX *ctx;
} CipherContext;

typedef struct ThemeCacheNode {
    void *bitmap; // Bitmap data
    size_t size;
    struct ThemeCacheNode *next;
} ThemeCacheNode;

typedef struct {
    pthread_mutex_t lock;
    ThemeCacheNode *head;
} ThemeCache;

CipherContext* initialize_cipher(const char *password, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key from password using SHA-1
    unsigned char key[SHA1_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), key);

    // Set up AES-256-CBC cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, *iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    CipherContext *cipher_context = malloc(sizeof(CipherContext));
    if (!cipher_context) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    cipher_context->ctx = ctx;
    cipher_context->iv = *iv;

    // Validate key length and IV
    if (EVP_CIPHER_CTX_key_length(ctx) != 32 || EVP_CIPHER_CTX_iv_length(ctx) != AES_BLOCK_SIZE) {
        free(cipher_context);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return cipher_context;
}

void* get_default_theme_directory(void) {
    char *theme_dir = getenv("THEME_DIR");
    if (!theme_dir) theme_dir = "/default/theme/path";

    // Logic to ensure the directory exists and is valid
    return strdup(theme_dir);
}

void recycle_unused_bitmaps(ThemeCache *cache) {
    pthread_mutex_lock(&cache->lock);

    ThemeCacheNode *current = cache->head;
    while (current) {
        if (current->bitmap && current->size > 0) {
            free(current->bitmap);
            current->bitmap = NULL;
            current->size = 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
}

ThemeCacheNode* load_theme_from_cache(const char *theme_path, ThemeCache *cache) {
    FILE *fp = fopen(theme_path, "rb");
    if (!fp) return NULL;

    fseek(fp, 0, SEEK_END);
    size_t file_size = ftell(fp);
    rewind(fp);

    unsigned char *data = malloc(file_size);
    if (!data) {
        fclose(fp);
        return NULL;
    }

    fread(data, 1, file_size, fp);
    fclose(fp);

    // Ensure data is valid and meets theme specifications
    // Placeholder for validation logic

    ThemeCacheNode *node = malloc(sizeof(ThemeCacheNode));
    if (!node) {
        free(data);
        return NULL;
    }

    node->bitmap = data;
    node->size = file_size;
    node->next = cache->head;

    pthread_mutex_lock(&cache->lock);
    cache->head = node;
    pthread_mutex_unlock(&cache->lock);

    return node;
}

void initialize_theme_cache(ThemeCache *cache) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->head = NULL;
}

int main() {
    ThemeCache theme_cache;
    initialize_theme_cache(&theme_cache);

    char *default_theme_dir = get_default_theme_directory();
    printf("Using theme directory: %s\n", default_theme_dir);

    const char *password = "secure_password";
    unsigned char iv[AES_BLOCK_SIZE] = {0}; // Should be securely generated

    CipherContext *cipher_context = initialize_cipher(password, &iv);
    if (!cipher_context) {
        fprintf(stderr, "Cipher initialization failed.\n");
        return 1;
    }

    load_theme_from_cache("path/to/theme.png", &theme_cache);

    recycle_unused_bitmaps(&theme_cache);

    // Clean up
    EVP_CIPHER_CTX_free(cipher_context->ctx);
    free(cipher_context);
    pthread_mutex_destroy(&cache.lock);

    free(default_theme_dir);
    return 0;
}
```

### Explanation:

- **Cipher Initialization:** The `initialize_cipher` function initializes AES-256-CBC encryption using a SHA-1 hashed password and a fixed IV. It returns a pointer to the cipher context if successful.

- **Theme Directory Management:** A default theme directory is fetched from an environment variable or set to a predefined path.

- **Cache Recycling:** The `recycle_unused_bitmaps` function nullifies unused bitmaps within the cache, freeing memory as needed.

- **Loading Themes:** Themes are loaded into the cache from specified file paths. Each loaded theme node maintains its bitmap data.

- **Thread Safety:** All operations on shared resources like the theme cache use mutex locks to ensure thread safety.

This code provides a basic framework for managing cryptographic operations and theme caching in a mobile application environment, focusing on security, efficiency, and scalability.']

