#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define MAX_COMMANDS 100
#define ENV_VARS "PATH=/usr/bin;USER=example"

typedef struct {
    int success;
    char message[256];
} CommandResult;

void execute_command(const char* command, const char* env_vars, int timeout, CommandResult* result);
void log_status(const char* status_message);

CommandResult* execute_commands_in_background(char** commands, size_t num_commands, int timeout) {
    if (num_commands > MAX_COMMANDS) {
        fprintf(stderr, "Exceeded maximum number of commands: %zu\n", num_commands);
        return NULL;
    }

    CommandResult* results = calloc(num_commands, sizeof(CommandResult));
    if (!results) {
        perror("Failed to allocate memory for results");
        return NULL;
    }

    for (size_t i = 0; i < num_commands; ++i) {
        execute_command(commands[i], ENV_VARS, timeout, &results[i]);
    }

    // Wait for all background processes
    while (wait(NULL) > 0);

    return results;
}

void execute_command(const char* command, const char* env_vars, int timeout, CommandResult* result) {
    pid_t pid = fork();
    if (pid < 0) {
        snprintf(result->message, sizeof(result->message), "Fork failed: %s", strerror(errno));
        result->success = 0;
        log_status(result->message);
        return;
    }

    if (pid == 0) { // Child process
        setenv("PATH", strtok(env_vars, ";"), 1);
        setenv("USER", strtok(NULL, ""), 1);

        execl("/bin/sh", "sh", "-c", command, (char*)NULL);
        snprintf(result->message, sizeof(result->message), "Exec failed: %s", strerror(errno));
        exit(EXIT_FAILURE); // If execl fails
    }

    int status;
    pid_t wpid = waitpid(pid, &status, 0);

    if (wpid == -1) {
        snprintf(result->message, sizeof(result->message), "Waitpid failed: %s", strerror(errno));
        result->success = 0;
        log_status(result->message);
        return;
    }

    if (WIFEXITED(status)) {
        int exit_code = WEXITSTATUS(status);
        if (exit_code == 0) {
            snprintf(result->message, sizeof(result->message), "Command succeeded: %s", command);
            result->success = 1;
        } else {
            snprintf(result->message, sizeof(result->message), "Command failed with exit code %d: %s", exit_code, command);
            result->success = 0;
        }
    } else if (WIFSIGNALED(status)) {
        snprintf(result->message, sizeof(result->message), "Command terminated by signal %d: %s", WTERMSIG(status), command);
        result->success = 0;
    }

    log_status(result->message);
}

void log_status(const char* status_message) {
    printf("%s\n", status_message); // Basic logging; can be extended
}

int main() {
    char* commands[] = {"echo Hello World", "sleep 2", "invalid_command"};
    size_t num_commands = sizeof(commands) / sizeof(commands[0]);
    int timeout = 5;

    CommandResult* results = execute_commands_in_background(commands, num_commands, timeout);

    if (results) {
        for (size_t i = 0; i < num_commands; ++i) {
            printf("Command %zu: %s\n", i + 1, results[i].message);
        }
        free(results);
    }

    return 0;
}
```

This C code defines a function to execute commands in the background with specific environment configurations. It handles errors gracefully, logs command statuses, and uses a timeout mechanism for each command. The `execute_commands_in_background` function manages multiple processes efficiently and returns execution results.']

