#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

// Assume these are provided by other parts of your application.
extern int verify_password_hash(const char* username, const char* password);
extern void log_error(const char* message);

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        log_error("Not enough memory");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = '\0';

    return realsize;
}

int validate_json_payload(const char *json_payload) {
    // Parse JSON payload and check for required fields
    if (!json_payload || strstr(json_payload, "\"username\"") == NULL ||
        strstr(json_payload, "\"password\"") == NULL ||
        strstr(json_payload, "\"session_token\"") == NULL) {
        log_error("Missing required fields in JSON payload");
        return 0;
    }

    char *username = strdup(strstr(json_payload, "\"username\":\"") + 12);
    char *end = strchr(username, '"');
    if (!end) { free(username); return 0; }
    *end = '\0';

    char *password = strdup(strstr(json_payload, "\"password\":\"") + 11);
    end = strchr(password, '"');
    if (!end) { free(username); free(password); return 0; }
    *end = '\0';

    char *session_token = strdup(strstr(json_payload, "\"session_token\":\"") + 17);
    end = strchr(session_token, '"');
    if (!end) { free(username); free(password); free(session_token); return 0; }
    *end = '\0';

    // Verify password hash
    if (!verify_password_hash(username, password)) {
        log_error("Password verification failed");
        free(username);
        free(password);
        free(session_token);
        return 0;
    }

    // Validate session token with external service
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "https://token.service/verify?session_token=%s", session_token);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            log_error("Failed to verify session token");
            free(chunk.memory);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            free(username);
            free(password);
            free(session_token);
            return 0;
        }

        // Check response from the service
        const char *response = chunk.memory;
        if (strstr(response, "invalid") != NULL || strstr(response, "expired") != NULL) {
            log_error("Session token invalid or expired");
            free(chunk.memory);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            free(username);
            free(password);
            free(session_token);
            return 0;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    free(chunk.memory);
    free(username);
    free(password);
    free(session_token);

    return 1;
}
