```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class MessageProcessor
{
    private readonly ILogger<MessageProcessor> _logger;
    private readonly IMemoryCache _cache;
    private static readonly object CacheLock = new();

    public MessageProcessor(ILogger<MessageProcessor> logger, IMemoryCache cache)
    {
        _logger = logger;
        _cache = cache;
    }

    public string ProcessEncryptedMessage(string encryptedData, string algorithmConfig, byte[] key, byte[] iv = null)
    {
        if (string.IsNullOrEmpty(encryptedData) || string.IsNullOrEmpty(algorithmConfig))
            throw new ArgumentException("Invalid input data or configuration.");

        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            // Validate and parse the Base64 encoded encrypted data
            byte[] cipherTextBytes;
            try
            {
                cipherTextBytes = Convert.FromBase64String(encryptedData);
            }
            catch (FormatException)
            {
                _logger.LogError("Invalid Base64 format.");
                return CreateReport($"Failure: Invalid Base64 string. Algorithm: {algorithmConfig}");
            }

            // Check cache for encryption algorithm instance
            using var algCacheKey = new object[] { algorithmConfig, key.Length, iv?.Length ?? 0 };
            using (MemoryCacheEntryOptions options = new())
            {
                if (!_cache.TryGetValue(algCacheKey, out SymmetricAlgorithm symmetricAlg))
                {
                    lock (CacheLock)
                    {
                        if (!_cache.TryGetValue(algCacheKey, out symmetricAlg))
                        {
                            symmetricAlg = CreateSymmetricAlgorithm(algorithmConfig, key, iv);
                            _cache.Set(algCacheKey, symmetricAlg, options);
                        }
                    }
                }

                // Decrypt the message
                byte[] plainBytes;
                using (ICryptoTransform decryptor = symmetricAlg.CreateDecryptor(key, iv))
                {
                    plainBytes = decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length);
                }

                stopwatch.Stop();

                return CreateReport($"Success: {Encoding.UTF8.GetString(plainBytes)}", algorithmConfig, encryptedData, stopwatch.ElapsedMilliseconds);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing encrypted message.");
            stopwatch.Stop();
            return CreateReport($"Failure: {ex.Message}. Algorithm: {algorithmConfig}", algorithmConfig, encryptedData, stopwatch.ElapsedMilliseconds);
        }
    }

    private SymmetricAlgorithm CreateSymmetricAlgorithm(string algorithmConfig, byte[] key, byte[] iv)
    {
        switch (algorithmConfig.ToLower())
        {
            case "tripledes":
                var tripleDES = new TripleDESCryptoServiceProvider();
                tripleDES.Key = key;
                tripleDES.IV = iv;
                return tripleDES;

            case "aes":
                var aes = Aes.Create();
                aes.Key = key;
                aes.IV = iv;
                return aes;

            default:
                throw new NotSupportedException($"Encryption algorithm '{algorithmConfig}' is not supported.");
        }
    }

    private string CreateReport(string result, string algorithmConfig = null, string inputData = null, long processingTimeMs = 0)
    {
        var reportBuilder = new StringBuilder();
        reportBuilder.AppendLine("Decryption Report:");
        if (!string.IsNullOrEmpty(algorithmConfig))
            reportBuilder.AppendLine($"Algorithm: {algorithmConfig}");
        if (!string.IsNullOrEmpty(inputData))
            reportBuilder.AppendLine($"Input Data: {inputData.Length} bytes");
        reportBuilder.AppendLine($"Result: {result}");
        reportBuilder.AppendLine($"Processing Time: {processingTimeMs} ms");

        return reportBuilder.ToString();
    }
}
```

### Key Points:
- **Caching**: Utilizes an `IMemoryCache` to cache symmetric algorithm instances, reducing overhead for repeated operations.
- **Logging**: Logs processing times and errors using `ILogger`.
- **Validation**: Validates Base64 input strings and handles exceptions gracefully.
- **Concurrency**: Locks on cache access to prevent race conditions when creating new algorithm instances.
- **Modular Design**: Easily extendable to support additional encryption algorithms.']

