using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasherService
{
    private readonly string _configFilePath;
    private readonly string _errorLogPath;
    private readonly ConcurrentDictionary<string, string> _filePaths = new();

    public FileHasherService(string configFilePath, string errorLogPath)
    {
        _configFilePath = configFilePath ?? throw new ArgumentNullException(nameof(configFilePath));
        _errorLogPath = errorLogPath ?? throw new ArgumentNullException(nameof(errorLogPath));
        LoadFileConfigurations();
    }

    private void LoadFileConfigurations()
    {
        if (File.Exists(_configFilePath))
        {
            var lines = File.ReadAllLines(_configFilePath);
            foreach (var line in lines)
            {
                _filePaths.TryAdd(line.Trim(), null);
            }
        }
    }

    public async Task<Dictionary<string, string>> GetValidFilePathsAndHashesAsync()
    {
        var validFilesWithHashes = new Dictionary<string, string>();
        List<Task> tasks = new();

        foreach (var filePath in _filePaths.Keys)
        {
            tasks.Add(Task.Run(() => ProcessFile(filePath, validFilesWithHashes)));
        }

        await Task.WhenAll(tasks);

        return validFilesWithHashes;
    }

    private void ProcessFile(string filePath, Dictionary<string, string> result)
    {
        if (ValidateFilePath(filePath))
        {
            var hash = ComputeSha256(filePath);
            lock (result)
            {
                result[filePath] = hash;
            }
        }
        else
        {
            LogError($"Invalid file path: {filePath}");
        }
    }

    private bool ValidateFilePath(string filePath)
    {
        return File.Exists(filePath);
    }

    private string ComputeSha256(string filePath)
    {
        using (var sha256 = SHA256.Create())
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hashBytes = sha256.ComputeHash(stream);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }
    }

    private void LogError(string message)
    {
        lock (_errorLogPath)
        {
            File.AppendAllText(_errorLogPath, $"{DateTime.UtcNow}: {message}{Environment.NewLine}");
        }
    }

    public void UpdateFileConfigurations(List<string> newFilePaths)
    {
        foreach (var path in newFilePaths)
        {
            _filePaths[path] = null;
        }
    }
}
