using System;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using System.Collections.Concurrent;

public class LargeBinaryFileLoader
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const int MaxRetries = 3;
    private const int BufferSize = 4 * 1024; // 4KB buffer

    public async Task<T> LoadAndDeserializeAsync<T>(string remoteUrl) where T : class
    {
        byte[] fileData;

        try
        {
            fileData = await DownloadFileWithRetries(remoteUrl, MaxRetries);
        }
        catch (Exception ex)
        {
            LogError("Failed to download the file", ex);
            throw;
        }

        try
        {
            return Deserialize<T>(fileData);
        }
        catch (Exception ex)
        {
            LogError("Deserialization failed", ex);
            throw;
        }
    }

    private async Task<byte[]> DownloadFileWithRetries(string url, int maxRetries)
    {
        int attempts = 0;
        while (attempts < maxRetries)
        {
            try
            {
                using var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();

                using var stream = await response.Content.ReadAsStreamAsync();
                return await ReadStreamWithBuffer(stream);
            }
            catch (Exception ex) when (attempts < maxRetries - 1)
            {
                attempts++;
                LogWarning($"Attempt {attempts} failed: {ex.Message}. Retrying...");
                await Task.Delay(1000); // Wait before retrying
            }
        }

        throw new Exception("Failed to download file after multiple attempts.");
    }

    private async Task<byte[]> ReadStreamWithBuffer(Stream stream)
    {
        using var memoryStream = new MemoryStream();
        byte[] buffer = new byte[BufferSize];

        int bytesRead;
        while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            memoryStream.Write(buffer, 0, bytesRead);
        }

        return memoryStream.ToArray();
    }

