// Import necessary modules
const { Kafka } = require('kafkajs');
const fs = require('fs');
const path = require('path');
const axios = require('axios');

class FileUploader {
  constructor(configServiceUrl, kafkaBroker) {
    this.kafka = new Kafka({
      clientId: 'file-uploader',
      brokers: [kafkaBroker]
    });
    this.producer = this.kafka.producer();
    this.configServiceUrl = configServiceUrl;
    this.fileMetadataStore = new Map(); // In-memory store for simplicity
  }

  async init() {
    await this.producer.connect();
    setInterval(() => this.updateConfig(), 60000); // Update configuration every minute
  }

  updateConfig() {
    axios.get(this.configServiceUrl)
      .then(response => {
        const config = response.data;
        Object.assign(this, config);
      })
      .catch(err => console.error('Failed to update config:', err));
  }

  async upload(fileBuffer, fileName, user) {
    try {
      // Validate file type and size
      if (!this.isValidFileType(fileName)) throw new Error('Invalid file type');
      if (fileBuffer.length > this.maxFileSize) throw new Error('File too large');

      const timestamp = Date.now();
      const fileId = `${user.id}-${timestamp}-${path.basename(fileName)}`;

      // Write file to temporary storage
      const tempFilePath = path.join(this.tempStoragePath, fileId);
      fs.writeFileSync(tempFilePath, fileBuffer);

      // Store metadata
      this.fileMetadataStore.set(fileId, {
        fileName,
        userId: user.id,
        uploadTimestamp: timestamp,
        size: fileBuffer.length,
        status: 'uploaded'
      });

      // Produce message to Kafka for further processing
      await this.producer.send({
        topic: 'file-upload-topic',
        messages: [{ value: JSON.stringify({ fileId, tempFilePath }) }]
      });

    } catch (error) {
      console.error('Upload error:', error.message);
      throw new Error(`Failed to upload file: ${fileName}`);
    }
  }

  isValidFileType(fileName) {
    const validTypes = this.allowedFileTypes.split(',');
    return validTypes.some(type => fileName.endsWith(type));
  }

  async finalize(fileId) {
    if (!this.fileMetadataStore.has(fileId)) return;

    try {
      // Retrieve metadata
      const { tempFilePath, userId, fileName } = this.fileMetadataStore.get(fileId);

      // Move file to permanent storage (simulated)
      const finalPath = path.join(this.permanentStoragePath, `${userId}/${fileName}`);
      fs.renameSync(tempFilePath, finalPath);

      // Update metadata status
      this.fileMetadataStore.set(fileId, { ...this.fileMetadataStore.get(fileId), status: 'finalized' });

    } catch (error) {
      console.error('Finalize error:', error.message);
      throw new Error(`Failed to finalize file: ${fileId}`);
    }
  }

  async shutdown() {
    await this.producer.disconnect();
  }
}

module.exports = FileUploader;

// Usage example:
// const uploader = new FileUploader('http://config-service/config', 'localhost:9092');
// await uploader.init();

// Example upload call
// uploader.upload(fileBuffer, 'example.jpg', { id: 'user123' });

```

### Explanation

- **Kafka Integration:** The code uses Kafka for asynchronous processing of file uploads. This ensures that the system can handle high concurrency by offloading processing to a message queue.

- **Configuration Management:** Configuration is fetched from an external service and periodically updated, allowing real-time changes without downtime.

- **File Validation:** Validates file types and sizes before proceeding with uploads.

- **Temporary Storage:** Files are temporarily stored locally, then moved to permanent storage upon successful processing.

- **Metadata Handling:** File metadata is managed in-memory for simplicity, but can be extended to use a more scalable store like a database.

- **Error Handling:** Robust error handling ensures that any issues during file upload or processing are logged and managed gracefully.

- **Shutdown Procedure:** Ensures clean disconnection from Kafka when the application shuts down."]

["```javascript
class DataFetcher {
  constructor() {
    this.cache = {};
    this.config = {
      cacheTimeout: 60000, // Default cache timeout in milliseconds
      apiRequestInterval: 300000, // Default interval between requests
      weatherApiKey: 'YOUR_WEATHER_API_KEY',
      pollutionApiKey: 'YOUR_POLLUTION_API_KEY',
      trafficApiKey: 'YOUR_TRAFFIC_API_KEY'
    };
    this.apiEndpoints = {
      weather: `https://api.weather.com/v1/location`,
      pollution: `https://api.pollution.com/v1/data`,
      traffic: `https://api.traffic.com/v1/status`
    };
  }

  async fetchData(location) {
    const now = Date.now();

    // Check if data is cached and valid
    if (this.cache[location] && (now - this.cache[location].timestamp < this.config.cacheTimeout)) {
      return this.cache[location].data;
    }

    try {
      const weatherData = await this.fetchWithRetry(this.apiEndpoints.weather, location, this.config.weatherApiKey);
      const pollutionData = await this.fetchWithRetry(this.apiEndpoints.pollution, location, this.config.pollutionApiKey);
      const trafficData = await this.fetchWithRetry(this.apiEndpoints.traffic, location, this.config.trafficApiKey);

      // Cache the data with a timestamp
      this.cache[location] = {
        data: { weather: weatherData, pollution: pollutionData, traffic: trafficData },
        timestamp: now
      };

      return this.cache[location].data;
    } catch (error) {
      console.error('Error fetching data:', error);
      // Notify user with a fallback mechanism or message
      this.notifyUserOfIssue(error);
    }
  }

  async fetchWithRetry(endpoint, location, apiKey, retries = 3) {
    let attempts = 0;

    while (attempts < retries) {
      try {
        const response = await fetch(`${endpoint}/${location}?apiKey=${apiKey}`);

        if (!response.ok) throw new Error(`API request failed with status ${response.status}`);

        return await response.json();
      } catch (error) {
        attempts++;
        console.error(`Attempt ${attempts} for ${endpoint} failed:`, error);

        // Handle specific errors like rate limits
        if (error.message.includes('429')) {
          const retryAfter = response.headers.get('Retry-After') || 1000;
          await this.sleep(retryAfter);
        } else {
          await this.sleep(2000); // Wait before retrying other types of failures
        }
      }
    }

    throw new Error(`Failed to fetch data from ${endpoint} after ${retries} attempts`);
  }

  notifyUserOfIssue(error) {
    if (error.message.includes('429')) {
      console.warn('Request rate limit exceeded. Please try again later.');
    } else {
      console.error('There was an issue retrieving the latest data. Please check your connection or try again later.');
    }
  }

  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  setConfig(options) {
    this.config = { ...this.config, ...options };
  }
}

// Example usage
const dataFetcher = new DataFetcher();
dataFetcher.setConfig({ cacheTimeout: 120000, apiRequestInterval: 600000 });

async function displayData(location) {
  try {
    const data = await dataFetcher.fetchData(location);
    console.log('Fetched Data:', data);
  } catch (error) {
    console.error('Error displaying data:', error);
  }
}

// Trigger the data fetch
displayData('NewYork');
```"]

