using Graph = boost::adjacency_list<boost::vecS, boost::vecS, boost::undirectedS>;
struct VertexProperty {
    int id;
    std::unordered_map<std::string, std::string> properties;

    VertexProperty(int vertex_id) : id(vertex_id) {}
};

// HTTP request manager with retry mechanism
class HttpRequestManager {
public:
    HttpRequestManager(boost::asio::io_context& io_context)
        : resolver_(io_context), socket_(io_context) {}

    void async_request(const std::string& url, int retries = 3) {
        auto self = shared_from_this();
        boost::asio::ip::tcp::resolver::query query(url, "http");
        resolver_.async_resolve(query,
            [this, self, retries](const boost::system::error_code& ec, 
                                  boost::asio::ip::tcp::endpoint endpoint) {
                if (!ec) {
                    socket_.async_connect(endpoint,
                        [this, self, url, retries](const boost::system::error_code& ec) {
                            if (!ec) {
                                send_request(url);
                            } else if (retries > 0) {
                                async_request(url, retries - 1);
                            }
                        });
                } else if (retries > 0) {
                    async_request(url, retries - 1);
                }
            });
    }

private:
    void send_request(const std::string& url) {
        // Send HTTP request logic here
        std::cout << "Request sent to: " << url << "\n";
        // Simulate response handling
    }

    boost::asio::ip::tcp::resolver resolver_;
    boost::asio::ip::tcp::socket socket_;
};

// Main application class
