use tokio::time::{sleep, Duration};
use log::{info, warn, error, LevelFilter};
use simplelog::*;
use serde_json::Value;
use std::env;
use reqwest::Client;

mod logger {
    use log::{Record, Metadata, Level};
    use std::sync::{Arc, Mutex};
    use simplelog::*;

    pub struct LoggerConfig {
        pub level: LevelFilter,
        pub file_path: Option<String>,
        pub remote_endpoint: Option<String>,
    }

    impl LoggerConfig {
        pub fn new() -> Self {
            // Load configuration from a file or environment
            Self {
                level: LevelFilter::Info, // default level
                file_path: None,
                remote_endpoint: None,
            }
        }
    }

    pub struct AppLogger {
        sinks: Arc<Mutex<Vec<Box<dyn Write + Send>>>>,
    }

    impl AppLogger {
        pub fn new(config: LoggerConfig) -> Self {
            let mut sinks = vec![];

            if let Some(file_path) = config.file_path.clone() {
                let file_logger = WriteLogger::new(LevelFilter::Info, Config::default(), file_path);
                sinks.push(Box::new(file_logger));
            }

            if let Some(remote_endpoint) = config.remote_endpoint.clone() {
                // Add logic to initialize remote logging (e.g., gRPC client)
                // This is a placeholder as actual implementation will depend on the protocol.
            }

            Self { sinks: Arc::new(Mutex::new(sinks)) }
        }

        pub fn log(&self, record: &Record) {
            if let Ok(mut sinks) = self.sinks.lock() {
                for sink in &mut *sinks {
                    writeln!(sink, "{:?}: {}", record.level(), record.args()).ok();
                }
            }
        }
    }

    impl log::Log for AppLogger {
        fn enabled(&self, metadata: &Metadata) -> bool {
            metadata.level() <= LevelFilter::Info
        }

        fn log(&self, record: &Record) {
            if self.enabled(record.metadata()) {
                Self::new(LoggerConfig::new()).log(record);
            }
        }

        fn flush(&self) {}
    }
}

#[tokio::main]
async fn main() {
    let config = logger::LoggerConfig::new();
    let _logger = logger::AppLogger::new(config);

    simplelog::CombinedLogger::init(vec![
        TermLogger::new(LevelFilter::Info, Config::default(), TerminalMode::Mixed).unwrap(),
        WriteLogger::new(LevelFilter::Debug, Config::default(), "output.log"),
    ]).expect("Failed to initialize logging");

    let args: Vec<String> = env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("task1") => task_one().await,
        Some("task2") => task_two().await,
        _ => warn!("No valid command provided"),
    }
}

