    owner_gid: u32,
}

async fn create_and_configure_directory(
    config_service_url: &str,
    directory_name: &str,
) -> Result<PathBuf, String> {
    // Attempt to retrieve the path from environment variable
    let dir_path_env = env::var("DIR_PATH").ok();
    let mut dir_path = match dir_path_env {
        Ok(path) => PathBuf::from(path),
        Err(_) => PathBuf::new(),
    };

    if !dir_path.is_dir() {
        // Ensure the path is empty or doesn't exist
        fs::remove_dir_all(&dir_path).ok();
    }

    // Append directory name to the existing path, ensuring uniqueness
    dir_path.push(directory_name);

    let config = retrieve_directory_config(config_service_url).await?;

    // Use OnceCell for one-time initialization logic
    static DIRECTORY_CREATE: OnceCell<()> = OnceCell::new();

    match DIRECTORY_CREATE.get_or_init(|| {
        tokio::spawn(async move {
            if !dir_path.exists() {
                DirBuilder::new()
                    .recursive(true)
                    .mode(config.permissions)
                    .create(&dir_path).map_err(|e| e.to_string())
            } else {
                Ok(())
            }
        })
    }) {
        Ok(_) => (),
        Err(e) => return Err(format!("Failed to create directory: {}", e)),
    }

    // Update the environment variable with the new path
    if let Err(e) = env::set_var("DIR_PATH", dir_path.to_str().unwrap_or_default()) {
        error!("Failed to set DIR_PATH environment variable: {}", e);
    }

    info!(
        "Directory created and configured at {:?}",
        dir_path
    );

    Ok(dir_path)
}

async fn retrieve_directory_config(config_service_url: &str) -> Result<DirectoryConfig, String> {
    let client = Client::new();
    match client.get(config_service_url).send().await {
        Ok(response) => match response.json::<DirectoryConfig>().await {
            Ok(config) => Ok(config),
            Err(err) => Err(format!("Failed to parse configuration: {}", err)),
        },
        Err(ReqwestError::Timeout | ReqwestError::Connect(ref e)) if e.is_timeout() => {
            info!("Retrying due to timeout...");
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            retrieve_directory_config(config_service_url).await
        }
        Err(err) => Err(format!("Failed to fetch configuration: {}", err)),
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let config_service_url = "https://config-service.example.com/directory-config";
    let directory_name = "my_directory";

    match create_and_configure_directory(config_service_url, directory_name).await {
        Ok(path) => info!("Successfully created and configured directory at {:?}", path),
        Err(err) => error!("Error creating or configuring directory: {}", err),
    }
}
```

**Assumptions & Design Decisions:**

- **Environment Variable:** The `DIR_PATH` variable is used to store the base directory. If it doesn't exist, a new path is created and set.
- **Atomic Directory Creation:** We use Rust's `OnceCell` for one-time operations in conjunction with asynchronous execution to handle potential race conditions gracefully.
- **Network Resilience:** The configuration retrieval function includes retry logic on timeout or connection errors, ensuring robustness against network issues.
- **Logging:** All operations and errors are logged using the `log` crate, which is initialized at runtime. This supports structured logging for analysis.
- **Idempotency & Extensibility:** The design ensures that re-running the function doesn't cause errors if directories already exist and allows easy addition of new parameters by extending the `DirectoryConfig` struct.
- **Performance Considerations:** Network calls are minimized, and retries include delays to handle transient network issues efficiently. 

This implementation balances efficiency, maintainability, scalability, and extensibility while adhering to Rust's idiomatic practices.']

