class ConfigRegistry:
    def __init__(self):
        self._factories = {}
        self._latest_versions = {}

    def register_factory(self, id_, factory_fn, version=None):
        if id_ in self._factories and not version:
            raise ValueError(f"ID {id_} is already registered.")

        self._factories[id_] = factory_fn
        self._latest_versions[id_] = version or factory_fn.__annotations__.get('version', 1)

    def remove_factory(self, id_):
        if id_ in self._factories:
            del self._factories[id_]
            del self._latest_versions[id_]

    @lru_cache(maxsize=128)  # Caching frequently accessed configurations
    def create_config(self, id_, json_str=None, version=None):
        factory = self._factories.get(id_)
        if not factory:
            raise ValueError(f"No factory registered for ID {id_}")

        requested_version = version or self._latest_versions[id_]
        return factory(json_str=json_str, version=requested_version)

    def get_documentation(self):
        docs = "Configuration Factories:\n"
        for id_, (factory, version) in zip(self._factories.keys(), self._latest_versions.items()):
            docs += f"- {id_}: Version {version}\n"
        return docs

def database_factory(json_str=None, version=1):
    class_version_map = {
        1: DatabaseConfig,
        2: DatabaseConfig
    }

    if version not in class_version_map:
        raise ValueError(f"Unsupported version: {version}")

    return class_version_map[version](json_str)

def api_factory(json_str=None, version=1):
    if version != 1:
        raise ValueError(f"Unsupported version: {version}")

    return ApiConfig(json_str)

def logging_factory(json_str=None, version=1):
