    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void nfa_api_send_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Mock function to send PDU
}

// Thread-safe list management
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_pdu_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    nfa_api_send_pdu(&pdu);  // Send PDU as part of adding to the list
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// C function for managing NFAPI_CRC_INDICATION_PDU_T structures
void manage_pdu_list(int n) {
    List* pdu_list = create_list();

    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_pdu_to_list(pdu_list, pdu);
    }

    free_list(pdu_list);
}

