```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10]; // Example size
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*OutOfMemoryCallback)(void);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int used_entries;
    pthread_mutex_t lock;
    OutOfMemoryCallback oom_callback;
    time_t last_cleanup_time;
} DynamicArrayManager;

static const size_t PAGE_SIZE = 4096; // Custom allocator page size

void init_dynamic_array_manager(DynamicArrayManager* manager, OutOfMemoryCallback callback) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->used_entries = 0;
    manager->oom_callback = callback;
    manager->last_cleanup_time = time(NULL);
}

int allocate_entry(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used_entries >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        if (manager->oom_callback) {
            manager->oom_callback();
        }
        return -1; // Out of memory
    }

    time_t current_time = time(NULL);
    entry.RX_UE_INFORMATION_TAG = rand(); // Example logic
    entry.CRC_INDICATION_REL8_TAG[0] = (entry.RNTI & 0xFF) ^ ((current_time >> 8) & 0xFF); // Example CRCFLAG logic

    manager->entries[manager->used_entries++] = entry;

    if (difftime(current_time, manager->last_cleanup_time) > 60) {
        // Perform garbage collection
        for (int i = 0; i < manager->used_entries / 2; ++i) { // Example cleanup logic
            manager->entries[i] = manager->entries[manager->used_entries - 1];
        }
        manager->used_entries /= 2;
        manager->last_cleanup_time = current_time;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void destroy_dynamic_array_manager(DynamicArrayManager* manager) {
    pthread_mutex_destroy(&manager->lock);
}

// Example callback function for out-of-memory condition
void oom_callback_handler() {
    fprintf(stderr, "Out of memory\n");
}
```

### Key Points:

1. **Dynamic Memory Allocation**: A static array with a fixed size (`MAX_ENTRIES`) is used to avoid frequent dynamic allocations. This reduces fragmentation and improves cache performance.

2. **Error Handling**: An out-of-memory callback mechanism notifies the caller when no more entries can be added.

3. **Thread Safety**: A mutex lock ensures that multiple threads can safely modify the array concurrently.

4. **Garbage Collection**: Periodically, half of the entries are cleaned up to free space, based on a time threshold.

5. **Performance Optimization**: The use of a fixed-size array and periodic garbage collection helps optimize both memory usage and processing time.

6. **System Dependencies**: The function is designed to integrate with existing systems by allowing custom callbacks for error handling.

7. **Scalability**: The approach scales by managing memory usage effectively and ensuring thread safety, though the static size limits maximum entries.

This implementation balances complexity, performance, and resource management based on typical constraints in embedded or real-time systems.']

