use reqwest::{Client, Error};
use std::sync::Arc;
use tokio::runtime::Runtime;

struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient { 
            client: Client::builder()
                .cookie_store(true)
                .build().unwrap(),
        }
    }

    pub async fn fetch_config(&self, url: &str, auth_token: &str) -> Result<(), Error> {
        let response = self.client
            .get(url)
            .bearer_auth(auth_token)
            .send()
            .await?;

        if response.status().is_success() {
            let config_data = response.json::<serde_json::Value>().await?;
            println!("{:?}", config_data);
            Ok(())
        } else {
            Err(Error::new(reqwest::StatusCode::from_u16(response.status_as_u16()).unwrap(), false))
        }
    }
}

fn main() {
    let runtime = Arc::new(Runtime::new().unwrap());
    runtime.block_on(async {
        let client = HttpClient::new();
        if let Err(e) = client.fetch_config("https://api.example.com/config", "your-auth-token").await {
            eprintln!("Failed to fetch config: {}", e);
        }
    });
}
