UnionFind* create_union_find(size_t size) {
    UnionFind *uf = (UnionFind *)malloc(sizeof(UnionFind));
    uf->parent = (int *)malloc(size * sizeof(int));
    uf->size = size;

    for (size_t i = 0; i < size; ++i)
        uf->parent[i] = i;

    return uf;
}

int find(UnionFind *uf, int i) {
    if (uf->parent[i] != i)
        uf->parent[i] = find(uf, uf->parent[i]);
    return uf->parent[i];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY)
        uf->parent[rootY] = rootX;
}

