#define INITIAL_CAPACITY 10

// Thread safety lock for shared resources
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure for storing NAS_Transport_PDU
typedef struct {
    NAS_Transport_PDU *array;
    size_t used;
    size_t capacity;
} PduArray;

void initPduArray(PduArray *a) {
    a->capacity = INITIAL_CAPACITY;
    a->used = 0;
    a->array = malloc(sizeof(NAS_Transport_PDU) * a->capacity);
    if (!a->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void freePduArray(PduArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->capacity = 0;
}

void ensureCapacity(PduArray *a) {
    if (a->used == a->capacity) {
        size_t new_capacity = a->capacity * 2;
        NAS_Transport_PDU *new_array = realloc(a->array, sizeof(NAS_Transport_PDU) * new_capacity);
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        a->array = new_array;
        a->capacity = new_capacity;
    }
}

int validateNasMessage(LTE_NAS_Message *message) {
    // Placeholder validation logic
    return message->id >= 0; 
}

void addNasTransportPdu(PduArray *a, LTE_NAS_Message nas_message) {
    if (!validateNasMessage(&nas_message)) {
        fprintf(stderr, "Invalid NAS Message\n");
        return;
    }

    ensureCapacity(a);

    pthread_mutex_lock(&queue_lock);
    a->array[a->used].nas_message = nas_message;
    (a->used)++;
    pthread_mutex_unlock(&queue_lock);
}

void processMessagesFromBroker(PduArray *pdu_array, LTE_NAS_Message (*get_next_message)()) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        LTE_NAS_Message msg = get_next_message();

        if (msg.id == -1) {  // Assuming -1 as an end-of-messages indicator
            pthread_mutex_unlock(&queue_lock);
            break;
        }

        addNasTransportPdu(pdu_array, msg);
        pthread_mutex_unlock(&queue_lock);
    }
}

// Example external message broker function
LTE_NAS_Message get_next_message() {
    static int current_id = 0;

    if (current_id > 20) {  // Limit the number of messages for this example
        return (LTE_NAS_Message){.id = -1}; 
    }

    LTE_NAS_Message msg = {.id = current_id++, .data = "Example Data"};
    return msg;
}

int main() {
    PduArray pdu_array;
    initPduArray(&pdu_array);

    processMessagesFromBroker(&pdu_array, get_next_message);

    for (size_t i = 0; i < pdu_array.used; i++) {
        printf("Message ID: %d\n", pdu_array.array[i].nas_message.id);
    }

    freePduArray(&pdu_array);

    return 0;
}
