// Define the structure for a configuration entry.
typedef struct {
    char ip[16];
    char mac[18];
    char subnet_mask[16];
    char gateway[16];
} DeviceConfig;

// Define the hash table node.
typedef struct Node {
    DeviceConfig config;
    struct Node* next;
} Node;

// Define the hash table.
#define TABLE_SIZE 1024
Node* hash_table[TABLE_SIZE];

unsigned int hash(char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % TABLE_SIZE;
}

void init_hash_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

// Validate the IP address format.
int is_valid_ip(const char* ip) {
    int num, dots = 0;
    const char *ptr;

    if (ip == NULL)
        return 0;

    ptr = ip;
    while (*ptr) {
        if (*ptr == '.') {
            if (!((++dots >= 1 && prev_char_is_digit(ptr)) &&
                  (prev_char_is_digit(ptr - 1))))
                return 0;
        } else if (!isdigit(*ptr))
            return 0;

        ptr++;
    }

    if (dots != 3)
        return 0;

    sscanf(ip, "%d.%d.%d.%d%n", &num, &num, &num, &num, &num);
    if (*ip + num != strlen(ip))
        return 0;

    return 1;
}

// Validate the MAC address format.
int is_valid_mac(const char* mac) {
    int i = 0;
    while (i < 17 && (isxdigit(mac[i]) || mac[i] == ':')) {
        if ((i % 3 == 2) && mac[i] != ':')
            return 0;
        ++i;
    }
    return i == 17 && mac[17] == '\0';
}

// Validate the subnet mask format.
int is_valid_subnet(const char* subnet) {
    // Similar to IP validation but checks for common subnet masks
    int num, dots = 0;
    const char *ptr;

    if (subnet == NULL)
        return 0;

    ptr = subnet;
    while (*ptr) {
        if (*ptr == '.') {
            if (!((++dots >= 1 && prev_char_is_digit(ptr)) &&
                  (prev_char_is_digit(ptr - 1))))
                return 0;
        } else if (!isdigit(*ptr))
            return 0;

        ptr++;
    }

    if (dots != 3)
        return 0;

    sscanf(subnet, "%d.%d.%d.%d%n", &num, &num, &num, &num, &num);
    // Check for common subnet masks like 255.255.255.0
    int mask = num << 24 | num << 16 | num << 8 | num;
    return (*ip + num == strlen(subnet)) && (mask & (mask - 1)) == 0;
}

// Function to add a device configuration into the hash table.
void add_device_config(const DeviceConfig* config) {
    unsigned int index = hash(config->ip);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&new_node->config, config, sizeof(DeviceConfig));
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

// Remove a device configuration from the hash table.
void remove_device_config(const char* ip) {
    unsigned int index = hash(ip);
    Node *current = hash_table[index], *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->config.ip, ip) == 0) {
            if (prev == NULL)
                hash_table[index] = current->next;
            else
                prev->next = current->next;
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Thread-safe function to process device configurations.
void* process_configs(void* arg) {
    DeviceConfig* configs = (DeviceConfig*)arg;
    int total_entries = *((int*)arg + 1); // Assuming second argument is count.

    init_hash_table();

    for (int i = 0; i < total_entries; ++i) {
        clock_t start_time = clock();

        if (!is_valid_ip(configs[i].ip) || !is_valid_mac(configs[i].mac)
            || !is_valid_subnet(configs[i].subnet_mask)) {
            continue;
        }

        add_device_config(&configs[i]);

        double time_taken = ((double)(clock() - start_time)) / CLOCKS_PER_SEC;
        printf("Processed config %d in %.6f seconds\n", i, time_taken);
    }

    return NULL;
}

// Main function to demonstrate the processing.
int main() {
    DeviceConfig configs[] = {
        {"192.168.1.1", "00:1A:2B:3C:4D:5E", "255.255.255.0", "192.168.1.254"},
        // Add more configurations as needed
