#define MAX_RNTI 65535

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

UnionFindNode* uf_create(int size) {
    UnionFindNode *uf = malloc(size * sizeof(UnionFindNode));
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(UnionFindNode* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void union_sets(UnionFindNode* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

typedef struct {
    int rnti;
    // Other PDU fields
} PDU;

PDU* process_rnti_array(int* array, size_t length, sqlite3* db) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    UnionFindNode *uf = uf_create(MAX_RNTI + 1);
    PDU *pdus = malloc(length * sizeof(PDU));

    // Database connection and mapping setup
    char* errMsg = NULL;
    int rc;

    for (size_t i = 0; i < length; ++i) {
        if (array[i] <= 0 || array[i] > MAX_RNTI) continue;

        pthread_mutex_lock(&lock);

        // Validate RNTI using Union-Find
        int rnti_parent = find(uf, array[i]);

        // Check database for additional validation
        char query[256];
        snprintf(query, sizeof(query), "SELECT tag FROM rnti_mapping WHERE rnti = %d", array[i]);

        rc = sqlite3_exec(db, query, NULL, 0, &errMsg);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "SQL error: %s\n", errMsg);
            sqlite3_free(errMsg);
            continue;
        }

        pthread_mutex_unlock(&lock);

        // Create PDU
        pdus[i].rnti = array[i];
        // Assign other fields like RX_UE_INFORMATION_TAG and CRC flag (randomly set)

        union_sets(uf, rnti_parent, i); // Example of merging sets if needed
    }

    pthread_mutex_destroy(&lock);
    return pdus;
}

int execute_command(const char* command) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE); // If exec fails
    } else if (pid > 0) {
        int status;
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    } else {
        perror("fork");
        return 0;
    }
}

int main(int argc, char** argv) {
    sqlite3 *db;
    rc = sqlite3_open("rnti_database.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return 1;
    }

    // Example input
    int rnti_array[] = {1001, 2002, 3003};
    size_t length = sizeof(rnti_array) / sizeof(rnti_array[0]);

    time_t start_time = clock();
    PDU* pdus = process_rnti_array(rnti_array, length, db);
    time_t end_time = clock();

    printf("Processing time: %ld ms\n", (end_time - start_time) * 1000 / CLOCKS_PER_SEC);

    execute_command("echo 'Executing command'");

    free(pdus);
    sqlite3_close(db);

    return 0;
}
