#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define maximum size constant
#define MAX_SIZE 1000

typedef struct {
    int value;
} record;

// Global mutex for thread safety
pthread_mutex_t lock;

void initialize_data(int max_size, long offsets[], int keys[], record records[]) {
    pthread_mutex_lock(&lock);

    // Validate and allocate memory with error checking
    if (max_size > MAX_SIZE) {
        fprintf(stderr, "Error: Maximum size exceeds allowed limit.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < max_size; ++i) {
        offsets[i] = rand() % 1000; // Example initialization
        keys[i] = rand() % 1000;    // Example initialization

        records[i].value = rand() % 100; // Random value within range [0, 99]
    }

    pthread_mutex_unlock(&lock);
}

void free_data(long offsets[], int keys[], record records[], int max_size) {
    pthread_mutex_lock(&lock);

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_unlock(&lock);
}

void update_record(int index, int new_value, record records[], int max_size) {
    if (index < 0 || index >= max_size) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    records[index].value = new_value;

    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for data structures with error handling
    long *offsets = malloc(MAX_SIZE * sizeof(long));
    int *keys = malloc(MAX_SIZE * sizeof(int));
    record *records = malloc(MAX_SIZE * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    // Initialize and use data structures
    initialize_data(MAX_SIZE, offsets, keys, records);

    // Example update to a record
    update_record(10, 42, records, MAX_SIZE); // Update index 10 with new value

    // Free allocated memory after usage
    free_data(offsets, keys, records, MAX_SIZE);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Mutex locks ensure that the data structures are safely accessed by multiple threads.
- **Error Handling**: Checks for allocation failures and index bounds to prevent crashes or undefined behavior.
- **Flexibility**: `MAX_SIZE` can be adjusted easily, while memory allocation checks prevent exceeding system limits.
- **Modularity**: Functions are defined to separate initialization, update, and cleanup logic, promoting maintainability.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RNTI 1000
#define MAX_UE_COUNT 1024

typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    uint32_t checksum;
    pthread_mutex_t lock;
} LinkedNodeList;

uint32_t get_random_uint32() {
    return rand() % MAX_RNTI + 1; // Random RNTI in range [1, MAX_RNTI]
}

bool is_rnti_repeated(int current_rnti, NFAPI_CRC_INDICATION_PDU_T* node) {
    while (node != NULL) {
        if (node->RNTI == current_rnti)
            return true;
        node = node->next;
    }
    return false;
}

void init_linked_node_list(LinkedNodeList* list) {
    list->head = NULL;
    list->checksum = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu(int tag, int rnti, uint8_t crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node)
        return NULL;

    new_node->RX_UE_INFORMATION_TAG = tag;
    new_node->RNTI = rnti;
    new_node->crc_tag.CRCFLAG = crc_flag;
    new_node->next = NULL;

    return new_node;
}

void append_nfaapi_crc_indication_pdu(LinkedNodeList* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current->next != NULL)
            current = current->next;

        current->next = node;
    }

    pthread_mutex_unlock(&list->lock);
}

void update_checksum(LinkedNodeList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    uint32_t new_checksum = (list->checksum + rnti) % 0xFFFFFFFF; // Simple checksum logic

    if (new_checksum <= MAX_RNTI)
        list->checksum = new_checksum;

    pthread_mutex_unlock(&list->lock);
}

void populate_linked_list(LinkedNodeList* list, int n) {
    for (int i = 0; i < n; ++i) {
        int tag = i;
        int rnti;
        uint8_t crc_flag = rand() % 2;

        do {
            rnti = get_random_uint32();
        } while (is_rnti_repeated(rnti, list->head));

        NFAPI_CRC_INDICATION_PDU_T* new_node = create_nfaapi_crc_indication_pdu(tag, rnti, crc_flag);

        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        append_nfaapi_crc_indication_pdu(list, new_node);

        update_checksum(list, rnti);
    }
}

void free_linked_list(LinkedNodeList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

void destroy_linked_node_list(LinkedNodeList* list) {
    if (list) {
        free_linked_list(list);
        pthread_mutex_destroy(&list->lock);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    LinkedNodeList nodeList;
    init_linked_node_list(&nodeList);

    populate_linked_list(&nodeList, MAX_UE_COUNT);

    destroy_linked_node_list(&nodeList);

    return 0;
}
```

This implementation provides a multi-thread-safe way to manage a dynamically populated linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. It ensures that no two consecutive nodes have the same RNTI and maintains a checksum across nodes, ensuring it doesn't exceed a threshold. The mutex lock is used to handle concurrency issues.']

