#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>

#define MAX_CACHE_ENTRIES 1000
#define CACHE_EXPIRY_TIME 300 // in seconds (5 minutes)
#define MAX_MEMORY_USAGE 1048576 // in bytes (1MB)

typedef struct {
    char hostname[256];
    u_char ip_address[16]; // Supports both IPv4 and IPv6 addresses
    time_t timestamp;
} DNSCacheEntry;

static DNSCacheEntry cache[MAX_CACHE_ENTRIES];
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long last_query_time_ns = 0;
static pthread_cond_t query_rate_limit = PTHREAD_COND_INITIALIZER;
static size_t current_cache_memory_usage = 0;
static const size_t max_ip_size = sizeof(struct in6_addr);

// Function to get the current time in nanoseconds
unsigned long long current_time_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (unsigned long long)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

// Rate limiting function
void rate_limit_queries() {
    pthread_mutex_lock(&cache_lock);
    while ((current_time_ns() - last_query_time_ns) < 100000000) { // 10 queries per second
        struct timespec wait_time;
        wait_time.tv_sec = (last_query_time_ns + 100000000 - current_time_ns()) / 1000000000;
        wait_time.tv_nsec = (last_query_time_ns + 100000000 - current_time_ns()) % 1000000000;
        pthread_cond_timedwait(&query_rate_limit, &cache_lock, &wait_time);
    }
    last_query_time_ns += 100000000;
    pthread_mutex_unlock(&cache_lock);
}

// Function to check if an entry is stale
int is_stale(DNSCacheEntry *entry) {
    return (time(NULL) - entry->timestamp > CACHE_EXPIRY_TIME);
}

// Caching functions
void add_to_cache(const char *hostname, const u_char *ip_address, size_t ip_size) {
    pthread_mutex_lock(&cache_lock);

    // Evict stale entries if necessary
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (is_stale(&cache[i])) {
            current_cache_memory_usage -= max_ip_size;
            memset(&cache[i], 0, sizeof(DNSCacheEntry));
        }
    }

    // Add new entry to cache
    int free_index = -1;
    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (current_cache_memory_usage + ip_size > MAX_MEMORY_USAGE) {
            // Evict the oldest entry to make room
            if (!is_stale(&cache[i])) {
                current_cache_memory_usage -= max_ip_size;
                memset(&cache[i], 0, sizeof(DNSCacheEntry));
                free_index = i;
            }
        } else if (strlen(cache[i].hostname) == 0) {
            free_index = i;
            break;
        }
    }

    if (free_index != -1) {
        strncpy(cache[free_index].hostname, hostname, sizeof(cache[free_index].hostname));
        memcpy(cache[free_index].ip_address, ip_address, ip_size);
        cache[free_index].timestamp = time(NULL);
        current_cache_memory_usage += ip_size;
    }

    pthread_mutex_unlock(&cache_lock);
}

u_char *get_from_cache(const char *hostname) {
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < MAX_CACHE_ENTRIES; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0 && !is_stale(&cache[i])) {
            u_char *ip_copy = malloc(max_ip_size);
            memcpy(ip_copy, cache[i].ip_address, max_ip_size);
            pthread_mutex_unlock(&cache_lock);
            return ip_copy;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// DNS resolution function
u_char *resolve_dns(const char *hostname, int timeout_seconds) {
    rate_limit_queries();

    u_char *cached_result = get_from_cache(hostname);
    if (cached_result != NULL) {
        return cached_result;
    }

    struct addrinfo hints, *res, *p;
    int rv;
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    // Set timeout for DNS resolution
    struct timeval tv;
    tv.tv_sec = timeout_seconds;
    tv.tv_usec = 0;
    setsockopt(0, SOL_SOCKET, SO_RCVTIMEO, (char *)&tv, sizeof(tv));

    if ((rv = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return NULL;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        char ipstr[INET6_ADDRSTRLEN];
        void *addr;

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            int ip_size = sizeof(struct in_addr);
            add_to_cache(hostname, (u_char *)addr, ip_size);
        } else if (p->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            int ip_size = sizeof(struct in6_addr);
            add_to_cache(hostname, (u_char *)addr, ip_size);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        printf("IP: %s\n", ipstr);
    }

    freeaddrinfo(res);

    cached_result = get_from_cache(hostname);
    if (cached_result != NULL) {
        return cached_result;
    }

    return NULL;
}

int main() {
    u_char *ip_address = resolve_dns("example.com", 5);
    if (ip_address != NULL) {
        // Use the resolved IP address
        free(ip_address);
    }
    return 0;
}
