        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX + 1;
        array[i].RNTI = rand() % UINT16_MAX + 1;
        array[i].crc_tag.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    return array;
}

// Function to free the allocated memory for the array of structures
void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

// Example integration into a data processing pipeline with periodic updates
void update_data_pipeline() {
    const size_t num_elements = 100; // Configurable number of structures
    NFAPI_CRC_INDICATION_PDU_T *data_array = NULL;

    while (1) { // Simulate periodic updates in an infinite loop
        free_crc_indication_pdu_array(data_array); // Free previous memory to prevent leaks

        data_array = create_crc_indication_pdu_array(num_elements);
        if (!data_array) {
            fprintf(stderr, "Failed to update data pipeline.\n");
            break;
        }

        // Simulate processing of the updated data
        for (size_t i = 0; i < num_elements; ++i) {
            printf("Processing PDU %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
                   i + 1,
                   data_array[i].RX_UE_INFORMATION_TAG,
                   data_array[i].RNTI,
                   data_array[i].crc_tag.CRCFLAG);
        }

        // Simulate delay between updates
        sleep(5); // Sleep for 5 seconds (adjust as needed)
    }
}

int main() {
