} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->capacity = initial_capacity;
    da->size = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        return -1;
    }
    da->capacity = new_capacity;
    return 0;
}

void add_crc_indication_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        if (resize_dynamic_array(da) != 0) {
            perror("Failed to resize array");
            pthread_mutex_unlock(&da->lock);
            return;
        }
    }
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);
}

void update_crc_indication_pdu(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (index >= da->size) return;
    pthread_mutex_lock(&da->lock);
    da->array[index] = pdu;
    pthread_mutex_unlock(&da->lock);
}

void delete_crc_indication_pdu(DynamicArray *da, size_t index) {
    if (index >= da->size) return;
    pthread_mutex_lock(&da->lock);
    memmove(&da->array[index], &da->array[index + 1], (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size--;
    pthread_mutex_unlock(&da->lock);
}

void monitor_memory_usage(DynamicArray *da) {
    size_t memory_used = da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    printf("Memory used: %zu bytes\n", memory_used);
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da, 4);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, {.CRCFLAG = rand() % 2}};
    add_crc_indication_pdu(&da, pdu);

    monitor_memory_usage(&da);

    free_dynamic_array(&da);
    return 0;
}
