// Configuration structure
typedef struct {
    int random_seed;
    bool enable_logging;
} Config;

Config config = {42, false}; // Default configuration

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Memory pool for efficient allocation (simple implementation)
#define POOL_SIZE 1024 * 10 // Example size
uint8_t memory_pool[POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* pool_alloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[pool_offset];
    pool_offset += size;
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void free_pool() {
    pthread_mutex_lock(&pool_mutex);
    pool_offset = 0;
    pthread_mutex_unlock(&pool_mutex);
}

// Logging function
void log_message(const char* message) {
    if (config.enable_logging) {
        printf("%s\n", message);
    }
}

// Load configuration from file or command-line arguments
void load_config(const char* config_file, int argc, char* argv[]) {
    // Example: Read from a simple text file or override with args
    FILE* file = fopen(config_file, "r");
    if (file) {
        fscanf(file, "%d %d", &config.random_seed, &config.enable_logging);
        fclose(file);
    } else {
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "--seed") == 0 && i + 1 < argc) config.random_seed = atoi(argv[++i]);
            if (strcmp(argv[i], "--log") == 0) config.enable_logging = true;
        }
    }

    log_message("Configuration loaded.");
}

// Pseudo-random number generator
uint16_t pseudo_random(uint16_t max_value, uint32_t* seed) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return (uint16_t)(*seed % max_value);
}

void generate_nfa_pi_list(int N, NFAPI_CRC_INDICATION_PDU_T** list) {
    pthread_mutex_lock(&mutex);

    uint32_t seed = config.random_seed;
    uint16_t used_rntis[65536] = {0};
    *list = (NFAPI_CRC_INDICATION_PDU_T*)pool_alloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (int i = 0; i < N; ++i) {
        uint16_t rnti;
        do {
            rnti = pseudo_random(65535, &seed) + 1;
        } while (used_rntis[rnti]);

        used_rntis[rnti] = 1;

        (*list)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*list)[i].RNTI = rnti;
        (*list)[i].CRC_INDICATION_REL8_TAG = (uint8_t)pseudo_random(256, &seed);
        (*list)[i].CRCFLAG = pseudo_random(2, &seed) == 0;

        log_message("Generated NFAPI_CRC_INDICATION_PDU_T structure.");
    }

    pthread_mutex_unlock(&mutex);
}

void free_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        pool_alloc(0); // Free by resetting the offset
    }
}

// Example usage
int main(int argc, char* argv[]) {
    load_config("config.txt", argc, argv);

    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T* list;

    generate_nfa_pi_list(N, &list);

    // Use the list...

    free_nfa_pi_list(list);
    free_pool();

    return 0;
}
