import <pthread.h>
import <string.h>

typedef struct {
    char MAC_Address[18];
    char IP_Address[16];
    int LinkStatus; // 1 for up, 0 for down
} NetworkInterfaceStatus;

#define MAX_INTERFACES 50
#define CONCURRENT_CHECKS 10

// Mock functions to simulate network interface status checking
void getMACAddress(int index, char* mac) {
    sprintf(mac, "00:11:22:33:%02x:%02x", index, (index + 1) % 256);
}

int getIPStatus(int index) {
    return (index % 3 == 0); // Simulate some interfaces down
}

char* getIPAddress(int index) {
    static char ip[16];
    if (getIPStatus(index)) {
        sprintf(ip, "192.168.1.%d", index + 1);
        return ip;
    }
    return NULL;
}

typedef struct {
    int index;
    NetworkInterfaceStatus *statusArray;
} ThreadData;

void* checkInterface(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    char mac[18];
    getMACAddress(data->index, mac);
    strcpy(data->statusArray[data->index].MAC_Address, mac);

    if (getIPStatus(data->index)) {
        data->statusArray[data->index].LinkStatus = 1;
        strncpy(data->statusArray[data->index].IP_Address, getIPAddress(data->index), sizeof(data->statusArray[data->index].IP_Address) - 1);
    } else {
        data->statusArray[data->index].LinkStatus = 0;
        strcpy(data->statusArray[data->index].IP_Address, "Unavailable");
    }

    return NULL;
}

NetworkInterfaceStatus* initializeNetworkInterfaces(int *count) {
    if (*count > MAX_INTERFACES) *count = MAX_INTERFACES;

    NetworkInterfaceStatus *interfaces = (NetworkInterfaceStatus*)malloc(*count * sizeof(NetworkInterfaceStatus));
    if (!interfaces) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_t threads[CONCURRENT_CHECKS];
    ThreadData threadData[*count];

    for (int i = 0; i < *count; ++i) {
        threadData[i].index = i;
        threadData[i].statusArray = interfaces;

        int threadIndex = i % CONCURRENT_CHECKS;
        if (pthread_create(&threads[threadIndex], NULL, checkInterface, &threadData[i]) != 0) {
            fprintf(stderr, "Failed to create thread for interface %d\n", i);
            free(interfaces);
            return NULL;
        }

        // Join threads in batches of CONCURRENT_CHECKS
        if ((i + 1) % CONCURRENT_CHECKS == 0 || i == *count - 1) {
            for (int j = 0; j < CONCURRENT_CHECKS && (i - j + 1) >= 0; ++j) {
                int indexToJoin = i - j;
                pthread_join(threads[indexToJoin % CONCURRENT_CHECKS], NULL);
            }
        }
    }

    return interfaces;
}

void freeNetworkInterfaces(NetworkInterfaceStatus* interfaces) {
    if (interfaces) {
        free(interfaces);
    }
}

int main() {
    int count = 15; // Assume we have 15 network interfaces
    NetworkInterfaceStatus *networkInterfaces = initializeNetworkInterfaces(&count);

    if (!networkInterfaces) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < count; ++i) {
        printf("Interface %d: MAC=%s, IP=%s, Status=%s\n", 
            i, networkInterfaces[i].MAC_Address,
            networkInterfaces[i].IP_Address,
            networkInterfaces[i].LinkStatus ? "Up" : "Down");
    }

    freeNetworkInterfaces(networkInterfaces);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Concurrency**: Uses pthreads to handle up to 10 interface checks concurrently.
- **Error Handling**: Checks for memory allocation and thread creation failures, providing feedback via `stderr`.
- **Scalability**: Handles systems with up to 50 interfaces by limiting checks and reusing resources efficiently.
- **Memory Management**: Frees dynamically allocated memory after use.']

