typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int is_rnti_unique(Node* head, unsigned int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.ue_info.RNTI == rnti) {
            return 0; // RNTI not unique
        }
        current = current->next;
    }
    return 1; // RNTI is unique
}

void log_allocation_failure(size_t size) {
    printf("Memory allocation failure for size: %zu\n", size);
}

Node* create_list(int list_size) {
    Node* head = NULL;
    Node* tail = NULL;
    pthread_mutex_lock(&list_mutex);

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < list_size; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            log_allocation_failure(sizeof(Node));
            while (head != NULL) { // Free all allocated nodes
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        unsigned int rnti;
        do {
            rnti = rand() % 0xFFFFFFFF; // Generate random RNTI
        } while (!is_rnti_unique(head, rnti));

        new_node->data.ue_info.RNTI = rnti;
        new_node->data.ue_info.crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        new_node->next = NULL;

        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }
        tail = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
    return head;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    int list_size = 100; // Configurable at runtime
    Node* nfa_list = create_list(list_size);

    if (!nfa_list) {
        printf("Failed to create NFAPI CRC Indication PDU list.\n");
        return -1;
    }

    // Use the list...

    free_list(nfa_list);
    return 0;
}
