#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Vertex {
    int RNTI;
    int CRCFLAG;
    struct Vertex* edges[10]; // assuming max 10 connections per vertex
} Vertex;

typedef struct Graph {
    Vertex** vertices;
    size_t num_vertices;
    size_t capacity;
} Graph;

Graph* create_graph(size_t initial_capacity) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->vertices = (Vertex**)malloc(initial_capacity * sizeof(Vertex*));
    graph->num_vertices = 0;
    graph->capacity = initial_capacity;
    return graph;
}

void resize_graph_if_needed(Graph* graph) {
    if (graph->num_vertices >= graph->capacity) {
        size_t new_capacity = graph->capacity * 2;
        Vertex** new_vertices = (Vertex**)realloc(graph->vertices, new_capacity * sizeof(Vertex*));
        if (new_vertices) {
            graph->vertices = new_vertices;
            graph->capacity = new_capacity;
        } else {
            fprintf(stderr, "Failed to resize graph\n");
            exit(EXIT_FAILURE);
        }
    }
}

void add_vertex(Graph* graph, int rnti, int crcflag) {
    resize_graph_if_needed(graph);
    Vertex* vertex = (Vertex*)malloc(sizeof(Vertex));
    if (!vertex) {
        fprintf(stderr, "Failed to allocate memory for vertex\n");
        exit(EXIT_FAILURE);
    }
    vertex->RNTI = rnti;
    vertex->CRCFLAG = crcflag;
    for (int i = 0; i < 10; ++i) {
        vertex->edges[i] = NULL;
    }
    graph->vertices[graph->num_vertices++] = vertex;
}

void add_edge(Vertex* from, Vertex* to) {
    for (int i = 0; i < 10; ++i) {
        if (!from->edges[i]) {
            from->edges[i] = to;
            break;
        }
    }
}

void free_graph(Graph* graph) {
    for (size_t i = 0; i < graph->num_vertices; ++i) {
        Vertex* vertex = graph->vertices[i];
        free(vertex);
    }
    free(graph->vertices);
    free(graph);
}

void log_operation(const char* operation, int rnti) {
#ifdef ENABLE_LOGGING
    printf("Operation: %s, RNTI: %d\n", operation, rnti);
#endif
}

void generate_structures_and_graph(size_t num_pdu, size_t num_vertices, size_t num_edges) {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for PDUs\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_pdu; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 10000;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdus[i].CRCFLAG = rand() % 2;
    }

    Graph* graph = create_graph(num_vertices);

    for (size_t i = 0; i < num_vertices; ++i) {
        int rnti = rand() % 10000;
        int crcflag = rand() % 2;
        add_vertex(graph, rnti, crcflag);
        log_operation("Add Vertex", rnti);
    }

    for (size_t i = 0; i < num_edges; ++i) {
        size_t from_idx = rand() % graph->num_vertices;
        size_t to_idx = rand() % graph->num_vertices;
        if (from_idx != to_idx) {
            add_edge(graph->vertices[from_idx], graph->vertices[to_idx]);
            log_operation("Add Edge", graph->vertices[from_idx]->RNTI);
        }
    }

    free(pdus);
    free_graph(graph);
}

int main() {
    generate_structures_and_graph(100, 50, 75);
    return 0;
}
