} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int valid; // Indicates if RX_UE_INFORMATION_TAG is valid
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFListManager;

// Memory pool for efficient allocation
static void *memory_pool[MEMORY_POOL_SIZE];
static int memory_pool_index = 0;

void initialize_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    if (memory_pool_index >= MEMORY_POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    return (NFAPI_CRC_INDICATION_PDU_T*)memory_pool[memory_pool_index++];
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (memory_pool_index > 0) {
        memory_pool[--memory_pool_index] = node;
    } else {
        free(node);
    }
}

// Logging function
void log_operation(const char *message) {
#ifdef LOG_VERBOSITY_LEVEL
    printf("%s\n", message);
#endif
}

// Initialize the NFListManager
NFListManager* initialize_manager() {
    NFListManager *manager = (NFListManager*)malloc(sizeof(NFListManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new structure
int add_structure(NFListManager *manager, unsigned long rnti) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate RNTI
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current) {
        if (current->rnti == rnti) {
            log_operation("Failed to add: Duplicate RNTI");
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate RNTI
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = allocate_structure();
    if (!new_node) {
        log_operation("Failed to add: Memory allocation failed");
        pthread_mutex_unlock(&manager->lock);
        return -2; // Allocation failure
    }
    new_node->rnti = rnti;
    new_node->valid = 1; // Assume valid for simplicity
    new_node->tag.crcflag = rand() % 2; // Random CRCFLAG

    new_node->next = manager->head;
    manager->head = new_node;

    log_operation("Structure added successfully");
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update an existing structure
int update_structure(NFListManager *manager, unsigned long rnti) {
    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current) {
        if (current->rnti == rnti) {
            current->tag.crcflag = rand() % 2; // Random CRCFLAG
            log_operation("Structure updated successfully");
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = current->next;
    }

    log_operation("Failed to update: RNTI not found");
    pthread_mutex_unlock(&manager->lock);
    return -1; // RNTI not found
}

// Remove a structure by RNTI
int remove_structure(NFListManager *manager, unsigned long rnti) {
    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T **current = &manager->head;
    while (*current) {
        if ((*current)->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *to_delete = *current;
            *current = (*current)->next;
            deallocate_structure(to_delete);
            log_operation("Structure removed successfully");
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    log_operation("Failed to remove: RNTI not found");
    pthread_mutex_unlock(&manager->lock);
    return -1; // RNTI not found
}

// Cleanup unused memory based on a threshold
void cleanup_memory(NFListManager *manager, int threshold_percentage) {
    pthread_mutex_lock(&manager->lock);

    int current_usage = MEMORY_POOL_SIZE - memory_pool_index;
    int usage_threshold = (MEMORY_POOL_SIZE * threshold_percentage) / 100;

    if (current_usage <= usage_threshold) {
        NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
        while (current && memory_pool_index < MEMORY_POOL_SIZE) {
            NFAPI_CRC_INDICATION_PDU_T *to_delete = current;
            current = current->next;
            deallocate_structure(to_delete);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Simulate periodic updates from an external data source
void* periodic_update(void *arg) {
    NFListManager *manager = (NFListManager*)arg;

    while (1) {
        // Simulate delay
        sleep(5);

        // Placeholder for actual update logic
        log_operation("Simulated external update");

        pthread_mutex_lock(&manager->lock);
        // Example: Remove a random RNTI to simulate updates
        if (manager->head) {
            remove_structure(manager, manager->head->rnti);
        }
        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    initialize_memory_pool();

    NFListManager *manager = initialize_manager();

    // Example usage
