} Vertex;

// Define a graph structure
typedef struct Graph {
    Vertex** vertices;
    size_t capacity;
    size_t size;
} Graph;

// Function prototypes
Graph* create_graph(size_t initial_capacity);
void add_vertex(Graph* graph, unsigned int rnti, bool crcflag);
Vertex* find_vertex(Graph* graph, unsigned int rnti);
void free_graph(Graph* graph);
void log_operation(const char* operation);

NFAPI_CRC_INDICATION_PDU_T* populate_nfa_pi_list(size_t num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed for pdu_list");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));  // Seed random number generator

    Graph* graph = create_graph(10);  // Initial capacity of the graph
    log_operation("Graph created");

    for (size_t i = 0; i < num_pdus; ++i) {
        unsigned int rnti = rand() % 10000 + 1;  // Random RNTI between 1 and 10000
        bool crcflag = rand() % 2 == 0;

        RX_UE_INFORMATION_TAG rx_info_tag = {rnti, (unsigned short)(rand() % 4)};

        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .rx_ue_information_tag = rx_info_tag,
            .rnti = rnti,
            .crc_indication_rel8_tag = rand() % 256,
            .crcflag = crcflag
        };

        add_vertex(graph, rnti, crcflag);

        pdu_list[i] = pdu;
    }

    free_graph(graph);
    log_operation("Graph freed");

    return pdu_list;
}

Graph* create_graph(size_t initial_capacity) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) {
        perror("Memory allocation failed for graph");
        exit(EXIT_FAILURE);
    }
    graph->capacity = initial_capacity;
    graph->size = 0;
    graph->vertices = (Vertex**)calloc(initial_capacity, sizeof(Vertex*));
    if (!graph->vertices) {
        free(graph);
        perror("Memory allocation failed for vertices array");
        exit(EXIT_FAILURE);
    }
    return graph;
}

void add_vertex(Graph* graph, unsigned int rnti, bool crcflag) {
    Vertex* existing = find_vertex(graph, rnti);
    if (existing) {
        existing->crcflag = crcflag;  // Update CRCFLAG if vertex exists
        log_operation("Vertex updated");
        return;
    }

    if (graph->size == graph->capacity) {
        size_t new_capacity = graph->capacity * 2;
        Vertex** new_vertices = (Vertex**)realloc(graph->vertices, new_capacity * sizeof(Vertex*));
        if (!new_vertices) {
            perror("Memory reallocation failed for vertices array");
            free_graph(graph);
            exit(EXIT_FAILURE);
        }
        graph->vertices = new_vertices;
        graph->capacity = new_capacity;
        log_operation("Graph capacity increased");
    }

    Vertex* vertex = (Vertex*)malloc(sizeof(Vertex));
    if (!vertex) {
        perror("Memory allocation failed for vertex");
        free_graph(graph);
        exit(EXIT_FAILURE);
    }
    vertex->rnti = rnti;
    vertex->crcflag = crcflag;
    vertex->next = NULL;

    graph->vertices[graph->size++] = vertex;
    log_operation("Vertex added");
}

Vertex* find_vertex(Graph* graph, unsigned int rnti) {
    for (size_t i = 0; i < graph->size; ++i) {
        if (graph->vertices[i]->rnti == rnti) {
            return graph->vertices[i];
        }
    }
    return NULL;
}

void free_graph(Graph* graph) {
    for (size_t i = 0; i < graph->size; ++i) {
        free(graph->vertices[i]);
    }
    free(graph->vertices);
    free(graph);
}

void log_operation(const char* operation) {
    // Simple logging mechanism
    printf("LOG: %s\n", operation);
}
