// Function to initialize and populate messages concurrently
void *initialize_messages(void *arg) {
    int start = *(int *)arg;
    LTEPHY_TRANSPORT_LAYER_MESSAGE *messages = malloc(MAX_MESSAGES * sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));

    if (!messages) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < MAX_MESSAGES; ++i) {
        int interface_id = start + i % MAX_INTERFACES;

        if (!is_interface_available(interface_id)) {
            printf("Interface %d unavailable\n", interface_id);
            continue;
        }

        char ip_address[16];
        if (!resolve_ip_address(interface_id, ip_address)) {
            printf("Failed to resolve IP for interface %d\n", interface_id);
            continue;
        }

        LTEPHY_TRANSPORT_LAYER_MESSAGE *msg = &messages[i];
        msg->config.lcg_config = rand() % 256; // Example LCG_CONFIG value
        msg->rrc_info.interface_id = interface_id;
        strcpy(msg->rrc_info.ip_address, ip_address);
        msg->qfi = rand() % 64; // QoS Flow Identifier range example: 0-63
        msg->pdu_size = (rand() % MAX_PDU_SIZE) + 1;

        printf("Initialized message %d for interface %d with IP %s\n", i, interface_id, ip_address);
    }

    free(messages);
    return NULL;
}

void initialize_transport_layer_messages_concurrently() {
    pthread_t threads[MAX_MESSAGES];

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < MAX_MESSAGES; ++i) {
        int *start_id = malloc(sizeof(int));
        if (!start_id) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }

        *start_id = i;
        pthread_create(&threads[i], NULL, initialize_messages, (void *)start_id);
    }

    for (int i = 0; i < MAX_MESSAGES; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initialize_transport_layer_messages_concurrently();
    return 0;
}
