// Function to initialize the network device configurations
NetworkDeviceConfig* initialize_device_configs(int device_count) {
    if (device_count > MAX_DEVICES) {
        fprintf(stderr, "Exceeded maximum device limit.\n");
        return NULL;
    }

    NetworkDeviceConfig *configs = malloc(device_count * sizeof(NetworkDeviceConfig));
    if (!configs) {
        perror("Failed to allocate memory for devices");
        return NULL;
    }

    for (int i = 0; i < device_count; ++i) {
        // Initialize IP address, subnet mask and gateway with random valid values
        char ip[INET_ADDRSTRLEN], subnet[INET_ADDRSTRLEN], gw[INET_ADDRSTRLEN];

        if (!network_utils_generate_random_ip(ip)) {
            fprintf(stderr, "Failed to generate random IP for device %d\n", i);
            free_device_configs(configs, i);
            return NULL;
        }
        strcpy(configs[i].ip_address, ip);

        if (!network_utils_generate_valid_subnet(subnet)) {
            fprintf(stderr, "Failed to generate valid subnet for device %d\n", i);
            free_device_configs(configs, i + 1);
            return NULL;
        }
        strcpy(configs[i].subnet_mask, subnet);

        if (!network_utils_generate_random_gateway(gw)) {
            fprintf(stderr, "Failed to generate random gateway for device %d\n", i);
            free_device_configs(configs, i + 1);
            return NULL;
        }
        strcpy(configs[i].gateway, gw);

        // Initialize services with random values
        configs[i].service_count = rand() % (SERVICE_LIMIT + 1);
        for (int j = 0; j < configs[i].service_count; ++j) {
            configs[i].services[j].port = random_valid_port();
            configs[i].services[j].protocol = random_protocol_type();
        }
    }

    return configs;
}

// Function to free allocated device configurations
void free_device_configs(NetworkDeviceConfig* configs, int device_count) {
    if (configs) {
        free(configs);
    }
}

// Helper function to generate a random valid port number
int random_valid_port() {
    return rand() % 65535 + 1; // Random port between 1 and 65535
}

// Helper function to randomly select a protocol type
ProtocolType random_protocol_type() {
    return (rand() % 2) ? PROTOCOL_TCP : PROTOCOL_UDP;
}
