        return -1;
    }

    *list = NULL;
    uint16_t* rnti_set = calloc(n, sizeof(uint16_t));
    if (!rnti_set) {
        logger("Memory allocation failed for RNTI set");
        return -2;
    }

    pthread_mutex_lock(&mutex);
    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        logger("Memory allocation failed for list");
        free(rnti_set);
        pthread_mutex_unlock(&mutex);
        return -3;
