    pthread_mutex_unlock(&mutex);

    for (size_t i = 0; i < n; ++i) {
        uint16_t rnti;
        int is_unique;
        do {
            rnti = rand() % MAX_LIST_SIZE;
            is_unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if ((*list)[j].RNTI == rnti) {
                    is_unique = 0;
                    break;
                }
