    bool rntiSet[65536] = {false}; // Assuming RNTI is 16-bit
    srand(time(NULL));

    for (size_t i = 0; i < max_list_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            // Log allocation failure and clean up
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        unsigned short rnti;
        do {
            rnti = rand() % 65536;
        } while (rntiSet[rnti]);

        newData->RX_UE_INFORMATION_TAG = rand();
        newData->RNTI = rnti;
        newData->crcTag.CRCFLAG = rand() % 2;

        *current = malloc(sizeof(Node));
        if (!*current) {
            free(newData);
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        (*current)->data = *newData;
        (*current)->next = NULL;
        current = &(*current)->next;

        rntiSet[rnti] = true;
    }

    pthread_mutex_unlock(&listMutex);
    return head;
}
