#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_TIMEOUT_MS 5000 // Maximum timeout in milliseconds

typedef struct {
    int pdcpsn;
    char* pdcpSdu; // Assume it's a dynamically allocated string for simplicity
    time_t timerInfo; // Timestamp when the entry was added/updated
} DL_DATA_PDU;

typedef struct Node {
    DL_DATA_PDU data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DLPDUTable;

void log_message(const char* message) {
    // Simple logging function, you might want to expand it
    printf("%s\n", message);
}

DL_DATA_PDU* create_dl_data_pdu(int sn, const char* sdu) {
    DL_DATA_PDU* pdu = (DL_DATA_PDU*)malloc(sizeof(DL_DATA_PDU));
    if (!pdu) return NULL;

    pdu->pdcpsn = sn;
    pdu->pdcpSdu = strdup(sdu);
    if (!pdu->pdcpSdu) {
        free(pdu);
        return NULL;
    }

    pdu->timerInfo = time(NULL);

    return pdu;
}

void cleanup_expired_entries(DLPDUTable* table, long timeout_ms) {
    pthread_mutex_lock(&table->lock);

    Node *current = table->head, *prev = NULL;
    time_t now = time(NULL);
    while (current != NULL) {
        if ((now - current->data.timerInfo) * 1000 > timeout_ms) {
            log_message("Removing expired entry with PDCP SN: ");
            printf("%d\n", current->data.pdcpsn);

            Node* toDelete = current;
            if (prev == NULL) { // Remove from head
                table->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;

            free(toDelete->data.pdcpSdu);
            free(toDelete);

        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

int add_dl_data_pdu(DLPDUTable* table, int sn, const char* sdu) {
    pthread_mutex_lock(&table->lock);

    Node* current = table->head;
    while (current != NULL) {
        if (current->data.pdcpsn == sn) {
            log_message("Attempt to add duplicate PDCP SN: ");
            printf("%d\n", sn);
            pthread_mutex_unlock(&table->lock);
            return -1; // Duplicate
        }
        current = current->next;
    }

    DL_DATA_PDU* new_pdu = create_dl_data_pdu(sn, sdu);
    if (!new_pdu) {
        log_message("Failed to allocate memory for new PDCP SN: ");
        printf("%d\n", sn);
        pthread_mutex_unlock(&table->lock);
        return -2; // Memory allocation failed
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        free(new_pdu);
        log_message("Failed to allocate memory for new node");
        pthread_mutex_unlock(&table->lock);
        return -3;
    }

    newNode->data = *new_pdu;
    newNode->next = table->head;
    table->head = newNode;

    log_message("Added PDCP SN: ");
    printf("%d\n", sn);

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

int update_dl_data_pdu(DLPDUTable* table, int sn, const char* sdu) {
    pthread_mutex_lock(&table->lock);

    Node* current = table->head;
    while (current != NULL) {
        if (current->data.pdcpsn == sn) {
            free(current->data.pdcpSdu);
            current->data.pdcpSdu = strdup(sdu);
            if (!current->data.pdcpSdu) {
                log_message("Failed to update PDCP SN: ");
                printf("%d\n", sn);
                pthread_mutex_unlock(&table->lock);
                return -1; // Memory allocation failed
            }

            current->data.timerInfo = time(NULL);

            log_message("Updated PDCP SN: ");
            printf("%d\n", sn);

            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        current = current->next;
    }

    log_message("Attempt to update non-existent PDCP SN: ");
    printf("%d\n", sn);

    pthread_mutex_unlock(&table->lock);
    return -1; // Not found
}

int remove_dl_data_pdu(DLPDUTable* table, int sn) {
    pthread_mutex_lock(&table->lock);

    Node *current = table->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.pdcpsn == sn) {
            if (prev == NULL) { // Remove from head
                table->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current->data.pdcpSdu);
            free(current);

            log_message("Removed PDCP SN: ");
            printf("%d\n", sn);

            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    log_message("Attempt to remove non-existent PDCP SN: ");
    printf("%d\n", sn);

    pthread_mutex_unlock(&table->lock);
    return -1; // Not found
}

void init_dl_data_pdu_table(DLPDUTable* table) {
    table->head = NULL;
    if (pthread_mutex_init(&table->lock, NULL) != 0) {
        log_message("Mutex init failed\n");
        exit(1); // Exit on critical error
    }
}

void destroy_dl_data_pdu_table(DLPDUTable* table) {
    pthread_mutex_lock(&table->lock);

    Node *current = table->head;
    while (current != NULL) {
        Node* toDelete = current;
        current = current->next;

        free(toDelete->data.pdcpSdu);
        free(toDelete);
    }

    table->head = NULL;
    pthread_mutex_unlock(&table->lock);

    if (pthread_mutex_destroy(&table->lock) != 0) {
        log_message("Mutex destroy failed\n");
    }
}

void* cleanup_thread_func(void* arg) {
    DLPDUTable* table = (DLPDUTable*)arg;

    while (1) {
        sleep(1); // Sleep for a second
        cleanup_expired_entries(table, MAX_TIMEOUT_MS);
    }

    return NULL;
}

int main() {
    DLPDUTable table;
    init_dl_data_pdu_table(&table);

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_thread_func, &table) != 0) {
        log_message("Failed to create cleanup thread");
        destroy_dl_data_pdu_table(&table);
        exit(1);
    }

    // Example usage
    add_dl_data_pdu(&table, 1, "Packet 1 data");
    update_dl_data_pdu(&table, 1, "Updated Packet 1 data");

    sleep(6); // Wait to allow cleanup

    remove_dl_data_pdu(&table, 1);

    destroy_dl_data_pdu_table(&table);

    pthread_cancel(cleanup_thread);
    pthread_join(cleanup_thread, NULL);

    return 0;
}
```

This implementation creates a dynamic list of LTE DL DATA PDU structures with thread-safe operations. It uses a mutex to ensure that only one thread can modify the list at a time, preventing data races. The `cleanup_expired_entries` function is executed by a separate thread in an infinite loop, periodically checking for and removing expired entries based on their timestamps.

The code includes logging statements for each operation to help with debugging and monitoring. Error handling is implemented for situations like duplicate PDCP SNs or non-existent entries being updated or removed. Memory management is handled carefully, ensuring that allocated memory is freed appropriately to avoid leaks. 

To run this example effectively, it's essential to compile it with a C compiler supporting pthreads (e.g., gcc with the `-pthread` flag). This code offers a basic framework and can be extended or modified to fit more specific requirements, such as adjusting the timeout threshold dynamically based on network conditions or adding more sophisticated logging mechanisms.']

