#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MEMORY_POOL_SIZE 1024

typedef struct {
    int valid;
    unsigned long RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    unsigned long RNTI;
    int CRCFLAG;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

typedef struct MemoryPool {
    size_t size;
    void* pool;
    void** free_list;
    pthread_mutex_t lock;
} MemoryPool;

// Memory Pool Functions
void initMemoryPool(MemoryPool* mp, size_t elementSize, int numElements) {
    mp->size = elementSize * numElements;
    mp->pool = malloc(mp->size);
    mp->free_list = (void**)malloc(numElements * sizeof(void*));
    pthread_mutex_init(&mp->lock, NULL);

    for (int i = 0; i < numElements - 1; ++i) {
        mp->free_list[i] = (char*)mp->pool + (i + 1) * elementSize;
    }
    mp->free_list[numElements - 1] = NULL;

    mp->free_list[0] = mp->pool;
}

void* allocateFromPool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    void* ptr = mp->free_list[0];
    if (ptr != NULL) {
        mp->free_list[0] = *(void**)ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void deallocateToPool(MemoryPool* mp, void* ptr) {
    pthread_mutex_lock(&mp->lock);
    *(void**)ptr = mp->free_list[0];
    mp->free_list[0] = ptr;
    pthread_mutex_unlock(&mp->lock);
}

void initList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* findNodeByRNTI(List* list, unsigned long rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void addOrUpdateNode(List* list, NFAPI_CRC_INDICATION_PDU_T pduData, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Node* node = findNodeByRNTI(list, rnti);
    if (node != NULL) {
        node->data = pduData;
        node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else {
        Node* newNode = (Node*)allocateFromPool(&memoryPool);
        newNode->data = pduData;
        newNode->RNTI = rnti;
        newNode->CRCFLAG = rand() % 2;
        newNode->next = list->head;
        list->head = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void removeNodeByRNTI(List* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            deallocateToPool(&memoryPool, current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanupMemoryIfNecessary(List* list) {
    // Implement a configurable threshold check and cleanup logic
}

// Main Function for Demonstration
int main() {
    List nfaList;
    initList(&nfaList);

    MemoryPool memoryPool;
    initMemoryPool(&memoryPool, sizeof(Node), MEMORY_POOL_SIZE);

    NFAPI_CRC_INDICATION_PDU_T pduData = {1, 12345678};
    addOrUpdateNode(&nfaList, pduData, 1001);
    removeNodeByRNTI(&nfaList, 1001);

    return 0;
}
