#include <time.h>

typedef struct {
    int measurementReportTag;
    int cellID;
    int signalStrength;
    time_t timestamp;
} LTE_PHY_Report;

#define MAX_REPORTS 1000

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    LTE_PHY_Report *reports;
    size_t count;
} ReportList;

void init_report_list(ReportList *list) {
    list->reports = malloc(sizeof(LTE_PHY_Report) * MAX_REPORTS);
    if (!list->reports) exit(EXIT_FAILURE);
    list->count = 0;
}

void add_report(ReportList *list, LTE_PHY_Report report) {
    pthread_mutex_lock(&lock);

    if (list->count < MAX_REPORTS) {
        list->reports[list->count++] = report;
    }

    pthread_mutex_unlock(&lock);
}

void clear_old_reports(ReportList *list, int age_threshold_sec) {
    time_t now = time(NULL);

    pthread_mutex_lock(&lock);

    size_t new_count = 0;

    for (size_t i = 0; i < list->count; ++i) {
        if ((now - list->reports[i].timestamp) <= age_threshold_sec) {
            list->reports[new_count++] = list->reports[i];
        }
    }

    list->count = new_count;

    pthread_mutex_unlock(&lock);
}

void serialize_report_list(const ReportList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->reports, sizeof(LTE_PHY_Report), list->count, file);

    fclose(file);
}

void deserialize_report_list(ReportList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fread(&list->count, sizeof(size_t), 1, file);
    list->reports = realloc(list->reports, list->count * sizeof(LTE_PHY_Report));
    fread(list->reports, sizeof(LTE_PHY_Report), list->count, file);

    fclose(file);
}

void free_report_list(ReportList *list) {
    free(list->reports);
    list->reports = NULL;
    list->count = 0;
}

// Example usage function
int main() {
    ReportList list;
    init_report_list(&list);

    LTE_PHY_Report report = {1, 1001, -70, time(NULL)};
    add_report(&list, report);

    clear_old_reports(&list, 60); // Clear entries older than 60 seconds

    serialize_report_list(&list, "reports.dat");
    free_report_list(&list);

    init_report_list(&list);
    deserialize_report_list(&list, "reports.dat");

    free_report_list(&list);
    return 0;
}
