#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define structures for NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, and RNTI
typedef struct {
    // Example fields; adjust as needed
    int rnti;
    char signal_strength[10];
    time_t timestamp;
} Vertex;

typedef struct Edge {
    int target_rnti;
    int bandwidth;
    int latency;
    struct Edge* next;
} Edge;

typedef struct Graph {
    Vertex** vertices;
    size_t vertex_count;
    pthread_mutex_t lock;
} Graph;

Graph* create_graph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->vertices = NULL;
    graph->vertex_count = 0;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void add_vertex(Graph* graph, int rnti, const char* signal_strength) {
    pthread_mutex_lock(&graph->lock);

    // Check if vertex already exists
    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i]->rnti == rnti) {
            pthread_mutex_unlock(&graph->lock);
            return;
        }
    }

    Vertex* new_vertex = (Vertex*)malloc(sizeof(Vertex));
    new_vertex->rnti = rnti;
    strncpy(new_vertex->signal_strength, signal_strength, sizeof(new_vertex->signal_strength));
    time(&(new_vertex->timestamp));

    graph->vertices = (Vertex**)realloc(graph->vertices, sizeof(Vertex*) * (graph->vertex_count + 1));
    graph->vertices[graph->vertex_count++] = new_vertex;

    pthread_mutex_unlock(&graph->lock);
}

void remove_vertex(Graph* graph, int rnti) {
    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i]->rnti == rnti) {
            free(graph->vertices[i]);
            memmove(&graph->vertices[i], &graph->vertices[i + 1],
                    sizeof(Vertex*) * (graph->vertex_count - i - 1));
            graph->vertex_count--;
            break;
        }
    }

    pthread_mutex_unlock(&graph->lock);
}

void add_edge(Graph* graph, int source_rnti, int target_rnti, int bandwidth, int latency) {
    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i]->rnti == source_rnti) {
            Edge* new_edge = (Edge*)malloc(sizeof(Edge));
            new_edge->target_rnti = target_rnti;
            new_edge->bandwidth = bandwidth;
            new_edge->latency = latency;
            new_edge->next = graph->vertices[i]->next_edge; // Assuming next_edge points to the first edge
            graph->vertices[i]->next_edge = new_edge;
            break;
        }
    }

    pthread_mutex_unlock(&graph->lock);
}

void remove_edge(Graph* graph, int source_rnti, int target_rnti) {
    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i]->rnti == source_rnti) {
            Edge** edge_ptr = &(graph->vertices[i]->next_edge);
            while (*edge_ptr) {
                if ((*edge_ptr)->target_rnti == target_rnti) {
                    Edge* to_free = *edge_ptr;
                    *edge_ptr = (*edge_ptr)->next;
                    free(to_free);
                    break;
                }
                edge_ptr = &((*edge_ptr)->next);
            }
            break;
        }
    }

    pthread_mutex_unlock(&graph->lock);
}

void log_operation(const char* operation) {
    // Toggle logging at runtime, minimal overhead
#ifdef ENABLE_LOGGING
    printf("Operation: %s\n", operation);
#endif
}

void destroy_graph(Graph* graph) {
    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->vertex_count; ++i) {
        Edge* edge = graph->vertices[i]->next_edge;
        while (edge) {
            Edge* to_free = edge;
            edge = edge->next;
            free(to_free);
        }
        free(graph->vertices[i]);
    }

    free(graph->vertices);
    pthread_mutex_unlock(&graph->lock);
    pthread_mutex_destroy(&graph->lock);
    free(graph);
}

// Example usage
int main() {
    Graph* graph = create_graph();
    add_vertex(graph, 1, "Strong");
