typedef struct Graph {
    Vertex *vertices;
    size_t vertex_count;
    size_t capacity;
    FILE *log_file;
    int logging_enabled;
} Graph;

Graph* create_graph(int initial_capacity) {
    Graph *graph = (Graph*)malloc(sizeof(Graph));
    graph->vertices = (Vertex*)calloc(initial_capacity, sizeof(Vertex));
    graph->vertex_count = 0;
    graph->capacity = initial_capacity;
    graph->log_file = NULL;
    graph->logging_enabled = 0;
    return graph;
}

void enable_logging(Graph *graph, const char *filename) {
    graph->log_file = fopen(filename, "a");
    graph->logging_enabled = 1;
}

void log_operation(Graph *graph, const char *operation) {
    if (graph->logging_enabled && graph->log_file) {
        fprintf(graph->log_file, "%s\n", operation);
        fflush(graph->log_file);
    }
}

int find_vertex_index(Graph *graph, unsigned int RNTI) {
    for (size_t i = 0; i < graph->vertex_count; ++i) {
        if (graph->vertices[i].RNTI == RNTI) {
            return i;
        }
    }
    return -1;
}

void add_vertex(Graph *graph, unsigned int RNTI, int CRCFLAG) {
    if (find_vertex_index(graph, RNTI) != -1) return;

    if (graph->vertex_count >= graph->capacity) {
        size_t new_capacity = graph->capacity * 2;
        Vertex *new_vertices = (Vertex*)realloc(graph->vertices, new_capacity * sizeof(Vertex));
        if (!new_vertices) {
            perror("Failed to resize vertex array");
            return;
        }
        graph->vertices = new_vertices;
        graph->capacity = new_capacity;
    }

    Vertex *vertex = &graph->vertices[graph->vertex_count++];
    vertex->RNTI = RNTI;
    vertex->CRCFLAG = CRCFLAG;
    vertex->edges = NULL;
    vertex->edge_count = 0;

    log_operation(graph, "Added vertex");
}

void add_edge(Graph *graph, unsigned int from_RNTI, unsigned int to_RNTI) {
    int from_index = find_vertex_index(graph, from_RNTI);
    int to_index = find_vertex_index(graph, to_RNTI);

    if (from_index == -1 || to_index == -1) return;

    Vertex *vertex = &graph->vertices[from_index];
    vertex->edges = realloc(vertex->edges, (vertex->edge_count + 1) * sizeof(size_t));
    if (!vertex->edges) {
        perror("Failed to resize edge array");
        return;
    }
    vertex->edges[vertex->edge_count++] = to_index;

    log_operation(graph, "Added edge");
}

void update_crcflag(Graph *graph, unsigned int RNTI, int new_CRCFLAG) {
    int index = find_vertex_index(graph, RNTI);
    if (index == -1) return;

    graph->vertices[index].CRCFLAG = new_CRCFLAG;
    log_operation(graph, "Updated CRCFLAG");
}

void free_graph(Graph *graph) {
    for (size_t i = 0; i < graph->vertex_count; ++i) {
        free(graph->vertices[i].edges);
    }
    free(graph->vertices);
    if (graph->log_file) fclose(graph->log_file);
    free(graph);
