NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t num_structures, size_t *out_count) {
    if (num_structures == 0 || out_count == NULL) return NULL;

    // Allocate memory for the list and a temporary array to track used RNTIs
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
