        do {
            rnti_found = false;
            pdu->RNTI = (RNTI)rand() % MAX_RNTI + 1; // Assuming RNTI starts from 1
            if (rnti_is_used(used_rntis, created_count, pdu->RNTI)) {
                rnti_found = true;
