#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "json-c/json.h"  // Assuming json-c library for JSON handling

#define MAX_DEVICES 10000
#define CONFIG_FILE "device_config.csv"

typedef struct {
    char rnti[16];
    char rx_ue_info_tag[32];
    unsigned int crc_indication_rel8;
    uint8_t crc_flag;  // Randomly set CRC flag
} NF_API_CRC_Ind;

typedef struct {
    NF_API_CRC_Ind *devices[MAX_DEVICES];
    size_t device_count;
    pthread_mutex_t lock;
} DeviceManager;

DeviceManager* initialize_device_manager() {
    DeviceManager *manager = malloc(sizeof(DeviceManager));
    if (!manager) return NULL;

    manager->device_count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < MAX_DEVICES; ++i)
        manager->devices[i] = NULL;

    // Seed random number generator
    srand(time(NULL));

    return manager;
}

void destroy_device_manager(DeviceManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < MAX_DEVICES && manager->devices[i]; ++i)
        free(manager->devices[i]);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_device(DeviceManager *manager, const char* rnti, const char* rx_ue_info_tag) {
    if (!manager || !rnti || !rx_ue_info_tag)
        return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->device_count >= MAX_DEVICES) {
        pthread_mutex_unlock(&manager->lock);
        return -2;  // Device limit reached
    }

    size_t index = manager->device_count++;
    NF_API_CRC_Ind *device = malloc(sizeof(NF_API_CRC_Ind));
    if (!device) {
        pthread_mutex_unlock(&manager->lock);
        return -3;  // Memory allocation failed
    }

    strncpy(device->rnti, rnti, sizeof(device->rnti) - 1);
    strncpy(device->rx_ue_info_tag, rx_ue_info_tag, sizeof(device->rx_ue_info_tag) - 1);
    device->crc_indication_rel8 = rand(); // Random CRC indication
    device->crc_flag = rand() % 2;        // Randomly set CRC flag

    manager->devices[index] = device;
    pthread_mutex_unlock(&manager->lock);

    return index;
}

int delete_device(DeviceManager *manager, size_t index) {
    if (!manager || index >= MAX_DEVICES)
        return -1;

    pthread_mutex_lock(&manager->lock);

    if (!manager->devices[index]) {
        pthread_mutex_unlock(&manager->lock);
        return -2;  // Device not found
    }

    free(manager->devices[index]);
    manager->devices[index] = NULL;
    memmove(&manager->devices[index], &manager->devices[index + 1],
            (MAX_DEVICES - index - 1) * sizeof(NF_API_CRC_Ind*));

    --manager->device_count;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

NF_API_CRC_Ind* get_device(DeviceManager *manager, size_t index) {
    if (!manager || index >= MAX_DEVICES)
        return NULL;

    pthread_mutex_lock(&manager->lock);

    NF_API_CRC_Ind* device = manager->devices[index];

    pthread_mutex_unlock(&manager->lock);

    return device;
}

int export_to_json(DeviceManager *manager, const char* filename) {
    if (!manager || !filename)
        return -1;

    FILE *file = fopen(filename, "w");
    if (!file)
        return -2;  // File opening failed

    fprintf(file, "[\n");

    for (size_t i = 0; i < manager->device_count; ++i) {
        NF_API_CRC_Ind *device = manager->devices[i];
        if (i > 0) fprintf(file, ",\n");

        fprintf(file, "{ \"rnti\": \"%s\", \"rx_ue_info_tag\": \"%s\", "
                        "\"crc_indication_rel8\": %u, \"crc_flag\": %d }",
                device->rnti, device->rx_ue_info_tag,
                device->crc_indication_rel8, device->crc_flag);
    }

    fprintf(file, "\n]\n");
    fclose(file);

    return 0;
}

int import_from_json(DeviceManager *manager, const char* filename) {
    if (!manager || !filename)
        return -1;

    FILE *file = fopen(filename, "r");
    if (!file)
        return -2;  // File opening failed

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *content = malloc(length + 1);
    fread(content, 1, length, file);
    fclose(file);

    content[length] = '\0';

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(content);
    free(content);

    if (!parsed_json) {
        return -3;  // JSON parsing failed
    }

    struct json_object *json_array;
    json_object_object_get_ex(parsed_json, "array", &json_array);

    size_t array_length;
    json_object_array_length(json_array, &array_length);

    for (size_t i = 0; i < array_length; ++i) {
        struct json_object *json_device;
        json_device = json_object_array_get_idx(json_array, i);

        struct json_object *rnti_obj, *rx_ue_info_tag_obj, *crc_indication_rel8_obj,
                           *crc_flag_obj;

        json_object_object_get_ex(json_device, "rnti", &rnti_obj);
        json_object_object_get_ex(json_device, "rx_ue_info_tag", &rx_ue_info_tag_obj);
        json_object_object_get_ex(json_device, "crc_indication_rel8", &crc_indication_rel8_obj);
        json_object_object_get_ex(json_device, "crc_flag", &crc_flag_obj);

        const char *rnti = json_object_get_string(rnti_obj);
        const char *rx_ue_info_tag = json_object_get_string(rx_ue_info_tag_obj);
        unsigned int crc_indication_rel8 = (unsigned int)json_object_get_int64(crc_indication_rel8_obj);
        uint8_t crc_flag = (uint8_t)json_object_get_int(crc_flag_obj);

        add_device(manager, rnti, rx_ue_info_tag);  // Add device after parsing
    }

    json_object_put(parsed_json);

    return 0;
}
