#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000

typedef enum { ACTIVE, INACTIVE } Status;

typedef struct {
    int sessionID;
    time_t timestamp;
    Status status;
    int priority; // Higher value means higher priority
} Session;

typedef struct {
    Session *sessions[MAX_SESSIONS];
    size_t count;
} SessionManager;

SessionManager* createSessionManager() {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;
    manager->count = 0;
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        manager->sessions[i] = NULL;
    }
    return manager;
}

void freeSessionManager(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]);
    }
    free(manager);
}

int addOrUpdateSession(SessionManager *manager, int sessionID, Status status, int priority) {
    if (manager == NULL || manager->count >= MAX_SESSIONS) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            // Update existing session
            manager->sessions[i]->status = status;
            manager->sessions[i]->priority = priority;
            manager->sessions[i]->timestamp = time(NULL);
            return 0; // Success
        }
    }

    // Add new session
    Session *newSession = (Session*)malloc(sizeof(Session));
    if (!newSession) return -1;

    newSession->sessionID = sessionID;
    newSession->status = status;
    newSession->priority = priority;
    newSession->timestamp = time(NULL);

    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->sessions[i] || manager->sessions[i]->priority < priority) {
            memmove(&manager->sessions[i + 1], &manager->sessions[i], 
                    sizeof(Session*) * (manager->count - i));
            manager->sessions[i] = newSession;
            if (i == manager->count) ++manager->count;
            return 0; // Success
        }
    }

    if (manager->count < MAX_SESSIONS) {
        manager->sessions[manager->count++] = newSession;
    } else {
        free(newSession);
        return -1; // No space to add session
    }

    return 0; // Success
}

Status getSessionStatus(SessionManager *manager, int sessionID) {
    if (manager == NULL) return INACTIVE;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            return manager->sessions[i]->status;
        }
    }

    return INACTIVE; // Session not found
}

int main() {
    SessionManager *manager = createSessionManager();
    if (!manager) {
        printf("Failed to create session manager.\n");
        return 1;
    }

    addOrUpdateSession(manager, 101, ACTIVE, 5);
