void free_network_events(NetworkEvent* events);

// Create an array of network events with dynamic memory allocation
NetworkEvent* create_event_array(size_t initial_capacity) {
    NetworkEvent* events = (NetworkEvent*)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!events) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return events;
}

// Add a new network event to the array
int add_network_event(NetworkEvent** events, size_t* count, size_t* capacity, const NetworkEvent* event) {
    if (*count >= *capacity) {
        // Double the capacity for amortized constant time complexity on additions
        size_t new_capacity = *capacity ? (*capacity << 1) : 4;
        NetworkEvent* new_events = (NetworkEvent*)realloc(*events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1; // Indicate failure
        }
        *events = new_events;
        *capacity = new_capacity;
    }

    (*events)[*count] = *event;
    (*count)++;

    return 0; // Success
}

// Free the dynamically allocated memory for network events
void free_network_events(NetworkEvent* events) {
    if (events) {
        free(events);
    }
}

