// Define the structure as per the problem statement.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int sequence_number;
    time_t timestamp;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure with lock for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for protecting access to the list
} NFAPI_CRC_LIST;

// Function prototypes
NFAPI_CRC_LIST* create_list();
int add_pdu(NFAPI_CRC_LIST* list);
void free_list(NFAPI_CRC_LIST* list);
Node* iterate_list(NFAPI_CRC_LIST* list, int (*callback)(Node*, void*), void* arg);

// Create a new linked list
NFAPI_CRC_LIST* create_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a PDU while ensuring no two consecutive elements have the same RNTI
int add_pdu(NFAPI_CRC_LIST* list) {
    if (!list) return -1;

    Node* current = list->head;
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.sequence_number = (current ? current->data.sequence_number + 1 : 0);
    time(&pdu.timestamp);

    // Assign random values to the fields
    srand(time(NULL) ^ (getpid()<<16));
    do {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() & 0x7FFF; // Example range for RNTI, adjust as needed
        pdu.CRC_INDICATION_REL8_TAG = rand(); 
        pdu.crc_flag = rand() % 2;
    } while (current && current->data.RNTI == pdu.RNTI);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the linked list memory
void free_list(NFAPI_CRC_LIST* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to iterate over the linked list and apply a callback function
Node* iterate_list(NFAPI_CRC_LIST* list, int (*callback)(Node*, void*), void* arg) {
    if (!list || !callback) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (callback(current, arg)) break;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return current; // Return the last processed node or NULL
}

// Example callback function to print PDU data
int print_pdu_data(Node* node, void* arg) {
    if (!node) return 1;

    printf("Sequence: %d, RX Tag: %d, RNTI: %u, CRC Tag: %d, Timestamp: %ld, CRC Flag: %d\n",
           node->data.sequence_number, node->data.RX_UE_INFORMATION_TAG,
           node->data.RNTI, node->data.CRC_INDICATION_REL8_TAG,
           node->data.timestamp, node->data.crc_flag);

    return 0; // Continue iteration
}

// Main function to demonstrate usage
int main() {
    NFAPI_CRC_LIST* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return -1;
    }

    for (int i = 0; i < 10; ++i) {
        if (add_pdu(list) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
            break;
        }
    }

    iterate_list(list, print_pdu_data, NULL);
    free_list(list);

    return 0;
}
```

This code includes a basic implementation of the described task with thread safety and error handling. It initializes the list, adds `NFAPI_CRC_INDICATION_PDU_T` structures ensuring no consecutive elements have the same RNTI value, and provides functions to iterate over and free the list.']

