Dynamic_Array* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    Dynamic_Array* arr = malloc(sizeof(Dynamic_Array));
    if (!arr) return NULL;

    arr->array = calloc(initial_capacity, sizeof(LTE_RRC_CME_IE_T*));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = initial_capacity;
    return arr;
}

int resize_dynamic_array(Dynamic_Array* arr, size_t new_capacity) {
    if (!arr || new_capacity == 0) return -1;

    LTE_RRC_CME_IE_T** temp = realloc(arr->array, new_capacity * sizeof(LTE_RRC_CME_IE_T*));
    if (!temp) return -1;

    arr->array = temp;
    arr->capacity = new_capacity;
    return 0;
}

int add_to_dynamic_array(Dynamic_Array* arr, LTE_RRC_CME_IE_T* element) {
    if (!arr || !element) return -1;

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        int result = resize_dynamic_array(arr, new_capacity);
        if (result != 0) return result;
    }

    arr->array[arr->size++] = element;
    return 0;
}

