    char* data;
    size_t dataSize;

    MIB_Block(int id, const char* d) : blockId(id), data(nullptr), dataSize(0) {
        if (d != nullptr && strlen(d) > 0) {
            dataSize = strlen(d) + 1; // Including null terminator
            data = new char[dataSize];
            strncpy(data, d, dataSize);
        }
    }

