        std::mutex hashMutex;
        for (const auto& str : inputStrings) {
            if (!str.empty() && str.length() <= 256) { // Max length limit
                std::lock_guard<std::mutex> lock(hashMutex);

                if (hashCache.find(str) != hashCache.end()) {
                    log("Hash found in cache for string: " + str);
                    continue;
                }

                unsigned char digest[MD5_DIGEST_LENGTH];
                MD5_CTX ctx;
                MD5_Init(&ctx);
                MD5_Update(&ctx, str.c_str(), str.length());
                MD5_Final(digest, &ctx);

                std::string hashString;
                for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
                    char buf[3];
                    snprintf(buf, sizeof(buf), "%02x", digest[i]);
                    hashString += buf;
                }

                hashCache[str] = *reinterpret_cast<unsigned char*>(const_cast<unsigned char*>(&digest));
                log("Computed MD5 for string: " + str);
            } else {
                log("Invalid string encountered during hashing.");
            }
        }
    }

