pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

CRCIndicationNode* generateNFCAPIListWithCRC(int size) {
    if (size <= 0) return NULL;

    CRCIndicationNode* head = NULL;
    CRCIndicationNode* tail = NULL;
    int allocated_count = 0;

    pthread_mutex_lock(&list_mutex);

    srand(time(NULL)); // Seed for random number generation

    while (allocated_count < size) {
        CRCIndicationNode* new_node = (CRCIndicationNode*)malloc(sizeof(CRCIndicationNode));
        if (!new_node) {
            log_error("Memory allocation failed");
            break;
        }

        new_node->pdu.RX_UE_INFORMATION_TAG = rand() % 1024; // Example tag
        bool unique_rnti_found = false;

        do {
            new_node->pdu.RNTI = (rand() % 65536) + 1; // Random RNTI

            CRCIndicationNode* current = head;
            while (current) {
                if (current->pdu.RNTI == new_node->pdu.RNTI) {
                    free(new_node);
                    unique_rnti_found = false;
                    break;
                }
                current = current->next;
            }

            unique_rnti_found = true;
        } while (!unique_rnti_found);

        new_node->pdu.CRCFLAG = rand() % 2; // Random CRC flag
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;

        allocated_count++;
    }

    log_performance_metric("Allocated Nodes", allocated_count);

    pthread_mutex_unlock(&list_mutex);

    // Clean up any partially allocated nodes if allocation failed
    if (allocated_count < size) {
        CRCIndicationNode* current = head;
        while (current) {
            CRCIndicationNode* to_free = current;
            current = current->next;
            free(to_free);
        }
        log_error("Partial list deallocation due to memory failure");
    }

    return head;
}

// Example logging functions
void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_performance_metric(const char* metric, int value) {
    printf("PERFORMANCE: %s = %d\n", metric, value);
}
