#include <stdlib.h>
#include <string.h>

typedef struct Dependency {
    char *name;
    struct Dependency *next;
} Dependency;

typedef struct FunctionConfig {
    char *function_name;
    char *reference;
    Dependency *dependencies;
    int type; // 0: unknown, 1: int, 2: float, 3: string, 4: array
} FunctionConfig;

typedef struct FunctionList {
    FunctionConfig *config;
    struct FunctionList *next;
} FunctionList;

FunctionList* parse_config(const char *file_path);
void free_function_list(FunctionList *list);

// Utility functions for parsing and managing memory
char* read_file(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char*)malloc(length + 1);
    if (buffer) {
        fread(buffer, 1, length, file);
        buffer[length] = '\0';
    }

    fclose(file);
    return buffer;
}

FunctionList* parse_config(const char *file_path) {
    char *content = read_file(file_path);
    if (!content) {
        fprintf(stderr, "Error reading file: %s\n", file_path);
        return NULL;
    }

    FunctionList *head = NULL, **current_ptr = &head;

    // Simulating parsing logic (pseudo-code)
    char *line = strtok(content, "\n");
    while (line != NULL) {
        FunctionConfig *config = malloc(sizeof(FunctionConfig));
        if (!config) {
            free_function_list(head);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Parsing logic for a single line
        char *name_token = strtok(line, ","); // Example tokenization
        config->function_name = strdup(name_token);

        char *ref_token = strtok(NULL, ",");
        config->reference = strdup(ref_token);

        config->dependencies = NULL; // Initialize dependencies

        // Add parsing logic for dependencies and type here...

        *current_ptr = malloc(sizeof(FunctionList));
        if (!*current_ptr) {
            free(config);
            free_function_list(head);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        (*current_ptr)->config = config;
        current_ptr = &((*current_ptr)->next);

        line = strtok(NULL, "\n");
    }

    free(content);
    return head;
}

void free_dependency(Dependency *dep) {
    while (dep) {
        Dependency *tmp = dep;
        dep = dep->next;
        free(tmp->name);
        free(tmp);
    }
}

void free_function_list(FunctionList *list) {
    while (list) {
        FunctionList *temp = list;
        list = list->next;

        free(temp->config->function_name);
        free(temp->config->reference);

        free_dependency(temp->config->dependencies);
        free(temp->config);
        free(temp);
    }
}

// Usage example
int main() {
    const char *file_path = "config.txt";
    FunctionList *functions = parse_config(file_path);

    if (functions) {
        // Process the functions as needed

        // Free resources after use
        free_function_list(functions);
    }

    return 0;
}
```

### Key Points:
