using System.Collections.Generic;
using System.IO;
using System.Net.NetworkInformation;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

public struct NetworkInterfaceStatus
{
    public string MAC_Address { get; set; }
    public string IP_Address { get; set; }
    public bool LinkStatus { get; set; }
}

class Program
{
    private static readonly SemaphoreSlim semaphore = new SemaphoreSlim(20);
    private static List<NetworkInterfaceStatus> networkInterfaces = new List<NetworkInterfaceStatus>();

    static async Task Main(string[] args)
    {
        var config = LoadConfiguration("config.json");

        int worldWidth = config.Width;
        int worldHeight = config.Height;
        double cameraSpeed = config.CameraSpeed;

        Console.WriteLine($"World Width: {worldWidth}, World Height: {worldHeight}, Camera Speed: {cameraSpeed}");

        await InitializeNetworkInterfaces();

        // Simulate ongoing operations with real-time updates
        while (true)
        {
            await Task.Delay(5000); // Check every 5 seconds for updates
            await UpdateNetworkInterfaceStatus();
        }
    }

    private static Config LoadConfiguration(string filePath)
    {
        string json = File.ReadAllText(filePath);
        return JsonConvert.DeserializeObject<Config>(json);
    }

    private static async Task InitializeNetworkInterfaces()
    {
        var tasks = new List<Task>();
        foreach (var networkInterface in NetworkInterface.GetAllNetworkInterfaces())
        {
            tasks.Add(CheckInterfaceStatus(networkInterface));
        }
        await Task.WhenAll(tasks);
    }

    private static async Task UpdateNetworkInterfaceStatus()
    {
        await semaphore.WaitAsync();
        try
        {
            var tasks = new List<Task>();
            foreach (var networkInterface in NetworkInterface.GetAllNetworkInterfaces())
            {
                tasks.Add(CheckInterfaceStatus(networkInterface));
            }
            await Task.WhenAll(tasks);
        }
        finally
        {
            semaphore.Release();
        }
    }

    private static async Task CheckInterfaceStatus(NetworkInterface networkInterface)
    {
        var status = new NetworkInterfaceStatus
        {
            MAC_Address = networkInterface.GetPhysicalAddress().ToString(),
            IP_Address = GetPrimaryIPAddress(networkInterface),
            LinkStatus = networkInterface.OperationalStatus == OperationalStatus.Up
        };

        lock (networkInterfaces)
        {
            // Update or add the interface status to the list
            var existingIndex = networkInterfaces.FindIndex(n => n.MAC_Address == status.MAC_Address);
            if (existingIndex >= 0)
                networkInterfaces[existingIndex] = status;
            else
                networkInterfaces.Add(status);
        }

        LogInterfaceStatus(networkInterface, status.LinkStatus);
    }

    private static string GetPrimaryIPAddress(NetworkInterface networkInterface)
    {
        foreach (var ip in networkInterface.GetIPProperties().UnicastAddresses)
        {
            if (ip.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork) // IPv4
                return ip.Address.ToString();
        }
        return null;
    }

    private static void LogInterfaceStatus(NetworkInterface networkInterface, bool linkStatus)
    {
        try
        {
            Console.WriteLine($"Interface {networkInterface.Name} - MAC: {networkInterface.GetPhysicalAddress()}, IP: {GetPrimaryIPAddress(networkInterface)}, Link Status: {(linkStatus ? "Up" : "Down")}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error logging interface status for {networkInterface.Name}: {ex.Message}");
        }
    }

    class Config
    {
        public int Width { get; set; }
        public int Height { get; set; }
        public double CameraSpeed { get; set; }
    }
}
```']

