static pthread_mutex_t monitor_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocations = 0;
static size_t peak_memory_usage = 0;
static size_t current_memory_usage = 0;

// Function to log memory usage statistics
void log_memory_statistics() {
    pthread_mutex_lock(&monitor_lock);
    printf("Total Allocations: %zu\n", total_allocations);
    printf("Peak Memory Usage: %zu bytes\n", peak_memory_usage);
    printf("Current Memory Usage: %zu bytes\n", current_memory_usage);
    pthread_mutex_unlock(&monitor_lock);
}

// Function to free memory and update usage statistics
void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t count) {
    if (array != NULL) {
        free(array);
        pthread_mutex_lock(&monitor_lock);
        current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T) * count;
        total_allocations--;
        pthread_mutex_unlock(&monitor_lock);
    }
}

// Function to allocate and initialize the array
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu_array(size_t n) {
    if (n < 1 || n > 1000) {
        fprintf(stderr, "Invalid number of structures requested.\n");
        return NULL;
    }

    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

    // Allocate memory
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size);
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize and populate the structures
    for (size_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Populate with a random value
        array[i].RNTI = rand() % 65536;          // Random RNTI within range
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF; // Random CRC flag
    }

    // Update memory usage statistics
    pthread_mutex_lock(&monitor_lock);
    current_memory_usage += size;
    if (current_memory_usage > peak_memory_usage) {
        peak_memory_usage = current_memory_usage;
    }
    total_allocations++;
    pthread_mutex_unlock(&monitor_lock);

    return array;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    // Example usage
    size_t num_structures = 500; // Example: Allocate memory for 500 structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_crc_indication_pdu_array(num_structures);

    if (pdu_array) {
        log_memory_statistics(); // Log current memory statistics

        free_crc_indication_pdu_array(pdu_array, num_structures); // Free allocated memory
        log_memory_statistics(); // Log updated memory statistics after freeing
    }

    return 0;
}
