['Below is an implementation of a C function that manages a dynamic, thread-safe, doubly linked list of `NFAPI_CRC_INDICATION_PDU_T` structures as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned long sequence_number;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    unsigned long current_sequence_number;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->current_sequence_number = 0;
    return list;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    // Ensure unique RNTI and CRC tags
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == data.RNTI || 
            (current->prev && current->prev->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG)) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI or consecutive CRC tag
        }
        if (current->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Non-consecutive duplicate RNTI
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    data.sequence_number = list->current_sequence_number++;
    data.timestamp = now;

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Usage example
int main() {
    LinkedList* list = create_list();
    if (!list) return 1;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 123, .CRC_INDICATION_REL8_TAG = 456 };

    if (insert_node(list, pdu) != 0) {
        printf("Insertion failed\n");
    }

    free_list(list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses a single mutex to manage concurrent access.
- **Memory Management**: Allocates nodes dynamically and ensures proper cleanup.
- **Error Handling**: Returns error codes for allocation failures and duplicate checks.
- **Unique Constraints**: Ensures uniqueness of `RNTI` across the list and prevents consecutive duplicate `CRC_INDICATION_REL8_TAG`.
- **Resource Cleanup**: Frees all allocated memory properly, including mutex destruction.']

