#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure Definitions

typedef struct {
    char LCG_ID[32];
    int TRANSPORT_CHANNEL_ID;
    char CHANNEL_CONFIGURATION[64];
} LogicalChannelUnit;

typedef struct LCGNode {
    LogicalChannelUnit* LCU;
    struct LCGNode* next; // Next LCU in the same group
    struct LCGNode* child; // Child LCGs
} LCGNode;

typedef struct {
    pthread_rwlock_t lock;
    LCGNode* root;
} LCGTree;

// Utility Functions

void initializeLCU(LogicalChannelUnit* lcu) {
    time_t now = time(NULL);
    sprintf(lcu->LCG_ID, "LCG_%ld", (long)now);
    lcu->TRANSPORT_CHANNEL_ID = rand() % 256;
    snprintf(lcu->CHANNEL_CONFIGURATION, sizeof(lcu->CHANNEL_CONFIGURATION), "Config_%d", rand());
}

int uniqueTransportChannelId(LCGNode* node, int id) {
    while (node) {
        if (node->LCU && node->LCU->TRANSPORT_CHANNEL_ID == id)
            return 0;
        node = node->next;
    }
    return 1;
}

// Tree Management Functions

void createLCG(LCGTree* tree, LCGNode** lcg) {
    *lcg = (LCGNode*)malloc(sizeof(LCGNode));
    if (*lcg == NULL) {
        perror("Failed to allocate LCG");
        exit(EXIT_FAILURE);
    }
    (*lcg)->LCU = (LogicalChannelUnit*)calloc(1, sizeof(LogicalChannelUnit));
    if ((*lcg)->LCU == NULL) {
        free(*lcg);
        perror("Failed to allocate Logical Channel Unit");
        exit(EXIT_FAILURE);
    }
    initializeLCU((*lcg)->LCU);
    (*lcg)->next = NULL;
    (*lcg)->child = NULL;
}

void addLCUToLCG(LCGNode* lcg, int transportChannelId) {
    LCGNode* new_lcu = (LCGNode*)malloc(sizeof(LCGNode));
    if (!new_lcu) {
        perror("Failed to allocate Logical Channel Unit Node");
        exit(EXIT_FAILURE);
    }

    new_lcu->LCU = (LogicalChannelUnit*)calloc(1, sizeof(LogicalChannelUnit));
    if (!new_lcu->LCU) {
        free(new_lcu);
        perror("Failed to allocate Logical Channel Unit");
        exit(EXIT_FAILURE);
    }

    do {
        initializeLCU(new_lcu->LCU);
    } while (!uniqueTransportChannelId(lcg, new_lcu->LCU->TRANSPORT_CHANNEL_ID));

    new_lcu->next = lcg->next;
    lcg->next = new_lcu;
}

void addChildLCG(LCGNode* parent, LCGNode** child) {
    createLCG(NULL, child);
    (*child)->next = parent->child;
    parent->child = *child;
}

void deleteLCGTree(LCGNode* node) {
    if (node == NULL)
        return;

    deleteLCGTree(node->child);
    while (node->next) {
        LCGNode* next_lcg = node->next;
        free(node->LCU);
        node = next_lcg;
    }
    free(node->LCU);
    free(node);
}

void initLCGTree(LCGTree* tree) {
    pthread_rwlock_init(&tree->lock, NULL);
    tree->root = NULL;
}

void insertLCG(LCGTree* tree, LCGNode** lcg) {
    pthread_rwlock_wrlock(&tree->lock);

    if (tree->root == NULL) {
        createLCG(tree, &tree->root);
        *lcg = tree->root;
    } else {
        addChildLCG(tree->root, lcg);
    }

    pthread_rwlock_unlock(&tree->lock);
}

void cleanupLCGTree(LCGTree* tree) {
    pthread_rwlock_wrlock(&tree->lock);

    if (tree->root)
        deleteLCGTree(tree->root);

    pthread_rwlock_unlock(&tree->lock);
    pthread_rwlock_destroy(&tree->lock);
}

// Example Usage

int main() {
    srand(time(NULL));

    LCGTree tree;
    initLCGTree(&tree);

    LCGNode* lcg1 = NULL, *lcg2 = NULL;

    insertLCG(&tree, &lcg1);
    addLCUToLCG(lcg1, 0);

    insertLCG(&tree, &lcg2);
    addLCUToLCG(lcg2, 0);

    cleanupLCGTree(&tree);

    return 0;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_rwlock_t` to ensure thread-safe access.
- **Memory Management**: Allocates memory dynamically for each LCG and LCU. Ensures proper deallocation to prevent leaks.
- **Unique Transport IDs**: Implements logic to guarantee unique transport channel IDs within an LCG.
- **Concurrency Considerations**: Read-write locks are used to balance read-heavy loads with occasional writes.
- **Error Handling**: Checks for allocation failures, exits gracefully if memory cannot be allocated.

