['Below is an implementation of the C function that manages a dynamic array of `LTE_DL_FRAME_MSG` structures in a multi-threaded environment. The code includes error handling for memory allocation failures and ensures thread-safe access using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Assuming these structures are defined somewhere else in your project.
typedef struct {
    int frame_id;
    int rnti;
} LTE_DL_FRAMEIE_T;

typedef struct {
    LTE_DL_FRAMEIE_T ie;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} FrameArrayManager;

// Initialize the manager
int initFrameArrayManager(FrameArrayManager* manager, size_t initial_capacity) {
    if (!manager) return -1;

    manager->array = (LTE_DL_FRAME_MSG*)malloc(initial_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (!manager->array) return -1;

    manager->capacity = initial_capacity;
    manager->size = 0;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager->array);
        return -1;
    }

    return 0;
}

// Allocate and deallocate memory with thread safety
int addFrameMsg(FrameArrayManager* manager, int frame_id, int rnti) {
    if (!manager || pthread_mutex_lock(&manager->lock)) return -1;

    // Resize array if needed
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_DL_FRAME_MSG* temp_array = realloc(manager->array, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (!temp_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = temp_array;
        manager->capacity = new_capacity;
    }

    // Add the new frame message
    LTE_DL_FRAMEIE_T* ie = &manager->array[manager->size].ie;
    ie->frame_id = frame_id;
    ie->rnti = rnti;

    manager->size++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Deallocate memory with thread safety
void freeFrameArrayManager(FrameArrayManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

```

### Key Points:
- **Thread Safety**: A `pthread_mutex_t` lock is used to ensure that access to the dynamic array is synchronized across multiple threads.
- **Dynamic Resizing**: The array resizes itself by doubling its capacity when full, ensuring efficient memory allocation and minimizing reallocation overhead.
- **Error Handling**: Returns error codes for failed memory allocations or mutex operations, which can be checked by the calling functions.
- **Memory Management**: Properly initializes, reallocates, and deallocates memory to prevent leaks.

This implementation balances performance, usability, maintainability, and scalability while providing thread-safe access in a multi-threaded environment.']

