#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000 // Initial maximum entries; can be adjusted at runtime

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    size_t max_entries;
    pthread_mutex_t lock;
} DynamicList;

void init_dynamic_list(DynamicList* list, size_t max_entries) {
    list->head = NULL;
    list->size = 0;
    list->max_entries = max_entries;
    pthread_mutex_init(&list->lock, NULL);
}

int insert_unique_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_entries) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == entry.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -2; // RNTI already exists
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failure
    }

    new_node->data = entry;
    new_node->next = NULL;
    *current = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_entry(DynamicList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void free_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    DynamicList list;
    init_dynamic_list(&list, MAX_ENTRIES);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, };
    memset(entry1.CRC_INDICATION_REL8_TAG, 0xAA, sizeof(entry1.CRC_INDICATION_REL8_TAG));
    entry1.CRCFLAG = rand() % 2;

    int result = insert_unique_entry(&list, entry1);
    if (result == 0) {
        printf("Entry inserted successfully.\n");
    } else {
        printf("Failed to insert entry. Error code: %d\n", result);
    }

    // Retrieve and print
    NFAPI_CRC_INDICATION_PDU_T* retrieved = retrieve_entry(&list, 100);
    if (retrieved) {
        printf("Retrieved Entry: RNTI = %u, CRCFLAG = %u\n", retrieved->RNTI, retrieved->CRCFLAG);
    } else {
        printf("Entry not found.\n");
    }

    free_dynamic_list(&list);

    return 0;
}
```

This C code defines a dynamic list structure that manages `NFAPI_CRC_INDICATION_PDU_T` entries with unique `RNTI`s. The implementation ensures thread-safe operations using a mutex lock, handles memory allocation failures gracefully, and provides functions for insertion, retrieval, and cleanup of resources. Adjustments can be made to the maximum number of entries at runtime based on system requirements.']

