// Initialize the dynamic array with a given initial capacity
void init_dynamic_array(DynamicArray* arr, size_t initial_capacity) {
    arr->array = (LTE_RRC_CME_IE_T*)malloc(initial_capacity * sizeof(LTE_RRC_CME_IE_T));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
}

// Resize the dynamic array when capacity is reached
void resize_dynamic_array(DynamicArray* arr) {
    size_t new_capacity = arr->capacity * 2;
    LTE_RRC_CME_IE_T* temp = (LTE_RRC_CME_IE_T*)realloc(arr->array, new_capacity * sizeof(LTE_RRC_CME_IE_T));
    if (temp != NULL) {
        arr->array = temp;
        arr->capacity = new_capacity;
    } else {
        perror("Failed to resize dynamic array");
