    }
}

// Add a new LTE_RRC_CME_IE_T structure to the dynamic array
void add_ie_to_array(DynamicArray* arr, LTE_RRC_CME_IE_T ie) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr);
    }

    arr->array[arr->size++] = ie;

    pthread_mutex_unlock(&arr->lock);
}

