<?php

class UserProfileManager {
    private $cache;
    private $dbConnection;

    public function __construct() {
        $this->cache = new Cache(); // Assuming a Cache class exists
        $this->dbConnection = new Database(); // Assuming a Database connection class exists
    }

    public function manageProfile($_REQUEST) {
        try {
            header('Content-Type: application/json');

            $subAction = $_REQUEST['sub_action'] ?? '';
            $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
            $name = $_REQUEST['name'] ?? '';
            $bio = $_REQUEST['bio'] ?? '';
            $profilePic = $_FILES['profilePic'] ?? null;
            $coverPic = $_FILES['coverPic'] ?? null;

            // Validate input
            if (!$this->validateInput($subAction, $name, $bio, $profilePic, $coverPic)) {
                return $this->jsonResponse('error', 'Invalid input data');
            }

            switch ($subAction) {
                case 'create':
                    $result = $this->createProfile($name, $bio, $profilePic, $coverPic);
                    break;

                case 'update':
                    if (!$id) throw new Exception("ID is required for update");
                    $result = $this->updateProfile($id, $name, $bio, $profilePic, $coverPic);
                    break;

                case 'delete':
                    if (!$id) throw new Exception("ID is required for delete");
                    $result = $this->deleteProfile($id);
                    break;

                case 'get':
                    $result = $this->getProfile($id);
                    break;

                default:
                    return $this->jsonResponse('error', 'Invalid sub_action');
            }

            return $this->jsonResponse('success', ['data' => $result]);

        } catch (Exception $e) {
            return $this->jsonResponse('error', $e->getMessage());
        }
    }

    private function validateInput($subAction, $name, $bio, $profilePic, $coverPic) {
        // Implement validation logic
        if ($subAction !== 'create' && $subAction !== 'update' && $subAction !== 'delete' && $subAction !== 'get') return false;

        if (!$this->isValidName($name)) return false;

        if (!empty($profilePic) && !$this->validateImage($profilePic, 500, 500, ['jpeg', 'png'])) return false;

        if (!empty($coverPic) && !$this->validateImage($coverPic, 1920, 1080, ['jpeg', 'png'])) return false;

        return true;
    }

    private function isValidName($name) {
        // Example validation for name
        return !empty($name);
    }

    private function validateImage($image, $maxWidth, $maxHeight, $allowedTypes) {
        if ($image['error'] !== UPLOAD_ERR_OK) return false;

        list($width, $height, $type) = getimagesize($image['tmp_name']);
        $fileType = image_type_to_extension($type);

        return in_array(strtolower($fileType), $allowedTypes) && $width <= $maxWidth && $height <= $maxHeight;
    }

    private function createProfile($name, $bio, $profilePic, $coverPic) {
        // Save images to cloud/storage and get URLs
        $profilePicUrl = $this->uploadImage($profilePic);
        $coverPicUrl = $this->uploadImage($coverPic);

        // Insert profile data into the database
        $id = $this->dbConnection->insert('profiles', [
            'name' => $name,
            'bio' => $bio,
            'profile_pic' => $profilePicUrl,
            'cover_pic' => $coverPicUrl
        ]);

        return ['id' => $id, 'name' => $name, 'bio' => $bio];
    }

    private function updateProfile($id, $name, $bio, $profilePic, $coverPic) {
        // Fetch current profile from cache or database
        $cacheKey = "profile_$id";
        $profileData = $this->cache->get($cacheKey);

        if (!$profileData) {
            $profileData = $this->dbConnection->select('profiles', ['*'], ['id' => $id]);
            $this->cache->set($cacheKey, $profileData);
        }

        // Update profile data
        if ($profilePic) {
            $profileData['profile_pic'] = $this->uploadImage($profilePic);
        }

        if ($coverPic) {
            $profileData['cover_pic'] = $this->uploadImage($coverPic);
        }

        $this->dbConnection->update('profiles', [
            'name' => $name,
            'bio' => $bio
        ], ['id' => $id]);

        // Update cache
        $this->cache->set($cacheKey, $profileData);

        return $profileData;
    }

    private function deleteProfile($id) {
        // Fetch current profile from cache or database
        $cacheKey = "profile_$id";
        $profileData = $this->cache->get($cacheKey);

        if (!$profileData) {
            $profileData = $this->dbConnection->select('profiles', ['*'], ['id' => $id]);
        }

        // Delete profile data from database
        $this->dbConnection->delete('profiles', ['id' => $id]);

        // Remove cache
        $this->cache->remove($cacheKey);

        return [];
    }

    private function getProfile($id) {
        $cacheKey = "profile_$id";
        $profileData = $this->cache->get($cacheKey);

        if (!$profileData) {
            $profileData = $this->dbConnection->select('profiles', ['*'], ['id' => $id]);
            $this->cache->set($cacheKey, $profileData);
        }

        return $profileData;
    }

    private function uploadImage($image) {
        // Upload logic to cloud storage or server
        if (!$image || $image['error'] !== UPLOAD_ERR_OK) return null;

        // Example: Upload image and return URL
        $uploadPath = '/path/to/storage/';
        move_uploaded_file($image['tmp_name'], $uploadPath . basename($image['name']));
        return "https://storage.example.com/" . basename($image['name']);
    }

    private function jsonResponse($status, $data) {
        return json_encode(['message' => $status, 'data' => $data]);
    }
}

// Usage
$profileManager = new UserProfileManager();
echo $profileManager->manageProfile($_REQUEST);

?>
