// Function to generate a random integer between min and max (inclusive)
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void populateNfarApiList(NFAPI_CRC_INDICATION_PDU_T *list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        list[i].RNTI = getRandomInt(1000, 9999);
        list[i].RX_UE_INFORMATION_TAG = getRandomInt(1, 65535);
        list[i].crcIndicationTag.CRCFLAG = getRandomInt(0, 1);
    }
}

Resource updateResourceWithHttpPut(int resourceId, const char *updatedData) {
    Resource updatedResource;
    pthread_mutex_lock(&resourceMutex);

    for (int i = 0; i < resourceCount; ++i) {
        if (resourcePool[i].id == resourceId) {
            strncpy(resourcePool[i].data, updatedData, sizeof(resourcePool[i].data) - 1);
            updatedResource = resourcePool[i];
            pthread_mutex_unlock(&resourceMutex);
            return updatedResource;
        }
    }

    pthread_mutex_unlock(&resourceMutex);
    printf("Error: Resource ID %d not found.\n", resourceId);
    exit(EXIT_FAILURE); // Or handle error appropriately
}

Resource deleteResourceWithHttpDelete(int resourceId) {
    Resource newResource = {0}; // Default initialized resource

    pthread_mutex_lock(&resourceMutex);

    for (int i = 0; i < resourceCount; ++i) {
        if (resourcePool[i].id == resourceId) {
            memset(&resourcePool[i], 0, sizeof(resourcePool[i]));
            break;
        }
    }

    pthread_mutex_unlock(&resourceMutex);
    return newResource;
}

int main() {
    // Seed random number generator
    srand((unsigned int)time(NULL));

    const size_t listSize = 10;
    NFAPI_CRC_INDICATION_PDU_T *apiList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * listSize);
    if (!apiList) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    populateNfarApiList(apiList, listSize);

    // Example resource usage
    pthread_mutex_lock(&resourceMutex);
    for (int i = 0; i < 5; ++i) {
        resourcePool[i].id = i + 1;
        snprintf(resourcePool[i].data, sizeof(resourcePool[i].data), "Resource %d", i + 1);
    }
    resourceCount = 5;
    pthread_mutex_unlock(&resourceMutex);

    Resource updatedRes = updateResourceWithHttpPut(3, "Updated data for resource 3");
    printf("Updated Resource: ID=%d Data=%s\n", updatedRes.id, updatedRes.data);

    Resource newRes = deleteResourceWithHttpDelete(2);
    printf("Deleted Resource initialized with default values: ID=%d Data=%s\n",
           newRes.id, newRes.data);

    free(apiList);
    return 0;
}
