#define MAX_NETWORK_INTERFACES 50
#define MAX_INIT_MESSAGES 10

typedef struct {
    int frame_id;
    int rnti;
} LTE_DL_FRAMEIE_T;

typedef struct {
    LTE_DL_FRAMEIE_T frameie;
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Memory allocation failed for DynamicArray");
        return NULL;
    }

    da->array = (LTE_DL_FRAME_MSG *)calloc(initial_capacity, sizeof(LTE_DL_FRAME_MSG));
    if (!da->array) {
        free(da);
        log_error("Memory allocation failed for LTE_DL_FRAME_MSG array");
        return NULL;
    }

    da->capacity = initial_capacity;
    da->count = 0;

    if (pthread_mutex_init(&da->lock, NULL) != 0) {
        log_error("Mutex initialization failed");
        free(da->array);
        free(da);
        return NULL;
    }

    return da;
}

int dynamic_array_add(DynamicArray *da, LTE_DL_FRAMEIE_T frameie) {
    if (!da) return -1;

    pthread_mutex_lock(&da->lock);

    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        LTE_DL_FRAME_MSG *new_array = (LTE_DL_FRAME_MSG *)realloc(da->array, new_capacity * sizeof(LTE_DL_FRAME_MSG));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            log_error("Memory reallocation failed");
            return -1;
        }

        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->count].frameie = frameie;
    da->count++;

    pthread_mutex_unlock(&da->lock);

    return 0;
}

void dynamic_array_free(DynamicArray *da) {
    if (da) {
        if (pthread_mutex_destroy(&da->lock) != 0)
            log_error("Mutex destruction failed");

        free(da->array);
        free(da);
    }
}

void random_frameie(LTE_DL_FRAMEIE_T *frameie) {
    frameie->frame_id = rand() % 1024;
    frameie->rnti = rand() % 65536;
}

void* init_messages(void *arg) {
    DynamicArray *da = (DynamicArray *)arg;

    for (int i = 0; i < MAX_INIT_MESSAGES; ++i) {
        LTE_DL_FRAMEIE_T frameie;
        random_frameie(&frameie);

        if (dynamic_array_add(da, frameie) != 0)
            log_error("Failed to add message");
    }

    return NULL;
}

void manage_network_interfaces(DynamicArray *da) {
    pthread_t threads[MAX_NETWORK_INTERFACES];
    int thread_count = MAX_NETWORK_INTERFACES < MAX_INIT_MESSAGES ? MAX_NETWORK_INTERFACES : MAX_INIT_MESSAGES;

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, init_messages, da) != 0) {
            log_error("Thread creation failed");
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    srand(time(NULL));

    DynamicArray *da = dynamic_array_init(MAX_NETWORK_INTERFACES);

    if (!da) {
        return -1;
    }

    manage_network_interfaces(da);

    // Garbage collection or cleanup logic can be added here

    dynamic_array_free(da);

    return 0;
}
