    int state;
    struct StateList *next;
} StateList;

StateList* create_filtered_state_list(const int *states, int num_states, const FSA *fsa, int last_state, unsigned long bitmask) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    // Filter states based on the bitmask
    int filtered_count = 0;
    for (int i = 0; i < num_states; ++i) {
        if ((1UL << states[i]) & bitmask) {
            filtered_count++;
        }
    }

    // Allocate memory for the new state list
    StateList *new_list = malloc(filtered_count * sizeof(StateList));
    pthread_mutex_unlock(&lock);

    if (!new_list) {
        return NULL;  // Handle allocation failure gracefully
    }

    int index = 0;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_states; ++i) {
        if ((1UL << states[i]) & bitmask) {
            new_list[index].state = states[i];
            new_list[index].next = (index + 1 < filtered_count) ? &new_list[index + 1] : NULL;
            index++;
        }
    }

    // Update the 'next' pointer of the last state in the original list
    StateList *last_node = malloc(sizeof(StateList));
    if (!last_node) {
        free(new_list);
        return NULL;
    }
    last_node->state = last_state;
    last_node->next = new_list;

    pthread_mutex_unlock(&lock);

    return new_list;
}
