['Here's a C implementation of the described function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct State {
    int state_id;
    struct State* next;
} State;

typedef struct FSA {
    int num_states;
    int** transitions; // 2D array: transitions[state][input] = next_state or -1 if no transition
} FSA;

typedef struct Config {
    char* memory_strategy;
    int log_level;
} Config;

void log_message(Config *config, const char *message) {
    if (config->log_level > 0) {
        printf("%s\n", message);
    }
}

State* create_state(int state_id) {
    State *new_state = malloc(sizeof(State));
    if (!new_state) {
        return NULL;
    }
    new_state->state_id = state_id;
    new_state->next = NULL;
    return new_state;
}

void free_states(State *head) {
    while (head != NULL) {
        State *temp = head;
        head = head->next;
        free(temp);
    }
}

State* manage_fsa_states(int *initial_states, int num_initial_states, FSA *fsa, int last_state_id, Config *config) {
    if (!fsa || !initial_states || num_initial_states <= 0 || fsa->num_states <= 0) {
        log_message(config, "Invalid input parameters.");
        return NULL;
    }

    State *visited = NULL; // Linked list to track visited states
    int *state_visited = calloc(fsa->num_states, sizeof(int));
    if (!state_visited) {
        log_message(config, "Memory allocation for state tracking failed.");
        return NULL;
    }

    State **queue = malloc((num_initial_states + fsa->num_states) * sizeof(State*));
    if (!queue) {
        free(state_visited);
        log_message(config, "Queue memory allocation failed.");
        return NULL;
    }

    int front = 0, rear = 0;

    // Enqueue initial states
    for (int i = 0; i < num_initial_states; ++i) {
        if (!state_visited[initial_states[i]]) {
            queue[rear++] = create_state(initial_states[i]);
            state_visited[initial_states[i]] = 1;
            log_message(config, "Enqueued initial state.");
        }
    }

    State *last_state = NULL;

    while (front < rear) {
        State *current = queue[front++];
        if (!current) continue;

        // Link to visited list
        current->next = visited;
        visited = current;

        last_state = current; // Keep track of the last state processed

        for (int input = 0; fsa->transitions[current->state_id] && input < num_initial_states; ++input) {
            int next_state_id = fsa->transitions[current->state_id][input];
            if (next_state_id != -1 && !state_visited[next_state_id]) {
                State *new_state = create_state(next_state_id);
                if (!new_state) {
                    log_message(config, "Memory allocation for new state failed.");
                    free_states(visited);
                    free(queue);
                    free(state_visited);
                    return NULL;
                }
                queue[rear++] = new_state;
                state_visited[next_state_id] = 1;
                log_message(config, "Enqueued a new state via transition.");
            }
        }
    }

    // Link last known state to the newly created list
    if (last_state) {
        last_state->next = visited; // In this context, it's more like linking back to itself for demonstration.
    } else {
        free_states(visited);
        free(queue);
        free(state_visited);
        log_message(config, "No states processed.");
        return NULL;
    }

    free(queue);
    free(state_visited);

    if (last_state_id != -1) {
        last_state->next = visited; // Link the specified last state to new list
    }

    log_message(config, "State management completed successfully.");
    return visited;
}
```

This function handles linked-list creation for states derived from a finite state automaton. It uses a queue to process each state exactly once, even if non-deterministic transitions exist. Logging is implemented based on the configuration settings provided.

Make sure to adapt logging and memory strategies according to your needs by modifying the `Config` structure and handling accordingly in the code.']

