use std::env;
use std::fs;
use std::process::Command;

fn execute_module_tests(
    label: &str,
    f: fn() -> Result<(), Box<dyn std::error::Error>>,
    mocking_library: &str,
    module_dependencies: Vec<&str>,
) {
    // Check or set the MODULE_PATH environment variable
    let mut module_path = env::var("MODULE_PATH").unwrap_or_else(|_| {
        let test_results_dir = "test_results";
        fs::create_dir_all(test_results_dir).expect(&format!(
            "Failed to create directory '{}'",
            test_results_dir
        ));
        test_results_dir.to_string()
    });

    // Ensure module_dependencies are up-to-date
    for dependency in &module_dependencies {
        let status = Command::new("npm")
            .arg("install")
            .arg(dependency)
            .status()
            .expect(&format!("Failed to run npm install for {}", dependency));

        if !status.success() {
            panic!(
                "Error installing dependency '{}': {}",
                dependency,
                status
            );
        }
    }

    // Load the JavaScript module using require
    let js_code = format!(r#"
        const module = require('./{}');
        try {{
            console.log(`Running test: {}`);
            module.test();  // Assuming the module has a 'test' function
        }} catch (error) {{
            console.error('Test failed:', error);
            process.exit(1);
        }}
    "#, label);

    println!("Executing test: {}", label);

    // Run the user-provided test function `f`
    if let Err(e) = f() {
        eprintln!("Error executing Rust test function '{}': {:?}", label, e);
        return;
    }

    // Reset the mocking library after test execution
    reset_mocking_library(mocking_library).expect("Failed to reset mocking library");

    // Log module name, test name, and dependency version information
    for dependency in &module_dependencies {
        let output = Command::new("npm")
            .arg("list")
            .arg(dependency)
            .output()
            .expect(&format!("Failed to get npm list for {}", dependency));

        if !output.status.success() {
            eprintln!(
                "Error retrieving version info for '{}': {}",
                dependency,
                String::from_utf8_lossy(&output.stderr)
            );
            continue;
        }

        let version_info = String::from_utf8(output.stdout).expect("Invalid UTF-8 output");
        println!("Dependency: {}, Version Info:\n{}", dependency, version_info);
    }

    // Log the completion of the test
    println!(
        "Test '{}' completed successfully. Module Path: {}",
        label, module_path
    );
}

fn reset_mocking_library(library_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let output = Command::new("node")
        .arg("-e")
        .arg(&format!(
            "require('{}.').reset();", library_name
        ))
        .output()?;

    if !output.status.success() {
        return Err(format!("Failed to reset mocking library '{}': {:?}", library_name, output).into());
    }

    Ok(())
}
```

