["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 1000 // Example initial maximum number; configurable

typedef enum {
    PHY_MESSAGE_TYPE_A,
    PHY_MESSAGE_TYPE_B,
    // Add other message types as needed
} PHY_MESSAGE_TYPE;

typedef struct {
    PHY_MESSAGE_TYPE type;
    int sequence_number;
    unsigned long frame_counter;
} PHY_MESSAGE_T;

typedef struct Node {
    PHY_MESSAGE_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_entries;
} PhyMessageList;

PhyMessageList* create_list(int max_entries) {
    PhyMessageList* list = (PhyMessageList*)malloc(sizeof(PhyMessageList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_entries = max_entries;
    return list;
}

int is_sequence_number_unique(PhyMessageList* list, int sequence_number) {
    Node* current = list->head;
    while (current) {
        if (current->data.sequence_number == sequence_number)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

int insert_message(PhyMessageList* list, PHY_MESSAGE_T message) {
    pthread_mutex_lock(&list->lock);

    if (!is_sequence_number_unique(list, message.sequence_number)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: Sequence number not unique
    }

    int count = 0;
    Node* current = list->head;

    while (current && ++count < list->max_entries) {
        if (message.frame_counter < current->data.frame_counter)
            break;
        current = current->next;
    }

    if (count >= list->max_entries) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Max entries reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Error: Memory allocation failed
    }

    new_node->data = message;
    new_node->next = current;

    if (current == list->head || message.frame_counter < list->head->data.frame_counter)
        list->head = new_node;
    else {
        Node* prev = list->head;
        while (prev->next != current) 
            prev = prev->next;
        prev->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

PHY_MESSAGE_T* retrieve_message(PhyMessageList* list, int sequence_number) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.sequence_number == sequence_number) {
            PHY_MESSAGE_T* message = &current->data;
            pthread_mutex_unlock(&list->lock);
            return message;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void free_list(PhyMessageList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int set_max_entries(PhyMessageList* list, int new_max_entries) {
    pthread_mutex_lock(&list->lock);

    if (new_max_entries <= 0 || new_max_entries > MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: Invalid max entries
    }

    int count = 0;
    Node* current = list->head;

    while (current && ++count < list->max_entries)
        current = current->next;

    if (count > new_max_entries) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Current entries exceed new max
    }

    list->max_entries = new_max_entries;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}
```

### Explanation:

- **Data Structures**: The code defines a `PhyMessageList` struct to manage the dynamic list, using linked lists for efficient insertion and retrieval. It includes a mutex for thread-safety.

- **Unique Sequence Numbers**: The function checks if a sequence number is unique before inserting a new message.

- **Insertion Logic**: Messages are inserted in order of their `FRAME_COUNTER`, ensuring fast access to the latest frames.

- **Memory Management**: Handles memory allocation failures and ensures resources are freed properly on error or completion.

- **Thread Safety**: Uses mutexes for thread-safe operations, preventing data corruption during concurrent access.

- **Configurable Max Entries**: Allows dynamic adjustment of maximum entries, with safety checks to ensure new limits don't exceed the number of current entries."]

