['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

EVP_CIPHER_CTX* initialize_aes256_cbc_cipher(const char *password, unsigned char **key) {
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    *key = malloc(EVP_MAX_KEY_LENGTH);

    if (!(*key)) return NULL;

    SHA256((unsigned char*)password, strlen(password), *key);
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        free(*key);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, *key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        return NULL;
    }

    if (16 != EVP_CIPHER_CTX_iv_length(ctx)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        return NULL;
    }

    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));
    if (1 != EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*key);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx, unsigned char *key) {
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (key) free(key);
}

int populate_sessions(SessionManager *manager, size_t num_sessions) {
    pthread_mutex_lock(&manager->lock);

    manager->pdu_list = malloc(num_sessions * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < num_sessions; ++i) {
        manager->pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        manager->pdu_list[i].RNTI = rand();
        manager->pdu_list[i].CRC_INDICATION_REL8_TAG = rand();
        manager->pdu_list[i].CRCFLAG = rand() & 1;

        for (size_t j = 0; j < i; ++j) {
            if (manager->pdu_list[j].RNTI == manager->pdu_list[i].RNTI) {
                fprintf(stderr, "Duplicate RNTI detected: %u\n", manager->pdu_list[i].RNTI);
                free(manager->pdu_list);
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }
        }
    }

    manager->count = num_sessions;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void cleanup_sessions(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->pdu_list) {
        free(manager->pdu_list);
        manager->pdu_list = NULL;
        manager->count = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

void session_manager_init(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->pdu_list = NULL;
    manager->count = 0;
}

void session_manager_cleanup(SessionManager *manager) {
    cleanup_sessions(manager);
    pthread_mutex_destroy(&manager->lock);
}
```

### Explanation:
- **AES Initialization**: The function `initialize_aes256_cbc_cipher` initializes an AES-256-CBC cipher with a derived key from the SHA-256 hash of the password.
