```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define NUM_METADATA_FIELDS 5

typedef struct {
    char *timestamp;
    char *event_type;
    double metadata[NUM_METADATA_FIELDS];
} Event;

typedef struct EventTypeNode {
    char *event_type;
    double average_last_three;
    int count;
    struct EventTypeNode *next;
} EventTypeNode;

EventTypeNode* find_or_create_node(EventTypeNode **head, const char *event_type) {
    EventTypeNode *current = *head;
    while (current != NULL) {
        if (strcmp(current->event_type, event_type) == 0) {
            return current;
        }
        current = current->next;
    }

    EventTypeNode *new_node = malloc(sizeof(EventTypeNode));
    new_node->event_type = strdup(event_type);
    new_node->average_last_three = 0.0;
    new_node->count = 0;
    new_node->next = *head;
    *head = new_node;

    return new_node;
}

int is_valid_event(const char *line, Event *event) {
    int fields_counted = 0;
    char *token = strtok(line, ",");

    if (token == NULL) return 0; // No timestamp
    event->timestamp = strdup(token);
    fields_counted++;

    token = strtok(NULL, ",");
    if (token == NULL) return 0; // No event type
    event->event_type = strdup(token);
    fields_counted++;

    for (int i = 0; i < NUM_METADATA_FIELDS; i++) {
        token = strtok(NULL, ",");
        if (token == NULL) return 0; // Missing metadata field
        event->metadata[i] = atof(token);
        fields_counted++;
    }

    return fields_counted == 2 + NUM_METADATA_FIELDS;
}

void free_event(Event *event) {
    free(event->timestamp);
    free(event->event_type);
}

double calculate_average_last_three(double last_three[]) {
    double sum = last_three[0] + last_three[1] + last_three[2];
    return sum / 3.0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    EventTypeNode *event_type_head = NULL;
    char line[MAX_LINE_LENGTH];
    Event event;

    while (fgets(line, sizeof(line), file)) {
        if (!is_valid_event(line, &event)) {
            fprintf(stderr, "Invalid event: %s", line);
            continue;
        }

        double last_three[NUM_METADATA_FIELDS - 2] = {event.metadata[3], event.metadata[4], event.metadata[5]};
        EventTypeNode *node = find_or_create_node(&event_type_head, event.event_type);

        node->average_last_three = ((node->count * node->average_last_three) + calculate_average_last_three(last_three)) / (node->count + 1);
        node->count++;

        free_event(&event);
    }

    fclose(file);

    EventTypeNode *current = event_type_head;
    while (current != NULL) {
        printf("Event Type: %s, Average of Last Three Metadata: %.2f\n", current->event_type, current->average_last_three);
        EventTypeNode *temp = current;
        current = current->next;
        free(temp->event_type);
        free(temp);
    }

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Memory Management**: The program uses `strdup` and `malloc` to handle dynamic memory allocation for event data.
- **Error Handling**: It checks for invalid file paths, malformed lines, and missing fields, logging errors as needed.
- **Memory Efficiency**: Memory is freed after processing each line to prevent leaks.
- **Extensibility**: The design allows easy extension by modifying the `NUM_METADATA_FIELDS` or adding new aggregation methods.']

