['Below is an example implementation that outlines how you might create such a C function to extract metadata from audio files. This code leverages dynamic libraries for format-specific parsing and includes modular design principles.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the custom struct for metadata.
typedef struct {
    int num_channels;
    long sample_rate;
    int bit_depth;
    char format[10];
} AudioMetadata;

// Dynamic library function pointers and types (placeholder).
typedef void* (*FormatParserInit)();
typedef AudioMetadata (*ParseAudio)(void*, const char*);
typedef void (*CleanupParser)(void*);

// Function to load a dynamic library.
void* load_library(const char *library_path) {
    return dlopen(library_path, RTLD_LAZY);
}

// Function to get a symbol from the loaded library.
void* get_symbol(void *handle, const char *symbol_name) {
    return dlsym(handle, symbol_name);
}

AudioMetadata extract_metadata(const char *file_path, const char *format) {
    AudioMetadata metadata = {0};
    void *lib_handle = NULL;
    FormatParserInit init_parser = NULL;
    ParseAudio parse_audio = NULL;
    CleanupParser cleanup_parser = NULL;

    // Load the appropriate dynamic library based on format.
    if (strcmp(format, "WAV") == 0) {
        lib_handle = load_library("libwavparser.so");
    } else if (strcmp(format, "AIFF") == 0) {
        lib_handle = load_library("libaifcpparser.so");
    } else if (strcmp(format, "FLAC") == 0) {
        lib_handle = load_library("libflacparser.so");
    } else if (strcmp(format, "OGG") == 0) {
        lib_handle = load_library("liboggparser.so");
    } else {
        fprintf(stderr, "Unsupported format: %s\n", format);
        return metadata;
    }

    // Retrieve function pointers from the library.
    init_parser = get_symbol(lib_handle, "init_parser");
    parse_audio = get_symbol(lib_handle, "parse_audio");
    cleanup_parser = get_symbol(lib_handle, "cleanup_parser");

    if (!init_parser || !parse_audio || !cleanup_parser) {
        fprintf(stderr, "Failed to load required functions from library\n");
        dlclose(lib_handle);
        return metadata;
    }

    // Initialize the parser.
    void *parser_instance = init_parser();

    // Parse the audio file and extract metadata.
    if (parser_instance != NULL) {
        metadata = parse_audio(parser_instance, file_path);
        strncpy(metadata.format, format, sizeof(metadata.format) - 1);

        // Cleanup after parsing is done.
        cleanup_parser(parser_instance);
    } else {
        fprintf(stderr, "Failed to initialize parser instance\n");
    }

    // Close the library handle.
    dlclose(lib_handle);

    return metadata;
}

// Example main function to demonstrate usage.
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <audio_file_path> <format>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
    const char *format = argv[2];

    AudioMetadata metadata = extract_metadata(file_path, format);

    if (metadata.num_channels > 0) {
        printf("Number of Channels: %d\n", metadata.num_channels);
        printf("Sample Rate: %ld\n", metadata.sample_rate);
        printf("Bit Depth: %d\n", metadata.bit_depth);
        printf("Format: %s\n", metadata.format);
    } else {
        fprintf(stderr, "Failed to extract metadata.\n");
    }

    return EXIT_SUCCESS;
}
```

### Key Features of the Code:

- **Dynamic Library Integration:** The code uses `dlopen` and `dlsym` for loading dynamic libraries and accessing format-specific parsing functions.

- **Error Handling:** It logs detailed messages if an unsupported format is encountered or if any dynamic library-related function fails.

- **Modular Design:** Functions are organized to allow easy addition of support for new audio formats by adding corresponding dynamic libraries and modifying the `extract_metadata` function accordingly.

- **Memory Management:** The code responsibly initializes, uses, and cleans up parser instances to prevent memory leaks.

This implementation provides a foundation that can be further extended with asynchronous processing mechanisms, more detailed error handling, or additional optimizations as required.']

