    PHY_TEST_RX_UE_INFO_TAG info_tag;
    float signal_quality_metric; // Example metric
} LTE_PHY_TEST_RX_UE_INFO_TAG;

// Define the dynamic array structure
typedef struct {
    LTE_PHY_TEST_RX_UE_INFO_TAG *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex; // Mutex for thread safety
} UE_Info_Array;

// Function to initialize the dynamic array
int init_ue_info_array(UE_Info_Array *ue_info_array, size_t initial_capacity) {
    if (!ue_info_array || initial_capacity == 0) return -1;

    ue_info_array->size = 0;
    ue_info_array->capacity = initial_capacity;

    pthread_mutex_init(&ue_info_array->mutex, NULL);
    ue_info_array->array = (LTE_PHY_TEST_RX_UE_INFO_TAG *)malloc(ue_info_array->capacity * sizeof(LTE_PHY_TEST_RX_UE_INFO_TAG));
    if (!ue_info_array->array) {
        pthread_mutex_destroy(&ue_info_array->mutex);
        return -1;
    }

    return 0;
}

// Function to resize the dynamic array
int resize_ue_info_array(UE_Info_Array *ue_info_array, size_t new_capacity) {
    if (!ue_info_array || !new_capacity) return -1;

    pthread_mutex_lock(&ue_info_array->mutex);

    LTE_PHY_TEST_RX_UE_INFO_TAG *new_array = (LTE_PHY_TEST_RX_UE_INFO_TAG *)realloc(ue_info_array->array, new_capacity * sizeof(LTE_PHY_TEST_RX_UE_INFO_TAG));
    if (!new_array) {
        pthread_mutex_unlock(&ue_info_array->mutex);
        return -1;
    }

    ue_info_array->array = new_array;
    ue_info_array->capacity = new_capacity;

    pthread_mutex_unlock(&ue_info_array->mutex);

    return 0;
}

// Function to deallocate the dynamic array
void free_ue_info_array(UE_Info_Array *ue_info_array) {
    if (ue_info_array) {
        pthread_mutex_lock(&ue_info_array->mutex);

        free(ue_info_array->array);
        ue_info_array->array = NULL;
        ue_info_array->size = 0;
        ue_info_array->capacity = 0;

        pthread_mutex_unlock(&ue_info_array->mutex);
        pthread_mutex_destroy(&ue_info_array->mutex);
    }
}

// Example usage
int main() {
    UE_Info_Array ue_info_array;

    if (init_ue_info_array(&ue_info_array, 10) != 0) {
        fprintf(stderr, "Failed to initialize UE info array\n");
        return -1;
    }

    // Simulate updating the array with new data
    pthread_mutex_lock(&ue_info_array.mutex);
    for (size_t i = 0; i < ue_info_array.capacity; ++i) {
        ue_info_array.array[i].info_tag.UE_ID = i;
        snprintf(ue_info_array.array[i].info_tag.RRC_STATE, sizeof(ue_info_array.array[i].info_tag.RRC_STATE), "Connected");
        ue_info_array.array[i].signal_quality_metric = 0.9f; // Example quality
    }
    ue_info_array.size = ue_info_array.capacity;
    pthread_mutex_unlock(&ue_info_array.mutex);

    free_ue_info_array(&ue_info_array);

    return 0;
}
