void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    return new_node;
}

void add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void remove_outdated_entries(LinkedList* list, int age_threshold_seconds) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    Node *prev = NULL, *curr = list->head;

    while (curr) {
        if ((current_time - curr->timestamp) > age_threshold_seconds) {
            Node* to_delete = curr;
            if (prev == NULL) {
                list->head = curr->next;
            } else {
                prev->next = curr->next;
            }
            curr = curr->next;
            free(to_delete);
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *curr = list->head, *next;

    while (curr) {
        next = curr->next;
        free(curr);
        curr = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void periodic_cleanup(LinkedList* list, int age_threshold_seconds, int interval_seconds) {
    while (1) {
        sleep(interval_seconds);
        remove_outdated_entries(list, age_threshold_seconds);
    }
}

int serialize_list(const LinkedList* list, const char* filename) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
        return -1;
    }

    Node* curr = list->head;
    while (curr) {
        fwrite(&curr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        fwrite(&curr->timestamp, sizeof(time_t), 1, file);
        curr = curr->next;
    }

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    return 0;
}

int deserialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    while (fread(&(NFAPI_CRC_INDICATION_PDU_T){}, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        NFAPI_CRC_INDICATION_PDU_T data;
        time_t timestamp;

        fseek(file, -sizeof(NFAPI_CRC_INDICATION_PDU_T), SEEK_CUR);
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

        if (fread(&timestamp, sizeof(time_t), 1, file) != 1) break;

        Node* new_node = create_node(data);
        fseek(file, sizeof(time_t), SEEK_CUR); // Skip the timestamp again for next iteration
        if (!new_node) {
            fclose(file);
            pthread_mutex_unlock(&list->lock);
            return -2;
        }

        new_node->timestamp = timestamp;
        new_node->next = list->head;
        list->head = new_node;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

