#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Assuming this is defined elsewhere in your codebase.
typedef struct {
    // Add relevant fields for NFAPI_CRC_INDICATION_PDU_T here.
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_HARDWARE_CAPACITY 1000
#define USAGE_THRESHOLD_HIGH (MAX_HARDWARE_CAPACITY * 0.8)
#define USAGE_THRESHOLD_LOW (MAX_HARDWARE_CAPACITY * 0.2)

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **pool;
    size_t capacity;
    size_t usage_count;
    pthread_mutex_t lock;
} CRC_Indication_Pool;

void log_message(const char* message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp)-1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, message);
}

CRC_Indication_Pool* create_crc_indication_pool(size_t initial_capacity) {
    if (initial_capacity > MAX_HARDWARE_CAPACITY) {
        log_message("Requested capacity exceeds hardware limit.");
        return NULL;
    }

    CRC_Indication_Pool *pool = malloc(sizeof(CRC_Indication_Pool));
    if (!pool) {
        log_message("Failed to allocate memory for CRC_Indication_Pool.");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->usage_count = 0;
    pool->pool = calloc(pool->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!pool->pool) {
        log_message("Failed to allocate memory for CRC indication PDU pointers.");
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    char message[100];
    snprintf(message, sizeof(message), "Created CRC Indication Pool with capacity: %zu", pool->capacity);
    log_message(message);

    return pool;
}

void destroy_crc_indication_pool(CRC_Indication_Pool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->usage_count; ++i) {
        free(pool->pool[i]);
    }

    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);

    log_message("Destroyed CRC Indication Pool.");
}

int add_crc_pdu(CRC_Indication_Pool *pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pool || !pdu) return -1;

    pthread_mutex_lock(&pool->lock);

    if (pool->usage_count >= pool->capacity) {
        log_message("Exceeded maximum capacity for CRC Indication Pool.");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    if ((float)(pool->usage_count + 1) / pool->capacity > USAGE_THRESHOLD_HIGH) {
        char message[200];
        snprintf(message, sizeof(message), "High usage alert: %zu/%zu PDU structures used.",
                 pool->usage_count + 1, pool->capacity);
        log_message(message);
    }

    pool->pool[pool->usage_count++] = pdu;
    pthread_mutex_unlock(&pool->lock);

    char message[100];
    snprintf(message, sizeof(message), "Added CRC PDU. Current usage: %zu/%zu", pool->usage_count, pool->capacity);
    log_message(message);

    return 0;
}

void resize_crc_indication_pool(CRC_Indication_Pool *pool, size_t new_capacity) {
    if (!pool || new_capacity > MAX_HARDWARE_CAPACITY) return;

    pthread_mutex_lock(&pool->lock);

    if (new_capacity < pool->usage_count) {
        log_message("Cannot reduce capacity below current usage.");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T **new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!new_pool) {
        log_message("Failed to reallocate memory for CRC Indication Pool.");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    pool->capacity = new_capacity;
    pool->pool = new_pool;

    char message[100];
    snprintf(message, sizeof(message), "Resized CRC Indication Pool. New capacity: %zu", new_capacity);
    log_message(message);

    pthread_mutex_unlock(&pool->lock);
}
