    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
};

std::mutex mtx;
std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaPduList;
int configSize = 0;

void logMessage(const std::string& message) {
    static std::ofstream logFile("program.log", std::ios_base::app);
    if (logFile.is_open()) {
        logFile << message << std::endl;
    }
}

bool readConfigFromFile(const std::string &filename, int &size) {
    tinyxml2::XMLDocument doc;
    if (doc.LoadFile(filename.c_str()) != tinyxml2::XML_SUCCESS) {
        logMessage("Error loading XML file.");
        return false;
    }

    auto root = doc.FirstChildElement("Config");
    if (!root) {
        logMessage("Root element not found in XML.");
        return false;
    }

    auto sizeElem = root->FirstChildElement("Size");
    if (sizeElem && sizeElem->QueryIntText(&size) != tinyxml2::XML_SUCCESS) {
        logMessage("Error reading Size from XML.");
        return false;
    }

    return true;
}

NFAPI_CRC_INDICATION_PDU_T createRandomPdu(int index) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = index + 1; // Example value
    pdu.RNTI = index * 2;                  // Example value

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (dis(gen) == 1);

    return pdu;
}

void populateNfaPduList() {
    mtx.lock();
    nfaPduList.clear();

    for (int i = 0; i < configSize; ++i) {
        nfaPduList.push_back(createRandomPdu(i));
    }

    logMessage("NFAPI_CRC_INDICATION_PDU_T list populated.");
    mtx.unlock();
}

void monitorXmlFile(const std::string &filename) {
    while (true) {
        int newSize;
        if (readConfigFromFile(filename, newSize)) {
            std::lock_guard<std::mutex> lock(mtx);
            if (newSize != configSize) {
                logMessage("Configuration size changed.");
                configSize = newSize;
                populateNfaPduList();
            }
        }

        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

int main() {
    const std::string xmlFilename = "config.xml";

    if (!readConfigFromFile(xmlFilename, configSize)) {
        logMessage("Failed to read initial configuration.");
        return 1;
    }

    std::thread monitorThread(monitorXmlFile, xmlFilename);

    // Main application logic here
    // ...

    monitorThread.join();
    return 0;
}
