} Node;

Node* head = NULL;

// Function to create a new node
Node* create_node(int id, time_t timestamp, int cqi, int mcs) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->metric.id = id;
    new_node->metric.timestamp = timestamp;
    new_node->metric.cqi = cqi;
    new_node->metric.mcs = mcs;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new metric
void add_metric(int id, time_t timestamp, int cqi, int mcs) {
    Node* existing = find_metric_by_id(id);
    if (existing) {
        update_metric(existing, timestamp, cqi, mcs);
    } else {
        Node* new_node = create_node(id, timestamp, cqi, mcs);
        new_node->next = head;
        head = new_node;
    }
}

// Function to find a metric by ID
Node* find_metric_by_id(int id) {
    Node* current = head;
    while (current) {
        if (current->metric.id == id) return current;
        current = current->next;
    }
    return NULL;
}

// Function to update an existing metric
void update_metric(Node* node, time_t timestamp, int cqi, int mcs) {
    node->metric.timestamp = timestamp;
    node->metric.cqi = cqi;
    node->metric.mcs = mcs;
}

// Function to retrieve metrics within a specified time range
Node* get_metrics_in_range(time_t start_time, time_t end_time, Node** results) {
    *results = NULL;
    Node* current = head;
    Node* tail = NULL;

    while (current) {
        if (current->metric.timestamp >= start_time && current->metric.timestamp <= end_time) {
            Node* new_node = create_node(current->metric.id, current->metric.timestamp,
                                         current->metric.cqi, current->metric.mcs);
            if (!(*results)) {
                *results = new_node;
            } else {
                tail->next = new_node;
            }
            tail = new_node;
        }
        current = current->next;
    }

    return *results;
}

// Function to free the list
void free_list(Node* head) {
    Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Example of integrating with an external data processing service for batch updates
void process_batch_updates(Node* metrics) {
    // Simulate sending metrics to an external service
    while (metrics) {
        printf("Processing metric ID: %d, Timestamp: %ld\n", metrics->metric.id,
               metrics->metric.timestamp);
        metrics = metrics->next;
    }
}

// Example usage
int main() {
    time_t now = time(NULL);

    add_metric(1, now - 100, 10, 5);
    add_metric(2, now - 200, 12, 7);
    add_metric(1, now - 50, 15, 9); // Update existing metric

    Node* results;
    get_metrics_in_range(now - 150, now, &results);

    process_batch_updates(results);
    free_list(results);
    free_list(head);

    return 0;
}
```

