extern int* rx_ue_info_map;          // Pre-initialized RX UE Information map
extern size_t rx_ue_info_count;      // Number of entries in the RX UE Information map

// Mutex for synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initializeCrcArray(NFAPI_CRC_INDICATION_PDU_T **pdu_array, size_t N, unsigned int seed) {
    if (!pdu_array || N == 0) return -1;

    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_array == NULL) return -2;

    pthread_mutex_lock(&mutex);

    int used_tags[256] = {0}; // Assuming 256 unique tags for simplicity
    size_t filled = 0;

    while (filled < N) {
        for (size_t i = 0; i < rx_ue_info_count && filled < N; ++i) {
            if (!used_tags[rx_ue_info_map[i]]) {
                (*pdu_array)[filled].RX_UE_INFORMATION_TAG = rx_ue_info_map[i];
                used_tags[(*pdu_array)[filled].RX_UE_INFORMATION_TAG] = 1;
                (*pdu_array)[filled].RNTI = getRntiFromDataSource();
                // Set CRC flags using seed and filled index for randomness
                (*pdu_array)[filled].CRC_INDICATION_REL8_TAG = (seed + filled) % 2; 
                filled++;
            }
        }

        // Attempt to refill RX UE Information map from external source if exhausted
        size_t new_count = rx_ue_info_count; // Simulate refilling logic
        if (new_count == rx_ue_info_count) break; // No more data available

        memset(used_tags, 0, sizeof(used_tags)); // Reset used tags for refill
    }

    pthread_mutex_unlock(&mutex);

    // If not all elements were filled due to exhausted resources, free memory and return error
    if (filled < N) {
        free(*pdu_array);
        *pdu_array = NULL;
        return -3;
    }

    return 0; // Success
}

void cleanupCrcArray(NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}
