// Assuming external libraries for secrets management and logging
public class DecryptionService
{
    private static readonly ConcurrentDictionary<string, int> IpAccessLog = new();
    private const int RateLimitThreshold = 10; // Requests per minute
    private readonly string SecretsManagerUrl = "https://secretsmanager.example.com"; // Placeholder URL
    private readonly HttpClient httpClient = new();

    public async Task<string> DecryptMessageAsync(string base64EncodedEncryptedMessage, bool compressOutput = false)
    {
        if (!IsValidBase64(base64EncodedEncryptedMessage))
        {
            LogAttempt("Invalid Base64", IPAddress.UserIP(), "Failure");
            return "Decryption failed: Invalid Base64 encoding.";
        }

        // Fetch the secret key and IV from a secrets manager
        var (key, iv) = await RetrieveKeyAndIVAsync();

        if (iv == null)
        {
            LogAttempt("IV generation required", IPAddress.UserIP(), "Failure");
            return "Decryption failed: Initialization Vector generation error.";
        }

        // Rate limiting check
        if (!CheckRateLimit(IPAddress.UserIP()))
        {
            LogAttempt("Rate limit exceeded", IPAddress.UserIP(), "Failure");
            return "Decryption request rate limited. Please try again later.";
        }

        byte[] encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
        string decryptedMessage;

        // Perform decryption
        using (var tripleDes = new TripleDESCryptoServiceProvider { Key = key, IV = iv, Mode = CipherMode.CBC })
        {
            using var decryptor = tripleDes.CreateDecryptor();
            using var memoryStream = new MemoryStream(encryptedBytes);
            using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
            using var reader = new StreamReader(cryptoStream);

            decryptedMessage = await reader.ReadToEndAsync();
        }

        if (compressOutput)
        {
            decryptedMessage = Compress(decryptedMessage);
        }

        LogAttempt("Decryption successful", IPAddress.UserIP(), "Success");
        return decryptedMessage;
    }

    private async Task<(byte[] key, byte[] iv)> RetrieveKeyAndIVAsync()
    {
        // Placeholder for fetching from a secrets manager
        var keyResponse = await httpClient.GetStringAsync($"{SecretsManagerUrl}/retrieve/key");
        var ivResponse = await httpClient.GetStringAsync($"{SecretsManagerUrl}/retrieve/iv");

        return (Convert.FromBase64String(keyResponse), Convert.FromBase64String(ivResponse));
    }

    private bool CheckRateLimit(string ipAddress)
    {
        if (!IpAccessLog.ContainsKey(ipAddress))
            IpAccessLog[ipAddress] = 0;

        var currentCount = Interlocked.Increment(ref IpAccessLog[ipAddress]);

        // Reset count every minute
        Task.Run(async () =>
        {
            await Task.Delay(TimeSpan.FromMinutes(1));
            Interlocked.Exchange(ref IpAccessLog[ipAddress], 0);
        });

        return currentCount <= RateLimitThreshold;
    }

    private static bool IsValidBase64(string base64EncodedEncryptedMessage)
    {
        byte[] data = Convert.FromBase64String(base64EncodedEncryptedMessage, ignorePadding: true);
        return data.Length % 8 == 0; // Triple DES requires block size of 8 bytes
    }

    private static string Compress(string input)
    {
        using var memoryStream = new MemoryStream();
        using (var gZipStream = new GZipStream(memoryStream, CompressionMode.Compress))
        using (var streamWriter = new StreamWriter(gZipStream))
            streamWriter.Write(input);

        return Convert.ToBase64String(memoryStream.ToArray());
    }

    private void LogAttempt(string message, string ipAddress, string status)
    {
        // Placeholder for centralized logging
        Console.WriteLine($"{DateTime.UtcNow} - {ipAddress} - {status}: {message}");
    }
}

