// Define a linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node();
void free_list(Node** head);
int compare_nodes(const void* a, const void* b);
void log_message(const char* message);
void sort_and_log(Node** head);

// Implementation of the functions
Node* create_node() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new node.");
        return NULL;
    }

    // Generate random data or use a placeholder
    new_node->data.ue_info_tag.rnti = rand();  // Example RNTI value
    new_node->data.rnti = rand();
    new_node->data.crc_indication_rel8_tag.crc_flag = rand() % 2;  // Random CRC flag

    log_message("Node created with random data.");
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
    log_message("All nodes have been freed.");
}

int compare_nodes(const void* a, const void* b) {
    Node* nodeA = *(Node**)a;
    Node* nodeB = *(Node**)b;

    if (nodeA->data.rnti < nodeB->data.rnti) return -1;
    if (nodeA->data.rnti > nodeB->data.rnti) return 1;
    return 0;
}

void log_message(const char* message) {
    printf("LOG: %s\n", message);
}

void sort_and_log(Node** head) {
    if (!head || !*head) return;

    Node* current = *head;
    int node_count = 0;
    while (current != NULL) {
        node_count++;
        current = current->next;
    }

    // Convert linked list to array for sorting
    Node** node_array = malloc(node_count * sizeof(Node*));
    if (!node_array) {
        log_message("Memory allocation failed for node array.");
        return;
    }

    current = *head;
    for (int i = 0; i < node_count; ++i) {
        node_array[i] = current;
        current = current->next;
    }

    qsort(node_array, node_count, sizeof(Node*), compare_nodes);

    // Convert sorted array back to linked list
    for (int i = 0; i < node_count - 1; ++i) {
        node_array[i]->next = node_array[i + 1];
    }
    node_array[node_count - 1]->next = NULL;
    *head = node_array[0];

    free(node_array);
    log_message("Nodes have been sorted and linked list updated.");
}

// Example of using these functions
int main() {
    Node* head = NULL;

    // Create nodes and append them to the list for demonstration purposes
    for (int i = 0; i < 10; ++i) {  // Create 10 nodes as an example
        Node* new_node = create_node();
        if (!new_node) continue;

        if (!head) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    sort_and_log(&head);

    // Clean up
    free_list(&head);

    return 0;
}
