typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

void log_action(const char* action, size_t current_size) {
    time_t now = time(NULL);
    printf("[%s] %s: List size is %zu\n", ctime(&now), action, current_size);
}

DynamicList* create_list(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_SIZE)
        initial_capacity = MAX_INITIAL_CAPACITY;

    DynamicList *list = malloc(sizeof(DynamicList));
    list->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_list_if_needed(DynamicList *list) {
    if (list->size < list->capacity && list->capacity <= MAX_SIZE)
        return;

    size_t new_capacity = list->capacity * 2;
    if (new_capacity > MAX_SIZE)
        new_capacity = MAX_SIZE;

    if (new_capacity > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_array) {
            list->array = new_array;
            list->capacity = new_capacity;
            log_action("Resized list", list->size);
        }
    }
}

int insert_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_SIZE) {
        printf("Max capacity reached. Cannot insert more elements.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    resize_list_if_needed(list);

    list->array[list->size] = element;
    list->size++;
    log_action("Inserted element", list->size);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->array[index];
    log_action("Retrieved element", list->size);

    pthread_mutex_unlock(&list->lock);
    return element;
}

void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    free(list->array);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
