#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint8_t preamble[16];
    uint32_t rach_request_tag;
    char *payload; // Dynamically allocated buffer for message payload
} NFAPI_MESSAGE_T;

typedef struct Node {
    NFAPI_MESSAGE_T message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} MessageCollection;

// Function to create a new node with given message data
Node* create_node(const uint8_t preamble[16], uint32_t rach_request_tag, const char *payload_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    memcpy(new_node->message.preamble, preamble, sizeof(preamble));
    new_node->message.rach_request_tag = rach_request_tag;
    new_node->message.payload = strdup(payload_data);

    if (!new_node->message.payload) {
        free(new_node);
        return NULL;
    }

    new_node->next = NULL;
    return new_node;
}

// Function to add a message to the collection
int add_message(MessageCollection* collection, const uint8_t preamble[16], uint32_t rach_request_tag, const char *payload_data) {
    Node* new_node = create_node(preamble, rach_request_tag, payload_data);
    if (!new_node) return -1;

    if (collection->head == NULL) {
        collection->head = new_node;
    } else {
        Node* current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    collection->count++;
    return 0;
}

// Function to remove a message by RACH_REQUEST_TAG
int remove_message(MessageCollection* collection, uint32_t rach_request_tag) {
    if (collection->head == NULL) return -1;

    Node *current = collection->head, *prev = NULL;
    while (current != NULL && current->message.rach_request_tag != rach_request_tag) {
        prev = current;
        current = current->next;
    }

    if (!current) return -1; // Message not found

    if (prev == NULL) { // Head needs to be removed
        collection->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->message.payload);
    free(current);
    collection->count--;
    return 0;
}

// Function to iterate over all messages and validate them
int validate_messages(const MessageCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        // Example validation: Check if payload length matches tag consistency
        size_t expected_length = current->message.rach_request_tag & 0xFF; // Simplified check
        if (strlen(current->message.payload) != expected_length) {
            printf("Invalid message found with RACH_REQUEST_TAG: %u\n", current->message.rach_request_tag);
            return -1;
        }

        current = current->next;
    }
    return 0; // All messages are valid
}

// Function to free the entire collection and its resources
void free_collection(MessageCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->message.payload);
        free(current);
        current = next;
    }
    collection->head = NULL;
    collection->count = 0;
}

int main() {
    MessageCollection messages = {NULL, 0};

    uint8_t preamble1[16] = {0};
    add_message(&messages, preamble1, 12345, "Payload1");

    uint8_t preamble2[16] = {0};
    add_message(&messages, preamble2, 67890, "Payload2");

    validate_messages(&messages);
    remove_message(&messages, 12345);

    free_collection(&messages);
    return 0;
}
```']

