    }
    pthread_mutex_unlock(&mutex);
}

void resize_dynamic_array(size_t new_size) {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(dynamic_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
