    if (dynamic_array) {
        free(dynamic_array);
        dynamic_array = NULL;
        array_size = current_count = 0;
    }
    pthread_mutex_unlock(&mutex);
}

int exponential_backoff(int attempt) {
    int wait_time = 1 << attempt; // Exponential backoff
    return wait_time * 1000000; // Convert to microseconds
}

