    LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_Message_List;

// Custom memory allocator for the list
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_list(LTE_Message_List *list, size_t max_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = max_capacity;
    list->count = 0;
    list->messages = (LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration*)custom_alloc(max_capacity * sizeof(*list->messages));
}

void destroy_list(LTE_Message_List *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->messages);
}

int insert_message(LTE_Message_List *list, LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration message) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    list->messages[list->count++] = message;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int delete_message(LTE_Message_List *list, int cell_identity) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i].cell_identity == cell_identity) {
            memmove(&list->messages[i], &list->messages[i + 1], (list->count - i - 1) * sizeof(LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration));
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Deleted successfully
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Message not found
}

LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration* retrieve_message(LTE_Message_List *list, int cell_identity) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i].cell_identity == cell_identity) {
            LTE_RRC_MESSAGE_TYPE_RRCConnectionReconfiguration *message = &list->messages[i];
            pthread_mutex_unlock(&list->lock);
            return message;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Message not found
}

// Example usage
