// Define the custom message object
typedef struct {
    int id;                   // Unique identifier for the message
    char protocolHeader[10];  // Protocol-specific header
    char *payload;            // Payload data
    char metadata[20];        // Metadata information
} Message;

// Node for the linked list
typedef struct Node {
    Message msg;
    struct Node* next;
} Node;

// Dynamic array of messages with thread-safe access
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} MessageArray;

// Custom memory allocator functions (simple version)
void* custom_alloc(size_t size);
void custom_free(void* ptr);

// Function to initialize the message array
MessageArray* init_message_array() {
    MessageArray* array = malloc(sizeof(MessageArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Insert a new message into the array
void insert_message(MessageArray* array, Message msg) {
    Node* newNode = custom_alloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    newNode->msg = msg;
    newNode->next = NULL;

    pthread_mutex_lock(&array->lock);

    // Insert at the head for O(1) insertion
    newNode->next = array->head;
    array->head = newNode;

    pthread_mutex_unlock(&array->lock);
}

// Delete a message by id
void delete_message(MessageArray* array, int id) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;

    while (current != NULL && current->msg.id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        // Message not found
        pthread_mutex_unlock(&array->lock);
        return;
    }

    if (prev == NULL) {
        array->head = current->next;  // Head needs to be updated
    } else {
        prev->next = current->next;
    }

    custom_free(current);  // Free the node

    pthread_mutex_unlock(&array->lock);
}

// Retrieve a message by id
Message* retrieve_message(MessageArray* array, int id) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;

    while (current != NULL && current->msg.id != id) {
        current = current->next;
    }

    Message* result = (current == NULL) ? NULL : &current->msg;

    pthread_mutex_unlock(&array->lock);
    return result;
}

// Custom memory allocator - simplistic version
void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    // Additional logic for reducing fragmentation could be added here
    return ptr;
}

void custom_free(void* ptr) {
