    // Logic to handle freeing in a way that reduces fragmentation could go here
}

// Function to destroy the message array and clean up resources
void destroy_message_array(MessageArray* array) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *next;

    while (current != NULL) {
        next = current->next;
        custom_free(current);
        current = next;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    MessageArray* array = init_message_array();

    // Example usage
    Message msg1 = {1, "Header1", "Payload1", "Meta1"};
    insert_message(array, msg1);

    Message *retrieved_msg = retrieve_message(array, 1);
    if (retrieved_msg != NULL) {
        printf("Retrieved message ID: %d\n", retrieved_msg->id);
    }

    delete_message(array, 1);

    destroy_message_array(array);
    return 0;
}
