```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <time.h>

#define MAX_STRUCTS 1000
#define LOG_BUFFER_SIZE 1000
#define RX_UE_INFO_TAG_MAX_LENGTH 128

typedef struct {
    char RX_UE_INFORMATION_TAG[RX_UE_INFO_TAG_MAX_LENGTH];
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    time_t timestamp;
    int num_structs;
} LogEntry;

NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
int current_count = 0;
LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;
sem_t semaphore;
pthread_mutex_t lock;

void initialize() {
    sem_init(&semaphore, 0, 1);
    pthread_mutex_init(&lock, NULL);
}

void add_structure(const char* RX_UE_INFO_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    sem_wait(&semaphore);

    if (current_count >= MAX_STRUCTS || strlen(RX_UE_INFO_TAG) >= RX_UE_INFO_TAG_MAX_LENGTH) {
        sem_post(&semaphore);
        return;
    }

    structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (current_count + 1));
    NFAPI_CRC_INDICATION_PDU_T* new_struct = &structures[current_count];
    strncpy(new_struct->RX_UE_INFORMATION_TAG, RX_UE_INFO_TAG, RX_UE_INFO_TAG_MAX_LENGTH);
    new_struct->RNTI = RNTI;
    new_struct->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    current_count++;

    pthread_mutex_lock(&lock);
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].num_structs = current_count;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
    pthread_mutex_unlock(&lock);

    sem_post(&semaphore);
}

void cleanup() {
    sem_destroy(&semaphore);
    pthread_mutex_destroy(&lock);

    free(structures);
    structures = NULL;
    current_count = 0;

    memset(log_buffer, 0, sizeof(log_buffer));
    log_index = 0;
}

int main() {
    initialize();

    // Example usage
    add_structure("Tag1", 1001, 1234);
    add_structure("Tag2", 1002, 5678);

    cleanup();
    return 0;
}
```

### Key Points:

- **Semaphore for Thread Safety**: A semaphore is used to ensure that only one thread can modify the structures array at a time.

- **Logging Mechanism**: Uses a circular buffer to store log entries with timestamps and current structure count.

- **Memory Management**: `realloc` is used to dynamically manage memory, but consider using a memory pool for better performance in high-concurrency scenarios.

- **Cleanup Function**: Frees allocated memory and resets the state of structures and logs.

This code provides a foundation for managing the described data structures while considering thread safety, logging, and cleanup. Adjustments may be necessary based on specific workload characteristics and concurrency levels.']

