```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int DL_BANDWIDTH_PART;
    int UL_BANDWIDTH_PART;
} BandwidthPart;

typedef struct {
    int PUSCH_Grant_Indication;
} PUSCHGrant;

typedef struct {
    int RNTI;
    BandwidthPart dl_bw;
    BandwidthPart ul_bw;
    PUSCHGrant *pusch_grants;
    size_t grant_count;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t size;
} UEContextArray;

UEContextArray* create_context_array() {
    UEContextArray *array = malloc(sizeof(UEContextArray));
    array->contexts = malloc(INITIAL_CAPACITY * sizeof(UEContext));
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    return array;
}

void resize_if_needed(UEContextArray *array) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->contexts = realloc(array->contexts, array->capacity * sizeof(UEContext));
    }
}

int find_context_index_by_rnti(const UEContextArray *array, int rnti) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->contexts[i].RNTI == rnti) {
            return i;
        }
    }
    return -1;
}

int add_context(UEContextArray *array, int rnti, BandwidthPart dl_bw, BandwidthPart ul_bw, PUSCHGrant *grants, size_t grant_count) {
    if (find_context_index_by_rnti(array, rnti) != -1) {
        return 0; // RNTI already exists
    }

    resize_if_needed(array);

    UEContext new_context;
    new_context.RNTI = rnti;
    new_context.dl_bw = dl_bw;
    new_context.ul_bw = ul_bw;
    new_context.pusch_grants = malloc(grant_count * sizeof(PUSCHGrant));
    memcpy(new_context.pusch_grants, grants, grant_count * sizeof(PUSCHGrant));
    new_context.grant_count = grant_count;

    array->contexts[array->size++] = new_context;
    return 1; // Success
}

int remove_context(UEContextArray *array, int rnti) {
    int index = find_context_index_by_rnti(array, rnti);
    if (index == -1) {
        return 0; // RNTI not found
    }

    free(array->contexts[index].pusch_grants);

    for (size_t i = index; i < array->size - 1; ++i) {
        array->contexts[i] = array->contexts[i + 1];
    }
    array->size--;
    return 1; // Success
}

int update_context(UEContextArray *array, int rnti, BandwidthPart dl_bw, BandwidthPart ul_bw, PUSCHGrant *grants, size_t grant_count) {
    int index = find_context_index_by_rnti(array, rnti);
    if (index == -1) {
        return 0; // RNTI not found
    }

    free(array->contexts[index].pusch_grants);

    array->contexts[index].dl_bw = dl_bw;
    array->contexts[index].ul_bw = ul_bw;
    array->contexts[index].pusch_grants = malloc(grant_count * sizeof(PUSCHGrant));
    memcpy(array->contexts[index].pusch_grants, grants, grant_count * sizeof(PUSCHGrant));
    array->contexts[index].grant_count = grant_count;

    return 1; // Success
}

void free_context_array(UEContextArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->contexts[i].pusch_grants);
    }
    free(array->contexts);
    free(array);
}
```

### Implementation Documentation

- **Data Structure Choice**: A dynamic array (`UEContextArray`) is chosen for its simplicity and efficiency in handling frequent add/remove operations. The capacity doubles when full, ensuring amortized constant time complexity for these operations.

- **Search Mechanism**: Linear search is used to find contexts by RNTI. While this has O(n) complexity, it's efficient given the expectation of unique RNTIs and relatively small array sizes in practice.

- **Memory Management**: Memory is dynamically allocated for each context and its grants. Careful management ensures no memory leaks occur during add/update/remove operations.

- **Scalability Considerations**: The dynamic resizing strategy allows the system to handle an increasing number of UE contexts efficiently.

- **Usability**: Functions are designed with clear interfaces, making it easy to add, remove, or update contexts. Error handling is included for duplicate RNTIs and non-existent contexts.

- **Integration**: This implementation assumes compatibility with external APIs for bandwidth allocation and grant indication updates, which should be handled outside this module.

This design balances efficiency, usability, maintainability, and scalability, making it suitable for real-world network environments."]

