#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int unique_RNTIs_count;
    int error_count;
} CRCList;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int is_unique(RNTI, Node* current) {
    while (current != NULL) {
        if (current->data.RNTI == RNTI) return 0;
        current = current->next;
    }
    return 1;
}

void add_crc_indication(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique(pdu.RNTI, list->head)) {
        log_error("Duplicate RNTI encountered.");
        list->error_count++;
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->unique_RNTIs_count++;
    pthread_mutex_unlock(&list->lock);
}

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand(time(NULL) + (unsigned int)pdu);
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu.RNTI = RNTI;
    pdu.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    generate_random_crcflag(&pdu);
    return pdu;
}

void* update_list(void *arg) {
    CRCList *list = (CRCList *) arg;

    // Simulating external data source retrieval
    for (int i = 0; i < 100; ++i) { 
        NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(rand(), rand() % 1024, rand());
        add_crc_indication(list, pdu);
        usleep(50000); // Simulate delay
    }

    return NULL;
}

CRCList* initialize_list() {
    CRCList *list = (CRCList *)malloc(sizeof(CRCList));
    if (!list) {
        log_error("Memory allocation failed during list initialization.");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->unique_RNTIs_count = 0;
    list->error_count = 0;

    return list;
}

void free_list(CRCList *list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    const int THREAD_COUNT = 5;

    CRCList *crc_list = initialize_list();
    if (!crc_list) return EXIT_FAILURE;

    pthread_t threads[THREAD_COUNT];
    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_create(&threads[i], NULL, update_list, crc_list)) {
            log_error("Thread creation failed.");
            free_list(crc_list);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < THREAD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Unique RNTIs processed: %d\n", crc_list->unique_RNTIs_count);
    printf("Errors encountered: %d\n", crc_list->error_count);

    free_list(crc_list);

    return EXIT_SUCCESS;
}
