pthread_cond_t log_cond = PTHREAD_COND_INITIALIZER;
int log_capacity = 10000; // Example capacity for logs
char *log_buffer = NULL;

void initialize_logging() {
    pthread_mutex_lock(&log_mutex);
    if (!log_buffer) {
        log_buffer = malloc(log_capacity);
        memset(log_buffer, 0, log_capacity);
    }
    pthread_mutex_unlock(&log_mutex);
}

void async_log(const char *message) {
    pthread_mutex_lock(&log_mutex);
    if (strlen(log_buffer) + strlen(message) < log_capacity - 1) {
        strcat(log_buffer, message);
        strcat(log_buffer, "\n");
    }
    pthread_cond_signal(&log_cond); // Notify a dedicated logging thread
    pthread_mutex_unlock(&log_mutex);
}

