        pthread_mutex_lock(&log_mutex);
        pthread_cond_wait(&log_cond, &log_mutex);

        if (strlen(log_buffer) > 0) {
            // Write logs to a file or external system
            printf("%s", log_buffer); // Simulated logging
            memset(log_buffer, 0, log_capacity);
        }
        pthread_mutex_unlock(&log_mutex);
    }
    return NULL;
}

