    for (size_t i = 0; i < N; ++i) {
        nfa_list[i].crc_tag.RX_UE_INFORMATION_TAG = rand() % 10000;
        nfa_list[i].crc_tag.RNTI = rand() % 65536;

        if ((i / group_size) % 2 == 0 && !error_set) { // Randomly set an error in each group
