#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming some external service for TAI updates
typedef struct {
    int tac;
    int plmnId;
} TAI;

// External TAIService simulation
int updateTAIService(int uesid, const TAI* tai) {
    // Simulated service call logic
    return 1;  // Assume success
}

typedef struct UECTX {
    int uesid;
    TAI* tais;
    size_t tai_count;
} UECTX;

// Node synchronization primitives for distributed system
pthread_rwlock_t ctx_lock = PTHREAD_RWLOCK_INITIALIZER;

// UE Context list structure with dynamic resizing capabilities
#define INITIAL_CTX_COUNT 10
typedef struct {
    UECTX** contexts;
    size_t count;
    size_t capacity;
} UEContextList;

// Initialize the context list
UEContextList* createUEContextList() {
    UEContextList* list = (UEContextList*)malloc(sizeof(UEContextList));
    if (!list) return NULL;
    list->contexts = (UECTX**)malloc(INITIAL_CTX_COUNT * sizeof(UECTX*));
    if (!list->contexts) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = INITIAL_CTX_COUNT;
    memset(list->contexts, 0, INITIAL_CTX_COUNT * sizeof(UECTX*));
    return list;
}

// Add a new UE context
int addUEContext(UEContextList* list, int uesid) {
    pthread_rwlock_wrlock(&ctx_lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->uesid == uesid) {
            pthread_rwlock_unlock(&ctx_lock);
            return -1; // UESID already exists
        }
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        UECTX** new_contexts = (UECTX**)realloc(list->contexts, new_capacity * sizeof(UECTX*));
        if (!new_contexts) {
            pthread_rwlock_unlock(&ctx_lock);
            return -1; // Memory allocation failed
        }
        memset(new_contexts + list->capacity, 0, list->capacity * sizeof(UECTX*));
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    UECTX* uctx = (UECTX*)malloc(sizeof(UECTX));
    if (!uctx) {
        pthread_rwlock_unlock(&ctx_lock);
        return -1; // Memory allocation failed
    }

    uctx->uesid = uesid;
    uctx->tais = NULL;
    uctx->tai_count = 0;

    list->contexts[list->count++] = uctx;

    pthread_rwlock_unlock(&ctx_lock);
    return 0;
}

// Remove a UE context by UESID
int removeUEContext(UEContextList* list, int uesid) {
    pthread_rwlock_wrlock(&ctx_lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->uesid == uesid) {
            free(list->contexts[i]->tais);
            free(list->contexts[i]);
            memmove(&list->contexts[i], &list->contexts[i + 1],
                    (list->count - i - 1) * sizeof(UECTX*));
            list->count--;
            pthread_rwlock_unlock(&ctx_lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&ctx_lock);
    return -1; // UESID not found
}

// Retrieve a UE context by UESID
UECTX* getUEContext(const UEContextList* list, int uesid) {
    pthread_rwlock_rdlock(&ctx_lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->uesid == uesid) {
            pthread_rwlock_unlock(&ctx_lock);
            return list->contexts[i];
        }
    }

    pthread_rwlock_unlock(&ctx_lock);
    return NULL;
}

// Add a TAI entry to a UE context
int addTAIEntry(UEContextList* list, int uesid, const TAI* tai) {
    if (!updateTAIService(uesid, tai)) {
        return -1; // External service failure
    }

    pthread_rwlock_wrlock(&ctx_lock);
    UECTX* ctx = getUEContext(list, uesid);

    if (ctx) {
        size_t new_size = (ctx->tai_count + 1) * sizeof(TAI);
        TAI* new_taivals = (TAI*)realloc(ctx->tais, new_size);
        if (!new_taivals) {
            pthread_rwlock_unlock(&ctx_lock);
            return -1; // Memory allocation failed
        }
        ctx->tais = new_taivals;
        memcpy(&ctx->tais[ctx->tai_count], tai, sizeof(TAI));
        ctx->tai_count++;
    }

    pthread_rwlock_unlock(&ctx_lock);
    return 0;
}

// Remove a TAI entry from a UE context
int removeTAIEntry(UEContextList* list, int uesid, const TAI* tai) {
    pthread_rwlock_wrlock(&ctx_lock);
    UECTX* ctx = getUEContext(list, uesid);

    if (ctx && ctx->tais) {
        for (size_t i = 0; i < ctx->tai_count; ++i) {
            if (ctx->tais[i].tac == tai->tac && ctx->tais[i].plmnId == tai->plmnId) {
                memmove(&ctx->tais[i], &ctx->tais[i + 1],
                        (ctx->tai_count - i - 1) * sizeof(TAI));
                ctx->tai_count--;
                TAI* new_taivals = (TAI*)realloc(ctx->tais, ctx->tai_count * sizeof(TAI));
                if (!new_taivals && ctx->tai_count > 0) {
                    pthread_rwlock_unlock(&ctx_lock);
                    return -1; // Memory reallocation failed
                }
                ctx->tais = new_taivals;
                break;
            }
        }
    }

    pthread_rwlock_unlock(&ctx_lock);
    return 0;
}

// Clean up the context list
void freeUEContextList(UEContextList* list) {
    pthread_rwlock_wrlock(&ctx_lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]) {
            free(list->contexts[i]->tais);
            free(list->contexts[i]);
        }
    }

    free(list->contexts);
    pthread_rwlock_unlock(&ctx_lock);

    pthread_rwlock_destroy(&ctx_lock);
    free(list);
}

// Main function for demonstration purposes only
int main() {
    UEContextList* list = createUEContextList();
    if (!list) return 1;

    addUEContext(list, 101);
    TAI tai = { .tac = 5, .plmnId = 20411 };
    addTAIEntry(list, 101, &tai);

    UECTX* ctx = getUEContext(list, 101);
    if (ctx) {
        printf("UESID: %d, TAIs: %zu\n", ctx->uesid, ctx->tai_count);
        for (size_t i = 0; i < ctx->tai_count; ++i) {
            printf("\ttac: %d, plmnId: %d\n", ctx->tais[i].tac, ctx->tais[i].plmnId);
        }
    }

    removeUEContext(list, 101);

    freeUEContextList(list);
    return 0;
}
