    if (E > MAX_EVENTS) {
        log_error("Requested number of events exceeds maximum allowed.");
        return NULL;
    }

    StateTransitionEvent **events = malloc(E * sizeof(StateTransitionEvent *));
    if (!events) {
        log_error("Failed to allocate memory for state transition events.");
        return NULL;
    }

    for (int i = 0; i < E; ++i) {
        pthread_mutex_lock(&mutex); // Ensure thread safety during allocation

        StateTransitionEvent *event = malloc(sizeof(StateTransitionEvent));
        if (!event) {
            log_error("Failed to allocate memory for a state transition event.");
            break;
        }

        // Example assignments, these could be based on real data or more complex logic
        event->state_tag = (MAC_entity_state_tag)(i % 2);  // Rotate through states A, B, etc.
        event->frame_number = i + 1;

        size_t lc_size = INITIAL_CHANNEL_SIZE;
        event->logical_channels = malloc(lc_size * sizeof(LC_Signal_Pair));
        if (!event->logical_channels) {
            log_error("Failed to allocate memory for logical channels.");
            free(event);
            break;
        }

        // Simulate realistic signal strengths with at least one significant interference
        for (int j = 0; j < L; ++j) {
            if (j == L - 1) {  // Ensure the last channel has a significant interference
                event->logical_channels[j].signal_strength = -100.0;
            } else {
                event->logical_channels[j].signal_strength = rand() % 20 + (-50); // Random signal strength from -50 to -30
            }
            event->logical_channels[j].lc_id = j; 
        }

        event->num_logical_channels = L;

        events[i] = event;

        pthread_mutex_unlock(&mutex);
    }

    return events;
}

