#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdatomic.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    atomic_size_t size;
    Node* head;
    pthread_mutex_t db_lock; // For DB synchronization
} CRCList;

void init_list(CRCList* list) {
    atomic_store(&list->size, 0);
    list->head = NULL;
    pthread_mutex_init(&list->db_lock, NULL);
}

bool is_rnti_in_list(CRCList* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return true;
        }
        current = current->next;
    }
    return false;
}

bool add_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (atomic_load(&list->size) >= MAX_LIST_SIZE || is_rnti_in_list(list, pdu.RNTI)) {
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return false;
    }

    new_node->data = pdu;
    new_node->next = list->head;

    atomic_fetch_add(&list->size, 1);
    list->head = new_node;

    // Simulate database storage with a mutex lock
    pthread_mutex_lock(&list->db_lock);
    // Database operation: Store RNTI and CRC_INDICATION_REL8_TAG
    printf("Storing to DB: RNTI=%u, CRCFLAG=%d\n", pdu.RNTI, pdu.tag.CRCFLAG);
    pthread_mutex_unlock(&list->db_lock);

    return true;
}

bool remove_from_list(CRCList* list, uint16_t rnti) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        return false; // Not found
    }

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    atomic_fetch_sub(&list->size, 1);
    free(current);

    pthread_mutex_lock(&list->db_lock);
    // Database operation: Remove RNTI
    printf("Removing from DB: RNTI=%u\n", rnti);
    pthread_mutex_unlock(&list->db_lock);

    return true;
}

void iterate_and_print_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG=%u, CRCFLAG=%d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.tag.CRCFLAG);
        current = current->next;
    }
}

void cleanup_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    atomic_store(&list->size, 0);
    pthread_mutex_destroy(&list->db_lock);
}

int main() {
    CRCList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .tag = {.CRCFLAG = rand() % 2} };
    add_to_list(&list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 101, .tag = {.CRCFLAG = rand() % 2} };
    add_to_list(&list, pdu2);

    iterate_and_print_list(&list);

    remove_from_list(&list, 100);
    iterate_and_print_list(&list);

    cleanup_list(&list);
    return 0;
}
```

