['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set to 0 or 1 for demonstration purposes
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t RNTI;
    uint8_t DL_BANDWIDTH_PART;
    uint8_t UL_BANDWIDTH_PART;
    int *active_PUSCH_Grant_Indications; // List of active grants
    size_t grant_count;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UE_Context_Manager;

// Utility function to generate a random CRCFLAG value
int generate_random_crcflag() {
    return rand() % 2; // Returns either 0 or 1
}

// Initialize the manager with a given initial capacity
void initialize_ue_context_manager(UE_Context_Manager *manager, size_t initial_capacity) {
    manager->contexts = malloc(sizeof(LTE_UE_Context) * initial_capacity);
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the dynamic array when capacity is reached
void resize_context_array(UE_Context_Manager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_UE_Context *new_array = realloc(manager->contexts, sizeof(LTE_UE_Context) * new_capacity);
    if (new_array) {
        manager->contexts = new_array;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize context array");
        exit(EXIT_FAILURE);
    }
}

// Add a new UE Context
void add_ue_context(UE_Context_Manager *manager, uint16_t rnti, uint8_t dl_bandwidth, uint8_t ul_bandwidth) {
    pthread_mutex_lock(&manager->lock);

    // Check if RNTI already exists
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            printf("RNTI %d already exists.\n", rnti);
            return;
        }
    }

    // Resize array if necessary
    if (manager->count >= manager->capacity) {
        resize_context_array(manager);
    }

    LTE_UE_Context new_context = {rnti, dl_bandwidth, ul_bandwidth, NULL, 0};
    manager->contexts[manager->count++] = new_context;

    pthread_mutex_unlock(&manager->lock);
}

// Remove a UE Context by RNTI
void remove_ue_context(UE_Context_Manager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].RNTI == rnti) {
            free(manager->contexts[i].active_PUSCH_Grant_Indications);
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    sizeof(LTE_UE_Context) * (manager->count - i - 1));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    printf("RNTI %d not found.\n", rnti);
    pthread_mutex_unlock(&manager->lock);
}

// Update a UE Context by RNTI
void update_ue_context(UE_Context_Manager *manager, uint16_t rnti, uint8_t dl_bandwidth, uint8_t ul_bandwidth) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].RNTI == rnti) {
            manager->contexts[i].DL_BANDWIDTH_PART = dl_bandwidth;
            manager->contexts[i].UL_BANDWIDTH_PART = ul_bandwidth;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    printf("RNTI %d not found for update.\n", rnti);
    pthread_mutex_unlock(&manager->lock);
}

// Retrieve a UE Context by RNTI
LTE_UE_Context* get_ue_context_by_rnti(UE_Context_Manager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->contexts[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Generate CRC Indication PDU list for each context
void generate_crc_indications(UE_Context_Manager *manager, NFAPI_CRC_INDICATION_PDU_T **indications, size_t *num_indications) {
    size_t total_indications = 0;

    pthread_mutex_lock(&manager->lock);

    // Calculate required memory for indications
    for (size_t i = 0; i < manager->count; ++i) {
        total_indications += 1; // One indication per context
    }

    *indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * total_indications);
    if (!*indications) {
        perror("Failed to allocate memory for indications");
        pthread_mutex_unlock(&manager->lock);
        exit(EXIT_FAILURE);
    }

    size_t index = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        (*indications)[index].RX_UE_INFORMATION_TAG = rand() % 65535; // Random value
        (*indications)[index].RNTI = manager->contexts[i].RNTI;
        (*indications)[index].CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
        index++;
    }

    *num_indications = total_indications;

    pthread_mutex_unlock(&manager->lock);
}

// Clean up the context manager
void cleanup_ue_context_manager(UE_Context_Manager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i].active_PUSCH_Grant_Indications);
    }
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
}

// Main function to demonstrate usage
int main() {
    UE_Context_Manager manager;
    initialize_ue_context_manager(&manager, 10);

    add_ue_context(&manager, 1001, 3, 5);
    add_ue_context(&manager, 1002, 4, 6);

    remove_ue_context(&manager, 1001);
    update_ue_context(&manager, 1002, 7, 8);

    NFAPI_CRC_INDICATION_PDU_T *indications = NULL;
    size_t num_indications = 0;

    generate_crc_indications(&manager, &indications, &num_indications);

    for (size_t i = 0; i < num_indications; ++i) {
        printf("RNTI: %d, RX TAG: %d, CRCFLAG: %d\n",
               indications[i].RNTI,
               indications[i].RX_UE_INFORMATION_TAG,
               indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    free(indications);
    cleanup_ue_context_manager(&manager);

    return 0;
}
```

### Assumptions and Design Choices
- The use of a dynamic array (`contexts`) ensures efficient access times.
- A mutex lock (`pthread_mutex_t`) is used to ensure thread safety, accommodating multi-threaded environments.
- Memory reallocation doubles the capacity when necessary, balancing between too frequent allocations and excessive memory usage.
- Each UE context includes a list for active PUSCH grants, initialized as needed.
- The `generate_crc_indications` function produces CRC indications with random RX tags and flags to simulate variability in network conditions.

### Limitations
- Random number generation is used for simplicity; real implementations might need deterministic or more secure methods.
- Memory allocation errors are handled by terminating the program. More robust error handling could be implemented based on specific requirements.
- The current implementation assumes a maximum size for dynamic arrays and does not handle situations where memory cannot be expanded due to system constraints.

This code is optimized for scenarios with frequent operations, ensuring efficient data access while maintaining thread safety and scalability.']

