```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_ENTRIES 10000

typedef struct {
    uint16_t rnti;
    char rx_ue_information_tag[64]; // Adjust size as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Function declarations
DynamicArray* init_dynamic_array();
int add_or_update_entry(DynamicArray *dyn_array, uint16_t rnti, const char *rx_ue_information_tag);
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(DynamicArray *dyn_array, uint16_t rnti);
void free_dynamic_array(DynamicArray *dyn_array);
int is_rx_ue_info_tag_unique(DynamicArray *dyn_array, const char *tag);

// Function implementations
DynamicArray* init_dynamic_array() {
    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->size = 0;
    dyn_array->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

int expand_capacity(DynamicArray *dyn_array) {
    size_t new_capacity = dyn_array->capacity * 2;
    if (new_capacity > MAX_ENTRIES) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;

    return 0;
}

int add_or_update_entry(DynamicArray *dyn_array, uint16_t rnti, const char *rx_ue_information_tag) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size >= dyn_array->capacity && expand_capacity(dyn_array) != 0) {
        pthread_mutex_unlock(&dyn_array->lock);
        return -1; // Memory allocation failure
    }

    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (dyn_array->array[i].rnti == rnti || strcmp(dyn_array->array[i].rx_ue_information_tag, rx_ue_information_tag) == 0) {
            strncpy(dyn_array->array[i].rx_ue_information_tag, rx_ue_information_tag, sizeof(dyn_array->array[i].rx_ue_information_tag));
            pthread_mutex_unlock(&dyn_array->lock);
            return i; // Update existing entry
        }
    }

    if (!is_rx_ue_info_tag_unique(dyn_array, rx_ue_information_tag)) {
        pthread_mutex_unlock(&dyn_array->lock);
        return -2; // Duplicate RX_UE_INFORMATION_TAG
    }

    dyn_array->array[dyn_array->size].rnti = rnti;
    strncpy(dyn_array->array[dyn_array->size].rx_ue_information_tag, rx_ue_information_tag, sizeof(dyn_array->array[0].rx_ue_information_tag));

    ++dyn_array->size;

    pthread_mutex_unlock(&dyn_array->lock);
    return dyn_array->size - 1; // Return index of new entry
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(DynamicArray *dyn_array, uint16_t rnti) {
    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (dyn_array->array[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *entry = &dyn_array->array[i];
            pthread_mutex_unlock(&dyn_array->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&dyn_array->lock);
    return NULL; // Entry not found
}

int is_rx_ue_info_tag_unique(DynamicArray *dyn_array, const char *tag) {
    for (size_t i = 0; i < dyn_array->size; ++i) {
        if (strcmp(dyn_array->array[i].rx_ue_information_tag, tag) == 0) {
            return 0;
        }
    }
    return 1;
}

void free_dynamic_array(DynamicArray *dyn_array) {
    pthread_mutex_lock(&dyn_array->lock);

    free(dyn_array->array);
    dyn_array->size = 0;
    dyn_array->capacity = 0;

    pthread_mutex_unlock(&dyn_array->lock);
    pthread_mutex_destroy(&dyn_array->lock);

    free(dyn_array);
}

// Logging function (simple example)
void log_message(const char *message) {
    // Consider using a logging library for more advanced features
    printf("%s\n", message); 
}
```

### Key Points:
- **Dynamic Array**: Uses a dynamic array to store entries with initial capacity and expands when necessary. This avoids the overhead of frequent linked list node allocations.
- **Thread Safety**: Utilizes a mutex (`pthread_mutex_t`) for concurrent access, preventing race conditions.
- **Memory Management**: Handles memory allocation failures by returning error codes and gracefully exits functions if allocations fail.
- **Uniqueness Check**: Ensures `RX_UE_INFORMATION_TAG` is unique before adding or updating an entry.
- **Logging**: Provides a simple logging mechanism to track operations (this can be expanded with more robust libraries).
- **Efficiency & Scalability**: Balances between array and linked list benefits, optimizing for access speed while allowing dynamic resizing.']

