// Summary report structure
typedef struct {
    int success_count;
    int failure_count;
} Report;

// Thread-safe dynamic list management function
Report manage_nfa_crc_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t capacity, size_t M) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Report report = {0, 0};

    if (capacity == 0 || list == NULL) {
        log_error("Invalid parameters: capacity or list is NULL.");
        return report;
    }

    // Function to allocate a single element
    auto allocate_element = [&report](int id) -> NFAPI_CRC_INDICATION_PDU_T* {
        pthread_mutex_lock(&mutex);
        char *msg;

        if (id < 0 || id >= capacity) {
            msg = "Failed allocation: Index out of bounds.";
            log_error(msg);
            report.failure_count++;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!element) {
                msg = "Failed allocation: Memory allocation error.";
                log_error(msg);
                report.failure_count++;
            } else {
                element->id = id;
                snprintf(element->data, sizeof(element->data), "Data for CRC ID %d", id);
                *list[id] = *element; // Store the allocated structure
                free(element);  // Free immediately after storing to avoid fragmentation
                msg = "Successful allocation for CRC ID ";
                log_info(msg);
                log_info(element->data);
                report.success_count++;
            }
        }

        pthread_mutex_unlock(&mutex);
        return NULL;
    };

    pthread_t threads[M];

    // Create M threads to handle allocations in parallel
    for (size_t i = 0; i < M && i < capacity; ++i) {
        if (pthread_create(&threads[i], NULL, 
                           reinterpret_cast<void*(*)(void*)>(allocate_element), 
                           (void*)(long)i)) {
            log_error("Failed to create thread.");
            report.failure_count++;
        }
    }

    for (size_t i = 0; i < M && i < capacity; ++i) {
        if (pthread_join(threads[i], NULL)) {
            log_error("Failed to join thread.");
            report.failure_count++;
        }
    }

    pthread_mutex_destroy(&mutex);

    // Log summary report
    char summary[256];
    snprintf(summary, sizeof(summary), "Summary: %d successes, %d failures",
             report.success_count, report.failure_count);
    log_info(summary);

    return report;
}

// Example usage:
int main() {
    size_t capacity = 100;  // Maximum number of elements
    size_t M = 10;          // Number of threads to run in parallel

    NFAPI_CRC_INDICATION_PDU_T *list[capacity] = {NULL};

    Report report = manage_nfa_crc_list(list, capacity, M);

    return 0;
}
