typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t current_size;
    size_t max_capacity;
    pthread_mutex_t lock; // Mutex for thread safety
} NFAPI_CrcArrayManager;

// Initialize the manager
void init_crc_array_manager(NFAPI_CrcArrayManager *manager, size_t initial_capacity) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->current_size = 0;
    manager->max_capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the array
void resize_crc_array(NFAPI_CrcArrayManager *manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->array = new_array;
    manager->max_capacity = new_capacity;
}

// Add a new element
void add_crc_element(NFAPI_CrcArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->current_size == manager->max_capacity) {
        resize_crc_array(manager, manager->max_capacity * 2);
    }

    manager->array[manager->current_size] = element;
    manager->current_size++;

    // Log the addition
    printf("Added element: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", element.RX_UE_INFORMATION_TAG, element.RNTI);

    pthread_mutex_unlock(&manager->lock);
}

// Remove an element by index
void remove_crc_element(NFAPI_CrcArrayManager *manager, size_t index) {
    if (index >= manager->current_size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = index; i < manager->current_size - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->current_size--;

    // Log the removal
    printf("Removed element at index %zu\n", index);

    pthread_mutex_unlock(&manager->lock);
}

// Update an existing element by index
void update_crc_element(NFAPI_CrcArrayManager *manager, size_t index, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (index >= manager->current_size) {
