} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

void resize_if_needed(CRCList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_items) {
            fprintf(stderr, "Failed to resize list\n");
            exit(EXIT_FAILURE);
        }

        list->items = new_items;
        list->capacity = new_capacity;
    }
}

void add_crc_item(CRCList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (item.RNTI > MAX_RNTI_VALUE || item.CRCFLAG > CRCFLAG_VALID_MAX) {
        fprintf(stderr, "Invalid RNTI or CRCFLAG\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    resize_if_needed(list);
    list->items[list->count++] = item;
    pthread_mutex_unlock(&list->lock);
}

void serialize_crc_list(CRCList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->items, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_crc_list(CRCList *list, FILE *file) {
    size_t count;

    pthread_mutex_lock(&list->lock);
    fread(&count, sizeof(size_t), 1, file);

    if (count > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* new_items = realloc(list->items, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_items) {
            fprintf(stderr, "Failed to resize list during deserialization\n");
            exit(EXIT_FAILURE);
        }

        list->items = new_items;
        list->capacity = count;
    }

    fread(list->items, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    list->count = count;
    pthread_mutex_unlock(&list->lock);
}

void initialize_crc_list(CRCList *list) {
    list->items = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list->items) {
        fprintf(stderr, "Failed to allocate memory for CRC list\n");
        exit(EXIT_FAILURE);
    }

    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void cleanup_crc_list(CRCList *list) {
    free(list->items);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CRCList list;
    initialize_crc_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T example = {1, 12345, 67890, 0};
    add_crc_item(&list, example);

    FILE *file = fopen("crc_list.bin", "wb");
    serialize_crc_list(&list, file);
    fclose(file);

    CRCList new_list;
    initialize_crc_list(&new_list);

    file = fopen("crc_list.bin", "rb");
    deserialize_crc_list(&new_list, file);
    fclose(file);

    cleanup_crc_list(&list);
    cleanup_crc_list(&new_list);

    return 0;
}
