```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 10
#define MAX_INTERFACES 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->size = 0;
    da->capacity = initial_capacity;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    da->size = 0;
    da->capacity = 0;
}

int expand_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        return -1;
    }
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

void add_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        if (expand_dynamic_array(da) != 0) {
            perror("Failed to expand array");
            pthread_mutex_unlock(&da->lock);
            return;
        }
    }
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);
}

void garbage_collect(DynamicArray *da, int (*is_valid)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&da->lock);
    size_t write_index = 0;
    for (size_t i = 0; i < da->size; ++i) {
        if (is_valid(da->array[i])) {
            da->array[write_index++] = da->array[i];
        }
    }
    da->size = write_index;
    pthread_mutex_unlock(&da->lock);
}

int is_valid_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Define validation logic here
    return 1; // Assume all PDUs are valid for now
}

void periodic_garbage_collection(DynamicArray *da, int interval_sec) {
    while (1) {
        sleep(interval_sec);
        garbage_collect(da, is_valid_pdu);
    }
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(int interface_id) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL) + interface_id); // Seed based on interface ID
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Random value for demonstration
    pdu.RNTI = rand() % 1000;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    return pdu;
}

void *manage_network_interfaces(void *arg) {
    DynamicArray da;
    init_dynamic_array(&da, 10);

    for (int i = 0; i < MAX_INTERFACES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu(i);
        add_pdu(&da, pdu);
    }

    return NULL;
}

void start_network_management() {
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, manage_network_interfaces, NULL) != 0) {
            perror("Failed to create thread");
        }
    }

    DynamicArray da;
    init_dynamic_array(&da, 10);
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, periodic_garbage_collection, &da);

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
    pthread_cancel(gc_thread); // Terminate garbage collection thread

    free_dynamic_array(&da);
}

int main() {
    start_network_management();
    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses `pthread_mutex_t` for synchronizing access to the dynamic array.
- **Dynamic Array Management:** Supports automatic resizing and periodic garbage collection.
- **Random PDU Generation:** Simulates random data generation with seed-based randomness.
- **Graceful Handling of Failures:** Includes error checking on memory allocation and expansion.
- **Scalability Considerations:** Designed to handle multiple interfaces and threads efficiently.']

