#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_CACHE_SIZE 10
#define MAX_IP_LENGTH 16

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[MAX_IP_LENGTH];
    struct in_addr ip_address;
    time_t timestamp;
} DNSCacheEntry;

DNSCacheEntry dns_cache[MAX_CACHE_SIZE];
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the DNS cache
void init_dns_cache() {
    memset(dns_cache, 0, sizeof(DNSCacheEntry) * MAX_CACHE_SIZE);
}

// Helper function for finding and updating a cached entry
int update_dns_cache(const char* hostname, struct in_addr ip_address) {
    pthread_mutex_lock(&cache_mutex);

    int found = -1;
    time_t current_time = time(NULL);

    // Update or insert logic
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (dns_cache[i].hostname[0] == '\0') { // Empty slot found
            strcpy(dns_cache[i].hostname, hostname);
            dns_cache[i].ip_address = ip_address;
            dns_cache[i].timestamp = current_time;
            pthread_mutex_unlock(&cache_mutex);
            return i;  // New entry index
        } else if (strcmp(dns_cache[i].hostname, hostname) == 0) { // Cache hit
            dns_cache[i].ip_address = ip_address;
            dns_cache[i].timestamp = current_time;
            found = i;
            break;
        }
    }

    pthread_mutex_unlock(&cache_mutex);
    return found;
}

// Function to get IP address for a hostname, using cache if available
int resolve_hostname(const char* hostname, struct in_addr* ip_address) {
    // First check the cache
    pthread_mutex_lock(&cache_mutex);

    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (dns_cache[i].hostname[0] != '\0' && strcmp(dns_cache[i].hostname, hostname) == 0) {
            if ((current_time - dns_cache[i].timestamp) < 300) { // Cache valid for 5 minutes
                *ip_address = dns_cache[i].ip_address;
                pthread_mutex_unlock(&cache_mutex);
                return 1; // Success from cache
            }
        }
    }

    pthread_mutex_unlock(&cache_mutex);

    struct hostent* host_info = gethostbyname(hostname);
    if (!host_info) {
        fprintf(stderr, "DNS resolution failed for hostname: %s\n", hostname);
        return 0;
    }

    *ip_address = *(struct in_addr*)host_info->h_addr_list[0];
    update_dns_cache(hostname, *ip_address);

    return 1; // Success from DNS
}

// Function to dynamically generate NFAPI_CRC_INDICATION_PDU_T structures and handle DNS resolution
int* generate_nfapi_crc_indication_pdu(int num_pdus, const char* hostname) {
    if (num_pdus <= 0) {
        fprintf(stderr, "Invalid number of PDUs requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for PDUs.\n");
        return NULL;
    }

    struct in_addr ip_address;
    u_char* resolved_ip = malloc(MAX_IP_LENGTH);
    if (resolved_ip == NULL || !resolve_hostname(hostname, &ip_address)) {
        free(pdus);
        free(resolved_ip);
        fprintf(stderr, "Failed to resolve IP address for hostname: %s\n", hostname);
        return NULL;
    }

    memcpy(resolved_ip, &(ip_address.s_addr), 4);

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pdus[i].RNTI = rand() % 1000000;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdus[i].CRCFLAG = rand() % 2; // Random CRC flag
    }

    printf("Resolved IP: %s\n", inet_ntoa(ip_address));
    free(resolved_ip);
    return (int*)pdus; // Cast to int* as requested
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <num_pdus> <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_dns_cache();

    int num_pdus = atoi(argv[1]);
    const char* hostname = argv[2];

    int *result = generate_nfapi_crc_indication_pdu(num_pdus, hostname);
    if (!result) {
        fprintf(stderr, "Failed to generate PDUs.\n");
        return EXIT_FAILURE;
    }

    // Assuming the result is used here

    free(result); // Free the allocated memory for PDUs
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` ensures thread safety when accessing shared DNS cache.
- **DNS Caching**: Uses a simple in-memory array to store and lookup recently resolved hostnames. 
- **Error Handling**: Handles DNS resolution failures by returning an error message, allowing the program to continue running or fail gracefully.
- **Resource Management**: Ensures memory is freed properly to prevent leaks.

This implementation balances complexity with maintainability and performance under concurrent access scenarios while providing caching for efficiency.']

