} NFAPI_CRC_INDICATION_PDU_T;

#define NUM_THREADS 4

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* cache[NUM_THREADS] = {NULL};

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_pdu(int count) {
    pthread_t thread_id;
    int thread_num = (int)(thread_id / NUM_THREADS);

    pthread_mutex_lock(&lock);
    if (!cache[thread_num]) {
        cache[thread_num] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
        if (!cache[thread_num]) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = cache[thread_num];
    pthread_mutex_unlock(&lock);

    for (int i = 0; i < count; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        pdu_array[i].RNTI = rand() % 5000; // Example value
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    // Validate the integrity of data
    for (int i = 0; i < count; ++i) {
        if (!pdu_array[i].RX_UE_INFORMATION_TAG || !pdu_array[i].RNTI ||
            (pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 1 && 
             pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0)) {
            free(pdu_array);
            return NULL;
        }
    }

    return pdu_array;
}

void release_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int thread_num) {
    pthread_mutex_lock(&lock);
    if (pdu_array == cache[thread_num]) {
        free(pdu_array);
        cache[thread_num] = NULL;
    }
    pthread_mutex_unlock(&lock);
}

// Example function to demonstrate usage
void process_pdu_data(int count) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_and_populate_crc_pdu(count);
    if (pdu_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    // Process data...

    int thread_num = 0; // Assume single-threaded for this example
    release_crc_pdu(pdu_array, thread_num);
}

int main() {
    process_pdu_data(10);
    return 0;
}
```

