    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPICRCArray;

// Function prototypes
NFAPICRCArray* init_nfa_crc_array(size_t initial_capacity);
void free_nfa_crc_array(NFAPICRCArray* arr);
int resize_nfa_crc_array(NFAPICRCArray* arr, size_t new_capacity);
int add_nfa_crc_indication_pdu(NFAPICRCArray* arr);

// Initialize the array with a given capacity
NFAPICRCArray* init_nfa_crc_array(size_t initial_capacity) {
    NFAPICRCArray* arr = (NFAPICRCArray*)malloc(sizeof(NFAPICRCArray));
    if (!arr) return NULL;

    arr->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

// Free the allocated resources
void free_nfa_crc_array(NFAPICRCArray* arr) {
    if (arr) {
        pthread_mutex_lock(&arr->mutex);
        free(arr->array);
        pthread_mutex_unlock(&arr->mutex);
        pthread_mutex_destroy(&arr->mutex);
        free(arr);
    }
}

// Resize the array to a new capacity
int resize_nfa_crc_array(NFAPICRCArray* arr, size_t new_capacity) {
    if (!arr || new_capacity <= arr->capacity) return -1;

    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return -1;

    pthread_mutex_lock(&arr->mutex);
    arr->array = temp;
    arr->capacity = new_capacity;
    pthread_mutex_unlock(&arr->mutex);

    return 0;
}

// Add a new NFAPI_CRC_INDICATION_PDU_T to the array
int add_nfa_crc_indication_pdu(NFAPICRCArray* arr) {
    if (!arr) return -1;

    pthread_mutex_lock(&arr->mutex);

    // Resize if necessary
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        if (resize_nfa_crc_array(arr, new_capacity) != 0) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
    }

    // Initialize a new entry
    NFAPI_CRC_INDICATION_PDU_T* pdu = &arr->array[arr->size++];
    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example initialization
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Example usage
int main() {
    srand(time(NULL));

    NFAPICRCArray* crc_array = init_nfa_crc_array(10);

    for (int i = 0; i < 20; ++i) { // Add more elements than initial capacity to test resizing
        if (add_nfa_crc_indication_pdu(crc_array) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
            free_nfa_crc_array(crc_array);
            return EXIT_FAILURE;
        }
    }

