typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 4

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random CRCFLAG
int generate_random_crc_flag() {
    return rand() % 2; // Randomly set to 0 or 1
}

// Thread-safe function to create and populate the list of structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pds(unsigned int n, unsigned int *error) {
    if (n == 0 || error == NULL) {
        *error = 1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        *error = 2;
        return NULL;
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = n < MAX_THREADS ? n : MAX_THREADS;

    for (int i = 0; i < thread_count; ++i) {
        unsigned int start_index = i * (n / thread_count);
        unsigned int end_index = (i == thread_count - 1) ? n : start_index + (n / thread_count);

        pthread_create(&threads[i], NULL, [](void* arg) -> void* {
            unsigned int* indices = (unsigned int*)arg;
            for (int j = 0; j < 2; ++j) { // Each thread handles two segments
                unsigned int start = indices[2 * j];
                unsigned int end = indices[2 * j + 1];

                pthread_mutex_lock(&lock);
                for (unsigned int k = start; k < end && k < n; ++k) {
                    ((NFAPI_CRC_INDICATION_PDU_T*)arg)[k].RX_UE_INFORMATION_TAG = rand();
                    ((NFAPI_CRC_INDICATION_PDU_T*)arg)[k].RNTI = rand();
                    ((NFAPI_CRC_INDICATION_PDU_T*)arg)[k].CRC_TAG.CRCFLAG = generate_random_crc_flag();
                }
                pthread_mutex_unlock(&lock);
            }
            return NULL;
        }, (void*)&pdu_list);

    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    *error = 0;
    return pdu_list;
}

// Function to free the list of structures
void free_nfa_pds(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    if (pdu_list != NULL) {
        free(pdu_list);
    }
}
