['Below is a C implementation of a dynamic list to manage `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring thread safety, efficient memory management, and robust error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with a mutex lock for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCIndicationList;

CRCIndicationList* create_list() {
    CRCIndicationList* list = malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void destroy_list(CRCIndicationList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_pdu(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !pdu) return -1;

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return -2;

    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int delete_pdu_by_rnti(CRCIndicationList* list, uint16_t rnti) {
    if (!list || !rnti) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Not found
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Node* query_pdu_by_rnti_range(CRCIndicationList* list, uint16_t rnti_start, uint16_t rnti_end) {
    if (!list || rnti_start > rnti_end) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && !(rnti_start <= current->data.RNTI && current->data.RNTI <= rnti_end)) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current; // Caller is responsible for freeing the nodes
}

// Example unit test
void test_crc_list() {
    CRCIndicationList* list = create_list();
    if (!list) {
        printf("Failed to create list\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, {.CRCFLAG = 1}};
    insert_pdu(list, pdu1);

    Node* queried_node = query_pdu_by_rnti_range(list, 90, 110);
    if (queried_node && queried_node->data.RNTI == 100) {
        printf("Query successful\n");
    } else {
        printf("Query failed\n");
