#define MAX_UES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to check if an array of RNTIs contains a unique value
int is_unique_RNTI(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    for (int i = 0; i < count; ++i) {
        if (pdus[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Function to generate random CRCFLAG
void set_random_CRCFLAG(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->CRCFLAG = rand() % 2; // Randomly sets CRCFLAG to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T* manage_pdu_array(int num_users, uint32_t ue_info_tag) {
    if (num_users <= 0 || num_users > MAX_UES) {
        fprintf(stderr, "Error: Invalid number of users.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    uint16_t rnti_pool[MAX_UES];
    srand(time(NULL));

    for (int i = 0; i < num_users; ++i) {
        // Simulate fetching RNTI from an external service
        uint16_t rnti = rand() % MAX_UES + 1;

        if (!is_unique_RNTI(rnti, pdus, i)) {
            fprintf(stderr, "Error: Duplicate RNTI detected.\n");
            free(pdus);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        rnti_pool[i] = rnti; // Store unique RNTIs

        pdus[i].RX_UE_INFORMATION_TAG = ue_info_tag;
        pdus[i].RNTI = rnti;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random value for tag
        set_random_CRCFLAG(&pdus[i]);
    }

    pthread_mutex_unlock(&lock);

    return pdus;
}

int main() {
    int num_users = 10;
    uint32_t ue_info_tag = 12345;

