void log_performance_metrics(const char* message) {
    printf("%s\n", message);
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    log_memory_usage(sizeof(LinkedList));
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    log_performance_metrics("Linked list destroyed");
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || !pthread_mutex_lock(&list->lock)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_performance_metrics("Memory allocation failed");
        return;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    log_memory_usage(sizeof(Node));
}

void manage_nfa_list(LinkedList* list, int N) {
