<?php

function authenticateAndRetrieveUserInfo($userId, $apiKey) {
    session_start();

    if (isset($_SESSION['access_token']) && $_SESSION['token_expiry'] > time()) {
        $accessToken = $_SESSION['access_token'];
    } else {
        $accessToken = getAccessToken($apiKey);
        if ($accessToken === false) {
            return ['error' => 'Authentication failed.'];
        }

        // Store in session with expiry
        $_SESSION['access_token'] = $accessToken;
        $_SESSION['token_expiry'] = time() + 3600; // Set token validity for 1 hour
    }

    $userInfo = getUserInfo($accessToken);

    if (isset($userInfo['error'])) {
        return ['error' => 'Failed to retrieve user information.'];
    }

    return $userInfo;
}

function getAccessToken($apiKey) {
    $url = "https://oauth.server.com/token";
    $data = [
        'grant_type' => 'client_credentials',
        'client_id'  => 'your_client_id',
        'client_secret' => $apiKey
    ];

    $options = [
        'http' => [
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data)
        ]
    ];

    $context = stream_context_create($options);
    $result = file_get_contents($url, false, $context);

    if ($result === FALSE) {
        return false;
    }

    $response = json_decode($result, true);

    return isset($response['access_token']) ? $response['access_token'] : false;
}

function getUserInfo($accessToken) {
    // Simple caching mechanism using a file-based approach
    $cacheFile = "user_info_cache.json";

    if (file_exists($cacheFile) && time() - filemtime($cacheFile) < 300) { // Cache valid for 5 minutes
        return json_decode(file_get_contents($cacheFile), true);
    }

    $url = "https://api.server.com/userinfo";

    $options = [
        'http' => [
            'header'  => "Authorization: Bearer $accessToken\r\n",
            'method'  => 'GET'
        ]
    ];

    $context = stream_context_create($options);
    $result = file_get_contents($url, false, $context);

    if ($result === FALSE) {
        return ['error' => 'Network error.'];
    }

    $userInfo = json_decode($result, true);

    // Cache user info
    file_put_contents($cacheFile, json_encode($userInfo));

    return $userInfo;
}
