#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

// Define the structure for TCP_NODELAY_OPTIONS
typedef struct {
    int socket_id;
    bool nagle_algorithm_enabled;
    time_t last_modified_timestamp;
} TCP_NODELAY_OPTION;

// Define a node for the linked list
typedef struct Node {
    TCP_NODELAY_OPTION option;
    struct Node* next;
} Node;

// Define the dynamic array structure with mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray* arr) {
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
}

// Add or update an entry based on socket ID
void addOrUpdateEntry(DynamicArray* arr, int socket_id, bool nagle_enabled) {
    Node** current = &(arr->head);

    pthread_mutex_lock(&(arr->lock));

    while (*current) {
        if ((*current)->option.socket_id == socket_id) {
            // Update existing entry
            (*current)->option.nagle_algorithm_enabled = nagle_enabled;
            (*current)->option.last_modified_timestamp = time(NULL);
            pthread_mutex_unlock(&(arr->lock));
            return;
        }
        current = &((*current)->next);
    }

    // Add new entry
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&(arr->lock));
        return; // Handle malloc failure as needed
    }

    newNode->option.socket_id = socket_id;
    newNode->option.nagle_algorithm_enabled = nagle_enabled;
    newNode->option.last_modified_timestamp = time(NULL);
    newNode->next = NULL;

    *current = newNode;
    pthread_mutex_unlock(&(arr->lock));
}

// Delete an entry based on socket ID
void deleteEntry(DynamicArray* arr, int socket_id) {
    Node** current = &(arr->head);

    pthread_mutex_lock(&(arr->lock));

    while (*current) {
        if ((*current)->option.socket_id == socket_id) {
            Node* toDelete = *current;
            *current = (*current)->next;
            free(toDelete);
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&(arr->lock));
}

// Clean up the dynamic array
void cleanupDynamicArray(DynamicArray* arr) {
    Node* current = arr->head;

    while (current) {
        Node* toDelete = current;
        current = current->next;
        free(toDelete);
    }

    pthread_mutex_destroy(&(arr->lock));
}

// Example usage
int main() {
    DynamicArray arr;
    initDynamicArray(&arr);

    addOrUpdateEntry(&arr, 1, true);
    addOrUpdateEntry(&arr, 2, false);
    deleteEntry(&arr, 1);

    cleanupDynamicArray(&arr);
    return 0;
}
```

