#define MAX_RETRIES 5
#define BACKOFF_BASE 100 // in milliseconds

typedef struct {
    int header;
    int payload_id;
    time_t timestamp;
} FrameManagementMessage;

typedef struct {
    FrameManagementMessage* frames;
    size_t count;
    size_t capacity;
} NetworkInterface;

// Function prototypes
int initialize_network_interface(NetworkInterface* interface, size_t num_frames);
void free_network_interface(NetworkInterface* interface);

// Helper functions
static int allocate_memory(NetworkInterface* interface, size_t new_capacity) {
    FrameManagementMessage* new_frames = realloc(interface->frames, sizeof(FrameManagementMessage) * new_capacity);
    if (!new_frames) {
        return -1; // Memory allocation failure
    }
    memset(new_frames + interface->capacity, 0, (new_capacity - interface->capacity) * sizeof(FrameManagementMessage));
    interface->frames = new_frames;
    interface->capacity = new_capacity;
    return 0;
}

static int populate_fmm(FrameManagementMessage* fmm) {
    // Simulate setting up headers and payload identifiers
    fmm->header = rand() % 256; // Random header for demonstration purposes
    fmm->payload_id = rand();   // Unique identifier
    fmm->timestamp = time(NULL);
    return 0;
}

static int send_fmm_with_retry(NetworkInterface* interface, FrameManagementMessage* fmm) {
    int attempt = 0;
    while (attempt < MAX_RETRIES) {
        if (rand() % 10 == 0) { // Simulate intermittent connectivity issues
            printf("Failed to send FMM. Attempting retry...\n");
            usleep(BACKOFF_BASE * (1 << attempt)); // Exponential backoff
            attempt++;
            continue;
        }
        // Simulate sending FMM over the network interface
        return 0; // Success
    }
    fprintf(stderr, "Failed to send FMM after %d retries.\n", MAX_RETRIES);
    return -1;
}

int initialize_network_interface(NetworkInterface* interface, size_t num_frames) {
    if (num_frames == 0) {
        return -2; // Invalid number of frames
    }

    srand(time(NULL)); // Seed random number generator

    interface->frames = NULL;
    interface->count = 0;
    interface->capacity = 0;

    for (size_t i = 0; i < num_frames; ) {
        if (interface->capacity <= i) {
            size_t new_capacity = interface->capacity > 0 ? interface->capacity * 2 : 1;
            if (allocate_memory(interface, new_capacity)) {
                fprintf(stderr, "Memory allocation failed. Operating in degraded mode.\n");
                break;
            }
        }

        FrameManagementMessage* fmm = &interface->frames[i];
        populate_fmm(fmm);

        int send_status = send_fmm_with_retry(interface, fmm);
        if (send_status == 0) {
            i++;
        } else {
            interface->count++; // Buffering FMM
            fprintf(stderr, "Buffered an incoming FMM due to send failure.\n");
        }
    }

    return 0;
}

void free_network_interface(NetworkInterface* interface) {
    if (interface && interface->frames) {
        free(interface->frames);
        interface->frames = NULL;
        interface->count = 0;
        interface->capacity = 0;
    }
}
