// Custom memory pool management structures
#define MEMORY_POOL_SIZE 1024 * 1024 // Example size of 1MB
static unsigned char memory_pool[MEMORY_POOL_SIZE];
static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t memory_offset = 0;

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&memory_mutex);
    if (memory_offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&memory_mutex);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[memory_offset];
    memory_offset += size;
    pthread_mutex_unlock(&memory_mutex);
    return ptr;
}

void custom_free(void) {
    pthread_mutex_lock(&memory_mutex);
    memset(memory_pool, 0, MEMORY_POOL_SIZE); // Reset the pool
    memory_offset = 0; // Reset offset to start
    pthread_mutex_unlock(&memory_mutex);
}

// Logging levels
typedef enum {
    LOG_ERROR,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;

LogLevel current_log_level = LOG_ERROR;

void log_message(LogLevel level, const char* message) {
    if (level <= current_log_level) {
        printf("%s\n", message); // Placeholder for actual logging mechanism
    }
}

// List management structures and functions
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

PduList pdu_list = { .head = NULL, .lock = PTHREAD_MUTEX_INITIALIZER };

// Function to check if RNTI is unique in the list
int is_rnti_unique(uint16_t rnti) {
    pthread_mutex_lock(&pdu_list.lock);
    Node* current = pdu_list.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&pdu_list.lock);
            return 0; // RNTI is not unique
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pdu_list.lock);
    return 1; // RNTI is unique
}

// Function to add a new PDU to the list
void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!is_rnti_unique(pdu->RNTI)) {
        log_message(LOG_ERROR, "Duplicate RNTI detected");
        return; // Duplicate found, handle gracefully
    }

    Node* new_node = (Node*)custom_alloc(sizeof(Node));
    if (new_node == NULL) {
        log_message(LOG_ERROR, "Memory allocation failed for new PDU node");
        return;
    }

    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    pthread_mutex_lock(&pdu_list.lock);
    new_node->next = pdu_list.head;
    pdu_list.head = new_node;
    pthread_mutex_unlock(&pdu_list.lock);
}

// Function to initialize and populate the list with random PDU structures
void initialize_pdu_list(size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 65536;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.crc_indication_rel8_tag.CRCFLAG = rand() & 1;

        add_pdu(&pdu);
    }
}

// Main function demonstrating usage
int main() {
    initialize_pdu_list(1000); // Example initialization with 1000 PDUs
    custom_free(); // Reset memory pool for reuse

    return 0;
}
