#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

// Assume these types are defined elsewhere according to system specifications
typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_INITIAL_SIZE 1024

// Memory pool structure for efficient memory management
typedef struct {
    size_t element_size;
    void* start;
    void* current;
    size_t total_size;
} MemoryPool;

// Dynamic list structure with thread safety mechanisms
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_rwlock_t r_lock;
    bool stop_flag;
} ConcurrentDynamicList;

MemoryPool* create_memory_pool(size_t element_size, size_t total_elements);
void destroy_memory_pool(MemoryPool* pool);

ConcurrentDynamicList* init_dynamic_list(size_t initial_capacity);
bool add_to_dynamic_list(ConcurrentDynamicList* list, NFAPI_CRC_INDICATION_PDU_T item);
void free_dynamic_list(ConcurrentDynamicList* list);
void resize_dynamic_list(ConcurrentDynamicList* list, size_t new_capacity);

// Thread-safe function to get a unique RNTI
uint16_t generate_unique_rnti(pthread_mutex_t* rnti_lock, uint16_t* existing_rntis, size_t count);

void monitor_packet_loss_and_integrity();
void report_statistics(ConcurrentDynamicList* list);
void compact_memory(MemoryPool* pool);

// Implementation of the functions

MemoryPool* create_memory_pool(size_t element_size, size_t total_elements) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->element_size = element_size;
    pool->total_size = element_size * total_elements;
    pool->start = malloc(pool->total_size);
    pool->current = pool->start;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->start);
    free(pool);
}

ConcurrentDynamicList* init_dynamic_list(size_t initial_capacity) {
    ConcurrentDynamicList* list = malloc(sizeof(ConcurrentDynamicList));
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->r_lock, NULL);

    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), initial_capacity);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)pool->start;
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

bool add_to_dynamic_list(ConcurrentDynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->stop_flag) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == item.RNTI) {
            printf("Warning: Duplicate RNTI detected. Entry not added.\n");
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    if (list->count >= list->capacity) {
