// Define the structure for CRC Indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // This will be logically determined
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for a dynamic array
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic Array Structure
typedef struct {
    Node* head;
    atomic_size_t size; // Atomic counter to manage concurrent access
    pthread_mutex_t lock; // Mutex for locking mechanism, if needed
} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->head = NULL;
    atomic_init(&array->size, 0);
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_node(Node* node) {
    Node* temp;
    while (node != NULL) {
        temp = node;
        node = node->next;
        free(temp);
    }
}

NFAPI_CRC_INDICATION_PDU_T calculate_crcflag(uint16_t RNTI, time_t current_time) {
    // Logic to determine CRCFLAG based on RNTI and current system time
    return (RNTI ^ (uint32_t)(current_time % 256)) & 0xFF;
}

void add_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle out-of-memory condition
        return;
    }
    pdu.CRCFLAG = calculate_crcflag(pdu.RNTI, time(NULL));

    pthread_mutex_lock(&array->lock);
    new_node->data = pdu;
    new_node->next = array->head;
    array->head = new_node;
    atomic_fetch_add(&array->size, 1);
    pthread_mutex_unlock(&array->lock);
}

void remove_pdu(DynamicArray* array) {
    if (pthread_mutex_trylock(&array->lock) == 0) { // Try to lock
        if (array->head != NULL) {
            Node* temp = array->head;
            array->head = array->head->next;
            free(temp);
            atomic_fetch_sub(&array->size, 1);
        }
        pthread_mutex_unlock(&array->lock);
    }
}

void garbage_collect(DynamicArray* array) {
    // Periodically clean up unused entries
    while (pthread_mutex_trylock(&array->lock) == 0) { // Try to lock
        if (atomic_load(&array->size) > 1000) { // Arbitrary threshold for example
            remove_pdu(array);
        }
        pthread_mutex_unlock(&array->lock);
    }
}

void handle_out_of_memory() {
    // Implement callback mechanism to handle out-of-memory condition gracefully
}

// Example usage function, demonstrating integration and operation
void manage_pdus(DynamicArray* array) {
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1234 };
    add_pdu(array, pdu);
    garbage_collect(array); // Periodic cleanup

    // Handle potential memory issues
    handle_out_of_memory();
}

void free_dynamic_array(DynamicArray* array) {
    free_node(array->head);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
