typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    _Atomic int CRCFLAG; // Using atomic for thread-safe flag setting
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;

    return dyn_array;
}

void destroy_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        free(dyn_array);
    }
}

int resize_dynamic_array(DynamicArray *dyn_array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;
    return 0;
}

int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (dyn_array->count >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity ? dyn_array->capacity * 2 : 1;
        if (resize_dynamic_array(dyn_array, new_capacity)) return -1;
    }

    dyn_array->array[dyn_array->count++] = element;
    return 0;
}

int get_element(const DynamicArray *dyn_array, size_t index, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (index >= dyn_array->count) return -1;

    *element = dyn_array->array[index];
    return 0;
}

void serialize_dynamic_array(const char *filename, const DynamicArray *dyn_array) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&dyn_array->count, sizeof(size_t), 1, file);
    fwrite(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), dyn_array->count, file);

    fclose(file);
}

int deserialize_dynamic_array(const char *filename, DynamicArray **out_dyn_array) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    DynamicArray *dyn_array = create_dynamic_array(count);
    if (!dyn_array) {
        fclose(file);
        return -1;
    }

    dyn_array->count = count;
    if (fread(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file) != count) {
        destroy_dynamic_array(dyn_array);
        fclose(file);
        return -1;
    }

    *out_dyn_array = dyn_array;
    fclose(file);
    return 0;
}

int main() {
    DynamicArray *dyn_array = create_dynamic_array(10);
    if (!dyn_array) {
        fprintf(stderr, "Failed to create dynamic array.\n");
        return EXIT_FAILURE;
    }

    // Populate the array
    for (size_t i = 0; i < 15; ++i) { // Adding more than initial capacity to test resizing
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.tag.RX_UE_INFORMATION_TAG = i;
        pdu.tag.RNTI = i + 1;
        atomic_store(&pdu.CRCFLAG, rand() % 2); // Randomly set CRCFLAG

        if (add_element(dyn_array, pdu) != 0) {
            fprintf(stderr, "Failed to add element.\n");
            destroy_dynamic_array(dyn_array);
            return EXIT_FAILURE;
        }
    }

    // Serialize the array
    serialize_dynamic_array("array.bin", dyn_array);

    // Deserialize into a new array
    DynamicArray *loaded_dyn_array = NULL;
    if (deserialize_dynamic_array("array.bin", &loaded_dyn_array) != 0) {
        fprintf(stderr, "Failed to deserialize dynamic array.\n");
        destroy_dynamic_array(dyn_array);
        return EXIT_FAILURE;
    }

    // Clean up
    destroy_dynamic_array(dyn_array);
    destroy_dynamic_array(loaded_dyn_array);

    return EXIT_SUCCESS;
}
