// Custom hash function to generate pseudo-random value for CRCFLAG
uint16_t custom_hash(uint32_t rnti) {
    uint16_t hash = 5381;
    const char *str = (const char *)&rnti;
    while (*str)
        hash = ((hash << 5) + hash) + *(unsigned char *)str++;
    return hash % 65536; // Use modulo to ensure the value fits into a uint16_t
}

// Thread-safe logging function
void log_message(const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_indication_pdu(size_t N, RX_UE_INFORMATION_T *rx_ue_information_array) {
    if (N == 0) return NULL;

    // Calculate the required memory size
    size_t mem_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(mem_size);
    if (!pdu_array) {
        log_message("Memory allocation failed");
        return NULL;
    }

    // Populate each structure
    for (size_t i = 0; i < N; ++i) {
        pdu_array[i].rx_ue_information.RNTI = rx_ue_information_array[i].RNTI;

        // Handle missing or malformed data gracefully
        if (pdu_array[i].rx_ue_information.RNTI == 0) {
            log_message("Malformed RNTI detected");
            free(pdu_array);
            return NULL;
        }

        pdu_array[i].crc_indication_rel8_tag.CRCFLAG = custom_hash(pdu_array[i].rx_ue_information.RNTI);
    }

    // Log memory usage and performance metrics
    log_message("Memory allocated for NFAPI_CRC_INDICATION_PDU_T array");

    return pdu_array;
}

// Function to verify the integrity of the data
void verify_crc_integrity(NFAPI_CRC_INDICATION_PDU_T *pdu_array, size_t N) {
