        if (expected_crcflag != pdu_array[i].crc_indication_rel8_tag.CRCFLAG) {
            log_message("CRC integrity check failed for index: ");
            // Include a mechanism to handle the failure appropriately
        }
    }

    log_message("CRC integrity verification completed");
}

