    if (!EVP_CIPHER_CTX_init(&ctx)) {
        return NULL; // Failed to initialize context
    }

    const EVP_CIPHER *cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0 || strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3(); // EDE and EDE3 use the same function
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb64();
    } else if (strcmp(mode, "NULL") == 0) {
        cipher = EVP_null();
    }

    if (!cipher) {
        EVP_CIPHER_CTX_cleanup(&ctx);
        return NULL; // Invalid mode
    }

    EVP_CIPHER_CTX_set_cipher(&ctx, cipher);
    return EVP_CIPHER_CTX_cipher(&ctx);
}
