#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[256];
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG; // Assume it's an integer for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_entries;
} CRCList;

CRCList* create_crc_list(size_t max_entries) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_entries = max_entries;

    return list;
}

int is_rnti_unique(CRCList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

int insert_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI not unique
    }

    if (list->count >= list->max_entries) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Key Points:
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management**: Efficiently manages memory by reusing nodes and freeing them when the list is destroyed.
- **Dynamic Configuration**: Allows for runtime configuration of `MAX_ENTRIES`.
- **Unique RNTI Check**: Ensures each `RNTI` is unique before insertion.
- **Error Handling**: Returns specific error codes for different failure scenarios.

This implementation provides a foundation for managing dynamic lists with concurrency, ensuring data integrity and efficient operations."]

