NFAPI_CRC_INDICATION_PDU_T* initialize_pdu_array(const char* filename, size_t* num_items) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Determine file size
    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    if (filesize <= 0) {
        fprintf(stderr, "Empty or invalid file\n");
        fclose(file);
        return NULL;
    }

    // Estimate initial allocation based on file size and structure size
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t initial_capacity = filesize / struct_size;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(initial_capacity * struct_size);
    if (!pdu_array) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    // Read file into array
    size_t items_read = 0;
    while (items_read < initial_capacity && !feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = &pdu_array[items_read];

        if (fread(&current_pdu->ue_info, sizeof(UE_INFO_TAG), 1, file) != 1 ||
            fread(&current_pdu->crc_rel8, sizeof(CRC_INDICATION_REL8_TAG), 1, file) != 1) {
            perror("Error reading from file");
            break;
        }

        current_pdu->crc_rel8.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        items_read++;
    }

    fclose(file);

    if (items_read < initial_capacity && !feof(file)) {
        fprintf(stderr, "Unexpected end of file\n");
    } else if (ferror(file)) {
        perror("File read error");
    }

    *num_items = items_read;
    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}
