int retry_allocation(size_t size);

DataPacket* initialize_data_packets(int num_packets) {
    if (num_packets <= 0 || num_packets > MAX_PACKETS) {
        fprintf(stderr, "Invalid number of packets requested.\n");
        return NULL;
    }

    srand(time(NULL));

    DataPacket *packets = (DataPacket *)malloc(num_packets * sizeof(DataPacket));
    if (!packets) {
        log_packet_processing("Failed to allocate memory for DataPackets.");
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        packets[i].packet_id = i + 1;
        packets[i].timestamp = time(NULL);

        int payload_size = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1);
        packets[i].payload_size = payload_size;

        if (!retry_allocation(payload_size)) {
            fprintf(stderr, "Failed to allocate memory for packet %d after retries.\n", i + 1);
            free_data_packets(packets, num_packets);
            return NULL;
        }
    }

    log_packet_processing("Successfully initialized DataPackets.");
    return packets;
}

int retry_allocation(size_t size) {
    unsigned char *payload = (unsigned char *)malloc(size);
    int retries = 0;

    while (!payload && retries < 3) { // Retry up to 3 times
        log_packet_processing("Memory allocation failed, retrying...");
        payload = (unsigned char *)malloc(size);
        ++retries;
    }

    if (payload) {
        return (int)payload; // Successful allocation
    } else {
        log_packet_processing("Final memory allocation failure.");
        return 0; // Allocation ultimately failed
    }
}

void free_data_packets(DataPacket *packets, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}

