// Mock memory pool allocation function
void* allocate_from_pool(size_t size) {
    return malloc(size);
}

// Periodic garbage collection mechanism
void* garbage_collector(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        // Perform cleanup, e.g., removing unused structures
        printf("Garbage collector running...\n");
        pthread_mutex_unlock(&lock);
        sleep(5); // Run every 5 seconds
    }
}

void initialize_list(size_t initial_size) {
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list_size = initial_size;
}

void populate_list(size_t num_entries) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_entries; ++i) {
        if ((list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) <= num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(pdu_list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_list) {
                fprintf(stderr, "Memory reallocation failed\n");
                pthread_mutex_unlock(&lock);
                return;
            }
            pdu_list = new_list;
            list_size++;
        }

        // Populate with random data
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 1000;
        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

