               pdu_list[i].RX_UE_INFORMATION_TAG, pdu_list[i].RNTI,
               pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    pthread_mutex_unlock(&lock);
}

void* thread_function(void* arg) {
    size_t num_entries = *(size_t*)arg;
    populate_list(num_entries);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&lock, NULL);

    initialize_list(10); // Initial allocation for 10 entries

    pthread_t threads[MAX_THREADS];
    size_t thread_workloads[] = {5, 7, 3, 9, 6, 4, 8, 2, 1, 10};

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collector, NULL);

    for (int i = 0; i < MAX_THREADS && i < sizeof(thread_workloads) / sizeof(thread_workloads[0]); ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &thread_workloads[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS && i < sizeof(thread_workloads) / sizeof(thread_workloads[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    free(pdu_list);
    pthread_mutex_destroy(&lock);

    return 0;
}
