```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int MEASUREMENT_ID;
    float SINR;
    float RSRP;
} MEASUREMENT_REPORT_ENTRY;

typedef struct MeasurementReport {
    MEASUREMENT_REPORT_ENTRY entry;
    struct MeasurementReport *next;
} MeasurementReport;

typedef struct {
    int UEID;
    char RRC_STATE[16];
    MeasurementReport *measurementListHead;
} UEContext;

// Function prototypes
void addMeasurementReport(UEContext *ueContext, MEASUREMENT_REPORT_ENTRY newEntry);
void serializeUEContext(const UEContext *ueContext, FILE *file);
int deserializeUEContext(UEContext **ueContext, const char *filename);
void freeUEContext(UEContext *ueContext);

// Function to add a measurement report entry
void addMeasurementReport(UEContext *ueContext, MEASUREMENT_REPORT_ENTRY newEntry) {
    MeasurementReport *newNode = (MeasurementReport *)malloc(sizeof(MeasurementReport));
    if (!newNode) return;

    newNode->entry = newEntry;
    newNode->next = ueContext->measurementListHead;
    ueContext->measurementListHead = newNode;
}

// Function to serialize a UEContext into a binary file
void serializeUEContext(const UEContext *ueContext, FILE *file) {
    if (!ueContext || !file) return;

    fwrite(&ueContext->UEID, sizeof(ueContext->UEID), 1, file);
    size_t stateLength = strlen(ueContext->RRC_STATE) + 1;
    fwrite(&stateLength, sizeof(stateLength), 1, file);
    fwrite(ueContext->RRC_STATE, sizeof(char), stateLength, file);

    MeasurementReport *current = ueContext->measurementListHead;
    int entryCount = 0;

    while (current) {
        entryCount++;
        current = current->next;
    }

    fwrite(&entryCount, sizeof(entryCount), 1, file);

    current = ueContext->measurementListHead;
    while (current) {
        fwrite(&(current->entry.MEASUREMENT_ID), sizeof(current->entry.MEASUREMENT_ID), 1, file);
        fwrite(&(current->entry.SINR), sizeof(current->entry.SINR), 1, file);
        fwrite(&(current->entry.RSRP), sizeof(current->entry.RSRP), 1, file);
        current = current->next;
    }
}

// Function to deserialize a UEContext from a binary file
int deserializeUEContext(UEContext **ueContext, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    *ueContext = (UEContext *)malloc(sizeof(UEContext));
    if (!*ueContext) {
        fclose(file);
        return -1;
    }

    fread(&((*ueContext)->UEID), sizeof((*ueContext)->UEID), 1, file);

    size_t stateLength;
    fread(&stateLength, sizeof(stateLength), 1, file);
    (*ueContext)->RRC_STATE[stateLength] = '\0';
    fread((*ueContext)->RRC_STATE, sizeof(char), stateLength, file);

    int entryCount;
    fread(&entryCount, sizeof(entryCount), 1, file);

    (*ueContext)->measurementListHead = NULL;
    for (int i = 0; i < entryCount; ++i) {
        MEASUREMENT_REPORT_ENTRY newEntry;
        fread(&newEntry.MEASUREMENT_ID, sizeof(newEntry.MEASUREMENT_ID), 1, file);
        fread(&newEntry.SINR, sizeof(newEntry.SINR), 1, file);
        fread(&newEntry.RSRP, sizeof(newEntry.RSRP), 1, file);

        addMeasurementReport(*ueContext, newEntry);
    }

    fclose(file);
    return 0;
}

// Function to free memory allocated for a UEContext
void freeUEContext(UEContext *ueContext) {
    if (!ueContext) return;

    MeasurementReport *current = ueContext->measurementListHead;
    while (current) {
        MeasurementReport *next = current->next;
        free(current);
        current = next;
    }

    free(ueContext);
}

int main() {
    // Example usage
    UEContext *context = (UEContext *)malloc(sizeof(UEContext));
    if (!context) return -1;

    context->UEID = 12345;
    strcpy(context->RRC_STATE, "CONNECTED");

    MEASUREMENT_REPORT_ENTRY entry1 = { .MEASUREMENT_ID = 1, .SINR = -10.5f, .RSRP = -110.0f };
    addMeasurementReport(context, entry1);

    FILE *file = fopen("uecontext.bin", "wb");
    if (file) {
        serializeUEContext(context, file);
        fclose(file);
    }

    UEContext *loadedContext = NULL;
    if (deserializeUEContext(&loadedContext, "uecontext.bin") == 0) {
        // Successfully loaded context
    }

    freeUEContext(context);
    freeUEContext(loadedContext);

    return 0;
}
```

This code handles dynamic memory allocation for `UEContext` and its associated measurement reports. It also includes functions to serialize and deserialize these structures to and from a binary file, ensuring data integrity and consistency. The serialization format is designed for scalability and performance, with careful consideration of memory management and error handling.']

