#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTS 10000

typedef struct {
    uint16_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    NFAPI_CRC_INDICATION_PDU_T nfa_api_crc_indication_pdu;
} NFAPI_Structure;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_Structure* allocate_structures(size_t count, int persist_to_disk, const char* file_path) {
    pthread_mutex_lock(&lock);

    if (count > MAX_STRUCTS) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_Structure *structures = (NFAPI_Structure *)malloc(count * sizeof(NFAPI_Structure));
    if (!structures) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        structures[i].crc_indication_rel8_tag.RNTI = rand() % 65536;
        structures[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand() % 256;
        structures[i].nfa_api_crc_indication_pdu.CRCFLAG = rand() % 2;
    }

    if (persist_to_disk) {
        FILE *file = fopen(file_path, "wb");
        if (!file) {
            free(structures);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        size_t written = fwrite(structures, sizeof(NFAPI_Structure), count, file);
        fclose(file);

        if (written != count) {
            free(structures);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    return structures;
}

void deallocate_structures(NFAPI_Structure* structures) {
    if (!structures) return;

    pthread_mutex_lock(&lock);
    free(structures);
    pthread_mutex_unlock(&lock);
}
