#define INITIAL_CAPACITY 10
#define VALID_THRESHOLD_SECONDS 60

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    time_t *timestamp;  // To track insertion times for validation
} CRC_LIST;

CRC_LIST* create_crc_list() {
    CRC_LIST *list = malloc(sizeof(CRC_LIST));
    if (!list) return NULL;

    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->timestamp = malloc(INITIAL_CAPACITY * sizeof(time_t));
    if (!list->data || !list->timestamp) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_crc_list(CRC_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    time_t *new_timestamp = realloc(list->timestamp, new_capacity * sizeof(time_t));

    if (!new_data || !new_timestamp) return;  // Handle reallocation failure gracefully

    list->data = new_data;
    list->timestamp = new_timestamp;
    list->capacity = new_capacity;
}

void insert_crc_indication(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_crc_list(list);
    }

    list->data[list->size] = pdu;
    list->timestamp[list->size] = time(NULL);  // Store current time
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void validate_and_remove_old_entries(CRC_LIST *list) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ) {
        if ((current_time - list->timestamp[i]) > VALID_THRESHOLD_SECONDS) {
            // Shift elements to remove the old entry
            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memmove(&list->timestamp[i], &list->timestamp[i + 1], (list->size - i - 1) * sizeof(time_t));

            list->size--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_crc_list(CRC_LIST *list) {
    if (!list) return;

    free(list->data);
    free(list->timestamp);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    CRC_LIST *list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return 1;
    }

