int is_uniform(int *flags, size_t count) {
    const int BUCKETS = 10; // Simplified bucketing for demonstration
    int buckets[BUCKETS] = {0};
    unsigned long range = MAX_CRCFLAG - MIN_CRCFLAG + 1;

    for (size_t i = 0; i < count; ++i) {
        buckets[(flags[i] % BUCKETS)]++;
    }

    // Check uniform distribution by verifying each bucket has roughly equal values
    int expected = count / BUCKETS;
    for (int i = 0; i < BUCKETS; ++i) {
        if (buckets[i] > expected * 1.5 || buckets[i] < expected * 0.5)
            return 0; // Not uniform
    }

    return 1; // Uniform
}

