    free(cache);
}

int load_png_to_cache(ThemeCache *cache, const char *filename) {
    pthread_mutex_lock(&cache->lock);

    // Simulate loading a PNG file
    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    fseek(file, 0, SEEK_SET);

    ThemeBitmap *bitmap = (ThemeBitmap*)malloc(sizeof(ThemeBitmap));
    bitmap->bitmap_data = (unsigned char*)malloc(size);
    fread(bitmap->bitmap_data, 1, size, file);
    fclose(file);

    bitmap->size = size;
    cache->cache[0] = bitmap; // Example: storing in the first slot

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void set_default_theme_dir(const char *env_var) {
    const char *default_dir = getenv(env_var);
    if (!default_dir) {
        default_dir = "./themes"; // Default directory
    }
    printf("Default theme directory: %s\n", default_dir);
}

int main() {
    // Example usage
    EVP_CIPHER_CTX *cipher_ctx = initialize_cipher("password123");
    if (!cipher_ctx) {
        fprintf(stderr, "Cipher initialization failed.\n");
        return 1;
    }

    ThemeCache *theme_cache = create_theme_cache(10);
    set_default_theme_dir("THEME_DIR");

    const char *png_file = "./themes/theme1.png";
    if (load_png_to_cache(theme_cache, png_file) != 0) {
        fprintf(stderr, "Failed to load PNG file.\n");
    }

    // Cleanup
    EVP_CIPHER_CTX_free(cipher_ctx);
    free_theme_cache(theme_cache);

    return 0;
}
