#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CAPACITY 1000

typedef struct CRC_INDICATION_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct UE_INFORMATION_TAG {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    int count;
    pthread_mutex_t lock;
} CRCLinkedList;

// Initialize the linked list
void init_list(CRCLinkedList *list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert an element into the list
int insert_element(CRCLinkedList *list) {
    if (list->count >= MAX_CAPACITY) {
        fprintf(stderr, "Warning: Max capacity reached. Skipping insertion.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Randomly set values for the new element
    srand(time(NULL) + rand());
    new_node->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
    new_node->ue_info.RNTI = rand() % 1000;                  // Example range
    new_node->crc_tag.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to retrieve an element (for demonstration purposes)
NFAPI_CRC_INDICATION_PDU_T *retrieve_element(CRCLinkedList *list, int index) {
    if (index < 0 || index >= list->count) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    for (int i = 0; current != NULL && i < index; i++) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

// Function to free the linked list
void free_list(CRCLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    CRCLinkedList list;
    init_list(&list);

    for (int i = 0; i < MAX_CAPACITY + 5; i++) { // Attempt to exceed max capacity
        insert_element(&list);
    }

    NFAPI_CRC_INDICATION_PDU_T *element = retrieve_element(&list, 0);
    if (element) {
        printf("Element RNTI: %d, CRCFLAG: %d\n", element->ue_info.RNTI, element->crc_tag.CRCFLAG);
    }

    free_list(&list);

    return 0;
}
```

