typedef struct {
    NFAPI_RRC_CU_RX_PDU_T** array;
    size_t size;
    threading.Lock lock; // For thread safety
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->array = (NFAPI_RRC_CU_RX_PDU_T**)malloc(initial_size * sizeof(NFAPI_RRC_CU_RX_PDU_T*));
    arr->size = initial_size;
    threading.Lock_init(&arr->lock);
    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i]) {
            free(arr->array[i]->messages);
            free(arr->array[i]);
        }
    }
    free(arr->array);
    threading.Lock_destroy(&arr->lock);
    free(arr);
}

void resize_dynamic_array(DynamicArray* arr, size_t new_size) {
    NFAPI_RRC_CU_RX_PDU_T** temp = (NFAPI_RRC_CU_RX_PDU_T**)realloc(arr->array, new_size * sizeof(NFAPI_RRC_CU_RX_PDU_T*));
    if (temp) {
        arr->size = new_size;
        arr->array = temp;
    }
}

void add_pdu(DynamicArray* arr, int ue_id, DL_CCCH_Message* messages, size_t message_count) {
    threading.Lock_acquire(&arr->lock);
    for (size_t i = 0; i < arr->size; ++i) {
        if (!arr->array[i] || arr->array[i]->UE_ID != ue_id) continue;

        // Update existing PDU
        free(arr->array[i]->messages);
        arr->array[i]->messages = messages;
        arr->array[i]->message_count = message_count;
        break;
    }

    if (i == arr->size || !arr->array[i]) {
        // Resize if necessary
        if (arr->size == 0) resize_dynamic_array(arr, 1);
        else while (i >= arr->size) resize_dynamic_array(arr, arr->size * 2);

        NFAPI_RRC_CU_RX_PDU_T* pdu = (NFAPI_RRC_CU_RX_PDU_T*)malloc(sizeof(NFAPI_RRC_CU_RX_PDU_T));
        pdu->UE_ID = ue_id;
        pdu->messages = messages;
        pdu->message_count = message_count;
        arr->array[i] = pdu;
    }

    threading.Lock_release(&arr->lock);
}

void update_sib(DynamicArray* arr, int ue_id, char* new_sib_content) {
