```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Assuming these structures are defined elsewhere in the project
typedef struct {
    int RRC_CONNECTION_RECONFIGURATION_TAG;
    char* SIB;  // System Information Block content
} DL_CCCH_Message;

typedef struct {
    int UE_ID;
    DL_CCCH_Message* messages;
    size_t message_count;
} NFAPI_RRC_CU_RX_PDU_T;

// Dynamic array of NFAPI_RRC_CU_RX_PDU_T structures
typedef struct {
    NFAPI_RRC_CU_RX_PDU_T** pdus;
    size_t count;
    pthread_mutex_t mutex;
} PduArrayManager;

// Function to initialize the manager
void pdu_array_manager_init(PduArrayManager* manager) {
    manager->pdus = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

// Function to allocate memory for a new NFAPI_RRC_CU_RX_PDU_T structure
NFAPI_RRC_CU_RX_PDU_T* create_pdu(int ue_id) {
    NFAPI_RRC_CU_RX_PDU_T* pdu = (NFAPI_RRC_CU_RX_PDU_T*)malloc(sizeof(NFAPI_RRC_CU_RX_PDU_T));
    if (!pdu) return NULL;

    pdu->UE_ID = ue_id;
    pdu->messages = NULL;
    pdu->message_count = 0;
    return pdu;
}

// Function to add a new PDU or update an existing one
void add_or_update_pdu(PduArrayManager* manager, int ue_id, DL_CCCH_Message message) {
    pthread_mutex_lock(&manager->mutex);

    // Check if the UE_ID already exists
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i]->UE_ID == ue_id) {
            // Add the new message to existing PDU
            manager->pdus[i]->messages = realloc(manager->pdus[i]->messages,
                                                 (manager->pdus[i]->message_count + 1) * sizeof(DL_CCCH_Message));
            if (!manager->pdus[i]->messages) {
                pthread_mutex_unlock(&manager->mutex);
                return;
            }
            manager->pdus[i]->messages[manager->pdus[i]->message_count] = message;
            ++(manager->pdus[i]->message_count);
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    // If UE_ID does not exist, create a new PDU
    NFAPI_RRC_CU_RX_PDU_T* new_pdu = create_pdu(ue_id);
    if (!new_pdu) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Allocate space for one message initially
    new_pdu->messages = malloc(sizeof(DL_CCCH_Message));
    if (!new_pdu->messages) {
        free(new_pdu);
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    new_pdu->messages[0] = message;
    new_pdu->message_count = 1;

    // Resize the array to accommodate the new PDU
    manager->pdus = realloc(manager->pdus, (manager->count + 1) * sizeof(NFAPI_RRC_CU_RX_PDU_T*));
    if (!manager->pdus) {
        free(new_pdu->messages);
        free(new_pdu);
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    manager->pdus[manager->count] = new_pdu;
    ++(manager->count);

    pthread_mutex_unlock(&manager->mutex);
}

// Function to deallocate memory for all PDUs
void cleanup_pdu_array(PduArrayManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i]->messages);
        free(manager->pdus[i]);
    }
    free(manager->pdus);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

// Function to query the number of active connections for a given UE_ID
size_t get_active_connections(PduArrayManager* manager, int ue_id) {
    size_t count = 0;
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdus[i]->UE_ID == ue_id) {
            count = manager->pdus[i]->message_count;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return count;
}

// Example usage
int main() {
    PduArrayManager manager;
    pdu_array_manager_init(&manager);

    DL_CCCH_Message message1 = { .RRC_CONNECTION_RECONFIGURATION_TAG = 1, .SIB = "RandomSIBContent1" };
    add_or_update_pdu(&manager, 12345, message1);

    DL_CCCH_Message message2 = { .RRC_CONNECTION_RECONFIGURATION_TAG = 2, .SIB = "RandomSIBContent2" };
    add_or_update_pdu(&manager, 12345, message2);

    printf("Active connections for UE_ID 12345: %zu\n", get_active_connections(&manager, 12345));

    cleanup_pdu_array(&manager);
    return 0;
}
```

