#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_GROUP_SIZE 10 // Adjust group size as needed

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Flag for parity check error
} NFAPI_CRC_INDICATION_PDU_T;

// Asynchronous logging structure and functions
typedef struct {
    sem_t write_sem;
    pthread_mutex_t mutex;
    FILE *log_file;
} AsyncLogger;

AsyncLogger logger = {0};

void init_async_logger(const char *filename) {
    sem_init(&logger.write_sem, 0, 1);
    pthread_mutex_init(&logger.mutex, NULL);
    logger.log_file = fopen(filename, "a");
}

void async_log(const char *message) {
    sem_wait(&logger.write_sem);
    pthread_mutex_lock(&logger.mutex);

    fprintf(logger.log_file, "%s\n", message);
    fflush(logger.log_file);

    pthread_mutex_unlock(&logger.mutex);
    sem_post(&logger.write_sem);
}

void cleanup_async_logger() {
    fclose(logger.log_file);
    sem_destroy(&logger.write_sem);
    pthread_mutex_destroy(&logger.mutex);
}

// Function to compute parity check
unsigned char calculate_parity(unsigned int tag) {
    unsigned char parity = 0;
    while (tag) {
        parity ^= (tag & 1);
        tag >>= 1;
    }
    return parity;
}

void* populate_crc_indications(void *arg) {
    size_t start, end;
    NFAPI_CRC_INDICATION_PDU_T *list;
    unsigned int group_size = MAX_GROUP_SIZE;

    // Extract arguments
    struct {
        NFAPI_CRC_INDICATION_PDU_T *list;
        size_t total_elements;
        size_t thread_id;
        size_t num_threads;
    } *params = (struct {
        NFAPI_CRC_INDICATION_PDU_T *list;
        size_t total_elements;
        size_t thread_id;
        size_t num_threads;
    } *)arg;

    list = params->list;
    size_t total_elements = params->total_elements;
    size_t num_threads = params->num_threads;

    start = (total_elements / num_threads) * params->thread_id;
    end = (params->thread_id == num_threads - 1) ? total_elements : start + (total_elements / num_threads);

    for (size_t i = start; i < end; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
        list[i].RNTI = rand() % 5000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 256;

        // Set CRCFLAG based on parity check over UE tags within a group
        unsigned char parity = calculate_parity(list[i].RX_UE_INFORMATION_TAG);
        size_t group_index = i / group_size;
        if (group_index * group_size < end) {
            list[i].CRCFLAG = (parity == 0); // Set error condition flag
        }
    }

    async_log("Thread finished processing its range");

    return NULL;
}

void manage_nfa_crc_indications(size_t N, size_t G) {
    if (N == 0 || G == 0) {
        printf("Invalid parameters for list size or group size.\n");
        return;
    }

