    pthread_t threads[num_threads];
    NFAPI_CRC_INDICATION_PDU_T *crc_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_list) {
        perror("Failed to allocate memory");
        return;
    }

    struct {
        NFAPI_CRC_INDICATION_PDU_T *list;
        size_t total_elements;
        size_t thread_id;
        size_t num_threads;
    } params[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        params[i].list = crc_list;
        params[i].total_elements = N;
        params[i].thread_id = i;
        params[i].num_threads = num_threads;

