            perror("Failed to create thread");
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Process the list as needed
    free(crc_list);

    async_log("Finished managing CRC indications.");
}

int main() {
    init_async_logger("async.log");

    size_t N = 1000000; // Example large number
    size_t G = MAX_GROUP_SIZE;

    manage_nfa_crc_indications(N, G);

    cleanup_async_logger();
    return 0;
}
