// Hash table structure
typedef struct Node {
    int rnti;
    struct Node *next;
} Node;

// Global lock for thread safety
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

Node* create_node(int rnti) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->rnti = rnti;
    node->next = NULL;
    return node;
}

void free_hash_table(Node* hash_table[]) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node *current = hash_table[i];
        while (current) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }
}

// Function to populate and manage the array
NFAPI_CRC_INDICATION_PDU_T* manage_crc_array(size_t N, size_t* allocated_size) {
    if (N > MAX_INT || N == 0) return NULL;

    pthread_mutex_lock(&array_lock);

    *allocated_size = 0;
    Node* hash_table[HASH_TABLE_SIZE] = {NULL};
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&array_lock);
        return NULL;
    }

    size_t count = 0;
    while (count < N) {
        int rnti = rand() % MAX_INT; // Generate a random RNTI
        int index = hash(rnti);

        Node* current = hash_table[index];
        while (current) {
            if (current->rnti == rnti) break;
            current = current->next;
        }

        if (!current) { // Unique RNTI found
            Node *new_node = create_node(rnti);
            if (!new_node) {
                free(array);
                pthread_mutex_unlock(&array_lock);
                return NULL;
            }
            new_node->next = hash_table[index];
            hash_table[index] = new_node;

            array[count].RX_UE_INFORMATION_TAG = rand(); // Random tag
            array[count].RNTI = rnti;
            array[count].CRC_INDICATION_REL8_TAG = rand(); // Random tag
            array[count].CRCFLAG = rand() % 2; // Random CRC flag

            count++;
        }
    }

    *allocated_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    free_hash_table(hash_table);

    pthread_mutex_unlock(&array_lock);
    return array;
}

// Usage example
