    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) {
        fprintf(stderr, "Error: Initial capacity must be greater than zero.\n");
        return NULL;
    }

    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);

    // Seed random number generator
    srand((unsigned int)time(NULL));

    return array;
}

bool add_structure(DynamicArray* array) {
    if (!array) {
        fprintf(stderr, "Error: DynamicArray pointer is null.\n");
        return false;
    }

    pthread_mutex_lock(&array->mutex);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            perror("Failed to reallocate memory for expanded array");
            return false;
        }

        array->array = new_array;
        array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = &array->array[array->count++];
    structure->RX_UE_INFORMATION_TAG = (uint16_t)rand();
    structure->RNTI = (uint16_t)rand();
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&array->mutex);

    return true;
}

size_t get_count(const DynamicArray* array) {
    if (!array) {
        fprintf(stderr, "Error: DynamicArray pointer is null.\n");
        return (size_t)-1; // Indicate error
    }

    pthread_mutex_lock((pthread_mutex_t*)&array->mutex);
    size_t count = array->count;
    pthread_mutex_unlock((pthread_mutex_t*)&array->mutex);

    return count;
}

bool free_dynamic_array(DynamicArray** array) {
    if (!array || !*array) {
        fprintf(stderr, "Error: DynamicArray pointer is null.\n");
        return false;
    }

    pthread_mutex_lock(&(*array)->mutex);
    free((*array)->array);
    pthread_mutex_unlock(&(*array)->mutex);

    pthread_mutex_destroy(&(*array)->mutex);
    free(*array);
    *array = NULL;

    return true;
}
