static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_theme_name(const char *name) {
    unsigned long hash = 5381;
    int c;
    while ((c = *name++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % THEME_CACHE_SIZE;
}

