    unsigned int index = hash_theme_name(theme_name);
    pthread_mutex_lock(&cache_lock);

    ThemeCacheEntry *entry = theme_cache[index];
    while (entry != NULL) {
        if (strcmp(entry->theme_name, theme_name) == 0) {
            entry->last_access_time = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return entry;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

