typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    atomic_int crcFlags[256];
} CRCList;

void log_creation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Integrate with an existing logging framework
    printf("Created NFAPI_CRC_INDICATION_PDU_T: Tag=%u, RNTI=%u\n", pdu->rxUEInformationTag, pdu->rnti);
}

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < 256; i++) {
        atomic_store(&list->crcFlags[i], 0);
    }
    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    int crcFlag;
    do {
        crcFlag = rand() % 256;
    } while (atomic_load(&list->crcFlags[crcFlag]));

    atomic_store(&list->crcFlags[crcFlag], 1);
    pdu->crcIndicationRel8Tag.crcFlag = (unsigned char)crcFlag;

    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(&newNode->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    log_creation(pdu);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_crc_list(CRCList* list, size_t index) {
    if (!list || index >= list->size) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    return current ? &current->data : NULL;
}

void remove_from_crc_list(CRCList* list, size_t index) {
    if (!list || index >= list->size) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    for (size_t i = 0; i < index && current != NULL; i++) {
        prev = current;
        current = current->next;
    }

    if (current) {
        atomic_store(&list->crcFlags[current->data.crcIndicationRel8Tag.crcFlag], 0);
        if (prev) {
            prev->next = current->next;
        } else {
            list->head = current->next;
        }
        free(current);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

void process_crc_list(CRCList* list, void (*process_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !process_func) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        process_func(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void example_process_function(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Example processing function
    printf("Processing PDU: Tag=%u, RNTI=%u, CRCFlag=%d\n", pdu->rxUEInformationTag, pdu->rnti, pdu->crcIndicationRel8Tag.crcFlag);
}

