    CRCList* list = create_crc_list();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .rxUEInformationTag = 1, .rnti = 1001 };
    add_to_crc_list(list, &pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .rxUEInformationTag = 2, .rnti = 1002 };
    add_to_crc_list(list, &pdu2);

    process_crc_list(list, example_process_function);
    remove_from_crc_list(list, 0);

    destroy_crc_list(list);
    return 0;
}
