    if (N > max_size) {
        log_message("Error: Requested size exceeds maximum allowed.");
        return FAILURE;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *temp_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_array) {
        log_message("Memory allocation failed.");
        return FAILURE;
    }

    INIT_LOCK; // Ensure lock is initialized once
    pthread_mutex_lock(&lock); // Lock for thread safety

    for (int i = 0; i < N; ++i) {
        temp_array[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        temp_array[i].RNTI = 1000 + i; // Specific RNTI
        temp_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = generate_crcflag(0, 255); // Random CRCFLAG

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Created structure %d with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d",
                 i + 1, temp_array[i].RX_UE_INFORMATION_TAG, temp_array[i].RNTI, temp_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        log_message(log_buffer);
    }

    pthread_mutex_unlock(&lock); // Unlock after critical section

    *array = temp_array; // Set output parameter
    return SUCCESS;
}

// Function to free the allocated array
void free_nfaapi_crc_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
        log_message("Freed NFAPI_CRC_INDICATION_PDU_T array.");
    }
}

