} NFAPI_CRC_INDICATION_PDU_T;

int log_error(const char *message) {
    FILE *log_file = fopen("crc_indication_log.txt", "a");
    if (log_file == NULL) {
        return 0; // Unable to open log file
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
    return 1;
}

int generate_unique_crc_flags(int *array, int size) {
    for (int i = 0; i < size; ++i) {
        array[i] = rand() % (size * 2); // Generate a candidate
        for (int j = 0; j < i; ++j) {
            if (array[j] == array[i]) { // Check uniqueness
                --i;
                break;
            }
        }
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_indication_pdu(int num_elements, int *error_code) {
    if (num_elements > MAX_ELEMENTS || num_elements <= 0) {
        *error_code = -1; // Invalid number of elements
        log_error("Invalid number of elements requested");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        *error_code = -2; // Memory allocation failure
        log_error("Memory allocation failed for CRC indication array");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (int i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        array[i].RNTI = rand() % 5000 + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 200 + 1;
    }

    int *crc_flags = (int *)malloc(num_elements * sizeof(int));
    if (crc_flags == NULL) {
        free(array);
        *error_code = -3; // Memory allocation failure for CRC flags
        log_error("Memory allocation failed for CRC flags");
        return NULL;
    }

    if (!generate_unique_crc_flags(crc_flags, num_elements)) {
        free(array);
        free(crc_flags);
        *error_code = -4; // Failed to generate unique CRC flags
        log_error("Failed to generate unique CRC flags");
        return NULL;
    }

    for (int i = 0; i < num_elements; ++i) {
        array[i].CRCFLAG = crc_flags[i];
    }

    free(crc_flags);
    *error_code = 0; // Success
    return array;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array != NULL) {
        free(array);
    }
}
