#include <stdint.h>
#include <pthread.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list structure with a mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new node
Node* create_node(uint16_t rx_tag, uint16_t rnti, uint8_t crc_rel8_tag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

// Function to initialize the linked list
void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to add a node to the list
void add_to_list(LinkedList* list, uint16_t rx_tag, uint16_t rnti, uint8_t crc_rel8_tag) {
    Node* new_node = create_node(rx_tag, rnti, crc_rel8_tag);

    if (!new_node) return;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Function to filter nodes by RNTI range
void* filter_list(LinkedList* list, uint16_t min_rnti, uint16_t max_rnti) {
    LinkedList filtered_list;
    init_list(&filtered_list);

    Node* current = NULL;

    pthread_mutex_lock(&list->lock);

    current = list->head;

    while (current) {
        if (current->data.RNTI >= min_rnti && current->data.RNTI <= max_rnti) {
            add_to_list(&filtered_list, current->data.RX_UE_INFORMATION_TAG,
                        current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        }
        current = current->next;

    }

    pthread_mutex_unlock(&list->lock);

    // Return the head of filtered list
    return (void*)&filtered_list;
}

// Function to free all nodes in a linked list
void free_list(LinkedList* list) {
    Node* current = NULL;
    Node* next_node = NULL;

    pthread_mutex_lock(&list->lock);

    current = list->head;

    while (current) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    LinkedList ue_list;
    init_list(&ue_list);

    // Add some elements to the list (example)
    add_to_list(&ue_list, 1, 100, 10);
    add_to_list(&ue_list, 2, 200, 20);
    add_to_list(&ue_list, 3, 150, 30);

    // Filter the list based on RNTI range
    LinkedList* filtered_list = (LinkedList*)filter_list(&ue_list, 100, 150);

    // Free lists after use
    free_list(&ue_list);
    free_list(filtered_list);

    return 0;
}
```

### Key Points:
- **Memory Management**: Memory is allocated and freed dynamically. Error handling for allocation failures is included.
- **Concurrency**: Thread safety is achieved using a mutex to protect the linked list operations.
- **Scalability**: The linked list can grow as needed, accommodating more structures efficiently.
- **Integration**: This code is designed to be modular and easily integrated with network systems through potential extensions like callbacks or event hooks.
- **Performance**: Minimal locking overhead for thread safety; efficient filtering by iterating only the necessary nodes.
- **Usability**: Simple interfaces (`add_to_list`, `filter_list`, `free_list`) facilitate easy management of the list.
- **Maintainability**: Clear structure and modular design make future changes straightforward.']

