#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_STRUCTURES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} CircularBuffer;

CircularBuffer buffer = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

void initialize_buffer(CircularBuffer* buf) {
    buf->head = buf->tail = NULL;
    buf->count = 0;
}

bool is_full(CircularBuffer* buf) {
    return buf->count == MAX_STRUCTURES;
}

bool is_empty(CircularBuffer* buf) {
    return buf->count == 0;
}

void enqueue(CircularBuffer* buf, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&buf->lock);

    if (is_full(buf)) {
        // Handle full buffer case: potentially block or discard
        printf("Buffer is full. Consider processing items.\n");
        pthread_cond_wait(&buf->cond, &buf->lock);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }

    new_node->data = data;
    new_node->next = NULL;

    if (is_empty(buf)) {
        buf->head = buf->tail = new_node;
    } else {
        buf->tail->next = new_node;
        buf->tail = new_node;
    }

    buf->count++;
    pthread_cond_signal(&buf->cond);
    pthread_mutex_unlock(&buf->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(CircularBuffer* buf) {
    NFAPI_CRC_INDICATION_PDU_T data;

    pthread_mutex_lock(&buf->lock);

    while (is_empty(buf)) {
        // Wait until there is data to process
        pthread_cond_wait(&buf->cond, &buf->lock);
    }

    Node* temp = buf->head;
    data = temp->data;
    buf->head = buf->head->next;

    if (buf->head == NULL) {
        buf->tail = NULL; // Buffer is now empty
    }

    free(temp);
    buf->count--;

    pthread_mutex_unlock(&buf->lock);
    return data;
}

// Thread pool for processing items in the buffer asynchronously
typedef struct ThreadPool {
    pthread_t* threads;
    size_t thread_count;
} ThreadPool;

void* process_items(void* arg) {
    CircularBuffer* buf = (CircularBuffer*)arg;

    while (true) { // Replace with actual exit condition
        NFAPI_CRC_INDICATION_PDU_T data = dequeue(buf);

        // Process the dequeued item here
        printf("Processing RNTI: %u\n", data.crc_tag.RNTI);

        // Simulate processing time
        sleep(1);
    }

    return NULL;
}

void initialize_thread_pool(ThreadPool* pool, size_t count) {
    pool->threads = malloc(sizeof(pthread_t) * count);
    if (!pool->threads) {
        perror("Failed to allocate memory for thread pool");
        exit(EXIT_FAILURE);
    }
    pool->thread_count = count;

    for (size_t i = 0; i < count; ++i) {
        pthread_create(&pool->threads[i], NULL, process_items, &buffer);
    }
}

void destroy_thread_pool(ThreadPool* pool) {
    free(pool->threads);
}

int main() {
    initialize_buffer(&buffer);

    ThreadPool pool;
    initialize_thread_pool(&pool, 4); // Start with a thread count of 4

    NFAPI_CRC_INDICATION_PDU_T pdu = {{.RX_UE_INFORMATION_TAG = 1, .RNTI = 12345}, true};

    enqueue(&buffer, pdu);

    // Simulate adding more items to the buffer here...

    sleep(10); // Let threads process for a while

    destroy_thread_pool(&pool);
    return 0;
}
