#include <pthread.h>

#define INITIAL_SIZE 10

typedef enum {
    IDLE,
    CONNECTED,
    PAGING,
    INACTIVE
} RRCState;

typedef struct {
    float snr;
} SNRMeasurement;

typedef struct UEContext {
    int ue_id;
    RRCState rrc_state;
    SNRMeasurement *snr_measurements;
    size_t measurement_count;
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ContextManager;

// Function prototypes
void init_context_manager(ContextManager *manager);
void add_or_update_context(ContextManager *manager, int ue_id, RRCState rrc_state, float snr);
float calculate_average_snr(ContextManager *manager);
void remove_contexts_by_criteria(ContextManager *manager, int (*criteria)(const UEContext *));
void cleanup_context_manager(ContextManager *manager);

// Function implementations
void init_context_manager(ContextManager *manager) {
    manager->contexts = malloc(INITIAL_SIZE * sizeof(UEContext*));
    manager->size = 0;
    manager->capacity = INITIAL_SIZE;
    pthread_mutex_init(&manager->lock, NULL);
}

void resize_contexts_if_needed(ContextManager *manager) {
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->contexts = realloc(manager->contexts, manager->capacity * sizeof(UEContext*));
    }
}

void add_or_update_context(ContextManager *manager, int ue_id, RRCState rrc_state, float snr) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            UEContext *context = manager->contexts[i];
            context->rrc_state = rrc_state;

            // Append SNR measurement
            context->snr_measurements = realloc(context->snr_measurements, 
                                                (context->measurement_count + 1) * sizeof(SNRMeasurement));
            context->snr_measurements[context->measurement_count].snr = snr;
            ++context->measurement_count;

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Add new context
    resize_contexts_if_needed(manager);

    UEContext *new_context = malloc(sizeof(UEContext));
    new_context->ue_id = ue_id;
    new_context->rrc_state = rrc_state;
    new_context->snr_measurements = malloc(sizeof(SNRMeasurement));
    new_context->snr_measurements[0].snr = snr;
    new_context->measurement_count = 1;

    manager->contexts[manager->size++] = new_context;

    pthread_mutex_unlock(&manager->lock);
}

float calculate_average_snr(ContextManager *manager) {
    pthread_mutex_lock(&manager->lock);

    float total_snr = 0.0f;
    size_t count = 0;

    for (size_t i = 0; i < manager->size; ++i) {
        UEContext *context = manager->contexts[i];
        for (size_t j = 0; j < context->measurement_count; ++j) {
            total_snr += context->snr_measurements[j].snr;
            count++;
        }
    }

    float average_snr = (count > 0) ? (total_snr / count) : 0.0f;

    pthread_mutex_unlock(&manager->lock);
    return average_snr;
}

void remove_contexts_by_criteria(ContextManager *manager, int (*criteria)(const UEContext *)) {
    pthread_mutex_lock(&manager->lock);

    size_t j = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (!criteria(manager->contexts[i])) {
            manager->contexts[j++] = manager->contexts[i];
        } else {
            free(manager->contexts[i]->snr_measurements);
            free(manager->contexts[i]);
        }
    }

    manager->size = j;
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_context_manager(ContextManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]->snr_measurements);
        free(manager->contexts[i]);
    }

    free(manager->contexts);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example criteria function
int is_inactive(const UEContext *context) {
    return context->rrc_state == INACTIVE;
}
