#include <time.h>

#define MAX_CONNECTIONS 1024
#define FIXED_SIZE_PAYLOAD 256
#define HEADER_SIZE sizeof(PacketHeader)
#define INITIAL_BUFFER_POOL 10

typedef struct {
    unsigned int src_ip;
    unsigned int dest_ip;
    unsigned char protocol_type;
    unsigned int seq_number;
    time_t timestamp;
    unsigned short checksum;
    size_t payload_size; // Variable length support
} PacketHeader;

typedef struct PacketBuffer {
    PacketHeader header;
    void *payload;
    struct PacketBuffer *next;
} PacketBuffer;

PacketBuffer *buffer_pool[MAX_CONNECTIONS] = {NULL};
int connection_count = 0;

unsigned short calculate_checksum(PacketHeader *header) {
    unsigned int sum = header->src_ip + header->dest_ip +
                       (header->protocol_type << 8) +
                       (header->seq_number & 0xFFFF) +
                       ((header->seq_number >> 16) & 0xFFFF);
    return (unsigned short)(~sum);
}

int validate_packet(PacketBuffer *packet) {
    unsigned short computed_checksum = calculate_checksum(&packet->header);
    return packet->header.checksum == computed_checksum;
}

PacketBuffer* allocate_packet_buffer() {
    PacketBuffer *new_buffer = (PacketBuffer *)malloc(sizeof(PacketBuffer));
    if (!new_buffer) return NULL;

