class DynamicValueGenerator {
private:
    float minValue;
    float maxValue;

public:
    DynamicValueGenerator(float initMin = 0.0f, float initMax = 1.0f)
        : minValue(initMin), maxValue(initMax) {}

    void AdjustRange(float newMin, float newMax) {
        if (newMin >= minValue && newMin < maxValue && newMax > newMin) {
            minValue = newMin;
            maxValue = newMax;
        }
    }

    int GetRandomInt() {
        return rand() % ((int)(maxValue - minValue + 1)) + (int)minValue;
    }

    float GetRandomFloat() {
        return minValue + static_cast<float>(rand()) / (static_cast<float>(RAND_MAX / (maxValue - minValue)));
    }

    float GetRandomFloatExclusive(float exclusiveMin, float exclusiveMax) {
        if (exclusiveMin >= exclusiveMax || exclusiveMin >= maxValue || exclusiveMax <= minValue) {
            return 0.0f; // Error handling: invalid range
        }
        float range = exclusiveMax - exclusiveMin;
        return exclusiveMin + static_cast<float>(rand()) / (static_cast<float>(RAND_MAX / range));
    }
};

NFAPI_CRC_INDICATION_PDU_T* generateNfarecPduList(size_t numPDUs) {
    if (numPDUs == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) return NULL; // Error handling: memory allocation failed

    srand(time(NULL));  // Seed the random number generator
    DynamicValueGenerator valueGen(0.0f, 1.0f);

    for (size_t i = 0; i < numPDUs; ++i) {
        pduList[i].informationTag.RX_UE_INFORMATION_TAG = valueGen.GetRandomInt();
        pduList[i].RNTI = valueGen.GetRandomInt() % UINT32_MAX;
        pduList[i].crcIndicationRel8Tag.CRCFLAG = (valueGen.GetRandomFloatExclusive(0.5f, 1.0f) > 0.5f) ? 1 : 0;
    }

    return pduList;
}

// Example usage:
int main() {
