    pthread_mutex_t lock; // Mutex for thread safety
} CRCArrayManager;

// Function prototypes
CRCArrayManager* create_crc_array_manager();
void add_pdu(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_pdu_by_tag(CRCArrayManager* manager, int tag);
int update_pdu(CRCArrayManager* manager, int tag, NFAPI_CRC_INDICATION_PDU_T new_data);
void destroy_crc_array_manager(CRCArrayManager* manager);

// Function implementations
CRCArrayManager* create_crc_array_manager() {
    CRCArrayManager* manager = (CRCArrayManager*)malloc(sizeof(CRCArrayManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_pdu(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&manager->lock);

    // Insert at head for O(1) insertion
    new_node->next = manager->head;
    manager->head = new_node;

    pthread_mutex_unlock(&manager->lock);
}

int remove_pdu_by_tag(CRCArrayManager* manager, int tag) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != tag) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Tag not found
        pthread_mutex_unlock(&manager->lock);
        return 0; // Failure to remove
    }

    if (prev == NULL) { // Head needs to be removed
        manager->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&manager->lock);

    return 1; // Success
}

int update_pdu(CRCArrayManager* manager, int tag, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != tag) {
        current = current->next;
    }

    if (!current) { // Tag not found
        pthread_mutex_unlock(&manager->lock);
        return 0; // Failure to update
    }

    memcpy(&current->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&manager->lock);

    return 1; // Success
}

void destroy_crc_array_manager(CRCArrayManager* manager) {
    if (!manager) return;

    Node *current = manager->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

