ConfigCache cache = { .config_data = NULL, .last_updated = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

char *get_config_directory() {
    static const char *default_dir = "/etc/nfapi/";
    return getenv("NFAPI_CONFIG_DIR") ? strdup(getenv("NFAPI_CONFIG_DIR")) : strdup(default_dir);
}

void free_cache_resources(ConfigCache *cache) {
    pthread_mutex_lock(&cache->lock);
    if (cache->config_data) {
        free(cache->config_data);
        cache->config_data = NULL;
    }
    pthread_mutex_unlock(&cache->lock);
