size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char **data = (char **)userp;

    if (*data == NULL) {
        *data = malloc(realsize + 1);
        if (*data == NULL) return 0;
    } else {
        *data = realloc(*data, strlen(*data) + realsize + 1);
        if (*data == NULL) return 0;
    }

    memcpy(&(char)*data[strlen((char)*data)], contents, realsize);
    ((char *)*data)[strlen((char)*data) + realsize] = '\0';

    return realsize;
}

void fetch_config_async(const char *url, ConfigCache *cache) {
    CURL *curl;
    CURLcode res;

