    size_t growth_factor;
    pthread_mutex_t lock; // For thread safety
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
} DynamicList;

// Logging utility
void log_operation(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Function to initialize the dynamic list
int init_dynamic_list(DynamicList *list, size_t initial_size, size_t growth_factor) {
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        log_operation("Mutex initialization failed");
        return -1;
    }

    list->initial_size = initial_size;
    list->growth_factor = growth_factor;
    list->count = 0;

    if ((list->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_size)) == NULL) {
        log_operation("Initial memory allocation failed");
        pthread_mutex_destroy(&list->lock);
        return -1;
    }

    log_operation("Dynamic list initialized successfully");
    return 0;
}

// Function to add an element to the dynamic list
int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->array_capacity) {
        size_t new_capacity = list->initial_size * ((list->count / list->initial_size + 1) * list->growth_factor);
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

        if (new_array == NULL) {
            log_operation("Memory reallocation failed");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->array = new_array;
        list->initial_size = new_capacity;
    }

    // Set random CRCFLAG
    pdu.CRCFLAG = rand() % 2; // Randomly 0 or 1

    list->array[list->count++] = pdu;

    log_operation("Element added successfully");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to validate the integrity of the dynamic list
int validate_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->array[i].RX_UE_INFORMATION_TAG == 0 || list->array[i].RNTI == 0) {
            log_operation("Validation failed: Invalid RX_UE_INFORMATION_TAG or RNTI");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    log_operation("List validation successful");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the dynamic list
void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->array != NULL) {
        free(list->array);
        log_operation("Memory deallocated successfully");
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    DynamicList list;
    if (init_dynamic_list(&list, INITIAL_BUFFER_SIZE, GROWTH_FACTOR) != 0) {
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2 };
    for (int i = 0; i < 10000; ++i) {
        if (add_element(&list, pdu) != 0) {
            free_dynamic_list(&list);
            return EXIT_FAILURE;
        }
    }

    if (validate_list(&list) != 0) {
        free_dynamic_list(&list);
        return EXIT_FAILURE;
    }

    free_dynamic_list(&list);
    return EXIT_SUCCESS;
}
```

### Design Decisions:

1. **Thread Safety**: Used `pthread_mutex_t` for mutual exclusion to ensure thread safety during list operations.
2. **Memory Management**: Implemented a dynamic array with an exponential growth strategy to balance between memory usage and allocation overhead.
3. **Error Handling**: Added checks for memory allocation failures and mutex initialization, with logging for each error scenario.
4. **Logging System**: Used a simple logging function to track operations, aiding in debugging and monitoring.
5. **Validation**: Provided a validation mechanism to check the integrity of the list after creation.
6. **Configurable Parameters**: Allowed configuration of initial buffer size and growth factor for flexibility.

This design ensures that the system is reliable, performant, and extensible for future enhancements.']

