typedef struct UnionFindNode {
    int parent;
    int rank;
} UnionFindNode;

// Global mutex for synchronization
pthread_mutex_t db_mutex = PTHREAD_MUTEX_INITIALIZER;

UnionFindNode* create_union_find(int size) {
    UnionFindNode *uf = (UnionFindNode*) malloc(size * sizeof(UnionFindNode));
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(UnionFindNode *uf, int x) {
    if (uf[x].parent != x)
        uf[x].parent = find(uf, uf[x].parent);
    return uf[x].parent;
}

void union_sets(UnionFindNode *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

