    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;
    printf("Time taken: %.2f ms\n", time_taken);

    execute_external_command("echo 'Processing completed'");

    free(uf);
    free(pdus);

    return 1;
}

