        new_node->next = NULL;

        pthread_mutex_lock(&list_mutex); // Ensure thread safety

        if (*head == NULL) {
            *head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;

        pthread_mutex_unlock(&list_mutex);

        count++;
        if (enable_logging) {
            log_message("Successfully added a valid entry");
        }
    }

    return (count == max_size) ? 0 : -1; // Return error code if list size limit exceeded
}

// Function to free the linked list
void free_crc_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
