    if (current == NULL) { // New packet
        current = malloc(sizeof(Node));
        if (!current) return -1; // Memory allocation failed

        current->packet = malloc(sizeof(NetworkDataPacket));
        if (!current->packet) {
            free(current);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        current->packet->packet_id = packet_id;
        current->packet->timestamp = timestamp;
        current->packet->data = strdup(data); // Make a copy of the data
        current->next = NULL;

        if (prev == NULL) { // Insert at head
            list->head = current;
        } else {
            prev->next = current;
        }
    } else { // Update existing packet
        free(current->packet->data); 
        current->packet->timestamp = timestamp; 
        current->packet->data = strdup(data);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Find and update an existing packet
NetworkDataPacket* updatePacket(PacketList* list, int packet_id, double new_timestamp, const char* new_data) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->packet->packet_id != packet_id) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Packet not found
    }

    free(current->packet->data);
    current->packet->timestamp = new_timestamp;
    current->packet->data = strdup(new_data);

    pthread_mutex_unlock(&list->lock);
    return current->packet;
}

// Query packets by timestamp range
Node* findPacketByTimestampRange(PacketList* list, double start_time, double end_time) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->packet->timestamp < start_time) {
        current = current->next;
    }

    // Create a dummy node to ease handling of the linked list
    Node* dummy = malloc(sizeof(Node));
    if (!dummy) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Memory allocation failed
    }
    dummy->next = current;

    // Traverse and unlink nodes outside the range
    Node *prev = dummy;
    while (current != NULL && current->packet->timestamp <= end_time) {
        prev = current;
        current = current->next;
    }

    prev->next = NULL; // Terminate the new list

    pthread_mutex_unlock(&list->lock);
    return dummy->next;
}

// Free all resources associated with the packet list
void freePacketList(PacketList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *tmp;

    while (current != NULL) {
        tmp = current;
        current = current->next;

        free(tmp->packet->data);
        free(tmp->packet);
        free(tmp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

This C code implements a multi-threaded packet manager that uses linked lists to store `NetworkDataPacket` structures. It includes thread-safe operations for adding, updating, and querying packets based on timestamp ranges while ensuring data integrity under concurrent access. The solution is designed with scalability in mind, allowing integration into larger systems.']

