#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rx_ue_info_tag;
    int rnti;
    unsigned char crc_indication;
    time_t timestamp; // For managing retention period
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCLinkedList;

CRCLinkedList* create_list() {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU* retrieve_head(CRCLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU* pdu = &list->head->data;
    Node* temp = list->head;
    list->head = list->head->next;

    free(temp);

    pthread_mutex_unlock(&list->lock);
    return pdu;
}

void prune_old_nodes(CRCLinkedList* list, time_t retention_period) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    time_t now = time(NULL);

    while (current != NULL) {
        if (difftime(now, current->data.timestamp) > retention_period) {
            if (prev == NULL) { // Removing head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(CRCLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    CRCLinkedList* list = create_list();

    // Insert nodes as needed, e.g.,
    NFAPI_CRC_INDICATION_PDU pdu1 = { .rx_ue_info_tag = 1, .rnti = 100, .crc_indication = 0x1F, .timestamp = time(NULL) };
    insert_node(list, pdu1);

    // Retrieve and process nodes
    NFAPI_CRC_INDICATION_PDU* pdu = retrieve_head(list);
    if (pdu) {
        printf("Retrieved PDU: RNTI=%d, CRC=%02x\n", pdu->rnti, pdu->crc_indication);
    }

    // Prune old elements
    prune_old_nodes(list, 60); // Retain only elements within last 60 seconds

    cleanup_list(list);

    return 0;
}
```

