    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define a simple logger function
#define LOG_DEBUG(...) fprintf(stderr, __VA_ARGS__)

// Mutex for thread-safe operations
pthread_mutex_t resource_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Node* create_linked_list(size_t num_elements);
void free_linked_list(Node* head);
int random_crc_flag();

Node* create_linked_list(size_t num_elements) {
    Node *head = NULL, *tail = NULL;

    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&resource_mutex);

    for (size_t i = 0; i < num_elements; ++i) {
        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            LOG_DEBUG("Memory allocation failed at element %zu\n", i);
            // Free previously allocated nodes
            free_linked_list(head);
            pthread_mutex_unlock(&resource_mutex);
            return NULL;
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        new_node->data.RNTI = rand() % 10000; // Example value
        new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = random_crc_flag();

        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&resource_mutex);

    LOG_DEBUG("Linked list of size %zu created successfully\n", num_elements);
    return head;
}

void free_linked_list(Node* head) {
    Node *current = head, *next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
}

int random_crc_flag() {
    // Return a random CRC flag
    return rand() % 2;
}
