```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000
#define VALID_RNTI_MIN 1
#define VALID_RNTI_MAX 65535

typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_LIST;

NFAPI_LIST nfa_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

bool isValidRNTI(uint16_t rnti) {
    return (rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX);
}

void addElement(int rxTag, uint16_t rnti) {
    if (!isValidRNTI(rnti)) return;

    pthread_mutex_lock(&nfa_list.lock);

    if (nfa_list.count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&nfa_list.lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElement) {
        pthread_mutex_unlock(&nfa_list.lock);
        return;
    }

    newElement->RX_UE_INFORMATION_TAG = rxTag;
    newElement->RNTI = rnti;
    newElement->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    newElement->next = nfa_list.head;

    nfa_list.head = newElement;
    ++nfa_list.count;

    pthread_mutex_unlock(&nfa_list.lock);
}

size_t getCurrentCount() {
    size_t count;

    pthread_mutex_lock(&nfa_list.lock);
    count = nfa_list.count;
    pthread_mutex_unlock(&nfa_list.lock);

    return count;
}
```

