import sqlite3

typedef struct {
    int bandwidth;        // in MHz
    int subcarrier_spacing;  // in kHz
    int cell_id;
} LtePhyConfig;

typedef struct {
    LtePhyConfig *configs;
    size_t count;
    size_t capacity;
