    pthread_mutex_t lock;
} PhyConfigList;

// Function to initialize the list and database connection
int init_phy_config_list(PhyConfigList *list, const char *db_path) {
    list->configs = NULL;
    list->count = 0;
    list->capacity = 0;
    if (sqlite3_open(db_path, &list->db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(list->db));
        return -1;
    }
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

// Function to resize the list
int resize_phy_config_list(PhyConfigList *list, size_t new_capacity) {
    LtePhyConfig *new_configs = realloc(list->configs, new_capacity * sizeof(LtePhyConfig));
    if (!new_configs) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    list->configs = new_configs;
    list->capacity = new_capacity;
    return 0;
}

// Function to add a configuration
int add_phy_config(PhyConfigList *list, LtePhyConfig config) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        if (resize_phy_config_list(list, new_capacity) != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->configs[list->count++] = config;

    // Save to database
    char *err_msg = NULL;
    sqlite3_stmt *stmt;
    const char *sql = "INSERT INTO phy_configurations (bandwidth, subcarrier_spacing, cell_id) VALUES (?, ?, ?)";

    if (sqlite3_prepare_v2(list->db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(list->db));
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    sqlite3_bind_int(stmt, 1, config.bandwidth);
    sqlite3_bind_int(stmt, 2, config.subcarrier_spacing);
    sqlite3_bind_int(stmt, 3, config.cell_id);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(list->db));
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to update configuration in the database
int update_phy_config_in_db(PhyConfigList *list, int cell_id, LtePhyConfig new_config) {
    char *err_msg = NULL;
    sqlite3_stmt *stmt;
    const char *sql = "UPDATE phy_configurations SET bandwidth=?, subcarrier_spacing=? WHERE cell_id=?";

    if (sqlite3_prepare_v2(list->db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(list->db));
        return -1;
    }

    sqlite3_bind_int(stmt, 1, new_config.bandwidth);
    sqlite3_bind_int(stmt, 2, new_config.subcarrier_spacing);
    sqlite3_bind_int(stmt, 3, cell_id);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(list->db));
        return -1;
    }

    sqlite3_finalize(stmt);
    return 0;
}

// Function to synchronize in-memory list with the database
int sync_with_database(PhyConfigList *list) {
    pthread_mutex_lock(&list->lock);

    char *err_msg = NULL;
    const char *sql = "SELECT bandwidth, subcarrier_spacing, cell_id FROM phy_configurations";
    sqlite3_stmt *stmt;

    if (sqlite3_prepare_v2(list->db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(list->db));
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        int bandwidth = sqlite3_column_int(stmt, 0);
        int subcarrier_spacing = sqlite3_column_int(stmt, 1);
        int cell_id = sqlite3_column_int(stmt, 2);

        // Check if this config already exists in the list
        for (size_t i = 0; i < list->count; ++i) {
            if (list->configs[i].cell_id == cell_id) {
                list->configs[i] = (LtePhyConfig){bandwidth, subcarrier_spacing, cell_id};
                break;
            }
        } else {
            // If not found, add it to the list
            LtePhyConfig new_config = {bandwidth, subcarrier_spacing, cell_id};
            if (add_phy_config(list, new_config) != 0) {
                fprintf(stderr, "Failed to add config from database\n");
                sqlite3_finalize(stmt);
                pthread_mutex_unlock(&list->lock);
                return -1;
            }
        }
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to handle errors and recovery
void handle_error_and_recover(PhyConfigList *list) {
    // Attempt to reconnect or notify about the failure
    if (sqlite3_errcode(list->db) == SQLITE_BUSY || sqlite3_errcode(list->db) == SQLITE_LOCKED) {
        fprintf(stderr, "Database is busy. Retrying...\n");
        sleep(1);  // Simple backoff strategy
        sqlite3_recover(list->db, NULL);
    } else if (sqlite3_errcode(list->db) != SQLITE_OK) {
        fprintf(stderr, "Unhandled database error: %s\n", sqlite3_errmsg(list->db));
    }
}

// Function to free the list resources and close the database
void cleanup_phy_config_list(PhyConfigList *list) {
    pthread_mutex_destroy(&list->lock);
    if (list->configs != NULL) {
        free(list->configs);
    }
    sqlite3_close(list->db);
}
