#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set to true or false
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    char *free_list;
} MemoryPool;

#define VALID_RNTI_MIN 0x0001
#define VALID_RNTI_MAX 0xFFFE

void log_error(const char *message) {
    // Example of a robust logging mechanism
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("error_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure the log is written immediately
}

// Initialize memory pool
MemoryPool* initialize_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory for pool");
        return NULL;
    }

    pool->block_size = block_size;
    pool->pool_size = num_blocks;

    // Allocate the entire pool
    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        perror("Failed to allocate memory blocks");
        free(pool);
        return NULL;
    }

    // Initialize the free list
    char *free_list_start = (char *)pool->pool;
    for (size_t i = 0; i < num_blocks - 1; ++i) {
        *(uint64_t *)(free_list_start + i * block_size) = ((uint64_t)(free_list_start + (i + 1) * block_size));
    }
    *(uint64_t *)(free_list_start + (num_blocks - 1) * block_size) = 0; // End of free list

    pool->free_list = free_list_start;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Allocate memory from the pool
void* allocate_memory(MemoryPool *pool) {
    if (!pool || !pool->free_list) {
        log_error("Memory pool is not initialized or exhausted");
        return NULL;
    }

    void *block = pool->free_list;

    pthread_mutex_lock(&pool->lock);
    pool->free_list = *(uint64_t *)pool->free_list;
    pthread_mutex_unlock(&pool->lock);

    return block;
}

// Free memory back to the pool
void free_memory(MemoryPool *pool, void *block) {
    if (!pool || !block) return;

    pthread_mutex_lock(&pool->lock);
    *(uint64_t *)block = (uint64_t)pool->free_list;
    pool->free_list = block;
    pthread_mutex_unlock(&pool->lock);
}

// Validate RNTI
bool is_valid_rnti(uint16_t rnti) {
    return rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX;
}

void process_nfa_indications(NFAPI_CRC_INDICATION_PDU_T *elements, size_t count, MemoryPool *pool) {
    if (!elements || !count || !pool) return;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = &elements[i];

        // Randomly set CRCFLAG
        element->CRCFLAG = rand() % 2 == 0;

        if (!is_valid_rnti(element->RNTI)) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Invalid RNTI: %u at index %zu", element->RNTI, i);
            log_error(log_msg);
            continue;
        }

        // Process the element (dummy processing)
        void *processed_data = allocate_memory(pool);
        if (processed_data) {
            // Simulate data copying
            memcpy(processed_data, element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free_memory(pool, processed_data); // Free after processing
        }
    }
}

// Example of usage
int main() {
    MemoryPool *pool = initialize_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ELEMENTS);
    if (!pool) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T elements[MAX_ELEMENTS];
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        elements[i].RX_UE_INFORMATION_TAG = i;
        elements[i].RNTI = VALID_RNTI_MIN + (i % (VALID_RNTI_MAX - VALID_RNTI_MIN + 1));
        elements[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    process_nfa_indications(elements, MAX_ELEMENTS, pool);

    free(pool->pool);
    free(pool);
    return EXIT_SUCCESS;
}
