}

int populate_crc_list(CRC_LIST_SYSTEM *system, size_t num_entries) {
    if (num_entries == 0 || num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Invalid number of entries\n");
        return -1;
    }

    pthread_mutex_lock(&system->mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(system->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_entries);
    if (!new_list) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&system->mutex);
        return -1;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        system->list[i].ue_info.RNTI = rand() % 65536; // Random RNTI
        memset(system->list[i].ue_info.RX_UE_INFORMATION_TAG, rand() % 256, sizeof(system->list[i].ue_info.RX_UE_INFORMATION_TAG));
        system->list[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        // Validation step
        if (system->list[i].ue_info.RNTI == 0 || 
            !memcmp(system->list[i].ue_info.RX_UE_INFORMATION_TAG, "\0", sizeof(system->list[i].ue_info.RX_UE_INFORMATION_TAG))) {
            fprintf(stderr, "Validation failed for entry %zu\n", i);
            pthread_mutex_unlock(&system->mutex);
            free(new_list);
            return -1;
        }
    }

    system->list = new_list;
    system->count = num_entries;

    pthread_mutex_unlock(&system->mutex);

    return 0; // Success
}

void cleanup_crc_list_system(CRC_LIST_SYSTEM *system) {
    pthread_mutex_lock(&system->mutex);
    free(system->list);
    system->list = NULL;
    system->count = 0;
    pthread_mutex_unlock(&system->mutex);
    pthread_mutex_destroy(&system->mutex);
}

// Serialization and deserialization functions
size_t serialize_crc_list(const CRC_LIST_SYSTEM *system, uint8_t **buffer) {
    size_t buffer_size = sizeof(size_t) + system->count * (sizeof(UE_INFO) + sizeof(CRC_INDICATION_REL8_TAG));
    *buffer = malloc(buffer_size);
    if (!*buffer) {
        return 0;
    }

    memcpy(*buffer, &system->count, sizeof(size_t));
    memcpy(*buffer + sizeof(size_t), system->list, buffer_size - sizeof(size_t));

    return buffer_size;
}

int deserialize_crc_list(CRC_LIST_SYSTEM *system, const uint8_t *buffer) {
    size_t count;
    memcpy(&count, buffer, sizeof(size_t));

    populate_crc_list(system, count);
    if (system->list == NULL) {
        return -1;
    }

    memcpy(system->list, buffer + sizeof(size_t), count * (sizeof(UE_INFO) + sizeof(CRC_INDICATION_REL8_TAG)));

    return 0; // Success
}

// Notification mechanism placeholder
void update_notification_callback() {
    printf("Notification: List updated\n");
}

int main() {
    CRC_LIST_SYSTEM system;
    init_crc_list_system(&system);

    size_t num_entries = generate_random_size(MAX_ENTRIES);
    if (populate_crc_list(&system, num_entries) == 0) {
        update_notification_callback();
    }

    uint8_t *serialized_data;
    size_t data_length = serialize_crc_list(&system, &serialized_data);
    if (data_length > 0) {
        printf("Serialized list length: %zu\n", data_length);
        free(serialized_data);
    }

    cleanup_crc_list_system(&system);

    return 0;
}
