#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_STRUCTS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} List;

// Memory pool for the structures
static void* memory_pool[MAX_STRUCTS];
static bool pool_initialized = false;

void init_memory_pool() {
    if (!pool_initialized) {
        for (size_t i = 0; i < MAX_STRUCTS; ++i) {
            memory_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        pool_initialized = true;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        if (memory_pool[i] != NULL) {
            NFAPI_CRC_INDICATION_PDU_T* ptr = memory_pool[i];
            memory_pool[i] = NULL;
            return ptr;
        }
    }
    // Fallback in case all are occupied
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (structure != NULL && !is_memory_pool_used(structure)) {
        for (size_t i = 0; i < MAX_STRUCTS; ++i) {
            if (memory_pool[i] == NULL) {
                memory_pool[i] = structure;
                break;
            }
        }
    } else {
        free(structure);
    }
}

bool is_memory_pool_used(NFAPI_CRC_INDICATION_PDU_T* structure) {
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        if (memory_pool[i] == structure) return true;
    }
    return false;
}

void init_list(List* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

bool is_structure_valid(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validation logic for the structure
    return pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0; 
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->count >= MAX_STRUCTS || !is_structure_valid(pdu)) return;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)allocate_structure();
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Randomly set CRCFLAG
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(List* list, size_t index) {
    if (index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(result, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&list->lock);

    return result;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        deallocate_structure((NFAPI_CRC_INDICATION_PDU_T*)current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    init_memory_pool();

    List pdu_list;
    init_list(&pdu_list);

    // Populate and manage the list here
    NFAPI_CRC_INDICATION_PDU_T sample_pdu = {1, 12345};
    add_to_list(&pdu_list, &sample_pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_from_list(&pdu_list, 0);

    free(retrieved_pdu); // Remember to deallocate after use
    free_list(&pdu_list);

    return 0;
}
```

### Explanation of Design Decisions:
1. **Memory Pool**: A memory pool is used for fixed allocation of `NFAPI_CRC_INDICATION_PDU_T` structures, minimizing dynamic allocation overhead and reducing fragmentation.
2. **Thread Safety**: A mutex (`pthread_mutex_t`) ensures thread-safe operations on the list, preventing race conditions during concurrent insertions or retrievals.
3. **Validation**: Structures are validated before insertion to maintain data integrity.
4. **Efficient Operations**: Insertion and retrieval operations are designed for efficiency in terms of both time complexity (O(1) insertion at head, O(n) retrieval by index) and memory usage.
5. **Resource Management**: The system limits the number of structures stored based on `MAX_STRUCTS`, ensuring controlled resource utilization.

This implementation balances thread safety, performance, and efficient resource management, suitable for high-concurrency scenarios in large-scale applications.']

