#define MAX_RETRIES 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate retrieving an RNTI from an external source
int get_RNTI_from_external_source() {
    // Simulate network delay and potential timeout scenario
    if (rand() % 10 < 2) {  // Simulating a 20% chance of failure
        return -1;  // Indicating a failed attempt to retrieve RNTI
    }
    return rand() % 10000 + 1;  // Return a valid RNTI
}

// Function to handle network retries with exponential backoff
int fetch_RNTI_with_retries(int max_retries) {
    int rnti = -1;
    int attempt = 0;
    while (attempt < max_retries) {
        rnti = get_RNTI_from_external_source();
        if (rnti != -1) {
            return rnti;  // Successfully retrieved RNTI
        }
        sleep(1 << attempt);  // Exponential backoff: 1, 2, 4, ...
        attempt++;
    }
    fprintf(stderr, "Failed to retrieve RNTI after %d attempts\n", max_retries);
    return -1;
}

// Function to initialize the dynamic array
NFAPI_CRC_INDICATION_PDU_T* init_dynamic_array(size_t num_elements) {
    if (num_elements == 0) {
        fprintf(stderr, "Error: Number of elements must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for the array");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_elements; ++i) {
        int rnti = fetch_RNTI_with_retries(MAX_RETRIES);
        if (rnti == -1) {
            fprintf(stderr, "Skipping element %zu due to RNTI retrieval failure.\n", i + 1);
            array[i].RX_UE_INFORMATION_TAG = -1;
            continue;  // Skip this element
        }

        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = (rand() % 2) ? 0xFF : 0x00; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&mutex);

    return array;
}

// Function to free the dynamic array
void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t num_elements) {
    if (array) {
        free(array);
    }
}

int main() {
    size_t num_elements = 10;  // Example number of elements

    NFAPI_CRC_INDICATION_PDU_T *dynamic_array = init_dynamic_array(num_elements);

    if (!dynamic_array) {
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        printf("Element %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=0x%02X, CRCFLAG=0x%02X\n",
