            dynamic_array[i].RX_UE_INFORMATION_TAG,
            dynamic_array[i].RNTI,
            dynamic_array[i].CRC_INDICATION_REL8_TAG,
            dynamic_array[i].CRCFLAG);
    }

    free_dynamic_array(dynamic_array, num_elements);

    return EXIT_SUCCESS;
}
