```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

// Constants
#define MAX_ELEMENTS 1000
#define RNTI_MIN_VALUE 1
#define RNTI_MAX_VALUE 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t mutex;
} PduManager;

// Function Prototypes
PduManager* create_pdu_manager();
void destroy_pdu_manager(PduManager *manager);
bool add_pdu_element(PduManager *manager, int rx_ue_tag, int rnti);
size_t get_pdu_count(const PduManager *manager);
bool is_rnti_valid(int rnti);

// Function Implementations
PduManager* create_pdu_manager() {
    PduManager *manager = malloc(sizeof(PduManager));
    if (manager) {
        manager->count = 0;
        pthread_mutex_init(&manager->mutex, NULL);
        for (int i = 0; i < MAX_ELEMENTS; ++i) {
            manager->elements[i] = NULL;
        }
    }
    return manager;
}

void destroy_pdu_manager(PduManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->elements[i]);
        }
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

bool is_rnti_valid(int rnti) {
    return rnti >= RNTI_MIN_VALUE && rnti <= RNTI_MAX_VALUE;
}

bool add_pdu_element(PduManager *manager, int rx_ue_tag, int rnti) {
    if (!is_rnti_valid(rnti)) {
        return false;
    }

    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&manager->mutex);
        return false; // No space to add more elements
    }

    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        pthread_mutex_unlock(&manager->mutex);
        return false; // Memory allocation failed
    }

    element->RX_UE_INFORMATION_TAG = rx_ue_tag;
    element->RNTI = rnti;
    srand(time(NULL)); // Seed the random number generator
    element->CRCFLAG = rand() % 2 == 0;

    manager->elements[manager->count++] = element;
    pthread_mutex_unlock(&manager->mutex);

    return true;
}

size_t get_pdu_count(const PduManager *manager) {
    size_t count;

    pthread_mutex_lock((pthread_mutex_t*)&manager->mutex);
    count = manager->count;
    pthread_mutex_unlock((pthread_mutex_t*)&manager->mutex);

    return count;
}
```

