// Initialize the CRC array manager
int init_crc_array_manager(CRCArrayManager *manager, size_t initial_capacity) {
    if (initial_capacity == 0) return -1;

    manager->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->data) return -1; // Error on memory allocation

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

// Resize the array when needed
int resize_crc_array_manager(CRCArrayManager *manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

