}

// Add a new element to the array
int add_crc_element(CRCArrayManager *manager, uint32_t rx_ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        int result = resize_crc_array_manager(manager, new_capacity);
        if (result != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Error on resizing
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &manager->data[manager->count];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;

    // Randomly set CRCFLAG
    srand(time(NULL) ^ pthread_self());
    int crcflag_value = rand() % 2; // Random value 0 or 1
    atomic_store(&element->CRC_INDICATION_REL8_TAG.CRCFLAG, crcflag_value);

    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Filter elements based on RNTI values provided in a separate array
void filter_crc_elements(const CRCArrayManager *manager, uint16_t *rnti_filter_array, size_t filter_count, NFAPI_CRC_INDICATION_PDU_T **filtered_data) {
    pthread_mutex_lock(&manager->lock);

    // Count elements that match the filter criteria
    size_t filtered_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        for (size_t j = 0; j < filter_count; ++j) {
            if (manager->data[i].RNTI == rnti_filter_array[j]) {
                filtered_count++;
                break;
            }
        }
    }

    *filtered_data = malloc(filtered_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*filtered_data) {
        pthread_mutex_unlock(&manager->lock);
        return; // Error on memory allocation
    }

    size_t k = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        for (size_t j = 0; j < filter_count; ++j) {
            if (manager->data[i].RNTI == rnti_filter_array[j]) {
                (*filtered_data)[k++] = manager->data[i];
                break;
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Clean up the CRC array manager
void cleanup_crc_array_manager(CRCArrayManager *manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
}
