} UnionFind;

UnionFind* UF_create(size_t n) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->parent = calloc(n, sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; ++i) uf->parent[i] = i;
    return uf;
}

void UF_destroy(UnionFind *uf) {
    free(uf->parent);
    free(uf);
}

int UF_find(UnionFind *uf, int x) {
