['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set true or false
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

typedef struct {
    PduNode* head;
    PduNode* tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} PduList;

// Function prototypes
PduList* create_pdu_list();
void destroy_pdu_list(PduList* list);
bool add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
bool clear_pdus(PduList* list);
void log_batch_size(const char* message, size_t batch_size);

// Function implementations
PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);

    return list;
}

void destroy_pdu_list(PduList* list) {
    if (!list) return;

    PduNode* current = list->head;
    while (current) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

bool add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return false;

    PduNode* node = (PduNode*)malloc(sizeof(PduNode));
    if (!node) return false;

    node->pdu = pdu;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = node;
    } else {
        list->tail->next = node;
    }
    list->tail = node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool clear_pdus(PduList* list) {
    if (!list) return false;

    pthread_mutex_lock(&list->lock);

    PduNode* current = list->head;
    while (current) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void log_batch_size(const char* message, size_t batch_size) {
    printf("%s: %zu PDUs processed\n", message, batch_size);
}

// Usage example
#define BATCH_SIZE 1000

void* process_pdus(void* arg) {
    PduList* list = (PduList*)arg;
    while (true) {
        pthread_mutex_lock(&list->lock);

        if (!list->head) {
            pthread_cond_wait(&list->cond_var, &list->lock);
        }

        size_t count = 0;
        while (list->head && count < BATCH_SIZE) {
            PduNode* node = list->head;
            list->head = node->next;
            if (!list->head) {
                list->tail = NULL;
            }
            free(node);
            count++;
        }

        pthread_mutex_unlock(&list->lock);

        log_batch_size("Batch processed", count);

        // Simulate some processing delay
        usleep(1000); 
    }
}

int main() {
    PduList* pdu_list = create_pdu_list();
    if (!pdu_list) {
        fprintf(stderr, "Failed to create PDU list\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_pdus, pdu_list);
    }

    // Simulate adding PDUs
    for (size_t i = 0; i < 10000000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;

        add_pdu(pdu_list, pdu);

        pthread_mutex_lock(&pdu_list->lock);
        pthread_cond_signal(&pdu_list->cond_var);
        pthread_mutex_unlock(&pdu_list->lock);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_pdu_list(pdu_list);

    return EXIT_SUCCESS;
}
