// Thread-safe function to add a structure to the collection
int add_structure(NFAPI_Collection* collection, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection is full
    }

    // Ensure no consecutive structures share the same RNTI
    if (collection->count > 0 &&
        collection->array[collection->count - 1]->RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Consecutive RNTI match
