    collection->array[collection->count++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->array[collection->count - 1]) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Memory allocation failed
