typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_or_update_node(List* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == new_data.RNTI) {
            current->data = new_data; // Update existing node
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_node_by_rnti(List* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void cleanup_unused_memory(List* list, float threshold) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    size_t total_size = 0;

    while (current != NULL) {
        total_size += sizeof(Node);
        prev = current;
        current = current->next;
    }

    if ((total_size * (100 - threshold)) / 100 < sizeof(List)) {
        Node* temp;
        while (list->head != NULL) {
            temp = list->head;
            list->head = list->head->next;
            free(temp);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void log_operation(const char *message, int verbosity_level, int level) {
    if (verbosity_level >= level) {
        printf("%s\n", message);
    }
}

int periodic_update(List* list, int retry_count, int delay_ms) {
    for (int i = 0; i < retry_count; ++i) {
        // Simulate update from external data source
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 10000; // Example RNTI range
        pdu.CRC_INDICATION_REL8_TAG = rand() & 1; // Random CRCFLAG

        if (add_or_update_node(list, pdu) == 0) {
            log_operation("Updated RNTI successfully", 2, 1);
            return 0;
        }

        usleep(delay_ms * 1000); // Delay before retry
    }

    log_operation("Failed to update after retries", 1, 1);
    return -1; // Update failure after retries
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    List* list = create_list();

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 4567, .CRC_INDICATION_REL8_TAG = 1 };
    add_or_update_node(list, pdu);

    cleanup_unused_memory(list, 50.0); // Clean up if unused memory > 50%

    periodic_update(list, 3, 500); // Retry update 3 times with 500ms delay

    remove_node_by_rnti(list, 4567);

    free_list(list);

    return 0;
