typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

uint32_t hash_rnti(uint16_t rnti) {
    return (rnti * 2654435761u) % 4294967296u; // FNV-1a hash function
}

void init_dynamic_array(DynamicArray* da, size_t initial_capacity) {
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void resize_dynamic_array(DynamicArray* da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->array = temp;
    da->capacity = new_capacity;
}

void add_entry(DynamicArray* da, uint32_t rx_ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
    }

    UE_INFO_TAG ue_info = {rx_ue_info_tag, rnti};
    CRC_INDICATION_REL8_TAG crc_tag = {
        .CRCFLAG = hash_rnti(rnti) & 1, // Example flag setting based on RNTI
        .RX_UE_INFORMATION_TAG = rx_ue_info_tag,
        .RNTI = rnti
    };

    da->array[da->count].ue_info = ue_info;
    da->array[da->count++].crc_tag = crc_tag;

    pthread_mutex_unlock(&da->lock);
}

void cleanup_expired_entries(DynamicArray* da) {
    // Placeholder for actual expiration logic, e.g., time-based removal
    pthread_mutex_lock(&da->lock);

    size_t i = 0;
    while (i < da->count) {
        if ((hash_rnti(da->array[i].crc_tag.RNTI) & 2) == 0) { // Example condition for expiration
            memmove(&da->array[i], &da->array[i + 1],
                    (da->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --da->count;
        } else {
            ++i;
        }
    }

    if (da->capacity > da->count && da->capacity / 2 >= da->count) {
        resize_dynamic_array(da, da->capacity / 2);
    }

    pthread_mutex_unlock(&da->lock);
}

void free_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;

    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

