    DynamicArray da;
    init_dynamic_array(&da, 10);

    add_entry(&da, 123456789, 1001);
    add_entry(&da, 987654321, 1002);

    cleanup_expired_entries(&da); // Call periodically

    free_dynamic_array(&da);
