```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 256

typedef struct {
    int sender_id;
    time_t timestamp;
    char payload[MAX_PAYLOAD_SIZE];
} Message;

typedef struct MessageNode {
    Message message;
    struct MessageNode* next;
} MessageNode;

typedef struct {
    MessageNode* head;
    pthread_mutex_t lock;
} MessageCollection;

MessageCollection* create_collection() {
    MessageCollection* collection = (MessageCollection*)malloc(sizeof(MessageCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void free_message_node(MessageNode* node) {
    if (node) {
        free(node);
    }
}

int add_message(MessageCollection* collection, int sender_id, const char* payload) {
    if (!collection || strlen(payload) >= MAX_PAYLOAD_SIZE) return -1;

    pthread_mutex_lock(&collection->lock);

    MessageNode* new_node = (MessageNode*)malloc(sizeof(MessageNode));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    new_node->message.sender_id = sender_id;
    new_node->message.timestamp = time(NULL);
    strncpy(new_node->message.payload, payload, MAX_PAYLOAD_SIZE);

    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_message_by_sender(MessageCollection* collection, int sender_id) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->lock);

    MessageNode *current = collection->head, *prev = NULL;
    while (current) {
        if (current->message.sender_id == sender_id) {
            if (prev) prev->next = current->next;
            else collection->head = current->next;

            free_message_node(current);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Not found
}

Message* get_latest_message(MessageCollection* collection, int sender_id) {
    if (!collection) return NULL;

    pthread_mutex_lock(&collection->lock);

    MessageNode* latest = NULL;
    for (MessageNode* current = collection->head; current; current = current->next) {
        if (current->message.sender_id == sender_id) {
            if (!latest || current->message.timestamp > latest->message.timestamp) {
                latest = current;
            }
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return latest ? &latest->message : NULL;
}

void prune_old_messages(MessageCollection* collection, time_t cutoff_time) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    MessageNode *current = collection->head, *prev = NULL;
    while (current) {
        if (difftime(current->message.timestamp, cutoff_time) < 0) {
            prev = current;
            current = current->next;
        } else {
            MessageNode* to_delete = current;
            if (prev) prev->next = current->next;
            else collection->head = current->next;

            current = current->next;
            free_message_node(to_delete);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void destroy_collection(MessageCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    MessageNode* current = collection->head;
    while (current) {
        MessageNode* next = current->next;
        free_message_node(current);
        current = next;
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for locking to ensure safe concurrent access.
- **Memory Management**: Properly allocates and frees memory for message nodes.
- **Error Handling**: Returns error codes for failures in operations like adding messages or removing by sender ID.
- **Pruning**: Implements a function to remove old messages based on a timestamp cutoff.

This implementation can be extended with additional features as needed, such as more sophisticated error handling or integration with external systems.']

