    png_init_io(png_ptr, fp);
    png_read_info(png_ptr, info_ptr);

    // Perform checks and load data into theme_cache (pseudo-code)
    // ...

    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    fclose(fp);

    pthread_mutex_unlock(&cache_lock);
}

void encryptAndStoreThemeData(const unsigned char *data, size_t data_len, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    int len;
    unsigned char encrypted_data[1024];
    int encrypted_len = 0;

    // Initialize the encryption operation
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Encrypt data in-place
    if (1 != EVP_EncryptUpdate(ctx, encrypted_data, &len, data, data_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    encrypted_len = len;

    // Finalize encryption
    if (1 != EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    encrypted_len += len;

    // Store or use the encrypted data as needed
    // ...

    EVP_CIPHER_CTX_free(ctx);
}
