    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    pdu->RNTI = rand() % 65535;
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    pdu->CRCFLAG = rand() % 2;
}

void initialize_dynamic_array(DynamicArray *da) {
    da->capacity = INITIAL_SIZE;
    da->count = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&da->lock, NULL);
}

void resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

void add_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->count == da->capacity) {
        resize_dynamic_array(da);
    }
    initialize_pdu(&pdu); // Ensure the structure is initialized
    da->array[da->count++] = pdu;
    pthread_mutex_unlock(&da->lock);
}

void periodic_garbage_collection(DynamicArray *da, size_t threshold) {
    pthread_mutex_lock(&da->lock);
    if (da->count < threshold) {
        size_t new_capacity = da->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array) {
            memcpy(new_array, da->array, da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(da->array);
            da->array = new_array;
            da->capacity = new_capacity;
        }
    }
    pthread_mutex_unlock(&da->lock);
}

void verify_integrity(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        // Simple check: ensure CRCFLAG is either 0 or 1
        if (da->array[i].CRCFLAG != 0 && da->array[i].CRCFLAG != 1) {
            fprintf(stderr, "Data integrity violation at index %zu\n", i);
        }
    }
    pthread_mutex_unlock(&da->lock);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->capacity = 0;
    da->count = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}
