#define MAX_CONFIGS 1024

typedef struct {
    char IPAddress[16];
    int PortNumber;
    char ConnectionStatus[20];
} NetworkInterfaceConfig;

typedef struct {
    NetworkInterfaceConfig configs[MAX_CONFIGS];
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

int validateIPAddress(const char *ipAddress) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ipAddress, &(sa.sin_addr)) == 1;
}

void initializeConfigManager(ConfigManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int fetchConfigurationData(NetworkInterfaceConfig *config) {
    // Simulate fetching data with potential delay or failure
    if (rand() % 10 < 2) return -1; // Simulate 20% chance of failure

    strcpy(config->IPAddress, "192.168.0.1");
    config->PortNumber = rand() % 65535 + 1;
    strcpy(config->ConnectionStatus, "Active");

    return 0;
}

int addOrUpdateNetworkInterface(ConfigManager *manager, const char *ipAddress) {
    pthread_mutex_lock(&manager->lock);

    if (!validateIPAddress(ipAddress)) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid IP address format
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i].IPAddress, ipAddress) == 0) {
            if (fetchConfigurationData(&manager->configs[i]) != 0) {
                pthread_mutex_unlock(&manager->lock);
                return -1; // Failed to update configuration
            }
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->count >= MAX_CONFIGS) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // No space for new configuration
    }

    NetworkInterfaceConfig *newConfig = &manager->configs[manager->count++];
    strcpy(newConfig->IPAddress, ipAddress);

    if (fetchConfigurationData(newConfig) != 0) {
        manager->count--;
        pthread_mutex_unlock(&manager->lock);
        return -1; // Failed to initialize new configuration
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void cleanup(ConfigManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
