// Utility function to validate service name and version format
bool isValidService(const char *name, const char *version) {
    if (strlen(name) == 0 || strlen(name) > MAX_SERVICE_NAME_LENGTH) return false;

    for (char *p = (char *)name; *p != '\0'; p++) {
        if (!isalnum(*p)) return false;
    }

    int major, minor, patch;
    return sscanf(version, "%d.%d.%d", &major, &minor, &patch) == 3 && 
           major >= 0 && minor >= 0 && patch >= 0;
}

// Utility function to generate a unique service ID
int generateUniqueServiceID(ServiceInstance *services, size_t count, int baseID) {
    for (size_t i = 1; ; ++i) {
        if (baseID + i > INT_MAX) return -1; // Prevent overflow
        bool exists = false;
        for (size_t j = 0; j < count; ++j) {
            if (services[j].ServiceID == baseID + i) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            return baseID + i;
        }
    }
}

// Main function to initialize and validate services
ServiceInstance* initializeAndValidateServices() {
    ServiceInstance *services = NULL;
    size_t count = 0;

    // Fetch data from an external API
    if (fetchServiceData(&services, &count) != 0) {
        fprintf(stderr, "Failed to fetch service data.\n");
        return NULL;
    }

    // Validate and ensure unique IDs
    for (size_t i = 0; i < count; ++i) {
        if (!isValidService(services[i].ServiceName, services[i].ServiceVersion)) {
            fprintf(stderr, "Invalid service metadata for %s.\n", services[i].ServiceName);
            free(services);
            return NULL;
        }

        // Ensure unique ServiceID
        int originalID = services[i].ServiceID;
        if (generateUniqueServiceID(services, i, 0) != originalID) {
            services[i].ServiceID = generateUniqueServiceID(services, count, 0);
            printf("Resolved ID conflict for %s. New ID: %d\n", services[i].ServiceName, services[i].ServiceID);
        }
    }

    // Check memory usage
    if (count * sizeof(ServiceInstance) > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeded threshold.\n");
        free(services);
        return NULL;
    }

    printf("Services initialized successfully. Total: %zu\n", count);
    return services;
}

