    LTEPHY_RRC_CONFIGURATION_T *new_configurations = (LTEPHY_RRC_CONFIGURATION_T *)realloc(manager->configurations, new_capacity * sizeof(LTEPHY_RRC_CONFIGURATION_T));
    if (new_configurations) {
