typedef struct {
    time_t timestamp;
    int packet_size;
    char source_ip[16];
    char destination_ip[16];
} NetworkPacket;

int is_valid_ip(const char *ip) {
    return (inet_pton(AF_INET, ip, NULL) == 1);
}

int generate_random_packet(NetworkPacket *packet) {
    time(&packet->timestamp);
    packet->packet_size = rand() % 1401 + 100; // Random size between 100 and 1500

    static int source_counter = 0;
    snprintf(packet->source_ip, sizeof(packet->source_ip), "192.168.%d.%d", (source_counter / 255) + 1, source_counter % 255);
    source_counter++;

    static int dest_counter = 100;
    snprintf(packet->destination_ip, sizeof(packet->destination_ip), "10.0.%d.%d", (dest_counter / 255) + 1, dest_counter % 255);
    dest_counter++;

    return is_valid_ip(packet->source_ip) && is_valid_ip(packet->destination_ip);
}

void load_packets_from_csv(NetworkPacket **packets, int *num_packets, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    NetworkPacket temp_packet;
    while (fscanf(file, "%ld,%d,%15[^,],%15s", &temp_packet.timestamp, &temp_packet.packet_size,
                  temp_packet.source_ip, temp_packet.destination_ip) == 4) {
        if (is_valid_ip(temp_packet.source_ip) && is_valid_ip(temp_packet.destination_ip)) {
            *packets = realloc(*packets, (*num_packets + 1) * sizeof(NetworkPacket));
            if (*packets) {
                memcpy(&((*packets)[*num_packets]), &temp_packet, sizeof(NetworkPacket));
                (*num_packets)++;
            }
        }
    }

    fclose(file);
}

NetworkPacket* allocate_and_populate_packets(int desired_count, const char *csv_filename) {
    NetworkPacket *packets = NULL;
    int num_packets = 0;
    int success_count = 0;
    int failure_count = 0;

    srand(time(NULL));

    load_packets_from_csv(&packets, &num_packets, csv_filename);

    while (num_packets < desired_count) {
        NetworkPacket new_packet;
        if (generate_random_packet(&new_packet)) {
            packets = realloc(packets, (num_packets + 1) * sizeof(NetworkPacket));
            if (packets) {
                memcpy(&packets[num_packets], &new_packet, sizeof(NetworkPacket));
                num_packets++;
                success_count++;
            } else {
                failure_count++;
            }
        }

        if (!packets && num_packets < desired_count) break;
    }

    printf("Packets successfully allocated: %d\n", success_count);
    printf("Allocation failures due to memory constraints: %d\n", failure_count);

    return packets;
}

void free_packet_array(NetworkPacket *packets) {
    free(packets);
}
