    Packet** packetList;
    size_t maxSize;
    size_t currentSize;
    time_t timestamp;
} TrafficFlow;

void optimizedInitFlow(TrafficFlow* flow, int maxInitialSize) {
    flow->packetList = (Packet**)malloc(maxInitialSize * sizeof(Packet*));
    for (int i = 0; i < maxInitialSize; i++) {
        flow->packetList[i] = NULL;
    }
    flow->maxSize = maxInitialSize;
    flow->currentSize = 0;
