Packet* createPacket(int data) {
    Packet* newPacket = (Packet*)malloc(sizeof(Packet));
    if (!newPacket) return NULL; // Check for memory allocation failure
    newPacket->data = data;
    return newPacket;
}

int insertPacket(TrafficFlow* flow, Packet* packet) {
    if (flow->currentSize >= flow->maxSize) {
        size_t newSize = flow->maxSize * 2;
        Packet** newList = (Packet**)realloc(flow->packetList, newSize * sizeof(Packet*));
        if (!newList) return -1; // Check for memory allocation failure
        flow->packetList = newList;

        for (size_t i = flow->currentSize; i < newSize; ++i) {
            flow->packetList[i] = NULL;
        }
        flow->maxSize = newSize;
    }

    flow->packetList[flow->currentSize++] = packet;
    time(&flow->timestamp);
    return 0;
}

Packet* retrievePacket(TrafficFlow* flow, size_t index) {
    if (index < flow->currentSize) {
        return flow->packetList[index];
    }
    return NULL; // Index out of bounds
}

void freeTrafficFlow(TrafficFlow* flow) {
    for (size_t i = 0; i < flow->currentSize; ++i) {
        if (flow->packetList[i]) {
            free(flow->packetList[i]);
        }
    }
    free(flow->packetList);
}

int main() {
    TrafficFlow flow;
    optimizedInitFlow(&flow, 5);

    for (int i = 0; i < 10; ++i) { // Insert more packets than initial size
        Packet* packet = createPacket(i * 100);
        if (!packet) break; // Handle memory allocation failure
        insertPacket(&flow, packet);
    }

    for (size_t i = 0; i < flow.currentSize; ++i) {
        Packet* pkt = retrievePacket(&flow, i);
        if (pkt) printf("Packet %zu: Data=%d\n", i, pkt->data);
    }

    freeTrafficFlow(&flow);

    return 0;
}
```

This code provides a basic framework for managing `TrafficFlow` structures with dynamic packet lists. It includes initialization, insertion, retrieval, and cleanup functions, ensuring efficient memory management and scalability for high-throughput scenarios.']

