            std::lock_guard<std::mutex> lock(log_mutex);
            std::cout << "[LOG] " << message << std::endl;
        }
    }

private:
    std::mutex log_mutex;

public:
    void concurrent_access_example() {
        std::thread t1([this]() { access_entities(); });
        std::thread t2([this]() { modify_entity(0); });

        t1.join();
        t2.join();
    }

    void access_entities() {
        for (const auto& entity : entities) {
            log_event("Accessing UE_ID: " + std::to_string(entity->rx_ue_info_tag.ue_id));
        }
    }

    void modify_entity(size_t index) {
        if (index < entities.size()) {
