    NFAPI_L1_RX_FRAME_INFO_T **new_frames = (NFAPI_L1_RX_FRAME_INFO_T **)realloc(array->frames, new_capacity * sizeof(NFAPI_L1_RX_FRAME_INFO_T *));
    if (new_frames) {
        array->frames = new_frames;
        array->capacity = new_capacity;
    } else {
