        fprintf(stderr, "Failed to resize dynamic frame array\n");
        exit(EXIT_FAILURE);
    }
}

void add_frame(DynamicFrameArray *array, const L1_RRC_CTXT_T *ctxt) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_dynamic_frame_array(array);
    }

    NFAPI_L1_RX_FRAME_INFO_T *frame = (NFAPI_L1_RX_FRAME_INFO_T *)malloc(sizeof(NFAPI_L1_RX_FRAME_INFO_T));
    if (!frame) {
        fprintf(stderr, "Failed to allocate memory for new frame\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    frame->ctxt = *ctxt; // Assuming a shallow copy is sufficient
    frame->pdu = (L1_RX_PDU_T *)malloc(sizeof(L1_RX_PDU_T));
    if (!frame->pdu) {
        fprintf(stderr, "Failed to allocate memory for L1_RX_PDU_T\n");
        free(frame);
        pthread_mutex_unlock(&array->lock);
        return;
    }

    array->frames[array->count++] = frame;

    pthread_mutex_unlock(&array->lock);
}

void remove_frame(DynamicFrameArray *array, size_t index) {
    if (index >= array->count) return; // Invalid index

    pthread_mutex_lock(&array->lock);

    NFAPI_L1_RX_FRAME_INFO_T *frame = array->frames[index];
    free(frame->pdu);
    free(frame);

    for (size_t i = index; i < array->count - 1; ++i) {
        array->frames[i] = array->frames[i + 1];
    }

    array->count--;

    pthread_mutex_unlock(&array->lock);
}

void iterate_frames(DynamicFrameArray *array, void (*operation)(NFAPI_L1_RX_FRAME_INFO_T *)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        operation(array->frames[i]);
    }

    pthread_mutex_unlock(&array->lock);
}

void cleanup_dynamic_frame_array(DynamicFrameArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->frames[i]->pdu);
        free(array->frames[i]);
    }

    free(array->frames);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
