import time.h

#define INITIAL_CAPACITY 100
#define SESSION_EXPIRATION_THRESHOLD 60 // seconds

typedef struct {
    int sessionID;
    time_t timestamp;
    size_t bufferCapacity;
    char *packetBuffer;
} Session;

typedef struct {
    Session **sessions;
    size_t capacity;
    size_t count;
} SessionManager;

SessionManager* createSessionManager() {
    SessionManager *manager = malloc(sizeof(SessionManager));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->sessions = calloc(manager->capacity, sizeof(Session *));
    return manager;
}

void resizeSessionsArray(SessionManager *manager) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        Session **newSessions = realloc(manager->sessions, newCapacity * sizeof(Session *));
        if (newSessions) {
            manager->sessions = newSessions;
            manager->capacity = newCapacity;
        }
    }
}

void addSession(SessionManager *manager, int sessionID, size_t initialBufferCapacity) {
    resizeSessionsArray(manager);

    Session *session = malloc(sizeof(Session));
    session->sessionID = sessionID;
    session->timestamp = time(NULL);
    session->bufferCapacity = initialBufferCapacity;
    session->packetBuffer = malloc(initialBufferCapacity);

    manager->sessions[manager->count++] = session;
}

void removeSessionById(SessionManager *manager, int sessionID) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->sessionID == sessionID) {
            free(manager->sessions[i]->packetBuffer);
            free(manager->sessions[i]);

            // Shift remaining sessions
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(Session *));
            manager->count--;
            break;
        }
    }
}

void processSessions(SessionManager *manager) {
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < manager->count; ++i) {
        Session *session = manager->sessions[i];

        // Process session packet data
        printf("Processing session %d\n", session->sessionID);
        // Example processing: handle session->packetBuffer data

        if (difftime(currentTime, session->timestamp) > SESSION_EXPIRATION_THRESHOLD) {
            removeSessionById(manager, session->sessionID);
            i--; // Adjust index after removal
        }
    }
}

void cleanup(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]->packetBuffer);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    free(manager);
}

int main() {
    SessionManager *manager = createSessionManager();

    addSession(manager, 1, 1024);
    addSession(manager, 2, 2048);

    processSessions(manager); // Simulate processing and check expiration

    cleanup(manager);

    return 0;
}
