    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < n && list->count < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_pdu;

        // Assign a unique RNTI value
        new_pdu.rnti = rand() % UINT32_MAX + 1;

        // Check for uniqueness in the current list
        int is_unique = 1;
        for (size_t j = 0; j < list->count && is_unique; ++j) {
            if (list->array[j].rnti == new_pdu.rnti) {
                is_unique = 0;
            }
        }

        if (!is_unique) continue;

        // Randomly set CRCFLAG in the CRC_INDICATION_REL8_TAG
        new_pdu.crcTag.crcFlag = rand() % 2; // Example: binary random flag

        // Set a placeholder value for RX_UE_INFORMATION_TAG
        new_pdu.rxUeInformationTag = i + 1;

        // Add to list if unique RNTI is found
        if (list->count < list->capacity) {
            list->array[list->count++] = new_pdu;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    // Log the number of unique RNTIs used
    printf("Number of unique RNTI values: %zu\n", list->count);
}

// Function to clean up resources and prevent memory leaks
void cleanup_crc_indication_list(CRCIndicationList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->array);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int main() {
    const size_t MAX_SIZE = 1000;
    CRCIndicationList list;

    init_crc_indication_list(&list, MAX_SIZE);

    // Example: Generate 500 PDU structures
    generate_crc_indications(&list, 500);

    cleanup_crc_indication_list(&list);
    return 0;
}
