#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    unsigned int size;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->size = 0;
    return array;
}

int resize_if_needed(DynamicArray* array, unsigned int target_size) {
    const unsigned int max_size = 10000;
    if (target_size > max_size) {
        fprintf(stderr, "Exceeded maximum capacity\n");
        return -1;
    }
    return 0;
}

Node* find_node_by_rnti(DynamicArray* array, unsigned int rnti) {
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

int insert_or_update(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* node = find_node_by_rnti(array, new_data.RNTI);
    if (node) {
        node->data = new_data;  // Update existing
    } else {
        if (resize_if_needed(array, array->size + 1) != 0) return -1;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) return -1;

        new_node->data = new_data;
        new_node->next = array->head;
        array->head = new_node;
        array->size++;
    }
    return 0;
}

void validate_and_repair(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        // Simulate validation logic: randomly set CRCFLAG
        srand(time(NULL));  // Ideally, seed once globally
        int valid_crc = rand() % 2;  // Randomly determine validity

        if (!valid_crc) {  // Simulated corruption detected
            fprintf(stderr, "Repairing corrupted entry with RNTI: %u\n", current->data.RNTI);
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = valid_crc;
        }

        current = current->next;
    }
}

void free_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    free(array);
}

int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = {0};
    strcpy(data.RX_UE_INFORMATION_TAG, "ExampleTag");
    data.RNTI = 12345;

    for (int i = 0; i < 100; ++i) {
        if (insert_or_update(array, data) != 0) {
            fprintf(stderr, "Failed to insert/update\n");
            free_dynamic_array(array);
            return -1;
        }
        // Modify RNTI and CRCFLAG for each iteration
        data.RNTI += i;
        data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    validate_and_repair(array);

    free_dynamic_array(array);
    return 0;
}
