['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDU_COUNT 1000
#define CRC_POLYNOMIAL 0x04C11DB7

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint32_t CRCFLAG; // To store computed CRC checksum
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDU_COUNT];
    size_t count;
    pthread_mutex_t mutex;
} PDU_COLLECTION;

static uint32_t compute_crc(uint8_t *data, size_t length) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i] << 24;
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80000000) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return ~crc;
}

void init_pdu_collection(PDU_COLLECTION *collection) {
    collection->count = 0;
    memset(collection->pdus, 0, sizeof(collection->pdus));
    pthread_mutex_init(&collection->mutex, NULL);
}

int add_pdu(PDU_COLLECTION *collection, uint32_t rx_tag, uint16_t rnti, const uint8_t crc_tag[4]) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Collection full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&collection->mutex);
        return -2; // Memory allocation failed
    }

    new_pdu->RX_UE_INFORMATION_TAG = rx_tag;
    new_pdu->RNTI = rnti;
    memcpy(new_pdu->CRC_INDICATION_REL8_TAG, crc_tag, sizeof(crc_tag));

    uint8_t *data_to_crc = (uint8_t *)new_pdu;
    size_t data_length = sizeof(NFAPI_CRC_INDICATION_PDU_T) - sizeof(uint32_t); // Exclude CRCFLAG
    new_pdu->CRCFLAG = compute_crc(data_to_crc, data_length);

    collection->pdus[collection->count++] = new_pdu;

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

int get_crc_flag(PDU_COLLECTION *collection, size_t index, uint32_t *crcflag) {
    if (index >= collection->count || crcflag == NULL) {
        return -1; // Invalid index or null pointer
    }

    pthread_mutex_lock(&collection->mutex);
    *crcflag = collection->pdus[index]->CRCFLAG;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

void free_pdu_collection(PDU_COLLECTION *collection) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->pdus[i]);
    }
    memset(collection->pdus, 0, sizeof(collection->pdus));
    collection->count = 0;
    pthread_mutex_unlock(&collection->mutex);

    pthread_mutex_destroy(&collection->mutex);
}
