// Function prototypes
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu);
void free_list(Node* head);
int validate_RNTI(int RNTI);
void serialize_to_file(Node* head, const char* filename);
int deserialize_from_file(const char* filename, Node** head);
unsigned long calculate_checksum(void* data, size_t length);

// Memory pool for efficient allocation
#define POOL_SIZE 10000
Node node_pool[POOL_SIZE];
size_t pool_index = 0;

Node* allocate_node() {
    if (pool_index < POOL_SIZE) {
        return &node_pool[pool_index++];
    }
    return NULL;
}

void deallocate_all_nodes() {
    pool_index = 0; // Reset the pool index for reuse
}

// Function to create and populate a linked list
Node* construct_list(size_t N, const int* known_RNTI) {
    Node* head = NULL;
    Node** tail = &head;
    int sum_of_RNTIs = 0;

    for (size_t i = 0; i < N; ++i) {
        int RNTI = rand() % 10000; // Simulating random RNTI generation

        if (!validate_RNTI(RNTI, known_RNTI)) {
            fprintf(stderr, "Invalid RNTI: %d\n", RNTI);
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = {i, RNTI, {.CRCFLAG = 0}};
        Node* new_node = create_node(pdu);

        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for node %zu\n", i);
            free_list(head); // Cleanup in case of failure
            deallocate_all_nodes();
            return NULL;
        }

        *tail = new_node;
        tail = &((*tail)->next);

        sum_of_RNTIs += RNTI;
        if (sum_of_RNTIs % 2 == 0) {
            (*tail - 1)->data.crc_tag.CRCFLAG = 1; // Set CRCFLAG based on parity
        }
    }

    *tail = NULL;
    return head;
}

// Helper functions
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = allocate_node();
    if (node) {
        node->data = pdu;
        node->next = NULL;
    }
    return node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        // Optional: Reset data for security
        memset(current, 0, sizeof(Node));
        current = next;
    }
    deallocate_all_nodes();
}

int validate_RNTI(int RNTI, const int* known_RNTI) {
    while (*known_RNTI != -1 && *known_RNTI != RNTI) {
        ++known_RNTI;
    }
    return *known_RNTI == RNTI;
}

void serialize_to_file(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Node* current = head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    unsigned long checksum = calculate_checksum(head, 0); // Calculate based on data size
    fwrite(&checksum, sizeof(unsigned long), 1, file);

    fclose(file);
}

int deserialize_from_file(const char* filename, Node** head) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t data_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    unsigned long checksum;
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    if (file_size < sizeof(unsigned long)) {
        fprintf(stderr, "Invalid file size\n");
        fclose(file);
        return -1;
    }

    Node* head_node = NULL;
    Node** tail = &head_node;

    while (ftell(file) + data_size <= file_size - sizeof(unsigned long)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, data_size, 1, file);
        Node* new_node = create_node(pdu);

        if (!new_node) {
            fprintf(stderr, "Memory allocation failed during deserialization\n");
            free_list(head_node);
            fclose(file);
            return -1;
        }

        *tail = new_node;
        tail = &((*tail)->next);
    }

    fread(&checksum, sizeof(unsigned long), 1, file);

    unsigned long calculated_checksum = calculate_checksum(head_node, data_size * (file_size / (data_size + sizeof(unsigned long))));
    if (checksum != calculated_checksum) {
        fprintf(stderr, "Checksum mismatch\n");
        free_list(head_node);
        fclose(file);
        return -1;
    }

    *head = head_node;
    fclose(file);
    return 0;
}

unsigned long calculate_checksum(void* data, size_t length) {
    unsigned char* bytes = (unsigned char*)data;
    unsigned long checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}
