#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONCURRENT_OPERATIONS 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int active_operations;
} ListManager;

ListManager* create_list_manager() {
    ListManager* lm = (ListManager*)malloc(sizeof(ListManager));
    lm->head = NULL;
    pthread_mutex_init(&lm->lock, NULL);
    pthread_cond_init(&lm->cond, NULL);
    lm->active_operations = 0;
    return lm;
}

void destroy_list_node(Node* node) {
    free(node);
}

void delete_list(ListManager* lm) {
    Node* current = lm->head;
    while (current != NULL) {
        Node* next = current->next;
        destroy_list_node(current);
        current = next;
    }
    pthread_mutex_destroy(&lm->lock);
    pthread_cond_destroy(&lm->cond);
    free(lm);
}

void acquire_lock(ListManager* lm) {
    pthread_mutex_lock(&lm->lock);
    while (lm->active_operations >= MAX_CONCURRENT_OPERATIONS) {
        pthread_cond_wait(&lm->cond, &lm->lock);
    }
    lm->active_operations++;
    pthread_mutex_unlock(&lm->lock);
}

void release_lock(ListManager* lm) {
    pthread_mutex_lock(&lm->lock);
    lm->active_operations--;
    pthread_cond_signal(&lm->cond);
    pthread_mutex_unlock(&lm->lock);
}

int add_pdu(ListManager* lm, NFAPI_CRC_INDICATION_PDU_T pdu) {
    acquire_lock(lm);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    new_node->next = NULL;

    if (lm->head == NULL) {
        lm->head = new_node;
    } else {
        Node* current = lm->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    release_lock(lm);
    return 0;
}

size_t serialize_list(ListManager* lm, unsigned char** buffer) {
    acquire_lock(lm);

    size_t list_size = 0;
    Node* current = lm->head;

    while (current != NULL) {
        list_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    *buffer = (unsigned char*)malloc(list_size);
    if (!(*buffer)) {
        release_lock(lm);
        return 0;
    }

    size_t offset = 0;
    current = lm->head;

    while (current != NULL) {
        memcpy((*buffer) + offset, &(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    release_lock(lm);
    return list_size;
}

int deserialize_list(ListManager* lm, unsigned char* buffer, size_t size) {
    acquire_lock(lm);

    if (size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        release_lock(lm);
        return -1;
    }

    delete_list(lm); // Clear existing list

    for (size_t i = 0; i < size; i += sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        memcpy(&pdu, buffer + i, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        add_pdu(lm, pdu);
    }

    release_lock(lm);
    return 0;
}

int validate_serialized_data(unsigned char* buffer, size_t size) {
    if (size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        return -1; // Invalid size
    }

    for (size_t i = 0; i < size; i += sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        memcpy(&pdu, buffer + i, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Example validation logic
        if (pdu.RX_UE_INFORMATION_TAG <= 0 || pdu.CRC_INDICATION_REL8_TAG.CRCFLAG < 0) {
            return -1; // Invalid data
        }
    }

    return 0;
}
