#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int Rx_UE_Information_Tag;
    unsigned int Rnti;
    unsigned int CrcIndicationTag;
} UeSessionState;

typedef struct {
    UeSessionState* sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

unsigned int calculate_checksum(UeSessionState session) {
    return session.Rx_UE_Information_Tag ^ session.Rnti ^ session.CrcIndicationTag;
}

void initialize_session_manager(SessionManager* manager, size_t initial_capacity) {
    manager->sessions = (UeSessionState*)malloc(initial_capacity * sizeof(UeSessionState));
    if (!manager->sessions) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void resize_session_array(SessionManager* manager, size_t new_capacity) {
    UeSessionState* new_sessions = (UeSessionState*)realloc(manager->sessions, new_capacity * sizeof(UeSessionState));
    if (!new_sessions) {
        perror("Failed to reallocate memory for sessions");
        exit(EXIT_FAILURE);
    }
    manager->sessions = new_sessions;
    manager->capacity = new_capacity;
}

void add_session(SessionManager* manager, UeSessionState session) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_session_array(manager, manager->capacity * 2);
    }

    unsigned int checksum = calculate_checksum(session);
    printf("Checksum for new session: %u\n", checksum); // Verification step

    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->lock);
}

void free_session_manager(SessionManager* manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    SessionManager manager;
    initialize_session_manager(&manager, 4);

    UeSessionState session1 = {1, 100, 200};
    add_session(&manager, session1);

    UeSessionState session2 = {2, 101, 201};
    add_session(&manager, session2);

    // Add more sessions as needed...

    free_session_manager(&manager);
    return 0;
}
