    uint16_t crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    double max_weighted_sum;
    uint32_t transaction_id_with_max_sum;
    int node_count;
} NFAPI_CRC_INDICATION_LIST_T;

// Function to create a new list
NFAPI_CRC_INDICATION_LIST_T* create_list() {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->max_weighted_sum = 0.0;
    list->transaction_id_with_max_sum = 0;
    list->node_count = 0;
    return list;
}

// Function to generate a random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2;
}

// Function to add a new structure to the list
void add_structure(NFAPI_CRC_INDICATION_LIST_T* list, uint32_t rnti, uint8_t rx_ue_information_tag, uint16_t crc_indication_rel8_tag) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data.rnti = rnti;
    new_node->data.rx_ue_information_tag = rx_ue_information_tag;
    new_node->data.crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_node->data.crcflag = generate_random_crcflag();
    new_node->timestamp = time(NULL);
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
}

// Function to filter the list
void filter_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    time_t now = time(NULL);
    int node_count_in_window = 0;

    while (current != NULL) {
        // Remove nodes older than WINDOW_SIZE
        if ((now - current->timestamp) > WINDOW_SIZE / 1000) {
            prev ? prev->next = current->next : list->head = current->next;
            free(current);
            list->node_count--;
            current = (prev ? prev->next : list->head);
            continue;
        }

        // Count similar structures in the sliding window
        Node *temp = current->next;
        node_count_in_window = 1; // Current node counts as one

        while (temp != NULL) {
            if ((now - temp->timestamp) <= WINDOW_SIZE / 1000 &&
                temp->data.rnti == current->data.rnti &&
                temp->data.rx_ue_information_tag == current->data.rx_ue_information_tag) {
                node_count_in_window++;
            }
            temp = temp->next;
        }

        // Calculate weighted sum
        double weighted_sum = (double)(current->data.crcflag * 1.5 + node_count_in_window);

        if (weighted_sum > list->max_weighted_sum) {
            list->max_weighted_sum = weighted_sum;
            list->transaction_id_with_max_sum = current->data.rnti;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to clean up the list
void destroy_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Example usage
int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_LIST_T* list = create_list();

    // Simulate adding structures
    for (int i = 0; i < 100; ++i) {
        add_structure(list, rand(), rand() % 256, rand());
    }

    // Filter the list
    filter_list(list);

    printf("Max Weighted Sum: %.2f\n", list->max_weighted_sum);
    printf("Transaction ID with Max Sum: %u\n", list->transaction_id_with_max_sum);

    destroy_list(list);
    return 0;
}
