// Function to generate a rolling hash for CRCFLAG
uint8_t calculate_crcflag(RX_UE_INFORMATION_TAG tag, uint16_t rnti) {
    unsigned int hash = 0;
    // Rolling hash calculation (simplified)
    hash = ((tag.tag << 16) ^ rnti) * 2654435761U;
    return (hash >> 24) & 0xFF;
}

// Thread-safe function to create and populate the list
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(size_t count, size_t threshold) {
    if (count > MAX_ELEMENTS) count = MAX_ELEMENTS;

    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Dynamic allocation
    list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    uint16_t used_rntis[MAX_ELEMENTS] = {0};
    int successful_crc_count = 0;

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        RX_UE_INFORMATION_TAG tag;
        uint16_t rnti;

        do {
            tag.tag = rand();
            rnti = rand() % MAX_ELEMENTS;
        } while (used_rntis[rnti]);

        pthread_mutex_lock(&lock);
        used_rntis[rnti] = 1;

        list[i].rx_ue_information_tag = tag;
        list[i].rnti = rnti;

        uint8_t crcflag = calculate_crcflag(tag, rnti);

        if ((tag.tag & 0xFFFF) >= threshold) { // Threshold condition
            list[i].crc_flag = crcflag;
            successful_crc_count++;
            log_message("CRC indication added");
        } else {
            list[i].crc_flag = 0; // Invalid CRCFLAG
            log_message("CRC indication not valid due to threshold failure");
        }

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    log_message("Total successful CRC indications: %d", successful_crc_count);

    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
        log_message("List memory freed");
    }
}
