        fprintf(stderr, "Error: Maximum packets per frame exceeded.\n");
        return;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < maxPacketsPerFrame; ++i) {
        int packetID;
        int retryCount = 0;

        do {
            packetID = generateUniquePacketID();
            if (packetID <= 0 && retryCount >= MAX_RETRIES) {
                fprintf(stderr, "Error: Failed to generate unique PacketID after %d retries.\n", MAX_RETRIES);
                return;
            }
            retryCount++;
        } while (packetID <= 0);

        frames[i].Timestamp = time(NULL); // Use current timestamp
        frames[i].PacketID = packetID;

        // Populate PacketData with random content
        for (int j = 0; j < sizeof(frames[i].PacketData) - 1; ++j) {
            frames[i].PacketData[j] = 'A' + rand() % 26;
        }
        frames[i].PacketData[sizeof(frames[i].PacketData) - 1] = '\0';
    }

    // Attempt to send the frame with retries
    int success = 0;
    for (int attempt = 0; attempt < MAX_RETRIES && !success; ++attempt) {
        if (sendFrame(frames, maxPacketsPerFrame)) {
            printf("Successfully sent frame with %zu packets.\n", maxPacketsPerFrame);
            success = 1;
        } else {
            fprintf(stderr, "Failed to send frame. Attempt %d/%d\n", attempt + 1, MAX_RETRIES);
        }
    }

    if (!success) {
        fprintf(stderr, "Error: Could not send the frame after %d attempts.\n", MAX_RETRIES);
    }
}

int main() {
