void add_bulk_elements(Node** head, NFAPI_CRC_INDICATION_PDU_T* elements, size_t count) {
    if (count > BULK_LIMIT || count + list_size(*head) > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Bulk operation exceeds limits.\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        add_single_element(head, elements[i]);
    }
}

void remove_faulty_elements() {
