    Node* prev = NULL;

    while (current != NULL) {
        if (!verify_crc(current->data)) {
            fprintf(stderr, "Error: CRC integrity check failed for element. Removing...\n");

            if (prev == NULL) { // Remove head
                head = current->next;
            } else {
                prev->next = current->next;
            }

            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

