```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

uint32_t rolling_hash(uint32_t ue_info, uint16_t rnti) {
    // Simple rolling hash function example
    return (ue_info ^ rnti * 2654435761U) & 0xFFFFFFFF;
}

int generate_crc_indication_list(int N, Node** head) {
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < N; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list_mutex);
            return -1;
        }

        // Generate valid values for demonstration purposes
        new_node->data.ue_information_tag = rand() % 0xFFFFFFFF; 
        new_node->data.rnti = rand() % 0xFFFF;
        new_node->data.crc_indication_rel8_tag = i % 256;

        // Calculate CRCFLAG using rolling hash
        new_node->data.crcflag = rolling_hash(new_node->data.ue_information_tag, new_node->data.rnti) & 1;

        new_node->next = *head;
        *head = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

void free_crc_indication_list(Node* head) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to update list periodically
void* periodic_update(void* args) {
    Node* list_head = *(Node**)args;

    while (1) {
        pthread_mutex_lock(&list_mutex);

        // Example: Update every 5 seconds with a fixed number of new elements
        int update_count = 10;
        if (generate_crc_indication_list(update_count, &list_head) != 0) {
            fprintf(stderr, "Failed to update list\n");
        }

        pthread_mutex_unlock(&list_mutex);

        // Simulate periodic delay
        sleep(5);
    }

    return NULL;
}

int main() {
    Node* head = NULL;

    if (generate_crc_indication_list(10, &head) != 0) {
        fprintf(stderr, "Failed to initialize list\n");
        return -1;
    }

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, periodic_update, &head) != 0) {
        fprintf(stderr, "Failed to create update thread\n");
        free_crc_indication_list(head);
        return -1;
    }

    // Main application logic here...

    // Cleanup
    pthread_join(update_thread, NULL);
    free_crc_indication_list(head);

    return 0;
}
```

