    pthread_mutex_t lock;
    int max_age_sec;
} DynamicList;

DynamicList* create_list(int max_age) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_age_sec = max_age;
    return list;
}

void free_node(Node *node) {
    free(node->data);
    free(node);
}

void clear_old_entries(DynamicList* list) {
    time_t now = time(NULL);
    Node **current = &list->head;

    while (*current != NULL) {
        if (now - (*current)->timestamp > list->max_age_sec) {
            Node *to_delete = *current;
            *current = to_delete->next;
            free_node(to_delete);
        } else {
            current = &(*current)->next;
        }
    }
}

void serialize_list(const char* filename, DynamicList* list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    Node *node = list->head;
    while (node) {
        fwrite(&node->data_size, sizeof(size_t), 1, file);
        fwrite(node->data, node->data_size, 1, file);
        node = node->next;
    }

    fclose(file);
}

void deserialize_list(const char* filename, DynamicList* list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t data_size;
    while (fread(&data_size, sizeof(size_t), 1, file)) {
        void *data = malloc(data_size);
        fread(data, data_size, 1, file);

        Node* node = malloc(sizeof(Node));
        if (!node || !data) continue;

        node->data = data;
        node->data_size = data_size;
        node->timestamp = time(NULL); // Set to current time for simplicity
        node->next = list->head;
        list->head = node;
    }

    fclose(file);
}

void add_entry(DynamicList* list, void *data, size_t data_size) {
    pthread_mutex_lock(&list->lock);

    Node* node = malloc(sizeof(Node));
    if (!node) return;

    node->data = malloc(data_size);
    memcpy(node->data, data, data_size);
    node->data_size = data_size;
    node->timestamp = time(NULL); // Set to current timestamp
    node->next = list->head;
    list->head = node;

    pthread_mutex_unlock(&list->lock);
}

void integrate_external_data(DynamicList* list, const char* external_source) {
    // Implementation for integrating data from an external source...
    // Consider using network APIs or other methods to fetch and update the list.
}

void periodic_clear(DynamicList* list) {
    while (1) {
        sleep(list->max_age_sec);
        clear_old_entries(list);
    }
}

int main() {
    DynamicList* crc_list = create_list(60);  // Example max age of 60 seconds

    // Simulate adding entries
    NFAPI_CRC_INDICATION_PDU_T pdu;
    memset(&pdu, 0, sizeof(pdu));
    add_entry(crc_list, &pdu, sizeof(pdu));

