        size_t newCapacity = list->capacity * 2;
        resizeDynamicList(list, newCapacity);
    }

    list->array[list->size++] = element;

    pthread_mutex_unlock(&list->mutex);
}

void freeDynamicList(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);

    free(list->array);
    list->array = NULL;
    list->size = 0;
    list->capacity = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void logDebugInfo(const char* message) {
    printf("[DEBUG] %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T createRandomElement() {
    NFAPI_CRC_INDICATION_PDU_T element;
    // Initialize rxUeInformationTag and rnti as needed
    srand(time(NULL));
    element.crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1

    return element;
}

int main() {
    DynamicList list;
    initializeDynamicList(&list, 10);

    for (size_t i = 0; i < 25; ++i) {
        NFAPI_CRC_INDICATION_PDU_T newElement = createRandomElement();
        addElement(&list, newElement);
        logDebugInfo("Added a new element.");
    }

    freeDynamicList(&list);
    return 0;
}
