    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
CRCList* create_list();
void destroy_list(CRCList* list);
bool add_crc_indication_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
size_t get_total_count(const CRCList* list);
Node* iterate_reverse(CRCList* list, size_t index);

// Utility function to log errors
void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

// Initialize the list
CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free memory
void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Validate CRC_INDICATION_REL8_TAG
bool validate_crc_tag(CRC_INDICATION_REL8_TAG tag) {
    // Implement validation logic here, e.g., check if fields are within expected ranges
    return true;  // Placeholder for actual validation logic
}

// Add a new NFAPI_CRC_INDICATION_PDU_T to the list
bool add_crc_indication_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!validate_crc_tag(pdu.crc_tag)) {
        log_error("CRC tag validation failed");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    new_node->data = pdu;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Get the total count of elements
size_t get_total_count(const CRCList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return count;
}

// Iterate over the list in reverse order
Node* iterate_reverse(CRCList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    Node* current = list->tail;
    for (size_t i = 0; i < index; ++i) {
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
    return current;
}

// Example usage
int main() {
    CRCList* list = create_list();
    if (!list) return EXIT_FAILURE;

    for (size_t i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .crc_tag = { .RX_UE_INFORMATION_TAG = i, .RNTI = i },
            .CRCFLAG = rand() % 2
        };
        add_crc_indication_pdu(list, pdu);
    }

    printf("Total count: %zu\n", get_total_count(list));

    for (size_t i = 0; i < get_total_count(list); ++i) {
        Node* node = iterate_reverse(list, i);
        if (node) {
            printf("Index %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
                   i, node->data.crc_tag.RX_UE_INFORMATION_TAG,
                   node->data.crc_tag.RNTI, node->data.CRCFLAG);
        }
    }

    destroy_list(list);
    return EXIT_SUCCESS;
}
