} NetworkEvent;

// Define the dynamic list node
typedef struct EventNode {
    NetworkEvent event;
    struct EventNode* next;
} EventNode;

// Define the dynamic list structure
typedef struct {
    EventNode* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicList;

// Function to initialize the dynamic list
void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

// Function to add an event to the dynamic list
void addEvent(DynamicList* list, NetworkEvent new_event) {
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return;
    }

    new_node->event = new_event;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    printf("Event added: PDU Session ID %d, QoS Class %d\n", new_event.pdu_session_id, new_event.qos_class_identifier);
}

// Function to purge stale events
void purgeStaleEvents(DynamicList* list, time_t max_age) {
    pthread_mutex_lock(&list->lock);

    EventNode *current = list->head;
    EventNode *prev = NULL;

    while (current != NULL) {
        if (time(NULL) - current->event.timestamp > max_age) {
            EventNode* to_delete = current;
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(to_delete);
            list->count--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    printf("Purge completed: %zu events remaining\n", list->count);
}

// Function to log operations
void logOperation(const char* message) {
    // Simple logging function, can be expanded with file writing or other mechanisms
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Example usage
int main() {
    DynamicList event_list;
    initDynamicList(&event_list);

    NetworkEvent new_event = { .pdu_session_id = 1, .qos_class_identifier = 10 };
    memcpy(new_event.mac_event_rx.data, "Example Data", 12);
    new_event.timestamp = time(NULL);

    addEvent(&event_list, new_event);

    // Simulate purge after some time
    sleep(2); // Wait for 2 seconds
    purgeStaleEvents(&event_list, 1); // Purge events older than 1 second

    return 0;
}
