#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t count;
    size_t updated_count;
    size_t retrieved_count;
    size_t errors;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
    array->count = 0;
    array->updated_count = 0;
    array->retrieved_count = 0;
    array->errors = 0;
    return array;
}

Node* find_node(DynamicArray* array, unsigned long rnti) {
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return current;
        current = current->next;
    }
    return NULL;
}

void add_structure(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);

    Node* existing_node = find_node(array, pdu.RNTI);
    if (existing_node != NULL) {
        // Handle duplicate RNTI by appending index
        while (find_node(array, pdu.RNTI + array->count) != NULL) {
            array->errors++;
        }
        pdu.RNTI += array->count;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    new_node->data = pdu;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;

    pthread_mutex_unlock(&array->mutex);
}

void update_structure(DynamicArray* array, unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T updated_pdu) {
    pthread_mutex_lock(&array->mutex);

    Node* node = find_node(array, rnti);
    if (node != NULL) {
        node->data = updated_pdu;
        array->updated_count++;
    } else {
        array->errors++;
    }

    pthread_mutex_unlock(&array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T retrieve_structure(DynamicArray* array, unsigned long rnti) {
    pthread_mutex_lock(&array->mutex);

    Node* node = find_node(array, rnti);
    NFAPI_CRC_INDICATION_PDU_T pdu = {0};
    if (node != NULL) {
        pdu = node->data;
        array->retrieved_count++;
    } else {
        array->errors++;
    }

    pthread_mutex_unlock(&array->mutex);
    return pdu;
}

void print_statistics(DynamicArray* array) {
    printf("Added: %zu, Updated: %zu, Retrieved: %zu, Errors: %zu\n",
           array->count, array->updated_count, array->retrieved_count, array->errors);
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);

    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int main() {
    DynamicArray* array = create_dynamic_array();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 2, rand() % 2};
    add_structure(array, pdu1);

    NFAPI_CRC_INDICATION_PDU_T updated_pdu = {1, 1001, 3, rand() % 2};
    update_structure(array, 1001, updated_pdu);

    NFAPI_CRC_INDICATION_PDU_T retrieved_pdu = retrieve_structure(array, 1001);
    printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%lu, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
           retrieved_pdu.RX_UE_INFORMATION_TAG, retrieved_pdu.RNTI,
           retrieved_pdu.CRC_INDICATION_REL8_TAG, retrieved_pdu.CRCFLAG);

    print_statistics(array);
    free_dynamic_array(array);

    return 0;
}
```

