        queue->head = new_node;
    } else {
        Node* temp = queue->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&queue->lock);
}

Packet dequeue_packet(PacketQueue* queue) {
    Packet empty_packet = {0};

    if (!queue || !queue->head) return empty_packet;

    pthread_mutex_lock(&queue->lock);

    Node* temp = queue->head;
    Packet packet = temp->data;

    queue->head = queue->head->next;
    free(temp);

    pthread_mutex_unlock(&queue->lock);

    return packet;
}

void destroy_packet_queue(PacketQueue* queue) {
    while (queue->head != NULL) {
        Node* temp = queue->head;
        queue->head = queue->head->next;
        free(temp);
    }

    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

// Thread function for handling client requests
void* handle_client(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;

    // Simulate packet processing
    for (int i = 0; i < 10; ++i) {
        Packet packet;
        packet.packet_id = rand();
        time(&packet.timestamp);
        snprintf(packet.payload, sizeof(packet.payload), "Payload %d", i);

        enqueue_packet(queue, packet);

        Packet processed_packet = dequeue_packet(queue);

        // Simulate processing
        printf("Processed Packet ID: %lu\n", processed_packet.packet_id);
    }

    return NULL;
}

int main() {
    PacketQueue* queue = create_packet_queue();

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, handle_client, (void*)queue);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_packet_queue(queue);

    return 0;
}
