#define MAX_RNTI_ENTRIES 1000
#define SUCCESS 0
#define MEMORY_ALLOCATION_ERROR -1

typedef struct {
    uint16_t rnti;
    int used;
} RNTIEntry;

int generate_unique_rnti(RNTIEntry *rnti_table, size_t table_size) {
    while (1) {
        uint16_t candidate = rand() % MAX_RNTI_ENTRIES;
        for (size_t i = 0; i < table_size; ++i) {
            if (rnti_table[i].rnti == candidate && rnti_table[i].used) {
                break;
            }
            if (i == table_size - 1) {
                return candidate; // Unique RNTI found
            }
        }
    }
}

int populate_nfa_pi_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **pdu_array, size_t array_size) {
    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_array == NULL) {
        return MEMORY_ALLOCATION_ERROR;
    }

    RNTIEntry rnti_table[MAX_RNTI_ENTRIES];
    memset(rnti_table, 0, sizeof(RNTIEntry) * MAX_RNTI_ENTRIES);

    for (size_t i = 0; i < array_size; ++i) {
        (*pdu_array)[i].RX_UE_INFORMATION_TAG = rand(); // Unique tag generation
        uint16_t rnti;
        int retry_count = 0;

        while (1) {
            if (retry_count > MAX_RNTI_ENTRIES / 2) { // Avoid infinite loop
                free(*pdu_array);
                return MEMORY_ALLOCATION_ERROR; // Unable to generate unique RNTI
            }

            rnti = generate_unique_rnti(rnti_table, MAX_RNTI_ENTRIES);

            if (rnti < MAX_RNTI_ENTRIES) {
                bool duplicate_found = false;
                for (size_t j = 0; j < MAX_RNTI_ENTRIES; ++j) {
                    if (rnti_table[j].rnti == rnti && rnti_table[j].used) {
                        duplicate_found = true;
                        break;
                    }
                }

                if (!duplicate_found) {
                    (*pdu_array)[i].RNTI = rnti;
                    for (size_t j = 0; j < MAX_RNTI_ENTRIES; ++j) {
                        if (rnti_table[j].rnti == rnti && !rnti_table[j].used) {
                            rnti_table[j].used = 1;
                            break;
                        }
                    }

                    (*pdu_array)[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF; // Unique tag generation
                    (*pdu_array)[i].CRCFLAG = rand() % 2;

                    break;
                } else {
                    retry_count++;
                }
            }
        }
    }

    return SUCCESS;
}

int main() {
    size_t array_size = 100;
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;

