#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* free_list;
    pthread_mutex_t lock;
    size_t pool_size;
} MemoryPool;

// Initialize the memory pool
void init_memory_pool(MemoryPool* pool, size_t pool_size) {
    pool->pool_size = pool_size;
    pool->free_list = NULL;

    for (size_t i = 0; i < pool_size; ++i) {
        MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        if (!node) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        node->next = pool->free_list;
        pool->free_list = node;
    }

    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate a new structure from the memory pool
MemoryPoolNode* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    MemoryPoolNode* node = pool->free_list;
    if (!node && pool->pool_size < MAX_POOL_SIZE) {
        node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        if (!node) {
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&pool->lock);
            exit(EXIT_FAILURE);
        }
    }
    if (node) {
        pool->free_list = node->next;
    }
    pthread_mutex_unlock(&pool->lock);
    return node;
}

// Return a structure to the memory pool
void deallocate_to_pool(MemoryPool* pool, MemoryPoolNode* node) {
    pthread_mutex_lock(&pool->lock);
    node->next = pool->free_list;
    pool->free_list = node;
    pthread_mutex_unlock(&pool->lock);
}

typedef struct List {
    MemoryPoolNode* head;
    pthread_rwlock_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
}

// Validate CRCFLAG randomly set
int validate_crcflag(int crcflag) {
    return (crcflag % 2 == 0); // Example validation logic
}

// Insert a new element into the list
void insert_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    MemoryPoolNode* node = allocate_from_pool(&pool);
    if (!node) {
        fprintf(stderr, "Failed to allocate memory from pool\n");
        return;
    }

    node->data = pdu;

    pthread_rwlock_wrlock(&list->lock);
    node->next = list->head;
    list->head = node;
    pthread_rwlock_unlock(&list->lock);
}

// Retrieve an element from the list
NFAPI_CRC_INDICATION_PDU_T* retrieve_list(List* list, int index) {
    MemoryPoolNode* current = list->head;
    int count = 0;

    pthread_rwlock_rdlock(&list->lock);
    while (current && count < index) {
        current = current->next;
        ++count;
    }
    pthread_rwlock_unlock(&list->lock);

    if (!current) return NULL;
    return &current->data;
}

void cleanup_list(List* list) {
    MemoryPoolNode* current = list->head;
    while (current) {
        MemoryPoolNode* next = current->next;
        deallocate_to_pool(&pool, current);
        current = next;
    }
    pthread_rwlock_destroy(&list->lock);
}

MemoryPool pool;
List nfa_list;

int main() {
    init_memory_pool(&pool, 1000); // Initialize with some initial size
    init_list(&nfa_list);

    srand(time(NULL));
    for (int i = 0; i < 10; ++i) { // Example insertion
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 100;

        int crcflag = rand();
        if (validate_crcflag(crcflag)) {
            pdu.CRCFLAG = crcflag;
            insert_list(&nfa_list, pdu);
        }
    }

    for (int i = 0; i < 10; ++i) { // Example retrieval
