            printf("Tag: %d, RNTI: %d, CRC_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        }
    }

    cleanup_list(&nfa_list);

    return 0;
}
