#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h> // for sleep()
#include <time.h>   // for time()

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
    int service_status;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->used = 0;
    list->size = 0;
    list->array = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->service_status = 0; // Service initially offline
}

void destroyDynamicList(DynamicList *list) {
    free(list->array);
    list->array = NULL;
    list->used = list->size = 0;
    pthread_mutex_destroy(&list->lock);
}

int resizeArray(DynamicList *list, size_t newSize) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return 0;

    list->array = new_array;
    list->size = newSize;
    return 1;
}

void addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->used == list->size) {
        size_t newSize = list->size ? list->size * 2 : 4;
        if (!resizeArray(list, newSize)) {
            fprintf(stderr, "Failed to resize array\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    list->array[list->used++] = element;

    pthread_mutex_unlock(&list->lock);
}

void *serviceMonitor(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    while (1) {
        sleep(5); // Monitor every 5 seconds

        pthread_mutex_lock(&list->lock);

        if (list->used > 0.8 * list->size && !resizeArray(list, list->size ? list->size * 2 : 4)) {
            fprintf(stderr, "Failed to resize array due to high load\n");
        }

        // Simulate resource monitoring and adaptive control
        int cpuUsage = rand() % 100;
        if (cpuUsage > 80) {
            printf("High CPU usage detected: %d%%\n", cpuUsage);
            // Adjust processing as needed, e.g., reduce task frequency
        }

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

void startService(DynamicList *list) {
    list->service_status = 1; // Service online

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, serviceMonitor, list)) {
        fprintf(stderr, "Failed to create monitoring thread\n");
        list->service_status = 0;
    } else {
        printf("Service started successfully.\n");
    }
}

void shutdownService(DynamicList *list) {
    list->service_status = 0; // Service offline
    pthread_cancel(monitor_thread); // Assumes monitor_thread is globally accessible or managed otherwise
    destroyDynamicList(list);
    printf("Service shut down gracefully.\n");
}

// Mock function to notify external services of status changes
void notifyStatusChange(int status) {
    const char *statusStr = (status == 1) ? "online" : "offline";
    printf("Notifying external service: Service is now %s\n", statusStr);

    // Implement retry and failure-handling logic here
}

int main() {
    DynamicList list;
    initDynamicList(&list);

    startService(&list);

    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() };
        element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        addElement(&list, element);
    }

    shutdownService(&list);

    return 0;
}
