        if (numConfigs <= 1) {
            fprintf(stderr, "Cannot allocate any configurations due to resource constraints.\n");
            *configs = NULL;
            return;
        }
        numConfigs--;
        totalSize = numConfigs * configSize;
    }

    // Allocate memory for the array of UdpSocketConfig
    *configs = (UdpSocketConfig *)malloc(totalSize);
    if (*configs == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

