['Below is a C function that meets your requirements for initializing and populating an array of `UeState` structures with thread-safe access:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_STATES 1000

typedef struct {
    int size;
    unsigned char *data;
} PDCP_PDU;

typedef struct {
    int ue_identifier;
    int rrc_connection_context;
    PDCP_PDU *pdcp_pdu_list;
    size_t pdcp_count;
} UeState;

typedef struct {
    UeState *ue_states;
    pthread_mutex_t lock;
    size_t count;
} UeStateManager;

UeStateManager *create_ue_state_manager() {
    UeStateManager *manager = (UeStateManager *)malloc(sizeof(UeStateManager));
    if (!manager) {
        perror("Failed to allocate memory for UE State Manager");
        return NULL;
    }

    manager->ue_states = (UeState *)calloc(MAX_UE_STATES, sizeof(UeState));
    if (!manager->ue_states) {
        free(manager);
        perror("Failed to allocate memory for UE States");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    return manager;
}

int add_ue_state(UeStateManager *manager, int ue_identifier, int rrc_connection_context) {
    if (pthread_mutex_lock(&manager->lock)) {
        perror("Failed to acquire lock");
        return -1;
    }

    if (manager->count >= MAX_UE_STATES) {
        fprintf(stderr, "Maximum UE States reached\n");
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }

    UeState *state = &manager->ue_states[manager->count];
    state->ue_identifier = ue_identifier;
    state->rrc_connection_context = rrc_connection_context;
    state->pdcp_pdu_list = NULL;
    state->pdcp_count = 0;

    manager->count++;

    if (pthread_mutex_unlock(&manager->lock)) {
        perror("Failed to release lock");
        return -1;
    }

    return 0;
}

int add_pdcp_pdu(UeStateManager *manager, int ue_identifier, PDCP_PDU pdu) {
    if (pthread_mutex_lock(&manager->lock)) {
        perror("Failed to acquire lock");
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->ue_states[i].ue_identifier == ue_identifier) {
            UeState *state = &manager->ue_states[i];

            state->pdcp_pdu_list = realloc(state->pdcp_pdu_list, (state->pdcp_count + 1) * sizeof(PDCP_PDU));
            if (!state->pdcp_pdu_list) {
                fprintf(stderr, "Failed to allocate memory for PDCP PDUs\n");
                pthread_mutex_unlock(&manager->lock);
                return -2;
            }

            state->pdcp_pdu_list[state->pdcp_count] = pdu;
            state->pdcp_count++;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    fprintf(stderr, "UE identifier not found\n");
    pthread_mutex_unlock(&manager->lock);
    return -3;
}

void free_ue_state_manager(UeStateManager *manager) {
    if (pthread_mutex_lock(&manager->lock)) {
        perror("Failed to acquire lock for cleanup");
        return;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        UeState *state = &manager->ue_states[i];
        free(state->pdcp_pdu_list);
    }

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager->ue_states);
    free(manager);
}

int main() {
    // Example usage
    UeStateManager *manager = create_ue_state_manager();
    if (!manager) return EXIT_FAILURE;

    if (add_ue_state(manager, 1, 100) == 0) {
        PDCP_PDU pdu = { .size = 128, .data = malloc(128) };
        add_pdcp_pdu(manager, 1, pdu);
        free(pdu.data); // Clean up after use
    }

    free_ue_state_manager(manager);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management**: Uses `calloc` and `realloc` to manage memory efficiently. Limits the maximum number of `UeState` entries.
- **Concurrency**: Utilizes a mutex (`pthread_mutex_t`) for thread-safe operations, ensuring no data races occur during concurrent access.
- **Scalability**: Designed with an array to hold `UeState` structures up to a predefined limit (`MAX_UE_STATES`). This provides constant-time complexity for direct indexing and is efficient under high concurrency.
- **Error Handling**: Provides error messages when memory allocation fails or when the maximum number of UE states is exceeded.']

