#define MIN_N 1
#define MAX_N 1000

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_array(size_t N, size_t *allocated_size) {
    if (N < MIN_N || N > MAX_N) {
        fprintf(stderr, "Invalid value for N: %zu. Must be between %d and %d.\n", N, MIN_N, MAX_N);
        return NULL;
    }

    pthread_mutex_lock(&allocation_mutex);

    *allocated_size = N;

    // Allocate memory
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for %zu elements.\n", N);
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Initialize the array
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 65536;  // Assuming a random valid tag
