    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NodeList {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct NodeList* next;
} NodeList;

// DOM Element Representation
typedef struct {
    char* class_name;
    char* id;
    // Additional attributes can be added as needed
} DOMElement;

// Asynchronous Data Fetch Simulation
typedef void (*DataFetchCallback)(DOMElement*, NFAPI_CRC_INDICATION_PDU_T*);

// Global Variables for Synchronization
NodeList* head = NULL;
int dataFetchedCount = 0;
int totalElementsToProcess = 0;
void (*domTraversalCallback)(DOMElement*) = NULL;

// Function Prototypes
void createNfadomList(DOMElement** domTree, int size, const char* selector, DataFetchCallback fetchData);
void processElement(DOMElement* element, NFAPI_CRC_INDICATION_PDU_T* pduData);
int matchesSelector(DOMElement* element, const char* selector);
void addNodeToList(NFAPI_CRC_INDICATION_PDU_T data);
void completeTraversal();
void simulateAsyncDataFetch(DOMElement* element, DataFetchCallback fetchData);

// Function Implementations
void createNfadomList(DOMElement** domTree, int size, const char* selector, DataFetchCallback fetchData) {
    totalElementsToProcess = size;
    for (int i = 0; i < size; ++i) {
        simulateAsyncDataFetch(domTree[i], fetchData);
    }
}

void processElement(DOMElement* element, NFAPI_CRC_INDICATION_PDU_T* pduData) {
    if (!matchesSelector(element, "your-selector")) return;

    pduData->RX_UE_INFORMATION_TAG = rand(); // Simulate data assignment
    pduData->RNTI = rand();
    pduData->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    addNodeToList(*pduData);
}

int matchesSelector(DOMElement* element, const char* selector) {
    if (strcmp(element->class_name, selector) == 0 || strcmp(element->id, selector) == 0) {
        return 1;
    }
    return 0;
}

void addNodeToList(NFAPI_CRC_INDICATION_PDU_T data) {
    NodeList* newNode = (NodeList*)malloc(sizeof(NodeList));
    if (!newNode) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    newNode->data = data;
    newNode->next = head;
    head = newNode;
}

void completeTraversal() {
    // Finalize any operations needed after traversal
    printf("DOM Traversal Complete. Processed %d elements.\n", dataFetchedCount);
}

void simulateAsyncDataFetch(DOMElement* element, DataFetchCallback fetchData) {
    NFAPI_CRC_INDICATION_PDU_T pduData;
    fetchData(element, &pduData);
    processElement(element, &pduData);

    // Simulate asynchronous completion
    dataFetchedCount++;
    if (dataFetchedCount == totalElementsToProcess) {
        completeTraversal();
    }
}

// Example Data Fetch Callback
void exampleFetchCallback(DOMElement* element, NFAPI_CRC_INDICATION_PDU_T* pduData) {
    // Simulate fetching data asynchronously
    // This is where you would integrate with your actual data source
    processElement(element, pduData);
}
```

