    Node* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPIList;

NFAPIList nfaList = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void initializeList(NFAPIList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    if (nfaList.count >= MAX_ELEMENTS) return -1;

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    newNode->data = element;
    pthread_mutex_lock(&nfaList.lock);
    newNode->next = nfaList.head;
    nfaList.head = newNode;
    nfaList.count++;
    pthread_mutex_unlock(&nfaList.lock);

    if (crcCheckFail(element)) {
        pthread_mutex_lock(&nfaList.lock);
        removeElement(nfaList.head, element);
        pthread_mutex_unlock(&nfaList.lock);
        free(newNode);
        return -3;
    }

    return 0;
}

void bulkAddElements(NFAPI_CRC_INDICATION_PDU_T elements[], int num) {
    if (num > BATCH_SIZE) num = BATCH_SIZE;

    for (int i = 0; i < num; ++i) {
