#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int CRCFLAG; // Assuming CRCFLAG is an integer for simplicity.
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
    int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_CAPACITY 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    int failed_crc_count;
} DynamicArray;

// Function prototypes
int compare_RNTI(const void *a, const void *b);
void initialize_dynamic_array(DynamicArray *da);
int add_or_update_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T new_pdu);
void free_dynamic_array(DynamicArray *da);

// Helper function to handle memory allocation with retry
void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed. Retrying...\n");
        ptr = malloc(size); // Retry once for simplicity.
        if (!ptr) {
            fprintf(stderr, "Memory allocation failed again. Exiting.\n");
            exit(EXIT_FAILURE);
        }
    }
    return ptr;
}

void initialize_dynamic_array(DynamicArray *da) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)allocate_memory(MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size = 0;
    da->capacity = MAX_CAPACITY;
    da->failed_crc_count = 0;
}

int compare_RNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return (pduA->RNTI > pduB->RNTI) - (pduA->RNTI < pduB->RNTI);
}

int add_or_update_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    if (new_pdu.RX_UE_INFORMATION_TAG <= 0 || !new_pdu.CRC_INDICATION_REL8_TAG.CRCFLAG) {
        da->failed_crc_count++;
        return -1;
    }

    for (size_t i = 0; i < da->size; i++) {
        if (da->array[i].RNTI == new_pdu.RNTI) {
            da->array[i] = new_pdu;
            qsort(da->array, da->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RNTI);
            return 0;
        }
    }

    if (da->size < MAX_CAPACITY) {
        da->array[da->size++] = new_pdu;
        qsort(da->array, da->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RNTI);
        return 1;
    }

    return -2; // Array is full.
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
}

// Unit tests
#include <assert.h>
#include <time.h>

void test_empty_input() {
    DynamicArray da;
    initialize_dynamic_array(&da);

    assert(add_or_update_element(&da, (NFAPI_CRC_INDICATION_PDU_T){.RNTI=1, .RX_UE_INFORMATION_TAG=10, .CRC_INDICATION_REL8_TAG={.CRCFLAG=0}}) == -1);
    assert(da.size == 0);
    assert(da.failed_crc_count == 1);

    free_dynamic_array(&da);
}

void test_add_and_update() {
    DynamicArray da;
    initialize_dynamic_array(&da);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {.RNTI=1, .RX_UE_INFORMATION_TAG=10, .CRC_INDICATION_REL8_TAG={.CRCFLAG=1}};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {.RNTI=2, .RX_UE_INFORMATION_TAG=20, .CRC_INDICATION_REL8_TAG={.CRCFLAG=1}};

    assert(add_or_update_element(&da, pdu1) == 1);
    assert(add_or_update_element(&da, pdu2) == 1);
    assert(da.size == 2);

    NFAPI_CRC_INDICATION_PDU_T pdu3 = {.RNTI=1, .RX_UE_INFORMATION_TAG=15, .CRC_INDICATION_REL8_TAG={.CRCFLAG=0}};
    assert(add_or_update_element(&da, pdu3) == -1);
    assert(da.failed_crc_count == 1);

    NFAPI_CRC_INDICATION_PDU_T pdu4 = {.RNTI=1, .RX_UE_INFORMATION_TAG=15, .CRC_INDICATION_REL8_TAG={.CRCFLAG=1}};
    assert(add_or_update_element(&da, pdu4) == 0);
    assert(da.size == 2);

    free_dynamic_array(&da);
}

void test_max_capacity() {
    DynamicArray da;
    initialize_dynamic_array(&da);

    for (int i = 0; i < MAX_CAPACITY; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {.RNTI=i, .RX_UE_INFORMATION_TAG=10 + i, .CRC_INDICATION_REL8_TAG={.CRCFLAG=1}};
        assert(add_or_update_element(&da, pdu) == 1);
    }

    assert(da.size == MAX_CAPACITY);

    NFAPI_CRC_INDICATION_PDU_T pdu_new = {.RNTI=1001, .RX_UE_INFORMATION_TAG=1010, .CRC_INDICATION_REL8_TAG={.CRCFLAG=1}};
    assert(add_or_update_element(&da, pdu_new) == -2);

    free_dynamic_array(&da);
}

void test_performance_under_load() {
    DynamicArray da;
    initialize_dynamic_array(&da);

    srand(time(NULL));
    for (int i = 0; i < MAX_CAPACITY * 10; ++i) { // Simulate high load
        NFAPI_CRC_INDICATION_PDU_T pdu = {.RNTI=rand(), .RX_UE_INFORMATION_TAG=i, .CRC_INDICATION_REL8_TAG={.CRCFLAG=(rand() % 2)}};
        add_or_update_element(&da, pdu);
    }

    assert(da.size <= MAX_CAPACITY);

    free_dynamic_array(&da);
}

int main() {
    test_empty_input();
    test_add_and_update();
    test_max_capacity();
    test_performance_under_load();

    printf("All tests passed.\n");
    return 0;
}
