#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MEMORY_LIMIT_BYTES (50 * 1024 * 1024) // 50 MB

typedef struct {
    unsigned int RNTI;
    unsigned int CRCFLAG;
    time_t timestamp; // Timestamp of insertion
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
    atomic_intptr_t head;  // Pointer to the head of the linked list
    atomic_intptr_t tail;  // Pointer to the tail of the linked list
} NFADynamicList;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* element;
    struct Node* next;
} Node;

NFADynamicList* create_list() {
    NFADynamicList* list = (NFADynamicList*)malloc(sizeof(NFADynamicList));
    if (!list) return NULL;

    for (int i = 0; i < MAX_ELEMENTS; ++i)
        list->data[i] = NULL;

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store_intptr_explicit(&list->head, NULL, memory_order_relaxed);
    atomic_store_intptr_explicit(&list->tail, NULL, memory_order_relaxed);

    return list;
}

void destroy_list(NFADynamicList* list) {
    if (!list) return;

    Node *current = (Node*)atomic_load_intptr_explicit(&list->head, memory_order_acquire);
    while (current != NULL) {
        Node *next = current->next;
        free(current->element);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_valid(unsigned int rnti) {
    return rnti >= 1 && rnti <= 65535;
}

void log_invalid_entry(unsigned int rnti) {
    printf("Invalid RNTI value: %u\n", rnti);
}

void* add_pdu(NFADynamicList* list, unsigned int rnti) {
    if (!is_rnti_valid(rnti)) {
        log_invalid_entry(rnti);
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node || list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        free(new_node);
        return NULL;
    }

    new_node->element = (NFAPI_CRC_INDICATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node->element) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    new_node->element->RNTI = rnti;
    new_node->element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    time(&(new_node->element->timestamp));

    Node *tail = (Node*)atomic_load_intptr_explicit(&list->tail, memory_order_acquire);
    if (!tail) {
        atomic_store_intptr_explicit(&list->head, new_node, memory_order_release);
        atomic_store_intptr_explicit(&list->tail, new_node, memory_order_release);
    } else {
        tail->next = new_node;
        atomic_store_intptr_explicit(&list->tail, new_node, memory_order_release);
    }

    // Check for RNTI constraint
    if (list->count > 0) {
        Node *prev = (Node*)atomic_load_intptr_explicit(&list->head, memory_order_acquire);
        while (prev && prev->next != NULL) {
            if (prev->element->RNTI == rnti) {
                free(new_node->element);
                free(new_node);
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            prev = prev->next;
        }
    }

    list->data[list->count++] = new_node->element;

    pthread_mutex_unlock(&list->lock);

    return new_node->element;
}

void* get_pdu(NFADynamicList* list, size_t index) {
    if (index >= list->count)
        return NULL;

    pthread_mutex_lock(&list->lock);
    Node *current = (Node*)atomic_load_intptr_explicit(&list->head, memory_order_acquire);

    for (size_t i = 0; current != NULL && i < index; ++i) {
        current = current->next;
    }

    void* pdu = current ? current->element : NULL;

    pthread_mutex_unlock(&list->lock);

    return pdu;
}

// Usage example
int main() {
    NFADynamicList *list = create_list();
    if (!list)
        return 1;

    for (unsigned int i = 0; i < 100; ++i) { // Add some PDU elements
        add_pdu(list, rand() % 65535 + 1);
    }

    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)get_pdu(list, i);
        if (pdu)
            printf("PDU[%zu]: RNTI=%u, CRCFLAG=%d, Timestamp=%ld\n", i, pdu->RNTI, pdu->CRCFLAG, pdu->timestamp);
    }

    destroy_list(list);

    return 0;
}
