// Define a structure for DataPacket
typedef struct {
    int packetID;
    char sourceAddress[16];
    char destinationAddress[16];
    unsigned int checksum;
} DataPacket;

// Function to calculate the checksum based on the given algorithm
unsigned int calculateChecksum(DataPacket *packet) {
    // Example checksum calculation (simple sum of characters)
    unsigned int sum = 0;
    for (int i = 0; i < strlen(packet->sourceAddress); ++i) {
        sum += packet->sourceAddress[i];
    }
    for (int i = 0; i < strlen(packet->destinationAddress); ++i) {
        sum += packet->destinationAddress[i];
    }
    return sum + packet->packetID;
}

// Function to initialize and populate an array of DataPackets
void initializeDataPackets(DataPacket *packets, size_t count) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Lock the function for thread safety
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < count; ++i) {
        packets[i].packetID = i + 1;
        snprintf(packets[i].sourceAddress, sizeof(packets[i].sourceAddress), "Source%d", i);
        snprintf(packets[i].destinationAddress, sizeof(packets[i].destinationAddress), "Dest%d", i);
        packets[i].checksum = calculateChecksum(&packets[i]);
    }

    // Unlock after processing
    pthread_mutex_unlock(&lock);
}

int main() {
    const size_t packetCount = 10;
    DataPacket *packetArray = (DataPacket *)malloc(packetCount * sizeof(DataPacket));

    if (!packetArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    initializeDataPackets(packetArray, packetCount);

    for (size_t i = 0; i < packetCount; ++i) {
        printf("PacketID: %d, Source: %s, Dest: %s, Checksum: %u\n",
               packetArray[i].packetID,
               packetArray[i].sourceAddress,
               packetArray[i].destinationAddress,
               packetArray[i].checksum);
    }

    free(packetArray);

    return EXIT_SUCCESS;
}
