    instance->RX_UE_INFORMATION_TAG = index + 1;
    instance->RNTI = index + 10000;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, generate_crc_flag, (void*)instance);
    pthread_detach(thread_id); // Detach the thread to handle CRC generation asynchronously
}

NFAPI_CRC_INDICATION_PDU_T** allocate_instances(int num_instances) {
    if (num_instances > MAX_INSTANCES) {
        fprintf(stderr, "Requested instances exceed maximum limit.\n");
        return NULL;
    }

    pthread_mutex_lock(&manager.mutex);
    for (int i = 0; i < manager.count; ++i) {
        free(manager.instances[i]);
    }
    manager.count = 0;

    NFAPI_CRC_INDICATION_PDU_T **allocated_instances = malloc(num_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!allocated_instances) {
        pthread_mutex_unlock(&manager.mutex);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_instances; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *instance = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!instance) {
            for (int j = 0; j < i; ++j) free(allocated_instances[j]);
            free(allocated_instances);
            pthread_mutex_unlock(&manager.mutex);
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }
        initialize_instance(instance, i);
        allocated_instances[i] = instance;
    }

    manager.instances[0] = allocated_instances;
    manager.count = num_instances;

    pthread_mutex_unlock(&manager.mutex);

    return allocated_instances;
}

void free_instances(NFAPI_CRC_INDICATION_PDU_T** instances, int num_instances) {
    if (!instances) return;

    for (int i = 0; i < num_instances; ++i) {
        free(instances[i]);
    }
    free(instances);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T **instances = allocate_instances(5000); // Example allocation
    if (instances == NULL) return EXIT_FAILURE;

    // Simulate some processing time
    sleep(2);

    free_instances(instances, 5000);
    return EXIT_SUCCESS;
}
