#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define ERROR_MEMORY_ALLOCATION_FAILED -1
#define SUCCESS 0

typedef enum {
    PDU_TYPE_A,
    PDU_TYPE_B,
    // Add new types as needed
} pdu_type_t;

typedef struct MAC_Control_PDU {
    pdu_type_t type;
    int sequence_number;
    size_t payload_size;
    time_t timestamp; // Optional timestamp
    struct MAC_Control_PDU *next;
} MAC_Control_PDU;

typedef struct MAC_Entity_PDU {
    int mac_entity_id;
    unsigned int frame_number;
    MAC_Control_PDU *control_pdus;
    struct MAC_Entity_PDU *next;
} MAC_Entity_PDU;

typedef struct PDU_Collection {
    MAC_Entity_PDU *head;
    pthread_mutex_t lock;
    size_t total_payload_size;
    int max_sequence_number;
    size_t pdu_count;
} PDU_Collection;

PDU_Collection* initialize_pdu_collection() {
    PDU_Collection *collection = malloc(sizeof(PDU_Collection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_payload_size = 0;
    collection->max_sequence_number = -1;
    collection->pdu_count = 0;

    return collection;
}

int add_mac_control_pdu(PDU_Collection *collection, int mac_entity_id, unsigned int frame_number,
                        pdu_type_t type, int sequence_number, size_t payload_size) {
    if (!collection) return ERROR_MEMORY_ALLOCATION_FAILED;

    pthread_mutex_lock(&collection->lock);

    MAC_Entity_PDU *entity = collection->head;
    while (entity && (entity->mac_entity_id != mac_entity_id || entity->frame_number != frame_number)) {
        entity = entity->next;
    }

    if (!entity) {
        entity = malloc(sizeof(MAC_Entity_PDU));
        if (!entity) {
            pthread_mutex_unlock(&collection->lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }

        entity->mac_entity_id = mac_entity_id;
        entity->frame_number = frame_number;
        entity->control_pdus = NULL;
        entity->next = collection->head;
        collection->head = entity;
    }

    MAC_Control_PDU *new_pdu = malloc(sizeof(MAC_Control_PDU));
    if (!new_pdu) {
        pthread_mutex_unlock(&collection->lock);
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    new_pdu->type = type;
    new_pdu->sequence_number = sequence_number;
    new_pdu->payload_size = payload_size;
    time(&(new_pdu->timestamp)); // Optional timestamp
    new_pdu->next = entity->control_pdus;
    entity->control_pdus = new_pdu;

    collection->total_payload_size += payload_size;
    if (sequence_number > collection->max_sequence_number) {
        collection->max_sequence_number = sequence_number;
    }
    collection->pdu_count++;

    pthread_mutex_unlock(&collection->lock);

    return SUCCESS;
}

int remove_mac_control_pdu(PDU_Collection *collection, int mac_entity_id, unsigned int frame_number,
                           int sequence_number) {
    if (!collection) return ERROR_MEMORY_ALLOCATION_FAILED;

    pthread_mutex_lock(&collection->lock);

    MAC_Entity_PDU *entity = collection->head;
    MAC_Entity_PDU **prev_entity_ptr = &collection->head;

    while (entity && !(entity->mac_entity_id == mac_entity_id && entity->frame_number == frame_number)) {
        prev_entity_ptr = &(entity->next);
        entity = entity->next;
    }

    if (!entity) {
        pthread_mutex_unlock(&collection->lock);
        return ERROR_MEMORY_ALLOCATION_FAILED; // Not found
    }

    MAC_Control_PDU **prev_pdu_ptr = &(entity->control_pdus);
    while (*prev_pdu_ptr && (*prev_pdu_ptr)->sequence_number != sequence_number) {
        prev_pdu_ptr = &((*prev_pdu_ptr)->next);
    }

    if (!(*prev_pdu_ptr)) {
        pthread_mutex_unlock(&collection->lock);
        return ERROR_MEMORY_ALLOCATION_FAILED; // Not found
    }

    MAC_Control_PDU *to_remove = *prev_pdu_ptr;
    *prev_pdu_ptr = to_remove->next;

    collection->total_payload_size -= to_remove->payload_size;
    free(to_remove);

    if (entity->control_pdus == NULL) {
        *prev_entity_ptr = entity->next;
        free(entity);
    }

    pthread_mutex_unlock(&collection->lock);

    return SUCCESS;
}

void get_statistics(PDU_Collection *collection, size_t *total_payload_size, float *average_payload_size,
                    int *max_sequence_number) {
    if (!collection || !total_payload_size || !average_payload_size || !max_sequence_number)
        return;

    pthread_mutex_lock(&collection->lock);

    *total_payload_size = collection->total_payload_size;
    *average_payload_size = (float)collection->pdu_count ? (float)collection->total_payload_size / collection->pdu_count : 0.0f;
    *max_sequence_number = collection->max_sequence_number;

    pthread_mutex_unlock(&collection->lock);
}

void free_pdu_collection(PDU_Collection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    MAC_Entity_PDU *entity = collection->head;
    while (entity) {
        MAC_Control_PDU *pdu = entity->control_pdus;
        while (pdu) {
            MAC_Control_PDU *temp_pdu = pdu;
            pdu = pdu->next;
            free(temp_pdu);
        }
        MAC_Entity_PDU *temp_entity = entity;
        entity = entity->next;
        free(temp_entity);
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

