typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_at_position(List* list, size_t position, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (position > list->count) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;

    if (position == 0) {
        new_node->next = list->head;
        new_node->prev = NULL;
        if (list->head != NULL) {
            list->head->prev = new_node;
        }
        list->head = new_node;
        if (list->tail == NULL) {
            list->tail = new_node;
        }
    } else {
        Node* current = list->head;
        for (size_t i = 0; i < position - 1 && current != NULL; i++) {
            current = current->next;
        }

        if (current == NULL) {
            free(new_node);
        } else {
            new_node->next = current->next;
            new_node->prev = current;

            if (current->next != NULL) {
                current->next->prev = new_node;
            }
            current->next = new_node;

            if (new_node->next == NULL) {
                list->tail = new_node;
            }
        }
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void remove_at_position(List* list, size_t position) {
    pthread_mutex_lock(&list->lock);

    if (position >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;

    if (position == 0) {
        list->head = current->next;
        if (list->head != NULL) {
            list->head->prev = NULL;
        } else {
            list->tail = NULL;
        }
    } else {
        for (size_t i = 0; i < position && current != NULL; i++) {
            current = current->next;
        }

        if (current == NULL || current->prev == NULL) {
            return;
        }

        current->prev->next = current->next;

        if (current->next != NULL) {
            current->next->prev = current->prev;
        } else {
            list->tail = current->prev;
        }
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

typedef struct {
    Node* current;
} ListIterator;

ListIterator* create_iterator(List* list, int reverse) {
    ListIterator* iterator = (ListIterator*)malloc(sizeof(ListIterator));
    pthread_mutex_lock(&list->lock);

    if (reverse) {
        iterator->current = list->tail;
    } else {
        iterator->current = list->head;
    }

    pthread_mutex_unlock(&list->lock);
    return iterator;
}

int has_next(ListIterator* iterator, int reverse) {
    return (iterator->current != NULL);
}

NFAPI_CRC_INDICATION_PDU_T next(ListIterator* iterator, int reverse) {
    if (!has_next(iterator, reverse)) {
        exit(EXIT_FAILURE); // Handle error as needed
    }

    NFAPI_CRC_INDICATION_PDU_T data = iterator->current->data;
    pthread_mutex_lock(&iterator->current->prev ? &iterator->current->prev->lock : &iterator->current->next->lock);

    if (reverse) {
        iterator->current = iterator->current->prev;
    } else {
        iterator->current = iterator->current->next;
    }

    pthread_mutex_unlock(iterator->current ? &iterator->current->prev ? &iterator->current->prev->lock : &iterator->current->next->lock : 0);
    return data;
}

void destroy_iterator(ListIterator* iterator) {
    free(iterator);
}
