    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].rnti == rnti) {
            for (size_t j = i; j < array->size - 1; ++j) {
                array->data[j] = array->data[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Not found
}

void traverse_array(const DynamicArray* array, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->data[i]);
    }
    pthread_mutex_unlock(&array->lock);
}

void print_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %d, CRC Indication: %u\n", pdu->rnti, pdu->crc_indication);
}
