#define MAX_RNTI 65535

typedef struct {
    int rnti;
    int dl_bandwidth_part;
    int ul_bandwidth_part;
    int **pusch_grants; // List of active PUSCH Grant Indications
} LTE_UE_Context;

typedef struct {
    unsigned short rx_ue_information_tag;
    unsigned short rnti;
    char crc_indication_rel8_tag[64];
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UE_Node {
    LTE_UE_Context context;
    struct UE_Node* next;
} UE_Node;

typedef struct {
    UE_Node* head;
    size_t count;
} UE_List;

int initialize_ue_context(LTE_UE_Context* context) {
    if (!context) return -1;
    context->rnti = rand() % MAX_RNTI + 1;
    context->dl_bandwidth_part = rand() % 10; // Example value
    context->ul_bandwidth_part = rand() % 10; // Example value
    context->pusch_grants = NULL;
    return 0;
}

int add_ue_context(UE_List* ue_list, LTE_UE_Context new_context) {
    if (!ue_list || !new_context.pusch_grants) return -1;

    UE_Node** curr = &ue_list->head;
    while (*curr) {
        if ((*curr)->context.rnti == new_context.rnti)
            return -2; // RNTI collision
        curr = &(*curr)->next;
    }

    UE_Node* node = (UE_Node*)malloc(sizeof(UE_Node));
    if (!node) return -1;

    node->context = new_context;
    node->next = NULL;
    *curr = node;
    ue_list->count++;
    return 0;
}

LTE_UE_Context* find_ue_by_rnti(UE_List* ue_list, int rnti) {
    UE_Node* curr = ue_list->head;
    while (curr) {
        if (curr->context.rnti == rnti)
            return &curr->context;
        curr = curr->next;
    }
    return NULL;
}

int remove_ue_context(UE_List* ue_list, int rnti) {
    UE_Node **curr = &ue_list->head;
    while (*curr) {
        if ((*curr)->context.rnti == rnti) {
            UE_Node *to_free = *curr;
            *curr = (*curr)->next;
            free(to_free);
            ue_list->count--;
            return 0;
        }
        curr = &(*curr)->next;
    }
    return -1; // Not found
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(size_t N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) return NULL;

    for (size_t i = 0; i < N; ++i) {
        indications[i].rx_ue_information_tag = rand() % 65535;
        indications[i].rnti = rand() % MAX_RNTI + 1;
        strcpy(indications[i].crc_indication_rel8_tag, "REL8TAG");
        indications[i].crcflag = rand() % 2; // Random CRCFLAG
    }

    return indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* indications) {
    if (indications) free(indications);
}

int main() {
    srand((unsigned int)time(NULL));

    UE_List ue_list = {NULL, 0};
    LTE_UE_Context context;

    initialize_ue_context(&context);

    if (add_ue_context(&ue_list, context) != 0)
        printf("Error adding context\n");

    NFAPI_CRC_INDICATION_PDU_T* indications = create_crc_indications(10);
    if (!indications) {
        printf("Failed to allocate CRC indications\n");
    }

    // Example usage
    LTE_UE_Context *found_context = find_ue_by_rnti(&ue_list, context.rnti);
    if (found_context)
        printf("Found UE Context with RNTI: %d\n", found_context->rnti);

    remove_ue_context(&ue_list, context.rnti);

    free_crc_indications(indications);

    // Free UE List
    while (ue_list.head) {
        remove_ue_context(&ue_list, ue_list.head->context.rnti);
    }

    return 0;
}
