NFAPI_CRC_INDICATION_PDU_T* initialize_and_filter_crc_indications(
    size_t count, 
    uint8_t threshold, 
    size_t *filtered_count) {

    // Seed the random number generator
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);

    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
