        array[i].RX_UE_INFORMATION_TAG = rand() % 256;  // Example random initialization
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand();  // Random CRCFLAG value

        // Filtering logic: keep elements with CRCFLAG greater than threshold
    }

    size_t filter_idx = 0;
    for (size_t i = 0; i < count; ++i) {
        if (array[i].CRCFLAG > threshold) {
            if (filter_idx != i) {
                array[filter_idx] = array[i];
            }
            filter_idx++;
        }
