```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <sys/mman.h>
#include <fcntl.h>

#define LOG_LEVEL_INFO 1

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(int level, const char *message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

int initialize_crc_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t n, uint8_t crc_threshold, const char *file_path) {
    pthread_mutex_lock(&mutex);

    // Memory allocation
    *array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(16, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        log_message(LOG_LEVEL_INFO, "Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Seed random number generator
    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        (*array)[i].RNTI = rand() % 65536;
        uint8_t crcflag = rand() & 1; // Randomly set CRCFLAG
        if (crcflag < crc_threshold) {
            continue;
        }
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
    }

    log_message(LOG_LEVEL_INFO, "Array initialized");

    int fd = open(file_path, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        log_message(LOG_LEVEL_INFO, "Failed to open file for persistence");
        free(*array);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Persist the array
    if (ftruncate(fd, n * sizeof(NFAPI_CRC_INDICATION_PDU_T)) == -1) {
        log_message(LOG_LEVEL_INFO, "Failed to truncate file for persistence");
        close(fd);
        free(*array);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (write(fd, *array, n * sizeof(NFAPI_CRC_INDICATION_PDU_T)) == -1) {
        log_message(LOG_LEVEL_INFO, "Failed to write array to file");
        close(fd);
        free(*array);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    close(fd);

    pthread_mutex_unlock(&mutex);
    return 0;
}

void load_crc_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t n, const char *file_path) {
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        log_message(LOG_LEVEL_INFO, "Failed to open file for loading");
        return;
    }

    *array = mmap(NULL, n * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ, MAP_PRIVATE, fd, 0);
    if (*array == MAP_FAILED) {
        log_message(LOG_LEVEL_INFO, "Memory mapping failed");
    } else {
        log_message(LOG_LEVEL_INFO, "Array loaded from file");
    }

    close(fd);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("Usage: %s <size> <crc_threshold> <file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t n = strtoul(argv[1], NULL, 10);
    uint8_t crc_threshold = atoi(argv[2]);

    if (n == 0 || crc_threshold > 1) {
        printf("Invalid parameters\n");
        return EXIT_FAILURE;
    }

    const char *file_path = argv[3];
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    int result = initialize_crc_array(&array, n, crc_threshold, file_path);
    if (result == 0) {
        log_message(LOG_LEVEL_INFO, "Initialization successful");
    } else {
        log_message(LOG_LEVEL_INFO, "Initialization failed");
    }

    load_crc_array(&array, n, file_path);

    free(array);
    return EXIT_SUCCESS;
}
```

