#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_RETRIES 10

typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T ue_info_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t min_rnti;
    uint16_t max_rnti;
} RNTI_RANGE_CONFIG;

pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
uint16_t current_max_rntis_generated = 0; // For dynamic retry logic

bool load_config(RNTI_RANGE_CONFIG *config) {
    FILE *file = fopen("rnti_range.conf", "r");
    if (!file) return false;

    fscanf(file, "%hu %hu", &config->min_rnti, &config->max_rnti);
    fclose(file);
    return true;
}

uint16_t generate_unique_rnti(RNTI_RANGE_CONFIG *config, uint16_t *used_rntis, size_t ue_count) {
    static bool init_rand = false;
    if (!init_rand) {
        srand(time(NULL));
        init_rand = true;
    }

    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        pthread_mutex_lock(&rnti_mutex);
        uint16_t rnti = config->min_rnti + rand() % (config->max_rnti - config->min_rnti + 1);

        if (used_rntis[rnti] == 0) { // RNTI is unique
            used_rntis[rnti] = 1;
            pthread_mutex_unlock(&rnti_mutex);
            return rnti;
        }
        pthread_mutex_unlock(&rnti_mutex);

        // Adjust retry logic based on system load (simplified)
        if (++current_max_rntis_generated % 1000 == 0) {
            usleep(10); // Simulate dynamic adjustment
        }
    }

    fprintf(stderr, "Failed to generate unique RNTI after %d retries\n", MAX_RETRIES);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu_list(size_t ue_count, size_t *actual_ue_count) {
    RNTI_RANGE_CONFIG config;
    if (!load_config(&config)) {
        fprintf(stderr, "Failed to load configuration\n");
        return NULL;
    }

    uint16_t *used_rntis = calloc((config.max_rnti - config.min_rnti + 1), sizeof(uint16_t));
    if (!used_rntis) {
        perror("Memory allocation failed for RNTI tracking");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pu_list = malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pu_list) {
        free(used_rntis);
        perror("Memory allocation failed for PDU list");
        return NULL;
    }

    size_t count = 0;
    while (count < ue_count) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pu_list[count];
        pdu->ue_info_tag.RNTI = generate_unique_rnti(&config, used_rntis, ue_count);

        if (pdu->ue_info_tag.RNTI == 0) continue; // Failed to get a unique RNTI

        pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2;
        count++;
    }

    *actual_ue_count = count;
    free(used_rntis);
    return pu_list;
}

void report_performance(size_t ue_count, double time_taken) {
    printf("Generated %zu UEs in %.4f seconds. Average time per UE: %.4f microseconds\n",
           ue_count, time_taken, (time_taken / ue_count * 1e6));
}
