['Below is an example implementation in C for the described task. It includes thread-safe access using a mutex lock, dynamic memory management with custom allocation, duplicate checking, and configurable logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFACustomList;

static void log_message(int level, const char* message) {
    // Simple logging function; could be expanded for more levels and details
    if (level <= 1) {  // Assuming 0 = ERROR, 1 = INFO
        printf("%s\n", message);
    }
}

void init_list(NFACustomList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_rnti_unique(NFACustomList* list, unsigned long rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 0; // RNTI not unique
        current = current->next;
    }
    return 1; // Unique RNTI
}

void add_pdu(NFACustomList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, pdu.RNTI)) {
        log_message(0, "Duplicate RNTI detected, ignoring entry.");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_message(0, "Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void generateNFCAPIListWithCRC(NFACustomList* list, int num_entries) {
    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.RNTI = rand() % 1000000;

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag

        add_pdu(list, pdu);
    }
}

void free_list(NFACustomList* list) {
    Node* current;
    while (list->head != NULL) {
        current = list->head;
        list->head = list->head->next;
        free(current);
    }

    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    NFACustomList list;
    init_list(&list);

    generateNFCAPIListWithCRC(&list, 10); // Generate 10 entries for example

    // Free resources before exiting
    free_list(&list);

    return 0;
}
