    RX_UE_INFORMATION_TAG ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Callback function type definition
typedef void (*callback_t)(NFAPI_CRC_INDICATION_PDU_T *);

void allocate_and_validate(NAPI_CRC_INDICATION_PDU_T **array, size_t N, callback_t process_pdu) {
    if (N == 0 || array == NULL || process_pdu == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; ++i) {
        (*array)[i].ue_information_tag.RNTI = rand() % UINT32_MAX;
        (*array)[i].rnti = rand() % UINT16_MAX;
        (*array)[i].crc_indication_rel8_tag.CRCFLAG = generate_random_crcflag();
    }

    // Validate uniqueness of RNTI
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = i + 1; j < N; ++j) {
            if ((*array)[i].ue_information_tag.RNTI == (*array)[j].ue_information_tag.RNTI) {
                fprintf(stderr, "RNTI collision detected.\n");
                free(*array);
                *array = NULL;
                exit(EXIT_FAILURE);
            }
        }
    }

    // Process each structure using the callback
    for (size_t i = 0; i < N; ++i) {
        process_pdu(&((*array)[i]));
    }
}

void deallocate_array(NAPI_CRC_INDICATION_PDU_T **array) {
    if (*array != NULL) {
        free(*array);
        *array = NULL;
    }
}
```

