    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG *crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} PduList;

PduList pdu_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void add_pdu(RX_UE_INFORMATION_TAG ue_info_tag, CRC_INDICATION_REL8_TAG *crc_indication) {
    pthread_mutex_lock(&pdu_list.lock);

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        logMessage(ERROR, "Memory allocation failed for new PDU");
        pthread_mutex_unlock(&pdu_list.lock);
        return;
    }

    new_pdu->ue_info_tag = ue_info_tag;
    new_pdu->crc_indication_rel8_tag = crc_indication;
    new_pdu->next = pdu_list.head;
    pdu_list.head = new_pdu;

    logMessage(INFO, "PDU added successfully");
    pthread_mutex_unlock(&pdu_list.lock);
}

void remove_pdu(int rnti) {
    pthread_mutex_lock(&pdu_list.lock);

    NFAPI_CRC_INDICATION_PDU_T *current = pdu_list.head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL && current->ue_info_tag.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        logMessage(ERROR, "PDU with specified RNTI not found");
        pthread_mutex_unlock(&pdu_list.lock);
        return;
    }

    if (prev == NULL) {
        pdu_list.head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->crc_indication_rel8_tag);
    free(current);

    logMessage(INFO, "PDU removed successfully");
    pthread_mutex_unlock(&pdu_list.lock);
}

void update_pdu(int rnti, CRC_INDICATION_REL8_TAG *new_crc_indication) {
    pthread_mutex_lock(&pdu_list.lock);

    NFAPI_CRC_INDICATION_PDU_T *current = pdu_list.head;

    while (current != NULL && current->ue_info_tag.rnti != rnti) {
        current = current->next;
    }

    if (current == NULL) {
        logMessage(ERROR, "PDU with specified RNTI not found for update");
        pthread_mutex_unlock(&pdu_list.lock);
        return;
    }

    free(current->crc_indication_rel8_tag);
    current->crc_indication_rel8_tag = new_crc_indication;

    logMessage(INFO, "PDU updated successfully");
    pthread_mutex_unlock(&pdu_list.lock);
}

void cleanup_pdus() {
    pthread_mutex_lock(&pdu_list.lock);

    NFAPI_CRC_INDICATION_PDU_T *current = pdu_list.head;
    NFAPI_CRC_INDICATION_PDU_T *next;

    while (current != NULL) {
        next = current->next;

        // Assume some condition to decide if a PDU should be cleaned
        // For example, based on age or other criteria
        free(current->crc_indication_rel8_tag);
        free(current);

        current = next;
    }

    pdu_list.head = NULL;

    logMessage(INFO, "PDUs cleanup completed");
    pthread_mutex_unlock(&pdu_list.lock);
}

