#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

typedef struct RadioBearer {
    int rbId;
    struct RadioBearer* next;
} RadioBearer;

typedef enum { ONLINE, OFFLINE } NetworkStatus;

typedef struct UserSession {
    unsigned long ueId;
    RadioBearer* radioBearers;
    NetworkStatus status;
    pthread_mutex_t mutex;  // Mutex for thread-safe access
} UserSession;

// Global variables to manage sessions
pthread_mutex_t globalSessionsMutex = PTHREAD_MUTEX_INITIALIZER;
UserSession** userSessions = NULL;
size_t sessionCount = 0;

void initializeSessionManager() {
    pthread_mutex_init(&globalSessionsMutex, NULL);
}

int addUserSession(unsigned long ueId) {
    pthread_mutex_lock(&globalSessionsMutex);

    // Find if the session already exists
    for (size_t i = 0; i < sessionCount; ++i) {
        if (userSessions[i]->ueId == ueId) {
            pthread_mutex_unlock(&globalSessionsMutex);
            return -1; // UserSession already exists
        }
    }

    // Allocate and initialize new session
    UserSession* newUserSession = (UserSession*)malloc(sizeof(UserSession));
    if (!newUserSession) {
        pthread_mutex_unlock(&globalSessionsMutex);
        return -2; // Memory allocation failed
    }

    newUserSession->ueId = ueId;
    newUserSession->radioBearers = NULL;
    newUserSession->status = OFFLINE;
    pthread_mutex_init(&newUserSession->mutex, NULL);

    // Resize the global sessions array and add new session
    UserSession** tempArray = realloc(userSessions, (sessionCount + 1) * sizeof(UserSession*));
    if (!tempArray) {
        free(newUserSession);
        pthread_mutex_unlock(&globalSessionsMutex);
        return -3; // Memory allocation failed during resize
    }
    userSessions = tempArray;
    userSessions[sessionCount++] = newUserSession;

    pthread_mutex_unlock(&globalSessionsMutex);
    return 0; // Success
}

int removeUserSession(unsigned long ueId) {
    pthread_mutex_lock(&globalSessionsMutex);

    for (size_t i = 0; i < sessionCount; ++i) {
        if (userSessions[i]->ueId == ueId) {
            UserSession* toDelete = userSessions[i];

            // Destroy the mutex
            pthread_mutex_destroy(&toDelete->mutex);

            // Free radio bearers list
            RadioBearer* rb = toDelete->radioBearers;
            while (rb) {
                RadioBearer* temp = rb;
                rb = rb->next;
                free(temp);
            }

            // Remove from the array and shift others down
            for (size_t j = i; j < sessionCount - 1; ++j) {
                userSessions[j] = userSessions[j + 1];
            }
            --sessionCount;

            // Reallocate memory to shrink array
            if (sessionCount > 0) {
                UserSession** tempArray = realloc(userSessions, sessionCount * sizeof(UserSession*));
                if (tempArray) {
                    userSessions = tempArray;
                }
            } else {
                free(userSessions);
                userSessions = NULL;
            }

            pthread_mutex_unlock(&globalSessionsMutex);
            free(toDelete);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&globalSessionsMutex);
    return -1; // UserSession not found
}

void addRadioBearer(unsigned long ueId, int rbId) {
    pthread_mutex_lock(&globalSessionsMutex);

    for (size_t i = 0; i < sessionCount; ++i) {
        if (userSessions[i]->ueId == ueId) {
            pthread_mutex_lock(&userSessions[i]->mutex);

            RadioBearer* newRB = (RadioBearer*)malloc(sizeof(RadioBearer));
            if (!newRB) {
                pthread_mutex_unlock(&userSessions[i]->mutex);
                pthread_mutex_unlock(&globalSessionsMutex);
                return;
            }

            newRB->rbId = rbId;
            newRB->next = userSessions[i]->radioBearers;
            userSessions[i]->radioBearers = newRB;

            pthread_mutex_unlock(&userSessions[i]->mutex);
            break;  // RadioBearer added
        }
    }

    pthread_mutex_unlock(&globalSessionsMutex);
}

void logSessionOperations(const char* operation) {
    printf("Operation: %s\n", operation);  // Basic logging to console
}

int main() {
    initializeSessionManager();

    addUserSession(1);
    addRadioBearer(1, 101);

    removeUserSession(1);

    return 0;
}
```

### Explanation
- **Global Mutex**: `globalSessionsMutex` ensures that access to the global list of sessions is thread-safe.
- **Session Management**: Functions for adding and removing sessions include memory management practices to minimize fragmentation and handle errors gracefully.
- **Thread-Safe Session Access**: Each session has its own mutex (`userSession->mutex`) to allow concurrent modification of radio bearers within a single session, reducing contention on the global lock.
- **Logging**: Simple logging is provided using `printf` for monitoring operations.']

