#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Global structure to manage the list and statistics.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t lock;
} CRCList;

CRCList crc_list = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

// Utility function for random CRCFLAG generation
unsigned char generate_random_crcflag() {
    return rand() % 2; // Simple binary flag for demonstration.
}

// Add an element to the list
int add_element(unsigned int rx_ue_tag, unsigned int rnti) {
    pthread_mutex_lock(&crc_list.lock);
    if (crc_list.count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // List full
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {rx_ue_tag, rnti, rand() % 256, generate_random_crcflag()};
    crc_list.elements[crc_list.count++] = new_element;
    pthread_mutex_unlock(&crc_list.lock);
    return 0; // Success
}

// Update an element in the list based on RNTI
int update_element(unsigned int rnti, unsigned char new_rel8_tag) {
    pthread_mutex_lock(&crc_list.lock);
    for (int i = 0; i < crc_list.count; ++i) {
        if (crc_list.elements[i].RNTI == rnti) {
            crc_list.elements[i].CRC_INDICATION_REL8_TAG = new_rel8_tag;
            pthread_mutex_unlock(&crc_list.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&crc_list.lock);
    return -1; // Element not found
}

// Retrieve an element from the list based on RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieve_element(unsigned int rnti) {
    pthread_mutex_lock(&crc_list.lock);
    for (int i = 0; i < crc_list.count; ++i) {
        if (crc_list.elements[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *element = &crc_list.elements[i];
            pthread_mutex_unlock(&crc_list.lock);
            return element;
        }
    }
    pthread_mutex_unlock(&crc_list.lock);
    return NULL; // Element not found
}

// Statistics function: count elements with CRCFLAG set to 1
int get_crcflag_statistics() {
    int crcflag_count = 0;
    pthread_mutex_lock(&crc_list.lock);
    for (int i = 0; i < crc_list.count; ++i) {
        if (crc_list.elements[i].CRCFLAG == 1) {
            crcflag_count++;
        }
    }
    pthread_mutex_unlock(&crc_list.lock);
    return crcflag_count;
}

// SQLite database initialization
int init_database(sqlite3 **db) {
    int rc = sqlite3_open("nfa_crc_indication.db", db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(*db));
        return -1;
    }

    const char *sql_create_table =
        "CREATE TABLE IF NOT EXISTS crc_indications("
        "RX_UE_INFORMATION_TAG INTEGER,"
        "RNTI INTEGER PRIMARY KEY,"
        "CRC_INDICATION_REL8_TAG INTEGER,"
        "CRCFLAG INTEGER);";

    char *err_msg = 0;
    rc = sqlite3_exec(*db, sql_create_table, 0, 0, &err_msg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", err_msg);
        sqlite3_free(err_msg);
        return -1;
    }

    return 0; // Success
}

// Save elements to the database
int save_to_database(sqlite3 *db) {
    pthread_mutex_lock(&crc_list.lock);
    char sql_insert[512];
    int rc = SQLITE_OK;

    sqlite3_stmt *stmt;
    const char *sql_prepare = "INSERT OR REPLACE INTO crc_indications VALUES(?, ?, ?, ?);";

    rc = sqlite3_prepare_v2(db, sql_prepare, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        pthread_mutex_unlock(&crc_list.lock);
        return -1;
    }

    for (int i = 0; i < crc_list.count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = &crc_list.elements[i];

        sqlite3_bind_int(stmt, 1, element->RX_UE_INFORMATION_TAG);
        sqlite3_bind_int(stmt, 2, element->RNTI);
        sqlite3_bind_int(stmt, 3, element->CRC_INDICATION_REL8_TAG);
        sqlite3_bind_int(stmt, 4, element->CRCFLAG);

        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            fprintf(stderr, "Failed to insert data: %s\n", sqlite3_errmsg(db));
            break;
        }

        sqlite3_reset(stmt);
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&crc_list.lock);

    return (rc == SQLITE_OK) ? 0 : -1; // Success or failure
}

// Load elements from the database
int load_from_database(sqlite3 *db) {
    char sql_query[] = "SELECT RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG FROM crc_indications;";
    sqlite3_stmt *stmt;

    int rc = sqlite3_prepare_v2(db, sql_query, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare query: %s\n", sqlite3_errmsg(db));
        return -1; // Failure
    }

    pthread_mutex_lock(&crc_list.lock);

    crc_list.count = 0;

    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        if (crc_list.count >= MAX_ELEMENTS) break;

        NFAPI_CRC_INDICATION_PDU_T element = {
            .RX_UE_INFORMATION_TAG = sqlite3_column_int(stmt, 0),
            .RNTI = sqlite3_column_int(stmt, 1),
            .CRC_INDICATION_REL8_TAG = (unsigned char)sqlite3_column_int(stmt, 2),
            .CRCFLAG = (unsigned char)sqlite3_column_int(stmt, 3)
        };

        crc_list.elements[crc_list.count++] = element;
    }

    pthread_mutex_unlock(&crc_list.lock);

    sqlite3_finalize(stmt);
    return (rc == SQLITE_DONE) ? 0 : -1; // Success or failure
}

// Example main function demonstrating usage
int main() {
    srand(time(NULL)); // Seed random number generator

    sqlite3 *db;
    if (init_database(&db)) {
        fprintf(stderr, "Failed to initialize database.\n");
        return EXIT_FAILURE;
    }

    add_element(12345, 67890);
    save_to_database(db);

    load_from_database(db);

    NFAPI_CRC_INDICATION_PDU_T *retrieved = retrieve_element(67890);
    if (retrieved) {
        printf("Retrieved RNTI: %u, CRCFLAG: %d\n", retrieved->RNTI, retrieved->CRCFLAG);
    }

    sqlite3_close(db);

    return EXIT_SUCCESS;
}
