}

void serializeUEContexts(const UEContext *contexts, size_t numUEs, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    // Write number of UE contexts
    fwrite(&numUEs, sizeof(size_t), 1, file);

    for (size_t i = 0; i < numUEs; ++i) {
        // Write UEID and RRC_STATE
        fwrite(&contexts[i].UEID, sizeof(int), 1, file);
        size_t stateLen = strlen(contexts[i].RRC_STATE) + 1;
        fwrite(&stateLen, sizeof(size_t), 1, file);
        fwrite(contexts[i].RRC_STATE, sizeof(char), stateLen, file);

        // Write number of measurements
        fwrite(&contexts[i].numMeasurements, sizeof(size_t), 1, file);

        for (size_t j = 0; j < contexts[i].numMeasurements; ++j) {
            // Write MeasurementReport
            fwrite(&contexts[i].Measurements[j], sizeof(struct UEContext::MeasurementReport), 1, file);
        }
    }

    fclose(file);
}

void deserializeUEContexts(UEContext **contexts, size_t *numUEs, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return;
    }

    // Read number of UE contexts
    fread(numUEs, sizeof(size_t), 1, file);

    *contexts = (UEContext *)malloc(*numUEs * sizeof(UEContext));
    for (size_t i = 0; i < *numUEs; ++i) {
        // Read UEID and RRC_STATE
        fread(&((*contexts)[i].UEID), sizeof(int), 1, file);
        size_t stateLen;
        fread(&stateLen, sizeof(size_t), 1, file);
        (*contexts)[i].RRC_STATE = (char *)malloc(stateLen * sizeof(char));
        fread((*contexts)[i].RRC_STATE, sizeof(char), stateLen, file);

        // Read number of measurements
        fread(&((*contexts)[i].numMeasurements), sizeof(size_t), 1, file);
        (*contexts)[i].Measurements = (struct UEContext::MeasurementReport *)malloc(
            (*contexts)[i].numMeasurements * sizeof(struct UEContext::MeasurementReport));

        for (size_t j = 0; j < (*contexts)[i].numMeasurements; ++j) {
            // Read MeasurementReport
            fread(&((*contexts)[i].Measurements[j]), sizeof(struct UEContext::MeasurementReport), 1, file);
        }
    }

    fclose(file);
}

void freeUEContexts(UEContext *contexts, size_t numUEs) {
    for (size_t i = 0; i < numUEs; ++i) {
        free(contexts[i].RRC_STATE);
        free(contexts[i].Measurements);
    }
    free(contexts);
}

int main() {
    const size_t numPDUs = 5;
    NFAPI_CRC_INDICATION_PDU_T pdus[numPDUs];
    initializeNFAPICRCIndicationPDU(pdus, numPDUs);

    const size_t numUEs = 10;
    UEContext *contexts = NULL;
    initializeUEContexts(&contexts, numUEs);

    serializeUEContexts(contexts, numUEs, "ue_contexts.bin");

    size_t loadedNumUEs;
    UEContext *loadedContexts = NULL;
    deserializeUEContexts(&loadedContexts, &loadedNumUEs, "ue_contexts.bin");

    freeUEContexts(contexts, numUEs);
    freeUEContexts(loadedContexts, loadedNumUEs);

    return 0;
}
