['Below is a C implementation that manages a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures with thread safety using mutexes for synchronization. This code includes functions to add, remove, and retrieve elements by index.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    // Add relevant fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_MANAGER_T;

// Initialize the manager
void init_crc_manager(NFAPI_CRC_MANAGER_T *manager) {
    manager->size = 0;
    manager->capacity = 10; // Initial capacity
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the internal array
void resize_array(NFAPI_CRC_MANAGER_T *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->array = new_array;
    manager->capacity = new_capacity;
}

// Add a new element
void add_element(NFAPI_CRC_MANAGER_T *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        resize_array(manager);
    }

    manager->array[manager->size++] = element;

    pthread_mutex_unlock(&manager->lock);
}

// Remove an element by index
void remove_element(NFAPI_CRC_MANAGER_T *manager, size_t index) {
    if (index >= manager->size) return;

    pthread_mutex_lock(&manager->lock);

    memmove(&manager->array[index], &manager->array[index + 1], 
            (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T get_element(const NFAPI_CRC_MANAGER_T *manager, size_t index) {
    if (index >= manager->size) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T element = manager->array[index];

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);

    return element;
}

// Free the allocated resources
void free_crc_manager(NFAPI_CRC_MANAGER_T *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    NFAPI_CRC_MANAGER_T manager;
    init_crc_manager(&manager);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, 'A'};
    add_element(&manager, pdu);

    NFAPI_CRC_INDICATION_PDU_T retrieved = get_element(&manager, 0);
    printf("Retrieved: RX=%d, RNTI=%d, CRC_TAG=%d, CRCFLAG=%c\n",
           retrieved.RX_UE_INFORMATION_TAG, retrieved.RNTI,
           retrieved.CRC_INDICATION_REL8_TAG, retrieved.CRCFLAG);

    remove_element(&manager, 0);
    free_crc_manager(&manager);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe access to the array.
- **Dynamic Resizing**: The array is resized when it reaches capacity, doubling its size each time.
- **Memory Management**: Properly allocates and deallocates memory to prevent leaks.
- **Error Handling**: Includes basic error handling for memory allocation failures.']

