#define MAX_NR_UL_UE_INFO_TAGS 1000

typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
