    uint16_t rnti;
    CRC_INDICATION_REL8_TAG_T crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Simulated function to get UE information
int getInitialUEInfo(RX_UE_INFORMATION_TAG_T *info, uint16_t *rnti) {
    static int count = 0;
    if (count < MAX_NR_UL_UE_INFO_TAGS) {
        info->RNTI = rand() % MAX_NR_UL_UE_INFO_TAGS + 1; // Simulated RNTI
        *rnti = info->RNTI;
        count++;
        return 1;
    }
    return 0;
}

// Function to check uniqueness of RNTI and RX_UE_INFORMATION_TAG pair in the array
int isUnique(NFAPI_CRC_INDICATION_PDU_T *array, int size, uint16_t rnti, RX_UE_INFORMATION_TAG_T rxUeInfo) {
    for (int i = 0; i < size; ++i) {
        if ((array[i].rxUeInformationTag.RNTI == rxUeInfo.RNTI &&
             array[i].rnti == rnti)) {
            return 0;
        }
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* initializeAndPopulateArray(int *numElements) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int capacity = 10; // Initial capacity
    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int count = 0;
    while (count < MAX_NR_UL_UE_INFO_TAGS && capacity > count) {
        RX_UE_INFORMATION_TAG_T rxUeInfo;
        uint16_t rnti;

        if (!getInitialUEInfo(&rxUeInfo, &rnti)) {
            break; // No more UE information available
        }

        if (isUnique(array, count, rnti, rxUeInfo)) {
            array[count].rxUeInformationTag = rxUeInfo;
            array[count].rnti = rnti;
            array[count].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            count++;
        }
    }

    if (count == capacity && capacity < MAX_NR_UL_UE_INFO_TAGS) {
        int newCapacity = capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            free(array);
            fprintf(stderr, "Memory reallocation failed\n");
            return NULL;
        }
        array = newArray;
    }

    *numElements = count;

    // Verify integrity
    for (int i = 0; i < count; ++i) {
        for (int j = 0; j < count; ++j) {
            if (i != j && 
                (array[i].rxUeInformationTag.RNTI == array[j].rxUeInformationTag.RNTI &&
                 array[i].rnti == array[j].rnti)) {
                fprintf(stderr, "Integrity check failed: duplicate RX_UE_INFORMATION_TAG and RNTI\n");
                free(array);
                return NULL;
            }
        }
    }

    return array;
}

int main() {
    int numElements = 0;
    NFAPI_CRC_INDICATION_PDU_T *array = initializeAndPopulateArray(&numElements);

    if (array) {
        printf("Successfully initialized %d elements\n", numElements);
        free(array);
    } else {
        fprintf(stderr, "Failed to initialize array\n");
    }

    return 0;
}
