int addEntry(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!isValidCRC(pdu)) {
        logError("Invalid CRC detected");
        return -1;
    }

    pthread_mutex_lock(&listMutex);

    // Adjust max list size dynamically
    adjustMaxListSizeBasedOnSystemResources();

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        logError("Memory allocation failed for new node");
        pthread_mutex_unlock(&listMutex);
        return -1;
    }

    memcpy(&newNode->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Append to the list
    newNode->next = head;
    head = newNode;

    logDebug("Entry added successfully");

    pthread_mutex_unlock(&listMutex);

    return 0;
}

void freeList() {
    pthread_mutex_lock(&listMutex);
    struct Node* current = head;
    while (current) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&listMutex);
}

