#define MAX_NODE_COUNT 100

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    int node_count;
} CRCIndicationList;

void initialize_list(CRCIndicationList *list, unsigned long seed) {
    list->head = NULL;
    list->node_count = 0;
    srand(seed);
}

bool add_node(CRCIndicationList *list, unsigned long RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    if (list->node_count >= MAX_NODE_COUNT) return false;

    int crcflag, attempts = 0;
    while (attempts < MAX_NODE_COUNT) { // Retry logic
        crcflag = rand() % 1024; // Example range for CRCFLAG

        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        bool isUnique = true;

        // Check uniqueness of CRCFLAG
        while (current != NULL) {
            if (current->crc_indication_rel8_tag.CRCFLAG == crcflag) {
                isUnique = false;
                break;
            }
            current = current->next;
        }

        if (isUnique) break; // Found unique CRCFLAG

        attempts++;
    }

    if (!isUnique || attempts >= MAX_NODE_COUNT) return false;

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return false;

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->crc_indication_rel8_tag.CRCFLAG = crcflag;
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    return true;
}

void free_list(CRCIndicationList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->node_count = 0;
}

void print_list(const CRCIndicationList *list) {
