    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %lu, RNTI: %hu, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG,
               current->RNTI,
               current->crc_indication_rel8_tag.CRCFLAG);
        current = current->next;
    }
}

int main() {
