static pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_random_crcflag() {
    static unsigned int seed = 0;
    pthread_mutex_lock(&rand_mutex);
    if (seed == 0) {
        seed = time(NULL); // Initialize with current time as seed
    }
    int crcflag = rand_r(&seed) % 2; // Generate random 0 or 1
