#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    FILE* log_file;
} DynamicArray;

void init_dynamic_array(DynamicArray* da, size_t initial_capacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->mutex, NULL);
    da->log_file = fopen("crc_log.txt", "a");
    if (!da->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_array(DynamicArray* da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    fclose(da->log_file);
}

int add_element(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    // Set CRCFLAG randomly
    element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    memcpy(&da->array[da->count], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->count++;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int remove_element(DynamicArray* da, size_t index) {
    if (index >= da->count) {
        fprintf(da->log_file, "Error: Index out of bounds\n");
        return -1;
    }

    pthread_mutex_lock(&da->mutex);

    memmove(&da->array[index], &da->array[index + 1], (da->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->count--;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray* da, size_t index) {
    if (index >= da->count) {
        fprintf(da->log_file, "Error: Index out of bounds\n");
        return NULL;
    }

    pthread_mutex_lock(&da->mutex);
    NFAPI_CRC_INDICATION_PDU_T* element = &da->array[index];
    pthread_mutex_unlock(&da->mutex);

    return element;
}

void log_crc_consistency(DynamicArray* da) {
    uint8_t crcflag_set = -1;

    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        if (crcflag_set == -1) {
            crcflag_set = da->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG;
        } else if (crcflag_set != da->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG) {
            fprintf(da->log_file, "Error: CRC flag inconsistency detected\n");
            pthread_mutex_unlock(&da->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&da->mutex);

    fprintf(da->log_file, "CRC flags are consistent across all elements.\n");
}

int main() {
    srand(time(NULL));
    DynamicArray da;
    init_dynamic_array(&da, 10);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234};
    add_element(&da, pdu);
    log_crc_consistency(&da);

    free_dynamic_array(&da);
    return 0;
}
