} LTE_PHY_MEASUREMENTS;

// Function prototypes
void add_measurement(LTE_PHY_MEASUREMENTS **measurements, size_t *size, LTE_PHY_MEASUREMENTS new_measurement);
void discard_invalid_measurements(LTE_PHY_MEASUREMENTS *measurements, size_t *size, int rx_power_threshold);
void sort_by_cell_id(LTE_PHY_MEASUREMENTS *measurements, size_t size);
bool is_valid_measurement(const LTE_PHY_MEASUREMENTS *measurement, int rx_power_threshold);

// Function to add a new measurement
void add_measurement(LTE_PHY_MEASUREMENTS **measurements, size_t *size, LTE_PHY_MEASUREMENTS new_measurement) {
    if (!is_valid_measurement(&new_measurement, -120)) return;

    // Reallocate memory for the new measurement
    *measurements = realloc(*measurements, (*size + 1) * sizeof(LTE_PHY_MEASUREMENTS));
    if (*measurements == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Add the new measurement and increment size
    (*measurements)[*size] = new_measurement;
    (*size)++;
}

// Function to discard invalid measurements based on RX_POWER threshold
void discard_invalid_measurements(LTE_PHY_MEASUREMENTS *measurements, size_t *size, int rx_power_threshold) {
    size_t valid_count = 0;

    // Filter out invalid measurements
    for (size_t i = 0; i < *size; ++i) {
        if (is_valid_measurement(&measurements[i], rx_power_threshold)) {
            measurements[valid_count++] = measurements[i];
        }
    }

    // Resize the array to fit only valid measurements
    *size = valid_count;
}

// Function to sort measurements by CELL_ID in ascending order
void sort_by_cell_id(LTE_PHY_MEASUREMENTS *measurements, size_t size) {
    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = 0; j < size - i - 1; ++j) {
            if (measurements[j].CELL_ID > measurements[j + 1].CELL_ID) {
                LTE_PHY_MEASUREMENTS temp = measurements[j];
                measurements[j] = measurements[j + 1];
                measurements[j + 1] = temp;
            }
        }
    }
}

// Function to check if a measurement is valid
bool is_valid_measurement(const LTE_PHY_MEASUREMENTS *measurement, int rx_power_threshold) {
    return measurement->RX_POWER >= rx_power_threshold && measurement->RX_POWER <= 0 &&
           measurement->CELL_ID > 0; // Assuming CELL_ID > 0 is valid
}

// Example usage
int main() {
    LTE_PHY_MEASUREMENTS *measurements = NULL;
    size_t size = 0;

    // Simulate adding measurements
    add_measurement(&measurements, &size, (LTE_PHY_MEASUREMENTS){1, 100, -50});
    add_measurement(&measurements, &size, (LTE_PHY_MEASUREMENTS){2, 200, -130}); // Invalid RX_POWER
    add_measurement(&measurements, &size, (LTE_PHY_MEASUREMENTS){3, 150, -70});

    // Discard invalid measurements with threshold -100 dBm
    discard_invalid_measurements(measurements, &size, -100);

    // Sort by CELL_ID
    sort_by_cell_id(measurements, size);

    // Print sorted and filtered measurements
    for (size_t i = 0; i < size; ++i) {
        printf("Tag: %d, Cell ID: %d, RX Power: %d\n", measurements[i].PHY_MEASUREMENT_TAG, measurements[i].CELL_ID, measurements[i].RX_POWER);
    }

    // Free allocated memory
    free(measurements);

    return 0;
}
