#define MAX_CAPACITY 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock; // Using a mutex for simplicity; consider lock-free techniques if needed.
