// Initialize the list
int init_crc_list(CRCList *list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) return -1;

    list->data = data;
    pthread_mutex_init(&list->lock, NULL);

    return 0;
}

// Resize the list
static int resize_crc_list(CRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    list->capacity = new_capacity;
    list->data = new_data;
    return 0;
}

// Add an element to the list
int add_crc_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity < MAX_CAPACITY ? list->capacity * 2 : MAX_CAPACITY;
        int ret = resize_crc_list(list, new_capacity);
        if (ret == -1) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *item = &list->data[list->size];
    *item = pdu;

    log_message("Added CRC PDU at index %zu", list->size);
    atomic_fetch_add(&list->size, 1);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Free the list resources
void free_crc_list(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

// Example function to populate the list with random data
void populate_crc_list(CRCList *list, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
