               i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);

        pthread_mutex_unlock(&poolMutex);
    }
}

int main() {
    int numThreads = 10;
    int numPDU_perThread = MAX_POOL_SIZE / numThreads;

    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; ++i) {
