    unsigned char crc_indication_rel8_tag;
    unsigned char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UnionFindNode {
    int parent;
    int rank;
} UnionFindNode;

UnionFindNode* makeSet(int n) {
    UnionFindNode *nodes = malloc(n * sizeof(UnionFindNode));
    for (int i = 0; i < n; ++i) {
        nodes[i].parent = i;
        nodes[i].rank = 0;
    }
    return nodes;
}

int find(UnionFindNode *nodes, int i) {
    if (nodes[i].parent != i) {
        nodes[i].parent = find(nodes, nodes[i].parent);
    }
    return nodes[i].parent;
}

void unionSets(UnionFindNode *nodes, int x, int y) {
    int rootX = find(nodes, x);
    int rootY = find(nodes, y);

    if (rootX != rootY) {
        if (nodes[rootX].rank < nodes[rootY].rank) {
            nodes[rootX].parent = rootY;
        } else if (nodes[rootX].rank > nodes[rootY].rank) {
            nodes[rootY].parent = rootX;
        } else {
            nodes[rootY].parent = rootX;
            nodes[rootX].rank++;
        }
    }
}

int validateRNTIs(const char *filename, int **rnti_array, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    int rnti;
    int seen[65536] = {0};
    int index = 0;

    while (fscanf(file, "%d", &rnti) == 1) {
        if (rnti < 0 || rnti >= 65536 || seen[rnti]) continue;

        seen[rnti] = 1;
        rnti_array[index++] = malloc(sizeof(int));
        *rnti_array[index - 1] = rnti;
    }

    fclose(file);
    *count = index;
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* createPDUs(const int *rntis, int count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < count; ++i) {
        pdus[i].rnti = rntis[i];
        pdus[i].rx_ue_info_tag = rand() % 256;
        pdus[i].crc_indication_rel8_tag = rand() % 256;
        pdus[i].crc_flag = rand() & 1; // Randomly set CRCFLAG
    }

    return pdus;
}

void executeCommand(const char *cmd) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    }

    if (pid > 0) {
        int status;
        wait(&status);
        if (WIFEXITED(status)) {
            printf("Child exited with status %d\n", WEXITSTATUS(status));
        } else {
            fprintf(stderr, "Child did not exit successfully.\n");
        }
    } else {
        execlp(cmd, cmd, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    }
}

int processPDUs(const char *logFile) {
    int *rnti_array[65536];
    int rnti_count = 0;

    if (!validateRNTIs(logFile, (int**)rnti_array, &rnti_count)) return 0;

    clock_t start = clock();
    NFAPI_CRC_INDICATION_PDU_T *pdus = createPDUs(rnti_array, rnti_count);
    clock_t end = clock();

    double cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
    printf("Processed PDUs in %f milliseconds\n", cpu_time_used);

    executeCommand("/path/to/your/command");

    for (int i = 0; i < rnti_count; ++i) {
        free(rnti_array[i]);
    }

    free(pdus);
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <network_log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    return processPDUs(argv[1]) ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

