} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535
#define ERROR_NONE 0
#define ERROR_MEMORY_ALLOCATION_FAILURE -1

// External function signature, assumed to be thread-safe.
int get_valid_tag(int *rx_ue_info_tag, int *rnti);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
void free_linked_list(Node* head);
Node* generate_and_sort_crc_indications(int N, unsigned int seed, int* max_crc_flag);
int compare_rnti(const void *a, const void *b);

int populate_and_sort_crc_indications(int N, unsigned int seed, NFAPI_CRC_INDICATION_PDU_T** structures, int* max_crc_flag) {
    if (N <= 0 || N > MAX_RNTI) {
        return ERROR_MEMORY_ALLOCATION_FAILURE;
    }

    srand(seed);
    Node* head = NULL;

    for (int i = 0; i < N; ++i) {
        int rx_ue_info_tag, rnti;
        int attempts = 3;

        while (attempts-- > 0) {
            if (get_valid_tag(&rx_ue_info_tag, &rnti) == 0) { // Assume 0 indicates success.
                break;
            }
        }

        if (attempts < 0) {
            free_linked_list(head);
            return ERROR_MEMORY_ALLOCATION_FAILURE; // Failed to get a valid tag after retries.
        }

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free_linked_list(head);
            return ERROR_MEMORY_ALLOCATION_FAILURE;
        }

        int crc_flag = rand() % 256; // Random CRCFLAG value between 0 and 255.

        new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
        new_node->data.RNTI = rnti;
        new_node->data.CRCFLAG = crc_flag;

        if (!head || head->data.RNTI > rnti) {
            new_node->next = head;
            head = new_node;
        } else {
            Node* current = head;
            while (current->next && current->next->data.RNTI < rnti) {
                current = current->next;
            }
            new_node->next = current->next;
            current->next = new_node;
        }

        if (crc_flag > *max_crc_flag) {
            *max_crc_flag = crc_flag;
        }
    }

    // Convert linked list to array.
    int count = 0;
    Node* current = head;
    while (current) {
        count++;
        current = current->next;
    }

    if (count != N) {
        free_linked_list(head);
        return ERROR_MEMORY_ALLOCATION_FAILURE;
    }

    *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*structures)) {
        free_linked_list(head);
        return ERROR_MEMORY_ALLOCATION_FAILURE;
    }

    current = head;
    for (int i = 0; i < N; ++i) {
        (*structures)[i] = current->data;
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return ERROR_NONE;
}

void free_linked_list(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
