    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG; // Randomly set CRC flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t count;
    pthread_mutex_t lock;
} NFAPICRCIndicationList;

// Function prototypes
void initialize_list(NFAPICRCIndicationList* list);
void add_structure(NFAPICRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T new_struct);
void sort_list(NFAPICRCIndicationList* list);
int is_rnti_unique(const NFAPICRCIndicationList* list, int rnti);
NFAPI_CRC_INDICATION_PDU_T create_random_crc_indication_pdu(int rnti, int tag);

// Initialize the list
void initialize_list(NFAPICRCIndicationList* list) {
    list->structures = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a structure to the list
void add_structure(NFAPICRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES || !is_rnti_unique(list, new_struct.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->structures[list->count++] = new_struct;
    sort_list(list);

    pthread_mutex_unlock(&list->lock);
}

// Check if RNTI is unique in the list
int is_rnti_unique(const NFAPICRCIndicationList* list, int rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->structures[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Sort the list based on RNTI values
void sort_list(NFAPICRCIndicationList* list) {
    qsort(list->structures, list->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          (int (*)(const void*, const void*))compare_rnti);
}

// Compare function for sorting by RNTI
int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* structA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* structB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return (structA->RNTI - structB->RNTI);
}

// Create a random CRC indication PDU
NFAPI_CRC_INDICATION_PDU_T create_random_crc_indication_pdu(int rnti, int tag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256; // Random CRC flag
    return pdu;
}

// Clean up the list
void destroy_list(NFAPICRCIndicationList* list) {
    free(list->structures);
    pthread_mutex_destroy(&list->lock);
}
```

### Explanation:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the list.
- **Memory Efficiency**: Allocates a fixed-size array for structures, minimizing fragmentation.
- **Sorting and Uniqueness**: Ensures no consecutive RNTIs are identical and sorts based on RNTI using `qsort`.
- **Random CRCFLAG**: Uses `rand()` to set a random CRC flag in each structure.
- **Modularity**: Functions are designed to be easily extended or modified for future requirements.

This implementation is modular, thread-safe, and efficient for handling up to 10,000 structures.']

