typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

bool resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false;
    da->array = new_array;
    da->capacity = new_capacity;
    return true;
}

void init_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand((unsigned int)time(NULL) ^ (uintptr_t)pdu);
    pdu->CRC_INDICATION_REL8_TAG.REL8_TAG.CRCFLAG = rand() % 2 == 0;
}

bool add_pseudo_random_pdu(DynamicArray *da, int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&da->lock);

    if (da->count >= da->capacity && !resize_dynamic_array(da, da->capacity ? da->capacity * 2 : 4)) {
        pthread_mutex_unlock(&da->lock);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &da->array[da->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    init_random_crcflag(pdu);

    pthread_mutex_unlock(&da->lock);
    return true;
}

bool update_pdu(DynamicArray *da, size_t index, int rx_ue_tag, int rnti) {
    if (index >= da->count) return false;

    pthread_mutex_lock(&da->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = &da->array[index];
    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    init_random_crcflag(pdu);

    pthread_mutex_unlock(&da->lock);
    return true;
}

bool delete_pdu(DynamicArray *da, size_t index) {
    if (index >= da->count) return false;

    pthread_mutex_lock(&da->lock);

    memmove(&da->array[index], &da->array[index + 1], (da->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --da->count;

    if (da->capacity > 4 && da->count < da->capacity / 4) {
        resize_dynamic_array(da, da->capacity / 2);
    }

    pthread_mutex_unlock(&da->lock);
    return true;
}

void print_dynamic_array(const DynamicArray *da) {
    for (size_t i = 0; i < da->count; ++i) {
        printf("Index %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               i,
               da->array[i].RX_UE_INFORMATION_TAG,
               da->array[i].RNTI,
               da->array[i].CRC_INDICATION_REL8_TAG.REL8_TAG.CRCFLAG);
    }
}

int main() {
    DynamicArray *da = create_dynamic_array(2);

    add_pseudo_random_pdu(da, 1, 100);
    add_pseudo_random_pdu(da, 2, 200);
    print_dynamic_array(da);

    update_pdu(da, 0, 3, 300);
    delete_pdu(da, 1);
    print_dynamic_array(da);

    free_dynamic_array(da);
    return 0;
}
```

### Explanation

