#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the LTE_UERadioResourceConfigDedicated structure
typedef struct {
    int bwpId;
    // Add other parameters as needed (e.g., SRS configurations, beamforming indicators)
} LTE_UERadioResourceConfigDedicated;

// Define a node for linked list management
typedef struct ConfigNode {
    LTE_UERadioResourceConfigDedicated config;
    struct ConfigNode* next;
} ConfigNode;

// Define the dynamic array structure with a mutex for thread safety
typedef struct {
    ConfigNode* head;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize the dynamic array
void initDynamicArray(DynamicArray* array) {
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
}

// Function to validate BWP configuration
int validateBWPConfig(const LTE_UERadioResourceConfigDedicated* config) {
    // Example validation: Ensure bwpId is within a valid range
    return config->bwpId >= 1 && config->bwpId <= 10; // Adjust range as needed
}

// Function to add or update a configuration
void addOrUpdateConfig(DynamicArray* array, LTE_UERadioResourceConfigDedicated config) {
    pthread_mutex_lock(&array->lock);

    ConfigNode* current = array->head;
    ConfigNode* prev = NULL;

    // Check if the config already exists and update it
    while (current != NULL) {
        if (current->config.bwpId == config.bwpId) {
            current->config = config; // Update existing configuration
            pthread_mutex_unlock(&array->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    // Validate the new configuration before adding
    if (validateBWPConfig(&config)) {
        ConfigNode* newNode = malloc(sizeof(ConfigNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        newNode->config = config;
        newNode->next = NULL;

        // Add new configuration to the list
        if (prev == NULL) {
            array->head = newNode;
        } else {
            prev->next = newNode;
        }
    } else {
        fprintf(stderr, "Invalid BWP configuration\n");
    }

    pthread_mutex_unlock(&array->lock);
}

// Function to remove a configuration by bwpId
void removeConfig(DynamicArray* array, int bwpId) {
    pthread_mutex_lock(&array->lock);

    ConfigNode *current = array->head, *prev = NULL;

    while (current != NULL) {
        if (current->config.bwpId == bwpId) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&array->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    fprintf(stderr, "Configuration not found\n");
    pthread_mutex_unlock(&array->lock);
}

// Function to free the dynamic array
void freeDynamicArray(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);

    ConfigNode *current = array->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    array->head = NULL;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    LTE_UERadioResourceConfigDedicated config1 = {1};
    addOrUpdateConfig(&array, config1);

    LTE_UERadioResourceConfigDedicated config2 = {2};
    addOrUpdateConfig(&array, config2);

    removeConfig(&array, 1);

    freeDynamicArray(&array);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures thread-safe operations.
- **Validation**: The `validateBWPConfig` function checks the integrity of configurations before applying them.
- **Dynamic Memory Management**: Configurations are managed using a linked list to handle dynamic memory efficiently.
- **Error Handling**: Basic error handling is included for memory allocation failures and invalid configurations.
- **Scalability and Performance**: The implementation uses efficient data structures and minimizes locking duration to maintain performance.']

