    nfaapi_crc_list.count++;

    pthread_mutex_unlock(&nfaapi_crc_list.lock);
    return NULL;
}

void cleanup_crc_indication_pdu_list() {
    pthread_mutex_lock(&nfaapi_crc_list.lock);

    if (nfaapi_crc_list.entries) {
        free(nfaapi_crc_list.entries);
        nfaapi_crc_list.entries = NULL;
    }

    log_message("Cleanup: CRC Indication PDU list freed.");
    nfaapi_crc_list.count = 0;

    pthread_mutex_unlock(&nfaapi_crc_list.lock);
}

int main() {
    // Example usage
    uint32_t sample_tag = 12345; // Sample tag for demonstration

    pthread_t thread;
    pthread_create(&thread, NULL, create_crc_indication_pdu, &sample_tag);
    pthread_join(thread, NULL);

    cleanup_crc_indication_pdu_list();

    return 0;
}
```

