typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} List;

List* list_init() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool validate_structure(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement validation logic for RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG
    return pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0 && pdu->CRC_INDICATION_REL8_TAG >= 0;
}

void manageAndValidateList(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu || !validate_structure(pdu)) return;

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        // Handle out-of-memory or max size exceeded
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        // Handle allocation failure
        return;
    }

    new_node->data = *pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

