int validate_config_file(const char *filename, size_t *buffer_sizes, int *rf_ch_ids, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // File open error

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (*count >= MAX_BUFFERS) break;

        int buffer_size;
        int rf_ch_id;
        if (sscanf(line, "%d %d", &buffer_size, &rf_ch_id) != 2) continue; // Malformed line

        if (buffer_size <= 0 || rf_ch_id < 1 || rf_ch_id > 14) continue; // Invalid values

        buffer_sizes[(*count)++] = (size_t)buffer_size;
        rf_ch_ids[(*count) - 1] = rf_ch_id;
