        if (!buffer->data) {
            free(buffer);
            break;
        }

        manager->buffers[manager->count++] = buffer;
    }
    pthread_mutex_unlock(&manager->lock);

    *manager_out = manager;

    return (manager->count == count) ? 0 : -3; // Check for allocation success
}

