        void *new_pool = realloc(memory_pool, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) return -1;

        memory_pool = new_pool;
        memory_pool_size = num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Initialize the array
    NFAPI_CRC_INDICATION_PDU_T *start_ptr = (NFAPI_CRC_INDICATION_PDU_T *)memory_pool;
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_elements; ++i, ++start_ptr) {
        start_ptr->RX_UE_INFORMATION_TAG = rand() ^ SEED_OFFSET;
        start_ptr->RNTI = rand() & 0xFFFF;
        start_ptr->CRC_INDICATION_REL8_TAG = rand() & 0xFF;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)memory_pool;
    return 0; // Success
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (*array && memory_pool == (void*)(*array)) {
        free(memory_pool);
        memory_pool = NULL;
        memory_pool_size = 0;
