// Function prototypes
void init_crc_indication_manager(CRC_Indication_Manager* manager, size_t initial_max_size);
void cleanup_crc_indication_manager(CRC_Indication_Manager* manager);
bool update_crc_list(CRC_Indication_Manager* manager, size_t max_size);

// Initialize the CRC Indication Manager
void init_crc_indication_manager(CRC_Indication_Manager* manager, size_t initial_max_size) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->list) {
        manager->allocation_failed = true;
        return;
    }
    manager->count = 0;
    manager->max_size = initial_max_size;
    manager->allocation_failed = false;
}

// Cleanup the CRC Indication Manager
void cleanup_crc_indication_manager(CRC_Indication_Manager* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->list) {
        free(manager->list);
        manager->list = NULL;
    }
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

// Update the CRC list ensuring no two consecutive RNTIs are the same
bool update_crc_list(CRC_Indication_Manager* manager, size_t max_size) {
    pthread_mutex_lock(&manager->mutex);

    if (max_size != manager->max_size) {
        // Handle dynamic updates to maximum list size safely
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(manager->list, max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&manager->mutex);
            return false;  // Allocation failed
        }
        manager->list = new_list;
        manager->max_size = max_size;
    }

    for (size_t i = 0; i < manager->count && i < manager->max_size - 1; ++i) {
        if (manager->list[i].ue_info_tag.RNTI == manager->list[i + 1].ue_info_tag.RNTI) {
            // Ensure no two consecutive RNTIs are the same
            uint32_t new_rnti = rand();  // Fetch a random RNTI, assuming it's valid and not zero.
            manager->list[i + 1].ue_info_tag.RNTI = new_rnti;
        }

        // Randomly set CRCFLAG
        manager->list[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    }

    if (manager->count > manager->max_size) {
        manager->count = manager->max_size;  // Truncate the list without reallocation
    }

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

// Example usage
int main() {
    CRC_Indication_Manager manager;

    init_crc_indication_manager(&manager, 10);  // Initialize with initial max size of 10

    if (!manager.allocation_failed) {
        bool success = update_crc_list(&manager, 15);  // Attempt to update the list
        if (success) {
            printf("CRC list updated successfully.\n");
        } else {
            printf("Failed to update CRC list due to allocation failure.\n");
        }
    }

    cleanup_crc_indication_manager(&manager);
    return 0;
}
