    time_t timestamp;
    struct CacheEntry *prev, *next;
} CacheEntry;

typedef struct {
    CacheEntry *head, *tail;
    int size;
    pthread_rwlock_t lock;
} LRUCache;

static NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_array = NULL;
