            pthread_mutex_unlock(&array_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array_lock);
    return 1;
}

void add_to_cache(int rx_ue_info_tag) {
    pthread_rwlock_wrlock(&cache.lock);
    CacheEntry *entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        log_message(3, "Failed to allocate cache entry.");
        pthread_rwlock_unlock(&cache.lock);
        return;
    }
    entry->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    entry->timestamp = time(NULL);

    if (cache.size == CACHE_SIZE) {
        CacheEntry *old_entry = cache.head;
        cache.head = cache.head->next;
        if (cache.head) {
            cache.head->prev = NULL;
        } else {
            cache.tail = NULL;
        }
        free(old_entry);
        cache.size--;
    }

    entry->next = NULL;
    entry->prev = cache.tail;
    if (cache.tail) {
        cache.tail->next = entry;
    } else {
        cache.head = entry;
    }
    cache.tail = entry;
    cache.size++;
    pthread_rwlock_unlock(&cache.lock);
}

int get_from_cache() {
    pthread_rwlock_rdlock(&cache.lock);
    CacheEntry *entry = cache.tail;
    if (entry) {
        int rx_ue_info_tag = entry->RX_UE_INFORMATION_TAG;
        if (entry == cache.head && entry == cache.tail) {
            free(entry);
            cache.head = NULL;
            cache.tail = NULL;
            cache.size--;
        } else if (entry == cache.tail) {
            cache.tail = entry->prev;
            if (cache.tail) {
                cache.tail->next = NULL;
            }
            free(entry);
            cache.size--;
        } else {
            CacheEntry *temp = entry->prev;
            temp->next = entry->next;
            if (entry->next) {
                entry->next->prev = temp;
            }
            free(entry);
            cache.size--;
        }
    } else {
        rx_ue_info_tag = -1; // or some invalid value
    }
    pthread_rwlock_unlock(&cache.lock);
    return rx_ue_info_tag;
}

