['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define RSSI_MIN -100  // Example range for RSSI in dBm
#define RSSI_MAX 0     // Example range for RSSI in dBm

typedef struct {
    int32_t rnti;
} RX_UE_INFO_TAG;

typedef struct {
    time_t timestamp;
    int32_t signal_strength_indicator; // RSSI value
} PHY_STATUS_REPORT_TAG;

typedef struct {
    RX_UE_INFO_TAG rx_ue_info_tag;
    int32_t rnti;
    PHY_STATUS_REPORT_TAG phy_status_report_tag;
} MAC_PDU;

typedef struct Node {
    MAC_PDU mac_pdu;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

unsigned int hash_function(RX_UE_INFO_TAG info, int32_t rnti, size_t size) {
    return ((info.rnti ^ rnti) % size);
}

HashTable* create_hash_table(size_t size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->table = (Node**)calloc(size, sizeof(Node*));
    ht->size = size;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node* current = ht->table[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->mutex);
    free(ht);
}

int is_unique(HashTable* ht, RX_UE_INFO_TAG info, int32_t rnti) {
    unsigned int index = hash_function(info, rnti, ht->size);
    Node* current = ht->table[index];

    while (current) {
        if (current->mac_pdu.rx_ue_info_tag.rnti == info.rnti &&
            current->mac_pdu.rnti == rnti) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

void add_to_hash_table(HashTable* ht, MAC_PDU pdu) {
    unsigned int index = hash_function(pdu.rx_ue_info_tag, pdu.rnti, ht->size);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->mac_pdu = pdu;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
}

int initialize_mac_pdu_list(MAC_PDU** list, size_t initial_capacity) {
    *list = (MAC_PDU*)calloc(initial_capacity, sizeof(MAC_PDU));
    if (!*list) return -1;

    HashTable* hash_table = create_hash_table(1024); // Example hash table size
    if (!hash_table) return -1;

    pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    int added_count = 0;
    for (size_t i = 0; i < initial_capacity; ++i) {
        MAC_PDU pdu;

        // Randomly generate RX_UE_INFO_TAG and RNTI
        pdu.rx_ue_info_tag.rnti = rand() % 10000 + 1;
        pdu.rnti = rand() % 10000 + 1;

        // Ensure uniqueness
        pthread_mutex_lock(&list_mutex);
        if (!is_unique(hash_table, pdu.rx_ue_info_tag, pdu.rnti)) {
            pthread_mutex_unlock(&list_mutex);
            continue; // Skip if not unique
        }
        pthread_mutex_unlock(&list_mutex);

        // Randomly set RSSI within specified range
        pdu.phy_status_report_tag.signal_strength_indicator = 
            rand() % (RSSI_MAX - RSSI_MIN + 1) + RSSI_MIN;
        pdu.phy_status_report_tag.timestamp = time(NULL);

        // Add to hash table for uniqueness check
        pthread_mutex_lock(&hash_table->mutex);
        add_to_hash_table(hash_table, pdu);
        pthread_mutex_unlock(&hash_table->mutex);

        // Add to list
        (*list)[added_count++] = pdu;
    }

    free_hash_table(hash_table);
    return added_count;
}

int main() {
    MAC_PDU* mac_pdu_list;
    int result = initialize_mac_pdu_list(&mac_pdu_list, 1000); // Example initial capacity

    if (result == -1) {
        fprintf(stderr, "Error initializing MAC PDU list.\n");
    } else {
        printf("Successfully added %d MAC_PDU structures.\n", result);
        free(mac_pdu_list);
    }

    return 0;
}
```

This code initializes a dynamic list of `MAC_PDU` structures with unique combinations of `RX_UE_INFO_TAG` and `RNTI`. It uses a hash table to ensure uniqueness, manages memory efficiently, and supports thread safety using mutexes. The RSSI is randomly set within the specified range, and the function returns the number of successfully added structures or -1 on error.']

