#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import threading

typedef struct {
    uint32_t tag;
    uint16_t cell_id;
    uint8_t rrc_instance;
    char *sib1_message; // Dynamically allocated to hold SIB1 message content
} LTE_DL_FRAME;

typedef struct {
    LTE_DL_FRAME **frames;
    size_t capacity;
    size_t size;
    threading.Lock lock;
} LTE_DL_FRAME_ARRAY;

// Initialize dynamic array structure
void initialize_array(LTE_DL_FRAME_ARRAY *array, size_t initial_capacity) {
    if (initial_capacity == 0)
        initial_capacity = 10; // Default initial capacity

    array->frames = (LTE_DL_FRAME **)malloc(initial_capacity * sizeof(LTE_DL_FRAME *));
    array->capacity = initial_capacity;
    array->size = 0;

    if (!array->frames) {
        fprintf(stderr, "Memory allocation failed for LTE_DL_FRAME_ARRAY.\n");
        exit(EXIT_FAILURE);
    }

    threading.Lock_init(&array->lock);
}

// Resize the dynamic array
void resize_array(LTE_DL_FRAME_ARRAY *array) {
    size_t new_capacity = array->capacity * 2;
    LTE_DL_FRAME **new_frames = (LTE_DL_FRAME **)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME *));

    if (!new_frames) {
        fprintf(stderr, "Memory reallocation failed for LTE_DL_FRAME_ARRAY.\n");
        // Handle error gracefully - can't resize but continue with current capacity
        return;
    }

    array->frames = new_frames;
    array->capacity = new_capacity;
}

// Add a new frame entry to the array
void add_frame(LTE_DL_FRAME_ARRAY *array, uint32_t tag, uint16_t cell_id, uint8_t rrc_instance, const char *sib1_message) {
    threading.Lock_acquire(&array->lock);

    if (array->size == array->capacity)
        resize_array(array);

    LTE_DL_FRAME *new_frame = (LTE_DL_FRAME *)malloc(sizeof(LTE_DL_FRAME));
    if (!new_frame) {
        fprintf(stderr, "Memory allocation failed for new LTE_DL_FRAME.\n");
        threading.Lock_release(&array->lock);
        return;
    }

    new_frame->tag = tag;
    new_frame->cell_id = cell_id;
    new_frame->rrc_instance = rrc_instance;
    size_t sib1_len = strlen(sib1_message) + 1; // Include null terminator
    if (sib1_len > 1024) {
        fprintf(stderr, "SIB1 message exceeds maximum allowed length.\n");
        free(new_frame);
        threading.Lock_release(&array->lock);
        return;
    }

    new_frame->sib1_message = (char *)malloc(sib1_len);
    if (!new_frame->sib1_message) {
        fprintf(stderr, "Memory allocation failed for SIB1 message.\n");
        free(new_frame);
        threading.Lock_release(&array->lock);
        return;
    }

    strncpy(new_frame->sib1_message, sib1_message, 1024);
    new_frame->sib1_message[1023] = '\0'; // Ensure null-termination

    array->frames[array->size++] = new_frame;

    threading.Lock_release(&array->lock);
}

// Update an existing frame entry
int update_frame(LTE_DL_FRAME_ARRAY *array, uint32_t tag, const char *new_sib1_message) {
    threading.Lock_acquire(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->tag == tag) {
            size_t sib1_len = strlen(new_sib1_message) + 1;
            if (sib1_len > 1024) {
                fprintf(stderr, "SIB1 message exceeds maximum allowed length during update.\n");
                threading.Lock_release(&array->lock);
                return -1;
            }

            free(array->frames[i]->sib1_message);

            array->frames[i]->sib1_message = (char *)malloc(sib1_len);
            if (!array->frames[i]->sib1_message) {
                fprintf(stderr, "Memory allocation failed during SIB1 message update.\n");
                threading.Lock_release(&array->lock);
                return -1;
            }

            strncpy(array->frames[i]->sib1_message, new_sib1_message, 1024);
            array->frames[i]->sib1_message[1023] = '\0'; // Ensure null-termination

            threading.Lock_release(&array->lock);
            return 0; // Success
        }
    }

    threading.Lock_release(&array->lock);
    return -1; // Entry not found
}

// Free all resources associated with the dynamic array
void free_array(LTE_DL_FRAME_ARRAY *array) {
    threading.Lock_acquire(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]) {
            free(array->frames[i]->sib1_message);
            free(array->frames[i]);
        }
    }

    free(array->frames);
    threading.Lock_destroy(&array->lock);
}

// Example logging function
void log_operation(const char *operation, const char *details) {
#ifdef DEBUG
    fprintf(stderr, "Operation: %s - Details: %s\n", operation, details);
#endif
}
```

This code provides a thread-safe implementation for managing a dynamic array of `LTE_DL_FRAME` structures with concurrent access support. It handles memory allocation and resizing dynamically to accommodate growing data needs efficiently while ensuring that the size constraints are respected. The logging mechanism is included but can be enabled or disabled via preprocessor directives for debugging purposes without affecting normal operations.']

