typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicNFAPIList;

DynamicNFAPIList* init_dynamic_nfa_list(size_t initial_capacity) {
    if (initial_capacity > MAX_ENTRIES || initial_capacity == 0) {
        return NULL;
    }

    DynamicNFAPIList *list = malloc(sizeof(DynamicNFAPIList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->entries = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        perror("Failed to allocate memory for entries");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_lock(&list->lock);
        if (list->count >= list->capacity) break;

        NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[list->count++];
        entry->RX_UE_INFORMATION_TAG = rand();
        entry->RNTI = rand() % 65536;
        entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;

        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

void resize_dynamic_nfa_list(DynamicNFAPIList *list, size_t new_capacity) {
    if (!list || new_capacity <= list->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entries) {
        pthread_mutex_lock(&list->lock);
        list->entries = new_entries;
        list->capacity = new_capacity;
        pthread_mutex_unlock(&list->lock);
    } else {
        perror("Failed to resize entries");
    }
}

void free_dynamic_nfa_list(DynamicNFAPIList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->entries);
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_and_print_rnti(const DynamicNFAPIList *list) {
    if (!list || !list->entries) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
