    DynamicNFAPIList *nfa_list = init_dynamic_nfa_list(initial_capacity);

    if (nfa_list) {
        iterate_and_print_rnti(nfa_list);

        // Example of resizing
        resize_dynamic_nfa_list(nfa_list, initial_capacity * 2);
        iterate_and_print_rnti(nfa_list);

        free_dynamic_nfa_list(nfa_list);
    }

    return 0;
}
