['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool validate_structure(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement validation logic based on CRCFLAG and other fields
    return true;  // Placeholder for actual validation logic
}

void init_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;  // Example initialization
    pdu->RNTI = rand() % 1000;                    // Example initialization
    pdu->crc_tag.CRCFLAG = rand() % 2;            // Randomly set CRCFLAG
}

void insert_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu || !validate_structure(pdu)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = *pdu;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);
    if (list->count == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void delete_pdu(List* list, int index) {
    if (!list || index < 0 || index >= list->count) return;

    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }

    if (!current) return;

    pthread_mutex_lock(&list->lock);
    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }
    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }
    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

void iterate_list(List* list, bool reverse) {
    Node* current = reverse ? list->tail : list->head;

    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.crc_tag.CRCFLAG);

        current = reverse ? current->prev : current->next;
    }
}

int main() {
    List* list = create_list();
    if (!list) return 1;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        init_pdu(&pdu);
        insert_pdu(list, &pdu);
    }

    iterate_list(list, false);  // Sequential traversal
    iterate_list(list, true);   // Reverse traversal

    destroy_list(list);
    return 0;
}
```

