#include <errno.h>

#define MAX_HOSTNAME_LENGTH 256
#define DNS_QUERY_RETRY_LIMIT 5

typedef struct {
    int valid;
    // Add other fields as necessary for RX_UE_INFORMATION_TAG and RNTI
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
} PduManager;

typedef enum {
    SUCCESS = 0,
    MEMORY_ERROR,
    DNS_RESOLUTION_FAILED,
    NETWORK_FAILURE
} ErrorCode;

ErrorCode resolve_hostname_to_ip(const char* hostname, u_char ip[4]) {
    struct hostent *host;
    int retry_count = 0;
    struct timeval tv = {2, 0}; // initial timeout 2 seconds

    while (retry_count < DNS_QUERY_RETRY_LIMIT) {
        setresrc(RDNS_TIMEOUT, tv.tv_sec);

        host = gethostbyname(hostname);
        if (host != NULL) {
            memcpy(ip, *host->h_addr_list, sizeof(u_char) * 4);
            return SUCCESS;
        }

        if (errno == ETIMEDOUT || errno == EAI_AGAIN) {
            retry_count++;
            tv.tv_sec *= 2; // Exponential backoff
        } else {
            break;
        }
    }

    return DNS_RESOLUTION_FAILED;
}

ErrorCode manage_pdus(PduManager *manager, const char* hostname, u_char ip[4]) {
    if (!manager || !hostname) return MEMORY_ERROR;

    pthread_mutex_lock(&manager->lock);

    int res = resolve_hostname_to_ip(hostname, ip);
    if (res != SUCCESS) {
        pthread_mutex_unlock(&manager->lock);
        return res;
    }

    // Allocate and manage PDUs
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(manager->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (manager->count + 1));
    if (!new_pdus) {
        pthread_mutex_unlock(&manager->lock);
        return MEMORY_ERROR;
    }

    manager->pdus = new_pdus;
    memset(&manager->pdus[manager->count], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Initialize the new PDU
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return SUCCESS;
}

void init_pdu_manager(PduManager *manager) {
    if (manager) {
        manager->pdus = NULL;
        manager->count = 0;
        pthread_mutex_init(&manager->lock, NULL);
    }
}

void free_pdu_manager(PduManager *manager) {
    if (manager) {
        free(manager->pdus);
        pthread_mutex_destroy(&manager->lock);
    }
}
