#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    TRAFFIC_ACCIDENT,
    ROAD_CLOSURE,
    SPEED_CHECKPOINT
} EventType;

typedef struct {
    double latitude;
    double longitude;
} Location;

typedef struct {
    time_t timestamp;
    EventType event_type;
    Location location;
} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
} TrafficEventManager;

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

TrafficEventManager* init_traffic_event_manager(size_t initial_capacity) {
    TrafficEventManager *manager = (TrafficEventManager *)malloc(sizeof(TrafficEventManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity > 0 ? initial_capacity : INITIAL_CAPACITY;
    manager->events = (TrafficEvent *)calloc(manager->capacity, sizeof(TrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    return manager;
}

void simulate_traffic_data(TrafficEventManager *manager);

int add_event(TrafficEventManager *manager, TrafficEvent event) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        TrafficEvent *new_events = (TrafficEvent *)realloc(manager->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) return -1;

        memset(new_events + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(TrafficEvent));
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    manager->events[manager->count++] = event;
    return 0;
}

int update_event(TrafficEventManager *manager, size_t index, TrafficEvent updated_event) {
    if (index >= manager->count) return -1;

    manager->events[index] = updated_event;
    return 0;
}

void free_traffic_event_manager(TrafficEventManager *manager) {
    if (manager) {
        free(manager->events);
        free(manager);
    }
}

void simulate_traffic_data(TrafficEventManager *manager) {
    // Example: Populate with some simulated data
    for (size_t i = 0; i < manager->capacity / 2; ++i) {
        TrafficEvent event;
        event.timestamp = time(NULL);  // Simulated timestamp
        event.event_type = TRAFFIC_ACCIDENT + (rand() % 3);
        event.location.latitude = rand() % 180 - 90;  // Random latitude between -90 and 89.999...
        event.location.longitude = rand() % 360 - 180; // Random longitude between -179.999... and 179.999...

        add_event(manager, event);
    }
}

int main() {
    TrafficEventManager *manager = init_traffic_event_manager(INITIAL_CAPACITY);
    if (!manager) {
        fprintf(stderr, "Failed to initialize traffic event manager.\n");
        return EXIT_FAILURE;
    }

    simulate_traffic_data(manager);

    // Example: Add a new event
    TrafficEvent new_event = { .timestamp = time(NULL), .event_type = ROAD_CLOSURE,
                               .location = { .latitude = 40.7128, .longitude = -74.0060 } };

    if (add_event(manager, new_event) != 0) {
        fprintf(stderr, "Failed to add a new event.\n");
    }

    // Example: Update an existing event
    TrafficEvent updated_event = { .timestamp = time(NULL), .event_type = SPEED_CHECKPOINT,
                                   .location = { .latitude = 34.0522, .longitude = -118.2437 } };

    if (update_event(manager, 0, updated_event) != 0) {
        fprintf(stderr, "Failed to update event.\n");
    }

    free_traffic_event_manager(manager);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Efficiency**: Starts with a small initial capacity and doubles it when needed.
- **Simulated Data Integration**: `simulate_traffic_data` is used to populate the manager with sample events.
- **Error Handling**: Checks for memory allocation failures, returns error codes for unsuccessful operations.
- **Iterative Safety**: The array structure ensures safe iteration by maintaining separate count and capacity fields.']

