} L1_RX_PDU_T;

typedef enum {
    FRAME_STATE_PENDING,
    FRAME_STATE_INITIALIZED
} FrameState;

typedef struct {
    L1_RRC_CTXT_T ctxt;
    L1_RX_PDU_T *pdu;
    FrameState state;
} NFAPI_L1_RX_FRAME_INFO_T;

typedef struct {
    NFAPI_L1_RX_FRAME_INFO_T **frames;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} FrameManager;

void initializeFrameManager(FrameManager *manager) {
    manager->frames = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

int addFrame(FrameManager *manager, L1_RRC_CTXT_T ctxt) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 4;
        NFAPI_L1_RX_FRAME_INFO_T **new_frames = realloc(manager->frames, new_capacity * sizeof(NFAPI_L1_RX_FRAME_INFO_T *));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    NFAPI_L1_RX_FRAME_INFO_T *frame = malloc(sizeof(NFAPI_L1_RX_FRAME_INFO_T));
    if (!frame) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    frame->ctxt = ctxt;
    frame->pdu = NULL;  // Allocate when needed
    frame->state = FRAME_STATE_PENDING;

    manager->frames[manager->count++] = frame;
    pthread_cond_signal(&manager->cond);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int removeFrame(FrameManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Index out of bounds
    }

    free(manager->frames[index]->pdu);
    free(manager->frames[index]);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->frames[i] = manager->frames[i + 1];
    }
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void iterateFrames(FrameManager *manager, void (*operation)(NFAPI_L1_RX_FRAME_INFO_T *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        operation(manager->frames[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void finalizeFrameManager(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->pdu);
        free(manager->frames[i]);
    }
    free(manager->frames);

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}

// Example usage of the iterate function
void exampleOperation(NFAPI_L1_RX_FRAME_INFO_T *frame) {
    if (frame->state == FRAME_STATE_INITIALIZED) {
        // Perform operation on initialized frame
    } else {
        // Handle pending frames
    }
}
```

