['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define MAX_CAPACITY 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG; // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_array(DynamicArray *da) {
    da->size = 0;
    da->capacity = INITIAL_CAPACITY;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->mutex, NULL);
}

void destroy_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}

void ensure_capacity(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity > MAX_CAPACITY) {
            new_capacity = MAX_CAPACITY;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

void add_entry(DynamicArray *da, unsigned int rx_tag, unsigned int rnti, unsigned char crcflag) {
    pthread_mutex_lock(&da->mutex);
    ensure_capacity(da);
