#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for network parameters
typedef struct {
    int signalStrength;
    double latency; // in milliseconds
} NetworkParams;

// Define a structure for an event log entry
typedef struct {
    char eventId[32];
    time_t timestamp;
    NetworkParams *params;
    size_t paramCount;
} EventLogEntry;

// Function to generate random network parameters
NetworkParams generateRandomNetworkParams() {
    NetworkParams params;
    params.signalStrength = rand() % 101; // Random signal strength between 0 and 100
    params.latency = (rand() % 500) + 10.0; // Random latency between 10ms and 510ms
    return params;
}

// Function to manage dynamic array of network event logs
typedef struct {
    EventLogEntry *entries;
    size_t capacity;
    size_t count;
} EventLogManager;

void initializeEventLogManager(EventLogManager *manager, size_t initialCapacity) {
    manager->entries = (EventLogEntry *)malloc(initialCapacity * sizeof(EventLogEntry));
    if (!manager->entries) {
        perror("Failed to allocate memory for event log entries");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initialCapacity;
    manager->count = 0;
}

void freeEventLogManager(EventLogManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i].params);
    }
    free(manager->entries);
    manager->entries = NULL;
    manager->capacity = 0;
    manager->count = 0;
}

int addEventLogEntry(EventLogManager *manager, const char *eventId, size_t paramCount) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        EventLogEntry *newEntries = realloc(manager->entries, newCapacity * sizeof(EventLogEntry));
        if (!newEntries) {
            perror("Failed to reallocate memory for event log entries");
            return -1;
        }
        manager->entries = newEntries;
        manager->capacity = newCapacity;
    }

    EventLogEntry *entry = &manager->entries[manager->count++];
    strncpy(entry->eventId, eventId, sizeof(entry->eventId) - 1);
    entry->eventId[sizeof(entry->eventId) - 1] = '\0';
    entry->timestamp = time(NULL);

    entry->params = (NetworkParams *)malloc(paramCount * sizeof(NetworkParams));
    if (!entry->params) {
        perror("Failed to allocate memory for network parameters");
        manager->count--; // Rollback the count increase
        return -1;
    }

    entry->paramCount = paramCount;
    for (size_t i = 0; i < paramCount; ++i) {
        entry->params[i] = generateRandomNetworkParams();
    }
    return 0;
}

EventLogEntry *findEventById(EventLogManager *manager, const char *eventId) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i].eventId, eventId) == 0) {
            return &manager->entries[i];
        }
    }
    return NULL;
}

int main() {
    srand((unsigned int)time(NULL));

    EventLogManager manager;
    initializeEventLogManager(&manager, 10);

    // Simulate adding events
    for (size_t i = 0; i < 20; ++i) {
        char eventId[32];
        snprintf(eventId, sizeof(eventId), "event_%zu", i);
        if (addEventLogEntry(&manager, eventId, 5) != 0) {
            fprintf(stderr, "Failed to add event: %s\n", eventId);
        }
    }

    // Simulate retrieving an event
    EventLogEntry *retrieved = findEventById(&manager, "event_10");
    if (retrieved) {
        printf("Retrieved Event ID: %s, Timestamp: %ld\n", retrieved->eventId, retrieved->timestamp);
    } else {
        printf("Event not found.\n");
    }

    // Cleanup
    freeEventLogManager(&manager);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: The `EventLogManager` dynamically allocates and reallocates memory as needed, doubling the capacity when full.
- **Random Data Generation**: Network parameters are generated randomly for each event log entry.
- **Error Handling**: Proper error handling is implemented for memory allocation failures.
- **Efficient Search**: A simple linear search is used to find events by ID, which can be optimized further if necessary.
- **Scalability Considerations**: The design allows for easy scaling with the use of dynamic arrays and efficient memory management.']

