    // Example validation logic
    return (rnti > 0 && rnti < 65535);
}

unsigned int calculate_crcflag(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simple example of a checksum algorithm
    unsigned int crc = 0;
    crc ^= pdu->RX_UE_INFORMATION_TAG;
    crc ^= (pdu->RNTI << 1);
    crc ^= (pdu->CRC_INDICATION_REL8_TAG >> 2);
    return crc;
}

int initialize_dynamic_array(DynamicArray* dynamicArray) {
    size_t initial_capacity = MAX_PDU_COUNT / 10; // Start with 10% of max capacity
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (initial_capacity * element_size > MEMORY_LIMIT) {
        fprintf(stderr, "Initial allocation exceeds memory limit\n");
        return -1;
    }

    dynamicArray->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * element_size);
    if (!dynamicArray->array) {
        perror("Failed to allocate initial array");
        return -1;
    }
    dynamicArray->capacity = initial_capacity;
    dynamicArray->count = 0;

    return 0;
}

int add_pdu(DynamicArray* dynamicArray, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_RX_UE_INFORMATION_TAG(pdu.RX_UE_INFORMATION_TAG)) {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG\n");
        return -1;
    }

    if (!validate_RNTI(pdu.RNTI)) {
        fprintf(stderr, "Invalid RNTI\n");
        return -1;
    }

    pdu.CRCFLAG = calculate_crcflag(&pdu);

    if (dynamicArray->count == dynamicArray->capacity) {
        size_t new_capacity = dynamicArray->capacity * 2;
        if (new_capacity > MAX_PDU_COUNT) {
            fprintf(stderr, "Maximum capacity reached\n");
            return -1;
        }

        size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (new_capacity * element_size > MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded\n");
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_array =
            (NFAPI_CRC_INDICATION_PDU_T*)realloc(dynamicArray->array,
                                                 new_capacity * element_size);
        if (!new_array) {
            perror("Failed to reallocate array");
            return -1;
        }
        dynamicArray->array = new_array;
        dynamicArray->capacity = new_capacity;
    }

    memcpy(&dynamicArray->array[dynamicArray->count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynamicArray->count++;

    return 0;
}

void free_dynamic_array(DynamicArray* dynamicArray) {
    if (dynamicArray->array) {
        free(dynamicArray->array);
        dynamicArray->array = NULL;
        dynamicArray->capacity = 0;
        dynamicArray->count = 0;
    }
}

