#endif
}

int addPdu(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->count >= MAX_PDU_COUNT) {
        pthread_rwlock_unlock(&manager->lock);
#ifdef LOGGING_ENABLED
        fprintf(stderr, "Buffer overflow: Unable to add new PDU.\n");
#endif
        return -1; // Buffer overflow error
    }

    manager->pdus[manager->count] = pdu;
    manager->pdus[manager->count]->CRCFLAG = computeCrcFlag(pdu);
#ifdef USE_CACHE
    manager->cached_RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
    manager->cached_RNTI = pdu->RNTI;
    manager->cache_valid = 1;
#endif

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Success
}

int getCrcFlag(PduManager *manager, size_t index, int *crcFlag) {
    if (index >= MAX_PDU_COUNT || index >= manager->count) {
#ifdef LOGGING_ENABLED
        fprintf(stderr, "Index out of bounds: Unable to retrieve CRC flag.\n");
#endif
        return -1; // Index error
    }

    pthread_rwlock_rdlock(&manager->lock);
    *crcFlag = manager->pdus[index]->CRCFLAG;
    pthread_rwlock_unlock(&manager->lock);

    return 0; // Success
}

