    manager->cached_RX_UE_INFORMATION_TAG = new_RX_UE_INFORMATION_TAG;
    manager->cached_RNTI = new_RNTI;
    manager->cache_valid = 1;
    pthread_rwlock_unlock(&manager->lock);
}
#endif

void cleanupPduManager(PduManager *manager) {
