async fn generate_pdu_instance() -> NFAPICRCIndicationPDU {
    let mut rng = rand::thread_rng();
    let rx_ue_information_tag = rng.gen::<u32>();
    let rnti = rng.gen::<u16>();
    let crc_indication_rel8_tag = CRCIndicationRel8Tag {
        crcflag: rng.gen(),
    };

    NFAPICRCIndicationPDU {
        rx_ue_information_tag,
        rnti,
        crc_indication_rel8_tag,
    }
