            let mut retries = 3;
            loop {
                match generate_pdu_instance().await {
                    Ok(pdu) => return Some(pdu),
                    Err(_) if retries > 0 => {
                        retries -= 1;
                        sleep(Duration::from_millis(100)).await; // Throttling
                    }
                    Err(_) => return None,
                }
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        match timeout(Duration::from_secs(timeout_duration), handle).await {
            Ok(result) => if let Some(pdu) = result {
                instances.push(pdu);
            },
            Err(_) => eprintln!("Task timed out"),
        }
    }

    instances
}

