#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*ProcessCallback)(NFAPI_CRC_INDICATION_PDU_T*);

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    int max_concurrent_ops;
    int active_threads;
} OperationLimiter;

void* initialize_operation_limiter(OperationLimiter *limiter, int max_concurrent_ops) {
    if (pthread_mutex_init(&limiter->mutex, NULL) != 0 ||
        pthread_cond_init(&limiter->cond_var, NULL) != 0) {
        return NULL;
    }
    limiter->max_concurrent_ops = max_concurrent_ops;
    limiter->active_threads = 0;
    return limiter;
}

void acquire_operation_limiter(OperationLimiter *limiter) {
    pthread_mutex_lock(&limiter->mutex);
    while (limiter->active_threads >= limiter->max_concurrent_ops) {
        pthread_cond_wait(&limiter->cond_var, &limiter->mutex);
    }
    limiter->active_threads++;
    pthread_mutex_unlock(&limiter->mutex);
}

void release_operation_limiter(OperationLimiter *limiter) {
    pthread_mutex_lock(&limiter->mutex);
    limiter->active_threads--;
    pthread_cond_signal(&limiter->cond_var);
    pthread_mutex_unlock(&limiter->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_array(size_t count, ProcessCallback callback) {
    if (count == 0 || callback == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    OperationLimiter limiter;
    initialize_operation_limiter(&limiter, 5); // Limit to 5 concurrent operations

    for (size_t i = 0; i < count; ++i) {
        acquire_operation_limiter(&limiter);

        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() & 1;

        callback(&array[i]);

        release_operation_limiter(&limiter);
    }

    pthread_mutex_destroy(&limiter.mutex);
    pthread_cond_destroy(&limiter.cond_var);

    return array;
}

void free_nfa_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}

size_t serialize_nfa_array(const NFAPI_CRC_INDICATION_PDU_T *array, size_t count, uint8_t **buffer) {
    size_t total_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = malloc(total_size);
    if (!*buffer) return 0;

    memcpy(*buffer, array, total_size);
    return total_size;
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_nfa_array(const uint8_t *buffer, size_t count, size_t buffer_size) {
    if (buffer_size != count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    memcpy(array, buffer, buffer_size);
    return array;
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Example processing function
    printf("Processing PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->crc_indication_rel8_tag.CRCFLAG);
}

int main() {
    size_t count = 10;
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_nfa_array(count, process_pdu);

    if (array) {
        uint8_t *serialized_data;
        size_t serialized_size = serialize_nfa_array(array, count, &serialized_data);

        if (serialized_data) {
            NFAPI_CRC_INDICATION_PDU_T *deserialized_array = deserialize_nfa_array(serialized_data, count, serialized_size);

            if (deserialized_array) {
                free(deserialized_array);
            }
            free(serialized_data);
        }

        free_nfa_array(array);
    }

    return 0;
}
