#define MAX_OPERATIONS 10
#define RATE_LIMIT_ENTRIES_PER_SECOND 5
#define CRCFLAG_SIZE sizeof(uint8_t)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
