    uint8_t CRCFLAG;
    time_t timestamp;
    int sequence_number;
} SerializedEntry;

typedef struct Node {
    SerializedEntry entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int operation_count;
    FILE* log_file;
} ListManager;

ListManager list_manager = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0, NULL};

void init_list_manager() {
    list_manager.log_file = fopen("list_log.txt", "a");
}

void destroy_list_manager() {
    if (list_manager.log_file) {
        fclose(list_manager.log_file);
    }
    Node* current = list_manager.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list_manager.lock);
    pthread_cond_destroy(&list_manager.cond);
}

void log_change(const char* action, const SerializedEntry* entry) {
    if (list_manager.log_file) {
        fprintf(list_manager.log_file, "%s: RNTI=%u, CRCFLAG=%d, Timestamp=%ld\n",
                action, entry->entry.RNTI, entry->CRCFLAG, entry->timestamp);
        fflush(list_manager.log_file);
    }
}

void add_entry(const NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t crc_flag) {
    pthread_mutex_lock(&list_manager.lock);

    while (list_manager.operation_count >= MAX_OPERATIONS) {
        pthread_cond_wait(&list_manager.cond, &list_manager.lock);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->entry.pdu = *pdu;
    new_node->entry.CRCFLAG = crc_flag;
    new_node->entry.timestamp = time(NULL);
    new_node->entry.sequence_number = rand(); // Replace with actual sequence logic
    new_node->next = list_manager.head;
    list_manager.head = new_node;

    log_change("ADD", &new_node->entry);

    list_manager.operation_count++;
    pthread_cond_signal(&list_manager.cond);
    pthread_mutex_unlock(&list_manager.lock);
}

SerializedEntry* serialize_list() {
    pthread_mutex_lock(&list_manager.lock);

    size_t size = 0;
    Node* current = list_manager.head;
    while (current) {
        size += sizeof(SerializedEntry);
        current = current->next;
    }

    SerializedEntry* buffer = malloc(size);
    if (!buffer) {
        pthread_mutex_unlock(&list_manager.lock);
        return NULL;
    }

    current = list_manager.head;
    unsigned char* ptr = (unsigned char*)buffer;
    while (current) {
        memcpy(ptr, &current->entry, sizeof(SerializedEntry));
        ptr += sizeof(SerializedEntry);
        current = current->next;
    }

    pthread_mutex_unlock(&list_manager.lock);
    return buffer;
}

int deserialize_list(const SerializedEntry* buffer, size_t size) {
    pthread_mutex_lock(&list_manager.lock);

    Node* prev = NULL;
    Node* current = list_manager.head;

    for (size_t i = 0; i < size; i += sizeof(SerializedEntry)) {
        if (!current || memcmp(&current->entry, buffer + i, sizeof(SerializedEntry))) {
            Node* new_node = malloc(sizeof(Node));
            if (!new_node) break;
            memcpy(&new_node->entry, buffer + i, sizeof(SerializedEntry));

            new_node->next = current;
            if (prev) prev->next = new_node;
            else list_manager.head = new_node;

            prev = new_node;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_manager.lock);
    return 1;
}

int validate_serialized_data(const SerializedEntry* buffer, size_t size) {
    for (size_t i = 0; i < size; i += sizeof(SerializedEntry)) {
        if (buffer[i].pdu.RX_UE_INFORMATION_TAG == 0 || buffer[i].pdu.RNTI == 0)
            return 0;
    }
    return 1;
}

void retry_mechanism(void (*operation)(const NFAPI_CRC_INDICATION_PDU_T*, uint8_t), 
                     const NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t crc_flag) {
    int retries = 3;
    while (retries--) {
        operation(pdu, crc_flag);
        if (pthread_mutex_trylock(&list_manager.lock) == 0) {
            pthread_mutex_unlock(&list_manager.lock);
            break;
        }
        sleep(1); // Retry after a delay
    }
}

void rate_limiter(void (*operation)(const NFAPI_CRC_INDICATION_PDU_T*, uint8_t),
                  const NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t crc_flag) {
    static time_t last_operation_time = 0;
    time_t current_time = time(NULL);

    if (current_time - last_operation_time < 1.0 / RATE_LIMIT_ENTRIES_PER_SECOND) {
        sleep((1.0 / RATE_LIMIT_ENTRIES_PER_SECOND) - (current_time - last_operation_time));
    }

    operation(pdu, crc_flag);
    last_operation_time = time(NULL);
}

void add_entry_with_rate_limiting_and_retry(const NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t crc_flag) {
    rate_limiter(&retry_mechanism, pdu, crc_flag, &add_entry, pdu, crc_flag);
}
