<?php

function authenticateAndRetrieveUserInfo($userId, $apiKey) {
    session_start();

    $authServerUrl = 'https://example.com/oauth/token';
    $userInfoEndpoint = "https://api.example.com/userinfo";

    // Check if access token is already in the session and valid
    if (isset($_SESSION['access_token']) && $_SESSION['token_expires'] > time()) {
        $accessToken = $_SESSION['access_token'];
    } else {
        // Prepare data for OAuth 2.0 authentication
        $data = [
            'grant_type' => 'client_credentials',
            'client_id' => $apiKey,
        ];

        // Make the request to obtain an access token
        $response = curl_init($authServerUrl);
        curl_setopt($response, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($response, CURLOPT_POST, true);
        curl_setopt($response, CURLOPT_POSTFIELDS, http_build_query($data));

        $result = curl_exec($response);
        $httpCode = curl_getinfo($response, CURLINFO_HTTP_CODE);

        if ($httpCode != 200) {
            // Handle authentication failure
            return ['error' => 'Failed to authenticate'];
        }

        $tokenData = json_decode($result, true);
        $accessToken = $tokenData['access_token'];
        $expiresIn = $tokenData['expires_in'];

        // Store the access token in the session with expiration time
        $_SESSION['access_token'] = $accessToken;
        $_SESSION['token_expires'] = time() + $expiresIn;
    }

    // Use the access token to fetch user information
    $ch = curl_init($userInfoEndpoint);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $accessToken,
    ]);

    $userInfoResponse = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

    if ($httpCode != 200) {
        // Handle failure to retrieve user information
        return ['error' => 'Failed to retrieve user info'];
    }

    $userInformation = json_decode($userInfoResponse, true);

    // Implement caching mechanism here (omitted for brevity)

    return [
        'user_info' => $userInformation,
        'metadata' => [
            'access_token_expiration' => $_SESSION['token_expires'],
        ],
    ];
}
