// Definitions for custom types and constants.
#define MAX_RNTI 65535
#define MAX_ELEMENTS 10000
#define MEMORY_LIMIT (50 * 1024 * 1024) // 50 MB

typedef struct {
    unsigned int crcFlag; // Represents the CRC flag, can be set randomly.
} CRC_INDICATION_REL8_TAG;

