typedef struct Element {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    struct Element *next;
} Element;

// Custom allocator management
typedef struct {
    void *pool;
    size_t blockSize;
    size_t poolSize;
    pthread_mutex_t lock;
} MemoryPool;

void initializeMemoryPool(MemoryPool *pool, size_t blockSize, size_t poolSize) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->blockSize = blockSize;
    pool->poolSize = poolSize;
    pool->pool = malloc(poolSize);
}

void* customAllocate(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(pool->blockSize);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void customDeallocate(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);
    free(ptr);
    pthread_mutex_unlock(&pool->lock);
}

// Global variables for list management
Element *head = NULL, *tail = NULL;
pthread_rwlock_t listLock = PTHREAD_RWLOCK_INITIALIZER;

void logInvalidRNTI(unsigned int rnti) {
    fprintf(stderr, "Invalid RNTI: %u\n", rnti);
}

void addElement(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pdu.RNTI < 1 || pdu.RNTI > MAX_RNTI) {
        logInvalidRNTI(pdu.RNTI);
        return;
    }

    pthread_rwlock_wrlock(&listLock);

    Element *newElement = (Element *) customAllocate(pool);
    newElement->pdu = pdu;
    newElement->timestamp = time(NULL);
    newElement->next = NULL;

    if (!head) {
        head = tail = newElement;
    } else {
        // Ensure no consecutive elements have the same RNTI
        while (tail && tail->pdu.RNTI == pdu.RNTI) {
            customDeallocate(pool, tail);
            Element *temp = head;
            while (temp && temp->next != tail) {
                temp = temp->next;
            }
            if (temp) temp->next = NULL;
            tail = temp;

            newElement = (Element *) customAllocate(pool);
            newElement->pdu = pdu;
            newElement->timestamp = time(NULL);
        }

        tail->next = newElement;
        tail = newElement;
    }

    pthread_rwlock_unlock(&listLock);
}

void processExternalData(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *dataArray, size_t dataSize) {
    for (size_t i = 0; i < dataSize; ++i) {
        dataArray[i].pdu.crcFlag = rand() % 2; // Randomly set CRC flag
        addElement(pool, dataArray[i]);
    }
}

void cleanup(MemoryPool *pool) {
    pthread_rwlock_wrlock(&listLock);
    Element *current = head;
    while (current) {
        Element *temp = current;
        current = current->next;
        customDeallocate(pool, temp);
    }
    head = tail = NULL;
    pthread_rwlock_unlock(&listLock);

    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    MemoryPool pool;
    initializeMemoryPool(&pool, sizeof(Element), MEMORY_LIMIT);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T exampleData[] = {
        { .RNTI = 1234, .validTag = 1 },
        { .RNTI = 5678, .validTag = 1 },
        { .RNTI = 1234, .validTag = 0 }, // Intentional duplicate for testing
    };

    processExternalData(&pool, exampleData, sizeof(exampleData) / sizeof(NFAPI_CRC_INDICATION_PDU_T));

    cleanup(&pool);
    return 0;
}
