} PHY_RX_TX_CONFIG_T;

typedef struct {
    unsigned long rx_timestamp;
    PHY_RX_TX_CONFIG_T config;
    PHY_STATS_T stats;
} PHY_FRAME_INFO_T;

#define TEMPORAL_RANGE_MIN 0
#define TEMPORAL_RANGE_MAX 1000000000 // Example range

typedef struct Node {
    PHY_FRAME_INFO_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    size_t count;
} PhyFrameList;

PhyFrameList* create_list() {
    PhyFrameList* list = (PhyFrameList*)malloc(sizeof(PhyFrameList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

void destroy_list(PhyFrameList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_timestamp_valid(unsigned long timestamp, PhyFrameList* list) {
    if (timestamp < TEMPORAL_RANGE_MIN || timestamp > TEMPORAL_RANGE_MAX)
        return 0;

    Node* node = list->head;
    while (node) {
        if (node->data.rx_timestamp == timestamp)
            return 0; // Timestamp already exists
        node = node->next;
    }

    return 1;
}

int add_frame_info(PhyFrameList* list, PHY_FRAME_INFO_T frame_info) {
    if (!is_timestamp_valid(frame_info.rx_timestamp, list))
        return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node)
        return -1;

    new_node->data = frame_info;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = NULL;
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_frame_info(PhyFrameList* list, unsigned long timestamp) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.rx_timestamp == timestamp) {
            if (current->prev)
                current->prev->next = current->next;
            else
                list->head = current->next;

            if (current->next)
                current->next->prev = current->prev;
            else
                list->tail = current->prev;

            free(current);
            list->count--;

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

int update_frame_info(PhyFrameList* list, unsigned long old_timestamp, PHY_FRAME_INFO_T new_frame_info) {
    if (!is_timestamp_valid(new_frame_info.rx_timestamp, list))
        return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.rx_timestamp == old_timestamp) {
            current->data = new_frame_info;

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void print_list(PhyFrameList* list) {
    pthread_mutex_lock(&list->lock);

    Node* node = list->head;
    while (node) {
        printf("Timestamp: %lu, Config Data: %d, Statistic: %d\n",
               node->data.rx_timestamp,
               node->data.config.config_data,
               node->data.stats.some_statistic);

        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example logging integration function
void log_operation(const char* operation, int result) {
    // Assume we have a logging framework available
    printf("Operation: %s, Result: %d\n", operation, result);
}
