```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TRANSPORT_FORMATS 100

typedef struct {
    int parameter;
} PHY_TRANSPORT_FORMAT_CONFIG_T;

typedef struct {
    int stats;
} PHY_TRANSPORT_FORMAT_STATS_T;

typedef struct {
    int event;
} PHY_TRANSPORT_FORMAT_EVENT_T;

typedef struct {
    PHY_TRANSPORT_FORMAT_CONFIG_T config;
    PHY_TRANSPORT_FORMAT_STATS_T stats;
    PHY_TRANSPORT_FORMAT_EVENT_T event;
} NFAPI_LTE_PDU_T;

typedef struct {
    NFAPI_LTE_PDU_T* pool;
    size_t capacity;
    pthread_mutex_t lock;
} PduPool;

PduPool* pdu_pool_create(size_t initial_capacity) {
    PduPool* pool = (PduPool*)malloc(sizeof(PduPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->pool = (NFAPI_LTE_PDU_T*)calloc(pool->capacity, sizeof(NFAPI_LTE_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

int pdu_pool_validate_config(const PHY_TRANSPORT_FORMAT_CONFIG_T* config) {
    // Example validation logic
    return (config->parameter >= 0 && config->parameter <= MAX_TRANSPORT_FORMATS);
}

void pdu_pool_modify(int index, const PHY_TRANSPORT_FORMAT_CONFIG_T* newConfig,
                     const PHY_TRANSPORT_FORMAT_STATS_T* newStats,
                     const PHY_TRANSPORT_FORMAT_EVENT_T* newEvent, PduPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->capacity) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    if (!pdu_pool_validate_config(newConfig)) {
        fprintf(stderr, "Configuration validation failed\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    pool->pool[index].config = *newConfig;
    pool->pool[index].stats = *newStats;
    pool->pool[index].event = *newEvent;

    pthread_mutex_unlock(&pool->lock);
}

void pdu_pool_create_pdu(const PHY_TRANSPORT_FORMAT_CONFIG_T* config,
                         const PHY_TRANSPORT_FORMAT_STATS_T* stats,
                         const PHY_TRANSPORT_FORMAT_EVENT_T* event, PduPool* pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->pool[i].config.parameter == -1) { // Assuming -1 indicates unused
            if (!pdu_pool_validate_config(config)) {
                fprintf(stderr, "Configuration validation failed\n");
                pthread_mutex_unlock(&pool->lock);
                return;
            }
            pool->pool[i] = (NFAPI_LTE_PDU_T){ *config, *stats, *event };
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void pdu_pool_delete_pdu(int index, PduPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (index < 0 || index >= pool->capacity) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    // Reset to default/empty state
    pool->pool[index].config.parameter = -1; 
    pool->pool[index].stats.stats = 0;
    pool->pool[index].event.event = 0;

    pthread_mutex_unlock(&pool->lock);
}

void pdu_pool_destroy(PduPool* pool) {
    if (pool) {
        free(pool->pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
```

### Key Points:
