NFAPICRCList* create_list(size_t initial_capacity) {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_list(NFAPICRCList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return;

    memset(new_elements + list->size, 0, (new_capacity - list->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->elements = new_elements;
    list->capacity = new_capacity;
}

int add_element(NFAPICRCList* list, RX_UE_INFORMATION_TAG ueInfoTag, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Max elements reached.
    }

    if (list->size == list->capacity) {
        resize_list(list, list->capacity * 2 > MAX_ELEMENTS ? MAX_ELEMENTS : list->capacity * 2);
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->size];
    element->UEInfoTag = ueInfoTag;
    element->RNTI = rnti;
    element->CRCIndicationRel8.CRCFLAG = rand() % 2; // Random CRCFLAG.

    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void verify_list_integrity(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        // Implement integrity checks here.
        if (list->elements[i].CRCIndicationRel8.CRCFLAG < 0 || list->elements[i].CRCIndicationRel8.CRCFLAG > 1) {
            fprintf(stderr, "Integrity check failed at index %zu.\n", i);
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->elements) {
        free(list->elements);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
