    if (count < MAX_ENTRIES) {
        nfa_list[count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfa_list[count]) {
            nfa_list[count]->RNTI = rnti;
            nfa_list[count]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
