        }
    }

    pthread_mutex_unlock(&mutex);
}

// Function to filter entries based on age and sliding window criteria
void filter_entries(int age_limit, int max_window_count) {
    pthread_mutex_lock(&mutex);

    time_t now = time(NULL);
    for (int i = 0; i < count; ++i) {
        if ((now - nfa_list[i]->timestamp > age_limit)) {
            free(nfa_list[i]);
            memmove(&nfa_list[i], &nfa_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (count - i - 1));
            count--;
            i--; // Adjust index after removal
        }
    }

    pthread_mutex_unlock(&mutex);
}

// Batch process filtered entries with a background thread pool for heavy computations
void batch_process(void (*process_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_t threads[4];
    int chunk_size = count / 4;

    for (int i = 0; i < 4 && i * chunk_size < count; ++i) {
        if (pthread_create(&threads[i], NULL, (void*)process_func, (void*)(nfa_list + i * chunk_size))) {
            fprintf(stderr, "Error creating thread\n");
        }
    }

    for (int i = 0; i < 4 && i * chunk_size < count; ++i) {
        if (pthread_join(threads[i], NULL)) {
