// Thread-safe list management with mutex lock and CRC failure count
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

static Node* head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static int crc_failure_count = 0;
static int min_rx_ue_info_tag, max_rx_ue_info_tag, min_crc_flag, max_crc_flag;

// Load configuration for allowed tag ranges
void load_config_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d %d", &min_rx_ue_info_tag, &max_rx_ue_info_tag);
    fscanf(file, "%d %d", &min_crc_flag, &max_crc_flag);

    fclose(file);
}

// Validate and update CRC failure count
void validate_and_update_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG < min_crc_flag || 
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG > max_crc_flag) {
        crc_failure_count++;
    }
}

// Add or update PDU in the list
void add_or_update_pdu(int rnti, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_mutex);

    if (pdu->RX_UE_INFORMATION_TAG < min_rx_ue_info_tag || 
        pdu->RX_UE_INFORMATION_TAG > max_rx_ue_info_tag) {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data = *pdu;
            validate_and_update_crc(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        prev = current;
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    validate_and_update_crc(pdu);

    if (prev == NULL) {
        head = new_node;
    } else {
        prev->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Remove PDU by RNTI
void remove_pdu_by_rnti(int rnti) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list_mutex);
}

// Get total CRC failure count
int get_crc_failure_count() {
    pthread_mutex_lock(&list_mutex);
    int count = crc_failure_count;
    pthread_mutex_unlock(&list_mutex);
    return count;
}

// Initialize the list and load configuration
void init_list(const char* config_filename) {
    head = NULL;
    memset(&crc_failure_count, 0, sizeof(crc_failure_count));
    load_config_from_file(config_filename);
}
```

