['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_PDUS 10000
#define BATCH_SIZE 1000
#define MAX_OPERATION_TIME_MS 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char *CRC_INDICATION_REL8_TAG; // Dynamically allocated
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDUS];
    size_t count;
    pthread_mutex_t mutex;
    int service_status; // 0: stopped, 1: running
    int retry_count;
} PDU_Manager;

PDU_Manager manager = { .count = 0, .service_status = 0, .retry_count = 3 };

void initialize_manager() {
    pthread_mutex_init(&manager.mutex, NULL);
}

void shutdown_manager() {
    pthread_mutex_destroy(&manager.mutex);

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.pdus[i]->CRC_INDICATION_REL8_TAG);
        free(manager.pdus[i]);
    }
}

int process_pdu_batch(size_t batch_size) {
    if (batch_size == 0 || !manager.service_status) return 0;

    pthread_mutex_lock(&manager.mutex);

    size_t end = manager.count;
    if (end - batch_size > MAX_PDUS) end = MAX_PDUS;

    for (size_t i = manager.count - batch_size; i < end && manager.pdus[i]; ++i) {
        // Simulate UE-specific data handling
        int network_delay_ms = rand() % 100; // Simulate network delay variability

        if (network_delay_ms > MAX_OPERATION_TIME_MS) {
            printf("Network delay exceeded limits, retrying...\n");
            continue;
        }

        // Process PDU
        char crc_flag = manager.pdus[i]->RNTI & 1;

        // Log processing success
        printf("Processed PDU with RNTI: %u, CRC_FLAG: %c\n", 
               manager.pdus[i]->RNTI, crc_flag ? '1' : '0');

        free(manager.pdus[i]->CRC_INDICATION_REL8_TAG);
        free(manager.pdus[i]);
        manager.pdus[i] = NULL;
    }

    // Shift remaining elements
    for (size_t i = end - batch_size; i < manager.count; ++i) {
        manager.pdus[i - batch_size] = manager.pdus[i];
        manager.pdus[i] = NULL;
    }
    manager.count -= batch_size;

    pthread_mutex_unlock(&manager.mutex);

    return 1;
}

void add_pdu(int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    if (manager.count >= MAX_PDUS) return;

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate PDU");
        return;
    }

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;

    size_t buffer_size = rand() % 1024 + 1; // Simulate variable size
    pdu->CRC_INDICATION_REL8_TAG = malloc(buffer_size);
    if (!pdu->CRC_INDICATION_REL8_TAG) {
        perror("Failed to allocate CRC_INDICATION buffer");
        free(pdu);
        return;
    }

    pthread_mutex_lock(&manager.mutex);
    manager.pdus[manager.count++] = pdu;
    pthread_mutex_unlock(&manager.mutex);
}

void start_service() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, (void *(*)(void *))process_pdu_batch, (void *)BATCH_SIZE)) {
        perror("Failed to create processing thread");
        return;
    }

    manager.service_status = 1;
    printf("Service started\n");

    // Simulate service shutdown after some time
    sleep(10);
    manager.service_status = 0;

    pthread_join(thread_id, NULL);
    printf("Service stopped\n");
}

int main() {
    initialize_manager();

    start_service();

    for (int i = 0; i < 5000; ++i) { // Simulate adding PDUs
        add_pdu(i % 100, rand());
    }

    process_pdu_batch(0); // Final batch processing

    shutdown_manager();

    return 0;
}
```

