#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    uint64_t transaction_id;
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int status; // 1 for success, 0 for failure
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    size_t count;
    pthread_mutex_t lock;
    FILE* log_file;
} TransactionManager;

TransactionManager* init_transaction_manager(const char* log_filename) {
    TransactionManager* manager = malloc(sizeof(TransactionManager));
    if (!manager) return NULL;

    memset(manager, 0, sizeof(TransactionManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager);
        return NULL;
    }

    return manager;
}

void log_failed_transaction(TransactionManager* manager, Transaction tx) {
    pthread_mutex_lock(&manager->lock);
    fprintf(manager->log_file, "Failed Transaction: ID=%llu, Timestamp=%ld, Source=%s, Destination=%s\n",
            (unsigned long long)tx.transaction_id, tx.timestamp, tx.source_ip, tx.destination_ip);
    fflush(manager->log_file);
    pthread_mutex_unlock(&manager->lock);
}

void add_transaction(TransactionManager* manager, Transaction tx) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count < MAX_TRANSACTIONS) {
        manager->transactions[manager->count++] = tx;
    }

    if (tx.status == 0) { // Log failed transactions
        log_failed_transaction(manager, tx);
    }

    pthread_mutex_unlock(&manager->lock);
}

void shutdown_transaction_manager(TransactionManager* manager) {
    if (manager) {
        fclose(manager->log_file);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
```

### Key Points:

1. **Data Structure**: A `Transaction` struct holds transaction details, and a `TransactionManager` manages an array of transactions.

2. **Thread Safety**: Use `pthread_mutex_t` to ensure thread-safe access to shared resources like the transaction array and log file.

3. **Logging Mechanism**: Failed transactions are logged immediately with minimal impact on performance by using a separate mutex for logging operations, allowing potential future optimizations such as batch processing or asynchronous logging if required.

4. **Memory Management**: Memory usage is optimized through fixed-size arrays and careful management of resources (e.g., log files).

5. **Scalability Considerations**: The design allows adding more complex features, like dynamic resizing or integration with other systems, without significant refactoring.

This implementation provides a solid foundation for managing network transactions in a multi-threaded environment while ensuring efficient logging and resource management.']

