```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 50000

typedef struct {
    int TX_UE_INFORMATION_TAG;
    int RNTI;
    int SRS_TX_CONFIG_REL15_TAG_DELAY;
} NFAPI_SRS_TX_REQ_PDU_T;

typedef struct Node {
    NFAPI_SRS_TX_REQ_PDU_T data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
    size_t peak_memory;
    size_t failed_transmissions;
    pthread_mutex_t lock;
} SRSArray;

SRSArray* create_srs_array() {
    SRSArray *srs = (SRSArray*)malloc(sizeof(SRSArray));
    srs->head = NULL;
    srs->count = 0;
    srs->peak_memory = 0;
    srs->failed_transmissions = 0;
    pthread_mutex_init(&srs->lock, NULL);
    return srs;
}

void free_srs_array(SRSArray *srs) {
    Node *current = srs->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&srs->lock);
    free(srs);
}

int insert_srs_pdu(SRSArray *srs, NFAPI_SRS_TX_REQ_PDU_T pdu) {
    pthread_mutex_lock(&srs->lock);

    Node **tracer = &srs->head;
    while (*tracer && (*tracer)->data.RNTI < pdu.RNTI) {
        tracer = &(*tracer)->next;
    }

    if (*tracer && (*tracer)->data.RNTI == pdu.RNTI) {
        pthread_mutex_unlock(&srs->lock);
        return 0; // Duplicate RNTI
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = *tracer;

    *tracer = new_node;
    srs->count++;

    size_t current_memory_usage = sizeof(SRSArray) + srs->count * sizeof(Node);
    if (current_memory_usage > srs->peak_memory) {
        srs->peak_memory = current_memory_usage;
    }

    pthread_mutex_unlock(&srs->lock);

    return 1; // Success
}

int validate_pdu(NFAPI_SRS_TX_REQ_PDU_T pdu) {
    return pdu.TX_UE_INFORMATION_TAG != 0 && pdu.RNTI != 0 && pdu.SRS_TX_CONFIG_REL15_TAG_DELAY >= 0;
}

void transmit_pdu(SRSArray *srs, NFAPI_SRS_TX_REQ_PDU_T pdu) {
    pthread_mutex_lock(&srs->lock);

    if (!validate_pdu(pdu)) {
        srs->failed_transmissions++;
        pthread_mutex_unlock(&srs->lock);
        return;
    }

    Node **tracer = &srs->head;
    while (*tracer && (*tracer)->data.RNTI != pdu.RNTI) {
        tracer = &(*tracer)->next;
    }

    if (*tracer) {
        free(*tracer); // Simulate transmission
        *tracer = (*tracer)->next;
        srs->count--;
    }

    pthread_mutex_unlock(&srs->lock);
}

void print_statistics(SRSArray *srs) {
    printf("Total Elements: %zu\n", srs->count);
    printf("Failed Transmissions: %zu\n", srs->failed_transmissions);
    printf("Peak Memory Usage: %zu bytes\n", srs->peak_memory);
}

// Unit tests
void test_srs_array() {
    SRSArray *srs = create_srs_array();

    NFAPI_SRS_TX_REQ_PDU_T pdu1 = {1, 1001, 10};
    insert_srs_pdu(srs, pdu1);

    NFAPI_SRS_TX_REQ_PDU_T pdu2 = {2, 1002, 20};
    insert_srs_pdu(srs, pdu2);

    // Test duplicate RNTI
    NFAPI_SRS_TX_REQ_PDU_T pdu3 = {3, 1001, 30};
    insert_srs_pdu(srs, pdu3); // Should fail

    // Test invalid PDU
    NFAPI_SRS_TX_REQ_PDU_T pdu4 = {0, 0, -1}; // Invalid
    transmit_pdu(srs, pdu4);

    print_statistics(srs);

    free_srs_array(srs);
}

int main() {
    test_srs_array();
    return 0;
}
```

### Explanation:

- **Data Structure**: A linked list is used to maintain sorted order based on `RNTI`. This allows for efficient insertion while keeping the list ordered.

- **Thread Safety**: The `pthread_mutex_t` lock ensures that operations on the array are thread-safe.

- **Memory Management**: Memory usage is tracked, and peak memory consumption is recorded. Nodes are freed upon successful transmission to simulate resource release.

- **Validation**: A function checks if a PDU configuration is valid before attempting transmission.

- **Statistics**: The system tracks failed transmissions and prints statistics on resource usage.

- **Unit Tests**: Basic tests validate insertion, handling of duplicate RNTIs, and invalid configurations. More comprehensive testing should be done in practice to cover edge cases and high-load scenarios.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUEUE_LENGTH 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG_CRCFLAG;
    time_t timestamp; // For duplicate handling based on time
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    int failed_crc_count;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* init_dynamic_array(size_t initial_capacity);
int add_pdu(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *pdu);
void free_dynamic_array(DynamicArray *array);
static int compare_rnti(const void *a, const void *b);
static size_t find_index_by_rnti(NFAPI_CRC_INDICATION_PDU_T *data, size_t size, int rnti);

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    array->failed_crc_count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int add_pdu(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pthread_mutex_lock(&array->lock) != 0) return -1;

    // Backpressure mechanism
    while (array->size >= MAX_QUEUE_LENGTH && pthread_mutex_unlock(&array->lock) == 0) {
        usleep(1000); // Wait and retry
        if (pthread_mutex_lock(&array->lock) != 0) return -1;
    }

    size_t index = find_index_by_rnti(array->data, array->size, pdu->RNTI);
    if (index < array->size && difftime(pdu->timestamp, array->data[index].timestamp) < 5.0) {
        // Update existing entry
        array->data[index] = *pdu;
    } else {
        // Check for capacity and resize if needed
        if (array->size >= array->capacity) {
            size_t new_capacity = array->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_data) {
                pthread_mutex_unlock(&array->lock);
                return -1; // Memory allocation failure
            }
            array->data = new_data;
            array->capacity = new_capacity;
        }

        // Insert the new PDU in sorted order
        memmove(array->data + index + 1, array->data + index, (array->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(array->data + index, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->size++;
    }

    // Check CRC flag
    if (pdu->CRC_INDICATION_REL8_TAG_CRCFLAG != 1) { // Assuming 1 is the valid value for demonstration
        array->failed_crc_count++;
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *array) {
    if (pthread_mutex_lock(&array->lock) == 0) {
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

static int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pdu_a->RNTI - pdu_b->RNTI;
}

static size_t find_index_by_rnti(NFAPI_CRC_INDICATION_PDU_T *data, size_t size, int rnti) {
    size_t low = 0, high = size;
    while (low < high) {
        size_t mid = (low + high) / 2;
        if (data[mid].RNTI < rnti)
            low = mid + 1;
        else
            high = mid;
    }
    return low;
}

int main() {
    DynamicArray *array = init_dynamic_array(10);
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    for (int i = 0; i < 20; i++) {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 100;
        pdu.CRC_INDICATION_REL8_TAG_CRCFLAG = rand() % 2;
        pdu.timestamp = time(NULL);

        if (add_pdu(array, &pdu) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
        }
    }

    printf("Number of failed CRC validations: %d\n", array->failed_crc_count);
    free_dynamic_array(array);
    return EXIT_SUCCESS;
}
```

This code implements a dynamic array management system for `NFAPI_CRC_INDICATION_PDU_T` structures, addressing the specified engineering challenges. It includes thread safety, backpressure mechanism, memory efficiency, duplicate handling, and performance optimizations.']

