typedef struct {
    NetworkEventLogEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    void (*on_capacity_reached)(void);
} EventLog;

EventLog* initialize_event_log(size_t initial_capacity, void (*callback)(void)) {
    EventLog *log = (EventLog*)malloc(sizeof(EventLog));
    if (!log) return NULL;

    log->entries = (NetworkEventLogEntry*)malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    if (!log->entries) {
        free(log);
        return NULL;
    }

    log->count = 0;
    log->capacity = initial_capacity;
    pthread_mutex_init(&log->lock, NULL);
    log->on_capacity_reached = callback;

    return log;
}

void resize_event_log(EventLog *log) {
    size_t new_capacity = log->capacity * 2;
    NetworkEventLogEntry *new_entries = (NetworkEventLogEntry*)realloc(log->entries, new_capacity * sizeof(NetworkEventLogEntry));

    if (!new_entries) return;

    log->entries = new_entries;
    log->capacity = new_capacity;
}

void add_log_entry(EventLog *log, const char* event_id, const char* description, const char* event_type) {
    pthread_mutex_lock(&log->lock);

    if (log->count >= log->capacity) {
        resize_event_log(log);
        if (log->on_capacity_reached) log->on_capacity_reached();
    }

    NetworkEventLogEntry *entry = &log->entries[log->count++];
    entry->timestamp = time(NULL);
    strncpy(entry->event_id, event_id, sizeof(entry->event_id));
    strncpy(entry->description, description, sizeof(entry->description));
    strncpy(entry->event_type, event_type, sizeof(entry->event_type));

    pthread_mutex_unlock(&log->lock);
}

void filter_and_send_logs(EventLog *log, const char* type_filter) {
    for (size_t i = 0; i < log->count; ++i) {
        if (strcmp(log->entries[i].event_type, type_filter) == 0) {
            // Simulate sending to external processor
            printf("Sending event ID: %s\n", log->entries[i].event_id);
        }
    }
}

void prune_old_entries(EventLog *log, size_t max_size) {
    if (log->count <= max_size) return;

    for (size_t i = 0; i < log->count - max_size; ++i) {
        // Prune logic: move last elements to the beginning
        log->entries[i] = log->entries[--log->count];
    }
}

void cleanup_event_log(EventLog *log) {
    pthread_mutex_destroy(&log->lock);
    free(log->entries);
    free(log);
}

int main() {
    EventLog *log = initialize_event_log(100, [](){ printf("Capacity reached!\n"); });

    add_log_entry(log, "E1234", "Connection established", "INFO");
    filter_and_send_logs(log, "INFO");

    prune_old_entries(log, 50);
    cleanup_event_log(log);

    return 0;
}
