typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    arr->array = calloc(arr->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    free(arr->array);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);

    free(arr);
}

static void resize_if_needed(DynamicArray *arr) {
    if (arr->size < arr->capacity) return;

    size_t new_capacity = arr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) {
        // Handle reallocation failure gracefully
        pthread_mutex_unlock(&arr->lock);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    arr->array = new_array;
    arr->capacity = new_capacity;
}

void insert(NFAPI_CRC_INDICATION_PDU_T pdu, DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    resize_if_needed(arr);

    arr->array[arr->size] = pdu;
    arr->size++;

    pthread_mutex_unlock(&arr->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve(DynamicArray *arr, size_t index) {
    if (index >= arr->size) return NULL;

    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &arr->array[index];
    pthread_mutex_unlock(&arr->lock);

    return pdu;
}

void delete(DynamicArray *arr, size_t index) {
    if (index >= arr->size) return;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = index; i < arr->size - 1; ++i) {
        arr->array[i] = arr->array[i + 1];
    }

    arr->size--;

    pthread_mutex_unlock(&arr->lock);
}

