#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint64_t UEID;
    char RRC_STATE[16];
    struct MeasurementReport* reports;
    size_t report_count;
} UEContext;

typedef struct {
    int MEASUREMENT_ID;
    float SINR;
    int8_t RSRP;
} MeasurementReport;

// Define a node for the lock-free queue
typedef struct Node {
    UEContext context;
    struct Node* next;
} Node;

#define QUEUE_SIZE 1024

// Lock-free queue structure using Michael-Scott algorithm
typedef struct {
    volatile Node* head;
    volatile Node* tail;
    pthread_mutex_t mutex; // Fallback for complex operations that cannot be lock-free
} LockFreeQueue;

LockFreeQueue queue = {NULL, NULL};

void init_lock_free_queue(LockFreeQueue* q) {
    Node* dummy = malloc(sizeof(Node));
    if (!dummy) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    dummy->next = NULL;
    pthread_mutex_init(&q->mutex, NULL);
    __atomic_store_n(&(q->head), dummy, __ATOMIC_RELEASE);
    __atomic_store_n(&(q->tail), dummy, __ATOMIC_RELEASE);
}

int enqueue(LockFreeQueue* q, UEContext context) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        return -1;
    }
    new_node->context = context;
    new_node->next = NULL;

    Node* tail;
    Node* next;

    do {
        tail = __atomic_load_n(&(q->tail), __ATOMIC_ACQUIRE);
        next = __atomic_load_n(&tail->next, __ATOMIC_ACQUIRE);

        if (tail == __atomic_load_n(&(q->tail), __ATOMIC_acquire)) {
            if (next == NULL) { // Tail is the last node
                if (__atomic_compare_exchange_n(&tail->next, &next, new_node,
                                                false, __ATOMIC_release, __ATOMIC_relaxed)) {
                    __atomic_store_n(&(q->tail), new_node, __ATOMIC_release);
                    return 0;
                }
            } else { // Tail is not the last node
                __atomic_compare_exchange_n(&(q->tail), &tail, next,
                                            false, __ATOMIC_relaxed, __ATOMIC_relaxed);
            }
        }

    } while (1);

    free(new_node); // In case of failure
    return -1;
}

UEContext dequeue(LockFreeQueue* q) {
    Node* head;
    Node* tail;
    Node* next;

    do {
        head = __atomic_load_n(&(q->head), __ATOMIC_acquire);
        tail = __atomic_load_n(&(q->tail), __ATOMIC_acquire);
        next = __atomic_load_n(&head->next, __ATOMIC_acquire);

        if (head == __atomic_load_n(&(q->head), __ATOMIC_acquire)) {
            if (head == tail) { // Queue is empty
                if (next == NULL) {
                    return (UEContext){0}; // Empty context on failure to dequeue
                }
                __atomic_compare_exchange_n(&(q->tail), &tail, next,
                                            false, __ATOMIC_relaxed, __ATOMIC_relaxed);
            } else { // Queue is not empty
                UEContext context = next->context;
                if (__atomic_compare_exchange_n(&(q->head), &head, next,
                                                false, __ATOMIC_release, __ATOMIC_relaxed)) {
                    free(head); // Free the old dummy node
                    return context;
                }
            }
        }

    } while (1);
}

void serialize_data_to_file(LockFreeQueue* q, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    Node* current = __atomic_load_n(&(q->head), __ATOMIC_acquire);
    while (current != __atomic_load_n(&(q->tail), __ATOMIC_acquire)) {
        UEContext context = current->context;
        fwrite(&context.UEID, sizeof(context.UEID), 1, file);
        fwrite(context.RRC_STATE, sizeof(context.RRC_STATE), 1, file);

        for (size_t i = 0; i < context.report_count; ++i) {
            MeasurementReport report = context.reports[i];
            int16_t meas_id = htonl(report.MEASUREMENT_ID);
            fwrite(&meas_id, sizeof(meas_id), 1, file);
            float sinr = htonf(report.SINR); // Custom function to handle float
            fwrite(&sinr, sizeof(sinr), 1, file);
            int8_t rsrp = report.RSRP;
            fwrite(&rsrp, sizeof(rsrp), 1, file);
        }

