<?php

class ConfigManager {
    private $environment;
    private $settings;

    public function __construct() {
        $this->detectEnvironment();
        $this->loadSettings();
    }

    private function detectEnvironment() {
        if (getenv('APP_ENV')) {
            $this->environment = getenv('APP_ENV');
        } else {
            // Default or detect from server metadata
            $this->environment = 'development';
        }
    }

    private function loadSettings() {
        $cacheFile = __DIR__ . '/config_cache.json';

        if (file_exists($cacheFile) && filemtime($cacheFile) > (time() - 3600)) {
            $this->settings = json_decode(file_get_contents($cacheFile), true);
        } else {
            $apiUrl = 'https://api.example.com/config/' . $this->environment;
            $response = file_get_contents($apiUrl);

            if ($response === FALSE) {
                error_log("Failed to fetch settings from API");
                // Handle gracefully
                return;
            }

            $this->settings = json_decode($response, true);
            file_put_contents($cacheFile, json_encode($this->settings));
        }
    }

    public function validateSettings() {
        if ($this->environment === 'development') {
            if (empty($this->settings['db_host'])) {
                throw new Exception("DB_HOST is required in development");
            }
        } else {
            // Log warnings
            error_log("Missing optional settings for non-development environment.");
        }
    }

    public function getSetting($key) {
        return $this->settings[$key] ?? null;
    }
}

