typedef struct Node {
    LTE_PHY_RX_BUFFER_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
}

int addElement(LinkedList* list, LTE_PHY_RX_BUFFER_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    newNode->pdu = pdu;
    newNode->next = list->head;
    list->head = newNode;

    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int removeElement(LinkedList* list, size_t index) {
    if (index >= list->size) return -1; // Index out of bounds

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    for (size_t i = 0; i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) { // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

LTE_PHY_RX_BUFFER_PDU_T* getElement(LinkedList* list, size_t index) {
    if (index >= list->size) return NULL; // Index out of bounds

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    LTE_PHY_RX_BUFFER_PDU_T* pdu = &current->pdu;

    pthread_mutex_unlock(&list->lock);

    return pdu;
}

void destroyLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

