unsigned int calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *array, size_t array_size) {
    unsigned int checksum = 0;
    for(size_t i = 0; i < array_size; ++i) {
        checksum += array[i].rnti; // Simplified checksum calculation
    }
    return checksum;
}

// Validate checksum (dummy implementation)
int validate_checksum(unsigned int expected_checksum, NFAPI_CRC_INDICATION_PDU_T *array, size_t array_size) {
    unsigned int current_checksum = calculate_checksum(array, array_size);
    return current_checksum == expected_checksum;
