// Function prototypes
void initialize_array(size_t initial_capacity);
void add_entry(NFAPI_CRC_INDICATION_PDU_T entry);
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(int rnti);
int remove_entry_by_index(size_t index);

// Initialize the dynamic array with a specified capacity
void initialize_array(size_t initial_capacity) {
    pthread_mutex_lock(&lock);

    if (array != NULL) {
        free(array);
    }

    array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed during initialization.");
        exit(EXIT_FAILURE); // Halt operations
    }

    array_size = 0;

    pthread_mutex_unlock(&lock);
}

// Add a new entry to the dynamic array
void add_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&lock);

    if (array == NULL) {
        initialize_array(10); // Start with an initial capacity
    }

    if (array_size >= sizeof(array) / sizeof(array[0])) {
        size_t new_capacity = array_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            log_error("Memory allocation failed while adding a new entry.");
            pthread_mutex_unlock(&lock);
            exit(EXIT_FAILURE); // Halt operations
        }

        array = new_array;
    }

    array[array_size++] = entry;

    unsigned int checksum = calculate_checksum(array, array_size);

    if (!validate_checksum(checksum, array, array_size)) {
        log_error("Checksum validation failed after adding an entry.");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE); // Halt operations
    }

    pthread_mutex_unlock(&lock);
}

// Retrieve an entry by RNTI
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(int rnti) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < array_size; ++i) {
        if (array[i].rnti == rnti) {
            pthread_mutex_unlock(&lock);
            return &array[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Remove an entry by index
int remove_entry_by_index(size_t index) {
    pthread_mutex_lock(&lock);

    if (index >= array_size) {
        pthread_mutex_unlock(&lock);
        log_error("Invalid index for removal.");
        return -1; // Indicate failure
    }

    memmove(&array[index], &array[index + 1], (--array_size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    unsigned int checksum = calculate_checksum(array, array_size);

    if (!validate_checksum(checksum, array, array_size)) {
        log_error("Checksum validation failed after removing an entry.");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE); // Halt operations
    }

    pthread_mutex_unlock(&lock);
    return 0; // Indicate success
}
