typedef struct {
    int Status;
    int Duration;
} EventDetails;

typedef struct {
    time_t Timestamp;
    char EventType[50];
    EventDetails EventDetails;
} NetworkEvent;

#define MAX_EVENTS 1000000
NetworkEvent events[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Mock function to simulate API call for retrieving Timestamp and EventType
void fetchEventDataFromAPI(time_t *timestamp, char *event_type) {
    // Simulate network delay and random failure
    int simulated_failure = rand() % 10;
    if (simulated_failure < 2) { // 20% chance of failure
        fprintf(stderr, "Network error: API call failed.\n");
        exit(EXIT_FAILURE);
    }

    *timestamp = time(NULL); // Get current timestamp as example
    snprintf(event_type, sizeof(*event_type), "EventType_%d", rand() % 10);
}

// Exponential backoff function for retrying network calls
void fetchWithRetry(time_t *timestamp, char *event_type) {
    int retries = 0;
    while (retries < 5) {
        try {
            fetchEventDataFromAPI(timestamp, event_type);
            return;
        } catch (...) {
            retries++;
            sleep((1 << retries)); // Exponential backoff: 1s, 2s, 4s, etc.
        }
    }
    fprintf(stderr, "Failed to retrieve data after multiple attempts.\n");
    exit(EXIT_FAILURE);
}

// Thread-safe function to initialize and populate NetworkEvents
void initializeNetworkEvents() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_EVENTS && event_count < MAX_EVENTS; i++) {
        time_t timestamp;
        char event_type[50];

        fetchWithRetry(&timestamp, event_type);

        events[event_count].Timestamp = timestamp;
        strncpy(events[event_count].EventType, event_type, sizeof(events[event_count].EventType) - 1);

        // Randomly generate Status and Duration
        events[event_count].EventDetails.Status = rand() % 1000;
        events[event_count].EventDetails.Duration = rand() % 60;

        event_count++;
    }

    pthread_mutex_unlock(&mutex);
}

// Comparison function for sorting based on Timestamp
int compareNetworkEvents(const void *a, const void *b) {
    NetworkEvent *eventA = (NetworkEvent *) a;
    NetworkEvent *eventB = (NetworkEvent *) b;

    return (eventA->Timestamp > eventB->Timestamp) - (eventA->Timestamp < eventB->Timestamp);
}

// Function to sort events by Timestamp
void sortNetworkEvents() {
    pthread_mutex_lock(&mutex);

    qsort(events, event_count, sizeof(NetworkEvent), compareNetworkEvents);

    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    initializeNetworkEvents();
    sortNetworkEvents();

    // Example output of sorted events
    for (int i = 0; i < event_count && i < 10; i++) { // Display first 10 events
        printf("Timestamp: %ld, EventType: %s, Status: %d, Duration: %d\n",
               events[i].Timestamp,
               events[i].EventType,
               events[i].EventDetails.Status,
               events[i].EventDetails.Duration);
    }

    return 0;
}
