// Function to generate a random CRCFLAG
uint8_t generate_crcflag() {
    if (!cache_initialized) {
        pthread_mutex_lock(&cache_lock);
        if (!cache_initialized) { // Double-check locking pattern
            for (int i = 0; i < CACHE_SIZE; ++i) {
                crc_cache[i].CRCFLAG = rand() % 256;
            }
            cache_initialized = 1;
        }
        pthread_mutex_unlock(&cache_lock);
    }

