// Dynamic array for managing session states
typedef struct {
    UESessionState **sessions;
    size_t count;
    pthread_mutex_t lock; // For synchronization
} SessionManager;

// Function prototypes
void initialize_session_manager(SessionManager *manager);
void add_session(SessionManager *manager, UESessionState *session);
void remove_session(SessionManager *manager, int ueId);
void update_allocation_status(SessionManager *manager, int ueId, struct RadioResourceBlock *new_allocations, size_t count);
void synchronize_with_nms(SessionManager *manager);

// Helper functions
static void log_performance_metrics();
static void exponential_backoff_retry(void (*func)(SessionManager *), SessionManager *manager);

// Implementation of the session manager functions
void initialize_session_manager(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->sessions = NULL;
    manager->count = 0;
}

void add_session(SessionManager *manager, UESessionState *session) {
    pthread_mutex_lock(&manager->lock);

    // Allocate memory for new sessions array
    UESessionState **new_sessions = realloc(manager->sessions, (manager->count + 1) * sizeof(UESessionState *));
    if (!new_sessions) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Add the new session
    manager->sessions = new_sessions;
    manager->sessions[manager->count] = session;

    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    // Log performance metrics after adding a session
    log_performance_metrics();
}

void remove_session(SessionManager *manager, int ueId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->ueId == ueId) {
            free(manager->sessions[i]);

            // Shift the remaining sessions
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(UESessionState *));
            manager->count--;

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_allocation_status(SessionManager *manager, int ueId, struct RadioResourceBlock *new_allocations, size_t count) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->ueId == ueId) {
            // Free old allocations
            free(manager->sessions[i]->allocations);

            // Allocate memory for new allocations
            manager->sessions[i]->allocations = malloc(count * sizeof(struct RadioResourceBlock *));
            if (!manager->sessions[i]->allocations) {
                perror("Failed to allocate memory");
                pthread_mutex_unlock(&manager->lock);
                return;
            }

            // Copy new allocations
            memcpy(manager->sessions[i]->allocations, new_allocations, count * sizeof(struct RadioResourceBlock *));
            manager->sessions[i]->allocation_count = count;

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void synchronize_with_nms(SessionManager *manager) {
    exponential_backoff_retry(synchronize_with_nms_helper, manager);
}

