    int retries = 0;
    const int max_retries = 5;

    while (retries < max_retries) {
        if ((*func)(manager)) {
            return; // Synchronization successful
        }

        // Exponential backoff strategy
        time_t delay = 1 << retries;
        printf("Synchronization failed, retrying in %ld seconds...\n", delay);
        sleep(delay);

        retries++;
    }

    fprintf(stderr, "Failed to synchronize with NMS after %d attempts.\n", max_retries);
}

