typedef struct DynamicArray {
    UESessionState **array;
    size_t size;
    size_t capacity;
} DynamicArray;

// Function prototypes
void initDynamicArray(DynamicArray *da);
int resizeDynamicArray(DynamicArray *da, size_t new_capacity);
int addSessionState(DynamicArray *da, UESessionState *session);
int removeSessionState(DynamicArray *da, unsigned long ueId);
UESessionState* findSessionStateById(DynamicArray *da, unsigned long ueId);
void freeDynamicArray(DynamicArray *da);

// Initialize a dynamic array
void initDynamicArray(DynamicArray *da) {
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
}

int resizeDynamicArray(DynamicArray *da, size_t new_capacity) {
    UESessionState **new_array = realloc(da->array, new_capacity * sizeof(UESessionState *));
    if (new_array == NULL) {
        return -1; // Allocation failed
    }
    da->capacity = new_capacity;
    da->array = new_array;
    return 0;
}

int addSessionState(DynamicArray *da, UESessionState *session) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 1 : da->capacity * 2;
        if (resizeDynamicArray(da, new_capacity)) {
            return -1; // Resize failed
        }
    }
    da->array[da->size++] = session;
    return 0;
}

int removeSessionState(DynamicArray *da, unsigned long ueId) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i]->ueId == ueId) {
            free(da->array[i]);
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(UESessionState *));
            da->size--;
            return 0;
        }
    }
    return -1; // Not found
}

UESessionState* findSessionStateById(DynamicArray *da, unsigned long ueId) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i]->ueId == ueId) {
            return da->array[i];
        }
    }
    return NULL;
}

void freeDynamicArray(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i]->rrb_allocations);
        free(da->array[i]->crc_indications);
        free(da->array[i]);
    }
    free(da->array);
}

