import threading
from collections import defaultdict
from typing import Dict

class NFAPI_CRC_INDICATION_PDU_T:
    # Placeholder class definition for NFAPI_CRC_INDICATION_PDU_T
    def __init__(self, data):
        self.data = data

    def __hash__(self):
        return hash(self.data)

    def __eq__(self, other):
        return isinstance(other, NFAPI_CRC_INDICATION_PDU_T) and self.data == other.data

class DynamicListManager:
    def __init__(self, initial_capacity: int = 16, load_factor: float = 0.75):
        self.lock = threading.RLock()
        self.table: Dict[int, list] = defaultdict(list)
        self.size = 0
        self.capacity = initial_capacity
        self.load_factor = load_factor

    def _hash(self, pdu: NFAPI_CRC_INDICATION_PDU_T) -> int:
        return hash(pdu) % self.capacity

    def _resize(self):
        with self.lock:
            old_table = self.table
            self.capacity *= 2
            self.table.clear()

            for bucket in old_table.values():
                for pdu in bucket:
                    index = self._hash(pdu)
                    self.table[index].append(pdu)

    def add_pdu(self, pdu: NFAPI_CRC_INDICATION_PDU_T) -> int:
        if not isinstance(pdu, NFAPI_CRC_INDICATION_PDU_T):
            return -1

        with self.lock:
            index = self._hash(pdu)

            # Check for duplicate
            for existing_pdu in self.table[index]:
                if pdu == existing_pdu:
                    return 0

            self.table[index].append(pdu)
            self.size += 1

            # Resize if load factor exceeded
            if self.size / self.capacity > self.load_factor:
                self._resize()

        return 1

    def get_count(self) -> int:
        with self.lock:
            return self.size

# Example usage:
