#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    uint32_t TX_STREAM_ID;
    uint16_t SEQUENCE_NUMBER;
    size_t DATA_LENGTH;
    time_t timestamp;
} TX_PACKET_INFO;

typedef struct CacheNode {
    TX_PACKET_INFO packet_info;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode** buckets;
    pthread_rwlock_t lock;
} PacketCache;

uint32_t hash_function(uint32_t stream_id, uint16_t sequence_number) {
    return (stream_id ^ ((uint64_t)sequence_number << 32)) % HASH_TABLE_SIZE;
}

PacketCache* create_cache() {
    PacketCache* cache = malloc(sizeof(PacketCache));
    if (!cache) return NULL;

    cache->buckets = calloc(HASH_TABLE_SIZE, sizeof(CacheNode*));
    if (!cache->buckets) {
        free(cache);
        return NULL;
    }

    pthread_rwlock_init(&cache->lock, NULL);
    return cache;
}

int add_packet(PacketCache* cache, TX_PACKET_INFO packet_info) {
    uint32_t index = hash_function(packet_info.TX_STREAM_ID, packet_info.SEQUENCE_NUMBER);

    pthread_rwlock_wrlock(&cache->lock);
    CacheNode* node = cache->buckets[index];
    while (node) {
        if (node->packet_info.TX_STREAM_ID == packet_info.TX_STREAM_ID &&
            node->packet_info.SEQUENCE_NUMBER == packet_info.SEQUENCE_NUMBER) {
            pthread_rwlock_unlock(&cache->lock);
            return 0; // Packet already exists
        }
        node = node->next;
    }

    CacheNode* new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_rwlock_unlock(&cache->lock);
        return -1; // Memory allocation failure
    }

    new_node->packet_info = packet_info;
    new_node->next = cache->buckets[index];
    cache->buckets[index] = new_node;

    pthread_rwlock_unlock(&cache->lock);
    return 1; // Packet added successfully
}

TX_PACKET_INFO* get_packet(PacketCache* cache, uint32_t stream_id, uint16_t sequence_number) {
    uint32_t index = hash_function(stream_id, sequence_number);

    pthread_rwlock_rdlock(&cache->lock);
    CacheNode* node = cache->buckets[index];
    while (node) {
        if (node->packet_info.TX_STREAM_ID == stream_id &&
            node->packet_info.SEQUENCE_NUMBER == sequence_number) {
            pthread_rwlock_unlock(&cache->lock);
            return &node->packet_info;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&cache->lock);
    return NULL; // Packet not found
}

void free_cache(PacketCache* cache) {
    if (!cache) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        CacheNode* node = cache->buckets[i];
        while (node) {
            CacheNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    pthread_rwlock_destroy(&cache->lock);
    free(cache->buckets);
    free(cache);
}

// Logging and monitoring example
void log_packet_addition(const TX_PACKET_INFO* packet_info, int success) {
    printf("Packet Add: Stream ID %u, Seq Num %u, Length %zu, Success %d\n",
           packet_info->TX_STREAM_ID, packet_info->SEQUENCE_NUMBER,
           packet_info->DATA_LENGTH, success);
}

// Example usage
int main() {
    PacketCache* cache = create_cache();
    if (!cache) {
        fprintf(stderr, "Failed to create packet cache.\n");
        return 1;
    }

    TX_PACKET_INFO packet = { .TX_STREAM_ID = 1, .SEQUENCE_NUMBER = 100, .DATA_LENGTH = 1024 };
    packet.timestamp = time(NULL);

    int result = add_packet(cache, packet);
    log_packet_addition(&packet, result);

    TX_PACKET_INFO* retrieved_packet = get_packet(cache, 1, 100);
    if (retrieved_packet) {
        printf("Retrieved Packet: Stream ID %u, Seq Num %u, Length %zu\n",
               retrieved_packet->TX_STREAM_ID,
               retrieved_packet->SEQUENCE_NUMBER,
               retrieved_packet->DATA_LENGTH);
    } else {
        printf("Packet not found.\n");
    }

    free_cache(cache);
    return 0;
}
```

