#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MEMORY_LIMIT (50 * 1024 * 1024) // 50 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom allocator structures
typedef struct MemoryBlock {
    size_t size;
    void *ptr;
    int is_free;
    struct MemoryBlock *next;
} MemoryBlock;

static MemoryBlock *free_list = NULL;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void* custom_alloc(size_t size);
void custom_free(void *ptr);
void initialize_allocator();
void defragment_memory();

// NFAPI_CRC_INDICATION_PDU_T list management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    int count;
    pthread_mutex_t lock;
} NFList;

NFList* create_list() {
    NFList *list = (NFList *)custom_alloc(sizeof(NFList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)custom_alloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_element(NFList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        printf("Maximum number of elements reached.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    unsigned short last_rnti = 0;
    NFAPI_CRC_INDICATION_PDU_T *new_element;

    for (;;) {
        new_element = &list->elements[list->count];

        do {
            new_element->RX_UE_INFORMATION_TAG = rand();
            new_element->RNTI = (unsigned short)(rand() % 65535 + 1);
            new_element->CRC_INDICATION_REL8_TAG = rand() % 256;
            new_element->CRCFLAG = rand() % 2;
            new_element->timestamp = time(NULL);
        } while (new_element->RNTI == last_rnti && list->count > 0);

        if (1 <= new_element->RNTI && new_element->RNTI <= 65535) {
            break;
        } else {
            printf("Invalid RNTI value generated: %u\n", new_element->RNTI);
        }
    }

    last_rnti = new_element->RNTI;

    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void destroy_list(NFList *list) {
    pthread_mutex_lock(&list->lock);
    custom_free(list->elements);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    custom_free(list);
}

void initialize_allocator() {
    // Initialize memory block list
    free_list = (MemoryBlock *)custom_alloc(sizeof(MemoryBlock));
    free_list->size = MEMORY_LIMIT;
    free_list->ptr = malloc(free_list->size);
    free_list->is_free = 1;
    free_list->next = NULL;
}

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&memory_lock);

    MemoryBlock *current = free_list;
    while (current != NULL) {
        if (current->is_free && current->size >= size) {
            // Split block if necessary
            if ((current->size - size) > sizeof(MemoryBlock)) {
                MemoryBlock *new_block = (MemoryBlock *)((char *)current->ptr + size);
                new_block->size = current->size - size;
                new_block->is_free = 1;
                new_block->next = current->next;

                current->size = size;
                current->next = new_block;
            }

            current->is_free = 0;
            pthread_mutex_unlock(&memory_lock);
            return current->ptr;
        }
        current = current->next;
    }

    // Handle out of memory
    printf("Out of memory!\n");
    pthread_mutex_unlock(&memory_lock);
    return NULL;
}

void custom_free(void *ptr) {
    if (ptr == NULL) return;

    pthread_mutex_lock(&memory_lock);

    MemoryBlock *current = free_list;
    while (current != NULL && current->ptr != ptr)
        current = current->next;

    if (current != NULL) {
        current->is_free = 1;
    }

    // Optional: Defragment memory when needed
    defragment_memory();

    pthread_mutex_unlock(&memory_lock);
}

void defragment_memory() {
    MemoryBlock *current = free_list, *prev = NULL;

    while (current != NULL && current->next != NULL) {
        if (current->is_free && current->next->is_free) {
            // Merge adjacent free blocks
            current->size += current->next->size;
            current->next = current->next->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    // Additional defragmentation strategies can be implemented here
}

int main() {
    initialize_allocator();

    NFList *list = create_list();

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        add_element(list);
    }

    destroy_list(list);

    return 0;
}
