['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} ThreadSafeList;

ThreadSafeList list = { .head = NULL, .tail = NULL, .count = 0,
                        .lock = PTHREAD_MUTEX_INITIALIZER, 
                        .cond_var = PTHREAD_COND_INITIALIZER };

void initialize_list(ThreadSafeList* lst) {
    lst->head = NULL;
    lst->tail = NULL;
    lst->count = 0;
}

int is_full(const ThreadSafeList* lst) {
    return lst->count >= MAX_SIZE;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(ThreadSafeList* lst, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lst->lock);

    if (is_full(lst)) {
        Node* temp = lst->head;
        lst->head = lst->head->next;
        free(temp);
        lst->count--;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&lst->lock);
        return;
    }

    if (lst->tail) {
        lst->tail->next = new_node;
        lst->tail = new_node;
    } else {
        lst->head = lst->tail = new_node;
    }

    lst->count++;
    pthread_cond_signal(&lst->cond_var);
    pthread_mutex_unlock(&lst->lock);
}

void clear_list(ThreadSafeList* lst) {
    pthread_mutex_lock(&lst->lock);

    Node* current = lst->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    lst->head = NULL;
    lst->tail = NULL;
    lst->count = 0;

    pthread_mutex_unlock(&lst->lock);
}

void destroy_list(ThreadSafeList* lst) {
    clear_list(lst);
    pthread_mutex_destroy(&lst->lock);
    pthread_cond_destroy(&lst->cond_var);
}

