                pdu.rxUeInformationTag.id = rng.GenerateRandomInt();
                pdu.rnti.value = static_cast<uint16_t>(rng.GenerateRandomInt());
                pdu.crcIndicationRel8Tag.CRCFLAG = (rng.GenerateRandomFloatInclusive() > 0.5f);

                indications.push_back(pdu);
            }
        }

        verifyStructures();
    }

    void resizeAndRepopulate(size_t newCount, RandomValueGenerator& rng) {
        std::lock_guard<std::mutex> lock(mtx);
        if (newCount > 10000) throw std::out_of_range("Requested size exceeds the maximum allowed.");

        indications.clear();
        indications.reserve(newCount);

        for (size_t i = 0; i < newCount; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rxUeInformationTag.id = rng.GenerateRandomInt();
            pdu.rnti.value = static_cast<uint16_t>(rng.GenerateRandomInt());
