}

int is_duplicate(LinkedList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 1; // Duplicate found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // No duplicate
}

void log_operation(const char* operation, unsigned int rnti) {
