    }
}

void add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->size >= MAX_ELEMENTS) return;

    if (is_duplicate(list, entry.rnti)) return;

    pthread_mutex_lock(&list->lock);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure
    }
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_operation("Added", entry.rnti);

    pthread_mutex_unlock(&list->lock);
}

