        current->data.ue_info.rnti = rand() % MAX_ELEMENTS;
        current->data.crc_tag.CRCFLAG = rand() & 1; // Random CRC flag
        log_operation("Refreshed", current->data.rnti);
        pthread_mutex_unlock(&list->lock);
    }
}

void delete_entry(LinkedList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Entry not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    list->size--;

    log_operation("Deleted", rnti);

    pthread_mutex_unlock(&list->lock);
}

void* manage_list(void* arg) {
    LinkedList* list = (LinkedList*)arg;

    // Example operations
    for (int i = 0; i < MAX_ELEMENTS / 10; ++i) { // Add some entries
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.ue_info.rnti = rand() % MAX_ELEMENTS;
        entry.rnti = rand() % MAX_ELEMENTS;
