    delete_entry(list, rand() % MAX_ELEMENTS); // Delete an example entry

    destroy_list(list);

    return NULL;
}

int main() {
    LinkedList* list = create_list();

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_list, list) != 0) {
        perror("Failed to create thread");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    // Clean up
    destroy_list(list);

    return 0;
}
