#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG:1; // Assuming 1-bit flag for simplicity
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int unique_sequence;
    time_t timestamp;
} LinkedList;

// Initialize the linked list
void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->unique_sequence = 0;
    time(&list->timestamp);
}

// Free a single node
void free_node(Node* node) {
    free(node);
}

// Free the entire linked list
void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Insert a new node ensuring no consecutive elements share the same RNTI
int insert_node(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI with previous element
    Node* current = list->head;
    if (current && current->data.RNTI == RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate found, insertion failed
    }

    // Allocate new node and initialize it
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    list->unique_sequence++;
    time(&list->timestamp);

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = list->head;

    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Iterate over the list to retrieve information
void iterate_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
void print_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n", 
           data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    LinkedList list;
    init_list(&list);

    insert_node(&list, 1, 100);
    insert_node(&list, 2, 101);

    iterate_list(&list, print_node);

    destroy_list(&list);

    return 0;
}
