['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define DEFAULT_UE_ID 0
#define DEFAULT_AMBR 1000 // in Kbps

typedef struct {
    int QoS_identifier;
    int priority;
} QoS_FLOW;

typedef struct SMF_CONTEXT {
    char PFCP_SESSION_ID[32];
    int Session_AMBR;
    QoS_FLOW *QoS_Flows; 
    size_t flow_count;
} SMF_CONTEXT;

typedef struct UDM_UE_CONTEXT {
    int UE_ID;
    int AMBR;
    SMF_CONTEXT *smf_contexts;
    size_t smf_count;
} UDM_UE_CONTEXT;

// Thread safety and memory management
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

UDM_UE_CONTEXT* create_ue_context(int ue_id, int ambr) {
    pthread_mutex_lock(&db_lock);

    UDM_UE_CONTEXT *ue_ctx = (UDM_UE_CONTEXT *)malloc(sizeof(UDM_UE_CONTEXT));
    if (!ue_ctx) {
        perror("Failed to allocate memory for UE context");
        pthread_mutex_unlock(&db_lock);
        return NULL;
    }
    ue_ctx->UE_ID = ue_id;
    ue_ctx->AMBR = ambr;
    ue_ctx->smf_contexts = NULL;
    ue_ctx->smf_count = 0;

    pthread_mutex_unlock(&db_lock);
    return ue_ctx;
}

void add_smf_context(UDM_UE_CONTEXT *ue_ctx, const char* pfcp_session_id, int session_ambr) {
    if (!ue_ctx) return;

    pthread_mutex_lock(&db_lock);

    SMF_CONTEXT *smf = (SMF_CONTEXT *)malloc(sizeof(SMF_CONTEXT));
    if (!smf) {
        perror("Failed to allocate memory for SMF context");
        pthread_mutex_unlock(&db_lock);
        return;
    }
    strncpy(smf->PFCP_SESSION_ID, pfcp_session_id, sizeof(smf->PFCP_SESSION_ID) - 1);
    smf->Session_AMBR = session_ambr;
    smf->QoS_Flows = NULL;
    smf->flow_count = 0;

    // Resize the array of SMF_CONTEXTs
    ue_ctx->smf_contexts = (SMF_CONTEXT *)realloc(ue_ctx->smf_contexts, 
        sizeof(SMF_CONTEXT) * (ue_ctx->smf_count + 1));
    if (!ue_ctx->smf_contexts) {
        perror("Failed to resize SMF contexts array");
        free(smf);
        pthread_mutex_unlock(&db_lock);
        return;
    }
    ue_ctx->smf_contexts[ue_ctx->smf_count] = *smf;
    free(smf);

    ue_ctx->smf_count++;

    pthread_mutex_unlock(&db_lock);
}

void add_qos_flow(SMF_CONTEXT *smf, int qos_id, int priority) {
    if (!smf) return;

    pthread_mutex_lock(&db_lock);

    // Resize the QoS_Flows array
    smf->QoS_Flows = (QoS_FLOW *)realloc(smf->QoS_Flows,
        sizeof(QoS_FLOW) * (smf->flow_count + 1));
    if (!smf->QoS_Flows) {
        perror("Failed to resize QoS Flows array");
        pthread_mutex_unlock(&db_lock);
        return;
    }

    smf->QoS_Flows[smf->flow_count].QoS_identifier = qos_id;
    smf->QoS_Flows[smf->flow_count].priority = priority;

    // Sort QoS flows by priority
    for (size_t i = 0; i < smf->flow_count; ++i) {
        for (size_t j = i + 1; j < smf->flow_count; ++j) {
            if (smf->QoS_Flows[i].priority < smf->QoS_Flows[j].priority) {
                QoS_FLOW temp = smf->QoS_Flows[i];
                smf->QoS_Flows[i] = smf->QoS_Flows[j];
                smf->QoS_Flows[j] = temp;
            }
        }
    }

    smf->flow_count++;

    pthread_mutex_unlock(&db_lock);
}

void remove_qos_flow(SMF_CONTEXT *smf, int qos_id) {
    if (!smf || !smf->QoS_Flows) return;

    pthread_mutex_lock(&db_lock);

    for (size_t i = 0; i < smf->flow_count; ++i) {
        if (smf->QoS_Flows[i].QoS_identifier == qos_id) {
            // Shift elements
            memmove(&smf->QoS_Flows[i], &smf->QoS_Flows[i + 1],
                sizeof(QoS_FLOW) * (smf->flow_count - i - 1));

            smf->flow_count--;

            // Resize the array to fit new count
            smf->QoS_Flows = (QoS_FLOW *)realloc(smf->QoS_Flows,
                sizeof(QoS_FLOW) * smf->flow_count);
            if (!smf->QoS_Flows && smf->flow_count > 0) {
                perror("Failed to resize QoS Flows array");
            }

            break;
        }
    }

    pthread_mutex_unlock(&db_lock);
}

void flush_to_disk(UDM_UE_CONTEXT *ue_ctx, const char* filename) {
    if (!ue_ctx || !filename) return;

    pthread_mutex_lock(&db_lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for flushing");
        pthread_mutex_unlock(&db_lock);
        return;
    }

    fwrite(ue_ctx, sizeof(UDM_UE_CONTEXT), 1, file);
    for (size_t i = 0; i < ue_ctx->smf_count; ++i) {
        fwrite(&(ue_ctx->smf_contexts[i]), sizeof(SMF_CONTEXT), 1, file);
        if (ue_ctx->smf_contexts[i].QoS_Flows) {
            size_t flow_count = ue_ctx->smf_contexts[i].flow_count;
            fwrite(&flow_count, sizeof(size_t), 1, file);
            fwrite(ue_ctx->smf_contexts[i].QoS_Flows, 
                sizeof(QoS_FLOW), flow_count, file);
        }
    }

    fclose(file);

    pthread_mutex_unlock(&db_lock);
}

void free_ue_context(UDM_UE_CONTEXT *ue_ctx) {
    if (!ue_ctx) return;

    pthread_mutex_lock(&db_lock);

    for (size_t i = 0; i < ue_ctx->smf_count; ++i) {
        free(ue_ctx->smf_contexts[i].QoS_Flows);
    }
    free(ue_ctx->smf_contexts);
    free(ue_ctx);

    pthread_mutex_unlock(&db_lock);
}

// Sample usage
int main() {
    UDM_UE_CONTEXT *ue = create_ue_context(DEFAULT_UE_ID, DEFAULT_AMBR);

    add_smf_context(ue, "session123", 500); // example session ID and AMBR
    add_qos_flow(&(ue->smf_contexts[0]), 1, 10);
    add_qos_flow(&(ue->smf_contexts[0]), 2, 20);

    remove_qos_flow(&(ue->smf_contexts[0]), 1);

    flush_to_disk(ue, "database.bin");

    free_ue_context(ue);

    return 0;
}
