void remove_application(VNF_HOST *host, int vm_id, char *app_name);
void scale_virtual_machines(VNF_HOST *host, ResourceMetrics metrics);
void handle_failures(VNF_HOST *host);

// Thread-safe function to add an application
void add_application(VNF_HOST *host, int vm_id, char *app_name) {
    pthread_mutex_lock(&host->lock);

    // Find the VM and add application
    for (size_t i = 0; i < host->vms_count; ++i) {
        if (host->vms[i].VM_ID == vm_id) {
            ApplicationNode *new_node = malloc(sizeof(ApplicationNode));
            new_node->app_name = strdup(app_name);
            new_node->next = host->vms[i].apps_head;
            host->vms[i].apps_head = new_node;
            break;
        }
    }

    pthread_mutex_unlock(&host->lock);
}

// Thread-safe function to remove an application
void remove_application(VNF_HOST *host, int vm_id, char *app_name) {
    pthread_mutex_lock(&host->lock);

    // Find the VM and remove application
    for (size_t i = 0; i < host->vms_count; ++i) {
        if (host->vms[i].VM_ID == vm_id) {
            ApplicationNode **current = &(host->vms[i].apps_head);
            while (*current != NULL) {
                if (strcmp((*current)->app_name, app_name) == 0) {
                    ApplicationNode *to_remove = *current;
                    *current = to_remove->next;
                    free(to_remove->app_name);
                    free(to_remove);
                    break;
                }
                current = &(*current)->next;
            }
            break;
        }
    }

    pthread_mutex_unlock(&host->lock);
}

// Function to scale virtual machines based on resource metrics
void scale_virtual_machines(VNF_HOST *host, ResourceMetrics metrics) {
    pthread_mutex_lock(&host->lock);

    // Example scaling logic (simplified)
