        VIRTUAL_MACHINE new_vm = { .VM_ID = host->vms_count + 1 };
        host->vms[host->vms_count++] = new_vm;
    } else if ((metrics.CPU_usage < 20 && metrics.memory_usage < 20) && host->vms_count > 1) {
        // Remove a VM (example logic)
        host->vms_count--;
        host->vms = realloc(host->vms, sizeof(VIRTUAL_MACHINE) * host->vms_count);
    }

    pthread_mutex_unlock(&host->lock);
}

