#define MAX_RETRIES 5

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    int Status;
    int Duration;
} EventDetails;

typedef struct {
    time_t Timestamp;
    EventType EventType;
    EventDetails EventDetails;
} NetworkEvent;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate API call with retry logic and exponential backoff
int fetch_event_data_from_api(NetworkEvent *event, int attempt) {
    // Simulate network delay and failure
    if (rand() % 10 < 3) { // 30% chance of failure
        return -1; // Simulate API failure
    }

    // Populate event with simulated data
    event->Timestamp = time(NULL) + rand() % 1000;
    event->EventType = rand() % 2; // Random event type

    if (attempt >= MAX_RETRIES) {
        printf("Max retries reached for fetching event data.\n");
        return -1;
    }

    return 0; // Success
}

// Function to fetch and filter unique events
int fetch_and_filter_events(NetworkEvent **events, int *size) {
    int capacity = 1000;
    *events = malloc(capacity * sizeof(NetworkEvent));
    if (*events == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    int count = 0;
    while (count < *size) {
        NetworkEvent new_event;
        int attempt = 0;

        while (fetch_event_data_from_api(&new_event, attempt++) != 0) {
            // Exponential backoff
            sleep((1 << attempt));
        }

        // Check for duplicates
        int is_duplicate = 0;
        for (int i = 0; i < count; ++i) {
            if ((*events)[i].Timestamp == new_event.Timestamp &&
                (*events)[i].EventType == new_event.EventType) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            if (count >= capacity) {
                capacity *= 2;
                *events = realloc(*events, capacity * sizeof(NetworkEvent));
                if (*events == NULL) {
                    fprintf(stderr, "Memory reallocation failed.\n");
                    return -1;
                }
            }
            new_event.EventDetails.Status = rand() % 100; // Random status
            new_event.EventDetails.Duration = rand() % 60; // Random duration

            pthread_mutex_lock(&mutex);
            (*events)[count++] = new_event;
            pthread_mutex_unlock(&mutex);
        }
    }

    *size = count;
    return 0;
}

// Comparator function for qsort
int compare_events(const void *a, const void *b) {
    NetworkEvent *eventA = (NetworkEvent *)a;
    NetworkEvent *eventB = (NetworkEvent *)b;

    if (eventA->Timestamp < eventB->Timestamp) return -1;
    if (eventA->Timestamp > eventB->Timestamp) return 1;
    return 0;
}

// Function to initialize and sort events
int initialize_and_sort_events(NetworkEvent **events, int *size) {
    if (fetch_and_filter_events(events, size) != 0) {
        free(*events);
        return -1;
    }

    qsort(*events, *size, sizeof(NetworkEvent), compare_events);
    return 0;
}

// Main function for testing
int main() {
    srand(time(NULL));

    NetworkEvent *events = NULL;
    int size = 10000; // Example size

    if (initialize_and_sort_events(&events, &size) == 0) {
        printf("Events initialized and sorted successfully.\n");
    } else {
        printf("Failed to initialize and sort events.\n");
    }

    free(events);
    return 0;
}
