typedef struct {
    UESessionState *sessions;
    size_t session_count;
    pthread_rwlock_t rwlock;  // Reader-writer lock for sessions
    pthread_mutex_t priority_lock;  // Spinlock or mutex for priority queue
    UESessionState *priority_queue[MAX_SESSIONS];
    size_t priority_count;
} SessionManager;

void initialize_session_manager(SessionManager *manager) {
    manager->sessions = NULL;
    manager->session_count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);
    pthread_mutex_init(&manager->priority_lock, NULL);
    manager->priority_count = 0;
}

int add_sessions(SessionManager *manager, UESessionState *new_sessions, size_t count) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < count; ++i) {
        // Efficient memory allocation
        manager->sessions = realloc(manager->sessions, sizeof(UESessionState) * (manager->session_count + 1));
        if (!manager->sessions) {
            pthread_rwlock_unlock(&manager->rwlock);
            return -1;
        }
        memcpy(&manager->sessions[manager->session_count], &new_sessions[i], sizeof(UESessionState));
        manager->session_count++;
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

int remove_sessions(SessionManager *manager, unsigned int *rntis, size_t count) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < manager->session_count; ++j) {
            if (manager->sessions[j].rnti == rntis[i]) {
                memmove(&manager->sessions[j], &manager->sessions[j + 1],
                        sizeof(UESessionState) * (manager->session_count - j - 1));
                manager->session_count--;
                break;
            }
        }
    }

    if (manager->session_count > 0) {
        manager->sessions = realloc(manager->sessions, sizeof(UESessionState) * manager->session_count);
    } else {
        free(manager->sessions);
        manager->sessions = NULL;
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

void enqueue_priority_session(SessionManager *manager, UESessionState session) {
    pthread_mutex_lock(&manager->priority_lock);

    if (manager->priority_count < MAX_SESSIONS) {
        manager->priority_queue[manager->priority_count++] = &session;
    }

    pthread_mutex_unlock(&manager->priority_lock);
}

int dequeue_priority_session(SessionManager *manager, UESessionState *out_session) {
    pthread_mutex_lock(&manager->priority_lock);

    if (manager->priority_count > 0) {
        *out_session = *(manager->priority_queue[0]);
        memmove(manager->priority_queue, manager->priority_queue + 1,
                sizeof(UESessionState) * (--manager->priority_count));
        return 0;
    }

    pthread_mutex_unlock(&manager->priority_lock);
    return -1;  // No session to dequeue
}

// Implement additional functions for integration with NMS and fault injection tests as needed

void cleanup_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_rwlock_destroy(&manager->rwlock);
    pthread_mutex_destroy(&manager->priority_lock);
}
