#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPILinkedList;

// Function prototypes
void initialize_list(NFAPILinkedList* list);
int add_structure(NFAPILinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data);
void cleanup_list(NFAPILinkedList* list);
static int generate_random_crc_flag();
static int is_rnti_unique(const NFAPILinkedList* list, int rnti);

// Initialize the linked list
void initialize_list(NFAPILinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a structure to the list ensuring constraints
int add_structure(NFAPILinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!is_rnti_unique(list, new_data.RNTI)) return -1;

    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    newNode->data = new_data;
    newNode->next = NULL;

    // Insert in sorted order
    if (!list->head || list->head->data.RNTI > new_data.RNTI) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.RNTI < new_data.RNTI) {
            current = current->next;
        }
        if (current->next) {
            newNode->next = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Clean up the list and free resources
void cleanup_list(NFAPILinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Generate random CRC flag
static int generate_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Check if RNTI is unique in the list
static int is_rnti_unique(const NFAPILinkedList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1; // RNTI is unique
}

int main() {
    NFAPILinkedList nfa_list;
    initialize_list(&nfa_list);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand(); // Simulate valid tag
        data.RNTI = rand() % (MAX_STRUCTURES * 2); // Ensure a larger range for uniqueness
        data.CRC_INDICATION_REL8_TAG = generate_random_crc_flag();

        if (add_structure(&nfa_list, data) != 0) {
            fprintf(stderr, "Failed to add structure at index %d\n", i);
        }
    }

    cleanup_list(&nfa_list);

    return 0;
}
