#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define N 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} NFAPI_CRC_INDICATION_LIST_T;

// External resource manager placeholder
void* external_resource_allocate(size_t size) {
    return malloc(size);
}

void external_resource_deallocate(void* ptr) {
    free(ptr);
}

NFAPI_CRC_INDICATION_LIST_T* create_list(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*) external_resource_allocate(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*) external_resource_allocate(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        external_resource_deallocate(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);

    return list;
}

void destroy_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) return;

    external_resource_deallocate(list->list);
    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->rwlock);
    external_resource_deallocate(list);
}

int populate_list(NFAPI_CRC_INDICATION_LIST_T* list, size_t N) {
    if (!list || list->count >= list->capacity) return -1;

    pthread_rwlock_wrlock(&list->rwlock);

    for (size_t i = 0; i < N && (list->count + i) < list->capacity; ++i) {
        list->list[list->count + i].RX_UE_INFORMATION_TAG = rand() % 100000;
        list->list[list->count + i].RNTI = rand() % 65535;
        list->list[list->count + i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0x01 : 0x00;
    }

    list->count += N;

    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

int serialize_list(const char* filename, const NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_rwlock_rdlock(&list->rwlock);

    fwrite(list->count, sizeof(size_t), 1, file);
    fwrite(list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

int deserialize_list(const char* filename, NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    NFAPI_CRC_INDICATION_LIST_T temp_list;
    temp_list.capacity = count;
    temp_list.count = 0;
    temp_list.list = (NFAPI_CRC_INDICATION_PDU_T*) external_resource_allocate(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_list.list) {
        fclose(file);
        return -1;
    }

    fread(temp_list.list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    pthread_rwlock_wrlock(&list->rwlock);

    destroy_list(list);
    *list = temp_list;

    pthread_rwlock_unlock(&list->rwlock);
    fclose(file);
    return 0;
}

int clear_and_repopulate_list(NFAPI_CRC_INDICATION_LIST_T* list, size_t N) {
    if (!list) return -1;

    pthread_rwlock_wrlock(&list->rwlock);

    // Clear the list
    memset(list->list, 0, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;

    // Repopulate with updated data (here simply calling populate_list again)
    if (populate_list(list, N) != 0) {
        pthread_rwlock_unlock(&list->rwlock);
        return -1;
    }

    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

// Example usage
int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_LIST_T* list = create_list(N);
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    if (populate_list(list, N) != 0) {
        fprintf(stderr, "Failed to populate list.\n");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    // Simulate serialization and deserialization
    serialize_list("list_data.bin", list);
    destroy_list(list);

    list = create_list(N);
    if (!list) {
        fprintf(stderr, "Failed to recreate list.\n");
        return EXIT_FAILURE;
    }

    if (deserialize_list("list_data.bin", list) != 0) {
        fprintf(stderr, "Failed to deserialize list.\n");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    // Clear and repopulate
    clear_and_repopulate_list(list, N);

    destroy_list(list);
    return EXIT_SUCCESS;
}
