    if (!newNode) {
        perror("Failed to allocate memory for SessionNode");
        free(session->rbs);
        free(session);
        return;
    }
    newNode->session = *session;
    newNode->next = head;
    head = newNode;

    // Free the temporary UESessionContext
    free(session->rbs);
    free(session);
}

void cleanupUnusedSessions(time_t currentTime) {
    SessionNode **current = &head;
    while (*current) {
        SessionNode *entry = *current;
        if (difftime(currentTime, entry->session.schedulingRequestTimestamp) > 3600) { // 1 hour timeout
            printf("Cleaning up session with UEIdentifier %d\n", entry->session.ueIdentifier);
            *current = entry->next; // Remove from list
            free(entry->session.rbs); // Free the RBs array
            free(entry); // Free the node
        } else {
            current = &entry->next;
        }
    }
}
