#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
} ThreadSafeList;

ThreadSafeList* create_list() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void insert_node(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->lock);
}

void traverse_list(ThreadSafeList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

void free_list(ThreadSafeList* list) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RNTI = rnti;
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example random tag
    CRC_INDICATION_REL8_TAG crc_tag;
    crc_tag.CRCFLAG = rand() % 2; // Randomly set flag
    return pdu;
}

void serialize_list(ThreadSafeList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_rwlock_unlock(&list->lock);
}

void deserialize_list(ThreadSafeList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    free_list(list); // Clear existing list

    pthread_rwlock_wrlock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        insert_node(list, pdu);
    }

    fclose(file);
    pthread_rwlock_unlock(&list->lock);
}

void populate_list(ThreadSafeList* list, int N) {
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu(i + 1); // Example RNTI
        insert_node(list, pdu);
    }
}

// Usage example:
/*
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u\n", pdu->RNTI, pdu->RX_UE_INFORMATION_TAG);
}
int main() {
    srand(time(NULL)); // Seed random number generator
    ThreadSafeList* list = create_list();
    populate_list(list, 10);

    traverse_list(list, print_pdu);

    serialize_list(list, "list.bin");
    deserialize_list(list, "list.bin");

    free_list(list);
    return 0;
}
*/

```

