#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_QOS_FLOW_RULES 100

typedef struct QoS_Flow_Rule {
    int qos_id;
    int priority;
    // Additional fields as needed...
} QoS_Flow_Rule;

typedef struct SMF_Context {
    int PFCP_SESSION_ID;
    int Session_AMBR;
    QoS_Flow_Rule* qos_flow_rules[MAX_QOS_FLOW_RULES];
    size_t rule_count;
    pthread_mutex_t lock;  // For thread safety
} SMF_Context;

typedef struct UDM_UE_Context {
    int UE_ID;
    int AMBR;
    SMF_Context* smf_contexts; // Dynamic list of SMF contexts
    size_t context_count;
    pthread_mutex_t lock;      // For thread safety
} UDM_UE_Context;

// Function prototypes
UDM_UE_Context* initialize_ue_context(int ue_id, int ambr);
void add_smf_context(UDM_UE_Context* ue_context, SMF_Context* smf_context);
void remove_smf_context(UDM_UE_Context* ue_context, int pfcpsession_id);
void update_qos_flow_rule(SMF_Context* smf_context, int qos_id, QoS_Flow_Rule new_rule);

// Initialize UDM_UE_CONTEXT
UDM_UE_Context* initialize_ue_context(int ue_id, int ambr) {
    UDM_UE_Context* context = (UDM_UE_Context*)malloc(sizeof(UDM_UE_Context));
    if (!context) return NULL;

    pthread_mutex_init(&context->lock, NULL);
    context->UE_ID = ue_id;
    context->AMBR = ambr;
    context->smf_contexts = NULL; // Initially no SMF contexts
    context->context_count = 0;

    return context;
}

// Add a new SMF_CONTEXT to the UE context
void add_smf_context(UDM_UE_Context* ue_context, SMF_Context* smf_context) {
    pthread_mutex_lock(&ue_context->lock);

    size_t new_size = (ue_context->context_count + 1) * sizeof(SMF_Context*);
    SMF_Context** new_list = realloc(ue_context->smf_contexts, new_size);
    if (!new_list) {
        pthread_mutex_unlock(&ue_context->lock);
        return; // Error handling: memory allocation failed
    }

    ue_context->smf_contexts = new_list;
    ue_context->smf_contexts[ue_context->context_count++] = smf_context;

    pthread_mutex_unlock(&ue_context->lock);

    // Logging the addition (pseudo-code)
    printf("Added SMF context with session ID %d\n", smf_context->PFCP_SESSION_ID);
}

// Remove an SMF_CONTEXT from the UE context by PFCP_SESSION_ID
void remove_smf_context(UDM_UE_Context* ue_context, int pfcpsession_id) {
    pthread_mutex_lock(&ue_context->lock);

    for (size_t i = 0; i < ue_context->context_count; ++i) {
        SMF_Context* context = ue_context->smf_contexts[i];
        if (context->PFCP_SESSION_ID == pfcpsession_id) {
            free(context->qos_flow_rules);
            for (size_t j = i; j < ue_context->context_count - 1; ++j) {
                ue_context->smf_contexts[j] = ue_context->smf_contexts[j + 1];
            }
            --ue_context->context_count;
            break;
        }
    }

    pthread_mutex_unlock(&ue_context->lock);

    // Logging the removal (pseudo-code)
    printf("Removed SMF context with session ID %d\n", pfcpsession_id);
}

// Update a QoS_FLOW rule in an SMF_CONTEXT
void update_qos_flow_rule(SMF_Context* smf_context, int qos_id, QoS_Flow_Rule new_rule) {
    pthread_mutex_lock(&smf_context->lock);

    for (size_t i = 0; i < smf_context->rule_count; ++i) {
        if (smf_context->qos_flow_rules[i]->qos_id == qos_id) {
            *smf_context->qos_flow_rules[i] = new_rule;
            // Re-sort the list based on priority or other criteria as needed
            break;
        }
    }

    pthread_mutex_unlock(&smf_context->lock);

    // Logging the update (pseudo-code)
    printf("Updated QoS rule with ID %d\n", qos_id);
}

// Example: Creating and using structures
int main() {
    UDM_UE_Context* ue_context = initialize_ue_context(1, 1000);

    SMF_Context smf_context;
    pthread_mutex_init(&smf_context.lock, NULL);
    smf_context.PFCP_SESSION_ID = 101;
    smf_context.Session_AMBR = 500;
    smf_context.rule_count = 2;

    QoS_Flow_Rule rule1 = { .qos_id = 201, .priority = 1 };
    QoS_Flow_Rule rule2 = { .qos_id = 202, .priority = 2 };

    smf_context.qos_flow_rules[0] = &rule1;
    smf_context.qos_flow_rules[1] = &rule2;

    add_smf_context(ue_context, &smf_context);

    QoS_Flow_Rule new_rule = { .qos_id = 201, .priority = 3 };
    update_qos_flow_rule(&smf_context, 201, new_rule);

    remove_smf_context(ue_context, 101);

    pthread_mutex_destroy(&ue_context->lock);
    free(ue_context->smf_contexts); // Ensure to free all allocated SMF contexts
    free(ue_context);

    return 0;
}
