               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.crc_info.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void reverse_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp = NULL;
    while (current != NULL) {
        temp = current->prev;
        current->prev = current->next;
        current->next = temp;
        current = current->prev;
    }

    if (temp != NULL)
        list->head = temp->prev;

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DoublyLinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
