#define MAX_FLOW_ID 10000
#define INACTIVITY_THRESHOLD 300 // seconds

typedef struct TrafficFlow {
    uint32_t flowId;
    size_t trafficVolume;
    time_t timestamp;
} TrafficFlow;

typedef struct TrafficArray {
    TrafficFlow *flows;
    atomic_size_t count;
    atomic_size_t capacity;
} TrafficArray;

TrafficArray* createTrafficArray(size_t initialCapacity) {
    TrafficArray *array = malloc(sizeof(TrafficArray));
    array->flows = calloc(initialCapacity, sizeof(TrafficFlow));
    atomic_store(&array->count, 0);
    atomic_store(&array->capacity, initialCapacity);
    return array;
}

void resizeTrafficArray(TrafficArray *array) {
    size_t newCapacity = atomic_load(&array->capacity) * 2;
    TrafficFlow *newFlows = realloc(array->flows, newCapacity * sizeof(TrafficFlow));
    if (newFlows) {
        array->flows = newFlows;
        atomic_store(&array->capacity, newCapacity);
    }
}

void addOrUpdateTrafficFlow(TrafficArray *array, uint32_t flowId, size_t trafficVolume, time_t timestamp) {
    if (flowId > MAX_FLOW_ID) return;

    for (size_t i = 0; i < atomic_load(&array->count); ++i) {
        if (array->flows[i].flowId == flowId) {
            array->flows[i].trafficVolume += trafficVolume;
            array->flows[i].timestamp = timestamp;
            logFlowEvent(flowId, "Updated", timestamp);
            return;
        }
    }

    if (atomic_load(&array->count) >= atomic_load(&array->capacity)) {
        resizeTrafficArray(array);
    }

    size_t index = atomic_fetch_add(&array->count, 1);
    array->flows[index] = (TrafficFlow){flowId, trafficVolume, timestamp};
    logFlowEvent(flowId, "Added", timestamp);
}

size_t getTotalTrafficVolume(TrafficArray *array, time_t startTimestamp, time_t endTimestamp) {
    size_t totalVolume = 0;
    for (size_t i = 0; i < atomic_load(&array->count); ++i) {
        if (array->flows[i].timestamp >= startTimestamp && array->flows[i].timestamp <= endTimestamp) {
            totalVolume += array->flows[i].trafficVolume;
        }
    }
    return totalVolume;
}

void flushInactiveFlows(TrafficArray *array, time_t currentTime) {
    size_t activeCount = 0;
    for (size_t i = 0; i < atomic_load(&array->count); ++i) {
        if (currentTime - array->flows[i].timestamp <= INACTIVITY_THRESHOLD) {
            if (activeCount != i) {
                array->flows[activeCount] = array->flows[i];
            }
            activeCount++;
        } else {
            logFlowEvent(array->flows[i].flowId, "Flushed", currentTime);
        }
    }

    atomic_store(&array->count, activeCount);
}

void logFlowEvent(uint32_t flowId, const char *event, time_t timestamp) {
    // Implement logging logic here. Consider using a robust logging framework.
    printf("Log: Flow %u %s at %ld\n", flowId, event, (long)timestamp);
}

void destroyTrafficArray(TrafficArray *array) {
    free(array->flows);
    free(array);
}
