#define MAX_STRUCTS 10000
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t lock;
} NFAPICRCList;

// Error codes
#define SUCCESS 0
#define ERROR_NULL_POINTER -1
#define ERROR_OUT_OF_MEMORY -2

// Function prototypes
int init_list(NFAPICRCList *list);
void cleanup_list(NFAPICRCList *list);
int add_structure(NFAPICRCList *list, const NFAPI_CRC_INDICATION_PDU_T *structure);
int remove_structure(NFAPICRCList *list, size_t index);
int serialize_list(const NFAPICRCList *list, const char *filename);
int deserialize_list(NFAPICRCList *list, const char *filename);

// Internal algorithm to set CRCFLAG
void set_crc_flag(CRC_INDICATION_REL8_TAG *tag) {
    // Placeholder for the actual CRC algorithm
    tag->CRCFLAG = (rand() % 2 == 0); 
}

int init_list(NFAPICRCList *list) {
    if (!list) return ERROR_NULL_POINTER;

    list->data = calloc(MAX_STRUCTS, STRUCT_SIZE);
    if (!list->data) return ERROR_OUT_OF_MEMORY;

    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return SUCCESS;
}

void cleanup_list(NFAPICRCList *list) {
    if (list && list->data) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
    }
}

int add_structure(NFAPICRCList *list, const NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (!list || !structure) return ERROR_NULL_POINTER;

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_OUT_OF_MEMORY;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = &list->data[list->size++];
    new_struct->RX_UE_INFORMATION_TAG = structure->RX_UE_INFORMATION_TAG;
    new_struct->RNTI = structure->RNTI;
    set_crc_flag(&new_struct->crc_tag);

    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

int remove_structure(NFAPICRCList *list, size_t index) {
    if (!list || list->size == 0 || index >= list->size) return ERROR_NULL_POINTER;

    pthread_mutex_lock(&list->lock);

    memmove(&list->data[index], &list->data[index + 1], (list->size - index - 1) * STRUCT_SIZE);
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

int serialize_list(const NFAPICRCList *list, const char *filename) {
    if (!list || !filename) return ERROR_NULL_POINTER;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(list->data, STRUCT_SIZE, list->size, file);
    fclose(file);

    return SUCCESS;
}

int deserialize_list(NFAPICRCList *list, const char *filename) {
    if (!list || !filename) return ERROR_NULL_POINTER;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t read_size = fread(list->data, STRUCT_SIZE, MAX_STRUCTS, file);
    list->size = read_size;
    fclose(file);

    return SUCCESS;
}

// Main function for demonstration (not part of the requirement)
int main() {
    NFAPICRCList my_list;
    if (init_list(&my_list) != SUCCESS) {
        fprintf(stderr, "Failed to initialize list\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T example_struct = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2 };
    add_structure(&my_list, &example_struct);

    serialize_list(&my_list, "list.bin");
    cleanup_list(&my_list);

    NFAPICRCList new_list;
    deserialize_list(&new_list, "list.bin");
    cleanup_list(&new_list);

    return EXIT_SUCCESS;
}
