#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_PACKET_COUNT 10

typedef struct {
    int packetID;
    time_t timestamp;
    size_t payloadLength;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    size_t maxBufferSize;
    pthread_mutex_t lock;
} PacketArray;

// Function prototypes
int initializePacketArray(PacketArray *array, size_t initialCapacity, size_t maxBufferSize);
int addDataPacket(PacketArray *array, int packetID, size_t payloadLength);
void adjustBufferSize(PacketArray *array);

int initializePacketArray(PacketArray *array, size_t initialCapacity, size_t maxBufferSize) {
    array->packets = (DataPacket *)malloc(initialCapacity * sizeof(DataPacket));
    if (!array->packets) return -1; // Allocation failure
    array->count = 0;
    array->capacity = initialCapacity;
    array->maxBufferSize = maxBufferSize;
    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

int addDataPacket(PacketArray *array, int packetID, size_t payloadLength) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        adjustBufferSize(array);
        if (array->count >= array->capacity) { // Buffer adjustment failed
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    if ((array->packets[array->count].payloadLength + payloadLength) > array->maxBufferSize) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Exceeds max buffer size constraint
    }

    DataPacket *packet = &array->packets[array->count++];
    packet->packetID = packetID;
    packet->timestamp = time(NULL);
    packet->payloadLength = payloadLength;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void adjustBufferSize(PacketArray *array) {
    size_t newCapacity = array->capacity * 2;
    DataPacket *newPackets = (DataPacket *)realloc(array->packets, newCapacity * sizeof(DataPacket));
    if (!newPackets && array->count > 0) { // Allocation failure
        array->capacity *= 2; // Attempt to double capacity again for recovery
        newPackets = realloc(array->packets, array->capacity * sizeof(DataPacket));
        if (!newPackets) return; // Critical allocation failure
    }

    if (newPackets) {
        array->packets = newPackets;
        array->capacity = newCapacity;
    }
}

void freePacketArray(PacketArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->packets);
}
```

