int populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** pdus, int n, unsigned int seed) {
    if (n <= 0 || n > MAX_STRUCTURES) return -1;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*pdus) {
            perror("Memory allocation failed");
            return -2;
        }

        srand(seed);
