        int is_unique = 1;

        for (int i = 0; i < n; ++i) {
            (*pdus)[i].RX_UE_INFORMATION_TAG = i + 1;
            do {
                (*pdus)[i].RNTI = rand() % MAX_STRUCTURES + 1;
                if (rnti_set[(*pdus)[i].RNTI - 1]) {
                    is_unique = 0;
                    break;
                }
                rnti_set[(*pdus)[i].RNTI - 1] = 1;
            } while (is_unique == 0);

            if (!is_unique) break;

            (*pdus)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }

        if (is_unique) break;

        free(*pdus);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}

