} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
} DynamicNfaList;

// Function to determine CRC flag based on RNTI
int determineCrcFlag(unsigned int rnti) {
    // Example rule: if RNTI is even, set crcFlag to 1; else 0
    return (rnti % 2 == 0) ? 1 : 0;
}

// Initialize dynamic list
void initDynamicNfaList(DynamicNfaList* list) {
    list->head = NULL;
    list->count = 0;
}

// Add a new PDU to the list
void addPduToDynamicList(DynamicNfaList* list, RX_UE_INFORMATION_TAG* rxTag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        perror("Failed to allocate memory for new PDU");
        return;
    }

    newNode->rxUeInformationTag = *rxTag;
    newNode->rnti = rnti;
    newNode->crcIndicationRel8Tag.crcFlag = determineCrcFlag(rnti);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

// Free all PDUs in the list
void freeDynamicNfaList(DynamicNfaList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

// Integrate into event loop
void processPduUpdates(DynamicNfaList* list, RX_UE_INFORMATION_TAG* rxTagArray, unsigned int rntiArray[], size_t numEntries) {
    for (size_t i = 0; i < numEntries; ++i) {
        addPduToDynamicList(list, &rxTagArray[i], rntiArray[i]);
    }
}

// Example usage
