    RNTI rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
    int crcflag;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRCList;

// Function to create a new list
CRCList* create_crc_list() {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Helper function to check for duplicate RNTI
int contains_rnti(CRCList* list, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) return 1;
        current = current->next;
    }
    return 0;
}

// Function to insert a new PDU into the list
void insert_pdu(CRCList* list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti,
                CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag, unsigned int seed) {
    if (contains_rnti(list, rnti)) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    srand(seed); // Seed the random number generator
    new_node->ue_info_tag = ue_info_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_node->crcflag = rand() % 2; // Generate pseudo-random CRCFLAG (0 or 1)
    new_node->timestamp = time(NULL);
    new_node->next = list->head;

    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    // Align to a 16-byte boundary
    void *current_ptr = new_node;
    size_t current_offset = (size_t)current_ptr % 16;
    if (current_offset != 0) {
        current_ptr = (void*)((size_t)current_ptr + (16 - current_offset));
    }
}

// Function to retrieve all PDUs from the list
void* get_all_pdus(CRCList* list, size_t *count) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    size_t size = 0;
    while (current != NULL) {
        size++;
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus_array) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    current = list->head;
    size_t index = 0;
    while (current != NULL) {
        pdus_array[index++] = *current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    *count = size;
    return pdus_array;
}

// Function to free the list
void destroy_crc_list(CRCList* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Main function for demonstration purposes
int main() {
    CRCList* list = create_crc_list();

    RX_UE_INFORMATION_TAG ue_info_tag = {1};
    RNTI rnti = 12345;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag = {0xABCD};

    insert_pdu(list, ue_info_tag, rnti, crc_indication_rel8_tag, 42);

    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)get_all_pdus(list, &count);

    for (size_t i = 0; i < count; i++) {
        printf("RNTI: %lu, CRCFLAG: %d, Timestamp: %ld\n", pdus[i].rnti, pdus[i].crcflag, pdus[i].timestamp);
    }

    free(pdus);
    destroy_crc_list(list);

    return 0;
}
