#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

// Define constants
#define MAX_ENTRIES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global variables for logging and tracking
static atomic_int nodes_processed = 0;
static atomic_int errors_encountered = 0;

// Lock for thread safety
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data);
void free_list(Node** head);
int validate_and_add_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data);
void log_message(const char* message);

// Create a new node with aligned memory allocation
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)aligned_alloc(64, sizeof(Node));
    if (!node) {
        atomic_fetch_add(&errors_encountered, 1);
        log_message("Memory allocation failure");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

// Free the entire linked list
void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Validate and add a new node to the list, ensuring no duplicates
int validate_and_add_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list_lock);

    Node* current = *head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG ||
            current->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&list_lock);
            return -1; // Duplicate found
        }
        current = current->next;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list_lock);
        return -1; // Memory allocation failure
    }

    new_node->next = *head;
    *head = new_node;

    atomic_fetch_add(&nodes_processed, 1);

    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Logging function for debugging and tracking
void log_message(const char* message) {
    printf("LOG: %s\n", message);
}

