        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() % 10000, .CRC_INDICATION_REL8_TAG = rand() % 256 };
        if (validate_and_add_node(&head, pdu) != 0) {
            break; // Stop on failure
        }
    }

    log_message("Processing complete");
    printf("Nodes processed: %d\n", atomic_load(&nodes_processed));
    printf("Errors encountered: %d\n", atomic_load(&errors_encountered));

    free_list(&head);

    return 0;
}
