typedef struct {
    int id;
    float qos; // Quality of Service parameters
} Bearer;

typedef struct BearerNode {
    Bearer bearer;
    struct BearerNode* next;
} BearerNode;

typedef struct {
    char imsi[15];
    char tmsi[10];
    BearerNode* bearers;
    pthread_mutex_t lock;
} SessionManagementContext;

SessionManagementContext* create_smc(const char* imsi, const char* tmsi) {
    SessionManagementContext* smc = (SessionManagementContext*)malloc(sizeof(SessionManagementContext));
    if (!smc) return NULL;

    strncpy(smc->imsi, imsi, sizeof(smc->imsi) - 1);
    strncpy(smc->tmsi, tmsi, sizeof(smc->tmsi) - 1);
    smc->bearers = NULL;
    pthread_mutex_init(&smc->lock, NULL);

    return smc;
}

void add_bearer(SessionManagementContext* smc, int id, float qos) {
    if (!smc) return;

    pthread_mutex_lock(&smc->lock);

    BearerNode* new_node = (BearerNode*)malloc(sizeof(BearerNode));
    if (!new_node) {
        pthread_mutex_unlock(&smc->lock);
        return;
    }

    new_node->bearer.id = id;
    new_node->bearer.qos = qos;
    new_node->next = smc->bearers;
    smc->bearers = new_node;

    pthread_mutex_unlock(&smc->lock);
}

void remove_bearer(SessionManagementContext* smc, int id) {
    if (!smc) return;

    pthread_mutex_lock(&smc->lock);

    BearerNode **current = &smc->bearers;
    while (*current) {
        BearerNode *entry = *current;
        if (entry->bearer.id == id) {
            *current = entry->next;
            free(entry);
            break;
        }
        current = &entry->next;
    }

    pthread_mutex_unlock(&smc->lock);
}

void update_bearer_status(SessionManagementContext* smc, int id, float new_qos) {
    if (!smc) return;

    pthread_mutex_lock(&smc->lock);

    BearerNode *current = smc->bearers;
    while (current) {
        if (current->bearer.id == id) {
            current->bearer.qos = new_qos;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&smc->lock);
}

void free_smc(SessionManagementContext* smc) {
    if (!smc) return;

    pthread_mutex_lock(&smc->lock);

    BearerNode *current = smc->bearers;
    while (current) {
        BearerNode *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&smc->lock);
    pthread_mutex_destroy(&smc->lock);
    free(smc);
}

// Example of integrating with an external data source for bearer status updates
void external_data_source_integration(SessionManagementContext* smcs[], size_t count) {
    // Simulate integration, this function would be called periodically or triggered by events.
    // It's a placeholder to show where you might interact with an external system.

    for (size_t i = 0; i < count; ++i) {
        if (smcs[i]) {
            BearerNode *current = smcs[i]->bearers;
            while (current) {
                // Simulate fetching updated QoS from an external source
                float new_qos = current->bearer.qos + 1.0f; // Example update

                pthread_mutex_lock(&smcs[i]->lock);
                current->bearer.qos = new_qos;
                pthread_mutex_unlock(&smcs[i]->lock);

                current = current->next;
            }
        }
    }
}
