```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int signal_strength;
    int noise_level;
} PHY_MEASUREMENT_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    PHY_MEASUREMENT_T* measurements;
    int config_signal_threshold;
    int config_noise_threshold;
} MeasurementArray;

void initMeasurementArray(MeasurementArray *arr, size_t initial_capacity) {
    arr->lock = (pthread_mutex_t){0};
    pthread_mutex_init(&arr->lock, NULL);
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->measurements = malloc(initial_capacity * sizeof(PHY_MEASUREMENT_T));
    if (!arr->measurements) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void resizeIfNeeded(MeasurementArray *arr) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        PHY_MEASUREMENT_T* new_measurements = realloc(arr->measurements, new_capacity * sizeof(PHY_MEASUREMENT_T));
        if (!new_measurements) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        arr->measurements = new_measurements;
        arr->capacity = new_capacity;
    }
    pthread_mutex_unlock(&arr->lock);
}

void addMeasurement(MeasurementArray *arr, int signal_strength, int noise_level) {
    resizeIfNeeded(arr);
    pthread_mutex_lock(&arr->lock);

    PHY_MEASUREMENT_T measurement = {signal_strength, noise_level};
    if (measurement.signal_strength > arr->config_signal_threshold &&
        measurement.noise_level < arr->config_noise_threshold) {
        arr->measurements[arr->count++] = measurement;
    }

    pthread_mutex_unlock(&arr->lock);
}

void updateConfig(MeasurementArray *arr, int signal_threshold, int noise_threshold) {
    pthread_mutex_lock(&arr->lock);
    arr->config_signal_threshold = signal_threshold;
    arr->config_noise_threshold = noise_threshold;
    pthread_mutex_unlock(&arr->lock);
}

void* serializeMeasurements(const MeasurementArray *arr, unsigned char **buffer) {
    pthread_mutex_lock(&arr->lock);

    size_t buffer_size = arr->count * sizeof(PHY_MEASUREMENT_T);
    *buffer = malloc(buffer_size);
    if (!(*buffer)) {
        perror("Failed to allocate serialization buffer");
        pthread_mutex_unlock(&arr->lock);
        return NULL;
    }
    memcpy(*buffer, arr->measurements, buffer_size);

    pthread_mutex_unlock(&arr->lock);
    return (void *)*buffer;
}

void freeMeasurementArray(MeasurementArray *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->measurements);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

int main() {
    MeasurementArray arr;
    initMeasurementArray(&arr, 10);

    addMeasurement(&arr, 20, 5); // Add a sample measurement
    updateConfig(&arr, 15, 10);   // Update thresholds

    unsigned char *serialized_data;
    serializeMeasurements(&arr, &serialized_data);
    if (serialized_data) {
        printf("Serialized data size: %zu\n", strlen((char*)serialized_data));
        free(serialized_data);
    }

    freeMeasurementArray(&arr);

    return 0;
}
```

### Key Features:
- **Dynamic Resizing**: The array doubles its capacity when needed, minimizing reallocation frequency.
- **Thread Safety**: Mutexes are used to ensure safe concurrent access.
- **Filtering Logic**: Measurements are added based on configurable thresholds.
- **Serialization**: Measurements can be serialized into a binary format for storage or transmission.
- **Config Update**: Allows periodic updates of filtering parameters.

This implementation balances memory efficiency and computational overhead, ensuring both performance and maintainability. Adjustments to the structure size or data access patterns may further optimize cache utilization.']

