        msg->ueList = malloc(ueCount * sizeof(UE_Info));
        if (!msg->ueList) {
            perror("Failed to allocate memory for UE list");
            --i; // Decrement index to retry this slot in the next iteration
            continue;
        }

        for (size_t j = 0; j < ueCount; ++j) {
            msg->ueList[j].RNTI = rand() % 10000 + 1; // RNTI between 1 and 10000
            msg->ueList[j].RX_UE_INFORMATION_TAG = rand() % 100 + 1; // RX_UE_INFO_TAG between 1 and 100
            msg->ueList[j].crcIndication.CRCFLAG = rand() & 0x01; // Random CRC flag (0 or 1)
        }

        msg->ueCount = ueCount;
    }

    return messages;
}

void freeRrcReconfiguration(LTE_RRC_RECONFIGURATION *messages, size_t count) {
    if (!messages) return;

    for (size_t i = 0; i < count; ++i) {
        LTE_RRC_RECONFIGURATION *msg = &messages[i];
        if (msg->ueList) free(msg->ueList);
    }

    free(messages);
}

int main() {
    size_t maxMessages = 10;
    pthread_mutex_lock(&lock);

    LTE_RRC_RECONFIGURATION *messages = manageRrcReconfiguration(maxMessages);

    if (!messages) {
        fprintf(stderr, "Failed to create RRC reconfiguration messages.\n");
        return EXIT_FAILURE;
    }

    // Use the messages...

    freeRrcReconfiguration(messages, maxMessages);

    pthread_mutex_unlock(&lock);
    return EXIT_SUCCESS;
}
