#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>

// Define constants and structure
#define POOL_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
        uint8_t CRC_INDICATION_REL8_TAG[10]; // Example size
    } CRC_DATA;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* pool;
    size_t unit_size;
    size_t total_units;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void initialize_memory_pool(MemoryPool* mp, size_t unit_size, size_t total_units);
NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* mp);
bool insert_unique_rnti(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T** list, uint16_t rnti, size_t* length);

// Initialize memory pool
void initialize_memory_pool(MemoryPool* mp, size_t unit_size, size_t total_units) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->unit_size = unit_size;
    mp->total_units = total_units;
    mp->free_count = total_units;
    mp->pool = malloc(unit_size * total_units);
}

// Allocate from pool
NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_count > 0) {
        void* mem = ((char*)mp->pool + (--mp->free_count) * mp->unit_size);
        pthread_mutex_unlock(&mp->lock);
        return (NFAPI_CRC_INDICATION_PDU_T*)mem;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

// Insert unique RNTI and retry on collision
bool insert_unique_rnti(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T** list, uint16_t rnti, size_t* length) {
    for (size_t i = 0; i < *length; ++i) {
        if ((*list)[i].RNTI == rnti) {
            return false;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = allocate_from_pool(mp);
    if (!new_pdu) {
        fprintf(stderr, "Memory allocation failed\n");
        return false;
    }

    // Populate the structure
    new_pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    new_pdu->RNTI = rnti;
    new_pdu->CRC_DATA.CRCFLAG = rand() % 2;
    for (int i = 0; i < sizeof(new_pdu->CRC_DATA.CRC_INDICATION_REL8_TAG); ++i) {
        new_pdu->CRC_DATA.CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }

    // Resize list and add the new PDU
    *list = realloc(*list, (*length + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        fprintf(stderr, "Memory reallocation failed\n");
        return false;
    }

    (*list)[*length] = *new_pdu;
    ++(*length);

    return true;
}

// Main function to create list
NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t N) {
    MemoryPool mp;
    initialize_memory_pool(&mp, sizeof(NFAPI_CRC_INDICATION_PDU_T), POOL_SIZE);

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    size_t length = 0;

    for (size_t i = 0; i < N; ++i) {
        bool success = false;
        while (!success) {
            uint16_t rnti = rand() % 65535; // Example RNTI range
            success = insert_unique_rnti(&mp, &list, rnti, &length);
            if (!success) {
                fprintf(stderr, "Duplicate RNTI detected, retrying\n");
            }
        }
    }

    return list;
}

// Cleanup function (for demonstration purposes)
void cleanup(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T* list) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(list);
}
