    array->capacity = 0;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

int add_packet(DynamicArray *array, int packet_id, size_t data_size, time_t timestamp) {
    // Validate packet (Example: Ensure non-negative data size)
    if (data_size == 0 || packet_id < 0) return -1;

    pthread_mutex_lock(&array->lock);

    // Resize array if necessary
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : INITIAL_CAPACITY;
        DataPacket *new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    // Add the packet
    DataPacket *packet = &array->packets[array->count++];
    packet->packet_id = packet_id;
    packet->data_size = data_size;
    packet->timestamp = timestamp;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void free_dynamic_array(DynamicArray *array) {
