int addChannel(ChannelManager* manager, int bandwidth, double centerFrequency, const char* modulationScheme) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity == 0 ? 10 : manager->capacity * 2;
        LTEPHYChannelInfo* newChannels = realloc(manager->channels, newCapacity * sizeof(LTEPHYChannelInfo));
        if (!newChannels) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failure
        }
        manager->channels = newChannels;
        manager->capacity = newCapacity;
    }

    LTEPHYChannelInfo* channel = &manager->channels[manager->count++];
    channel->bandwidth = bandwidth;
    channel->centerFrequency = centerFrequency;
    snprintf(channel->modulationScheme, sizeof(channel->modulationScheme), "%s", modulationScheme);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

