typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 10000000

int generate_unique_crc(uint32_t *crc_set, size_t size) {
    uint32_t crc;
    int attempts = 0;
    while (1) {
        crc = rand() & 0xFFFFFFFF; // Ensure it's a 32-bit value
        for (size_t i = 0; i < size; ++i) {
            if (crc_set[i] == crc) {
                attempts++;
                break;
            }
        }
        if (attempts > MAX_ENTRIES / 10) {
            fprintf(stderr, "Failed to generate unique CRC after many attempts\n");
            return -1;
        }
        if (attempts < size) {
            break;
        }
    }
    return crc;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_list(size_t n_entries, int *error_count, int *processed_count) {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    uint32_t *crc_set = malloc(n_entries * sizeof(uint32_t));
    if (!crc_set) {
        fprintf(stderr, "Memory allocation for CRC set failed\n");
        *error_count = 1;
        return NULL;
    }

    // Initialize the list
    list = malloc(n_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        free(crc_set);
        fprintf(stderr, "Memory allocation for NFA list failed\n");
        *error_count = 1;
        return NULL;
    }

    memset(list, 0, n_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    srand(time(NULL));
    uint32_t unique_crcs[MAX_ENTRIES] = {0};

    size_t current_size = 0;

    for (size_t i = 0; i < n_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list[i];

        entry->RX_UE_INFORMATION_TAG = rand() % MAX_ENTRIES;
        entry->RNTI = rand() % 65536; // Random RNTI
        entry->CRC_INDICATION_REL8_TAG = rand() % 256;

        for (size_t j = 0; j < current_size; ++j) {
            if (unique_crcs[j] == entry->RX_UE_INFORMATION_TAG) {
                fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG detected: %u\n", entry->RX_UE_INFORMATION_TAG);
                free(crc_set);
                free(list);
                *error_count = 1;
                return NULL; // Graceful exit on duplicate detection
            }
        }

        uint32_t crc_result = generate_unique_crc(unique_crcs, current_size);
        if (crc_result == -1) {
            free(crc_set);
            free(list);
            *error_count = 1;
            return NULL;
        }

        entry->CRCFLAG = crc_result;
        unique_crcs[current_size++] = entry->RX_UE_INFORMATION_TAG;

        (*processed_count)++;
    }

    free(crc_set);

    return list;
}

int main() {
    int error_count = 0, processed_count = 0;
    size_t n_entries = 100000; // Example with 100k entries

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = allocate_nfa_list(n_entries, &error_count, &processed_count);

    if (nfa_list) {
        printf("Successfully allocated and initialized list.\n");
        printf("Total processed: %d\n", processed_count);
        free(nfa_list);
    } else {
        printf("Failed to allocate the list. Error count: %d\n", error_count);
    }

    return 0;
}
```']

