        mac_contexts[i].mac_id = -1;  // Indicates an unused slot
    }

    return mac_contexts;
}

// Function to resize the MAC context array when needed
MAC_CONTEXT_T* resize_mac_context_array(MAC_CONTEXT_T* contexts, size_t new_size) {
    MAC_CONTEXT_T* new_contexts = allocate_mac_contexts(new_size);

    for (size_t i = 0; i < new_size && i < (new_size / 2); ++i) { // Copy old data
        new_contexts[i] = contexts[i];
