            contexts[i].mac_id = mac_id;
            contexts[i].stats.packets_received = packets;
            contexts[i].stats.bytes_received = bytes;
            return;
        }
    }

    // Resize and add new context if no slots are available
    size_t new_size = count * 2;
    MAC_CONTEXT_T* resized_contexts = resize_mac_context_array(contexts, new_size);
    update_statistics(resized_contexts, new_size, mac_id, packets, bytes);

