typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    size_t count;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || !data.RX_UE_INFORMATION_TAG) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int delete_node(DoublyLinkedList* list, Node* node) {
    if (!list || !node) return -1;

    pthread_mutex_lock(&list->lock);
    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }
    if (node->prev) {
        node->prev->next = node->next;
    }
    if (node->next) {
        node->next->prev = node->prev;
    }
    free(node);
    list->count--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void traverse_list(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void reverse_list(DoublyLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* temp = NULL;
    while (current) {
        temp = current->prev;
        current->prev = current->next;
        current->next = temp;
        current = current->prev;
    }
    if (temp) {
        list->head = temp->prev;
    }
    pthread_mutex_unlock(&list->lock);
}

int serialize_list(DoublyLinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

int deserialize_list(DoublyLinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    free_list(list); // Clear existing list
    list->head = list->tail = NULL;
    list->count = 0;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_node(list, data);
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu && pdu->CRC_INDICATION_REL8_TAG.crc_rel8.CRCFLAG == 0) {
        pdu->CRC_INDICATION_REL8_TAG.crc_rel8.CRCFLAG = rand() % 2;
    }
}

void generate_list(DoublyLinkedList* list, size_t N) {
