// Define the structure as per your description
typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI_THRESHOLD 10000
#define CHECKSUM_INTERVAL 1000

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
uint32_t running_checksum = 0;

// Function to generate a random RNTI, ensuring it doesn't repeat consecutively
int generate_unique_rnti(int last_rnti) {
    int rnti;
    do {
        rnti = rand() % MAX_RNTI_THRESHOLD; // Adjust the range as necessary
    } while (rnti == last_rnti);
    return rnti;
}

// Function to calculate checksum and reset if needed
void update_checksum(int rnti, int* count) {
    running_checksum += rnti;
    (*count)++;

    if (*count >= CHECKSUM_INTERVAL) {
        if (running_checksum > MAX_RNTI_THRESHOLD) {
            // Handle overflow logic here
            printf("Checksum threshold exceeded!\n");
            running_checksum = 0; // Reset checksum
        }
        *count = 0;
    }
}

// Function to create and populate the linked list
NFAPI_CRC_INDICATION_PDU_T* populate_crc_list(size_t num_entries) {
    if (num_entries == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    int last_rnti = -1; // Initialize to an invalid RNTI
    int count = 0;

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&lock);

        new_node->RX_UE_INFORMATION_TAG = i;
        new_node->RNTI = generate_unique_rnti(last_rnti);
        last_rnti = new_node->RNTI;

        // Set CRCFLAG randomly
        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // 0 or 1

        update_checksum(new_node->RNTI, &count);

        pthread_mutex_unlock(&lock);

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
    }

    return head;
}

// Example usage
int main() {
    size_t num_entries = 1000; // Number of entries to create
    NFAPI_CRC_INDICATION_PDU_T* list_head = populate_crc_list(num_entries);

    // Clean up the allocated memory
    while (list_head) {
        NFAPI_CRC_INDICATION_PDU_T* temp = list_head;
        list_head = list_head->next;
        free(temp);
    }

    return 0;
}
