        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_array) {
            perror("Failed to reallocate array");
            exit(EXIT_FAILURE);
        }
        da->capacity = new_capacity;
        da->array = new_array;
    }
}

void addEntry(DynamicArray *da, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
