#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
    time_t last_processed_time;
    size_t processed_count;
} DynamicList;

void initialize_dynamic_list(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->last_processed_time = time(NULL);
    list->processed_count = 0;
}

int add_structure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES || list->processed_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return 0; // List is full
    }

    if (time(NULL) - list->last_processed_time > 60) { // Reset every minute
        list->processed_count = 0;
        list->last_processed_time = time(NULL);
    }

    list->data[list->count++] = structure;
    list->processed_count++;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

void* process_structures(void *arg) {
    DynamicList *list = (DynamicList*)arg;

    while (1) {
        pthread_mutex_lock(&list->lock);

        if (list->count > 0) {
            for (size_t i = 0; i < list->count; ++i) {
                // Process structure here
                free(list->data[i]); // Free memory after processing
                list->data[i] = NULL;
            }
            list->count = 0;
        }

        pthread_mutex_unlock(&list->lock);
        sleep(1); // Simulate processing delay
    }
}

void generate_random_structure(NFAPI_CRC_INDICATION_PDU_T **structure) {
    *structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*structure)->ue_info.RNTI = rand() % 1000; // Example RNTI
    (*structure)->crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
}

void fallback_strategy(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count > MAX_STRUCTURES / 2) { // If more than half full, initiate fallback
        for (size_t i = list->count / 2; i < list->count; ++i) {
            free(list->data[i]);
            list->data[i] = NULL;
        }
        list->count /= 2;
    }

    pthread_mutex_unlock(&list->lock);
}

void handle_bursts(DynamicList *list) {
    while (1) {
        pthread_mutex_lock(&list->lock);

        if (list->processed_count >= MAX_STRUCTURES - 100) { // If approaching limit, defer processing
            fallback_strategy(list);
        }

        pthread_mutex_unlock(&list->lock);
        sleep(5); // Check every 5 seconds
    }
}

int main() {
    DynamicList list;
    initialize_dynamic_list(&list);

    pthread_t process_thread, burst_thread;

    pthread_create(&process_thread, NULL, process_structures, &list);
    pthread_create(&burst_thread, NULL, handle_bursts, &list);

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *structure;
        generate_random_structure(&structure);

        if (!add_structure(&list, structure)) {
            // Handle case where structure could not be added
            free(structure); // Prevent memory leak
        }

        sleep(0.1); // Simulate incoming data rate
    }

    return 0;
}
