MemoryPool g_memory_pool = { sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, NULL, PTHREAD_MUTEX_INITIALIZER };

int init_memory_pool(size_t max_elements) {
    pthread_mutex_lock(&g_memory_pool.lock);
    if (g_memory_pool.pool != NULL) {
        free(g_memory_pool.pool);
    }
    g_memory_pool.total_size = max_elements * g_memory_pool.element_size;
    g_memory_pool.pool = malloc(g_memory_pool.total_size);
    if (!g_memory_pool.pool) {
        perror("Failed to allocate memory pool");
        pthread_mutex_unlock(&g_memory_pool.lock);
        return -1;
    }
    pthread_mutex_unlock(&g_memory_pool.lock);
    return 0;
}

void* pool_alloc() {
    pthread_mutex_lock(&g_memory_pool.lock);
    if (g_memory_pool.total_size < g_memory_pool.element_size) {
        pthread_mutex_unlock(&g_memory_pool.lock);
        return NULL;
    }
    void* mem = g_memory_pool.pool;
    g_memory_pool.pool = ((char*)g_memory_pool.pool) + g_memory_pool.element_size;
    g_memory_pool.total_size -= g_memory_pool.element_size;
    pthread_mutex_unlock(&g_memory_pool.lock);
    return mem;
}

