    if (head == NULL) {
        head = pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = pdu;
    }

    pthread_mutex_unlock(&list_lock);
    return 0;
}

int manage_nfa_list(size_t max_size) {
    if (init_memory_pool(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
