double computeMovingAverage(NetworkStats* stats, int n, int M) {
    if (M <= 0 || n < M) return -1.0; // Invalid window size or insufficient data
    double sum = 0;
    for (int i = n - M; i < n; ++i) {
        sum += stats[i].packet_count;
    }
    return sum / M;
}

void manageNetworkStats(int num_entries, int M) {
    if (num_entries <= 0 || M <= 0) {
        printf("Invalid input parameters.\n");
        return;
    }

    NetworkStats* stats = (NetworkStats*)malloc(num_entries * sizeof(NetworkStats));
    if (!stats) {
        perror("Failed to allocate memory for network statistics");
        return;
    }

    // Initialize with dummy data
    srand(time(NULL));  // Seed random number generator
    for (int i = 0; i < num_entries; ++i) {
        stats[i].timestamp = time(NULL) - rand() % 3600; // Random timestamp within the last hour
        stats[i].packet_count = rand() % 100;
        stats[i].byte_count = rand() % 2000; // Up to 2000 bytes
        stats[i].error_rate = (float)(rand() % 10) / 100.0;

        if (stats[i].byte_count > BYTES_THRESHOLD) {
            logOverflow(i, stats[i].byte_count);
        }
    }

    // Compute moving average of the packet count over a sliding window
    for (int i = M - 1; i < num_entries; ++i) {
        double avg = computeMovingAverage(stats, i + 1, M);
        if (avg != -1.0) {
            printf("Moving average at index %d: %.2f\n", i, avg);
        }
    }

    // Free allocated memory
    free(stats);
}

int main() {
    int num_entries = 100;  // Example number of entries
    int window_size = 5;    // Sliding window size

    manageNetworkStats(num_entries, window_size);

    return 0;
}
