    // Assume additional fields for CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list and mutex for thread safety
Node* head = NULL;
pthread_mutex_t lock;

void init_list() {
    pthread_mutex_init(&lock, NULL);
    head = NULL;
}

void log_message(const char* message) {
    // Simple logging mechanism (could be extended to use a dedicated logging library)
    printf("%s\n", message);
}

int allocate_node(NFAPI_CRC_INDICATION_PDU_T data, Node** new_node) {
    *new_node = (Node*)aligned_alloc(64, sizeof(Node)); // Ensure memory alignment
    if (*new_node == NULL) {
        log_message("Memory allocation failed");
        return -1;
    }

    (*new_node)->data = data;
    (*new_node)->next = NULL;
    return 0;
}

int insert_unique(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG || 
            current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&lock);
            return 0; // Duplicate found
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T new_data = {RX_UE_INFORMATION_TAG, RNTI, rand() % 2};
    Node* new_node;

    if (allocate_node(new_data, &new_node) != 0) {
        pthread_mutex_unlock(&lock);
        return -1; // Allocation failed
    }

    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
    log_message("Node inserted");
    return 1; // Successful insertion
}

void free_list() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;

    pthread_mutex_unlock(&lock);
    log_message("List freed");
}

void handle_data_source() {
    // Placeholder for external data source handling logic
    // This function would manage real-time updates, handle transient outages,
    // and ensure data consistency upon reconnection.
}

int main() {
    init_list();

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        int RX_UE_TAG = rand() % 10000;
        int RNTI = rand() % 10000;

        if (insert_unique(RX_UE_TAG, RNTI) != 1) {
            log_message("Failed to insert unique node");
        }
    }

    free_list();
    pthread_mutex_destroy(&lock);

    handle_data_source();

    return 0;
}
