        char *value_str = line + count + 1;

        if (strstr(param.name, "int")) {
            param.type = INT;
            param.value.intValue = atoi(value_str);
        } else if (strstr(param.name, "float")) {
            param.type = FLOAT;
            param.value.floatValue = atof(value_str);
        } else if (strstr(param.name, "string")) {
            param.type = STRING;
            param.value.stringValue = strdup(value_str);
        } else if (strstr(param.name, "array")) {
            // Example array handling: assume space-separated integers
            param.type = ARRAY;
            char *token = strtok(value_str, " ");
            int size = 0, capacity = 10;

            while (token) {
                if (size >= capacity) {
                    capacity *= 2;
                    param.value.arrayValue = realloc(param.value.arrayValue, sizeof(int) * capacity);
                }
                param.value.arrayValue[size++] = atoi(token);
                token = strtok(NULL, " ");
