    RRC_STATE RRC_STATE;
} LTEPHY_RRC_UE_CONFIG;

#define MAX_INSTANCES 1000
#define INIT_SUCCESS_THRESHOLD 0.8

// Function to simulate network latency with a variable delay
void simulate_network_latency() {
    // Simulate varying network conditions with random delays between 10ms and 200ms
    int delay = rand() % 191 + 10; // Random delay between 10 to 200 milliseconds
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = delay * 1000000L; // Convert milliseconds to nanoseconds
    while (nanosleep(&req, &rem) && rem.tv_sec == 0) {
        req = rem;
    }
}

// Function to initialize an array of LTEPHY_RRC_UE_CONFIG structures
LTEPHY_RRC_UE_CONFIG* initialize_ue_config_array(int size, int *reinit_count) {
    if (size <= 0 || size > MAX_INSTANCES) return NULL;

    LTEPHY_RRC_UE_CONFIG *array = malloc(size * sizeof(LTEPHY_RRC_UE_CONFIG));
    if (!array) return NULL;

    srand(time(NULL)); // Seed random number generator

    int successful_initializations = 0;
    for (int i = 0; i < size; ++i) {
        simulate_network_latency();

        LTEPHY_RRC_UE_CONFIG *config = &array[i];
        config->UE_ID = rand() % 10000 + 1; // Random UE_ID between 1 and 10000
        config->CELL_ID = rand() % 1000 + 1; // Random CELL_ID between 1 and 1000

        // Simulate RRC_STATE based on random conditions
        int state_success = rand() % 2;
        if (state_success) {
            config->RRC_STATE = rand() % 3; // Random state: IDLE, CONNECTED, or DISCONNECTED
            successful_initializations++;
        } else {
            config->RRC_STATE = -1; // Indicate failure with an invalid RRC_STATE
        }
    }

    float success_rate = (float)successful_initializations / size;
    if (success_rate < INIT_SUCCESS_THRESHOLD) {
        free(array);
        *reinit_count += 1;
        return initialize_ue_config_array(size, reinit_count); // Retry initialization
    }

    return array;
}

// Function to verify the integrity of initialized data
int verify_ue_config_integrity(LTEPHY_RRC_UE_CONFIG *array, int size) {
    if (!array) return -1;

    int valid_count = 0;
    for (int i = 0; i < size; ++i) {
        LTEPHY_RRC_UE_CONFIG *config = &array[i];
        // Verify RRC_STATE is not corrupted
        if (config->RRC_STATE != -1 && config->UE_ID > 0 && config->CELL_ID > 0) {
            valid_count++;
        }
    }

    return valid_count;
}

int main() {
    int reinit_attempts = 0;

    // Test with different load conditions
    for (int test_size = 0; test_size <= MAX_INSTANCES; test_size += 100) {
        LTEPHY_RRC_UE_CONFIG *config_array = initialize_ue_config_array(test_size, &reinit_attempts);

        if (!config_array) {
            printf("Initialization failed after %d attempts.\n", reinit_attempts);
            continue;
        }

        int valid_entries = verify_ue_config_integrity(config_array, test_size);
        printf("Test size: %d | Valid entries: %d\n", test_size, valid_entries);

        free(config_array); // Free allocated memory
    }

    return 0;
}
