    if (!array) return NULL;
    array->head = NULL;
    array->size = 0;
    return array;
}

// Free the dynamic array and its nodes
void free_dynamic_array(DynamicArray* array) {
    Node *current = array->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    free(array);
}

// Add a new cell or update an existing one based on physicalCellId
int add_or_update_cell(DynamicArray* array, int physicalCellId, NRCellStatus newCell) {
    if (!array) return -1;

    Node **tracer = &array->head;
    while (*tracer) {
        if ((*tracer)->cell.nrPhysicalCellId == physicalCellId) {
            (*tracer)->cell = newCell;
            sort_cells_by_signal_strength(array);
            return 0; // Updated
        }
        tracer = &(*tracer)->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->cell = newCell;
    newNode->next = NULL;
    *tracer = newNode;
    array->size++;

    sort_cells_by_signal_strength(array);
    return 1; // Added
}

// Find a node by physicalCellId
Node* find_node_by_physical_id(Node* node, int physicalCellId) {
    while (node) {
        if (node->cell.nrPhysicalCellId == physicalCellId)
            return node;
        node = node->next;
    }
    return NULL;
}

// Sort cells in the array by signal strength using a simple insertion sort
void sort_cells_by_signal_strength(DynamicArray* array) {
    if (!array || !array->head) return;

    Node *sorted = NULL, *current = array->head, *nextNode;

    while (current) {
        nextNode = current->next;

        // Insert into sorted list
        if (!sorted || sorted->cell.measurementResult.signalStrength <= current->cell.measurementResult.signalStrength) {
            current->next = sorted;
            sorted = current;
        } else {
            Node *tracer = sorted;
            while (tracer->next && tracer->next->cell.measurementResult.signalStrength > current->cell.measurementResult.signalStrength)
                tracer = tracer->next;

            current->next = tracer->next;
            tracer->next = current;
        }

        current = nextNode;
    }

    array->head = sorted;
}

