#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeNode(Node* node) {
    free(node);
}

void destroyList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int generateRandomCRCFlag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T createPDU(unsigned long rxUEInfoTag, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rxUEInfoTag;
    pdu.RNTI = rnti;
    pdu.crcIndicationRel8Tag.crcFlag = generateRandomCRCFlag();
    return pdu;
}

void insertAtEnd(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }

    list->tail = newNode;
    pthread_mutex_unlock(&list->lock);
}

void deleteNode(DoublyLinkedList* list, Node* nodeToDelete) {
    pthread_mutex_lock(&list->lock);

    if (nodeToDelete == NULL) return;

    if (nodeToDelete->prev != NULL) {
        nodeToDelete->prev->next = nodeToDelete->next;
    } else {
        list->head = nodeToDelete->next;
    }

    if (nodeToDelete->next != NULL) {
        nodeToDelete->next->prev = nodeToDelete->prev;
    } else {
        list->tail = nodeToDelete->prev;
    }

    freeNode(nodeToDelete);
    pthread_mutex_unlock(&list->lock);
}

void reverseList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp = NULL;
    while (current != NULL) {
        temp = current->prev;
        current->prev = current->next;
        current->next = temp;
        current = current->prev;
    }

    if (temp != NULL) {
        list->head = temp->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void traverseList(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void serializeList(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserializeList(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insertAtEnd(list, pdu);
    }

    fclose(file);
}

void generateAndPopulateList(DoublyLinkedList* list, int N) {
    if (N <= 0) return;

    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = createPDU(rand(), rand());
        insertAtEnd(list, pdu);
    }

    pthread_mutex_unlock(&list->lock);
}

void printPDU(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %lu, RNTI: %hu, CRCFLAG: %u\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.crcIndicationRel8Tag.crcFlag);
}

int main() {
    srand(time(NULL));

    DoublyLinkedList* list = createList();
    generateAndPopulateList(list, 10);

    printf("Original List:\n");
    traverseList(list, printPDU);

    reverseList(list);
    printf("\nReversed List:\n");
    traverseList(list, printPDU);

    serializeList(list, "list.dat");

    DoublyLinkedList* newList = createList();
    deserializeList(newList, "list.dat");

    printf("\nDeserialized List:\n");
    traverseList(newList, printPDU);

    destroyList(list);
    destroyList(newList);

    return 0;
}
