static void resize_array() {
    if (count < capacity) return;
    capacity *= 2; // Double the size for efficiency during growth
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(pdu_array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
