    if (index >= capacity || count == 0 && index != 0) return false;

    if (index < count) { // Update existing entry
        pdu_array[index].ue_info.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_array[index].ue_info.RNTI = RNTI;
        pdu_array[index].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
