        if (index >= capacity) {
            resize_array();
        }
        pdu_array[index].ue_info.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_array[index].ue_info.RNTI = RNTI;
        pdu_array[index].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        if (index >= count) {
            count++;
        }
    }

    return true;
}

// Function to retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T* get_pdu_by_index(unsigned int index) {
    if (index < count) {
        return &pdu_array[index];
    } else {
        return NULL; // Index out of bounds
    }
}

// Function to safely deallocate memory
void free_resources() {
