    struct {
        _Atomic(int) CRCFLAG; // Atomic to ensure thread-safe updates
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ResizableList;

ResizableList* create_list() {
    ResizableList *list = malloc(sizeof(ResizableList));
    if (!list) return NULL;

    list->capacity = INITIAL_SIZE;
    list->count = 0;
    list->data = calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    return list;
}

void destroy_list(ResizableList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        pthread_cond_destroy(&list->cond);
        free(list->data);
        free(list);
    }
}

static void resize_list_if_needed(ResizableList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return; // Handle error as needed
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

static void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int tag, int rnti) {
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pthread_mutex_lock(&pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
    // Random CRCFLAG for demonstration
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    pthread_mutex_unlock(&pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

void add_pdu(ResizableList *list, int tag, int rnti) {
    pthread_mutex_lock(&list->lock);

    resize_list_if_needed(list);

    initialize_pdu(&list->data[list->count], tag, rnti);
    list->count++;

    // Signal any waiting threads
    pthread_cond_signal(&list->cond);

    pthread_mutex_unlock(&list->lock);
}

void* process_pdu(void *arg) {
    ResizableList *list = (ResizableList*) arg;

    while (1) { // Replace with condition or interrupt for graceful shutdown
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pthread_mutex_lock(&list->lock);

        while (list->count == 0) {
            // Wait for data to process, handle spurious wakeups
            pthread_cond_wait(&list->cond, &list->lock);
        }

        memcpy(&pdu, &list->data[0], sizeof(NFAPI_CRC_INDICATION_PDU_T));

        list->count--;
        memmove(list->data, list->data + 1, (list->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pthread_mutex_unlock(&list->lock);

        // Simulate processing
        printf("Processing PDU with RNTI: %d, CRCFLAG: %d\n", pdu.RNTI, atomic_load(&pdu.CRC_INDICATION_REL8_TAG.CRCFLAG));
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    ResizableList *list = create_list();
    if (!list) return EXIT_FAILURE;

    pthread_t producer_thread;
    pthread_t consumer_threads[4]; // For example, 4 consumer threads

    if (pthread_create(&producer_thread, NULL, (void*) process_pdu, list)) {
        destroy_list(list);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (pthread_create(&consumer_threads[i], NULL, (void*) process_pdu, list)) {
            destroy_list(list);
            return EXIT_FAILURE;
        }
    }

    // Simulate adding data
    for (int i = 0; i < 20; i++) {
        add_pdu(list, rand() % 100, rand() % 1000);
    }

    pthread_join(producer_thread, NULL);

    for (int i = 0; i < 4; i++) {
        pthread_cancel(consumer_threads[i]);
        pthread_join(consumer_threads[i], NULL);
    }

    destroy_list(list);
    return EXIT_SUCCESS;
}
