#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    uint16_t RNTI;
    // Other RX_UE_INFORMATION_TAG fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other CRC_INDICATION_REL8_TAG fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t timestamp;
    uint64_t unique_id;
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
uint64_t id_counter = 0;

void get_current_timestamp(uint32_t *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = localtime(&rawtime);
    *timestamp = mktime(info);
}

uint64_t generate_unique_id() {
    static pthread_mutex_t id_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&id_lock);
    uint64_t id = ++id_counter;
    pthread_mutex_unlock(&id_lock);
    return id;
}

void initialize_list_with_n_structures(int n) {
    pthread_mutex_lock(&list_lock);

    if (head != NULL) {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
    } else {
        head = malloc(sizeof(Node));
        if (!head) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&list_lock);
            return;
        }
    }

    uint16_t last_rnti = 0;

    for (int i = 0; i < n; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            // Cleanup and exit on allocation failure
            break;
        }

        new_node->data.ue_info.RNTI = (uint16_t)(rand() % 0xFFFF);

        while(new_node->data.ue_info.RNTI == last_rnti) {
            new_node->data.ue_info.RNTI = (uint16_t)(rand() % 0xFFFF);
        }

        last_rnti = new_node->data.ue_info.RNTI;

        get_current_timestamp(&new_node->data.timestamp);
        new_node->data.unique_id = generate_unique_id();
        new_node->data.crc_indication.CRCFLAG = rand() & 1;

        pthread_mutex_init(&new_node->data.lock, NULL);

        if (head == NULL) {
            head = new_node;
        } else {
            Node *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }

        // Placeholder for logging integration
    }

    pthread_mutex_unlock(&list_lock);
}

// Example cleanup function to free the list
void free_list() {
    pthread_mutex_lock(&list_lock);

    Node *current = head;
    while (current != NULL) {
        Node *next_node = current->next;
        pthread_mutex_destroy(&current->data.lock);
        free(current);
        current = next_node;
    }

    head = NULL;

    pthread_mutex_unlock(&list_lock);
}

int main() {
    // Example usage
    initialize_list_with_n_structures(10);

    // Perform operations...

    free_list();
    return 0;
}
