    ConnectionContext *contexts[MAX_CONNECTIONS];
    size_t count;
} ConnectionPool;

int initialize_connection_pool(ConnectionPool *pool) {
    pool->count = 0;
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        pool->contexts[i] = NULL;
    }
    return 0;
}

ConnectionContext* allocate_context() {
    ConnectionContext *context = (ConnectionContext *)malloc(sizeof(ConnectionContext));
    if (!context) {
        perror("Failed to allocate connection context");
        return NULL;
    }
    memset(context, 0, sizeof(ConnectionContext));
    context->socket_fd = -1;
    time(&context->last_activity);
    return context;
}

int add_connection_to_pool(ConnectionPool *pool, ConnectionContext *context) {
    if (pool->count >= MAX_CONNECTIONS) {
        printf("Connection pool is full\n");
        free(context);
        return -1;
    }

    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!pool->contexts[i]) {
            pool->contexts[i] = context;
            pool->count++;
            return 0;
        }
    }

    free(context);
    return -1;
}

void remove_inactive_connections(ConnectionPool *pool, time_t timeout) {
    time_t now = time(NULL);

    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool->contexts[i]) {
            if (difftime(now, pool->contexts[i]->last_activity) > timeout) {
                close(pool->contexts[i]->socket_fd);
                free(pool->contexts[i]);
                pool->contexts[i] = NULL;
                pool->count--;
            }
        }
    }
}

void cleanup_connection_pool(ConnectionPool *pool) {
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool->contexts[i]) {
            close(pool->contexts[i]->socket_fd);
            free(pool->contexts[i]);
            pool->contexts[i] = NULL;
        }
    }
    pool->count = 0;
}

int main() {
    ConnectionPool pool;
    initialize_connection_pool(&pool);

    // Example of adding a new connection context
    ConnectionContext *new_context = allocate_context();
    if (new_context) {
        add_connection_to_pool(&pool, new_context);
    }

    // Periodically remove inactive connections
    while (1) {
        remove_inactive_connections(&pool, 300); // Timeout of 5 minutes
        sleep(60); // Check every minute
    }

    cleanup_connection_pool(&pool);
    return 0;
}
