['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define structures
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct Node* next;
} Node;

// List management structure
typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
CRCList* create_crc_list();
int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
void clear_and_free_list(CRCList* list);
int verify_crc_list_integrity(const CRCList* list);
Node* get_node_by_index(const CRCList* list, size_t index);

// Create and initialize the list
CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add an element to the list
int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failure
    }

    new_node->data = pdu;
    new_node->crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Clear and free all allocated memory
void clear_and_free_list(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Verify integrity of the list
int verify_crc_list_integrity(const CRCList* list) {
    if (!list) return -1;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current) {
        // Check if CRCFLAG is set; this example assumes non-zero as valid
        if (current->crc_tag.CRCFLAG == 0) {
            pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
            return -2; // Integrity check failed
        }
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return 0; // All elements have valid CRCFLAG
}

// Get node by index for iteration purposes
Node* get_node_by_index(const CRCList* list, size_t index) {
    if (!list || index >= list->count) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return current;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    CRCList* crc_list = create_crc_list();
    if (!crc_list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return -1;
    }

    for (size_t i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() };
        if (add_to_crc_list(crc_list, pdu) != 0) {
            fprintf(stderr, "Failed to add element %zu\n", i);
        }
    }

    if (verify_crc_list_integrity(crc_list) == 0) {
        printf("CRC list integrity verified.\n");
    } else {
        fprintf(stderr, "CRC list integrity check failed.\n");
    }

    clear_and_free_list(crc_list);

    return 0;
}
```

This code provides a thread-safe implementation of a linked list to manage `NFAPI_CRC_INDICATION_PDU_T` structures with random CRC flags. It includes functions for adding elements, verifying the list's integrity, and clearing/freeing memory. The design ensures efficient memory usage and low-latency processing suitable for high-throughput environments.']

