// Global memory management variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned char *memory_pool = NULL;
static size_t pool_size = 0;

// Function to initialize the memory pool
void init_memory_pool(size_t max_elements, size_t struct_size) {
    pthread_mutex_lock(&mutex);
    if (pool_size < max_elements * struct_size) {
        free(memory_pool);
        pool_size = max_elements * struct_size;
        memory_pool = (unsigned char *)malloc(pool_size);
        if (!memory_pool) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to create and populate the NFAPI_CRC_INDICATION_PDU_T array
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(size_t n, size_t struct_size) {
    if (n * struct_size > pool_size) {
        fprintf(stderr, "Requested allocation exceeds memory budget\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Allocate from the pre-allocated pool
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool;

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < n; ++i) {
        // Populate RX_UE_INFORMATION_TAG and RNTI
        ((CRC_INDICATION_REL8_TAG_T*)&array[i].CRC_INDICATION_REL8_TAG)->RX_UE_INFORMATION_TAG = rand() % 1000;
        ((CRC_INDICATION_REL8_TAG_T*)&array[i].CRC_INDICATION_REL8_TAG)->RNTI = rand() % 1000;

        // Set CRCFLAG randomly
        array[i].CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&mutex);
    return array;
}

// Function to release all allocated resources
void release_resources() {
    pthread_mutex_lock(&mutex);
    free(memory_pool);
    memory_pool = NULL;
    pool_size = 0;
    pthread_mutex_unlock(&mutex);
}

int main() {
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t max_elements = 100; // Maximum elements the system can handle

    init_memory_pool(max_elements, struct_size);

    size_t n = 50; // Number of elements to create
    NFAPI_CRC_INDICATION_PDU_T* array = create_and_populate_array(n, struct_size);

    if (array) {
        for (size_t i = 0; i < n; ++i) {
            printf("Element %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
                   i,
                   array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG,
                   array[i].CRC_INDICATION_REL8_TAG.RNTI,
                   array[i].CRCFLAG);
        }
    }

    release_resources();
    return 0;
}
