// Utility function to generate a random CRCFLAG
uint16_t generate_random_crcflag() {
    return rand() % 65536; // Random value between 0 and 65535
}

// Initialize NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* init_nfaapi_crc_indication_pdu(uint64_t rx_ue_info, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rx_ue_info;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION.CRCFLAG = generate_random_crcflag();

    return pdu;
}

// Initialize a UEContext structure
UEContext* init_ue_context(int ueid, const char* rrc_state) {
    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    if (!context) return NULL;

    context->UEID = ueid;
    context->RRC_STATE = strdup(rrc_state);
    context->MeasurementReport = NULL;
    context->MeasurementCount = 0;

    return context;
}

// Add a measurement report entry to UEContext
int add_measurement_report(UEContext* context, int measurement_id, float sinr, float rsrp) {
    if (!context || !context->RRC_STATE) return -1;

    context->MeasurementReport = (MEASUREMENT_REPORT_ENTRY_T*)realloc(context->MeasurementReport,
        (context->MeasurementCount + 1) * sizeof(MEASUREMENT_REPORT_ENTRY_T));

    if (!context->MeasurementReport) return -1;

    MEASUREMENT_REPORT_ENTRY_T* entry = &context->MeasurementReport[context->MeasurementCount];
    entry->MEASUREMENT_ID = measurement_id;
    entry->SINR = sinr;
    entry->RSRP = rsrp;
    context->MeasurementCount++;

    return 0;
}

// Serialize UEContext data to a binary file
int serialize_ue_contexts(UEContext* contexts, size_t count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        UEContext* context = &contexts[i];

        fwrite(&context->UEID, sizeof(int), 1, file);
        size_t rrc_state_len = strlen(context->RRC_STATE) + 1;
        fwrite(&rrc_state_len, sizeof(size_t), 1, file);
        fwrite(context->RRC_STATE, sizeof(char), rrc_state_len, file);

        fwrite(&context->MeasurementCount, sizeof(size_t), 1, file);

        for (size_t j = 0; j < context->MeasurementCount; ++j) {
            MEASUREMENT_REPORT_ENTRY_T* entry = &context->MeasurementReport[j];

            fwrite(&entry->MEASUREMENT_ID, sizeof(int), 1, file);
            fwrite(&entry->SINR, sizeof(float), 1, file);
            fwrite(&entry->RSRP, sizeof(float), 1, file);
        }
    }

    fclose(file);
    return 0;
}

// Free UEContext resources
void free_ue_context(UEContext* context) {
    if (!context) return;

    free(context->RRC_STATE);
    free(context->MeasurementReport);
    free(context);
}

int main() {
    srand(time(NULL));

    size_t ue_count = 5; // Example count, can be dynamic
    UEContext* contexts[MAX_UE_CONTEXT];

    for (size_t i = 0; i < ue_count; ++i) {
        contexts[i] = init_ue_context(i, "RRC_CONNECTED");

        add_measurement_report(contexts[i], 1, -10.5f, -110.2f);
        add_measurement_report(contexts[i], 2, -15.3f, -120.7f);
    }

    if (serialize_ue_contexts((UEContext*)contexts, ue_count, "ue_data.bin") != 0) {
        fprintf(stderr, "Serialization failed.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < ue_count; ++i) {
        free_ue_context(contexts[i]);
    }

    return EXIT_SUCCESS;
}
```

