### JavaScript Code

```javascript
function copyDataChunks(chunks, numBytes) {
    const resultBuffer = Buffer.allocUnsafe(numBytes);
    let bytesRead = 0;

    for (const chunk of chunks) {
        if (bytesRead >= numBytes) break; // If we've copied enough data, exit early

        const bytesToCopy = Math.min(chunk.length, numBytes - bytesRead);
        chunk.copy(resultBuffer, bytesRead, 0, bytesToCopy);

        bytesRead += bytesToCopy;
    }

    return resultBuffer.slice(0, bytesRead); // Return only the portion that was actually filled
}
```

