#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int rnti; // Radio Network Temporary Identifier
    char *ue_config; // UE configuration parameters (variable size)
} LTE_UE_Context;

typedef struct Node {
    LTE_UE_Context context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ContextList;

// Initialize the context list
ContextList* init_context_list() {
    ContextList* list = (ContextList*)malloc(sizeof(ContextList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new UE context to the list
void add_ue_context(ContextList* list, LTE_UE_Context context) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->context = context;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

// Retrieve a UE context by RNTI
LTE_UE_Context* get_ue_context(ContextList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.rnti == rnti) {
            LTE_UE_Context* context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
            *context = current->context;
            pthread_mutex_unlock(&list->lock);
            return context;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Delete a UE context by RNTI
void delete_ue_context(ContextList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->context.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) { // Head node needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->context.ue_config);  // Free the variable-sized configuration
    free(current);

    pthread_mutex_unlock(&list->lock);
}

// Cleanup and delete all contexts in the list
void destroy_context_list(ContextList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current->context.ue_config);
        free(current);
        current = nextNode;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Handle external data source for UE configuration
char* fetch_ue_configuration(int rnti) {
    // Simulate variable response time and potential failure
    char* config = (char*)malloc(256);  // Assume max size, adjust as necessary
    if (!config) return NULL;

    // Fetching logic here...
    snprintf(config, 256, "UE_Configuration_for_RNTI_%d", rnti);

    // Simulate delay or failure handling
    if (/* condition for failure */) {
        free(config);
        return NULL;
    }

    return config;
}

// Example usage function
void example_usage() {
    ContextList* list = init_context_list();

    int rnti1 = 1000;
    char* ue_config1 = fetch_ue_configuration(rnti1);
    if (ue_config1) {
        LTE_UE_Context context1 = {rnti1, ue_config1};
        add_ue_context(list, context1);

        // Retrieve and print
        LTE_UE_Context* retrieved_context = get_ue_context(list, rnti1);
        if (retrieved_context) {
            printf("Retrieved RNTI: %d\n", retrieved_context->rnti);
            free(retrieved_context->ue_config);
            free(retrieved_context);
        }

        // Delete context
        delete_ue_context(list, rnti1);

        // Cleanup
        destroy_context_list(list);
    }
}

int main() {
    example_usage();
    return 0;
}
