} NFAPI_CRC_INDICATION_PDU_T;

extern int fetchRealTimeRNTI(void);
extern void logStatusMessage(const char* message);

#define MAX_MEMORY_THRESHOLD_BYTES 1024 * 1024 // Example threshold: 1 MB
#define PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define MAX_PDUS (MAX_MEMORY_THRESHOLD_BYTES / PDU_SIZE)

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void managePDUs(unsigned int M) {
    if (M > MAX_PDUS) {
        logStatusMessage("Requested PDUs exceed maximum allowed based on memory threshold.");
        M = MAX_PDUS;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(M * PDU_SIZE);
    if (!pdus) {
        logStatusMessage("Failed to allocate memory for PDUs.");
        return;
    }

    unsigned int num_pdus = 0;
    unsigned int last_rnti = 0;
    bool exceeded_memory_limit = false;

    while (num_pdus < M) {
        pthread_mutex_lock(&mutex);

        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[num_pdus];

        // Fetch real-time RNTI with minimal latency
        int rnti = fetchRealTimeRNTI();

        if (rnti == last_rnti) {
            pthread_mutex_unlock(&mutex);
            continue;  // Skip this iteration to avoid consecutive duplicate RNTIs
        }

        pdu-> /* fill RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with rnti */;
        pdu-> /* set CRCFLAG randomly */;

        last_rnti = rnti;
        num_pdus++;

        // Check memory usage
        size_t used_memory = num_pdus * PDU_SIZE;
        if (used_memory > 0.9 * MAX_MEMORY_THRESHOLD_BYTES) {
            exceeded_memory_limit = true;
            logStatusMessage("Memory usage exceeds 90% of threshold, reducing PDUs creation.");
            break;  // Stop creating more PDUs
        }

        pthread_mutex_unlock(&mutex);
    }

    if (exceeded_memory_limit && num_pdus > M * 0.1) {
        logStatusMessage("Reducing number of PDUs due to memory constraints.");
        free(pdus);  // Free allocated memory since we are not using all allocated slots
        pdus = malloc((M / 2) * PDU_SIZE);
        if (pdus && num_pdus > M / 2) {
            memcpy(pdus, &pdus[0], ((M / 2) * PDU_SIZE));
            num_pdus = M / 2;
        }
    }

    logStatusMessage("PDU management completed.");

    free(pdus);  // Ensure all allocated memory is freed
}

// Function to simulate the program's execution
int main() {
    managePDUs(1000);  // Example usage with up to 1000 PDUs
    return 0;
}
