#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_RNTI 0x7FFF
#define NUM_THREADS 4
#define EXPORT_FILE "export_data.txt"

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int success_count;
    int failure_count;
} ListManager;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void init_list(ListManager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->success_count = 0;
    manager->failure_count = 0;
}

int is_valid_rnti(uint16_t rnti) {
    return rnti > 0 && rnti <= MAX_RNTI;
}

NFAPI_CRC_INDICATION_PDU_T generate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL) ^ pthread_self());
    pdu.RX_UE_INFORMATION_TAG = rand() % 10000; // Example range
    pdu.RNTI = rand() % (MAX_RNTI + 1);
    pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu.CRCFLAG = rand() & 1;
    return pdu;
}

void add_pdu(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid_rnti(pdu.RNTI)) {
        pthread_mutex_lock(&manager->lock);
        manager->failure_count++;
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Node* new_node = create_node(pdu);
    if (!new_node) return;

    pthread_mutex_lock(&manager->lock);
    new_node->next = manager->head;
    manager->head = new_node;
    manager->success_count++;
    pthread_mutex_unlock(&manager->lock);
}

void* process_pdus(void* arg) {
    ListManager* manager = (ListManager*)arg;
    for (int i = 0; i < 10000; ++i) { // Example processing count
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_pdu();
        add_pdu(manager, pdu);
    }
    return NULL;
}

void export_data(ListManager* manager) {
    FILE* file = fopen(EXPORT_FILE, "w");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);
    Node* current = manager->head;
    while (current) {
        fprintf(file, "%u %u %u %d\n",
                current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI,
                current->data.CRC_INDICATION_REL8_TAG,
                current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);

    fprintf(file, "Success: %d, Failure: %d\n", manager->success_count, manager->failure_count);
    fclose(file);
}

void free_list(ListManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    ListManager manager;
    init_list(&manager);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_pdus, &manager);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    export_data(&manager);
    free_list(&manager);

    return 0;
}
```

