        return NULL; // Invalid input size
    }

    pthread_mutex_lock(&mutex);

    time_t current_time = time(NULL);
    if (current_time - last_reset_time >= reset_interval) {
        processed_count = 0;
        last_reset_time = current_time;
    }

    if (processed_count + count > MAX_STRUCTURES) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Exceeds the allowed limit
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
