    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int updateCRCFlag(LinkedList* list, unsigned long rnti, char new_crc_flag) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Element not found
    }

    strcpy(current->data.CRC_INDICATION_REL8_TAG, &new_crc_flag);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void initCache(Cache* cache) {
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

int cachePut(Cache* cache, unsigned long rnti, char crcFlag) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&cache->lock);
        return -1; // Cache is full
    }

    for (int i = 0; i < cache->size; ++i) {
        if (cache->entries[i].RNTI == rnti) {
            cache->entries[i].CRCFLAG = crcFlag;
            pthread_mutex_unlock(&cache->lock);
            return 0;
        }
    }

    CacheEntry newEntry = {rnti, crcFlag};
    cache->entries[cache->size++] = newEntry;

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

char* cacheGet(Cache* cache, unsigned long rnti) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < cache->size; ++i) {
        if (cache->entries[i].RNTI == rnti) {
            char* crcFlagStr = malloc(2 * sizeof(char));
            sprintf(crcFlagStr, "%c", cache->entries[i].CRCFLAG);
            pthread_mutex_unlock(&cache->lock);
            return crcFlagStr;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Not found
}

void destroyCache(Cache* cache) {
    pthread_mutex_destroy(&cache->lock);
}
```

This code defines a thread-safe linked list to manage `NFAPI_CRC_INDICATION_PDU_T` structures, along with a simple cache mechanism. The list operations include adding, removing, and updating elements based on `RNTI`. The cache helps reduce redundant lookups for frequently accessed UE information. Error checking is incorporated for memory allocation failures and invalid inputs.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

// Definitions for structures
typedef struct {
    uint8_t data[16];  // Example structure, fill as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t rnti;
    uint8_t crc_flag;
    struct CRC_INDICATION_REL8_TAG* next;
} CRC_INDICATION_REL8_TAG;

typedef struct Node {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG* crc_ind;
    struct Node* next;
} Node;

// Thread-safe linked list structure
typedef struct {
    Node* head;
    pthread_rwlock_t lock;
} ThreadSafeLinkedList;

// Function prototypes
ThreadSafeLinkedList* create_thread_safe_list(int N);
void free_thread_safe_list(ThreadSafeLinkedList* list);
int serialize_list(const char* filename, const ThreadSafeLinkedList* list);
int deserialize_list(const char* filename, ThreadSafeLinkedList* list);

// Helper functions for logging and error handling
void log_message(const char* message);

ThreadSafeLinkedList* create_thread_safe_list(int N) {
    if (N <= 0) return NULL;

    ThreadSafeLinkedList* list = malloc(sizeof(ThreadSafeLinkedList));
    if (!list) {
        log_message("Memory allocation failed for list.");
        return NULL;
    }

    pthread_rwlock_init(&list->lock, NULL);
    list->head = NULL;

    // Populate the linked list
    Node* current = NULL;
    for (int i = 0; i < N; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            log_message("Memory allocation failed for node.");
            free_thread_safe_list(list);
            return NULL;
        }

        // Example initialization
        memset(&new_node->ue_info, 0, sizeof(RX_UE_INFORMATION_TAG)); // Populate as needed
        new_node->rnti = rand(); // Random RNTI

        new_node->crc_ind = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!new_node->crc_ind) {
            log_message("Memory allocation failed for CRC indication.");
            free(new_node);
            free_thread_safe_list(list);
            return NULL;
        }

        new_node->crc_ind->rnti = rand(); // Example RNTI
        new_node->crc_ind->crc_flag = rand() % 2; // Random CRC flag
        new_node->crc_ind->next = NULL;

        pthread_rwlock_wrlock(&list->lock);
        if (!list->head) {
            list->head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
        pthread_rwlock_unlock(&list->lock);

        log_message("Node inserted into the list.");
    }

    return list;
}

void free_thread_safe_list(ThreadSafeLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current->crc_ind);
        free(current);
        current = next_node;
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);

    log_message("List and resources have been freed.");
}

int serialize_list(const char* filename, const ThreadSafeLinkedList* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return -1;
    }

    pthread_rwlock_rdlock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&current->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&(current->rnti), sizeof(uint16_t), 1, file);

        CRC_INDICATION_REL8_TAG* crc_current = current->crc_ind;
        while (crc_current) {
            fwrite(&(crc_current->rnti), sizeof(uint16_t), 1, file);
            fwrite(&(crc_current->crc_flag), sizeof(uint8_t), 1, file);
            crc_current = crc_current->next;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);

    fclose(file);
    log_message("List serialized successfully.");

    return 0;
}

int deserialize_list(const char* filename, ThreadSafeLinkedList* list) {
    if (!filename || !list) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        return -1;
    }

    pthread_rwlock_wrlock(&list->lock);
    free_thread_safe_list(list);  // Clear existing list

    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind;

    while (fread(&ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file) == 1) {
        fread(&rnti, sizeof(uint16_t), 1, file);

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            log_message("Memory allocation failed for node during deserialization.");
            fclose(file);
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }

        memcpy(&new_node->ue_info, &ue_info, sizeof(RX_UE_INFORMATION_TAG));
        new_node->rnti = rnti;

        new_node->crc_ind = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!new_node->crc_ind) {
            log_message("Memory allocation failed for CRC indication during deserialization.");
            free(new_node);
            fclose(file);
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }

        while (fread(&rnti, sizeof(uint16_t), 1, file) == 1 &&
               fread(&crc_ind.crc_flag, sizeof(uint8_t), 1, file) == 1) {
            CRC_INDICATION_REL8_TAG* current_crc = new_node->crc_ind;
            while (current_crc->next != NULL) {
                current_crc = current_crc->next;
            }

            CRC_INDICATION_REL8_TAG* new_crc = malloc(sizeof(CRC_INDICATION_REL8_TAG));
            if (!new_crc) {
                log_message("Memory allocation failed for additional CRC indication during deserialization.");
                free_thread_safe_list(list);
                fclose(file);
                pthread_rwlock_unlock(&list->lock);
                return -1;
            }

            new_crc->rnti = rnti;
            new_crc->crc_flag = crc_ind.crc_flag;
            new_crc->next = NULL;

            current_crc->next = new_crc;
        }

        if (list->head == NULL) {
            list->head = new_node;
        } else {
            Node* temp = list->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    fclose(file);

    log_message("List deserialized successfully.");

    return 0;
}

void log_message(const char* message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

// The function to create a new state list from FSA
int* create_state_list(const int* states, int num_states, const void* fsa, int last_state) {
    if (!states || !fsa || num_states <= 0) return NULL;

    // Example implementation: Assume `fsa` is structured and accessible
    // Here we just return a copy of the input state array for illustration

    int* new_list = malloc(num_states * sizeof(int));
    if (!new_list) {
        log_message("Memory allocation failed for state list.");
        return NULL;
    }

    memcpy(new_list, states, num_states * sizeof(int));

    log_message("State list created successfully.");

