void populate_network_event_logs(LogManager* log_manager, size_t log_count) {
    if (!log_manager || log_count == 0 || log_count > LOG_ENTRY_MAX_COUNT) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    pthread_mutex_lock(&log_manager->lock);

    // Free existing entries if reinitialization is needed
    if (log_manager->entries) {
        memory_pool_free(log_manager->entries);
    }

    size_t total_size = log_count * sizeof(NetworkEventLogEntry);
    void* mem_ptr = memory_pool_alloc(total_size);

    if (!mem_ptr) {
        fprintf(stderr, "Out of memory.\n");
        pthread_mutex_unlock(&log_manager->lock);
        return;
    }

    log_manager->entries = (NetworkEventLogEntry*)mem_ptr;

    for (size_t i = 0; i < log_count; ++i) {
        NetworkEventLogEntry* entry = &log_manager->entries[i];

        // Simulate populating the entry with valid data
        entry->RX_UE_INFORMATION_TAG = rand() % 10000;
        entry->RNTI = rand() % 1000;
        entry->CRC_INDICATION_REL8_TAG = rand() % 1000;
        entry->CRCFLAG = rand() & 1;

        // Fill details with some example data
        snprintf(entry->details, MAX_EVENT_DETAILS_SIZE, "Log Entry #%zu", i);
    }

    log_manager->count = log_count;

    pthread_mutex_unlock(&log_manager->lock);
}

void initialize_log_manager(LogManager* log_manager) {
    if (!log_manager) return;

    memset(log_manager, 0, sizeof(*log_manager));
    pthread_mutex_init(&log_manager->lock, NULL);
}

void cleanup_log_manager(LogManager* log_manager) {
    if (!log_manager) return;

    pthread_mutex_lock(&log_manager->lock);

    if (log_manager->entries) {
        memory_pool_free(log_manager->entries);
        log_manager->entries = NULL;
    }

    pthread_mutex_unlock(&log_manager->lock);
    pthread_mutex_destroy(&log_manager->lock);
}
