    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(CRC_LIST* list) {
    if (list) {
        pthread_mutex_lock(&list->lock);
        free(list->data);
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int resize_if_needed(CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

