}

void remove_expired_entries(CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    size_t i = 0;

    while (i < list->size) {
        if ((current_time - list->data[i].timestamp) > THRESHOLD_AGE_SECONDS || !validate_crc_entry(&list->data[i])) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->data[j] = list->data[j + 1];
            }
            --list->size;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void* update_from_external_source(void* arg) {
    CRC_LIST* list = (CRC_LIST*)arg;

    // Simulate latency and potential data source unavailability
    while (1) {
