// Define a custom message structure
typedef struct {
    int sender_id;
    time_t timestamp;
    char *payload;
} Message;

// Node for linked list
typedef struct MessageNode {
    Message msg;
    struct MessageNode* next;
} MessageNode;

// List to manage messages with thread-safe operations
typedef struct {
    MessageNode* head;
    pthread_mutex_t lock; // Mutex for thread safety
} MessageList;

// Function to initialize the message list
void initMessageList(MessageList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to free a single message node
void freeMessageNode(MessageNode* node) {
    if (node != NULL) {
        free(node->msg.payload);
        free(node);
    }
}

// Function to add a new message
void addMessage(MessageList* list, int sender_id, time_t timestamp, const char* payload) {
    pthread_mutex_lock(&list->lock);

    MessageNode* newNode = (MessageNode*)malloc(sizeof(MessageNode));
    if (!newNode) {
        perror("Failed to allocate memory");
        return;
    }

    newNode->msg.sender_id = sender_id;
    newNode->msg.timestamp = timestamp;
    size_t payload_length = strlen(payload) + 1;
    newNode->msg.payload = (char*)malloc(payload_length);
    if (!newNode->msg.payload) {
        perror("Failed to allocate memory for payload");
        free(newNode);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    strcpy(newNode->msg.payload, payload);

    // Add the new node at the beginning of the list
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve messages within a specified time range
void retrieveMessages(MessageList* list, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        if (current->msg.timestamp >= start_time && current->msg.timestamp <= end_time) {
            printf("Sender ID: %d, Timestamp: %ld, Payload: %s\n",
                   current->msg.sender_id, current->msg.timestamp, current->msg.payload);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free the entire message list
void freeMessageList(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        MessageNode* next = current->next;
        freeMessageNode(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    // Example usage
    MessageList msg_list;
    initMessageList(&msg_list);

    time_t now = time(NULL);
    addMessage(&msg_list, 1, now - 100, "Hello from sender 1");
    addMessage(&msg_list, 2, now - 50, "Hello from sender 2");

    printf("Messages within last 60 seconds:\n");
    retrieveMessages(&msg_list, now - 60, now);

    freeMessageList(&msg_list);
    return 0;
}
