```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // To track the age of the entry
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} Deque;

Deque* create_deque() {
    Deque* deque = (Deque*)malloc(sizeof(Deque));
    if (!deque) return NULL;
    deque->head = deque->tail = NULL;
    deque->size = 0;
    pthread_mutex_init(&deque->lock, NULL);
    return deque;
}

void destroy_deque(Deque* deque) {
    Node* current = deque->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&deque->lock);
    free(deque);
}

int is_full(Deque* deque) {
    return deque->size >= MAX_LIST_SIZE;
}

void add_to_deque(Deque* deque, NFAPI_CRC_INDICATION_PDU_T data) {
    if (is_full(deque)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&deque->lock);

    if (!deque->head) {
        deque->head = deque->tail = new_node;
    } else {
        deque->tail->next = new_node;
        new_node->prev = deque->tail;
        deque->tail = new_node;
    }

    deque->size++;
    pthread_mutex_unlock(&deque->lock);
}

NFAPI_CRC_INDICATION_PDU_T remove_oldest(Deque* deque) {
    NFAPI_CRC_INDICATION_PDU_T data = {0};
    if (!deque->head) return data;

    Node* oldest = deque->head;
    pthread_mutex_lock(&deque->lock);

    if (oldest == deque->tail) {
        deque->head = deque->tail = NULL;
    } else {
        deque->head = oldest->next;
        deque->head->prev = NULL;
    }

    data = oldest->data;
    free(oldest);
    deque->size--;

    pthread_mutex_unlock(&deque->lock);
    return data;
}

void remove_newest_if_needed(Deque* deque) {
    if (deque->size < MAX_LIST_SIZE / 2) return;

    if (!deque->tail) return;

    Node* newest = deque->tail;
    pthread_mutex_lock(&deque->lock);

    if (newest == deque->head) {
        deque->head = deque->tail = NULL;
    } else {
        deque->tail = newest->prev;
        deque->tail->next = NULL;
    }

    free(newest);
    deque->size--;

    pthread_mutex_unlock(&deque->lock);
}

void manage_crc_list(Deque* deque, NFAPI_CRC_INDICATION_PDU_T new_data) {
    add_to_deque(deque, new_data);

    if (is_full(deque)) {
        remove_oldest(deque);
    }

    remove_newest_if_needed(deque);
}

// Example usage
int main() {
    Deque* crc_list = create_deque();
    if (!crc_list) return 1;

    for (int i = 0; i < 200; ++i) { // Simulate adding data
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        manage_crc_list(crc_list, pdu);
    }

    destroy_deque(crc_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` lock ensures that operations on the deque are thread-safe.
- **Memory Management**: All dynamically allocated memory is freed when elements are removed or when the deque itself is destroyed.
- **Dynamic List Size**: The list maintains a maximum size (`MAX_LIST_SIZE`) and removes the oldest entries if full, while also periodically removing the newest to maintain performance.
- **Efficient Operations**: Using a double-ended queue (deque) allows for efficient addition and removal of elements from both ends.']

