import threading.h

#define MAX_PDUS 1024 // Adjust as needed

typedef struct {
    size_t size;
    uint8_t *data;
} PDU;

typedef struct {
    int ue_id;
    int qos_profile_id;
    PDU pdus[MAX_PDUs];
    size_t pdu_count;
    pthread_mutex_t lock; // For thread safety
} SessionContext;

typedef struct {
    SessionContext **sessions;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for session list
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = (SessionContext**)calloc(initial_capacity, sizeof(SessionContext*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);
    return manager;
}

void free_pdu(PDU *pdu) {
    if (pdu && pdu->data) {
        free(pdu->data);
        pdu->size = 0;
    }
}

void free_session_context(SessionContext *context) {
    for (size_t i = 0; i < context->pdu_count; ++i) {
        free_pdu(&context->pdus[i]);
    }
    pthread_mutex_destroy(&context->lock);
}

SessionContext* create_session_context(int ue_id, int qos_profile_id) {
    SessionContext *context = (SessionContext*)malloc(sizeof(SessionContext));
    if (!context) return NULL;

    context->ue_id = ue_id;
    context->qos_profile_id = qos_profile_id;
    context->pdu_count = 0;
    pthread_mutex_init(&context->lock, NULL);

    return context;
}

void update_qos_profile(SessionManager *manager, int ue_id, int new_qos_id) {
    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        SessionContext *context = manager->sessions[i];
        if (context && context->ue_id == ue_id) {
            pthread_mutex_lock(&context->lock);
            context->qos_profile_id = new_qos_id;
            pthread_mutex_unlock(&context->lock);
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
}

SessionContext* get_session_context(SessionManager *manager, int ue_id) {
    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        SessionContext *context = manager->sessions[i];
        if (context && context->ue_id == ue_id) {
            pthread_rwlock_unlock(&manager->rwlock);
            return context;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
    return NULL;
}

void add_pdu(SessionManager *manager, int ue_id, uint8_t *data, size_t size) {
    SessionContext *context = get_session_context(manager, ue_id);
    if (context && context->pdu_count < MAX_PDUS) {
        pthread_mutex_lock(&context->lock);
        PDU *pdu = &context->pdus[context->pdu_count++];
        pdu->size = size;
        pdu->data = malloc(size);
        if (pdu->data) {
            memcpy(pdu->data, data, size);
        }
        pthread_mutex_unlock(&context->lock);
    }
}

void delete_session(SessionManager *manager, int ue_id) {
    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        SessionContext *context = manager->sessions[i];
        if (context && context->ue_id == ue_id) {
            free_session_context(context);
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(SessionContext*));
            --manager->count;
            break;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
}

void free_session_manager(SessionManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        free_session_context(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_rwlock_unlock(&manager->rwlock);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

// Example usage
int main() {
    SessionManager *manager = create_session_manager(10000);

    // Add sessions, PDUs, update QoS, etc.

    free_session_manager(manager);
    return 0;
}
