#include <chrono>
#include <thread>
#include <atomic>

class TokenManager {
public:
    struct SessionInfo {
        std::string sessionId;
        std::chrono::system_clock::time_point expirationTime;
        std::vector<std::string> accessedResources;

        bool isExpired() const {
            return std::chrono::system_clock::now() > expirationTime;
        }
    };

private:
    using TokenMap = std::unordered_map<std::string, SessionInfo>;
    TokenMap tokens_;
    mutable std::shared_mutex mutex_;
    std::atomic<bool> stopPurgeThread_{false};
    std::thread purgeThread_;

public:
    TokenManager() {
        purgeThread_ = std::thread(&TokenManager::purgeExpiredTokens, this);
    }

    ~TokenManager() {
        stopPurgeThread_ = true;
        if (purgeThread_.joinable()) {
            purgeThread_.join();
        }
    }

    void addOrUpdateSession(const std::string& sessionId,
                            const std::chrono::system_clock::time_point expirationTime,
                            const std::vector<std::string>& accessedResources) {
        std::unique_lock lock(mutex_);
        tokens_[sessionId] = {sessionId, expirationTime, accessedResources};
    }

    bool getSessionInfo(const std::string& sessionId, SessionInfo& sessionInfo) const {
        std::shared_lock lock(mutex_);
        auto it = tokens_.find(sessionId);
        if (it != tokens_.end()) {
            sessionInfo = it->second;
            return true;
        }
        return false;
    }

    void purgeExpiredTokens() {
        while (!stopPurgeThread_) {
            std::unique_lock lock(mutex_, std::defer_lock);
            lock.lock();

            for (auto it = tokens_.begin(); it != tokens_.end();) {
                if (it->second.isExpired()) {
                    it = tokens_.erase(it);
                } else {
                    ++it;
                }
            }

            lock.unlock();
            std::this_thread::sleep_for(std::chrono::minutes(1));
        }
    }

    void simulateApiUpdate(const std::string& sessionId, const std::chrono::system_clock::time_point newExpirationTime) {
        // Simulating an external API update
        std::unique_lock lock(mutex_);
        auto it = tokens_.find(sessionId);
        if (it != tokens_.end()) {
            it->second.expirationTime = newExpirationTime;
        }
    }

private:
    void handleApiFailureGracefully() {
        // Implement retry logic or fallback mechanism for API failures
    }

public:
    void adjustResourcePoolsBasedOnActivityLevel(size_t currentLoad) {
        // Adjust resource allocations dynamically based on the load and activity level
    }
};

// Example usage:
