    std::vector<std::string> resources = {"resource1", "resource2"};

    tokenManager.addOrUpdateSession(sessionId, expirationTime, resources);

    TokenManager::SessionInfo sessionInfo;
    if (tokenManager.getSessionInfo(sessionId, sessionInfo)) {
        std::cout << "Session ID: " << sessionInfo.sessionId << "\n";
    }

    return 0;
}
