```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define packet data structure and any other necessary fields
    size_t length;
    unsigned char* data;
} PacketData;

typedef struct {
    int tag;  // MAC_RX_BUFFER_INFO tag
    PacketData* packets;
} MAC_RX_BUFFER;

#define MAX_PACKET_SIZE 1500

pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a single packet with specified size
PacketData* allocate_packet(size_t size) {
    if (size == 0 || size > MAX_PACKET_SIZE) return NULL;
    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    if (!packet) return NULL;
    packet->length = size;
    packet->data = (unsigned char*)malloc(size);
    if (!packet->data) {
        free(packet);
        return NULL;
    }
    return packet;
}

// Function to initialize MAC_RX_BUFFER array
MAC_RX_BUFFER* init_mac_rx_buffers(int N, size_t memory_budget) {
    if (N <= 0 || memory_budget == 0) return NULL;

    MAC_RX_BUFFER* buffers = (MAC_RX_BUFFER*)malloc(N * sizeof(MAC_RX_BUFFER));
    if (!buffers) return NULL;

    size_t max_packet_size = memory_budget / N;
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&buffer_lock);
        buffers[i].tag = i; // Assign some tag
        buffers[i].packets = allocate_packet(max_packet_size);
        pthread_mutex_unlock(&buffer_lock);

        if (!buffers[i].packets) { 
            // Cleanup in case of failure
            for (int j = 0; j < i; ++j) {
                free(buffers[j].packets->data);
                free(buffers[j].packets);
            }
            free(buffers);
            return NULL;
        }
    }

    return buffers;
}

// Function to release resources
void cleanup_mac_rx_buffers(MAC_RX_BUFFER* buffers, int N) {
    if (!buffers) return;

    for (int i = 0; i < N; ++i) {
        if (buffers[i].packets) {
            free(buffers[i].packets->data);
            free(buffers[i].packets);
        }
    }

    free(buffers);
}

// Function to dynamically resize the buffer array
MAC_RX_BUFFER* resize_mac_rx_buffers(MAC_RX_BUFFER* buffers, int current_size, int new_size, size_t memory_budget) {
    if (new_size <= 0 || !buffers && new_size > 0) return NULL;

    pthread_mutex_lock(&buffer_lock);

    MAC_RX_BUFFER* new_buffers = (MAC_RX_BUFFER*)malloc(new_size * sizeof(MAC_RX_BUFFER));
    if (!new_buffers) { 
        pthread_mutex_unlock(&buffer_lock);
        return buffers;
    }

    size_t max_packet_size = memory_budget / new_size;

    // Copy existing buffers to the new array
    for (int i = 0; i < current_size && i < new_size; ++i) {
        if (buffers[i].packets) {
            new_buffers[i].packets = allocate_packet(buffers[i].packets->length);
            if (new_buffers[i].packets) {
                memcpy(new_buffers[i].packets->data, buffers[i].packets->data, buffers[i].packets->length);
            }
        }
        new_buffers[i].tag = buffers[i].tag;
    }

    // Initialize the rest of the array
    for (int i = current_size; i < new_size; ++i) {
        new_buffers[i].tag = i;
        new_buffers[i].packets = allocate_packet(max_packet_size);
    }

    pthread_mutex_unlock(&buffer_lock);

    if (!buffers) return new_buffers;

    // Cleanup old buffers
    for (int i = 0; i < current_size; ++i) {
        if (buffers[i].packets) {
            free(buffers[i].packets->data);
            free(buffers[i].packets);
        }
    }

    free(buffers);

    return new_buffers;
}

// Example function to monitor memory usage
void monitor_memory_usage(MAC_RX_BUFFER* buffers, int N) {
    if (!buffers) return;

    size_t total_memory_used = 0;
    for (int i = 0; i < N; ++i) {
        if (buffers[i].packets) {
            total_memory_used += sizeof(PacketData) + buffers[i].packets->length;
        }
    }

    printf("Total memory used by buffers: %zu bytes\n", total_memory_used);
}
