    return 1;
}

int isValidCRCFlag(uint8_t crc_flag) {
    // Example validation logic for CRC flag
    return (crc_flag % 2 == 0);
}

void resizeList(CRCList *list) {
    size_t new_capacity = list->capacity * GROWTH_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to resize the list");
        exit(EXIT_FAILURE);
    }
    memset(new_data + list->capacity, 0, (new_capacity - list->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->data = new_data;
    list->capacity = new_capacity;
}

void logPerformanceMetrics(CRCList *list, double totalTime, size_t successfulEntries) {
    fprintf(list->log_file, "Total time: %.2f seconds\n", totalTime);
    fprintf(list->log_file, "Successful entries added: %zu\n", successfulEntries);
    if (successfulEntries > 0) {
        fprintf(list->log_file, "Average time per entry: %.6f seconds\n", totalTime / successfulEntries);
    }
}

void addEntry(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resizeList(list);
    }

    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.valid_tag = generateRandomValidTag();
    entry.rnti = generateUniqueRNTI(list);

    do {
        entry.crc_flag = rand() % 256; // Randomly set CRC flag
    } while (!isValidCRCFlag(entry.crc_flag));

    list->data[list->size++] = entry;

    pthread_mutex_unlock(&list->lock);
}

void initializeList(CRCList *list, const char *logFilePath) {
    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for the list");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);

    list->log_file = fopen(logFilePath, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void freeList(CRCList *list) {
    free(list->data);
    fclose(list->log_file);
    pthread_mutex_destroy(&list->lock);
}

void handleNFAPIEntries(CRCList *list, size_t numEntries) {
    clock_t start = clock();

    for (size_t i = 0; i < numEntries; ++i) {
        addEntry(list);
    }

    clock_t end = clock();
    double totalTime = (double)(end - start) / CLOCKS_PER_SEC;
    logPerformanceMetrics(list, totalTime, list->size);
}

int main() {
    srand(time(NULL));

    CRCList list;
    initializeList(&list, "performance.log");

    // Simulate concurrent processing
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))handleNFAPIEntries, &list);
    }
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    freeList(&list);

    return 0;
}
```

### Key Points:
