                # e.g., pdu_data.rxUeInformationTag.field = value

                # Set CRCFLAG using the probability model
                pdu_data.crcIndicationRel8Tag.CRCFLAG = 1 if self._generate_crc_flag() else 0

                new_node = Node(data=pdu_data)

                if not self.head:
                    self.head = new_node
                else:
                    current.next = new_node

                current = new_node

    # Serialize the linked list to a binary format for persistence
    def serialize(self):
        with self.lock:
            data = []
            current = self.head

            while current:
                data.append(bytes(current.data))
                current = current.next

            return b''.join(data)

    # Deserialize from binary format back into the linked list structure
    @staticmethod
    def deserialize(binary_data):
        if not binary_data:
            return None

        linked_list = CRCLinkedList()

        offset = 0
        while offset < len(binary_data):
            data_size = sizeof(NFAPI_CRC_INDICATION_PDU_T)

            pdu_bytes = binary_data[offset:offset + data_size]
            pdu_data = NFAPI_CRC_INDICATION_PDU_T.from_buffer_copy(pdu_bytes)

            new_node = Node(data=pdu_data)

            if not linked_list.head:
                linked_list.head = new_node
            else:
                current = linked_list.head
                while current.next:
                    current = current.next
                current.next = new_node

            offset += data_size

        return linked_list

