#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RETRIES 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
} NFAPI_CATALOG;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_warning(const char* message) {
    printf("WARNING: %s\n", message);
}

int generate_unique_rnti(int upper_limit, int *rntis, int current_count) {
    while (1) {
        int rnti = rand() % upper_limit;
        for (int i = 0; i < current_count; ++i) {
            if (rntis[i] == rnti) return -1;
        }
        return rnti;
    }
}

void* generate_pdu(void *arg) {
    int idx = *(int*)arg;
    int upper_limit = ((struct task_args *)arg)->upper_limit;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pthread_mutex_lock(&mutex);
        if (idx < g_catalog.count) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        int rnti = generate_unique_rnti(upper_limit, g_rntis, g_catalog.count);
        if (rnti == -1) {
            retries++;
            pthread_mutex_unlock(&mutex);
            continue;
        }
        pdu.RNTI = rnti;

        pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Example range
        pdu.CRCFLAG = rand() % 2;

        g_rntis[g_catalog.count] = rnti;
        g_catalog.array[g_catalog.count++] = pdu;

        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    log_warning("Max retries reached for generating a unique RNTI");
    return NULL;
}

NFAPI_CATALOG* create_and_populate_pdu_list(size_t N, unsigned int seed, int upper_limit) {
    if (seed == 0) {
        seed = time(NULL);
    }

    srand(seed);

    g_catalog.array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!g_catalog.array) return NULL;

    pthread_t threads[N];
    struct task_args args[N];

    for (int i = 0; i < N; ++i) {
        args[i].upper_limit = upper_limit;
    }

    g_rntis = malloc(N * sizeof(int));
    if (!g_rntis) {
        free(g_catalog.array);
        return NULL;
    }

    g_catalog.count = 0;

    for (int i = 0; i < N; ++i) {
        args[i].index = i;
        pthread_create(&threads[i], NULL, generate_pdu, &args[i]);
    }

    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (g_catalog.count != N) {
        log_warning("Generated fewer structures than requested");
        free(g_rntis);
        free(g_catalog.array);
        g_catalog.array = malloc(g_catalog.count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!g_catalog.array) return NULL;
        for (size_t i = 0; i < g_catalog.count; ++i) {
            g_catalog.array[i] = g_catalog.array[i];
        }
    }

    free(g_rntis);
    pthread_mutex_destroy(&mutex);

    return &g_catalog;
}

NFAPI_CATALOG* g_catalog;
int *g_rntis;

int main() {
    size_t N = 10; // Example number of structures
    unsigned int seed = 12345; // Example seed value
    int upper_limit = 1000; // Example RNTI range

    NFAPI_CATALOG* catalog = create_and_populate_pdu_list(N, seed, upper_limit);
    if (!catalog) {
        printf("Error: Could not generate the required PDU list.\n");
        return 1;
    }

    for (size_t i = 0; i < catalog->count; ++i) {
        printf("PDU %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               i,
               catalog->array[i].RX_UE_INFORMATION_TAG,
               catalog->array[i].RNTI,
               catalog->array[i].CRC_INDICATION_REL8_TAG,
               catalog->array[i].CRCFLAG);
    }

    free(catalog->array);
    return 0;
}
