              const NFAPI_CRC_INDICATION_PDU_T *pdu_b = b;
              return (pdu_a->RNTI - pdu_b->RNTI);
          });

    log_message("PDU array sorted by RNTI.");

    return pdu_array;
}

// Function to free the allocated memory.
