// Function to initialize dynamic array
LTE_PHY_MEASUREMENT_T* init_dynamic_array(size_t initial_capacity) {
    if (initial_capacity <= 0) return NULL;

    LTE_PHY_MEASUREMENT_T *array = malloc(sizeof(LTE_PHY_MEASUREMENT_T) * initial_capacity);
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        array[i].CELL_ID = rand(); // Simulate unique ID
        time(&array[i].TIMESTAMP); // Current timestamp
        array[i].RSSI = 0.0;

        pthread_mutex_init(&array[i].lock, NULL);
        array[i].crc_tag.CRCFLAG = rand() % 2; // Random CRC flag

        array[i].RX_UE_INFORMATION_TAG = rand(); // Simulate unique tag
        array[i].RNTI = rand() & 0x7FFF; // RNTI should be 15-bit

        array[i].head = NULL;
        array[i].tail = NULL;
    }

    return array;
}

// Function to resize dynamic array
LTE_PHY_MEASUREMENT_T* resize_dynamic_array(LTE_PHY_MEASUREMENT_T *array, size_t current_size, size_t new_capacity) {
    if (new_capacity <= current_size) return array;

    LTE_PHY_MEASUREMENT_T *new_array = realloc(array, sizeof(LTE_PHY_MEASUREMENT_T) * new_capacity);
    if (!new_array) {
        perror("Memory reallocation failed");
        free(array);
        return NULL;
    }

    for (size_t i = current_size; i < new_capacity; ++i) {
        new_array[i].CELL_ID = rand();
        time(&new_array[i].TIMESTAMP);

        pthread_mutex_init(&new_array[i].lock, NULL);
        new_array[i].crc_tag.CRCFLAG = rand() % 2;

        new_array[i].RX_UE_INFORMATION_TAG = rand();
        new_array[i].RNTI = rand() & 0x7FFF;

        new_array[i].head = NULL;
        new_array[i].tail = NULL;
    }

    return new_array;
}

// Function to insert packet into the list
void insert_packet(LTE_PHY_MEASUREMENT_T *measurement, void *packet) {
    if (!measurement || !packet) return;

    pthread_mutex_lock(&measurement->lock);

    struct PacketList *new_node = malloc(sizeof(struct PacketList));
    if (!new_node) {
        perror("Packet list node allocation failed");
        pthread_mutex_unlock(&measurement->lock);
        return;
    }

    new_node->packet = packet;
    new_node->next = NULL;

    if (measurement->tail) {
        measurement->tail->next = new_node;
    } else {
        measurement->head = new_node;
    }

    measurement->tail = new_node;

    pthread_mutex_unlock(&measurement->lock);
}

// Function to calculate average RSSI
void calculate_average_rssi(LTE_PHY_MEASUREMENT_T *array, size_t array_size) {
    if (!array || array_size == 0) return;

    double total_rssi = 0.0;
    size_t count = 0;

    for (size_t i = 0; i < array_size; ++i) {
        pthread_mutex_lock(&array[i].lock);

        // Simulate RSSI calculation
        double rssi = rand() % 100 - 50; // Random RSSI value between -50 and 49
        total_rssi += rssi;
        array[i].RSSI = rssi;

        count++;
        pthread_mutex_unlock(&array[i].lock);
    }

    if (count > 0) {
        double average_rssi = total_rssi / count;
        printf("Average RSSI: %f\n", average_rssi);
    }
}

// Function to free dynamic array
void free_dynamic_array(LTE_PHY_MEASUREMENT_T *array, size_t size) {
    if (!array) return;

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&array[i].lock);

        struct PacketList *current = array[i].head;
        while (current) {
            struct PacketList *next = current->next;
            free(current);
            current = next;
        }

        pthread_mutex_unlock(&array[i].lock);
        pthread_mutex_destroy(&array[i].lock);
    }

    free(array);
}

// Example usage
int main() {
    srand(time(NULL));

    size_t initial_capacity = 10;
    LTE_PHY_MEASUREMENT_T *measurements = init_dynamic_array(initial_capacity);

    if (!measurements) return EXIT_FAILURE;

    // Simulate inserting packets and resizing array
    void *packet1 = malloc(100); // Dummy packet data
    insert_packet(&measurements[0], packet1);

    size_t new_capacity = 20;
    LTE_PHY_MEASUREMENT_T *resized_array = resize_dynamic_array(measurements, initial_capacity, new_capacity);
    if (!resized_array) {
        free_dynamic_array(measurements, initial_capacity);
        return EXIT_FAILURE;
    }

    calculate_average_rssi(resized_array, new_capacity);

    free(packet1); // Free inserted packet
    free_dynamic_array(resized_array, new_capacity);

    return EXIT_SUCCESS;
}
