void initializeAndPopulateNfarxContexts(int num_contexts, int max_size) {
    NFAPI_MESSAGE_T *contexts = NULL;
    size_t current_size = 0;

    if (num_contexts <= 0) {
        free(contexts);
        contexts = NULL;
        return;
    }

    if (num_contexts > max_size) num_contexts = max_size;

    while (current_size < num_contexts) {
        NFAPI_MESSAGE_T *new_array = realloc(contexts, (current_size + 1) * sizeof(NFAPI_MESSAGE_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed at size %zu\n", current_size + 1);
            break;
        }
        contexts = new_array;

        // Initialize and allocate structures within each NFAPI_MESSAGE_T
        for (size_t i = current_size; i < num_contexts && i < max_size; ++i) {
            contexts[i].ue_context = {}; // Assuming default initialization is acceptable
            contexts[i].data_pdu = {};

            contexts[i].stream_info = allocateStreamInfo();
            if (!contexts[i].stream_info) {
                fprintf(stderr, "Failed to allocate RX_STREAM_INFO at index %zu\n", i);
                continue;
