            contexts[i].txinfo = allocateTxInfo();
            if (!contexts[i].txinfo) {
                fprintf(stderr, "Failed to allocate RX_TXINFO at index %zu\n", i);
                free(contexts[i].stream_info);  // Cleanup on allocation failure
                contexts[i].stream_info = NULL;
                continue;
            }
        }

        current_size += (num_contexts - current_size < max_size) ? num_contexts - current_size : max_size;
    }

    if (current_size > 0 && current_size != num_contexts) {
        fprintf(stderr, "Could not fully allocate all required contexts.\n");
    }

    // Example of freeing memory
    for (size_t i = 0; i < current_size; ++i) {
        free(contexts[i].stream_info);
        free(contexts[i].txinfo);
    }

    free(contexts);
}
