#define MAX_STRUCTURES 1000 // Default max structures, adjust as needed

// Memory pool structure
typedef struct {
    size_t element_size;
    size_t total_elements;
    void* memory_pool;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize memory pool
bool init_memory_pool(MemoryPool* pool, size_t element_size, size_t max_elements) {
    if (pool == NULL || element_size == 0 || max_elements == 0)
        return false;

    pool->element_size = element_size;
    pool->total_elements = max_elements;
    pool->memory_pool = malloc(element_size * max_elements);
    pthread_mutex_init(&pool->lock, NULL);

    return pool->memory_pool != NULL;
}

// Destroy memory pool
void destroy_memory_pool(MemoryPool* pool) {
    if (pool == NULL)
        return;

    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

// Allocate a single structure from the pool
NFAPI_CRC_INDICATION_PDU_T* allocate_structure(MemoryPool* pool, size_t count) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;

    if (count > pool->total_elements)
        count = pool->total_elements;

    pthread_mutex_lock(&pool->lock);
    result = malloc(pool->element_size * count);
    pthread_mutex_unlock(&pool->lock);

    return result;
}

// Validate the structure
bool validate_structure(NFAPI_CRC_INDICATION_PDU_T* structures, size_t count) {
    if (structures == NULL || count == 0)
        return false;

    for (size_t i = 0; i < count; ++i) {
        if (structures[i].RNTI == 0 || structures[i].tag.crcflag > 1)
            return false;
    }

    return true;
}

// Generate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_structures(MemoryPool* pool, size_t max_requested, size_t* actual_count) {
    if (pool == NULL || actual_count == NULL)
        return NULL;

    *actual_count = 0;

    // Determine the maximum number of structures we can handle
    size_t n = (max_requested > pool->total_elements) ? pool->total_elements : max_requested;

    // Allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T* structs = allocate_structure(pool, n);
    if (structs == NULL)
        return NULL;

    // Populate each structure with random data
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < n; ++i) {
        structs[i].RNTI = rand() % 10000 + 1;  // Ensure non-zero RNTI
        structs[i].tag.crcflag = rand() % 2;   // Random CRCFLAG value of 0 or 1
    }

    *actual_count = n;

    // Validate structures
    if (!validate_structure(structs, n)) {
        free(structs);
        return NULL;
    }

    return structs;
}

int main() {
    MemoryPool pool;
    size_t actual_count;

    if (init_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_STRUCTURES)) {
        NFAPI_CRC_INDICATION_PDU_T* structures = generate_structures(&pool, 500, &actual_count);

        if (structures != NULL) {
            printf("Generated %zu valid structures.\n", actual_count);
            free(structures); // Free allocated memory after use
        } else {
            printf("Failed to generate structures.\n");
        }

        destroy_memory_pool(&pool);
    } else {
        printf("Memory pool initialization failed.\n");
    }

    return 0;
}
