#include <pthread.h>

// Constants for validation
#define MAX_TIME_SLOT_INDEX 100
#define MIN_CARRIER_FREQUENCY 8000000
#define MAX_CARRIER_FREQUENCY 30000000

typedef struct PacketData {
    char* data;
    size_t length;
} PacketData;

typedef struct FrameProcessingTask {
    int TimeSlotIndex;
    double CarrierFrequency;
    PacketData* Buffer;
    struct FrameProcessingTask* next;
} FrameProcessingTask;

// Global linked list head and lock
FrameProcessingTask* taskListHead = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_time_slot_index(int index) {
    return (index >= 0 && index <= MAX_TIME_SLOT_INDEX);
}

int is_valid_carrier_frequency(double frequency) {
    return (frequency >= MIN_CARRIER_FREQUENCY && frequency <= MAX_CARRIER_FREQUENCY);
}

FrameProcessingTask* create_task(int timeSlotIndex, double carrierFrequency, const char* packetData, size_t length) {
    if (!is_valid_time_slot_index(timeSlotIndex)) {
        fprintf(stderr, "Invalid TimeSlotIndex: %d\n", timeSlotIndex);
        return NULL;
    }

    if (!is_valid_carrier_frequency(carrierFrequency)) {
        fprintf(stderr, "Invalid CarrierFrequency: %.2f MHz\n", carrierFrequency / 1e6);
        return NULL;
    }

    FrameProcessingTask* newTask = (FrameProcessingTask*)malloc(sizeof(FrameProcessingTask));
    if (!newTask) {
        perror("Failed to allocate memory for task");
        return NULL;
    }

    PacketData* buffer = (PacketData*)malloc(sizeof(PacketData));
    if (!buffer) {
        perror("Failed to allocate memory for packet data buffer");
        free(newTask);
        return NULL;
    }

    buffer->data = (char*)malloc(length);
    if (!buffer->data) {
        perror("Failed to allocate memory for packet data");
        free(buffer);
        free(newTask);
        return NULL;
    }

    // Copy the packet data
    memcpy(buffer->data, packetData, length);
    buffer->length = length;

    newTask->TimeSlotIndex = timeSlotIndex;
    newTask->CarrierFrequency = carrierFrequency;
    newTask->Buffer = buffer;
    newTask->next = NULL;

    return newTask;
}

void add_task(int timeSlotIndex, double carrierFrequency, const char* packetData, size_t length) {
    FrameProcessingTask* newTask = create_task(timeSlotIndex, carrierFrequency, packetData, length);
    if (!newTask) {
        fprintf(stderr, "Failed to create task\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    newTask->next = taskListHead;
    taskListHead = newTask;

    pthread_mutex_unlock(&mutex);
}

void remove_task(int timeSlotIndex) {
    pthread_mutex_lock(&mutex);

    FrameProcessingTask *current = taskListHead, *prev = NULL;

    while (current && current->TimeSlotIndex != timeSlotIndex) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        fprintf(stderr, "Task with TimeSlotIndex %d not found\n", timeSlotIndex);
    } else {
        if (prev) {
            prev->next = current->next;
        } else {
            taskListHead = current->next;
        }

        free(current->Buffer->data);
        free(current->Buffer);
        free(current);
    }

    pthread_mutex_unlock(&mutex);
}

void log_task_operations(const char* message) {
    static FILE* logFile = NULL;

    if (!logFile) {
        logFile = fopen("task_log.txt", "a");
        if (!logFile) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(logFile, "%s\n", message);
    fflush(logFile); // Ensure the message is written immediately
}

void cleanup() {
    pthread_mutex_lock(&mutex);

    FrameProcessingTask* current = taskListHead;

    while (current) {
        FrameProcessingTask* temp = current;
        current = current->next;

        free(temp->Buffer->data);
        free(temp->Buffer);
        free(temp);
    }

    taskListHead = NULL;

    pthread_mutex_unlock(&mutex);

    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }
}

// Test the functions
int main() {
    add_task(1, 9000000.0, "Sample packet data", 16);
    remove_task(1);
    cleanup();

    return 0;
}
