    SUCCESS,
    OUT_OF_MEMORY,
    LOCK_FAILURE
} ErrorCode;

ErrorCode create_and_populate_nfa_pi_crc_ind_list(NFAPI_CRC_IND_LIST** list, size_t initial_capacity) {
