    if ((*list)->data == NULL) {
        LogError("Memory allocation failed for data array");
        pthread_mutex_destroy(&(*list)->lock);
        CustomFree(*list);
        return OUT_OF_MEMORY;
    }

    (*list)->capacity = initial_capacity;
    (*list)->count = 0;

