        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T* new_elements =
            (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

