bool remove_pdu(CRCList* list, int rnti_or_crcflag, bool is_rnti) {
    if (list->size == 0) return false;

    size_t write_index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if ((is_rnti && list->elements[i].RNTI != rnti_or_crcflag) ||
            (!is_rnti && list->elements[i].CRC_INDICATION_REL8_TAG.CRCFLAG != (rnti_or_crcflag ? 1 : 0))) {
            list->elements[write_index++] = list->elements[i];
        }
    }

    if (write_index == list->size) return false; // Element not found

    list->size = write_index;
    return true;
}

// Get an iterator for the list
CRCIterator get_iterator(const CRCList* list) {
    CRCIterator iter;
    iter.list = list;
    iter.current = NULL;
    iter.index = 0;

    if (list && list->size > 0) {
        iter.current = &list->elements[iter.index];
    }

    return iter;
}

// Move iterator to next element
bool move_next(CRCIterator* iter) {
    if (!iter || !iter->list || iter->index >= iter->list->size - 1) return false;

    ++iter->index;
    iter->current = &((iter->list)->elements[iter->index]);
    return true;
}
