#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

// Define the structure as per your requirements
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set in this context
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int elements_added;
    int elements_removed;
    size_t memory_consumed;
} CRCList;

// Function prototypes
CRCList* create_list(size_t initial_capacity);
void free_list(CRCList *list);
bool insert_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
bool remove_pdu(CRCList *list, int RNTI); // Example key for removal
void log_performance(const CRCList *list);

CRCList* create_list(size_t initial_capacity) {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->elements_added = 0;
    list->elements_removed = 0;
    list->memory_consumed = sizeof(CRCList) + initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return list;
}

void free_list(CRCList *list) {
    pthread_mutex_lock(&list->lock);
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
    pthread_mutex_unlock(&list->lock);
}

bool insert_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->count++] = pdu;
    list->elements_added++;
    list->memory_consumed += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_pdu(CRCList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i].RNTI == RNTI) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            list->elements_removed++;
            list->memory_consumed -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

void log_performance(const CRCList *list) {
    printf("Elements Added: %d\n", list->elements_added);
    printf("Elements Removed: %d\n", list->elements_removed);
    printf("Current Memory Consumed: %zu bytes\n", list->memory_consumed);
}

int main() {
    srand(time(NULL));

    CRCList *list = create_list(4);

    for (int i = 0; i < 10; ++i) { // Example usage
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 100;
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2 == 0;

        insert_pdu(list, pdu);
    }

    remove_pdu(list, 42); // Example RNTI to remove

    log_performance(list);

    free_list(list);

    return 0;
}
