#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    int elements_added;
    int elements_removed;
    size_t total_memory_consumed;
} DynamicList;

// Function prototypes
DynamicList* create_list();
void destroy_list(DynamicList* list);
int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element);
int remove_element(DynamicList* list, int RNTI, int (*cmp_func)(const void*, const void*));
Node* find_node_by_RNTI(Node* head, int RNTI, int (*cmp_func)(const void*, const void*));
void log_performance(const DynamicList* list);
void update_memory_usage(DynamicList* list, int change);

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->elements_added = 0;
    list->elements_removed = 0;
    list->total_memory_consumed = sizeof(DynamicList);

    return list;
}

void destroy_list(DynamicList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
        update_memory_usage(list, -sizeof(Node));
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    list->size++;
    list->elements_added++;
    update_memory_usage(list, sizeof(Node));

    pthread_mutex_unlock(&list->lock);

    log_performance(list);
    return 0;
}

int remove_element(DynamicList* list, int RNTI, int (*cmp_func)(const void*, const void*)) {
    if (!list || !cmp_func) return -1;

    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect) {
        Node *current = *indirect;
        if (cmp_func((void*)&RNTI, (void*)&current->data.RNTI) == 0) {
            *indirect = current->next;
            free(current);
            list->size--;
            list->elements_removed++;
            update_memory_usage(list, -sizeof(Node));

            pthread_mutex_unlock(&list->lock);
            log_performance(list);
            return 0;
        }
        indirect = &current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

Node* find_node_by_RNTI(Node* head, int RNTI, int (*cmp_func)(const void*, const void*)) {
    while (head) {
        if (cmp_func((void*)&RNTI, (void*)&head->data.RNTI) == 0) {
            return head;
        }
        head = head->next;
    }
    return NULL;
}

void log_performance(const DynamicList* list) {
    printf("Elements Added: %d\n", list->elements_added);
    printf("Elements Removed: %d\n", list->elements_removed);
    printf("Total Memory Consumed: %zu bytes\n", list->total_memory_consumed);
}

void update_memory_usage(DynamicList* list, int change) {
    list->total_memory_consumed += change;
}

// Example comparison function
int compare_RNTI(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

// Random CRCFLAG generator for testing
void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}
