#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include "json-c/json.h"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicNFAPIList;

DynamicNFAPIList* create_dynamic_list(size_t initial_capacity) {
    DynamicNFAPIList* list = malloc(sizeof(DynamicNFAPIList));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_dynamic_list(DynamicNFAPIList* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

static void resize_if_needed(DynamicNFAPIList* list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return;

        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void insert_pdu(DynamicNFAPIList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    resize_if_needed(list);

    list->data[list->size] = pdu;
    list->size++;

    printf("Inserted element. Current size: %zu\n", list->size);
    pthread_mutex_unlock(&list->lock);
}

void delete_pdu(DynamicNFAPIList* list, int index) {
    if (index < 0 || index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    memmove(&list->data[index], &list->data[index + 1], 
            (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    printf("Deleted element at index %d. Current size: %zu\n", index, list->size);

    pthread_mutex_unlock(&list->lock);
}

int handle_json_payload(DynamicNFAPIList* list, const char* json_str) {
    struct json_object *parsed_json;
    struct json_object *id_obj;
    struct json_object *name_obj;
    struct json_object *email_obj;
    struct json_object *password_obj;

    parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) return -1;

    if (json_object_object_get_ex(parsed_json, "id", &id_obj) &&
        json_object_object_get_ex(parsed_json, "name", &name_obj) &&
        json_object_object_get_ex(parsed_json, "email", &email_obj) &&
        json_object_object_get_ex(parsed_json, "password", &password_obj)) {

        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Set fields based on JSON data. Here as example:
        pdu.RX_UE_INFORMATION_TAG = (int)json_object_get_int(id_obj);
        pdu.RNTI = rand();  // Example RNTI generation
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000; // Random CRC tag
        pdu.CRCFLAG = rand() % 2;

        insert_pdu(list, pdu);

        json_object_put(parsed_json);  // Free JSON object
        return 0;
    }

    json_object_put(parsed_json);
    return -1;
}

int main() {
    DynamicNFAPIList* list = create_dynamic_list(10);

    const char* json_payload = "{\"id\":123, \"name\":\"John Doe\", \"email\":\"john@example.com\", \"password\":\"secret\"}";
    handle_json_payload(list, json_payload);

    delete_pdu(list, 0);

    destroy_dynamic_list(list);
    return 0;
}
