#define MAX_NFAPI_ELEMENTS 1024

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    size_t size;
    unsigned short* rnti_pool;
    int pool_size;
} CRCList;

CRCList crc_list = {NULL, 0, NULL, 0};

unsigned short generate_unique_rnti() {
    static unsigned short last_rnti = 0;
    unsigned short new_rnti;

    do {
        new_rnti = rand() % (0xFFFF - 1) + 1; // RNTI range: 1 to 65535
    } while (new_rnti == last_rnti);

    return new_rnti;
}

int add_crc_indication_to_list(size_t num_elements) {
    if (crc_list.size >= MAX_NFAPI_ELEMENTS || !num_elements) {
        fprintf(stderr, "Error: Cannot add elements to the list.\n");
        return -1;
    }

    for (size_t i = 0; i < num_elements && crc_list.size < MAX_NFAPI_ELEMENTS; ++i) {
        struct Node* new_node = malloc(sizeof(struct Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed.\n");
            return -1;
        }

        unsigned short rnti;
        do {
            rnti = generate_unique_rnti();
        } while (rnti == ((crc_list.head && crc_list.head->data.rx_ue_information_tag.RNTI) 
                          || 0));

        // Check uniqueness in the pool
        int is_unique = 1;
        for (int j = 0; j < crc_list.pool_size; ++j) {
            if (crc_list.rnti_pool[j] == rnti) {
                is_unique = 0;
                break;
            }
        }

        if (!is_unique || num_elements > MAX_NFAPI_ELEMENTS - crc_list.size) {
            free(new_node);
            fprintf(stderr, "Failed to allocate unique RNTI.\n");
            return -1;
        }

        new_node->data.rx_ue_information_tag.RNTI = rnti;
        new_node->data.rx_ue_information_tag.crc_ind_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1
        new_node->next = crc_list.head;
        crc_list.head = new_node;

        if (crc_list.pool_size < MAX_NFAPI_ELEMENTS) {
            crc_list.rnti_pool = realloc(crc_list.rnti_pool, sizeof(unsigned short) * (crc_list.pool_size + 1));
            if (!crc_list.rnti_pool) {
                free(new_node);
                fprintf(stderr, "Memory allocation failed for RNTI pool.\n");
                return -1;
            }
            crc_list.rnti_pool[crc_list.pool_size++] = rnti;
        }

        ++crc_list.size;
    }

    return 0;
}

void free_crc_indication_list() {
    struct Node* current = crc_list.head;
    while (current) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }
    if (crc_list.rnti_pool) {
        free(crc_list.rnti_pool);
    }
    memset(&crc_list, 0, sizeof(CRCList));
}

int main() {
    srand((unsigned int)time(NULL));

    // Example usage
    if (add_crc_indication_to_list(10) != 0) {
        fprintf(stderr, "Error adding elements to the list.\n");
    }

    free_crc_indication_list();
    return 0;
}
