#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure Definitions
typedef struct {
    unsigned int flowID;
    char sourceAddress[16];
    char destinationAddress[16];
} TrafficFlow;

// Global Variables and Mutex for Thread Safety
TrafficFlow *trafficFlows = NULL;
size_t capacity = 0, size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
int validateAddress(const char* address);
void initTrafficFlowArray(size_t initialCapacity);
int addTrafficFlow(unsigned int flowID, const char* sourceAddress, const char* destinationAddress);
void resizeTrafficFlowArray();
void freeTrafficFlowArray();

// Address validation function (stub for illustration)
int validateAddress(const char* address) {
    // Simple mock validation: check if it's a non-empty string
    return address != NULL && strlen(address) > 0;
}

// Initialize the traffic flow array with a given capacity
void initTrafficFlowArray(size_t initialCapacity) {
    pthread_mutex_lock(&mutex);
    if (trafficFlows == NULL || initialCapacity > capacity) {
        free(trafficFlows); // Free existing memory to prevent leaks
        trafficFlows = malloc(initialCapacity * sizeof(TrafficFlow));
        if (!trafficFlows) {
            perror("Failed to allocate memory for TrafficFlow array");
            exit(EXIT_FAILURE);
        }
        capacity = initialCapacity;
    }
    size = 0;
    pthread_mutex_unlock(&mutex);
}

// Add a new traffic flow, ensuring no duplicates and valid addresses
int addTrafficFlow(unsigned int flowID, const char* sourceAddress, const char* destinationAddress) {
    if (!validateAddress(sourceAddress) || !validateAddress(destinationAddress)) {
        return -1; // Invalid address
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < size; ++i) {
        if (strcmp(trafficFlows[i].sourceAddress, sourceAddress) == 0 &&
            strcmp(trafficFlows[i].destinationAddress, destinationAddress) == 0) {
            pthread_mutex_unlock(&mutex);
            return -2; // Duplicate address combination
        }
    }

    if (size >= capacity) {
        resizeTrafficFlowArray();
    }

    trafficFlows[size].flowID = flowID;
    strncpy(trafficFlows[size].sourceAddress, sourceAddress, sizeof(trafficFlows[size].sourceAddress) - 1);
    strncpy(trafficFlows[size].destinationAddress, destinationAddress, sizeof(trafficFlows[size].destinationAddress) - 1);

    size++;
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

// Double the capacity of the traffic flow array if needed
void resizeTrafficFlowArray() {
    size_t newCapacity = capacity * 2;
    TrafficFlow* temp = realloc(trafficFlows, newCapacity * sizeof(TrafficFlow));
    if (!temp) {
        perror("Failed to reallocate memory for TrafficFlow array");
        exit(EXIT_FAILURE);
    }
    trafficFlows = temp;
    capacity = newCapacity;
}

// Free allocated memory
void freeTrafficFlowArray() {
    pthread_mutex_lock(&mutex);
    free(trafficFlows);
    trafficFlows = NULL;
    size = 0;
    capacity = 0;
    pthread_mutex_unlock(&mutex);
}
```

### Explanation

1. **Concurrency**: The code uses a mutex (`pthread_mutex_t`) to ensure that only one thread can modify the `trafficFlows` array at any time, maintaining data integrity during concurrent access.

2. **Memory Management**: 
   - The function starts by initializing the traffic flow array with an initial capacity.
   - It doubles the capacity of the array when it becomes full (`resizeTrafficFlowArray`), which is a common strategy to balance between frequent allocations and memory fragmentation.

3. **Address Validation**: A stubbed `validateAddress` function checks if the addresses are non-empty strings for simplicity. In a real-world application, this would likely involve more complex validation logic.

4. **Error Handling**:
   - Returns `-1` for invalid address inputs.
   - Returns `-2` for duplicate `sourceAddress` and `destinationAddress` combinations.
   - Memory allocation failures result in the program exiting with an error message.

5. **Dynamic Resizing**: The array is resized dynamically to handle more entries without predefining a large maximum capacity, balancing memory usage against resizing cost.

6. **Memory Deallocation**: A function (`freeTrafficFlowArray`) ensures that allocated memory is properly freed when no longer needed, preventing leaks.']

