#include <pthread.h>

typedef struct {
    // Example fields
} NgapUEID;

typedef struct {
    int messageIdentifier;
    // Other relevant fields
} NgapMessageTransfer;

typedef struct {
    int NgapProcedureCode;
    NgapUEID *NgapUEID;
    NgapMessageTransfer NgapMessageTransfer;
} LTE_NgapMessage;

typedef struct Node {
    LTE_NgapMessage data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
}

LTE_NgapMessage* addMessage(DynamicArray *array, int NgapProcedureCode, NgapUEID *NgapUEID, int messageIdentifier) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data.NgapProcedureCode = NgapProcedureCode;
    newNode->data.NgapUEID = NgapUEID;
    newNode->data.NgapMessageTransfer.messageIdentifier = messageIdentifier;
    newNode->next = NULL;

    pthread_mutex_lock(&array->lock);

    newNode->next = array->head;
    array->head = newNode;
    array->count++;

    pthread_mutex_unlock(&array->lock);

    return &newNode->data;
}

LTE_NgapMessage* getMessageByIdentifier(DynamicArray *array, int messageIdentifier) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        if (current->data.NgapMessageTransfer.messageIdentifier == messageIdentifier) {
            pthread_mutex_unlock(&array->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void cleanupDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    array->head = NULL;
    array->count = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Usage example
int main() {
    DynamicArray messageArray;
    initDynamicArray(&messageArray);

    NgapUEID ueid; // Initialize appropriately
    addMessage(&messageArray, 1, &ueid, 12345);

    LTE_NgapMessage* msg = getMessageByIdentifier(&messageArray, 12345);
    if (msg) {
        printf("Message found: %d\n", msg->NgapMessageTransfer.messageIdentifier);
    } else {
        printf("Message not found.\n");
    }

    cleanupDynamicArray(&messageArray);

    return 0;
}
```

