// Define constants
#define MAX_PDU_COUNT 1024

// Pre-defined structure for CRC indication tag
typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Structure containing RX UE information and RNTI
typedef struct {
    int32_t RX_UE_INFORMATION_TAG; // Example type, replace with actual
    int16_t RNTI;                  // Example type, replace with actual
