// Main structure for NFAPI CRC indication PDU
typedef struct {
    RX_UE_INFO_RNTI_T ue_info_rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Pre-allocated buffer
static atomic_uint64_t pre_alloc_buffer[MAX_PDU_COUNT];
static size_t available_slots = MAX_PDU_COUNT;

// Error logging function (stub for integration with an existing system)
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Initialize the buffer
void initialize_buffer() {
    atomic_store(&available_slots, MAX_PDU_COUNT);
}

// Function to generate a random CRCFLAG
uint8_t generate_random_crc_flag() {
    return (rand() & 1); // Randomly set CRCFLAG as 0 or 1
}

// High-performance function to populate PDU list
NFAPI_CRC_INDICATION_PDU_T* populate_pdu_list(size_t n, NFAPI_CRC_INDICATION_PDU_T* buffer) {
    if (n > MAX_PDU_COUNT) {
        log_error("Requested PDUs exceed maximum capacity.");
        return NULL;
    }

    size_t slots_needed = atomic_fetch_sub(&available_slots, n);
    if (slots_needed < n) {
        // Not enough pre-allocated slots
        atomic_fetch_add(&available_slots, n - slots_needed);  // Rollback change
        log_error("Failed to allocate PDU slots.");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        size_t index = (atomic_load64(&pre_alloc_buffer[slots_needed + i]) & ((1ULL << 32) - 1));

        buffer[i].ue_info_rnti.RX_UE_INFORMATION_TAG = rand(); // Random example data
        buffer[i].ue_info_rnti.RNTI = rand();
        buffer[i].crc_tag.CRCFLAG = generate_random_crc_flag();

        pre_alloc_buffer[index] = index;  // Mark as used by setting the low part of the value
    }

    return buffer;
}

// Example integration function (to demonstrate usage)
void system_integration_example() {
    initialize_buffer();

    NFAPI_CRC_INDICATION_PDU_T pdu_list[MAX_PDU_COUNT];
    if (populate_pdu_list(100, pdu_list) == NULL) {
        log_error("Failed to populate PDU list.");
    }
}

int main() {
    // Simulate system usage
    system_integration_example();

    return 0;
}
```

