    struct PacketNode* next;
} PacketNode;

typedef struct {
    int CELL_ID;
    time_t TIMESTAMP;
    double RSSI;
    PacketNode* packets_head;  // Pointer to the head of a linked list
    size_t packet_count;
} LTE_PHY_MEASUREMENT_T;

// Helper functions
void initialize_crc_info(NFAPI_CRC_INDICATION_PDU_T *crc) {
    if (crc != NULL) {
        crc->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}

PacketNode* create_packet_node(const Packet &packet_data, NFAPI_CRC_INDICATION_PDU_T crc_info) {
    PacketNode *new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new packet node.\n");
        exit(EXIT_FAILURE);
    }

    new_node->packet_data = packet_data;
    new_node->crc_info = crc_info;
    initialize_crc_info(&new_node->crc_info);
    new_node->next = NULL;

    return new_node;
}

void add_packet(LTE_PHY_MEASUREMENT_T *measurement, const Packet &packet_data) {
    if (measurement == NULL) {
        fprintf(stderr, "Invalid measurement pointer.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T crc_info;
    initialize_crc_info(&crc_info);

    PacketNode* new_node = create_packet_node(packet_data, crc_info);

    // Add to the head of the list for quick insertion
    new_node->next = measurement->packets_head;
    measurement->packets_head = new_node;
    measurement->packet_count++;
}

void calculate_average_rssi(LTE_PHY_MEASUREMENT_T *measurement, double signal_strength) {
    if (measurement == NULL || measurement->packet_count == 0) return;

    static double total_signal_strength = 0.0;
    total_signal_strength += signal_strength;

    measurement->RSSI = total_signal_strength / measurement->packet_count;
}

LTE_PHY_MEASUREMENT_T* initialize_measurement_array(size_t num_measurements, int initial_packet_list_size) {
    LTE_PHY_MEASUREMENT_T *measurements = (LTE_PHY_MEASUREMENT_T*)malloc(num_measurements * sizeof(LTE_PHY_MEASUREMENT_T));

    if (!measurements) {
        fprintf(stderr, "Memory allocation failed for measurement array.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_measurements; ++i) {
        measurements[i].CELL_ID = rand(); // Random CELL_ID
        measurements[i].TIMESTAMP = time(NULL); // Current timestamp
        measurements[i].RSSI = 0.0;
        measurements[i].packets_head = NULL;
        measurements[i].packet_count = 0;
    }

    return measurements;
}

void free_measurement_array(LTE_PHY_MEASUREMENT_T *measurements, size_t num_measurements) {
    if (!measurements) return;

    for (size_t i = 0; i < num_measurements; ++i) {
        PacketNode* current = measurements[i].packets_head;

        while (current != NULL) {
            PacketNode* next_node = current->next;
            free(current);
            current = next_node;
        }
    }

    free(measurements);
}

// Demonstration
int main() {
    size_t num_measurements = 10;
    LTE_PHY_MEASUREMENT_T *measurements = initialize_measurement_array(num_measurements, 5);

    Packet packet1 = {12345, 0x01};  // Example RNTI and RX_UE_INFORMATION_TAG

    add_packet(&measurements[0], packet1);
    calculate_average_rssi(&measurements[0], -75.0);  // Example signal strength

    printf("CELL_ID: %d, TIMESTAMP: %ld, RSSI: %.2f\n", measurements[0].CELL_ID, measurements[0].TIMESTAMP, measurements[0].RSSI);

    free_measurement_array(measurements, num_measurements);

    return 0;
}
