// Dynamic array structure and related functions
typedef struct {
    LTE_DL_FRAME_MSG *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = malloc(initial_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (!da->array) {
        free(da);
        return NULL;
    }
    pthread_mutex_init(&da->lock, NULL);
    da->capacity = initial_capacity;
    da->count = 0;
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        pthread_mutex_destroy(&da->lock);
        free(da->array);
        free(da);
    }
}

int dynamic_array_resize(DynamicArray *da, size_t new_capacity) {
    LTE_DL_FRAME_MSG *new_array = realloc(da->array, new_capacity * sizeof(LTE_DL_FRAME_MSG));
    if (!new_array) return 0;
    da->array = new_array;
    da->capacity = new_capacity;
    return 1;
}

int dynamic_array_add(DynamicArray *da, LTE_DL_FRAME_MSG msg) {
    pthread_mutex_lock(&da->lock);
    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        if (!dynamic_array_resize(da, new_capacity)) {
            pthread_mutex_unlock(&da->lock);
            return 0; // Memory allocation failure
        }
    }
    da->array[da->count++] = msg;
    pthread_mutex_unlock(&da->lock);
    return 1;
}

void populate_dynamic_array(DynamicArray *da) {
    srand(time(NULL));
    for (size_t i = 0; i < 100; ++i) { // Example loop, adjust as needed
        LTE_DL_FRAME_MSG msg;
        msg.valid_element.frame_id = rand() % 1024;
        msg.valid_element.RNTI = rand() % 2048;

        // Simulate NFAPI_CRC_INDICATION_PDU_T and associated data
        NFAPI_CRC_INDICATION_PDU_T pdu; 
        RX_UE_INFORMATION_TAG rx_info;
        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (!dynamic_array_add(da, msg)) {
            fprintf(stderr, "Failed to add message to dynamic array.\n");
            break;
        }
    }
}

// Example usage
int main() {
    DynamicArray *da = create_dynamic_array(10);
    if (!da) {
        fprintf(stderr, "Failed to create dynamic array.\n");
        return EXIT_FAILURE;
    }

    populate_dynamic_array(da);

    destroy_dynamic_array(da);
    return 0;
}
