#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CHANNELS 10

typedef struct {
    int frequency;
    int power_level;
    int data_rate;
} RadioParams;

typedef struct {
    char channel_name[50];
    int channel_number;
    RadioParams radio_params;
} ChannelSettings;

typedef struct {
    int num_channels;
    ChannelSettings channels[MAX_CHANNELS];
} WirelessConfig;

#define SUCCESS 0
#define ERROR_INVALID_FILE -1
#define ERROR_CORRUPTED_DATA -2
#define ERROR_OUT_OF_RANGE -3

int read_config_file(const char *filename, WirelessConfig *config) {
    FILE *file = fopen(filename, "r");
    if (!file) return ERROR_INVALID_FILE;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%s %d", config->channels[config->num_channels].channel_name,
                   &config->channels[config->num_channels].channel_number) != 2) {
            fclose(file);
            return ERROR_CORRUPTED_DATA;
        }

        char radio_line[256];
        if (!fgets(radio_line, sizeof(radio_line), file)) {
            fclose(file);
            return ERROR_CORRUPTED_DATA;
        }

        RadioParams *params = &config->channels[config->num_channels].radio_params;
        if (sscanf(radio_line, "%d %d %d", &params->frequency,
                   &params->power_level, &params->data_rate) != 3) {
            fclose(file);
            return ERROR_CORRUPTED_DATA;
        }

        // Validate parameters
        if (params->frequency < 2400 || params->frequency > 2484 ||
            params->power_level < 1 || params->power_level > 20 ||
            params->data_rate < 1 || params->data_rate > 150) {
            fclose(file);
            return ERROR_OUT_OF_RANGE;
        }

        config->num_channels++;
        if (config->num_channels >= MAX_CHANNELS) break; // Prevent overflow
    }
    fclose(file);

    if (config->num_channels == 0) return ERROR_CORRUPTED_DATA;

    return SUCCESS;
}

int initialize_wireless_config(const char *filename, WirelessConfig *config) {
    memset(config, 0, sizeof(WirelessConfig));

    int status = read_config_file(filename, config);
    if (status != SUCCESS) {
        printf("Error initializing wireless configuration: %d\n", status);
        return status;
    }

    // Check for dependencies and circular dependencies
    for (int i = 0; i < config->num_channels; ++i) {
        for (int j = 0; j < config->num_channels; ++j) {
            if (i != j && config->channels[i].channel_number == config->channels[j].channel_number) {
                printf("Error: Circular dependency detected between channels %d and %d\n", i, j);
                return ERROR_CORRUPTED_DATA;
            }
        }
    }

    // Additional checks for future scalability
    // For now, assume no additional dependencies are required

    return SUCCESS;
}

int main() {
    WirelessConfig config;
    int result = initialize_wireless_config("config.txt", &config);

    if (result == SUCCESS) {
        printf("Wireless configuration initialized successfully.\n");
    } else {
        printf("Failed to initialize wireless configuration with error code: %d\n", result);
    }

    return 0;
}
