#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = (Node*)aligned_alloc(64, sizeof(Node));
    if (!node) return NULL;
    node->data = pdu;
    node->next = NULL;
    return node;
}

void free_list(Node* head) {
    Node* tmp;
    while (head) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

Node* create_linked_list(int n) {
    pthread_mutex_lock(&list_mutex);

    Node* head = NULL, *tail = NULL;

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Fill the structure with data
        pdu.ue_info_tag.RNTI = rand() % 65536; // Example RNTI value
        pdu.rnti = rand() % 65536;             // Example RNTI value
        pdu.crc_tag.CRCFLAG = rand() & 1;      // Random CRC flag (0 or 1)

        Node* new_node = create_node(pdu);
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            free_list(head);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        if (!head) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    pthread_mutex_unlock(&list_mutex);
    return head;
}

void serialize_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        return;
    }

    Node* current = head;

    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

Node* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("File opening failed");
        return NULL;
    }

    Node* head = NULL, *tail = NULL;

    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = create_node(pdu);
        if (!new_node) {
            perror("Memory allocation failed");
            free_list(head);
            fclose(file);
            return NULL;
        }

        if (!head) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    fclose(file);
    return head;
}

int main() {
    Node* list = create_linked_list(10000);
    serialize_list(list, "list_data.bin");
    free_list(list);

    Node* deserialized_list = deserialize_list("list_data.bin");
    free_list(deserialized_list);

    return 0;
}
