#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ListManager;

ListManager* create_list_manager(size_t max_size) {
    ListManager* manager = malloc(sizeof(ListManager));
    if (!manager) return NULL;

    manager->capacity = max_size > 0 ? max_size : MAX_STRUCTURES;
    manager->table = calloc(manager->capacity, sizeof(Node*));
    if (!manager->table) {
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

unsigned long hash(unsigned int rnti, unsigned int rx_tag) {
    return (rnti ^ (rx_tag << 1)) % ((unsigned long)MAX_STRUCTURES - 1);
}

int is_duplicate(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    unsigned long index = hash(pdu->RNTI, pdu->RX_UE_INFORMATION_TAG);

    pthread_mutex_lock(&manager->lock);
    Node* current = manager->table[index];
    while (current != NULL) {
        if ((current->data.RNTI == pdu->RNTI) && 
            (current->data.RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG)) {
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int add_pdu(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (is_duplicate(manager, pdu)) return -1;

    unsigned long index = hash(pdu->RNTI, pdu->RX_UE_INFORMATION_TAG);

    pthread_mutex_lock(&manager->lock);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Link the node into the list
    new_node->next = manager->table[index];
    manager->table[index] = new_node;

    if (manager->count < manager->capacity) {
        manager->count++;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

size_t get_count(ListManager* manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void free_list_manager(ListManager** manager) {
    if (!manager || !(*manager)) return;

    for (size_t i = 0; i < (*manager)->capacity; ++i) {
        Node* current = (*manager)->table[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    pthread_mutex_destroy(&(*manager)->lock);
    free((*manager)->table);
    free(*manager);
    *manager = NULL;
}

void serialize_list(ListManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->capacity; ++i) {
        Node* current = manager->table[i];
        while (current != NULL) {
            fwrite(&(current->data.RX_UE_INFORMATION_TAG), sizeof(current->data.RX_UE_INFORMATION_TAG), 1, file);
            fwrite(&(current->data.RNTI), sizeof(current->data.RNTI), 1, file);
            fwrite(current->data.CRC_INDICATION_REL8_TAG, sizeof(current->data.CRC_INDICATION_REL8_TAG), 1, file);
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

int deserialize_list(ListManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    while (get_count(manager) < count && !feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {0};

        if (fread(&(pdu.RX_UE_INFORMATION_TAG), sizeof(pdu.RX_UE_INFORMATION_TAG), 1, file) == 1 &&
            fread(&(pdu.RNTI), sizeof(pdu.RNTI), 1, file) == 1 &&
            fread(pdu.CRC_INDICATION_REL8_TAG, sizeof(pdu.CRC_INDICATION_REL8_TAG), 1, file) == 1) {

            add_pdu(manager, &pdu);
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);

    return 0;
}

