['```c
#include <stdio.h>
#include <stdlib.h>
import threading

typedef struct L2Entity {
    int id;
} L2Entity;

typedef struct MacConfig {
    int macId;
    L2Entity **l2Entities;
    size_t l2Count;
    char *state; // e.g., "initialized", "operational"
} MacConfig;

// Global lock for thread safety
pthread_mutex_t configLock = PTHREAD_MUTEX_INITIALIZER;

MacConfig* initMacConfigs(size_t initialSize) {
    pthread_mutex_lock(&configLock);

    MacConfig *configs = (MacConfig *)malloc(initialSize * sizeof(MacConfig));
    if (!configs) {
        perror("Failed to allocate memory for MAC configurations");
        pthread_mutex_unlock(&configLock);
        return NULL;
    }

    for (size_t i = 0; i < initialSize; ++i) {
        configs[i].macId = -1; // Uninitialized ID
        configs[i].l2Entities = NULL;
        configs[i].l2Count = 0;
        configs[i].state = strdup("initialized");
    }

    pthread_mutex_unlock(&configLock);
    return configs;
}

int resizeMacConfigs(MacConfig **configs, size_t newSize) {
    pthread_mutex_lock(&configLock);

    MacConfig *newConfigs = (MacConfig *)realloc(*configs, newSize * sizeof(MacConfig));
    if (!newConfigs) {
        perror("Failed to reallocate memory for MAC configurations");
        pthread_mutex_unlock(&configLock);
        return -1;
    }

    size_t oldSize = (*configs != NULL) ? ((*configs)[0].macId == -1) ? 0 : sizeof(MacConfig) / sizeof(**configs) : 0;

    if (newConfigs && oldSize < newSize) {
        for (size_t i = oldSize; i < newSize; ++i) {
            newConfigs[i].macId = -1;
            newConfigs[i].l2Entities = NULL;
            newConfigs[i].l2Count = 0;
            newConfigs[i].state = strdup("initialized");
        }
    }

    *configs = newConfigs;
    pthread_mutex_unlock(&configLock);
    return 0;
}

int addMacEntity(MacConfig **configs, size_t currentSize, int macId, L2Entity *l2Entities, size_t l2Count) {
    pthread_mutex_lock(&configLock);

    for (size_t i = 0; i < currentSize; ++i) {
        if ((*configs)[i].macId == -1) { // Find an empty slot
            (*configs)[i].macId = macId;

            // Ensure unique L2 entity references and avoid duplicates
            size_t maxL2Entities = l2Count * 2;
            L2Entity **uniqueL2s = (L2Entity **)malloc(maxL2Entities * sizeof(L2Entity *));
            if (!uniqueL2s) {
                perror("Failed to allocate memory for unique L2 entities");
                pthread_mutex_unlock(&configLock);
                return -1;
            }

            size_t idx = 0;
            for (size_t j = 0; j < l2Count; ++j) {
                int isUnique = 1;
                for (size_t k = 0; k < idx && isUnique; ++k) {
                    if (uniqueL2s[k]->id == l2Entities[j].id) {
                        isUnique = 0;
                    }
                }
                if (isUnique) {
                    uniqueL2s[idx++] = &l2Entities[j];
                }
            }

            (*configs)[i].l2Entities = realloc((*configs)[i].l2Entities, idx * sizeof(L2Entity *));
            if (!(*configs)[i].l2Entities) {
                perror("Failed to reallocate memory for L2 entities");
                free(uniqueL2s);
                pthread_mutex_unlock(&configLock);
                return -1;
            }
            (*configs)[i].l2Count = idx;
            memcpy((*configs)[i].l2Entities, uniqueL2s, idx * sizeof(L2Entity *));
            free(uniqueL2s);

            // Transition to operational state
            free((*configs)[i].state);
            (*configs)[i].state = strdup("operational");

            pthread_mutex_unlock(&configLock);
            return 0;
        }
    }

    // Resize if no empty slot is found
    size_t newSize = currentSize * 2;
    int resizeResult = resizeMacConfigs(configs, newSize);
    if (resizeResult == -1) {
        pthread_mutex_unlock(&configLock);
        return -1;
    }

    // Retry after resizing
    addMacEntity(configs, newSize, macId, l2Entities, l2Count);

    pthread_mutex_unlock(&configLock);
    return 0; // Success
}

void freeMacConfigs(MacConfig **configs) {
    pthread_mutex_lock(&configLock);

    if (*configs) {
        for (size_t i = 0; (*configs)[i].macId != -1 || (*configs)[i].l2Entities != NULL; ++i) {
            free((*configs)[i].state);
            free((*configs)[i].l2Entities);
        }
        free(*configs);
    }

    pthread_mutex_unlock(&configLock);
}
```']

