NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_api_array(size_t N, int retry_count) {
    size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    if (required_memory + current_memory_usage > MEMORY_THRESHOLD) {
        log_operation("Memory threshold exceeded");
        return NULL;
