        current_memory_usage += required_memory;

        for (size_t i = 0; i < N; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
            array[i].RNTI = rand() % 10000;

            if (include_crc_flag) {
                array[i].CRC_INDICATION_REL8_TAG.CRC_FLAG = rand() % 2;
            }
        }

        log_operation("Memory allocation successful");
        return array;
    }

    log_operation("Failed to allocate memory after retries");
    return NULL;
}

void free_nfa_api_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (!array) return;

    size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    current_memory_usage -= required_memory;
    free(array);
    log_operation("Memory deallocated");
}

// Example usage
int main() {
    srand(time(NULL));

    update_crc_flag_setting(1); // Enable CRC flag by default
    update_max_elements(800);   // Set max elements to 800

    size_t N = 500;
    int retry_count = 3;

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_nfa_api_array(N, retry_count);
    if (array) {
        // Use the array...
        free_nfa_api_array(array, N);
    }

    printf("Current memory usage: %zu bytes\n", get_current_memory_usage());
    return 0;
}
```

### Key Features:
- **Dynamic Memory Allocation**: Allocates memory for an array of `NFAPI_CRC_INDICATION_PDU_T` structures.
- **Error Handling and Logging**: Logs operations and handles allocation failures with retries.
- **Configuration Management**: Allows runtime updates to CRC flag inclusion and maximum elements without restarts.
- **Thread Safety**: Uses mutexes and read-write locks to ensure thread-safe configuration updates.
- **Memory Monitoring**: Tracks memory usage and prevents exceeding a specified threshold.
- **Modularity and Extensibility**: Designed for easy future enhancements.']

