    EventType type;
    int unique_id;
    struct NetworkEvent* next;
} NetworkEvent;

// Linked list to manage network events
typedef struct EventList {
    NetworkEvent* head;
    pthread_mutex_t lock; // Mutex for thread safety
} EventList;

// Initialize the event list
void init_event_list(EventList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new network event to the list
int add_network_event(EventList* list, EventType type, int unique_id) {
    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!new_event) return -1; // Memory allocation failure

    time(&new_event->timestamp);
    new_event->type = type;
    new_event->unique_id = unique_id;

    pthread_mutex_lock(&list->lock);

    new_event->next = list->head;
    list->head = new_event;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Remove events older than a specified time threshold
int remove_old_events(EventList* list, time_t threshold) {
    pthread_mutex_lock(&list->lock);

    NetworkEvent *current = list->head;
    NetworkEvent *prev = NULL;

    while (current != NULL) {
        if (difftime(threshold, current->timestamp) > 0) { // Event is older than threshold
            NetworkEvent* to_delete = current;
            if (prev == NULL) {
                list->head = current->next; // Update head if removing the first element
            } else {
                prev->next = current->next;
            }
            current = current->next;

            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Retrieve events by type
NetworkEvent* get_events_by_type(EventList* list, EventType type) {
    NetworkEvent *matched_events = NULL;
    NetworkEvent **tail = &matched_events;

    pthread_mutex_lock(&list->lock);

    for (NetworkEvent* current = list->head; current != NULL; current = current->next) {
        if (current->type == type) {
            *tail = (NetworkEvent*)malloc(sizeof(NetworkEvent));
            if (!(*tail)) break; // Memory allocation failure
            **tail = *current;
            (*tail)->next = NULL;
            tail = &((*tail)->next);
        }
    }

    pthread_mutex_unlock(&list->lock);

    return matched_events; // Returns a new list of events matching the type
}

// Function to log events (simulated interface with an external logging service)
void log_events(EventList* list) {
    NetworkEvent *current = list->head;

    while (current != NULL) {
        // Simulate logging event data to an external service
        printf("Logging Event ID: %d, Type: %d, Timestamp: %ld\n", current->unique_id, current->type, current->timestamp);

        // Handle potential failures in communication with the logging service here

        current = current->next;
    }
}

// Cleanup function to free allocated memory
void cleanup_event_list(EventList* list) {
    pthread_mutex_lock(&list->lock);

    NetworkEvent *current = list->head;
    while (current != NULL) {
        NetworkEvent *to_free = current;
        current = current->next;
        free(to_free);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    EventList event_list;
    init_event_list(&event_list);

    // Example usage
    add_network_event(&event_list, EVENT_TYPE_A, 1);
    add_network_event(&event_list, EVENT_TYPE_B, 2);

    time_t threshold = time(NULL) - 3600; // 1 hour ago
    remove_old_events(&event_list, threshold);

    NetworkEvent* events_of_type_a = get_events_by_type(&event_list, EVENT_TYPE_A);
    log_events(&event_list);

    // Free the memory of retrieved events if needed
    while (events_of_type_a != NULL) {
        NetworkEvent *temp = events_of_type_a;
        events_of_type_a = events_of_type_a->next;
        free(temp);
    }

    cleanup_event_list(&event_list);

    return 0;
}
