#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Use a larger type to allow for appending index
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    unsigned long key;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
    int added_count;
    int updated_count;
    int retrieved_count;
    int error_count;
} HashTable;

unsigned long hash_function(unsigned long key, size_t capacity) {
    return key % capacity;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    table->added_count = 0;
    table->updated_count = 0;
    table->retrieved_count = 0;
    table->error_count = 0;
    return table;
}

void log_operation(const char* operation, const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), operation, message);
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free_node(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void add_or_update_structure(HashTable* table, unsigned long RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(RNTI, table->capacity);
    Node* current = table->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->key == RNTI) {
            current->data = data;
            pthread_mutex_unlock(&table->lock);
            log_operation("UPDATE", "Updated existing structure");
            table->updated_count++;
            return;
        }
        prev = current;
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        log_operation("ERROR", "Failed to allocate memory for new node");
        table->error_count++;
        return;
    }

    new_node->key = RNTI;
    new_node->data = data;
    new_node->next = NULL;

    if (prev) {
        prev->next = new_node;
    } else {
        table->buckets[index] = new_node;
    }

    pthread_mutex_unlock(&table->lock);
    log_operation("ADD", "Added new structure");
    table->added_count++;
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(HashTable* table, unsigned long RNTI) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(RNTI, table->capacity);
    Node* current = table->buckets[index];

    while (current) {
        if (current->key == RNTI) {
            pthread_mutex_unlock(&table->lock);
            log_operation("RETRIEVE", "Retrieved structure");
            table->retrieved_count++;
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
    log_operation("ERROR", "Structure not found");
    table->error_count++;
    return NULL;
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}

int main() {
    srand(time(NULL));
    HashTable* table = create_hash_table(1000003); // Prime number for better distribution

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 123; // Example tag
    pdu.CRC_INDICATION_REL8_TAG = 456; // Example CRC indication

    unsigned long RNTI = 78901234; // Example RNTI
    set_random_crcflag(&pdu);

    add_or_update_structure(table, RNTI, pdu);
    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_structure(table, RNTI);

    if (retrieved_pdu) {
        printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%d, CRCFLAG=%d\n",
               retrieved_pdu->RX_UE_INFORMATION_TAG,
               retrieved_pdu->CRCFLAG);
    }

    destroy_hash_table(table);
    return 0;
}
