typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;  // For thread-safe operations
} List;

void initList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int isRNTIUnique(List* list, RNTI rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return 0;  // Not unique
        }
        current = current->next;
    }
    return 1;  // Unique
}

int addPDU(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!isRNTIUnique(list, pdu.rnti)) {
        pthread_mutex_unlock(&list->lock);
        return -1;  // RNTI not unique
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -2;  // Memory allocation failed
    }

    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

void removePDU(List* list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {  // RNTI not found
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

void clearList(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void destroyList(List* list) {
    clearList(list);
    pthread_mutex_destroy(&list->lock);
}

// Function to create and add a PDU with random CRCFLAG
