#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    float minValue;
    float maxValue;
    pthread_mutex_t mutex;
    int currentIndex; // For managing the range exhaustion
    const int size;
    float *values;
} DynamicValueGenerator;

DynamicValueGenerator* create_dynamic_value_generator(float min, float max) {
    DynamicValueGenerator* generator = malloc(sizeof(DynamicValueGenerator));
    if (!generator) return NULL;

    generator->minValue = min;
    generator->maxValue = max;
    pthread_mutex_init(&generator->mutex, NULL);
    generator->currentIndex = 0;
    generator->size = (int)((max - min + 1.0f) * 100); // Arbitrary precision for float range
    generator->values = malloc(generator->size * sizeof(float));

    if (!generator->values) {
        free(generator);
        return NULL;
    }

    for (int i = 0; i < generator->size; ++i) {
        generator->values[i] = min + ((float)i / 100.0f);
    }
    return generator;
}

void destroy_dynamic_value_generator(DynamicValueGenerator* generator) {
    if (!generator) return;

    pthread_mutex_destroy(&generator->mutex);
    free(generator->values);
    free(generator);
}

float get_random_float(DynamicValueGenerator* generator, float exclusiveMin, float exclusiveMax) {
    pthread_mutex_lock(&generator->mutex);

    if (exclusiveMin >= exclusiveMax || exclusiveMin < generator->minValue || exclusiveMax > generator->maxValue) {
        pthread_mutex_unlock(&generator->mutex);
        fprintf(stderr, "Invalid range for GetRandomFloatExclusive.\n");
        return 0.0f;
    }

    float result = 0.0f;
    if (generator->currentIndex < generator->size) {
        int index = rand() % (int)((exclusiveMax - exclusiveMin) * 100);
        while(generator->values[generator->currentIndex] <= exclusiveMin || 
              generator->values[generator->currentIndex] >= exclusiveMax) {
            generator->currentIndex++;
            if (generator->currentIndex >= generator->size) {
                fprintf(stderr, "Range exhausted.\n");
                pthread_mutex_unlock(&generator->mutex);
                return 0.0f;
            }
        }

        result = generator->values[generator->currentIndex];
        generator->currentIndex++;

    } else {
        fprintf(stderr, "DynamicValueGenerator range exhausted.\n");
    }

    pthread_mutex_unlock(&generator->mutex);
    return result;
}

float get_random_float_exclusive(DynamicValueGenerator* generator) {
    float minValue = generator->minValue + 0.01f; // Arbitrary small increment
    float maxValue = generator->maxValue - 0.01f; // Arbitrary small decrement

    return get_random_float(generator, minValue, maxValue);
}

int get_random_int(DynamicValueGenerator* generator) {
    pthread_mutex_lock(&generator->mutex);

    if (generator->currentIndex >= generator->size) {
        fprintf(stderr, "DynamicValueGenerator range exhausted.\n");
        pthread_mutex_unlock(&generator->mutex);
        return 0;
    }

    int result = rand() % (int)(generator->maxValue - generator->minValue + 1);
    generator->currentIndex++;

    pthread_mutex_unlock(&generator->mutex);
    return result;
}

void adjust_range(DynamicValueGenerator* generator, float newMin, float newMax) {
    if (newMin > newMax || newMin < generator->minValue || newMax > generator->maxValue) {
        fprintf(stderr, "Invalid range for AdjustRange.\n");
        return;
    }

    pthread_mutex_lock(&generator->mutex);
    generator->minValue = newMin;
    generator->maxValue = newMax;

    // Reinitialize values with the new range
    free(generator->values);
    generator->size = (int)((newMax - newMin + 1.0f) * 100); 
    generator->values = malloc(generator->size * sizeof(float));

    if (!generator->values) {
        fprintf(stderr, "Memory allocation failed during AdjustRange.\n");
    } else {
        for (int i = 0; i < generator->size; ++i) {
            generator->values[i] = newMin + ((float)i / 100.0f);
        }
    }

    pthread_mutex_unlock(&generator->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfarec_pdu_list(int num_pdus, DynamicValueGenerator* generator) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) return NULL;

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_pdus; ++i) {
        pduList[i].RNTI = get_random_int(generator);
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pduList[i].CRC_INDICATION_REL8_TAG = (unsigned short)get_random_float_exclusive(generator);
    }

    return pduList;
}

int main() {
    DynamicValueGenerator* generator = create_dynamic_value_generator(0.0f, 100.0f);

    int num_pdus = 10; // Example number of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_nfarec_pdu_list(num_pdus, generator);

    if (pdus) {
        for (int i = 0; i < num_pdus; ++i) {
            printf("RNTI: %u, RX_UE_INFORMATION_TAG: %d, CRC_INDICATION_REL8_TAG: %hu\n",
                   pdus[i].RNTI,
                   pdus[i].RX_UE_INFORMATION_TAG,
                   pdus[i].CRC_INDICATION_REL8_TAG);
        }
    }

    free(pdus);
    destroy_dynamic_value_generator(generator);

    return 0;
}
