typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to compare two structures based on RNTI
int compareRNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pduA->RNTI - pduB->RNTI;
}

// Thread-safe function to dynamically allocate and initialize an array of structures
NFAPI_CRC_INDICATION_PDU_T* createAndInitializeArray(size_t numElements) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Initialize the array with random values
    srand(time(NULL));  // Seed for randomness
    for (size_t i = 0; i < numElements; ++i) {
        pthread_mutex_lock(&lock);

        array[i].RX_UE_INFORMATION_TAG = rand() % 100;  // Example value
        array[i].RNTI = rand() % 65536;  // Random RNTI in the range of unsigned short

        // Set CRCFLAG to a random value (0 or 1)
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&lock);
    }

    // Sort the array based on RNTI
    qsort(array, numElements, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareRNTI);

    pthread_mutex_destroy(&lock);

    return array;
}

// Function to release allocated resources
void freeArray(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
