    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicArray;

// Function to initialize the dynamic array
void initDynamicArray(DynamicArray *da) {
    da->capacity = 10; // Initial capacity
    da->count = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->lock, NULL);
}

// Function to resize the dynamic array
void resizeArray(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    da->array = new_array;
    da->capacity = new_capacity;
}

// Function to add a new element
void addElement(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        resizeArray(da, da->capacity * 2); // Double the capacity
    }

    da->array[da->count++] = element;

    pthread_mutex_unlock(&da->lock);
}

// Function to retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T getElement(DynamicArray *da, size_t index) {
    if (index >= da->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&da->lock);

    NFAPI_CRC_INDICATION_PDU_T element = da->array[index];

    pthread_mutex_unlock(&da->lock);

    return element;
}

// Function to remove an element by index
void removeElement(DynamicArray *da, size_t index) {
    if (index >= da->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&da->lock);

    for (size_t i = index; i < da->count - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    --da->count;

    if (da->capacity > 10 && da->count <= da->capacity / 4) {
        resizeArray(da, da->capacity / 2); // Halve the capacity
    }

    pthread_mutex_unlock(&da->lock);
}

// Function to reorder array based on RNTI value
void reorderArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count - 1; ++i) {
        for (size_t j = i + 1; j < da->count; ++j) {
            if (da->array[i].RNTI > da->array[j].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = da->array[i];
                da->array[i] = da->array[j];
                da->array[j] = temp;
            }
        }
    }

    pthread_mutex_unlock(&da->lock);
}

// Function to free the dynamic array
void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;

    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

// Function to set a random CRCFLAG
void setRandomCRCFLAG(NFAPI_CRC_INDICATION_PDU_T *element) {
    element->crc_indication_rel8.CRCFLAG = rand() % 2; // Randomly 0 or 1
}
