```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
} List;

// Function to create a new list
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

// Check for duplicate RNTI
int has_duplicate_RNTI(List* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

// Add a new structure
int add_structure(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_rwlock_wrlock(&list->lock);
    if (has_duplicate_RNTI(list, pdu->RNTI)) {
        pthread_rwlock_unlock(&list->lock);
        return -1; // Duplicate RNTI
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    memcpy(&(new_node->data), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Update CRCFLAG by index
int update_crcflag(List* list, int index, int crcflag) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    for (int i = 0; current && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->lock);
        return -1; // Index out of bounds
    }

    current->data.CRCFLAG = crcflag;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Remove structure by RNTI
int remove_structure_by_rnti(List* list, unsigned int rnti) {
    pthread_rwlock_wrlock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->lock);
        return -1; // RNTI not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Free the entire list and destroy lock
void free_list(List* list) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    List* nfa_list = create_list();
    if (!nfa_list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 2, rand() % 2};
    add_structure(nfa_list, &pdu1);

    update_crcflag(nfa_list, 0, 1);

    remove_structure_by_rnti(nfa_list, 1001);

    free_list(nfa_list);
    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_rwlock_t` for read-write locks to handle concurrent access efficiently.
- **Memory Management**: Dynamically allocates nodes and ensures they are freed properly.
- **Input Validation**: Checks for duplicate RNTI and valid indices.
- **Performance Considerations**: Minimizes lock contention by using read-write locks, allowing multiple readers or a single writer at a time."]

