#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int id;
    char rrc_state[20];
} BearerContext;

typedef struct {
    int ue_id;
    char rrc_state[10];
    BearerContext *bearers;
    size_t bearer_count;
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t size;
    size_t count;
} UETable;

static void hash_table_resize(UETable *table);
static int hash_function(int ue_id, size_t table_size);

UETable* initialize_ue_table() {
    UETable *table = malloc(sizeof(UETable));
    if (!table) return NULL;

    table->size = INITIAL_CAPACITY;
    table->contexts = calloc(table->size, sizeof(UEContext *));
    if (!table->contexts) {
        free(table);
        return NULL;
    }
    table->count = 0;

    return table;
}

static int hash_function(int ue_id, size_t table_size) {
    return (ue_id % table_size + table_size) % table_size;
}

void add_ue_context(UETable *table, UEContext *context) {
    if (!table || !context) return;

    size_t index = hash_function(context->ue_id, table->size);
    while (table->contexts[index]) {
        if (table->contexts[index]->ue_id == context->ue_id) {
            free(table->contexts[index]->bearers);
            table->contexts[index] = context; // Update existing
            return;
        }
        index = (index + 1) % table->size;
    }

    table->contexts[index] = context;

    if ((double)table->count / table->size > LOAD_FACTOR_THRESHOLD) {
        hash_table_resize(table);
    } else {
        table->count++;
    }
}

UEContext* get_ue_context(UETable *table, int ue_id) {
    if (!table) return NULL;

    size_t index = hash_function(ue_id, table->size);
    for (size_t i = 0; i < table->size; ++i) {
        UEContext *context = table->contexts[index];
        if (context && context->ue_id == ue_id) {
            return context;
        }
        index = (index + 1) % table->size;
    }
    return NULL;
}

void remove_ue_context(UETable *table, int ue_id) {
    if (!table) return;

    size_t index = hash_function(ue_id, table->size);
    for (size_t i = 0; i < table->size; ++i) {
        UEContext *context = table->contexts[index];
        if (context && context->ue_id == ue_id) {
            free(context->bearers);
            free(context);

            // Remove by shifting elements
            while ((index + 1) % table->size != i) {
                size_t next_index = (index + 1) % table->size;
                table->contexts[index] = table->contexts[next_index];
                index = next_index;
            }
            table->contexts[index] = NULL;

            table->count--;
            return;
        }
        index = (index + 1) % table->size;
    }
}

static void hash_table_resize(UETable *table) {
    size_t new_size = table->size * 2;
    UEContext **new_contexts = calloc(new_size, sizeof(UEContext *));

    if (!new_contexts) return;

    for (size_t i = 0; i < table->size; ++i) {
        if (table->contexts[i]) {
            size_t index = hash_function(table->contexts[i]->ue_id, new_size);
            while (new_contexts[index]) {
                index = (index + 1) % new_size;
            }
            new_contexts[index] = table->contexts[i];
        }
    }

    free(table->contexts);
    table->contexts = new_contexts;
    table->size = new_size;
}

void iterate_ue_contexts(UETable *table, void (*callback)(UEContext *)) {
    if (!table || !callback) return;

    for (size_t i = 0; i < table->size; ++i) {
        UEContext *context = table->contexts[i];
        if (context) {
            callback(context);
        }
    }
}

void free_ue_table(UETable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        UEContext *context = table->contexts[i];
        if (context) {
            free(context->bearers);
            free(context);
        }
    }

    free(table->contexts);
    free(table);
}

// Optional logging mechanism
typedef enum { LOG_OFF, LOG_ON } LogLevel;
static LogLevel log_level = LOG_OFF;

void set_log_level(LogLevel level) {
    log_level = level;
}

static void log_operation(const char *message) {
    if (log_level == LOG_ON) {
        printf("%s\n", message);
    }
}

// Usage example with logging
int main() {
    UETable *ue_table = initialize_ue_table();
    set_log_level(LOG_ON);

    UEContext context1 = { .ue_id = 1, .rrc_state = "connected" };
    add_ue_context(ue_table, &context1);
    log_operation("Added UE Context ID: 1");

    UEContext *retrieved_context = get_ue_context(ue_table, 1);
    if (retrieved_context) {
        log_operation("Retrieved UE Context ID: 1");
    }

    remove_ue_context(ue_table, 1);
    log_operation("Removed UE Context ID: 1");

    free_ue_table(ue_table);
    return 0;
}
