['Below is a C implementation of a dynamically resizable linked list designed to manage `NFAPI_CRC_INDICATION_PDU_T` structures. The implementation ensures unique identification by `RNTI`, handles memory allocation errors gracefully, supports insertion at both head and tail positions, provides an iterator for traversal, accommodates scaling issues with configurable maximum size, and includes basic considerations for concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold CRC indication data.
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG; // Randomly set flag for demonstration
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG crcData;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list structure.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    unsigned int max_size; // Configurable maximum size
    pthread_mutex_t lock;  // Mutex for thread safety
} CRCList;

// Function to initialize the list.
void initCRCList(CRCList *list, unsigned int maxSize) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = maxSize;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to free the entire list.
void destroyCRCList(CRCList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Function to insert at the head.
int insertAtHead(CRCList *list, unsigned int rxTag, unsigned int rnti) {
    if (list->size >= list->max_size) return -1; // List is full

    pthread_mutex_lock(&list->lock);

    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        if (current->crcData.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation error
    }

    newNode->crcData.RX_UE_INFORMATION_TAG = rxTag;
    newNode->crcData.RNTI = rnti;
    newNode->crcData.CRCFLAG = rand() % 2; // Randomly set flag for demonstration
    newNode->next = list->head;
    list->head = newNode;

    if (list->tail == NULL) {
        list->tail = newNode;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to insert at the tail.
int insertAtTail(CRCList *list, unsigned int rxTag, unsigned int rnti) {
    if (list->size >= list->max_size) return -1; // List is full

    pthread_mutex_lock(&list->lock);

    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        if (current->crcData.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation error
    }

    newNode->crcData.RX_UE_INFORMATION_TAG = rxTag;
    newNode->crcData.RNTI = rnti;
    newNode->crcData.CRCFLAG = rand() % 2; // Randomly set flag for demonstration
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }

    list->tail = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to iterate over the list.
void forEach(CRCList *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example callback function for iteration
void printNode(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (node) {
        printf("RNTI: %u, RX Tag: %u, CRC Flag: %d\n",
               node->crcData.RNTI,
               node->crcData.RX_UE_INFORMATION_TAG,
               node->crcData.CRCFLAG);
    }
}

// Example usage
int main() {
    CRCList list;
    initCRCList(&list, 100); // Initialize with a max size of 100

    insertAtHead(&list, 1, 1234);
    insertAtTail(&list, 2, 5678);

    forEach(&list, printNode);

    destroyCRCList(&list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex (`pthread_mutex_t`) to ensure thread safety when modifying the list.
- **Error Handling**: Functions return specific error codes for full list, duplicate `RNTI`, and memory allocation failures.
- **Memory Management**: Memory is allocated dynamically for each new node. The `destroyCRCList` function ensures all allocated memory is freed.
- **Iterator**: `forEach` provides a mechanism to traverse the list with a callback function.

This implementation balances performance and memory usage while providing mechanisms to handle common edge cases, such as duplicate entries or full capacity.']

