import string.h>

typedef struct {
    // Assuming a basic structure for MAC_Header
    unsigned char version;
    unsigned char type;
    unsigned short length;
} MAC_Header;

typedef struct {
    MAC_Header header;
    void *data;  // Pointer to variable-length data
    size_t data_length;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T **pdus;
    size_t count;
    size_t capacity;
} PDU_List;

// Function prototypes
PDU_List* initialize_pdu_list(size_t initial_capacity);
int add_pdu_to_list(PDU_List *list, MAC_Header header, void *data, size_t data_length);
void free_pdu_list(PDU_List *list);

int validate_mac_header(MAC_Header *header) {
    // Example validation logic: Check if version and type are within expected ranges
    return header && (header->version == 1) && (header->type >= 0) && (header->type <= 255);
}

PDU_List* initialize_pdu_list(size_t initial_capacity) {
    PDU_List *list = malloc(sizeof(PDU_List));
    if (!list) return NULL;

    list->pdus = malloc(initial_capacity * sizeof(MAC_PDU_T *));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

int add_pdu_to_list(PDU_List *list, MAC_Header header, void *data, size_t data_length) {
    if (!validate_mac_header(&header)) {
        fprintf(stderr, "Invalid MAC Header\n");
        return -1;  // Invalid header
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        MAC_PDU_T **new_pdus = realloc(list->pdus, new_capacity * sizeof(MAC_PDU_T *));
        if (!new_pdus) return -1;  // Out of memory

        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    MAC_PDU_T *pdu = malloc(sizeof(MAC_PDU_T));
    if (!pdu) return -1;  // Out of memory

    pdu->header = header;
    pdu->data_length = data_length;

    if (data_length > 0) {
        pdu->data = malloc(data_length);
        if (!pdu->data) {
            free(pdu);  // Clean up allocation
            return -1;  // Out of memory
        }
        memcpy(pdu->data, data, data_length);
    } else {
        pdu->data = NULL;
    }

    list->pdus[list->count++] = pdu;

    return 0;  // Success
}

void free_pdu_list(PDU_List *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        MAC_PDU_T *pdu = list->pdus[i];
        if (pdu && pdu->data) {
            free(pdu->data);
        }
        free(pdu);
    }

    free(list->pdus);
    free(list);
}
