['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define SESSION_TIMEOUT 60 // Timeout threshold in seconds

typedef struct Packet {
    int sequence_number;
    time_t timestamp;
} Packet;

typedef struct SessionContext {
    char CID[256];
    char peer_address[128];
    Packet *packets;
    size_t packet_count;
    pthread_mutex_t lock; // Mutex for concurrency
    time_t last_updated;  // Timestamp of the last update
} SessionContext;

typedef struct Node {
    SessionContext *session;
    struct Node *next;
} Node;

typedef struct SessionList {
    Node *head;
    pthread_rwlock_t list_lock; // Read-write lock for concurrency control
} SessionList;

SessionList session_list = {NULL, PTHREAD_RWLOCK_INITIALIZER};

// Function to create a new session context
SessionContext* create_session_context(const char *CID, const char *peer_address) {
    SessionContext *session = malloc(sizeof(SessionContext));
    if (!session) return NULL;

    strncpy(session->CID, CID, sizeof(session->CID) - 1);
    strncpy(session->peer_address, peer_address, sizeof(session->peer_address) - 1);
    session->packets = NULL;
    session->packet_count = 0;
    pthread_mutex_init(&session->lock, NULL);
    session->last_updated = time(NULL);

    return session;
}

// Function to add or update a session context
void add_or_update_session(const char *CID, const char *peer_address, int sequence_number) {
    pthread_rwlock_wrlock(&session_list.list_lock);

    Node *current = session_list.head;
    while (current) {
        SessionContext *session = current->session;

        pthread_mutex_lock(&session->lock);
        if (strcmp(session->CID, CID) == 0) {
            // Update existing session
            if (time(NULL) - session->last_updated > SESSION_TIMEOUT) {
                // Handle expired sessions
                pthread_mutex_unlock(&session->lock);
                continue;
            }

            // Add packet to the session
            Packet *new_packets = realloc(session->packets, sizeof(Packet) * (session->packet_count + 1));
            if (!new_packets) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&session->lock);
                pthread_rwlock_unlock(&session_list.list_lock);
                return;
            }

            session->packets = new_packets;
            session->packets[session->packet_count].sequence_number = sequence_number;
            session->packets[session->packet_count].timestamp = time(NULL);
            session->packet_count++;

            session->last_updated = time(NULL);

            pthread_mutex_unlock(&session->lock);
            break;
        }
        pthread_mutex_unlock(&session->lock);

        current = current->next;
    }

    if (current == NULL) {
        // Create new session
        SessionContext *new_session = create_session_context(CID, peer_address);
        if (!new_session) {
            fprintf(stderr, "Failed to create a new session context\n");
            pthread_rwlock_unlock(&session_list.list_lock);
            return;
        }

        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            free(new_session);
            fprintf(stderr, "Memory allocation failed for new node\n");
            pthread_rwlock_unlock(&session_list.list_lock);
            return;
        }

        new_node->session = new_session;
        new_node->next = session_list.head;
        session_list.head = new_node;

        pthread_mutex_lock(&new_session->lock);
        // Initialize with first packet
        Packet *initial_packet = malloc(sizeof(Packet));
        if (!initial_packet) {
            fprintf(stderr, "Memory allocation failed for initial packet\n");
            free(new_node);
            pthread_rwlock_unlock(&session_list.list_lock);
            return;
        }

        new_session->packets = initial_packet;
        new_session->packets[0].sequence_number = sequence_number;
        new_session->packets[0].timestamp = time(NULL);
        new_session->packet_count = 1;

        pthread_mutex_unlock(&new_session->lock);
    }

    pthread_rwlock_unlock(&session_list.list_lock);
}

// Function to retrieve a session by CID
SessionContext* get_session_by_CID(const char *CID) {
    pthread_rwlock_rdlock(&session_list.list_lock);

    Node *current = session_list.head;
    while (current) {
        SessionContext *session = current->session;

        pthread_mutex_lock(&session->lock);
        if (strcmp(session->CID, CID) == 0) {
            pthread_mutex_unlock(&session->lock);
            pthread_rwlock_unlock(&session_list.list_lock);
            return session;
        }
        pthread_mutex_unlock(&session->lock);

        current = current->next;
    }

    pthread_rwlock_unlock(&session_list.list_lock);
    return NULL;
}

// Function to purge expired sessions
void purge_expired_sessions() {
    pthread_rwlock_wrlock(&session_list.list_lock);

    Node *current = session_list.head;
    Node *prev = NULL;

    while (current) {
        SessionContext *session = current->session;

        pthread_mutex_lock(&session->lock);
        if (time(NULL) - session->last_updated > SESSION_TIMEOUT) {
            // Remove expired session
            Node *to_delete = current;
            current = current->next;

            free(session->packets); // Free packets memory
            pthread_mutex_destroy(&session->lock); // Destroy mutex
            free(session); // Free session context

            if (prev == NULL) {
                // Removing head node
                session_list.head = current;
            } else {
                prev->next = current;
            }

            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }

        pthread_mutex_unlock(&session->lock);
    }

    pthread_rwlock_unlock(&session_list.list_lock);
}

// Function to cleanup and destroy the session list
void destroy_session_list() {
    Node *current = session_list.head;

    while (current) {
        SessionContext *session = current->session;
        free(session->packets); // Free packets memory
        pthread_mutex_destroy(&session->lock); // Destroy mutex
        free(session); // Free session context

        Node *to_delete = current;
        current = current->next;
        free(to_delete);
    }

    pthread_rwlock_destroy(&session_list.list_lock);
}

int main() {
    // Example usage
    add_or_update_session("CID1", "192.168.0.1", 1001);

    SessionContext *session = get_session_by_CID("CID1");
    if (session) {
        printf("Session found: CID=%s, Address=%s\n", session->CID, session->peer_address);
    } else {
        printf("Session not found.\n");
    }

    // Purge expired sessions
    purge_expired_sessions();

    destroy_session_list();
    return 0;
}
```

### Explanation of Key Elements:

