}

int add_or_update_packet(PacketList *list, int packet_id, const char *new_payload) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            // Update existing packet
            free(current->data.payload);
            size_t payload_size = strlen(new_payload) + 1;
            if (payload_size > MAX_PAYLOAD_SIZE) payload_size = MAX_PAYLOAD_SIZE;
            current->data.payload = malloc(payload_size);
            strncpy(current->data.payload, new_payload, payload_size - 1);
            current->data.payload[payload_size - 1] = '\0';
            current->data.timestamp = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }

    // Add new packet
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }
    size_t payload_size = strlen(new_payload) + 1;
    if (payload_size > MAX_PAYLOAD_SIZE) payload_size = MAX_PAYLOAD_SIZE;
    new_node->data.payload = malloc(payload_size);
    if (!new_node->data.payload) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }
    strncpy(new_node->data.payload, new_payload, payload_size - 1);
    new_node->data.payload[payload_size - 1] = '\0';
    new_node->data.packet_id = packet_id;
    new_node->data.timestamp = time(NULL);
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

DataPacket* get_packet(PacketList *list, int packet_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            DataPacket *packet_copy = malloc(sizeof(DataPacket));
            if (!packet_copy) {
                pthread_mutex_unlock(&list->lock);
                return NULL; // Memory allocation failure
            }
            memcpy(packet_copy, &current->data, sizeof(DataPacket));
            pthread_mutex_unlock(&list->lock);
            return packet_copy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Packet not found
}

void free_packet_data(DataPacket *packet) {
