['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PAYLOAD_SIZE 4096
#define COMPACT_THRESHOLD 0.5

typedef struct {
    int packet_id;
    char *payload;
    time_t timestamp;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t capacity;
    size_t count;
    pthread_key_t key;
} PacketArray;

void* thread_local_allocator(void) {
    return NULL; // Placeholder for thread-local memory allocation
}

static void initialize_thread_local_storage() {
    pthread_key_create(&((PacketArray*)0)->key, thread_local_allocator);
}

DataPacket* create_packet(int packet_id, const char *payload) {
    DataPacket *packet = (DataPacket *)malloc(sizeof(DataPacket));
    if (!packet) return NULL;

    packet->packet_id = packet_id;
    size_t payload_len = strlen(payload);
    if (payload_len > MAX_PAYLOAD_SIZE) {
        free(packet);
        return NULL;
    }

    packet->payload = strdup(payload);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    packet->timestamp = time(NULL);

    return packet;
}

void destroy_packet(DataPacket *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

static void expand_array(PacketArray *array, size_t new_capacity) {
    DataPacket **new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket *));
    if (!new_packets) return;

    array->packets = new_packets;
    array->capacity = new_capacity;
}

void initialize_packet_array(PacketArray *array, size_t initial_capacity) {
    pthread_once(&((PacketArray*)0)->key, initialize_thread_local_storage);

    array->count = 0;
    array->capacity = initial_capacity;
    array->packets = calloc(array->capacity, sizeof(DataPacket *));
    if (!array->packets) exit(EXIT_FAILURE);
}

void add_packet(PacketArray *array, DataPacket *packet) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        expand_array(array, new_capacity);
    }

    array->packets[array->count++] = packet;
}

DataPacket* get_packet(PacketArray *array, int packet_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->packet_id == packet_id) {
            return array->packets[i];
        }
    }
    return NULL;
}

void update_packet(PacketArray *array, int packet_id, const char *new_payload) {
    DataPacket *packet = get_packet(array, packet_id);
    if (packet) {
        size_t new_payload_len = strlen(new_payload);
        if (new_payload_len > MAX_PAYLOAD_SIZE) return;

        free(packet->payload);
        packet->payload = strdup(new_payload);
        if (packet->payload) packet->timestamp = time(NULL);
    }
}

void compact_array(PacketArray *array) {
    if (array->count / (double)array->capacity <= COMPACT_THRESHOLD) {
        size_t new_capacity = array->capacity / 2;
        expand_array(array, new_capacity);
    }
}

void serialize_packets(const PacketArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->packets[i]->packet_id, sizeof(int), 1, file);
        size_t payload_len = strlen(array->packets[i]->payload) + 1;
        fwrite(&payload_len, sizeof(size_t), 1, file);
        fwrite(array->packets[i]->payload, sizeof(char), payload_len, file);
        fwrite(&array->packets[i]->timestamp, sizeof(time_t), 1, file);
    }

    fclose(file);
}

void deserialize_packets(PacketArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    expand_array(array, count);

    for (size_t i = 0; i < count; ++i) {
        int packet_id;
        size_t payload_len;
        time_t timestamp;

        fread(&packet_id, sizeof(int), 1, file);
        fread(&payload_len, sizeof(size_t), 1, file);

        if (payload_len > MAX_PAYLOAD_SIZE + 1) continue;

        char *payload = malloc(payload_len);
        fread(payload, sizeof(char), payload_len, file);
        fread(&timestamp, sizeof(time_t), 1, file);

        DataPacket *packet = create_packet(packet_id, payload);
        free(payload);

        if (packet) array->packets[array->count++] = packet;
    }

    fclose(file);
}

void cleanup_packet_array(PacketArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        destroy_packet(array->packets[i]);
    }
    free(array->packets);
}
