}

void add_or_update_packet(PacketList *list, int packet_id, const char *new_payload) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            // Update existing packet
            free(current->data.payload);
            size_t payload_len = strlen(new_payload);
            if (payload_len > MAX_PAYLOAD_SIZE) {
                payload_len = MAX_PAYLOAD_SIZE;
                log_warning("Payload truncated to maximum allowed size.");
            } else if (payload_len < MIN_PAYLOAD_SIZE) {
                log_warning("Payload size is below the minimum recommended size.");
            }
            current->data.payload = strndup(new_payload, payload_len);
            current->data.last_updated = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    // Add new packet
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_warning("Memory allocation failed for new packet.");
        return;
    }
    size_t payload_len = strlen(new_payload);
    if (payload_len > MAX_PAYLOAD_SIZE) {
        payload_len = MAX_PAYLOAD_SIZE;
        log_warning("Payload truncated to maximum allowed size.");
    } else if (payload_len < MIN_PAYLOAD_SIZE) {
        log_warning("Payload size is below the minimum recommended size.");
    }
    new_node->data.packet_id = packet_id;
    new_node->data.payload = strndup(new_payload, payload_len);
    new_node->data.last_updated = time(NULL);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

DataPacket* get_packet(PacketList *list, int packet_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            DataPacket *packet_copy = (DataPacket *)malloc(sizeof(DataPacket));
            if (!packet_copy) {
                pthread_mutex_unlock(&list->lock);
                log_warning("Memory allocation failed for packet copy.");
                return NULL;
            }
            packet_copy->packet_id = current->data.packet_id;
            packet_copy->payload = strdup(current->data.payload);
            packet_copy->last_updated = current->data.last_updated;
            pthread_mutex_unlock(&list->lock);
            return packet_copy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    log_warning("Packet with specified ID not found.");
    return NULL;
}

int main() {
