};

// CRC_INDICATION_REL8_TAG structure
struct CRC_INDICATION_REL8_TAG {
    uint32_t CRCFLAG;
};

// NFAPI_CRC_INDICATION_PDU_T structure derived from custom base
struct NFAPI_CRC_INDICATION_PDU_T {
    struct RX_UE_INFORMATION_TAG {
        int id; // Simplified for illustration
    } rx_ue_info;

    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

// NFV entity class derived from the structure
class NFVEntity : public NFAPI_CRC_INDICATION_PDU_T {
public:
    using Base = NFAPI_CRC_INDICATION_PDU_T;

    // Constructor to initialize with random CRCFLAG
    NFVEntity() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);
        crc_indication_rel8_tag.CRCFLAG = dis(gen);
    }
};

// Cache manager class
class CacheManager {
public:
    void addItem(std::shared_ptr<NFVEntity> entity) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_.push_back(entity);
    }

    // Simple invalidation policy based on time-to-live (TTL)
    void invalidateOldEntries() {
        auto now = std::chrono::steady_clock::now();
        for (auto it = cache_.begin(); it != cache_.end();) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - (*it)->ttl_).count() > TTL) {
                it = cache_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    std::vector<std::shared_ptr<NFVEntity>> cache_;
    const int TTL = 60; // Time-to-live in seconds
    mutable std::mutex mutex_; // Mutex for thread-safe access
};

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
std::vector<std::shared_ptr<NFVEntity>> initializeEntities(size_t count) {
    std::vector<std::shared_ptr<NFVEntity>> entities;
    for (size_t i = 0; i < count; ++i) {
        auto entity = std::make_shared<NFVEntity>();
        entity->rx_ue_info.id = i; // Example initialization
        entity->RNTI = static_cast<uint16_t>(i + 1); // Example RNTI setting
        entities.push_back(entity);
    }
