#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

// Function to generate a unique RNTI within the specified range
uint16_t generate_unique_rnti(uint16_t used_rtis[], size_t count) {
    uint16_t rnti = 0;
    do {
        rnti = (rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;
    } while (!is_unique_rnti(rnti, used_rtis, count));
    return rnti;
}

// Check if an RNTI is unique
bool is_unique_rnti(uint16_t rnti, uint16_t *used_rtis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (used_rtis[i] == rnti) {
            return false;
        }
    }
    return true;
}

// Initialize the dynamic array
DynamicArray* init_dynamic_array(size_t initial_size) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for DynamicArray");
        exit(EXIT_FAILURE);
    }

    array->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        perror("Failed to allocate memory for data array");
        exit(EXIT_FAILURE);
    }

    array->size = initial_size;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Resize the dynamic array
bool resize_dynamic_array(DynamicArray *array, size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory for data array");
        return false;
    }

    array->data = new_data;
    array->size = new_size;
    return true;
}

// Free the dynamic array
void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}

// Function to dynamically allocate and populate NFAPI_CRC_INDICATION_PDU_T structures
DynamicArray* create_nfaapi_crc_indication_pdu_array(size_t N) {
    if (N == 0) return NULL;

    DynamicArray *array = init_dynamic_array(N);

    uint16_t used_rtis[N];
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&array->lock);

        array->data[i].RX_UE_INFORMATION_TAG = rand(); // Assuming a valid tag is any random value
        array->data[i].RNTI = generate_unique_rnti(used_rtis, i);
        used_rtis[i] = array->data[i].RNTI;

        array->data[i].tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        pthread_mutex_unlock(&array->lock);
    }

    return array;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t N = 10;
    DynamicArray *crc_array = create_nfaapi_crc_indication_pdu_array(N);

    if (crc_array) {
        for (size_t i = 0; i < crc_array->size; ++i) {
            printf("RNTI: %u, CRCFLAG: %d\n", crc_array->data[i].RNTI, crc_array->data[i].tag.CRCFLAG);
        }

        free_dynamic_array(crc_array);
    }

    return 0;
}
```

### Key Points:
- **Concurrency**: The function uses a mutex (`pthread_mutex_t`) to ensure thread safety when populating the array.
- **Memory Management**: Memory is dynamically allocated and freed using `malloc`, `calloc`, `realloc`, and `free`. This ensures efficient memory usage.
- **Error Handling**: The code checks for allocation failures and handles them by printing an error message and exiting gracefully.
- **Unique RNTI Generation**: Ensures unique `RNTI` values are generated within the specified range.']

['Below is a C implementation that initializes and manages a dynamic array of `LTE_DL_FRAMEINFO` structures using a pool allocation strategy. It includes efficient memory management, fast access to frames by number, and thread-safe operations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int frameNumber;
    // Add other fields representing downlink frame information here.
} LTE_DL_FRAMEINFO;

typedef struct FramePool {
    LTE_DL_FRAMEINFO *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} FramePool;

FramePool* create_frame_pool(size_t initial_capacity) {
    FramePool *pool = (FramePool *)malloc(sizeof(FramePool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for frame pool\n");
        return NULL;
    }

    pool->frames = (LTE_DL_FRAMEINFO *)calloc(initial_capacity, sizeof(LTE_DL_FRAMEINFO));
    if (!pool->frames) {
        free(pool);
        fprintf(stderr, "Failed to allocate memory for frames\n");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_frame_pool(FramePool *pool) {
    if (pool) {
        free(pool->frames);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_frame(FramePool *pool, LTE_DL_FRAMEINFO frame_info) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        LTE_DL_FRAMEINFO *new_frames = (LTE_DL_FRAMEINFO *)realloc(pool->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
        if (!new_frames) {
            pthread_mutex_unlock(&pool->lock);
            fprintf(stderr, "Failed to reallocate memory for frames\n");
            return -1;
        }
        pool->frames = new_frames;
        pool->capacity = new_capacity;
    }

    pool->frames[pool->count++] = frame_info;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

LTE_DL_FRAMEINFO* get_frame_by_number(FramePool *pool, int frame_number) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->frames[i].frameNumber == frame_number) {
            LTE_DL_FRAMEINFO *result = &pool->frames[i];
            pthread_mutex_unlock(&pool->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void update_frame(FramePool *pool, int frame_number, LTE_DL_FRAMEINFO new_info) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->frames[i].frameNumber == frame_number) {
            pool->frames[i] = new_info;
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    FramePool *pool = create_frame_pool(10);

    if (!pool) return 1;

    LTE_DL_FRAMEINFO frame1 = { .frameNumber = 100 };
    add_frame(pool, frame1);

    LTE_DL_FRAMEINFO *retrievedFrame = get_frame_by_number(pool, 100);
    if (retrievedFrame) {
        printf("Retrieved Frame Number: %d\n", retrievedFrame->frameNumber);
    }

    destroy_frame_pool(pool);

    return 0;
}
```

This code defines a `FramePool` structure that manages an array of `LTE_DL_FRAMEINFO` structures. It includes functions to create and destroy the pool, add frames, retrieve frames by number, and update frames. The use of mutex locks ensures thread-safe operations.']

['Below is a C implementation that manages a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures with unique RNTI values. The code uses mutex locks for thread safety and handles memory allocation failures gracefully.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int rnti;
    // Add other CRC indication tags as needed.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t capacity;
    pthread_mutex_t lock;
} BoundedList;

BoundedList* create_bounded_list(size_t max_size) {
    BoundedList* list = malloc(sizeof(BoundedList));
    if (!list) return NULL;

    list->head = NULL;
    list->capacity = max_size;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

int add_to_bounded_list(BoundedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current && *current)->data.rnti != pdu.rnti) {
        current = &(*current)->next;
    }

    if (*current) { // RNTI already exists
        pthread_mutex_unlock(&list->lock);
        return 0; // No addition, as RNTI is unique
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }
    *current = new_node;
    new_node->data = pdu;
    new_node->next = NULL;

    size_t count = 0;
    for (Node* temp = list->head; temp; temp = temp->next) {
        ++count;
    }

    if (count >= list->capacity) {
        // Remove the oldest node to make space
        Node* prev = NULL;
        Node* oldest = list->head;

        for (Node* temp = list->head; temp && temp->next; temp = temp->next) {
            prev = temp;
            oldest = oldest->next;
        }

        if (prev) {
            prev->next = NULL;
            free(oldest);
        } else { // Only one node exists, remove it
            free(list->head);
            list->head = NULL;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

int is_rnti_in_list(BoundedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    for (Node* current = list->head; current; current = current->next) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_bounded_list(BoundedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    BoundedList* list = create_bounded_list(5); // Capacity of 5 elements

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .rnti = 100 };
    add_to_bounded_list(list, pdu1);

    if (is_rnti_in_list(list, 100)) {
        printf("RNTI 100 is in the list.\n");
    }

    free_bounded_list(list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe access.
- **Memory Management**: Handles memory allocation failures gracefully.
- **Unique RNTI**: Ensures each RNTI is unique in the list.
- **Bounded List Capacity**: Automatically removes the oldest element when capacity is exceeded.
- **Cleanup**: Properly frees all allocated resources.']

