    // Traverse to the node at the specified index
    for (int i = 0; temp != NULL && i < index; ++i) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) { // Index out of bounds
        pthread_mutex_unlock(&lock);
        return;
    }

    if (prev == NULL) { // Remove head
        head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);

    pthread_mutex_unlock(&lock);
}

// Function to update an element by RNTI
