import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

public class NFACRCIndicationsGenerator {

    private static final String API_URL = "https://pokeapi.co/api/v2/type/";
    private static Map<String, List<String>> pokemonTypeCache = new HashMap<>();

    public static List<String> generateNFACRCIndications(int N) {
        List<String> indications = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            try {
                int rnti = new Random().nextInt(10000);
                String rxUeInformationTag = "RX_UE_INFORMATION_TAG";
                boolean crcFlag = new Random().nextBoolean();

                List<String> pokemonTypes = getPokemonTypes();
                for (String type : pokemonTypes) {
                    List<String> weaknesses = getWeaknesses(type);

                    indications.add(String.format("%s[RNTI=%d] CRI[CRCFLAG=%b] Weaknesses=[%s]",
                            rxUeInformationTag, rnti, crcFlag,
                            String.join(",", weaknesses)));
                }
            } catch (Exception e) {
                System.err.println("Failed to generate indication: " + e.getMessage());
            }
        }

        return indications;
    }

    private static List<String> getPokemonTypes() throws Exception {
        if (!pokemonTypeCache.isEmpty()) {
            return new ArrayList<>(pokemonTypeCache.values().stream()
                    .flatMap(List::stream)
                    .distinct()
                    .collect(Collectors.toList()));
        }

        URL url = new URL(API_URL);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == 200) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();

            // Parse the JSON response to extract Pokemon types
            List<String> types = parsePokemonTypes(content.toString());
            pokemonTypeCache.putAll(extractNamesAndIdentities(types));

            return types;
        } else {
            throw new RuntimeException("Failed to retrieve data from API");
        }
    }

    private static List<String> getWeaknesses(String type) throws Exception {
        URL url = new URL(API_URL + type);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == 200) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();

            return parseWeaknesses(content.toString());
        } else {
            throw new RuntimeException("Failed to retrieve weaknesses for type: " + type);
        }
    }

    private static Map<String, List<String>> extractNamesAndIdentities(List<String> types) {
        // Simulate extracting names and identities from parsed JSON
        Map<String, List<String>> extracted = new HashMap<>();
        for (String type : types) {
            extracted.computeIfAbsent(type, k -> new ArrayList<>()).add(type);
        }
        return extracted;
    }

    private static List<String> parsePokemonTypes(String jsonResponse) {
        // Simulate parsing the JSON response to extract Pokemon types
        return List.of("fire", "water", "grass"); // Example list of types
    }

    private static List<String> parseWeaknesses(String jsonResponse) {
        // Simulate parsing the JSON response for weaknesses
        Map<String, List<String>> weaknessMap = new HashMap<>();
        weaknessMap.put("fire", List.of("water"));
        weaknessMap.put("water", List.of("electric"));
        weaknessMap.put("grass", List.of("fire"));

        String type = jsonResponse.contains("\"name\": \"fire\"") ? "fire" : 
                      jsonResponse.contains("\"name\": \"water\"") ? "water" :
                      "grass";

        return weaknessMap.getOrDefault(type, new ArrayList<>());
    }
}
