#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Use an appropriate type for RNTI
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int generate_random_crcflag() {
    return rand() % 2; // Example: Randomly generates 0 or 1
}

void add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == new_pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return; // RNTI must be unique, so do not add duplicates
        }
        current = &((*current)->next);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_pdu.CRCFLAG = generate_random_crcflag();
    new_node->data = new_pdu;
    new_node->next = NULL;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
}

void update_element(CRCList* list, unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T updated_pdu) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data = updated_pdu; // Update the existing node
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(CRCList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Node **current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == rnti) {
            Node *to_remove = *current;
            *current = (*current)->next; // Remove node
            free(to_remove);
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    CRCList* list = create_list();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 100 };
    add_element(list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 67890, .CRC_INDICATION_REL8_TAG = 200 };
    add_element(list, pdu2);

    // Update
    pdu2.RX_UE_INFORMATION_TAG = 3;
    update_element(list, pdu2.RNTI, pdu2);

    // Remove
    remove_element(list, pdu1.RNTI);

    destroy_list(list);
    return 0;
}
