    if (!parent) {
        logHandler.log("Failed to allocate memory for Union-Find parent array");
        free(nfaapiList);
        return 1;
    }

    for (int i = 0; i < N; ++i) {
        parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void union_sets(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA != rootB)
            parent[rootB] = rootA;
    }

    // Count disjoint pairs
    clock_t start = clock();
    int disjointPairsCount = 0;

    for (int i = 0; i < N - 1; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (find(i) != find(j)) {
                union_sets(i, j);
                disjointPairsCount++;
            }
        }
    }

    clock_t end = clock();
    double timeTaken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;
    logHandler.log("Disjoint pairs counted in milliseconds: ");
    printf("%f\n", timeTaken);

    free(parent);
    free(nfaapiList);

    return 0; // Success
