#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[MAX_STRUCTURES];
    pthread_mutex_t lock;
    int active_count;
} PoolManager;

PoolManager* create_pool_manager() {
    PoolManager* manager = (PoolManager*)malloc(sizeof(PoolManager));
    if (!manager) return NULL;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        manager->pool[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
    manager->active_count = 0;

    return manager;
}

void destroy_pool_manager(PoolManager* manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        free(manager->pool[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(PoolManager* manager, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (manager->pool[i] == NULL || manager->active_count < MAX_STRUCTURES) {
            NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!structure) {
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }

            structure->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            manager->pool[i] = structure;
            manager->active_count++;
            pthread_mutex_unlock(&manager->lock);

            // Simulate external data source update with a placeholder
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = 100000; // 100ms delay to simulate latency

            if (nanosleep(&delay, NULL) < 0) {
                pthread_mutex_lock(&manager->lock);
                manager->active_count--;
                free(structure);
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }

            pthread_mutex_lock(&manager->lock);

            // Update structure with RX_UE_INFORMATION_TAG and RNTI
            // Placeholder for actual update logic

            pthread_mutex_unlock(&manager->lock);
            return manager->pool[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void release_structure(PoolManager* manager, NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!manager || !structure) return;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (manager->pool[i] == structure) {
            free(manager->pool[i]);
            manager->pool[i] = NULL;
            manager->active_count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    srand(time(NULL));
    PoolManager* manager = create_pool_manager();

    if (!manager) {
        fprintf(stderr, "Failed to initialize pool manager\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = get_structure(manager, 1, 12345);
    if (pdu) {
        printf("Structure acquired: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               1, 12345, pdu->crc_tag.CRCFLAG);
        release_structure(manager, pdu);
    } else {
        fprintf(stderr, "Failed to acquire structure\n");
    }

    destroy_pool_manager(manager);
    return EXIT_SUCCESS;
}
