#include "jansson.h" // A lightweight JSON library

typedef struct {
    int id;
    char *session_id;
    time_t initiation_time;
} Session;

typedef struct {
    int ue_id;
    Session **sessions;
    size_t session_count;
} UeContext;

// Function prototypes
UeContext* create_ue_context(int ue_id);
void add_session(UeContext *ue, const char *session_id);
void remove_expired_sessions(UeContext *ue, time_t timeout);
void update_session(UeContext *ue, int session_index, const char *new_session_id);
void free_ue_context(UeContext *ue);
int load_ue_contexts_from_json(const char *file_path, UeContext ***contexts, size_t *count);
int save_ue_contexts_to_json(const char *file_path, UeContext **contexts, size_t count);

// Implementations
UeContext* create_ue_context(int ue_id) {
    UeContext *ue = (UeContext *)malloc(sizeof(UeContext));
    if (!ue) return NULL;
    ue->ue_id = ue_id;
    ue->sessions = NULL;
    ue->session_count = 0;
    return ue;
}

void add_session(UeContext *ue, const char *session_id) {
    Session **new_sessions = (Session **)realloc(ue->sessions, (ue->session_count + 1) * sizeof(Session *));
    if (!new_sessions) return;

    ue->sessions = new_sessions;
    ue->sessions[ue->session_count] = (Session *)malloc(sizeof(Session));
    if (!ue->sessions[ue->session_count]) {
        // Handle allocation failure
        free(new_sessions);
        return;
    }

    ue->sessions[ue->session_count]->id = ue->session_count; // Simplified session ID
    ue->sessions[ue->session_count]->session_id = strdup(session_id);
    ue->sessions[ue->session_count]->initiation_time = time(NULL);

    ue->session_count++;
}

void remove_expired_sessions(UeContext *ue, time_t timeout) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < ue->session_count; ) {
        if (difftime(current_time, ue->sessions[i]->initiation_time) > timeout) {
            free(ue->sessions[i]->session_id);
            free(ue->sessions[i]);
            memmove(&ue->sessions[i], &ue->sessions[i + 1], (ue->session_count - i - 1) * sizeof(Session *));
            ue->session_count--;
        } else {
            i++;
        }
    }
}

void update_session(UeContext *ue, int session_index, const char *new_session_id) {
    if (session_index < 0 || session_index >= ue->session_count) return;
    free(ue->sessions[session_index]->session_id);
    ue->sessions[session_index]->session_id = strdup(new_session_id);
}

void free_ue_context(UeContext *ue) {
    for (size_t i = 0; i < ue->session_count; i++) {
        free(ue->sessions[i]->session_id);
        free(ue->sessions[i]);
    }
    free(ue->sessions);
    free(ue);
}

int load_ue_contexts_from_json(const char *file_path, UeContext ***contexts, size_t *count) {
    json_error_t error;
    json_t *root = json_load_file(file_path, 0, &error);
    if (!root) return -1;

    const char *key;
    json_t *value;
    json_object_foreach(root, key, value) {
        int ue_id = atoi(key);
        UeContext *ue = create_ue_context(ue_id);

        json_array_foreach(value, _, session_value) {
            json_t *session_obj = json_array_get(session_value, 0);
            char *session_id = strdup(json_string_value(session_obj));
            add_session(ue, session_id);
        }

        // Add to contexts array
        *contexts = realloc(*contexts, (*count + 1) * sizeof(UeContext *));
        (*contexts)[*count] = ue;
        (*count)++;
    }
    json_decref(root);
    return 0;
}

int save_ue_contexts_to_json(const char *file_path, UeContext **contexts, size_t count) {
    json_t *root = json_object();
    for (size_t i = 0; i < count; i++) {
        json_t *ue_obj = json_object();
        json_object_set_new(ue_obj, "sessions", json_array());

        for (size_t j = 0; j < contexts[i]->session_count; j++) {
            json_t *session_obj = json_pack("{s:s}", "session_id", contexts[i]->sessions[j]->session_id);
            json_array_append_new(json_object_get(ue_obj, "sessions"), session_obj);
        }

        char key[32];
        snprintf(key, sizeof(key), "%d", contexts[i]->ue_id);
        json_object_set_new(root, key, ue_obj);
    }

    int ret = json_dump_file(root, file_path, JSON_INDENT(4));
    json_decref(root);
    return ret == 0 ? 0 : -1;
}

// Example usage
int main() {
    UeContext **contexts = NULL;
    size_t count = 0;

    load_ue_contexts_from_json("config.json", &contexts, &count);

    // Simulate operations
    add_session(contexts[0], "session_123");
    remove_expired_sessions(contexts[0], 3600);
    update_session(contexts[0], 0, "updated_session_123");

    save_ue_contexts_to_json("config.json", contexts, count);

    for (size_t i = 0; i < count; i++) {
        free_ue_context(contexts[i]);
    }
    free(contexts);

    return 0;
}
```

### Key Points:
- **JSON Handling**: Uses the `jansson` library to manage JSON parsing and serialization.
- **Dynamic Memory Management**: Ensures efficient allocation and deallocation of memory for sessions and UE contexts.
- **Concurrency Considerations**: The code is structured for single-threaded execution; thread safety would require additional mechanisms (e.g., mutexes).
- **Performance Trade-offs**: Balances between frequent disk I/O and in-memory operations, optimizing by minimizing file writes.']

