public class UserActivityProcessor {

    private static final Logger LOGGER = Logger.getLogger(UserActivityProcessor.class.getName());
    private static final long CACHE_EXPIRATION_TIME_MS = TimeUnit.DAYS.toMillis(1);
    private static Map<String, CacheEntry> weatherCache = new ConcurrentHashMap<>();

    public static Map<String, SummaryReport> processUserActivityLog(List<UserEvent> events) {
        Map<String, List<UserEvent>> userEventsMap = new HashMap<>();

        for (UserEvent event : events) {
            userEventsMap.computeIfAbsent(event.userId, k -> new ArrayList<>()).add(event);
        }

        Map<String, SummaryReport> summaryReports = new ConcurrentHashMap<>();

        userEventsMap.forEach((userId, eventsForUser) -> {
            long totalDuration = 0;
            String mostFrequentLocation = null;
            int locationFrequency = 0;
            Map<String, Integer> locationCount = new HashMap<>();

            for (int i = 1; i < eventsForUser.size(); i++) {
                UserEvent currentEvent = eventsForUser.get(i);
                UserEvent previousEvent = eventsForUser.get(i - 1);

                long duration = java.time.Duration.between(previousEvent.timestamp, currentEvent.timestamp).toMillis();
                totalDuration += duration;

                locationCount.merge(currentEvent.location, 1, Integer::sum);
                if (locationCount.get(currentEvent.location) > locationFrequency) {
                    locationFrequency = locationCount.get(currentEvent.location);
                    mostFrequentLocation = currentEvent.location;
                }
            }

            SummaryReport report = new SummaryReport();
            report.totalActivities = eventsForUser.size();
            report.averageActivityDuration = totalDuration / (double) (eventsForUser.size() - 1);
            report.mostFrequentLocation = mostFrequentLocation;

            // Enrich the summary with activity-specific insights
            enrichSummaryWithInsights(eventsForUser, report);

            summaryReports.put(userId, report);
        });

        return summaryReports;
    }

    private static void enrichSummaryWithInsights(List<UserEvent> events, SummaryReport report) {
        Map<String, Integer> activityTypeCount = new HashMap<>();

        for (UserEvent event : events) {
            activityTypeCount.merge(event.activityType, 1, Integer::sum);
        }

        // Example: Enriching with social activity insights
        if (activityTypeCount.containsKey("social")) {
            report.additionalInsights.put("friendsEncountered", calculateFriendsEncountered(events));
        }

        // Example: Enriching with work-related activities insights
        if (activityTypeCount.containsKey("work")) {
            long totalWorkDuration = 0;
            for (UserEvent event : events) {
                if ("work".equals(event.activityType)) {
                    totalWorkDuration += java.time.Duration.between(event.timestamp, Instant.now()).toMillis();
                }
            }
            report.additionalInsights.put("productivityEstimate", estimateProductivity(totalWorkDuration));
        }

        // Fetch weather conditions for each location
        Set<String> uniqueLocations = new HashSet<>();
        events.forEach(event -> uniqueLocations.add(event.location));

        for (String location : uniqueLocations) {
            String weatherInfo = fetchWeatherWithRetry(location);
            if (weatherInfo != null) {
                report.additionalInsights.put("weather_" + location, weatherInfo);
            }
        }
    }

    private static int calculateFriendsEncountered(List<UserEvent> events) {
        // Placeholder logic for calculating friends encountered
        return new Random().nextInt(10);  // Example: random number of friends
    }

    private static double estimateProductivity(long totalDurationMillis) {
        // Placeholder logic for estimating productivity
        return totalDurationMillis / (1000.0 * 60);  // Example: minutes worked
    }

    private static String fetchWeatherWithRetry(String location) {
        int retries = 3;
        long waitTimeMs = 500;

        while (retries > 0) {
            try {
                return fetchWeather(location);
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Failed to fetch weather for location: " + location + ". Retrying...", e);
                retries--;
                if (retries == 0) {
                    break;
                }
                try {
                    Thread.sleep(waitTimeMs);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                waitTimeMs *= 2; // Exponential backoff
            }
        }

        return null;
    }

    private static String fetchWeather(String location) throws Exception {
        CacheEntry cacheEntry = weatherCache.get(location);

        if (cacheEntry != null && Instant.now().toEpochMilli() - cacheEntry.timestamp < CACHE_EXPIRATION_TIME_MS) {
            return cacheEntry.weatherData;
        }

        // Simulate API call
        String weatherData = "Sunny";  // Placeholder for actual API response

        weatherCache.put(location, new CacheEntry(weatherData, Instant.now().toEpochMilli()));

        return weatherData;
    }

    private static class CacheEntry {
        String weatherData;
        long timestamp;

        CacheEntry(String weatherData, long timestamp) {
            this.weatherData = weatherData;
            this.timestamp = timestamp;
        }
    }
}
