#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the status types for a network interface.
typedef enum {
    STATUS_DOWN,
    STATUS_UP,
    STATUS_UNKNOWN
} InterfaceStatus;

// Structure to hold IP configuration details.
typedef struct {
    char *ipAddress;
    // Additional fields can be added here, such as subnet mask, gateway, etc.
} IPConfiguration;

// Structure for holding network interface configurations.
typedef struct {
    int interfaceIndex;
    IPConfiguration *ipConfigs;  // Dynamic array of IP configurations.
    size_t ipConfigCount;
    InterfaceStatus status;
} NetworkInterfaceConfig;

// Structure to hold the dynamic array and its metadata, including a mutex for thread safety.
typedef struct {
    NetworkInterfaceConfig **configs;
    size_t configCount;
    pthread_mutex_t lock;  // Mutex for protecting access to configs.
} InterfaceConfigManager;

// Function declarations
void initializeManagerInterface(InterfaceConfigManager *manager);
int addOrUpdateConfiguration(InterfaceConfigManager *manager, int interfaceIndex, IPConfiguration *ipConfigs, size_t count, InterfaceStatus status);
InterfaceStatus getConfigurationStatus(InterfaceConfigManager *manager, int interfaceIndex);
void freeConfigurationManager(InterfaceConfigManager *manager);

// Function to initialize the manager.
void initializeManagerInterface(InterfaceConfigManager *manager) {
    manager->configs = NULL;
    manager->configCount = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add or update a configuration for a given interface index.
int addOrUpdateConfiguration(InterfaceConfigManager *manager, int interfaceIndex, IPConfiguration *ipConfigs, size_t count, InterfaceStatus status) {
    // Lock the manager to ensure thread-safe access.
    pthread_mutex_lock(&manager->lock);

    NetworkInterfaceConfig **newArray = realloc(manager->configs, (manager->configCount + 1) * sizeof(NetworkInterfaceConfig *));
    if (!newArray) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }

    manager->configs = newArray;
    manager->configs[manager->configCount] = malloc(sizeof(NetworkInterfaceConfig));
    if (!manager->configs[manager->configCount]) {
        free(newArray);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }

    NetworkInterfaceConfig *newConfig = manager->configs[manager->configCount];
    newConfig->interfaceIndex = interfaceIndex;
    newConfig->ipConfigs = malloc(count * sizeof(IPConfiguration));
    if (!newConfig->ipConfigs) {
        free(newConfig);
        free(newArray);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }

    for (size_t i = 0; i < count; ++i) {
        newConfig->ipConfigs[i] = ipConfigs[i];
    }

    newConfig->ipConfigCount = count;
    newConfig->status = status;

    manager->configCount++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Retrieve the configuration status for a given interface index.
InterfaceStatus getConfigurationStatus(InterfaceConfigManager *manager, int interfaceIndex) {
    pthread_mutex_lock(&manager->lock);

    InterfaceStatus status = STATUS_UNKNOWN;
    for (size_t i = 0; i < manager->configCount; ++i) {
        if (manager->configs[i]->interfaceIndex == interfaceIndex) {
            status = manager->configs[i]->status;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return status;
}

// Free all allocated memory in the configuration manager.
void freeConfigurationManager(InterfaceConfigManager *manager) {
    for (size_t i = 0; i < manager->configCount; ++i) {
        free(manager->configs[i]->ipConfigs);
        free(manager->configs[i]);
    }
    free(manager->configs);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    InterfaceConfigManager manager;
    initializeManagerInterface(&manager);

    IPConfiguration ip1 = { .ipAddress = "192.168.0.1" };
    addOrUpdateConfiguration(&manager, 1, &ip1, 1, STATUS_UP);

    InterfaceStatus status = getConfigurationStatus(&manager, 1);
    printf("Interface 1 status: %d\n", status); // Should print 2 for STATUS_UP

    freeConfigurationManager(&manager);
    return 0;
}
```

### Key Considerations
- **Memory Management**: Dynamically allocates memory for the configurations and their associated IP details. Carefully deallocates in `freeConfigurationManager`.
- **Concurrency**: Uses a mutex (`pthread_mutex_t`) to ensure thread safety when modifying or accessing the configuration array.
- **Error Handling**: Checks allocation results, returning an error code on failure.
- **Scalability & Extendibility**: The structure allows for easy addition of new fields and types. Each IP config is stored in a dynamically allocated array within each `NetworkInterfaceConfig`.']

