int countDisjointPairs(int *dataArray, size_t arraySize) {
    int *parent = malloc(arraySize * sizeof(int));
    if (!parent) return logError("Memory allocation failed for Union-Find");

    for (size_t i = 0; i < arraySize; ++i) parent[i] = -1;

    // Union-Find logic to count disjoint pairs
    int disjointCount = 0;
    for (size_t i = 0; i < arraySize; ++i) {
