            for (size_t j = i + 1; j < arraySize; ++j) {
                if (dataArray[i] == dataArray[j] && parent[j] == -1) {
                    parent[j] = i;
                    disjointCount++;
                }
            }
        }
    }

    free(parent);
    return disjointCount;
}

