    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void add_structure(uint16_t tag, uint32_t rnti) {
    pthread_mutex_lock(&list.lock);

    if (list.count >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum structure limit reached\n");
        pthread_mutex_unlock(&list.lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list.lock);
        return;
    }

    new_node->data.valid_rx_ue_information_tag = tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_flag = generate_crc_flag();
    new_node->next = list.head;
    list.head = new_node;
    list.count++;

    fprintf(stderr, "Added structure. Total: %d\n", list.count);

    pthread_mutex_unlock(&list.lock);
}

void remove_structure() {
    pthread_mutex_lock(&list.lock);

    if (list.head == NULL) {
        fprintf(stderr, "No structures to remove\n");
        pthread_mutex_unlock(&list.lock);
        return;
    }

    Node* temp = list.head;
    list.head = list.head->next;
    free(temp);
    list.count--;

    fprintf(stderr, "Removed structure. Total: %d\n", list.count);

    pthread_mutex_unlock(&list.lock);
}

void process_structures() {
    // Simulate processing logic
    while (1) {
        remove_structure();

        // Implement delay or wait for new data if needed

        usleep(100000);  // Sleep to simulate time taken per operation (adjust as necessary)
    }
}

// Thread function to simulate concurrent access
void* thread_function(void* arg) {
    uint16_t tag = rand() % 0xFFFF; // Example RX_UE_INFORMATION_TAG
    uint32_t rnti = rand();          // Example RNTI

    while (1) {
