size_t active_count = 0;
pthread_mutex_t lock;
pthread_cond_t cond_var;

void initialize_pool() {
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond_var, NULL);
    for (int i = 0; i < MAX_ACTIVE_STRUCTURES; ++i) {
        pdu_pool[i] = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&lock);

    while (active_count == MAX_ACTIVE_STRUCTURES) {
        // Wait for space to become available
        pthread_cond_wait(&cond_var, &lock);
    }

    size_t index = active_count++;
    pdu_pool[index] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_pool[index]) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Randomly set CRCFLAG for demonstration
    srand(time(NULL) ^ pthread_self());
    pdu_pool[index]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&lock);
    return pdu_pool[index];
}

void release_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < MAX_ACTIVE_STRUCTURES; ++i) {
        if (pdu_pool[i] == pdu) {
            free(pdu_pool[i]);
            pdu_pool[i] = NULL;
            active_count--;

            // Notify other threads that a slot has been freed
            pthread_cond_signal(&cond_var);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void adjust_max_structures(size_t new_limit) {
    if (new_limit > MAX_ACTIVE_STRUCTURES) {
        fprintf(stderr, "New limit exceeds predefined maximum\n");
        return;
    }

    pthread_mutex_lock(&lock);

    while (active_count > new_limit) {
        // Free excess structures
        for (size_t i = 0; i < active_count; ++i) {
            if (pdu_pool[i]) {
                free(pdu_pool[i]);
                pdu_pool[i] = NULL;
                active_count--;
                break;
            }
        }
    }

    pthread_mutex_unlock(&lock);
}

void monitor_and_log() {
    // Dummy implementation for demonstration purposes
