// Assume these are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

// Logging function
void log_message(const char* message) {
    printf("%s\n", message);
}

// Function to initialize the list
CRCList* crc_list_init() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to resize the list
int crc_list_resize(CRCList* list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_data) return -1;

    list->data = new_data;
    list->capacity = new_capacity;
    return 0;
}

// Function to add a CRC indication
int crc_list_add(CRCList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        if (crc_list_resize(list) != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[list->size];

    // Ensure unique CRCFLAG
    int crcflag_set = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG == crcflag_set) {
            crcflag_set++;
        }
    }

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag_set;

    log_message("Added PDU: TAG = ", RX_UE_INFORMATION_TAG, " RNTI = ", RNTI);

    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to destroy the list
void crc_list_destroy(CRCList* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Example usage
int main() {
    CRCList* list = crc_list_init();

    if (!list) {
        fprintf(stderr, "Failed to initialize CRC List\n");
        return 1;
    }

    for (int i = 0; i < 20; ++i) { // Simulate adding items
        crc_list_add(list, rand() % 100, rand() % 100);
    }

    crc_list_destroy(list);
    return 0;
}
```

### Key Points:

