#include <string.h>

#define IP_ADDRESS_LEN 16

typedef struct {
    char source_ip[IP_ADDRESS_LEN];
    char destination_ip[IP_ADDRESS_LEN];
    int protocol_type;
    size_t payload_length;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    struct Node* next;
} Node;

Node* head = NULL;

void add_header(const char* src_ip, const char* dest_ip, int protocol, size_t payload_len) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        return;
    }

    strncpy(new_node->header.source_ip, src_ip, IP_ADDRESS_LEN - 1);
    new_node->header.source_ip[IP_ADDRESS_LEN - 1] = '\0';
    strncpy(new_node->header.destination_ip, dest_ip, IP_ADDRESS_LEN - 1);
    new_node->header.destination_ip[IP_ADDRESS_LEN - 1] = '\0';
    new_node->header.protocol_type = protocol;
    new_node->header.payload_length = payload_len;

    new_node->next = head;
    head = new_node;
}

void remove_header_by_ip(const char* ip_address) {
    Node *temp = head, *prev = NULL;

    while (temp != NULL && strcmp(temp->header.source_ip, ip_address) != 0 &&
           strcmp(temp->header.destination_ip, ip_address) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    if (prev == NULL) { // head needs to be removed
        head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);
}

void search_headers_by_protocol(int protocol_type, void (*callback)(PacketHeader*)) {
    Node* current = head;
    while (current != NULL) {
        if (current->header.protocol_type == protocol_type) {
            callback(&current->header);
        }
        current = current->next;
    }
}

void print_packet_header(PacketHeader* header) {
    printf("Source IP: %s, Destination IP: %s, Protocol: %d, Payload Length: %zu\n",
           header->source_ip, header->destination_ip, header->protocol_type,
           header->payload_length);
}

int main() {
    // Example usage
    add_header("192.168.1.1", "192.168.1.2", 6, 512);
    add_header("10.0.0.1", "10.0.0.2", 17, 256);

    printf("Headers with protocol type 6:\n");
    search_headers_by_protocol(6, print_packet_header);

    remove_header_by_ip("192.168.1.1");

    return 0;
}
