#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    uint64_t unique_id;
} ManagedNFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    ManagedNFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    uint64_t id_counter;
} ListManager;

ListManager list_manager = {NULL, PTHREAD_RWLOCK_INITIALIZER, 0};

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

ManagedNFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    ManagedNFAPI_CRC_INDICATION_PDU_T* structure = (ManagedNFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(ManagedNFAPI_CRC_INDICATION_PDU_T));
    if (!structure) {
        log_error("Memory allocation failed");
        return NULL;
    }

    // Initialize fields
    structure->pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example random generation
    structure->pdu.RNTI = rand() % 65536;
    structure->pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
    structure->pdu.CRCFLAG = rand() % 2 == 0;
    structure->timestamp = time(NULL);
    pthread_rwlock_wrlock(&list_manager.lock);
    structure->unique_id = list_manager.id_counter++;
    pthread_rwlock_unlock(&list_manager.lock);

    return structure;
}

void add_structure_to_list(ManagedNFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate node for list");
        free(structure);
        return;
    }

    new_node->data = *structure;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list_manager.lock);
    new_node->next = list_manager.head;
    list_manager.head = new_node;
    pthread_rwlock_unlock(&list_manager.lock);
}

void cleanup_unused_entries() {
    time_t current_time = time(NULL);

    pthread_rwlock_wrlock(&list_manager.lock);
    Node *current = list_manager.head, *prev = NULL;

    while (current) {
        if (difftime(current_time, current->data.timestamp) > 60) { // Example cleanup threshold
            Node* to_delete = current;
            if (prev)
                prev->next = current->next;
            else
                list_manager.head = current->next;

            free(to_delete);
            current = current->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&list_manager.lock);
}

void query_list(uint16_t rnti, bool crcflag, size_t* count, ManagedNFAPI_CRC_INDICATION_PDU_T** results) {
    pthread_rwlock_rdlock(&list_manager.lock);
    Node* current = list_manager.head;
    *count = 0;

    while (current && (*count < MAX_STRUCTURES)) {
        if ((rnti == UINT16_MAX || current->data.pdu.RNTI == rnti) &&
            (crcflag == false || current->data.pdu.CRCFLAG == crcflag)) {
            results[(*count)++] = &(current->data);
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list_manager.lock);
}

void export_list_to_json(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_error("Failed to open file for writing JSON data");
        return;
    }

    fprintf(file, "[\n");

    pthread_rwlock_rdlock(&list_manager.lock);
    Node* current = list_manager.head;
    int first_entry = 1;

    while (current) {
        if (!first_entry)
            fprintf(file, ",\n");

        fprintf(file, " { \"RX_UE_INFORMATION_TAG\": %u, \"RNTI\": %hu, \"CRC_INDICATION_REL8_TAG\": %hhu, "
                        "\"CRCFLAG\": %s, \"timestamp\": %ld, \"unique_id\": %llu }",
                current->data.pdu.RX_UE_INFORMATION_TAG,
                current->data.pdu.RNTI,
                current->data.pdu.CRC_INDICATION_REL8_TAG,
                current->data.pdu.CRCFLAG ? "true" : "false",
                current->data.timestamp,
                (unsigned long long)current->data.unique_id);

        first_entry = 0;
        current = current->next;
    }

    fprintf(file, "\n]");
    fclose(file);
    pthread_rwlock_unlock(&list_manager.lock);
}

void init_list_manager() {
    list_manager.head = NULL;
    list_manager.id_counter = 1; // Start IDs from 1
}

int main() {
    srand(time(NULL));  // Seed the random number generator
    init_list_manager();

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        ManagedNFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure();
        if (structure)
            add_structure_to_list(structure);
    }

    cleanup_unused_entries();

    size_t count;
    ManagedNFAPI_CRC_INDICATION_PDU_T* results[MAX_STRUCTURES];
    query_list(UINT16_MAX, false, &count, results);

    export_list_to_json("exported_data.json");

    return 0;
}
```

