['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define LOAD_FACTOR 0.75

typedef struct {
    char IMSI[16]; // Assuming IMSI is a string of length 15 + null terminator
    int RRC_STATE;
    double PHY_LAYER_STATS;
} LTE_UERadioLinkInfo;

typedef struct Node {
    LTE_UERadioLinkInfo data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(const char* IMSI) {
    unsigned long hash = 5381;
    int c;
    while ((c = *IMSI++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash;
}

HashTable* initialize_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;

    table->buckets = (Node**)calloc(table->capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for buckets");
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insert_into_hash_table(HashTable* table, LTE_UERadioLinkInfo* ue_info) {
    if (!table || !ue_info) return;

    unsigned long index = hash_function(ue_info->IMSI) % table->capacity;

    pthread_mutex_lock(&table->lock);

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&table->lock);
        return;
    }

    memcpy(&node->data, ue_info, sizeof(LTE_UERadioLinkInfo));
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->size++;

    if ((double)table->size / table->capacity > LOAD_FACTOR) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = 2 * table->capacity;
    Node** new_buckets = (Node**)calloc(new_capacity, sizeof(Node*));
    if (!new_buckets) {
        perror("Failed to allocate memory for resized buckets");
        return;
    }

    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next_node = node->next;

            unsigned long new_index = hash_function(node->data.IMSI) % new_capacity;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
```']

