#include <curl/curl.h> // For REST API calls

// Define the structure types
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void *memory;
    size_t size;
} MemoryStruct;

// Theme management structures
typedef struct {
    pthread_mutex_t cache_lock;
    FILE *cache_file;
    char theme_data[1024]; // Example fixed-size buffer, should be dynamically managed in practice
} ThemeCache;

// Configuration parameter structure
typedef union {
    int intValue;
    float floatValue;
    char* stringValue;
    int* arrayValue; // Dynamic allocation needed based on size
} ConfigParamValue;

typedef struct {
    char key[256];
    ConfigParamValue value;
    char type[10]; // e.g., "int", "float", "string", "array"
} ConfigParameter;

// Function prototypes
void fetch_and_apply_user_preferences(ThemeCache *theme_cache, int num_pdu);
void load_configuration(const char *file_path, ConfigParameter **config_list);

// Helper function to perform REST API call asynchronously and cache result
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (!ptr) return 0; // Out of memory

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

void fetch_and_apply_user_preferences(ThemeCache *theme_cache, int num_pdu) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.memory = malloc(1);  // Will be grown as needed by the realloc above
    chunk.size = 0;    // No data at this point

    pthread_mutex_lock(&theme_cache->cache_lock);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/theme"); // Replace with actual endpoint
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);

        if(res == CURLE_OK) {
            // Parse JSON response and apply to theme_cache
            strcpy(theme_cache->theme_data, chunk.memory);  // Simplified for example
        }

        curl_easy_cleanup(curl);
    }
    free(chunk.memory);

    pthread_mutex_unlock(&theme_cache->cache_lock);

    curl_global_cleanup();

    NFAPI_CRC_INDICATION_PDU_T pdu_array[num_pdu];
    for (int i = 0; i < num_pdu; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu_array[i].RNTI = rand() % 10000;
        pdu_array[i].CRCFLAG = rand() & 1;
    }

    // Further processing can be done with the populated `pdu_array`
}

void load_configuration(const char *file_path, ConfigParameter **config_list) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return;
    }

    int capacity = 10; // Initial capacity
    *config_list = malloc(capacity * sizeof(ConfigParameter));
    int count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        if (*config_list && count >= capacity) {
            capacity *= 2;
            *config_list = realloc(*config_list, capacity * sizeof(ConfigParameter));
            if (!*config_list) break; // Out of memory
        }

        // Simplified parsing logic
        sscanf(line, "%255[^=]=%s", (*config_list)[count].key, line);
        if (strstr((*config_list)[count].key, "int")) {
            strcpy((*config_list)[count].type, "int");
            (*config_list)[count].value.intValue = atoi(strstr(line, "=") + 1);
        } else if (strstr((*config_list)[count].key, "float")) {
            strcpy((*config_list)[count].type, "float");
            (*config_list)[count].value.floatValue = atof(strstr(line, "=") + 1);
        } else if (strstr((*config_list)[count].key, "string")) {
            strcpy((*config_list)[count].type, "string");
            char *val = strdup(strstr(line, "=") + 1);
            val[strcspn(val, "\r\n")] = 0; // Remove newline
            (*config_list)[count].value.stringValue = val;
        }
        count++;
    }

    fclose(file);

    if (count < capacity) {
        *config_list = realloc(*config_list, count * sizeof(ConfigParameter));
    }
}

// DNS resolution function with error handling
int resolve_hostname(const char *hostname, u_char ip[4]) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return -1; // Error code for DNS resolution failure
    }

    addr_list = (struct in_addr **) he->h_addr_list;
    if (addr_list[0] != NULL) {
        memcpy(ip, addr_list[0], sizeof(struct in_addr));
        return 0; // Success
    }
    return -1; // No address found
}
