} MAC_Transmission_Report_T;

typedef struct {
    MAC_Transmission_Report_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

#define SUCCESS 0
#define ALLOCATION_FAILURE -1

DynamicArray* initialize_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *dynamic_array = malloc(sizeof(DynamicArray));
    if (!dynamic_array) return NULL;

    pthread_mutex_init(&dynamic_array->lock, NULL);

    dynamic_array->array = calloc(initial_capacity, sizeof(MAC_Transmission_Report_T));
    if (!dynamic_array->array) {
        free(dynamic_array);
        return NULL;
    }

    dynamic_array->size = 0;
    dynamic_array->capacity = initial_capacity;

    return dynamic_array;
}

int add_report(DynamicArray *dynamic_array, MAC_Transmission_Report_T report) {
    if (!dynamic_array) return ALLOCATION_FAILURE;

    pthread_mutex_lock(&dynamic_array->lock);

    if (dynamic_array->size == dynamic_array->capacity) {
        size_t new_capacity = dynamic_array->capacity * 2;
        MAC_Transmission_Report_T *new_array = realloc(dynamic_array->array, new_capacity * sizeof(MAC_Transmission_Report_T));
        if (!new_array) {
            pthread_mutex_unlock(&dynamic_array->lock);
            return ALLOCATION_FAILURE;
        }
        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;
    }

    dynamic_array->array[dynamic_array->size++] = report;

    pthread_mutex_unlock(&dynamic_array->lock);

    return SUCCESS;
}

void cleanup_dynamic_array(DynamicArray *dynamic_array) {
    if (!dynamic_array) return;

    pthread_mutex_lock(&dynamic_array->lock);
    free(dynamic_array->array);
    pthread_mutex_unlock(&dynamic_array->lock);

    pthread_mutex_destroy(&dynamic_array->lock);
    free(dynamic_array);
}
