from random import randint
from threading import Lock, Thread

#define MAX_THREADS 10000
#define INITIAL_CAPACITY 1024

typedef struct {
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node_t {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node_t *next;
} Node;

Node* head = NULL;
Lock list_lock = Lock();
int current_capacity = 0;

void add_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // handle memory allocation failure
    new_node->data = pdu;
    new_node->next = NULL;

    list_lock.acquire();

    Node **tracer = &head;
    while (*tracer && (*tracer)->data.RNTI < pdu.RNTI) {
        tracer = &(*tracer)->next;
    }

    if (*tracer && (*tracer)->data.RNTI == pdu.RNTI) {
        free(new_node);
    } else {
        new_node->next = *tracer;
        *tracer = new_node;
    }

    list_lock.release();
}

void remove_duplicates() {
    list_lock.acquire();

    Node* current = head;
    while (current && current->next) {
        if (current->data.RNTI == current->next->data.RNTI) {
            Node* to_delete = current->next;
            current->next = current->next->next;
            free(to_delete);
        } else {
            current = current->next;
        }
    }

    list_lock.release();
}

NFAPI_CRC_INDICATION_PDU_T* get_sorted_array(int *size) {
    list_lock.acquire();

    Node *current = head;
    int count = 0;
    while (current) {
        count++;
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        list_lock.release();
        return NULL; // handle memory allocation failure
    }

    int index = 0;
    current = head;
    while (current) {
        array[index++] = current->data;
        current = current->next;
    }

    *size = count;

    list_lock.release();

    return array;
}

void resize_and_repopulate(int new_capacity) {
