// Create a dynamic array with initial capacity
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);

    return array;
}

// Destroy the dynamic array
void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    free(array->data);
    pthread_mutex_destroy(&array->lock);
    pthread_cond_destroy(&array->cond);
    free(array);
}

// Resize the array if needed
int resize_dynamic_array_if_needed(DynamicArray *array) {
    if (array->size < array->capacity) return 0;

    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    array->data = new_data;
    array->capacity = new_capacity;
    return 0;
}

// Insert element in sorted order by RNTI
int insert_sorted_by_rnti(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element, bool (*filter)(unsigned int)) {
    if (filter && !filter(element.ueInfoTag.RNTI)) return -1;

    pthread_mutex_lock(&array->lock);

    if (resize_dynamic_array_if_needed(array) != 0) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    size_t pos = array->size;
    for (; pos > 0 && array->data[pos-1].ueInfoTag.RNTI > element.ueInfoTag.RNTI; --pos) {
        array->data[pos] = array->data[pos-1];
    }

    array->data[pos] = element;
    array->size++;

    pthread_cond_broadcast(&array->cond);
    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Fetch real-time updates and populate the dynamic array
void fetch_real_time_updates(DynamicArray *array, bool (*filter)(unsigned int)) {
    // Simulate fetching data from an external source
    for (size_t i = 0; i < 10000; ++i) { // Assuming a fixed number of elements to simulate updates
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ueInfoTag.RNTI = rand() % 100000; // Random RNTI value
        pdu.ueInfoTag.CRCFLAG = rand() % 2;   // Random CRCFLAG (0 or 1)
        pdu.CRC_INDICATION_REL8_TAG = rand(); // Random tag

        insert_sorted_by_rnti(array, pdu, filter);
    }
}

// Render script tags as HTML
char* render_script_tags_as_html() {
    const char *scripts[] = {"console.log('Script 1');", "console.log('Script 2');"};
    size_t num_scripts = sizeof(scripts) / sizeof(scripts[0]);

    char *html = malloc(256);
    if (!html) return NULL;

    strcpy(html, "<div class='footer-scripts'>\n");
    for (size_t i = 0; i < num_scripts; ++i) {
