} DynamicArray;

// Function to initialize the dynamic array
bool initDynamicArray(DynamicArray *da, size_t initial_capacity) {
    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);

    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        pthread_mutex_destroy(&da->lock);
        return false;
    }
    return true;
}

// Function to free the dynamic array
void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

// Function to resize the dynamic array
bool resizeDynamicArray(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false;

    da->capacity = new_capacity;
    pthread_mutex_unlock(&da->lock);
    da->array = new_array;
    pthread_mutex_lock(&da->lock);
    return true;
}

// Function to add an element to the dynamic array
bool addElement(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (!resizeDynamicArray(da, new_capacity)) {
            pthread_mutex_unlock(&da->lock);
            return false;
        }
    }

    // Initialize the CRCFLAG with a random value
    srand(time(NULL));
    element.CRCFLAG = rand() % 2;

    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->lock);
    return true;
}

// Function to handle memory allocation failures and retry mechanism
bool safeAddElement(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    int retries = 5;
    bool success = false;

    while (retries > 0 && !success) {
        if (!addElement(da, element)) {
            retries--;
            sleep(1 << (5 - retries)); // Exponential backoff
        } else {
            success = true;
        }
    }

    return success;
}

