    stats->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}

// Function to dynamically allocate and initialize LTE PHY layer statistics structures
LTE_PHY_STATS* allocate_and_initialize_stats(int N, int log_fd) {
    if (N <= 0) {
        dprintf(log_fd, "Invalid number of elements: %d\n", N);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    LTE_PHY_STATS *stats_array = malloc(N * sizeof(LTE_PHY_STATS));
    if (!stats_array) {
        dprintf(log_fd, "Memory allocation failed for %d elements.\n", N);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Seed random number generator
    srand(time(NULL));

    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; ++i) {
        simulate_data(&stats_array[i]);
        // Validate the data if necessary, e.g., check signal strength ranges
        if (stats_array[i].signal_strength <= 0 || stats_array[i].error_rate < 0.0f ||
            stats_array[i].error_rate > 0.1f) {
            dprintf(log_fd, "Data anomaly detected in element %d.\n", i);
            free(stats_array);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&lock);

    // Clean up
    pthread_mutex_destroy(&lock);

    return stats_array;
}

