// Function to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* manageArray(size_t max_size, int seed) {
    initialize(seed);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t current_size = 0;

    while (current_size < max_size) {
        // Allocate or reallocate array memory
        if (!array || current_size == (size_t)(array - malloc(array))) {
            NFAPI_CRC_INDICATION_PDU_T* new_array =
                realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (current_size + 1));
            if (!new_array) {
                fprintf(stderr, "Memory allocation failed\n");
                freeArray(&array); // Ensure resources are freed on failure
                return NULL;
            }
            array = new_array;
        }

        // Fetch data updates periodically to maintain up-to-date valid tags
        if (current_size % 1000 == 0) {
