        // Randomly set CRCFLAG
        pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        ++current_size;
    }

    return array;
}

// Function to free allocated resources
void freeArray(NFAPI_CRC_INDICATION_PDU_T** array) {
