import threading

typedef struct {
    int ue_id;
    float sync_measurement;
} SyncIndicator;

typedef struct Node {
    SyncIndicator data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a new node
Node* create_node(int ue_id, float sync_measurement) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL; // Check for malloc failure
    newNode->data.ue_id = ue_id;
    newNode->data.sync_measurement = sync_measurement;
    newNode->next = NULL;
    return newNode;
}

// Thread-safe function to add a new synchronization indicator
void add_sync_indicator(int ue_id, float sync_measurement) {
    pthread_mutex_lock(&mutex);

    Node* newNode = create_node(ue_id, sync_measurement);
    if (!newNode) {
        pthread_mutex_unlock(&mutex);
        return; // Handle malloc failure gracefully
    }

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to filter out weak signals below a threshold
void filter_interferers(float strength_threshold) {
    pthread_mutex_lock(&mutex);

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.sync_measurement < strength_threshold) {
            Node* temp = current;
            if (prev == NULL) {
                head = current->next; // Update head if needed
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&mutex);
}

// Cleanup function to free all allocated memory
void cleanup() {
    pthread_mutex_lock(&mutex);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;

    pthread_mutex_unlock(&mutex);
}

