```c
#include <stdio.h>
#include <stdlib.h>
import json-c/json.h
#include <pthread.h>

typedef struct {
    int MEASUREMENT_ID;
    float SINR;
    float RSRP;
} MEASUREMENT_REPORT_ENTRY;

typedef struct {
    int UEID;
    char *RRC_STATE;
    MEASUREMENT_REPORT_ENTRY **MeasurementReport; // List of measurement reports
    size_t MeasurementCount;
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UEManager;

// Initialize the UEManager
UEManager* init_ue_manager(size_t initial_capacity) {
    UEManager *manager = malloc(sizeof(UEManager));
    manager->contexts = calloc(initial_capacity, sizeof(UEContext *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Resize the array dynamically
void resize_ue_manager(UEManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UEContext **new_contexts = realloc(manager->contexts, new_capacity * sizeof(UEContext *));
    if (new_contexts) {
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize UEManager\n");
    }
}

// Add a new UEContext
void add_ue_context(UEManager *manager, int ueid, const char *rrc_state) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_ue_manager(manager);
    }

    UEContext *new_context = malloc(sizeof(UEContext));
    new_context->UEID = ueid;
    new_context->RRC_STATE = strdup(rrc_state);
    new_context->MeasurementReport = NULL;
    new_context->MeasurementCount = 0;

    manager->contexts[manager->count++] = new_context;

    pthread_mutex_unlock(&manager->lock);
}

// Add a measurement report to a UEContext
void add_measurement_report(UEManager *manager, int ueid, MEASUREMENT_REPORT_ENTRY entry) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->UEID == ueid) {
            size_t new_count = manager->contexts[i]->MeasurementCount + 1;
            MEASUREMENT_REPORT_ENTRY **new_reports = realloc(manager->contexts[i]->MeasurementReport, new_count * sizeof(MEASUREMENT_REPORT_ENTRY *));
            if (new_reports) {
                manager->contexts[i]->MeasurementReport = new_reports;
                manager->contexts[i]->MeasurementReport[manager->contexts[i]->MeasurementCount++] = malloc(sizeof(MEASUREMENT_REPORT_ENTRY));
                manager->contexts[i]->MeasurementReport[manager->contexts[i]->MeasurementCount - 1] = entry;
            } else {
                fprintf(stderr, "Failed to add measurement report\n");
            }
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Serialize UEManager to a binary file
void serialize_ue_manager(const UEManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        UEContext *context = manager->contexts[i];
        fwrite(&context->UEID, sizeof(int), 1, file);
        size_t rrc_state_length = strlen(context->RRC_STATE) + 1;
        fwrite(&rrc_state_length, sizeof(size_t), 1, file);
        fwrite(context->RRC_STATE, sizeof(char), rrc_state_length, file);
        fwrite(&context->MeasurementCount, sizeof(size_t), 1, file);

        for (size_t j = 0; j < context->MeasurementCount; ++j) {
            MEASUREMENT_REPORT_ENTRY *entry = context->MeasurementReport[j];
            fwrite(&entry->MEASUREMENT_ID, sizeof(int), 1, file);
            fwrite(&entry->SINR, sizeof(float), 1, file);
            fwrite(&entry->RSRP, sizeof(float), 1, file);
        }
    }

    fclose(file);
}

// Deserialize UEManager from a binary file
UEManager* deserialize_ue_manager(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    UEManager *manager = init_ue_manager(count);
    manager->count = count;

    for (size_t i = 0; i < count; ++i) {
        UEContext *context = malloc(sizeof(UEContext));
        fread(&context->UEID, sizeof(int), 1, file);

        size_t rrc_state_length;
        fread(&rrc_state_length, sizeof(size_t), 1, file);
        context->RRC_STATE = malloc(rrc_state_length);
        fread(context->RRC_STATE, sizeof(char), rrc_state_length, file);

        fread(&context->MeasurementCount, sizeof(size_t), 1, file);
        context->MeasurementReport = calloc(context->MeasurementCount, sizeof(MEASUREMENT_REPORT_ENTRY *));

        for (size_t j = 0; j < context->MeasurementCount; ++j) {
            MEASUREMENT_REPORT_ENTRY *entry = malloc(sizeof(MEASUREMENT_REPORT_ENTRY));
            fread(&entry->MEASUREMENT_ID, sizeof(int), 1, file);
            fread(&entry->SINR, sizeof(float), 1, file);
            fread(&entry->RSRP, sizeof(float), 1, file);
            context->MeasurementReport[j] = entry;
        }

        manager->contexts[i] = context;
    }

    fclose(file);
    return manager;
}

// Export UEManager to JSON format
void export_ue_manager_to_json(const UEManager *manager, const char *filename) {
    json_object *jobj = json_object_new_array();

    for (size_t i = 0; i < manager->count; ++i) {
        json_object *jcontext = json_object_new_object();

        json_object_object_add(jcontext, "UEID", json_object_new_int(manager->contexts[i]->UEID));
        json_object_object_add(jcontext, "RRC_STATE", json_object_new_string(manager->contexts[i]->RRC_STATE));

        json_object *jreports = json_object_new_array();

        for (size_t j = 0; j < manager->contexts[i]->MeasurementCount; ++j) {
            MEASUREMENT_REPORT_ENTRY *entry = manager->contexts[i]->MeasurementReport[j];

            json_object *jreport = json_object_new_object();
            json_object_object_add(jreport, "MEASUREMENT_ID", json_object_new_int(entry->MEASUREMENT_ID));
            json_object_object_add(jreport, "SINR", json_object_new_double(entry->SINR));
            json_object_object_add(jreport, "RSRP", json_object_new_double(entry->RSRP));

            json_object_array_add(jreports, jreport);
        }

        json_object_object_add(jcontext, "MeasurementReport", jreports);
        json_object_array_add(jobj, jcontext);
    }

    FILE *file = fopen(filename, "w");
    if (file) {
        fprintf(file, "%s\n", json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN));
        fclose(file);
    }
    json_object_put(jobj); // Free the JSON object
}

// Example unit test function
void run_tests() {
    UEManager *manager = init_ue_manager(2);

    add_ue_context(manager, 1, "CONNECTED");
    MEASUREMENT_REPORT_ENTRY entry = {1001, -10.5f, -80.0f};
    add_measurement_report(manager, 1, entry);

    serialize_ue_manager(manager, "ue_data.bin");
    UEManager *loaded_manager = deserialize_ue_manager("ue_data.bin");

    export_ue_manager_to_json(loaded_manager, "ue_data.json");

    // Add assertions or checks here to validate correctness

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->RRC_STATE);
        free(manager->contexts[i]);
    }
    free(manager->contexts);

    pthread_mutex_destroy(&manager->lock);
    free(manager);

    for (size_t i = 0; i < loaded_manager->count; ++i) {
        free(loaded_manager->contexts[i]->RRC_STATE);
        for (size_t j = 0; j < loaded_manager->contexts[i]->MeasurementCount; ++j) {
            free(loaded_manager->contexts[i]->MeasurementReport[j]);
        }
        free(loaded_manager->contexts[i]->MeasurementReport);
        free(loaded_manager->contexts[i]);
    }
    free(loaded_manager->contexts);

    pthread_mutex_destroy(&loaded_manager->lock);
    free(loaded_manager);
}

int main() {
    run_tests();
    return 0;
}
