        free(new_context);
        pthread_mutex_unlock(&ue_context_lock);
        return NULL;
    }

    strcpy(new_context->rrc_connection_setup_complete, rrc_message);

    generate_security_key(new_context->security_key);

    // Store the context in a thread-safe manner
    ue_contexts[current_ue_count++] = new_context;

    pthread_mutex_unlock(&ue_context_lock);

    printf("UE Context initialized for UE ID: %d\n", ue_id);
    return new_context;
}

