    pthread_mutex_lock(&ue_context_lock);

    for (int i = 0; i < current_ue_count; ++i) {
        if (ue_contexts[i]->ue_id == ue_id) {
            free(ue_contexts[i]);
            // Shift contexts to fill the gap
            memmove(&ue_contexts[i], &ue_contexts[i + 1], sizeof(void*) * (current_ue_count - i - 1));
            current_ue_count--;
            printf("UE Context removed for UE ID: %d\n", ue_id);
