unsigned int hash_function(unsigned long tag, unsigned short rnti) {
    return (tag ^ ((rnti << 16) | (rnti >> 16))) & 0xFFFFFFFF;
}

void log_message(const char *message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t count, size_t max_memory_usage) {
    if (count == 0 || max_memory_usage < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_message("Invalid input parameters.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    unsigned long memory_allocated = 0;

    try {
        array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) throw "Memory allocation failed.";

        memory_allocated += count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (memory_allocated > max_memory_usage) {
            log_message("Exceeded maximum allowed memory usage.");
            free(array);
            return NULL;
        }

        for (size_t i = 0; i < count; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX + 1;
            array[i].RNTI = rand() % USHRT_MAX + 1;

            // Ensure uniqueness
            for (size_t j = 0; j < i; ++j) {
                while ((array[i].RX_UE_INFORMATION_TAG == array[j].RX_UE_INFORMATION_TAG) ||
                       (array[i].RNTI == array[j].RNTI)) {
                    array[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX + 1;
