['To achieve this task, we can use a combination of mutexes for thread safety, dynamic memory management for efficient resizing, and reference counting for automatic deallocation. Below is an implementation in C using POSIX threads (`pthread`) for concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Add relevant fields here
    int rnti;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct DynamicList {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    unsigned int ref_count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->ref_count = 1; // Initial reference count

    return list;
}

void destroy_list(DynamicList* list) {
    if (list && --list->ref_count == 0) {
        Node* current = list->head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void retain_list(DynamicList* list) {
    if (list) {
        __sync_fetch_and_add(&(list->ref_count), 1);
    }
}

int add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_pdu(DynamicList* list, int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.rnti == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -3; // PDU not found
}

void lookup_rnti(DynamicList* list, int rnti) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            // Perform desired operation with the found PDU
            printf("RNTI %d found\n", rnti);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    DynamicList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .rnti = 12345 };
    add_pdu(list, pdu);

    lookup_rnti(list, 12345);
    remove_pdu(list, 12345);

    destroy_list(list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the list.
- **Reference Counting**: Manages memory by retaining and releasing references to the list.
- **Dynamic Memory Management**: Allocates nodes dynamically and frees them when no longer needed.
- **Error Handling**: Returns error codes for invalid operations or failures.
- **RNTI Lookup**: Demonstrates how to integrate with an RNTI lookup mechanism.

This implementation provides a robust foundation for managing a dynamic list of PDU structures in a multi-threaded environment.']

