            let end_time = Instant::now();

            // Measure memory usage after
            system.refresh_all();
            let after_memory_usage = system.used_memory();

            println!("Compilation time: {:?}", end_time.duration_since(start_time));
            println!("Memory used before compilation: {} KB", before_memory_usage);
            println!("Memory used after compilation: {} KB", after_memory_usage);

