    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicNfaList;

// Function prototypes
DynamicNfaList* create_dynamic_nfa_list(size_t initial_size);
int populate_list(DynamicNfaList* nfa_list, size_t N);
int resize_list(DynamicNfaList* nfa_list, size_t new_capacity);
void free_dynamic_nfa_list(DynamicNfaList* nfa_list);
int iterate_and_print(const DynamicNfaList* nfa_list);
int serialize_list(const DynamicNfaList* nfa_list, const char *filename);
