DynamicNfaList* create_dynamic_nfa_list(size_t initial_size) {
    if (initial_size == 0) return NULL;
    DynamicNfaList* list = (DynamicNfaList*)malloc(sizeof(DynamicNfaList));
    if (!list) return NULL;

    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    list->capacity = initial_size;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int populate_list(DynamicNfaList* nfa_list, size_t N) {
    if (!nfa_list || nfa_list->count >= nfa_list->capacity) return -1;

    for (size_t i = 0; i < N && nfa_list->count < nfa_list->capacity; ++i) {
        pthread_mutex_lock(&nfa_list->lock);

        unsigned long tag = rand(); // Generate unique tags
        nfa_list->list[nfa_list->count].RX_UE_INFORMATION_TAG = tag;
        nfa_list->list[nfa_list->count].RNTI = (unsigned short)(i + 1); // Example RNTI generation
        nfa_list->list[nfa_list->count].crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        nfa_list->count++;

        pthread_mutex_unlock(&nfa_list->lock);
    }

    return 0;
}

int resize_list(DynamicNfaList* nfa_list, size_t new_capacity) {
    if (!nfa_list || new_capacity <= nfa_list->capacity) return -1;

    NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfa_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return -1;

    nfa_list->list = temp;
    nfa_list->capacity = new_capacity;

    return 0;
}

void free_dynamic_nfa_list(DynamicNfaList* nfa_list) {
    if (!nfa_list) return;

    pthread_mutex_destroy(&nfa_list->lock);
    free(nfa_list->list);
    free(nfa_list);
}

int iterate_and_print(const DynamicNfaList* nfa_list) {
    if (!nfa_list || !nfa_list->list) return -1;

    for (size_t i = 0; i < nfa_list->count; ++i) {
        printf("RX_UE_INFORMATION_TAG: %lu, RNTI: %hu, CRCFLAG: %d\n",
               nfa_list->list[i].RX_UE_INFORMATION_TAG,
               nfa_list->list[i].RNTI,
               nfa_list->list[i].crc_tag.CRCFLAG);
    }

    return 0;
}

int serialize_list(const DynamicNfaList* nfa_list, const char *filename) {
    if (!nfa_list || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&nfa_list->lock);
    size_t written = fwrite(nfa_list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T), nfa_list->count, file);
    pthread_mutex_unlock(&nfa_list->lock);

    fclose(file);

    return (written == nfa_list->count) ? 0 : -1;
}

DynamicNfaList* deserialize_list(const char *filename) {
    if (!filename) return NULL;

    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t element_count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    DynamicNfaList* nfa_list = create_dynamic_nfa_list(element_count);
    if (!nfa_list) {
        fclose(file);
        return NULL;
    }

    pthread_mutex_lock(&nfa_list->lock);
    size_t read_elements = fread(nfa_list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T), element_count, file);
    nfa_list->count = (read_elements == element_count) ? element_count : 0; // Validate the number of elements
    pthread_mutex_unlock(&nfa_list->lock);

    fclose(file);

    return nfa_list;
}
