#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int UE_IDENTITY_TAG;
    int CELL_ID_TAG;
    int RRC_MESSAGE_TAG;
} LTE_RRC_MESSAGE_T;

typedef struct {
    LTE_RRC_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
} LTE_RRC_SESSION_T;

void init_session(LTE_RRC_SESSION_T *session, size_t initial_capacity) {
    session->messages = (LTE_RRC_MESSAGE_T *)malloc(initial_capacity * sizeof(LTE_RRC_MESSAGE_T));
    if (!session->messages) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    session->count = 0;
    session->capacity = initial_capacity;
}

void ensure_capacity(LTE_RRC_SESSION_T *session, size_t additional_count) {
    if (session->count + additional_count > session->capacity) {
        size_t new_capacity = session->capacity * 2;
        while (new_capacity < session->count + additional_count)
            new_capacity *= 2;

        LTE_RRC_MESSAGE_T *new_messages = (LTE_RRC_MESSAGE_T *)realloc(session->messages, new_capacity * sizeof(LTE_RRC_MESSAGE_T));
        if (!new_messages) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        session->messages = new_messages;
        session->capacity = new_capacity;
    }
}

void add_message(LTE_RRC_SESSION_T *session, int ue_identity_tag, int cell_id_tag, int rrc_message_tag) {
    ensure_capacity(session, 1);

    LTE_RRC_MESSAGE_T message;
    message.UE_IDENTITY_TAG = ue_identity_tag;
    message.CELL_ID_TAG = cell_id_tag;
    message.RRC_MESSAGE_TAG = rrc_message_tag;

    session->messages[session->count++] = message;
}

void validate_and_correct_order(LTE_RRC_SESSION_T *session) {
    for (size_t i = 1; i < session->count; ++i) {
        if (session->messages[i].RRC_MESSAGE_TAG <= session->messages[i - 1].RRC_MESSAGE_TAG) {
            // Correct the order if out of sequence
            LTE_RRC_MESSAGE_T temp = session->messages[i];
            for (size_t j = i; j > 0 && session->messages[j - 1].RRC_MESSAGE_TAG > temp.RRC_MESSAGE_TAG; --j) {
                session->messages[j] = session->messages[j - 1];
            }
            session->messages[j] = temp;
        }
    }
}

void dispatch_messages(LTE_RRC_SESSION_T *session, void (*message_broker)(LTE_RRC_MESSAGE_T *)) {
    for (size_t i = 0; i < session->count; ++i) {
        message_broker(&session->messages[i]);
    }
}

void free_session(LTE_RRC_SESSION_T *session) {
    free(session->messages);
    session->messages = NULL;
    session->count = 0;
    session->capacity = 0;
}
