    for (int i = 0; i < num_elements; ++i) {
        if ((array[i].crc_indication_rel8_tag.crcflag != 0 && array[i].crc_indication_rel8_tag.crcflag != 1)) {
            fprintf(stderr, "CRC Flag integrity check failed at index %d\n", i);
            free(array);
            return NULL;
        }
    }

    return array;
}

// Function to log the elements in different formats
void log_elements(const NFAPI_CRC_INDICATION_PDU_T *array, int num_elements, FILE *log_file, int log_level, const char *format) {
    if (!array || num_elements <= 0) {
        return;
    }

