            fwrite(&array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, log_file);
        } else if (strcmp(format, "text") == 0 && log_level > 1) {
            fprintf(log_file, "Element %d: RX UE Info Tag = %u, RNTI = %u, CRC Flag = %d\n", i, array[i].rx_ue_info_tag.tag, array[i].rnti.rnti, array[i].crc_indication_rel8_tag.crcflag);
        }
    }
}

// Function to free the allocated memory
void free_nfa_pi_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
