['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int access_count;
    const unsigned int gc_threshold; // Access cycles after which GC should run
} DynamicList;

DynamicList* create_list(unsigned int gc_threshold) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->access_count = 0;
    list->gc_threshold = gc_threshold;
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void randomize_crc_flag(CRC_INDICATION_REL8_TAG* crc_tag) {
    crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

Node* create_node(unsigned long ue_info_tag, unsigned short rnti) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data.RX_UE_INFORMATION_TAG = ue_info_tag;
    node->data.RNTI = rnti;
    randomize_crc_flag(&node->data.crc_tag);
    node->next = NULL;
    return node;
}

void insert_node(DynamicList* list, unsigned long ue_info_tag, unsigned short rnti) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(ue_info_tag, rnti);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->access_count++;
    if (list->access_count >= list->gc_threshold) {
        garbage_collect(list);
        list->access_count = 0;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_head(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;
    free(temp);

    pthread_mutex_unlock(&list->lock);
}

void garbage_collect(DynamicList* list) {
    // Simulate a simple GC by removing the first node (could be optimized further)
    if (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
}

void print_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("UE Info Tag: %lu, RNTI: %hu, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.crc_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    DynamicList* list = create_list(100); // GC every 100 access cycles

    insert_node(list, 12345, 6789);
    insert_node(list, 54321, 9876);

    print_list(list);

    remove_head(list);
    print_list(list);

    destroy_list(list);
    return 0;
}
