class Cache {
private:
    std::unordered_map<int, std::string> dataCache;
    mutable std::mutex cacheMutex;

public:
    std::string getData(int key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = dataCache.find(key);
        if (it != dataCache.end()) {
            return it->second;
        }
        return "";
    }

    void setData(int key, const std::string& value) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        dataCache[key] = value;
    }
};

