        int retries = 0;
        while (retries < 3) {
            if (billingSystem->processCharge(amount)) {
                return true;
            }
            retries++;
            std::this_thread::sleep_for(std::chrono::seconds(1 << retries)); // Exponential backoff
        }
        Logger::log("Billing failed after retries.");
        return false;
    }
};

