#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_STRUCTURES 1000 // Example maximum limit

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG; 
} CRC_INDICATION_REL8_TAG;

typedef struct {
    time_t timestamp;
    pthread_mutex_t lock;
    uint64_t id; // Unique identifier
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} NFACRCList;

// Initialize the list with a given capacity
void init_NFACRCList(NFACRCList *list, size_t initial_capacity) {
    list->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_rwlock_init(&list->rwlock, NULL);
}

// Function to add a new structure
int add_CRC_INDICATION_PDU(NFACRCList *list) {
    if (pthread_rwlock_wrlock(&list->rwlock) != 0) return -1;

    if (list->count >= list->capacity || list->capacity >= MAX_STRUCTURES) {
        pthread_rwlock_unlock(&list->rwlock);
        return -2; // Exceeded capacity
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = &list->array[list->count];
    pthread_mutex_init(&new_entry->lock, NULL);

    new_entry->timestamp = time(NULL);
    new_entry->id = (list->count + 1); // Example unique ID logic

    // Populate with random data
    new_entry->tag.RX_UE_INFORMATION_TAG = rand();
    new_entry->tag.RNTI = rand() % 65536;
    new_entry->tag.CRCFLAG = rand() % 2;

    list->count++;
    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

// Free resources
void free_NFACRCList(NFACRCList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_destroy(&list->array[i].lock);
    }
    pthread_rwlock_destroy(&list->rwlock);
    free(list->array);
}

// Example unit test
void test_add_crc_indication_pdu() {
    NFACRCList crc_list;
    init_NFACRCList(&crc_list, 10);

    for (int i = 0; i < 12; ++i) { // Attempt to add more than capacity
        int result = add_CRC_INDICATION_PDU(&crc_list);
        if (result == -2) {
            printf("Capacity limit reached at addition %d\n", i+1);
        } else if (result != 0) {
            printf("Error occurred while adding entry\n");
        }
    }

    free_NFACRCList(&crc_list);
}

int main() {
    test_add_crc_indication_pdu();
    return 0;
}
```

### Documentation:
- **Thread Safety**: The code uses `pthread_rwlock_t` for read-write locks, allowing multiple readers or one writer. Each entry has a mutex to ensure thread-safe operations on individual elements.

- **Memory Management**: Dynamic memory is allocated once during initialization, and the array size is fixed. This minimizes heap fragmentation. However, resizing logic could be added for further flexibility.

