    }

    return list;
}

// Logging functions
void initializeLogger(Logger* logger, const char* logFileName) {
    logger->logFile = fopen(logFileName, "a");
    if (!logger->logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", logFileName);
        exit(EXIT_FAILURE);
    }
    logger->consoleLog = stdout;
}

void finalizeLogger(Logger* logger) {
    if (logger->logFile) {
        fclose(logger->logFile);
    }
}

void logMessage(Logger* logger, const char* message) {
    fprintf(logger->logFile, "%s\n", message);
    fprintf(logger->consoleLog, "%s\n", message);
}

int main() {
    Logger logger;
    initializeLogger(&logger, "nfaapi_log.txt");

    int successCount = 0;
    int failureCount = 0;

    NFAPI_CRC_INDICATION_PDU_T* pduList = createNFAPICRCIndicationList(1000, &successCount, &failureCount, &logger);

    if (pduList) {
        logMessage(&logger, "Successfully created structures.");
    } else {
        logMessage(&logger, "Failed to create structures.");
    }

    logMessage(&logger, (char*)malloc(snprintf(NULL, 0, "Success count: %d\n", successCount)));
    logMessage(&logger, (char*)malloc(snprintf(NULL, 0, "Failure count: %d\n", failureCount)));

    free(pduList);
    finalizeLogger(&logger);

    return 0;
}
