#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 100000
#define ALERT_THRESHOLD_SIZE 1500 // Example threshold for packet size in bytes
#define ALERT_FREQUENCY_THRESHOLD 500 // Example frequency threshold per second

typedef struct {
    char packet_id[36]; // Unique packet ID
    char src_ip[16];
    char dst_ip[16];
    char protocol_type[10];
    time_t timestamp;
    int payload_length;
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} EventNode;

typedef struct {
    EventNode* head;
    pthread_mutex_t lock;
} TrafficList;

TrafficList traffic_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void log_event(const char* message) {
    FILE* log_file = fopen("traffic_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int add_event(NetworkEvent event) {
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) return -1;

    memcpy(&new_node->event, &event, sizeof(NetworkEvent));
    new_node->next = NULL;

    pthread_mutex_lock(&traffic_list.lock);

    new_node->next = traffic_list.head;
    traffic_list.head = new_node;

    pthread_mutex_unlock(&traffic_list.lock);
    return 0;
}

int process_event(NetworkEvent event) {
    if (event.payload_length > ALERT_THRESHOLD_SIZE) {
        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "Alert: Packet size exceeded for packet %s", event.packet_id);
        log_event(log_msg);
        return 1; // Alert triggered
    }
    return 0;
}

void* process_traffic(void* arg) {
    NetworkEvent event;
    while (1) { // Simulate receiving data indefinitely
        // Simulated network receive function
        if (!receive_network_data(&event)) continue;

        add_event(event);

        if (process_event(event)) {
            log_event("Alert triggered");
        }
    }
}

int main() {
    pthread_t traffic_thread;

    if (pthread_create(&traffic_thread, NULL, process_traffic, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(traffic_thread, NULL);
    return EXIT_SUCCESS;
}

int receive_network_data(NetworkEvent* event) {
    // Simulate network data reception
    static int counter = 0;
    if (counter >= MAX_EVENTS) return 0;

    snprintf(event->packet_id, sizeof(event->packet_id), "pkt-%d", counter++);
    strcpy(event->src_ip, "192.168.1.1");
    strcpy(event->dst_ip, "10.0.0.1");
    strcpy(event->protocol_type, "TCP");
    event->timestamp = time(NULL);
    event->payload_length = rand() % 2000;

    return 1;
}
