int pool_index = 0;

// Function to get a new structure from the pool
NFAPI_CRC_INDICATION_PDU_T *get_structure(uint16_t rnti) {
    pthread_mutex_lock(&pool_mutex);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool[i].RNTI == 0 && pool_index < POOL_SIZE) { // Unused structure
            pool[pool_index].RX_UE_INFORMATION_TAG = rand() % 10000;
            pool[pool_index].RNTI = rnti;
            pool[pool_index].CRC_INDICATION_REL8_TAG = rand() % 256;
            pool[pool_index].CRCFLAG = rand() % 2; // Random CRCFLAG
            NFAPI_CRC_INDICATION_PDU_T *new_struct = &pool[pool_index++];

            pthread_mutex_unlock(&pool_mutex);
            return new_struct;
        }
    }

    pthread_mutex_unlock(&pool_mutex);
    log_message(ERROR, "Memory pool exhausted");
    return NULL;
}

// Function to initialize the memory pool
