    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *structure = get_structure(rnti_list[i]);
        if (structure != NULL) {
            ++success_count;
        }
    }

    log_message(INFO, "Successfully created structures");
    return success_count;
}

