    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t mutex; // Mutex for thread safety
} CRC_LIST;

// Function to initialize the CRC_LIST
void init_crc_list(CRC_LIST* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Helper function to check for duplicate RNTI
bool rnti_exists(CRC_LIST* list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->crc_tag.RNTI == rnti)
            return true;
        current = current->next;
    }
    return false;
}

// Function to add a new entry to the list
void add_crc_entry(CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&list->mutex);

    if (rnti_exists(list, new_entry->crc_tag.RNTI)) {
        printf("Error: Duplicate RNTI %d detected.\n", new_entry->crc_tag.RNTI);
        free(new_entry);
    } else {
        // Insert at the head for O(1) insertion
        new_entry->next = list->head;
        list->head = new_entry;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to destroy and free the linked list
void destroy_crc_list(CRC_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* create_crc_entry(int rx_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry)
        return NULL;

    entry->crc_tag.RX_UE_INFORMATION_TAG = rx_tag;
    entry->crc_tag.RNTI = rnti;
    entry->crc_tag.CRCFLAG = rand() % 256; // Randomly set CRCFLAG
    entry->next = NULL;

    return entry;
}

// Main function for testing
int main() {
    srand(time(NULL)); // Seed random number generator

    CRC_LIST list;
    init_crc_list(&list);

    // Simulate adding entries from multiple threads (example)
    NFAPI_CRC_INDICATION_PDU_T* entry1 = create_crc_entry(1, 100);
    add_crc_entry(&list, entry1);

    NFAPI_CRC_INDICATION_PDU_T* entry2 = create_crc_entry(2, 101);
    add_crc_entry(&list, entry2);

    // Attempt to add a duplicate RNTI
    NFAPI_CRC_INDICATION_PDU_T* entry3 = create_crc_entry(3, 100);
    add_crc_entry(&list, entry3);

    destroy_crc_list(&list);

    return 0;
}
