```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Assuming NFAPI_CRC_INDICATION_PDU_T is defined elsewhere
typedef struct {
    unsigned int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} CRCList;

CRCList* create_list() {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

void free_node(Node* node) {
    free(node);
}

int is_rnti_unique(CRCList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        log_error("Duplicate RNTI detected: %u", pdu.RNTI);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_error("Memory allocation failed");
        return -1;
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_pdu(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free_node(current);

    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void trim_list(CRCList* list, size_t max_size) {
    pthread_mutex_lock(&list->lock);

    while (list->size > max_size && list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free_node(temp);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

void update_from_external_source(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* updates, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_pdu(list, updates[i]);
    }
}

void destroy_list(CRCList* list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free_node(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example logging function
