#define MAX_HARQ_PROCESSES 8

typedef struct {
    int pdsch_grant;
    int harq_process_id;
    int mcs_level;
} DL_SCH_PDSCH_DCI_INFO_T;

typedef struct {
    int cell_id;
    int frame_number;
    size_t num_dci_info_list;
    DL_SCH_PDSCH_DCI_INFO_T *dci_info_list;
} LTE_DL_FRAME_STRUCT;

// Function prototypes
void initialize_frames(LTE_DL_FRAME_STRUCT **frames, size_t num_frames);
void free_frames(LTE_DL_FRAME_STRUCT **frames, size_t num_frames);

void initialize_frames(LTE_DL_FRAME_STRUCT **frames, size_t num_frames) {
    srand(time(NULL));

    *frames = (LTE_DL_FRAME_STRUCT *)malloc(num_frames * sizeof(LTE_DL_FRAME_STRUCT));
    if (*frames == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_frames; ++i) {
        // Simulate potential delay in receiving cell ID
        int cell_id = rand() % 10000; // Random cell ID

        (*frames)[i].cell_id = cell_id;
        (*frames)[i].frame_number = i;

        size_t num_dci_info_list = rand() % 10 + 1; // Random number of DCI objects (1 to 10)
        (*frames)[i].dci_info_list = (DL_SCH_PDSCH_DCI_INFO_T *)malloc(num_dci_info_list * sizeof(DL_SCH_PDSCH_DCI_INFO_T));

        if ((*frames)[i].dci_info_list == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free_frames(frames, i);
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < num_dci_info_list; ++j) {
            (*frames)[i].dci_info_list[j].pdsch_grant = rand() % 100; // Random PDSCH Grant
            (*frames)[i].dci_info_list[j].harq_process_id = rand() % MAX_HARQ_PROCESSES; // Random HARQ Process ID
            (*frames)[i].dci_info_list[j].mcs_level = rand() % 28; // Random MCS level (0 to 27)
        }

        (*frames)[i].num_dci_info_list = num_dci_info_list;
    }
}

void free_frames(LTE_DL_FRAME_STRUCT **frames, size_t num_frames) {
    if (*frames != NULL) {
        for (size_t i = 0; i < num_frames; ++i) {
            free((*frames)[i].dci_info_list);
        }
        free(*frames);
        *frames = NULL;
    }
}

int main() {
    size_t num_frames = 100; // Example number of frames
    LTE_DL_FRAME_STRUCT *frames = NULL;

    initialize_frames(&frames, num_frames);

    // Use the initialized frames...

    free_frames(&frames, num_frames);

    return 0;
}
