AllocationIndex allocate_frame_info() {
    AllocationIndex alloc_index;
    Node* prev = NULL;
    Node* current = head;

    while (current != NULL) {
        if (!atomic_load(&current->next)) {
            atomic_store(&current->next, &head);
            alloc_index.index = ((uintptr_t)current - (uintptr_t)memory_pool) / sizeof(Node);
            alloc_index.valid = true;
            return alloc_index;
        }
        prev = current;
        current = atomic_load(&current->next);
    }

    // If no free node is found, consider expanding the list or handle out-of-memory.
    alloc_index.index = SIZE_MAX;
    alloc_index.valid = false;

    return alloc_index;
}

void free_frame_info(AllocationIndex alloc_index) {
    if (!alloc_index.valid || alloc_index.index >= capacity) return;

    Node* to_free = &((Node*)memory_pool)[alloc_index.index];
    atomic_store(&to_free->next, head);
