    if (current_timestamp - last_gc_timestamp >= GARBAGE_COLLECTION_INTERVAL_MS) {
        garbage_collect();
        last_gc_timestamp = current_timestamp;
    }
}

void garbage_collect() {
    Node* prev = NULL;
    Node* current = head;

    while (current != NULL && atomic_load(&allocation_count) > 0) {
        if (/* condition to determine if the node is unused */) {
            // Free or recycle node
            Node* next = atomic_load(&current->next);
            atomic_store(&prev->next, next);
            --allocation_count;
        } else {
            prev = current;
        }
        current = atomic_load(&prev->next);
    }
}

