// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list structure
typedef struct {
    Node* head;
    int size;
} LinkedList;

// Function prototypes
LinkedList* createList();
int insertUnique(LinkedList* list, unsigned int tag);
void freeList(LinkedList* list);

// Create a new linked list
LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

// Insert unique element into the list
int insertUnique(LinkedList* list, unsigned int tag) {
    if (!list) return -1;

    // Check for uniqueness
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            return 0; // Element already exists
        }
        current = current->next;
    }

    // Insert new element
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->data.RX_UE_INFORMATION_TAG = tag;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    return 1; // Success
}

// Free the linked list and its elements
void freeList(LinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

// Example usage
int main() {
    LinkedList* list = createList();
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return 1;
    }

    // Insert elements (example)
