int read_json_file(const char *filename, json_object **jobj) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    struct json_object *parsed_json;
    size_t file_size;
    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    rewind(file);

    char *buffer = (char *)malloc(file_size + 1);
    fread(buffer, file_size, 1, file);
    buffer[file_size] = '\0';

    parsed_json = json_tokener_parse(buffer);
    free(buffer);
    fclose(file);

    if (!parsed_json) {
        free(parsed_json);
        return 0;
    }

    *jobj = parsed_json;
    return 1;
}

