#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    unsigned int rnti;
    // Add more UE configuration parameters as needed
    char config[256];
} LTEUEContext;

typedef struct {
    LTEUEContext *contexts;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
} LTEUEList;

// Initialize the list
void initializeLTEUEList(LTEUEList *list) {
    list->contexts = malloc(INITIAL_CAPACITY * sizeof(LTEUEContext));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
}

// Resize the list if necessary
void resizeLTEUEListIfNeeded(LTEUEList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTEUEContext *new_contexts = realloc(list->contexts, new_capacity * sizeof(LTEUEContext));
        if (new_contexts) {
            list->contexts = new_contexts;
            list->capacity = new_capacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed while resizing the context list.\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Add a new LTE UE context to the list
void addLTEUEContext(LTEUEList *list, unsigned int rnti, const char *config) {
    pthread_rwlock_wrlock(&list->lock);

    resizeLTEUEListIfNeeded(list);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].rnti == rnti) {
            // Update existing context
            strncpy(list->contexts[i].config, config, sizeof(list->contexts[i].config));
            pthread_rwlock_unlock(&list->lock);
            return;
        }
    }

    list->contexts[list->size].rnti = rnti;
    strncpy(list->contexts[list->size].config, config, sizeof(list->contexts[list->size].config));
    ++list->size;

    pthread_rwlock_unlock(&list->lock);
}

// Retrieve a context by RNTI
LTEUEContext *getLTEUEContextByRNTI(LTEUEList *list, unsigned int rnti) {
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].rnti == rnti) {
            LTEUEContext *context = malloc(sizeof(LTEUEContext));
            memcpy(context, &list->contexts[i], sizeof(LTEUEContext));
            pthread_rwlock_unlock(&list->lock);
            return context;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL; // Not found
}

// Remove a context by RNTI
void removeLTEUEContextByRNTI(LTEUEList *list, unsigned int rnti) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].rnti == rnti) {
            memmove(&list->contexts[i], &list->contexts[i + 1],
                    (--list->size - i) * sizeof(LTEUEContext));
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);
}

// Free resources
void destroyLTEUEList(LTEUEList *list) {
    free(list->contexts);
    pthread_rwlock_destroy(&list->lock);
}

int main() {
    LTEUEList list;
    initializeLTEUEList(&list);

    addLTEUEContext(&list, 1001, "ConfigA");
    addLTEUEContext(&list, 1002, "ConfigB");

    LTEUEContext *context = getLTEUEContextByRNTI(&list, 1001);
    if (context) {
        printf("Retrieved RNTI: %u, Config: %s\n", context->rnti, context->config);
        free(context);
    }

    removeLTEUEContextByRNTI(&list, 1001);

    destroyLTEUEList(&list);
    return 0;
}
```

This code implements a basic LTE UE context manager in C. It uses dynamic resizing for the list of contexts and read-write locks to manage concurrent access efficiently. This setup ensures that operations are fast enough for high-throughput environments, while also handling configuration updates gracefully without restarting the system. Additional enhancements like caching, error handling, and performance monitoring can be integrated as needed based on specific requirements.']

