#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int rntiSet[MAX_RNTI] = {0};

// Function to generate a unique RNTI
uint16_t generateUniqueRNTI() {
    uint16_t rnti;
    do {
        // Simulate external data source or fallback local generation
        rnti = rand() % MAX_RNTI;
    } while (rntiSet[rnti] != 0);

    pthread_mutex_lock(&listMutex);
    rntiSet[rnti] = 1; // Mark as used
    pthread_mutex_unlock(&listMutex);

    return rnti;
}

// Function to create and populate the linked list with N entries
Node* createNFAPI_CRC_INDICATION_PDU_List(int N) {
    Node *current, *newNode;

    for (int i = 0; i < N; ++i) {
        newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed.\n");
            continue;
        }

        // Generate unique RNTI
        newNode->data.RNTI = generateUniqueRNTI();

        // Populate CRC_INDICATION_REL8_TAG
        newNode->data.crcTag.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&listMutex);
        newNode->next = NULL;
        if (head == NULL) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
        pthread_mutex_unlock(&listMutex);
    }

    return head;
}

// Function to serialize the linked list into a binary file
void serializeList(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&listMutex);
    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&listMutex);

    fclose(file);
}

// Function to deserialize a binary file into the linked list
Node* deserializeList(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading.\n");
        return NULL;
    }

    pthread_mutex_lock(&listMutex);
    head = NULL;
    Node* current = NULL;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        Node *newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed during deserialization.\n");
            break;
        }

        newNode->data = pdu;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    pthread_mutex_unlock(&listMutex);
    fclose(file);

    return head;
}

// Utility function to free the linked list
void freeList() {
    pthread_mutex_lock(&listMutex);
    Node* current = head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    head = NULL;
    pthread_mutex_unlock(&listMutex);
}

int main() {
    srand(time(NULL)); // Seed random number generator
    int N = 10; // Example size of the list

    createNFAPI_CRC_INDICATION_PDU_List(N);
    serializeList("nfa_list.bin");
    freeList();

    Node* deserializedList = deserializeList("nfa_list.bin");

    // Cleanup after deserialization
    freeList();

    return 0;
}
```

