// Packet header structures
typedef struct {
    // IP Header fields
} IPHeader;

typedef struct {
    // UDP Header fields
} UDPHeader;

typedef struct {
    IPHeader ip_header;
    UDPHeader udp_header;
} PacketHeader;

typedef struct {
    PacketHeader *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // For thread-safety
} DynamicPacketArray;

// Initialize the dynamic packet array
DynamicPacketArray* init_packet_array(size_t initial_capacity) {
    DynamicPacketArray *array = malloc(sizeof(DynamicPacketArray));
    if (!array) return NULL;

    array->packets = calloc(initial_capacity, sizeof(PacketHeader));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Resize the dynamic packet array
int resize_packet_array(DynamicPacketArray *array, size_t new_capacity) {
    if (new_capacity <= array->capacity)
        return 0;

    PacketHeader *new_packets = realloc(array->packets, new_capacity * sizeof(PacketHeader));
    if (!new_packets)
        return -1; // Error

    array->packets = new_packets;
    array->capacity = new_capacity;
    return 0;
}

// Add a packet to the dynamic packet array
int add_packet(DynamicPacketArray *array, PacketHeader *packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        int resize_result = resize_packet_array(array, array->capacity * 2);
        if (resize_result != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Error
        }
    }

    array->packets[array->count++] = *packet;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Free the dynamic packet array
void free_packet_array(DynamicPacketArray *array) {
    if (!array)
        return;

    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage function for populating packets with different ports
void populate_packets_with_ports(DynamicPacketArray *array, size_t packet_count) {
    for (size_t i = 0; i < packet_count; ++i) {
        PacketHeader packet;

        // Initialize IPHeader and UDPHeader in 'packet'
        // Customize based on network requirements

        add_packet(array, &packet);
    }
}

// Example main function
int main() {
    DynamicPacketArray *packet_array = init_packet_array(10);

    if (!packet_array) {
        fprintf(stderr, "Failed to initialize packet array\n");
        return 1;
    }

    populate_packets_with_ports(packet_array, 50);

    free_packet_array(packet_array);
    return 0;
}
