#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    FILE* log_file;
} DynamicList;

// Function Prototypes
DynamicList* create_list(const char* log_filename);
void destroy_list(DynamicList* list);
int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry);
int remove_entry(DynamicList* list, int index);
NFAPI_CRC_INDICATION_PDU_T get_entry(DynamicList* list, int index);
int save_to_file(const char* filename, DynamicList* list);
DynamicList* load_from_file(const char* filename);

// Logging function
void log_event(DynamicList* list, const char* event) {
    pthread_mutex_lock(&list->lock);
    fprintf(list->log_file, "%s\n", event);
    fflush(list->log_file);
    pthread_mutex_unlock(&list->lock);
}

DynamicList* create_list(const char* log_filename) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    list->log_file = fopen(log_filename, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        free(list);
        return NULL;
    }
    log_event(list, "List created");

    return list;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    log_event(list, "Memory deallocated");
    fclose(list->log_file);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "Added entry at index %zu", list->size);
    log_event(list, log_buffer);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList* list, int index) {
    if (index < 0 || index >= (int)list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *previous = NULL;
    for (int i = 0; current && i < index; ++i) {
        previous = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (previous) {
        previous->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "Removed entry at index %d", index);
    log_event(list, log_buffer);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_entry(DynamicList* list, int index) {
    if (index < 0 || index >= (int)list->size) {
        fprintf(stderr, "Index out of bounds\n");
        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (int i = 0; current && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty;
    }

    NFAPI_CRC_INDICATION_PDU_T entry = current->data;

    pthread_mutex_unlock(&list->lock);
    return entry;
}

int save_to_file(const char* filename, DynamicList* list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    fwrite(&list->size, sizeof(size_t), 1, file);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "List saved to %s", filename);
    log_event(list, log_buffer);

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

DynamicList* load_from_file(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    DynamicList* list = create_list("list_operations.log");
    if (!list) {
        fclose(file);
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    fread(&(list->size), sizeof(size_t), 1, file);
    NFAPI_CRC_INDICATION_PDU_T entry;
    for (size_t i = 0; i < list->size; ++i) {
        if (!fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            perror("Failed to read entry from file");
            destroy_list(list);
            fclose(file);
            return NULL;
        }
        add_entry(list, entry);
    }

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "List loaded from %s", filename);
    log_event(list, log_buffer);

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return list;
}
