#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    void (*callback)(const char* event, const NFAPI_CRC_INDICATION_PDU_T* data);
} CRCIndicationList;

void notify_change(CRCIndicationList* list, const char* event, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->callback && data) {
        list->callback(event, data);
    }
}

CRCIndicationList* create_list(void (*cb)(const char*, const NFAPI_CRC_INDICATION_PDU_T*)) {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->callback = cb;

    return list;
}

void free_list(CRCIndicationList* list) {
    Node *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list || !data) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        // Remove oldest element first
        Node *temp = list->head;
        list->head = list->head->next;
        free(temp);
        --list->size;
        notify_change(list, "removed", NULL);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of memory
    }
    new_node->data = *data;
    new_node->next = list->head;
    list->head = new_node;
    ++list->size;

    notify_change(list, "added", data);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int add_batch(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T* batch_data, size_t count) {
    if (!list || !batch_data) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < count; ++i) {
        while (list->size >= MAX_LIST_SIZE) {
            Node *temp = list->head;
            list->head = list->head->next;
            free(temp);
            --list->size;
            notify_change(list, "removed", NULL);
        }

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        new_node->data = batch_data[i];
        new_node->next = list->head;
        list->head = new_node;
        ++list->size;

        notify_change(list, "added", &batch_data[i]);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_oldest(CRCIndicationList* list) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Nothing to remove
    }

    Node *temp = list->head;
    list->head = list->head->next;
    free(temp);
    --list->size;

    notify_change(list, "removed", NULL);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_batch(CRCIndicationList* list, size_t count) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < count && list->size > 0; ++i) {
        Node *temp = list->head;
        list->head = list->head->next;
        free(temp);
        --list->size;

        notify_change(list, "removed", NULL);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}
```

This code defines a thread-safe dynamic list management system for `NFAPI_CRC_INDICATION_PDU_T` structures. The core operations include adding individual and batch elements, removing oldest elements both individually and in batches, while maintaining synchronization using mutexes. Callbacks notify clients of changes to the list. Memory is managed carefully to prevent leaks, even when errors occur during operations.']

['Below is a C implementation for the described task. The code includes dynamic memory allocation, validation, logging, thread safety using mutexes, error handling, and network latency management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Definitions and constants (Assumed)
#define MAX_RNTI_VALUE 65535
#define LOG_FILE "crc_log.txt"
#define RETRY_LIMIT 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to simulate external service call with retry logic
int fetch_RX_UE_INFORMATION_TAG(int *tag) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        // Simulate network delay and potential failure
        if ((rand() % 10) != 0) { // 90% chance of success
            *tag = rand(); // Fetch data successfully
            return 1; // Success
        }
        retries++;
    }
    return 0; // Failure after retries
}

// Function to log information with thread safety
void log_info(const char *message, int level) {
    pthread_mutex_lock(&log_mutex);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
    pthread_mutex_unlock(&log_mutex);
}

// Main function to allocate and initialize structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdus(int N, int log_level) {
    if (N <= 0) return NULL;

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_info("Memory allocation failed.", log_level);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        int RX_UE_TAG;
        if (!fetch_RX_UE_INFORMATION_TAG(&RX_UE_TAG)) {
            free(pdus); // Free allocated memory on failure
            log_info("Failed to fetch RX_UE_INFORMATION_TAG after retries.", log_level);
            return NULL;
        }

        uint16_t RNTI = rand() % (MAX_RNTI_VALUE + 1);

        if (RNTI > MAX_RNTI_VALUE) {
            free(pdus); // Free allocated memory on invalid value
            log_info("Invalid RNTI value fetched.", log_level);
            return NULL;
        }

        unsigned char CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        pdus[i].RX_UE_INFORMATION_TAG = RX_UE_TAG;
        pdus[i].RNTI = RNTI;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "PDU[%d]: RX_UE_TAG=%d, RNTI=0x%04X, CRCFLAG=%d", 
                 i, pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG);

        if (log_level > 1) {
            log_info(log_message, log_level);
        }
    }

    return pdus;
}

// Example of usage
int main() {
    int N = 10; // User input for number of PDUs
    int log_level = 2; // Example log level

    NFAPI_CRC_INDICATION_PDU_T *pdus = create_crc_indication_pdus(N, log_level);
    if (pdus) {
        printf("PDUs created successfully.\n");

        free(pdus); // Free allocated memory
    } else {
        printf("Failed to create PDUs.\n");
    }

    pthread_mutex_destroy(&log_mutex);
    return 0;
}
```

This implementation uses a mutex for thread-safe logging and includes error handling for network-related issues by retrying the fetch operation. It dynamically allocates memory, validates RNTI values, and logs details of each structure created. The code is designed to be scalable and maintainable with future enhancements in mind.']

['Below is a C code implementation for your task description. This example focuses on initializing a dynamic array of `LTE_PHY_MEASUREMENT_T` structures, populating them with `NFAPI_CRC_INDICATION_PDU_T` structures, and managing packet lists using both an array and a linked list for comparison. The solution ensures thread safety, efficient memory management, and scalability under varying loads.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEASUREMENTS 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketNode {
    NFAPI_CRC_INDICATION_PDU_T packet;
    struct PacketNode* next;
} PacketNode;

typedef struct {
    int CELL_ID;
    time_t TIMESTAMP;
    float RSSI;
    unsigned int num_packets;
    unsigned int capacity;
    float total_rssi; // For average calculation
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* packets_array;
    PacketNode* packets_list_head;
} LTE_PHY_MEASUREMENT_T;

typedef struct {
    LTE_PHY_MEASUREMENT_T* measurements;
    size_t count;
    size_t capacity;
    pthread_mutex_t list_mutex;
} MeasurementManager;

MeasurementManager* init_manager(size_t initial_capacity) {
    MeasurementManager* manager = malloc(sizeof(MeasurementManager));
    if (!manager) return NULL;

    manager->measurements = calloc(initial_capacity, sizeof(LTE_PHY_MEASUREMENT_T));
    if (!manager->measurements) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->list_mutex, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&manager->measurements[i].mutex, NULL);
        manager->measurements[i].packets_array = NULL;
        manager->measurements[i].packets_list_head = NULL;
    }

    return manager;
}

void free_manager(MeasurementManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        pthread_mutex_lock(&manager->measurements[i].mutex);

        // Free array
        free(manager->measurements[i].packets_array);

        // Free linked list
        PacketNode* current = manager->measurements[i].packets_list_head;
        while (current) {
            PacketNode* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&manager->measurements[i].mutex);
    }

    pthread_mutex_destroy(&manager->list_mutex);

    for (size_t i = 0; i < manager->capacity; ++i) {
        pthread_mutex_destroy(&manager->measurements[i].mutex);
    }

    free(manager->measurements);
    free(manager);
}

int add_measurement(MeasurementManager* manager, LTE_PHY_MEASUREMENT_T measurement) {
    if (!manager || manager->count >= MAX_MEASUREMENTS) return -1;

    pthread_mutex_lock(&manager->list_mutex);

    // Maintain a rolling window of the last 1000 entries
    size_t index = manager->count % MAX_MEASUREMENTS;
    pthread_mutex_lock(&manager->measurements[index].mutex);
    memcpy(&manager->measurements[index], &measurement, sizeof(LTE_PHY_MEASUREMENT_T));
    pthread_mutex_unlock(&manager->measurements[index].mutex);

    manager->count++;
    if (manager->count > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_PHY_MEASUREMENT_T* new_measurements = realloc(manager->measurements, new_capacity * sizeof(LTE_PHY_MEASUREMENT_T));
        if (!new_measurements) return -1;

        for (size_t i = manager->capacity; i < new_capacity; ++i) {
            pthread_mutex_init(&new_measurements[i].mutex, NULL);
            new_measurements[i].packets_array = NULL;
            new_measurements[i].packets_list_head = NULL;
        }

        manager->measurements = new_measurements;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->list_mutex);

    return 0;
}

void add_packet(LTE_PHY_MEASUREMENT_T* measurement, NFAPI_CRC_INDICATION_PDU_T packet) {
    if (!measurement) return;

    pthread_mutex_lock(&measurement->mutex);

    // Array-based storage
    if (measurement->num_packets >= measurement->capacity) {
        size_t new_capacity = measurement->capacity ? measurement->capacity * 2 : 4;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(measurement->packets_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return;

        measurement->packets_array = new_array;
        measurement->capacity = new_capacity;
    }

    measurement->packets_array[measurement->num_packets++] = packet;
    measurement->total_rssi += packet.crc_indication_rel8_tag.CRCFLAG; // Example RSSI update

    // Linked list-based storage
    PacketNode* new_node = malloc(sizeof(PacketNode));
    if (new_node) {
        new_node->packet = packet;
        new_node->next = measurement->packets_list_head;
        measurement->packets_list_head = new_node;
    }

    pthread_mutex_unlock(&measurement->mutex);
}

float calculate_average_rssi(LTE_PHY_MEASUREMENT_T* measurement) {
    if (!measurement || measurement->num_packets == 0) return 0.0f;

    pthread_mutex_lock(&measurement->mutex);
    float average_rssi = measurement->total_rssi / measurement->num_packets;
    pthread_mutex_unlock(&measurement->mutex);

    return average_rssi;
}

void example_usage() {
    srand(time(NULL));
    MeasurementManager* manager = init_manager(10);
    if (!manager) {
        printf("Failed to initialize measurement manager.\n");
        return;
    }

    for (int i = 0; i < 20; ++i) { // Add more measurements than initial capacity
        LTE_PHY_MEASUREMENT_T measurement;
        measurement.CELL_ID = rand() % 100;
        measurement.TIMESTAMP = time(NULL);
        measurement.RSSI = 0.0f;
        measurement.num_packets = 0;

        NFAPI_CRC_INDICATION_PDU_T packet;
        packet.RX_UE_INFORMATION_TAG = rand();
        packet.RNTI = rand() % 10;
        packet.crc_indication_rel8_tag.CRCFLAG = rand() % 100;

        add_packet(&measurement, packet);

        int result = add_measurement(manager, measurement);
        if (result != 0) {
            printf("Failed to add measurement.\n");
        }
    }

    for (size_t i = 0; i < manager->count && i < MAX_MEASUREMENTS; ++i) {
        float average_rssi = calculate_average_rssi(&manager->measurements[i % MAX_MEASUREMENTS]);
        printf("Measurement %zu - Average RSSI: %.2f\n", i, average_rssi);
    }

    free_manager(manager);
}

int main() {
    example_usage();
    return 0;
}
```

### Key Features:
- **Thread Safety:** Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Array Management:** Implements dynamic resizing for packet storage arrays.
- **Linked List Option:** Demonstrates linked list management as an alternative.
- **Rolling Window:** Maintains a fixed-size rolling window of measurements.
- **Error Handling:** Checks for allocation failures and handles them gracefully.

This implementation provides a robust foundation for managing LTE PHY measurements with dynamic packet handling, ensuring scalability and performance under varying loads.']

['Below is a C implementation for managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures. This code includes features for dynamic resizing, efficient iteration, memory management, error handling, filtering criteria based on age and frequency within a 3-second window, and thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    unsigned int max_weighted_sum;
    unsigned int corresponding_rnti;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->max_weighted_sum = 0;
    list->corresponding_rnti = 0;
    return list;
}

void free_node(Node* node) {
    free(node);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = pdu;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = NULL;
    }

    list->size++;

    // Update metrics
    unsigned int weighted_sum = pdu.RX_UE_INFORMATION_TAG * 0.7 + pdu.RNTI * 0.3;
    if (weighted_sum > list->max_weighted_sum) {
        list->max_weighted_sum = weighted_sum;
        list->corresponding_rnti = pdu.RNTI;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_old_elements(DynamicList* list, time_t current_time) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next_node;

    while (current) {
        next_node = current->next;

        if ((current_time - current->timestamp) > 3) { // 3 seconds window
            if (current->prev)
                current->prev->next = current->next;
            else
                list->head = current->next;

            if (current->next)
                current->next->prev = current->prev;
            else
                list->tail = current->prev;

            free_node(current);
            list->size--;
        }

        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    list->head = list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void process_list(DynamicList* list) {
    time_t current_time = time(NULL);

    // Filter and remove old elements
    remove_old_elements(list, current_time);

    // Iterate over the list
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("Processing RNTI: %u\n", current->data.RNTI);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu_example = { .RX_UE_INFORMATION_TAG = 12345, .RNTI = 6789 };
    add_element(list, pdu_example);

    process_list(list);
    cleanup_list(list);

    return 0;
}
```

### Key Points:
- **DynamicList Structure**: Manages the list with head and tail pointers, mutex for thread safety, size, and metrics.
- **Thread Safety**: Utilizes `pthread_mutex_t` to lock critical sections ensuring safe concurrent access.
- **Memory Management**: Proper allocation and deallocation prevent memory leaks. Use of mutex ensures no race conditions during dynamic resizing or element removal.
- **Element Filtering**: Elements older than 3 seconds are removed in the `remove_old_elements` function, optimizing list size for real-time data management.
- **Metrics Calculation**: Updates `max_weighted_sum` and its corresponding `RNTI` each time a new element is added.

This implementation provides efficient memory usage and CPU performance under high-load conditions while ensuring thread safety.']

['Below is a C implementation that addresses the task requirements by managing a dynamic array of `LTE_DL_FRAMEINFO` structures with considerations for initialization, updates from an NMS, error handling, scalability, and usability.

