#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024

typedef struct {
    // Define fields relevant to MAC_RACH_CONFIG_DRS
    int someConfigValue; // Placeholder example field
} MAC_RACH_CONFIG_DRS;

typedef struct {
    // Define fields relevant to PHY_RX_CONFIG
    int anotherConfigValue; // Placeholder example field
} PHY_RX_CONFIG;

