    unsigned char* rawPacketData;
} DL_FRAME_INFO;

typedef struct {
    MAC_RACH_CONFIG_DRS macRachConfigDrss;
    PHY_RX_CONFIG phyRxConfigs;
    DL_FRAME_INFO dlFrameInfo;
} LTE_DL_FRAMEINFO;

typedef struct {
    LTE_DL_FRAMEINFO* frames;
    size_t frameCount;
    size_t capacity;
} FrameManager;

void initDefaultMACRACHConfig(MAC_RACH_CONFIG_DRS *config) {
    // Initialize with default values
    config->someConfigValue = 0; // Default value
}

void initDefaultPHYRXConfig(PHY_RX_CONFIG *config) {
    // Initialize with default values
    config->anotherConfigValue = 1; // Default value
}

void initDLFrameInfo(DL_FRAME_INFO *info) {
    info->rawPacketData = (unsigned char*)malloc(MAX_PACKET_SIZE);
    if (!info->rawPacketData) {
        fprintf(stderr, "Failed to allocate memory for DL frame info\n");
        exit(EXIT_FAILURE); // Handle allocation failure gracefully
    }
    memset(info->rawPacketData, 0, MAX_PACKET_SIZE);
}

void initFrame(LTE_DL_FRAMEINFO *frame) {
    initDefaultMACRACHConfig(&frame->macRachConfigDrss);
    initDefaultPHYRXConfig(&frame->phyRxConfigs);
    initDLFrameInfo(&frame->dlFrameInfo);
}

void resizeFrames(FrameManager* manager, size_t newCapacity) {
    LTE_DL_FRAMEINFO* newFrames = (LTE_DL_FRAMEINFO*)realloc(manager->frames, newCapacity * sizeof(LTE_DL_FRAMEINFO));
    if (!newFrames) {
        fprintf(stderr, "Failed to reallocate memory for frames\n");
        exit(EXIT_FAILURE);
    }
    manager->frames = newFrames;
    manager->capacity = newCapacity;
}

void initializeFrameManager(FrameManager* manager, size_t initialCapacity) {
    manager->frameCount = 0;
    manager->capacity = initialCapacity;
    resizeFrames(manager, initialCapacity);
    for (size_t i = 0; i < initialCapacity; ++i) {
        initFrame(&manager->frames[i]);
    }
}

void addFrame(FrameManager* manager) {
    if (manager->frameCount >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        resizeFrames(manager, newCapacity);
    }
    initFrame(&manager->frames[manager->frameCount++]);
}

void updateMACRACHConfig(MAC_RACH_CONFIG_DRS* config, int newValue) {
    // Example: Update the configuration value
    config->someConfigValue = newValue;
}

void updatePHYRXConfig(PHY_RX_CONFIG* config, int newValue) {
    // Example: Update the configuration value
    config->anotherConfigValue = newValue;
}

void handleNetworkUpdates(FrameManager *manager, MAC_RACH_CONFIG_DRS newMacRachConfig, PHY_RX_CONFIG newPhyRxConfig) {
    for (size_t i = 0; i < manager->frameCount; ++i) {
        updateMACRACHConfig(&manager->frames[i].macRachConfigDrss, newMacRachConfig.someConfigValue);
        updatePHYRXConfig(&manager->frames[i].phyRxConfigs, newPhyRxConfig.anotherConfigValue);
    }
}

void freeFrameManager(FrameManager* manager) {
    for (size_t i = 0; i < manager->frameCount; ++i) {
        free(manager->frames[i].dlFrameInfo.rawPacketData);
    }
    free(manager->frames);
    manager->frames = NULL;
    manager->frameCount = 0;
    manager->capacity = 0;
}

int main() {
    FrameManager manager;
    initializeFrameManager(&manager, 10); // Start with an initial capacity of 10 frames

    // Example usage: Adding a new frame
    addFrame(&manager);

    // Simulate receiving updates from NMS
    MAC_RACH_CONFIG_DRS nmsMacRachConfig = { .someConfigValue = 42 };
    PHY_RX_CONFIG nmsPhyRxConfig = { .anotherConfigValue = 84 };

    handleNetworkUpdates(&manager, nmsMacRachConfig, nmsPhyRxConfig);

    // Clean up resources
    freeFrameManager(&manager);

    return 0;
}
```

### Key Features:

- **Dynamic Array Management**: Uses a dynamic array that doubles its capacity when needed.
- **Initialization and Defaults**: Frames are initialized with default configurations for `MAC_RACH_CONFIG_DRS`, `PHY_RX_CONFIG`, and allocate memory for `DL_FRAME_INFO`.
- **Handling Updates**: Incorporates updates from an NMS while allowing the system to continue functioning in degraded mode using last-known-good settings if needed.
- **Memory Management**: Manages dynamic memory allocation, ensuring resources are freed properly to avoid leaks.
- **Error Handling**: Provides robust error handling for memory allocation failures and logs critical errors.

This implementation balances performance, scalability, usability, and maintainability by providing a flexible interface and efficient resource management.']

