#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    unsigned long long memory_usage; // in bytes
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->memory_usage = 0;

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current) {
        next = current->next;
        free(current);
        list->memory_usage -= sizeof(Node);
        list->size--;
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;

    return node;
}

void append_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;
    list->memory_usage += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
}

void populate_list(LinkedList* list, size_t n) {
    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        append_to_list(list, pdu);
    }
}

void log_resource_usage(const LinkedList* list) {
    printf("List Size: %zu\n", list->size);
    printf("Memory Usage: %llu bytes\n", list->memory_usage);
}

int main() {
    size_t n = 10000;
    LinkedList* list = create_linked_list();

    if (!list) {
        fprintf(stderr, "Failed to create linked list.\n");
        return EXIT_FAILURE;
    }

    populate_list(list, n);

    log_resource_usage(list);

    destroy_linked_list(list);
    return EXIT_SUCCESS;
}
