typedef struct {
    char bssid[6]; // Example field, adjust as needed
} IEEE80211_STA_INFO;

typedef struct {
    unsigned char* data;
    size_t capacity;
    size_t count;
    size_t packet_size;
} CLIENT_PACKET_QUEUE;

typedef struct {
    IEEE80211_STA_INFO sta_info;
    PHY_RX_STATS rx_stats;
    CLIENT_PACKET_QUEUE packet_queue;
} WLAN_CLIENT_STATS;

// Function prototypes
WLAN_CLIENT_STATS* create_client();
void delete_client(WLAN_CLIENT_STATS** client);
void update_rx_stats(WLAN_CLIENT_STATS* client, int new_metric);
int enqueue_packet(WLAN_CLIENT_STATS* client, const unsigned char* packet, size_t size);
int dequeue_packet(WLAN_CLIENT_STATS* client, unsigned char* buffer);

// Implementation

WLAN_CLIENT_STATS* create_client() {
    WLAN_CLIENT_STATS* client = (WLAN_CLIENT_STATS*)malloc(sizeof(WLAN_CLIENT_STATS));
    if (!client) return NULL;

    // Initialize sta_info and rx_stats with default values
    memset(&client->sta_info, 0, sizeof(IEEE80211_STA_INFO));
    memset(&client->rx_stats, 0, sizeof(PHY_RX_STATS));

    // Initialize packet_queue
    client->packet_queue.capacity = 64;
    client->packet_queue.count = 0;
    client->packet_queue.packet_size = 128; // Example size, adjust as needed

    // Allocate initial buffer
    client->packet_queue.data = (unsigned char*)malloc(client->packet_queue.capacity * client->packet_queue.packet_size);
    if (!client->packet_queue.data) {
        free(client);
        return NULL;
    }

    return client;
}

void delete_client(WLAN_CLIENT_STATS** client) {
    if (*client) {
        free((*client)->packet_queue.data);
        free(*client);
        *client = NULL;
    }
}

void update_rx_stats(WLAN_CLIENT_STATS* client, int new_metric) {
    if (client) {
        client->rx_stats.some_rx_metric = new_metric;
    }
}

int enqueue_packet(WLAN_CLIENT_STATS* client, const unsigned char* packet, size_t size) {
    if (!client || !packet || size > client->packet_queue.packet_size) return -1;

    if (client->packet_queue.count >= client->packet_queue.capacity) {
        // Double the capacity
        size_t new_capacity = client->packet_queue.capacity * 2;
        unsigned char* new_data = (unsigned char*)realloc(client->packet_queue.data, new_capacity * client->packet_queue.packet_size);
        if (!new_data) return -1;

        client->packet_queue.data = new_data;
        client->packet_queue.capacity = new_capacity;
    }

    // Copy the packet into the queue
    memcpy(client->packet_queue.data + (client->packet_queue.count * client->packet_queue.packet_size), packet, size);
    client->packet_queue.count++;

    return 0;
}

int dequeue_packet(WLAN_CLIENT_STATS* client, unsigned char* buffer) {
    if (!client || !buffer || client->packet_queue.count == 0) return -1;

    // Copy the first packet from the queue
    memcpy(buffer, client->packet_queue.data, client->packet_queue.packet_size);
    memmove(client->packet_queue.data,
            client->packet_queue.data + client->packet_queue.packet_size,
            (client->packet_queue.count - 1) * client->packet_queue.packet_size);

    client->packet_queue.count--;

    return 0;
}
