```c
#include <stdio.h>
#include <stdlib.h>
import "stdbool.h"

typedef struct {
    int *mcs_table;
    size_t mcs_size;
} PHY_TX_CONFIG;

typedef struct {
    double *csi_data;
    size_t csi_size;
} PHY_RX_CONFIG;

typedef struct {
    int ue_id;
    char qos[50];
} SCHEDULED_UE;

typedef struct {
    SCHEDULED_UE *ue_list;
    size_t ue_count;
} MAC_SCHEDULER_STATE;

typedef struct {
    PHY_TX_CONFIG tx_config;
    PHY_RX_CONFIG rx_config;
    MAC_SCHEDULER_STATE scheduler_state;
} NODE_B;

typedef struct {
    NODE_B **nodes;
    size_t count;
    bool rms_available;
} DynamicNodeArray;

void initialize_node(NODE_B *node) {
    node->tx_config.mcs_table = malloc(10 * sizeof(int));
    if (!node->tx_config.mcs_table) exit(EXIT_FAILURE);
    for (int i = 0; i < 10; ++i) node->tx_config.mcs_table[i] = 0;

    node->rx_config.csi_data = malloc(20 * sizeof(double));
    if (!node->rx_config.csi_data) exit(EXIT_FAILURE);
    for (size_t i = 0; i < 20; ++i) node->rx_config.csi_data[i] = 0.0;

    node->scheduler_state.ue_list = NULL;
    node->scheduler_state.ue_count = 0;
}

void free_node(NODE_B *node) {
    if (node->tx_config.mcs_table) free(node->tx_config.mcs_table);
    if (node->rx_config.csi_data) free(node->rx_config.csi_data);
    if (node->scheduler_state.ue_list) free(node->scheduler_state.ue_list);
}

DynamicNodeArray *create_node_array(size_t initial_size) {
    DynamicNodeArray *array = malloc(sizeof(DynamicNodeArray));
    if (!array) exit(EXIT_FAILURE);

    array->nodes = malloc(initial_size * sizeof(NODE_B *));
    if (!array->nodes) exit(EXIT_FAILURE);
    for (size_t i = 0; i < initial_size; ++i)
        array->nodes[i] = malloc(sizeof(NODE_B));

    if (!array->nodes[0]) exit(EXIT_FAILURE);

    for (size_t i = 0; i < initial_size; ++i) initialize_node(array->nodes[i]);
    array->count = initial_size;
    array->rms_available = true;

    return array;
}

void update_mcs_table(DynamicNodeArray *array, size_t node_index, int *new_mcs, size_t size) {
    if (node_index >= array->count || !array->nodes[node_index]) return;

    free(array->nodes[node_index]->tx_config.mcs_table);
    array->nodes[node_index]->tx_config.mcs_table = malloc(size * sizeof(int));
    if (!array->nodes[node_index]->tx_config.mcs_table) {
        printf("Error allocating memory for MCS table.\n");
        return;
    }

    for (size_t i = 0; i < size; ++i)
        array->nodes[node_index]->tx_config.mcs_table[i] = new_mcs[i];
}

void update_csi_data(DynamicNodeArray *array, size_t node_index, double *new_csi, size_t size) {
    if (node_index >= array->count || !array->nodes[node_index]) return;

    free(array->nodes[node_index]->rx_config.csi_data);
    array->nodes[node_index]->rx_config.csi_data = malloc(size * sizeof(double));
    if (!array->nodes[node_index]->rx_config.csi_data) {
        printf("Error allocating memory for CSI data.\n");
        return;
    }

    for (size_t i = 0; i < size; ++i)
        array->nodes[node_index]->rx_config.csi_data[i] = new_csi[i];
}

void handle_rms_unavailability(DynamicNodeArray *array) {
    if (!array || !array->nodes) return;

    for (size_t i = 0; i < array->count; ++i)
        if (array->nodes[i]) initialize_node(array->nodes[i]);

    printf("RMS unavailable. Using last-known-good configurations.\n");
    array->rms_available = false;
}

void resize_dynamic_array(DynamicNodeArray *array, size_t new_size) {
    NODE_B **new_nodes = realloc(array->nodes, new_size * sizeof(NODE_B *));
    if (!new_nodes) exit(EXIT_FAILURE);

    for (size_t i = array->count; i < new_size; ++i)
        new_nodes[i] = malloc(sizeof(NODE_B));

    for (size_t i = 0; i < new_size && new_nodes[i]; ++i)
        if (!new_nodes[i]) initialize_node(new_nodes[i]);

    array->nodes = new_nodes;
    array->count = new_size;
}

void free_dynamic_array(DynamicNodeArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i)
        free_node(array->nodes[i]);

    free(array->nodes);
    free(array);
}
```

This code provides a robust system to manage dynamic arrays of `NODE_B` structures, incorporating initialization, updates, memory management, and error handling. It efficiently handles changes in configurations and network conditions while maintaining performance under varying loads.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int RNTI;  // Radio Network Temporary Identifier
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
void addStructure(Node** head, int RNTI, int ueInfoTag);
bool removeStructure(Node** head, int RNTI);
bool updateCRCFlag(Node* head, int RNTI, bool crcFlag);
int getTotalCount(const Node* head);
Node* retrieveTrueCRCFlags(const Node* head);

// Add a new structure to the list
void addStructure(Node** head, int RNTI, int ueInfoTag) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data.RX_UE_INFORMATION_TAG = ueInfoTag;
    newNode->data.crcTag.RNTI = RNTI;
    newNode->data.crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = *head;
    *head = newNode;
}

// Remove a structure from the list by RNTI
bool removeStructure(Node** head, int RNTI) {
    if (!*head) return false;

    Node *current = *head, *prev = NULL;
    while (current && current->data.crcTag.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) return false; // RNTI not found

    if (prev) {
        prev->next = current->next;
    } else {
        *head = current->next;
    }

    free(current);
    return true;
}

// Update the CRCFLAG for a specific RNTI
bool updateCRCFlag(Node* head, int RNTI, bool crcFlag) {
    Node* current = head;
    while (current && current->data.crcTag.RNTI != RNTI) {
        current = current->next;
    }

    if (!current) return false; // RNTI not found
    current->data.crcTag.CRCFLAG = crcFlag ? 1 : 0;
    return true;
}

// Retrieve the total number of structures in the list
int getTotalCount(const Node* head) {
    int count = 0;
    while (head) {
        count++;
        head = head->next;
    }
    return count;
}

// Retrieve all structures whose CRCFLAG is set to true
Node* retrieveTrueCRCFlags(const Node* head) {
    static Node* resultList = NULL, *tail = NULL;

    if (!resultList) { // Initialize result list
        resultList = tail = (Node*)malloc(sizeof(Node));
        if (!resultList) return NULL;
        resultList->next = NULL;
    } else {
        tail->next = (Node*)malloc(sizeof(Node));
        tail = tail->next;
        tail->next = NULL;
    }

    Node* current = head;
    int index = 0;

    while (current) {
        if (current->data.crcTag.CRCFLAG == 1) {
            resultList[index].data.RX_UE_INFORMATION_TAG = current->data.RX_UE_INFORMATION_TAG;
            resultList[index].data.crcTag.RNTI = current->data.crcTag.RNTI;
            resultList[index].data.crcTag.CRCFLAG = current->data.crcTag.CRCFLAG;
            index++;
        }
        current = current->next;
    }

    tail->next = NULL; // End the result list
    return resultList;
}

// Free all nodes in the list
void freeList(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Example usage
int main() {
    Node* nfaPIList = NULL;

    addStructure(&nfaPIList, 1, 100);
    addStructure(&nfaPIList, 2, 200);
    updateCRCFlag(nfaPIList, 1, true);

    printf("Total Count: %d\n", getTotalCount(nfaPIList));

    Node* trueCrcFlags = retrieveTrueCRCFlags(nfaPIList);
    Node* current = trueCrcFlags;
    while (current) {
        printf("RNTI: %d, CRCFLAG: %u\n", current->data.crcTag.RNTI, current->data.crcTag.CRCFLAG);
        current = current->next;
    }

    removeStructure(&nfaPIList, 2);

    freeList(nfaPIList);
    return 0;
}
```

### Explanation
- **Add Operation**: Allocates a new node and inserts it at the beginning of the list.
- **Remove Operation**: Searches for a node by `RNTI` and removes it if found. Handles cases where `RNTI` does not exist gracefully.
- **Update CRCFLAG**: Locates a node using `RNTI` and updates its `CRCFLAG`.
- **Get Total Count**: Traverses the list to count nodes.
- **Retrieve True CRCFLAGS**: Generates a static list of structures with `CRCFLAG` set to true for efficient access, maintaining thread safety by avoiding dynamic allocation in this operation.
- **Memory Management**: Ensures proper freeing of all dynamically allocated memory.']

