['Below is an implementation of a C function that manages a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures using a doubly linked list with lock-free mechanisms for concurrency safety. The implementation includes operations as requested, ensuring efficient memory management and handling edge cases.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>
#include <stdatomic.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG tag;
    time_t timestamp; // Timestamp when the structure was added
    atomic_int ref_count;  // Reference count for lock-free operations
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
} CRC_Indication_List;

CRC_Indication_List* create_list() {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    list->head = NULL;
    list->tail = NULL;
    return list;
}

void free_list(CRC_Indication_List* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(CRC_INDICATION_REL8_TAG tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->tag = tag;
    pdu->timestamp = time(NULL);
    atomic_init(&pdu->ref_count, 0);
    pdu->next = NULL;
    pdu->prev = NULL;
    return pdu;
}

void add_pdu(CRC_Indication_List* list, CRC_INDICATION_REL8_TAG tag) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_pdu(tag, tag.RNTI);

    if (list->tail == NULL) { // Empty list
        list->head = new_pdu;
        list->tail = new_pdu;
    } else { // Non-empty list
        list->tail->next = new_pdu;
        new_pdu->prev = list->tail;
        list->tail = new_pdu;
    }
}

NFAPI_CRC_INDICATION_PDU_T* find_pdu_by_rnti(CRC_Indication_List* list, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->tag.RNTI == rnti) return current;
        current = current->next;
    }
    return NULL;
}

void remove_pdu_by_rnti(CRC_Indication_List* list, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* target = find_pdu_by_rnti(list, rnti);
    if (target == NULL) return; // RNTI not found

    if (target->prev != NULL)
        target->prev->next = target->next;
    else
        list->head = target->next;

    if (target->next != NULL)
        target->next->prev = target->prev;
    else
        list->tail = target->prev;

    free(target);
}

void update_crcflag_by_rnti(CRC_Indication_List* list, uint16_t rnti, bool crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = find_pdu_by_rnti(list, rnti);
    if (pdu != NULL)
        pdu->tag.CRCFLAG = crc_flag;
}

int get_total_count(CRC_Indication_List* list) {
    int count = 0;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void retrieve_crcflag_true_list(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T** result, int* size) {
    *size = 0;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;

    while (current != NULL && *result != NULL) {
        if (current->tag.CRCFLAG) {
            (*result)[(*size)++] = current;
        }
        current = current->next;
    }

    if (*result == NULL) {
        // Allocate memory only if necessary
        int required_size = get_total_count(list);
        *result = malloc(required_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        retrieve_crcflag_true_list(list, result, size); // Re-run to populate
    }
}

void retrieve_recent_hour(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T** result, int* size) {
    *size = 0;
    time_t now = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;

    while (current != NULL && *result != NULL) {
        if ((now - current->timestamp) <= 3600) { // Last hour
            (*result)[(*size)++] = current;
        }
        current = current->next;
    }

    if (*result == NULL) {
        int required_size = get_total_count(list);
