import java.io.*;

public class CommandExecutor {

    public static void executeCommand(String command, String workingDirPath) {
        File dir = new File(workingDirPath);

        // Delete file if it exists
        File fileToDelete = new File(dir, "file.txt");
        if (fileToDelete.exists()) {
            if (!fileToDelete.delete()) {
                System.err.println("Failed to delete the existing file.");
                return;
            }
        }

        try {
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.directory(dir);
            Process process = processBuilder.start();

            // Read output stream
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("OUTPUT: " + line);
            }

            // Read error stream
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                System.err.println("ERROR: " + line);
            }

            int exitCode = process.waitFor();
            if (exitCode == 0) {
                System.out.println("Command executed successfully.");
            } else {
                System.err.println("Command execution failed with exit code " + exitCode);
            }

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        executeCommand("echo Hello, World!", "/path/to/working/directory");
    }
}
