    for (int i = 0; i < NUM_THREADS; ++i) {
        if(pthread_create(&threads[i], NULL, handle_burst, NULL) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Ensure we wait for threads to finish before cleanup in case of shutdown
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void shutdown_manager() {
    pthread_mutex_lock(&manager.mutex);
    manager.shutdown = 1;
    pthread_cond_broadcast(&manager.cond);
    pthread_mutex_unlock(&manager.mutex);

    // Ensure all threads are joined
    pthread_mutex_destroy(&manager.mutex);
    pthread_cond_destroy(&manager.cond);
}

void add_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&manager.mutex);

    while (manager.count == MAX_STRUCTURES && !manager.shutdown) {
        log_status("Buffer full, waiting for space...");
        pthread_cond_wait(&manager.cond, &manager.mutex);
    }

    if (!manager.shutdown) {
        manager.structures[manager.count++] = structure;
        pthread_cond_broadcast(&manager.cond);
    } else {
        free(structure); // Handle gracefully shutdown scenario
    }

    pthread_mutex_unlock(&manager.mutex);
}

static void* handle_burst(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* buffer[MAX_STRUCTURES];
        size_t filled = 0;

        pthread_mutex_lock(&manager.mutex);

        while (filled < MAX_STRUCTURES && manager.count > 0 && !manager.shutdown) {
            buffer[filled++] = manager.structures[--manager.count];
        }

        if (!manager.shutdown) {
            // Process the batch of structures
            for (size_t i = 0; i < filled; ++i) {
                // Process each structure here...
                free(buffer[i]); // Freeing after processing
            }
        } else {
            while (filled > 0) {
                free(buffer[--filled]);
            }
        }

        pthread_mutex_unlock(&manager.mutex);

        if (manager.shutdown && filled == 0) break;

        // Simulate some delay to prevent tight looping
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 1000000 };
        nanosleep(&ts, NULL);
    }
    return NULL;
}

static void log_status(const char* message) {
