typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFALIST;

void init_list(NFALIST *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int resize_if_needed(NFALIST *list) {
    if (list->size >= list->capacity && list->capacity < MAX_CAPACITY) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) return -1; // Memory allocation failed

        list->data = new_data;
        list->capacity = new_capacity;

        return 0; // Success
    }
    return 0;
}

int add_element(NFALIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (resize_if_needed(list) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Failed to resize
    }

    list->data[list->size++] = element;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int remove_element(NFALIST *list, size_t index) {
    if (index >= list->size) return -1;

    pthread_mutex_lock(&list->lock);

    memmove(&list->data[index], &list->data[index + 1],
            (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int update_element(NFALIST *list, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    if (index >= list->size) return -1;

    pthread_mutex_lock(&list->lock);

    list->data[index] = element;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void free_list(NFALIST *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

