        pthread_mutex_unlock(&list->lock);
        return false;
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Resize the list if needed
static bool resizeIfNeeded(DynamicList* list) {
    if (list->size < list->capacity && list->capacity <= MAX_CAPACITY) {
        return true;
