NFAPI_CRC_INDICATION_PDU_T* create_list(int n);
void sort_list(NFAPI_CRC_INDICATION_PDU_T** head);
void export_to_binary(const char* filename, const NFAPI_CRC_INDICATION_PDU_T* head);
void free_list(NFAPI_CRC_INDICATION_PDU_T* head);
int validate_data(RX_UE_INFORMATION_TAG* tag);

// Main function to create and manage the linked list
NFAPI_CRC_INDICATION_PDU_T* create_and_manage_list(int n) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = create_list(n);

    // Validate and sort the list
    if (head) {
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current) {
            if (!validate_data(&current->rxUeInfoTag)) {
                fprintf(stderr, "Invalid data detected.\n");
                free_list(head);
                return NULL;
            }
            current = current->next;
        }
        sort_list(&head);
    }

    // Export to binary format
    export_to_binary("output.bin", head);

    return head;
}

// Function implementations

NFAPI_CRC_INDICATION_PDU_T* create_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL, *tail = NULL;

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed.\n");
            free_list(head);
            return NULL;
        }

        // Populate the node with random data
        new_node->rxUeInfoTag.RNTI = rand() % 10000; // Example RNTI value
        new_node->crcIndicationRel8Tag.CRCFLAG = rand() % 2;

        new_node->next = NULL;
        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}

void sort_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    if (!head || !*head) return;

    NFAPI_CRC_INDICATION_PDU_T *sorted = NULL, *current = *head, *next_node = NULL;

    while (current) {
        next_node = current->next;
        sorted_insert(&sorted, current);
        current = next_node;
    }

    *head = sorted;
}

void sorted_insert(NFAPI_CRC_INDICATION_PDU_T** head_ref, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    if (!(*head_ref) || (*head_ref)->rxUeInfoTag.RNTI >= new_node->rxUeInfoTag.RNTI) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head_ref;
        while (current->next && current->next->rxUeInfoTag.RNTI < new_node->rxUeInfoTag.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void export_to_binary(const char* filename, const NFAPI_CRC_INDICATION_PDU_T* head) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    const NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        fwrite(&current->rxUeInfoTag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->crcIndicationRel8Tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        current = current->next;
    }

    fclose(file);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        free(temp);
    }
}

int validate_data(RX_UE_INFORMATION_TAG* tag) {
    // Implement validation logic here
    return tag && tag->RNTI > 0; // Example validation: RNTI must be positive
}
