#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 65535
#define MIN_RNTI 1

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;

void* generate_crc_array(void* arg) {
    int n = *(int*)arg;
    if (n < 1 || n > 10000) {
        fprintf(stderr, "Invalid input range for N\n");
        return NULL;
    }

    srand(time(NULL));

    pthread_mutex_lock(&mutex);

    Node** temp_head = &head;

    for (int i = 0; i < n; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            while (*temp_head != NULL) { // Cleanup
                Node* temp = *temp_head;
                *temp_head = (*temp_head)->next;
                free(temp);
            }
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->data.RNTI = (rand() % MAX_RNTI) + MIN_RNTI;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256;
        new_node->data.CRCFLAG = rand() % 2;

        // Insert in sorted order
        Node* current = *temp_head;
        while (current && current->data.RNTI < new_node->data.RNTI) {
            temp_head = &(current->next);
            current = current->next;
        }
        new_node->next = current;
        *temp_head = new_node;

        // Move head forward
        if (*head == new_node)
            head = new_node;
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

void free_list() {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int n = atoi(argv[1]);

    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, generate_crc_array, &n)) {
        fprintf(stderr, "Error creating thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    // Optional: Print the list for verification
    Node* current = head;
    while (current) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %d\n",
               current->data.RNTI,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG);
        current = current->next;
    }

    free_list();

    return EXIT_SUCCESS;
}
```

### Key Considerations:
1. **Thread Safety:** A mutex (`pthread_mutex_t`) is used to ensure that concurrent threads do not lead to race conditions when accessing/modifying the linked list.
2. **Memory Management:** Efficient memory allocation for nodes, with error handling for allocation failures and cleanup in case of errors during processing.
3. **Dynamic List Growth:** The linked list allows dynamic growth without pre-allocation, minimizing memory fragmentation.
4. **Sorting on Insertion:** Each new element is inserted into the sorted position to maintain a sorted linked list by `RNTI`.
5. **Graceful Degradation:** In case of allocation failure, cleanup occurs to prevent resource leakage.
6. **Scalability and Performance:** The use of a mutex can be optimized further if contention becomes an issue, potentially using read-write locks or other more advanced synchronization techniques for performance improvements under high concurrency.

This example is intended as a starting point; real-world applications might require additional features like handling external data updates, error management, or optimizations based on specific requirements.']

