// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RRC_MEASUREMENTS_PDU_T* initialize_measurements_array(size_t num_entries) {
    NFAPI_RRC_MEASUREMENTS_PDU_T *array = (NFAPI_RRC_MEASUREMENTS_PDU_T *)malloc(num_entries * sizeof(NFAPI_RRC_MEASUREMENTS_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for measurements array");
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        array[i].UE_ID = rand(); // Assign a unique UE_ID
        array[i].count = 0;
        array[i].measurements = NULL;
    }

    return array;
}

int add_measurement(NFAPI_RRC_MEASUREMENTS_PDU_T *entry, int cell_id, float rsrp) {
    pthread_mutex_lock(&mutex);

    entry->measurements = realloc(entry->measurements, (entry->count + 1) * sizeof(struct { int CELL_ID; float RSRP; }));
    if (!entry->measurements) {
        perror("Failed to reallocate memory for measurements");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    entry->measurements[entry->count].CELL_ID = cell_id;
    entry->measurements[entry->count].RSRP = rsrp;
    ++entry->count;

    // Sort by CELL_ID
    qsort(entry->measurements, entry->count, sizeof(struct { int CELL_ID; float RSRP; }), [](const void *a, const void *b) {
        return ((struct { int CELL_ID; float RSRP; } *)a)->CELL_ID - ((struct { int CELL_ID; float RSRP; } *)b)->CELL_ID;
    });

    pthread_mutex_unlock(&mutex);
    return 0;
}

void free_measurements_array(NFAPI_RRC_MEASUREMENTS_PDU_T *array, size_t num_entries) {
    if (!array) return;

    for (size_t i = 0; i < num_entries; ++i) {
        free(array[i].measurements);
    }

    free(array);
}

int main() {
    // Example usage
    size_t num_UEs = 10;
    NFAPI_RRC_MEASUREMENTS_PDU_T *array = initialize_measurements_array(num_UEs);

    if (array) {
        add_measurement(&array[0], 3, -95.5);
        add_measurement(&array[0], 1, -90.2);
        add_measurement(&array[0], 2, -92.7);

        // Output measurements for UE with index 0
        printf("UE_ID: %d\n", array[0].UE_ID);
        for (size_t i = 0; i < array[0].count; ++i) {
            printf("CELL_ID: %d, RSRP: %.1f\n", array[0].measurements[i].CELL_ID, array[0].measurements[i].RSRP);
        }

        free_measurements_array(array, num_UEs);
    }

    return 0;
}
