#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024
#define OVERFLOW_FACTOR 2

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** cacheArray;
    size_t capacity;
    pthread_mutex_t lock;
    int count;
    Node* overflowList;
} DistributedCache;

DistributedCache* create_cache(size_t initialCapacity) {
    DistributedCache* cache = (DistributedCache*)malloc(sizeof(DistributedCache));
    if (!cache) return NULL;

    cache->capacity = initialCapacity;
    cache->count = 0;
    cache->cacheArray = (Node**)calloc(initialCapacity, sizeof(Node*));
    if (!cache->cacheArray) {
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->lock, NULL);
    cache->overflowList = NULL;

    srand(time(NULL)); // Initialize random seed
    return cache;
}

void free_cache(DistributedCache* cache) {
    if (!cache) return;

    for (size_t i = 0; i < cache->capacity; ++i) {
        Node* node = cache->cacheArray[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    while (cache->overflowList) {
        Node* temp = cache->overflowList;
        cache->overflowList = cache->overflowList->next;
        free(temp);
    }

    pthread_mutex_destroy(&cache->lock);
    free(cache->cacheArray);
    free(cache);
}

int is_rnti_unique(DistributedCache* cache, unsigned int rnti) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        Node* node = cache->cacheArray[i];
        while (node) {
            if (node->data.RNTI == rnti)
                return 0;
            node = node->next;
        }
    }

    Node* current = cache->overflowList;
    while (current) {
        if (current->data.RNTI == rnti)
            return 0;
        current = current->next;
    }

    return 1;
}

void insert_into_cache(DistributedCache* cache, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&cache->lock);

    if (!is_rnti_unique(cache, pdu.RNTI)) {
        printf("RNTI already exists. Skipping insertion.\n");
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    size_t index = pdu.RNTI % cache->capacity;
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&cache->lock);
        return;
    }
    newNode->data = pdu;

    newNode->next = cache->cacheArray[index];
    cache->cacheArray[index] = newNode;
    ++(cache->count);

    if (cache->count > MAX_CACHE_SIZE) {
        // Move excess to overflow
        while (cache->count > MAX_CACHE_SIZE && cache->overflowList) {
            Node* oldNode = cache->overflowList;
            cache->overflowList = cache->overflowList->next;

            size_t index = oldNode->data.RNTI % cache->capacity;
            oldNode->next = cache->cacheArray[index];
            cache->cacheArray[index] = oldNode;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void log_cache_performance(DistributedCache* cache) {
    printf("Current Cache Size: %zu\n", cache->count);
    // Additional logging can be added here
}

int main() {
    DistributedCache* cache = create_cache(MAX_CACHE_SIZE);
    if (!cache) {
        printf("Failed to initialize cache.\n");
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < MAX_CACHE_SIZE * OVERFLOW_FACTOR; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = rand() % 10000 };
        pdu.crcTag.CRCFLAG = rand() % 2;

        insert_into_cache(cache, pdu);
    }

    log_cache_performance(cache);

    free_cache(cache);
    return EXIT_SUCCESS;
}
```

This code sets up a distributed cache with thread-safe operations using mutexes. It includes mechanisms for dynamic memory allocation and overflow handling when the primary cache reaches its capacity. Each `RNTI` is ensured to be unique across both main and overflow lists, with error checks for memory allocation failures. The example also demonstrates basic logging of cache performance metrics.']

