#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Assume these are predefined structures based on your description.
typedef struct {
    unsigned int CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned int RNTI;
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned int MAC_PDU_TAG;
    char *payloadBuffer;
    size_t payloadSize;
} MAC_RX_DATA_PDU_T;

typedef struct {
    unsigned int L2_RX_FRAME_INFO_TAG;
    MAC_RX_DATA_PDU_T *macRxDataPdu;
    NFAPI_CRC_INDICATION_PDU_T *crcIndicationList;
    size_t crcIndicationCount;
} NFAPI_L2_RX_FRAME_PDU_T;

#define MAX_FRAMES 100

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate random number in range
int randomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}

NFAPI_L2_RX_FRAME_PDU_T* initializeFrames(size_t frameCount) {
    NFAPI_L2_RX_FRAME_PDU_T *frames = NULL;

    if (frameCount > MAX_FRAMES || frameCount == 0) return NULL;

    frames = malloc(frameCount * sizeof(NFAPI_L2_RX_FRAME_PDU_T));
    if (!frames) return NULL;

    for (size_t i = 0; i < frameCount; ++i) {
        pthread_mutex_lock(&lock);

        // Initialize L2 RX Frame Info Tag
        frames[i].L2_RX_FRAME_INFO_TAG = randomInRange(1, 1000); 

        // Allocate and initialize MAC_RX_DATA_PDU_T
        frames[i].macRxDataPdu = malloc(sizeof(MAC_RX_DATA_PDU_T));
        if (!frames[i].macRxDataPdu) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        frames[i].macRxDataPdu->MAC_PDU_TAG = randomInRange(1, 1000); 
        size_t payloadSize = randomInRange(64, 1024); // Example sizes
        frames[i].macRxDataPdu->payloadBuffer = malloc(payloadSize);
        if (!frames[i].macRxDataPdu->payloadBuffer) {
            free(frames[i].macRxDataPdu);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        frames[i].macRxDataPdu->payloadSize = payloadSize;

        // Initialize CRC Indication List
        size_t crcCount = randomInRange(1, 5); 
        frames[i].crcIndicationList = malloc(crcCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!frames[i].crcIndicationList) {
            free(frames[i].macRxDataPdu->payloadBuffer);
            free(frames[i].macRxDataPdu);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        frames[i].crcIndicationCount = crcCount;

        for (size_t j = 0; j < crcCount; ++j) {
            frames[i].crcIndicationList[j].RNTI = randomInRange(1, 1000); 
            // Assume RX_UE_INFORMATION_TAG and other fields are initialized here
            frames[i].crcIndicationList[j].ue_info.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
            frames[i].crcIndicationList[j].crcIndicationRel8Tag = randomInRange(1, 1000); 
        }

        pthread_mutex_unlock(&lock);
    }

    return frames;
}

void freeFrames(NFAPI_L2_RX_FRAME_PDU_T *frames, size_t frameCount) {
    if (!frames) return;

    for (size_t i = 0; i < frameCount; ++i) {
        if (frames[i].macRxDataPdu) {
            free(frames[i].macRxDataPdu->payloadBuffer);
            free(frames[i].macRxDataPdu);
        }

        if (frames[i].crcIndicationList) {
            free(frames[i].crcIndicationList);
        }
    }

    free(frames);
}

int main() {
    srand(time(NULL));

    size_t frameCount = 10; // Example frame count
    NFAPI_L2_RX_FRAME_PDU_T *frames = initializeFrames(frameCount);

    if (!frames) {
        fprintf(stderr, "Failed to initialize frames.\n");
        return EXIT_FAILURE;
    }

    // Use the frames...

    freeFrames(frames, frameCount);
    return EXIT_SUCCESS;
}
```

### Key Points:
