- **Error Handling**: Checks for allocation failures and exits gracefully if any occur.
- **Random Initialization**: Randomizes values within specified ranges to simulate realistic data.
- **Scalability & Performance**: Limits the maximum number of frames (`MAX_FRAMES`) to avoid excessive resource usage.']

['Below is a multi-threaded C implementation of a dynamic array for managing UE context information. This code uses mutexes and condition variables for thread-safe operations and includes periodic cleanup to optimize memory usage.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    char serving_plmn[3]; // E.g., "001" for PLMN ID
    double *downlink_traffic_indicators; // Dynamic array of indicators
    size_t traffic_count;
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    unsigned int cleanup_interval_ms;
    time_t last_cleanup;
} UECtxManager;

// Initialize context manager
void init_ctx_manager(UECtxManager *manager, size_t initial_capacity, unsigned int cleanup_interval) {
    manager->contexts = malloc(initial_capacity * sizeof(UEContext *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->cleanup_interval_ms = cleanup_interval;
    manager->last_cleanup = time(NULL);
}

// Resize array if needed
static void ensure_capacity(UECtxManager *manager) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEContext **new_contexts = realloc(manager->contexts, new_capacity * sizeof(UEContext *));
        if (new_contexts) {
            manager->contexts = new_contexts;
            manager->capacity = new_capacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Insert or update UE context
void insert_ue_context(UECtxManager *manager, int ue_id, const char *serving_plmn, double *traffic_indicators, size_t traffic_count) {
    pthread_mutex_lock(&manager->lock);

    // Check if the UE already exists and update it
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            strncpy(manager->contexts[i]->serving_plmn, serving_plmn, sizeof(manager->contexts[i]->serving_plmn));
            free(manager->contexts[i]->downlink_traffic_indicators);
            manager->contexts[i]->traffic_count = traffic_count;
            manager->contexts[i]->downlink_traffic_indicators = malloc(traffic_count * sizeof(double));
            memcpy(manager->contexts[i]->downlink_traffic_indicators, traffic_indicators, traffic_count * sizeof(double));
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Create a new UE context
    ensure_capacity(manager);
    UEContext *context = malloc(sizeof(UEContext));
    context->ue_id = ue_id;
    strncpy(context->serving_plmn, serving_plmn, sizeof(context->serving_plmn));
    context->traffic_count = traffic_count;
    context->downlink_traffic_indicators = malloc(traffic_count * sizeof(double));
    memcpy(context->downlink_traffic_indicators, traffic_indicators, traffic_count * sizeof(double));

    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->lock);
}

// Delete UE context
void delete_ue_context(UECtxManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            free(manager->contexts[i]->downlink_traffic_indicators);
            free(manager->contexts[i]);
            memmove(&manager->contexts[i], &manager->contexts[i + 1], (manager->count - i - 1) * sizeof(UEContext *));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve UE context
UEContext* get_ue_context(const UECtxManager *manager, int ue_id) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            UEContext* context = malloc(sizeof(UEContext));
            *context = *(manager->contexts[i]);
            pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return NULL;
}

// Periodic cleanup
void* periodic_cleanup(void *arg) {
    UECtxManager *manager = (UECtxManager *)arg;

    while (1) {
        sleep(manager->cleanup_interval_ms / 1000);

        pthread_mutex_lock(&manager->lock);
        time_t now = time(NULL);
        if ((now - manager->last_cleanup) >= manager->cleanup_interval_ms / 1000) {
            // Implement cleanup logic here
            manager->last_cleanup = now;
        }
        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

// Destroy context manager
void destroy_ctx_manager(UECtxManager *manager, pthread_t cleanup_thread) {
    pthread_cancel(cleanup_thread);
    pthread_join(cleanup_thread, NULL);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->downlink_traffic_indicators);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
}

// Usage example
int main() {
    UECtxManager ctx_manager;
    init_ctx_manager(&ctx_manager, 10, 5000); // Initial capacity of 10 and cleanup every 5 seconds

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, &ctx_manager) != 0) {
        fprintf(stderr, "Failed to create cleanup thread\n");
        destroy_ctx_manager(&ctx_manager, cleanup_thread);
        return EXIT_FAILURE;
    }

    // Example operations
    double traffic[5] = {1.2, 3.4, 5.6, 7.8, 9.0};
    insert_ue_context(&ctx_manager, 12345, "001", traffic, 5);

    UEContext *context = get_ue_context(&ctx_manager, 12345);
    if (context) {
        // Use context
        free(context->downlink_traffic_indicators);
        free(context);
    }

    delete_ue_context(&ctx_manager, 12345);

    destroy_ctx_manager(&ctx_manager, cleanup_thread);

    return 0;
}
```

This code provides a thread-safe dynamic array to manage UE contexts with periodic cleanup. It uses mutexes for synchronization and supports efficient insertion, deletion, and retrieval operations based on UE ID. The `periodic_cleanup` function is designed to run in a separate thread to handle memory optimization without blocking the main execution flow.']

['Below is a C function that dynamically allocates memory for an array of `NFAPI_CRC_INDICATION_PDU_T` structures based on user input. The implementation considers error handling, logging, and efficient memory management.

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include "third_party_memory_api.h" // Assuming this header defines required third-party API functions.
#include "logging_framework.h"      // Assuming this header provides the necessary logging macros/functions.
#include <time.h>                   // For generating random CRCFLAG values.

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
