#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic List Structure with mutex for concurrency control
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

// Initialize a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Initialize the CRCList
CRCList* initialize_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new element to the list
void add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = create_node(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

// Remove an element based on RNTI
void remove_element(CRCList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

// Update CRCFLAG for a specific RNTI
void update_crcflag(CRCList* list, unsigned long rnti, int crcflag) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (current != NULL) {
        current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
    }

    pthread_mutex_unlock(&list->lock);
}

// Periodic update from external data source
void* periodic_update(void* args) {
    CRCList* list = (CRCList*)args;

    while (1) {
        // Simulate fetching new data periodically
        sleep(5); // Adjust as necessary for real-time constraints

        pthread_mutex_lock(&list->lock);

        Node *current = list->head;
        while (current != NULL) {
            // Update logic here, e.g., refresh CRCFLAG or other fields
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG ^= 1; // Example toggle for demonstration
            current = current->next;
        }

        pthread_mutex_unlock(&list->lock);
    }
}

// Cleanup the list and free resources
void cleanup_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    CRCList* list = initialize_list();

    // Simulate adding elements
    for (unsigned long rnti = 1; rnti <= 10; ++rnti) {
        NFAPI_CRC_INDICATION_PDU_T data = {1, rnti, {.CRCFLAG = rand() % 2}};
        add_element(list, data);
    }

    // Start periodic update thread
    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, periodic_update, list) != 0) {
        fprintf(stderr, "Failed to create update thread\n");
        cleanup_list(list);
        return EXIT_FAILURE;
    }

    // Simulate operations
    sleep(10); // Allow some time for updates

    remove_element(list, 5);
    update_crcflag(list, 3, 1);

    // Cleanup before exit
    pthread_cancel(update_thread);
    pthread_join(update_thread, NULL);
    cleanup_list(list);

    return EXIT_SUCCESS;
}
