['```c
#include <stdio.h>
#include <stdlib.h>
#include <yaml.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Structures for session management
typedef struct {
    char *sid;
    char *metadata;
} Session;

typedef struct {
    int max_sessions;
    int current_sessions;
    pthread_mutex_t lock;
    Session **sessions;
} SessionManager;

// Configuration structure from YAML file
typedef struct {
    int initial_max_sessions;
    char *auth_server_url;
} Config;

// Function prototypes
void initialize_session_manager(SessionManager *manager, const Config *config);
void activate_session(SessionManager *manager, const char *sid, const char *metadata);
void cleanup_session(SessionManager *manager, const char *sid);
void load_config(const char *file_path, Config *config);
void log_message(const char *message);

// YAML parsing and error handling
void handle_yaml_error(yaml_parser_t *parser) {
    if (!yaml_parser_get_error(parser)) return;
    fprintf(stderr, "YAML Error: %s\n", parser->error.message);
}

void load_config(const char *file_path, Config *config) {
    FILE *file = fopen(file_path, "rb");
    yaml_parser_t parser;

    yaml_parser_initialize(&parser);
    if (!yaml_parser_set_input_file(&parser, file)) {
        log_message("Failed to set input file for YAML parser.");
        return;
    }

    yaml_event_t event;
    while (1) {
        if (!yaml_parser_parse(&parser, &event))
            handle_yaml_error(&parser);

        switch (event.type) {
            case YAML_MAPPING_START_EVENT:
                break;

            case YAML_SEQUENCE_START_EVENT:
                break;

            case YAML_SCALAR_EVENT:
                if (strcmp(event.data.scalar.value, "initial_max_sessions") == 0) {
                    yaml_parser_parse(&parser, &event);
                    config->initial_max_sessions = atoi(event.data.scalar.value);
                } else if (strcmp(event.data.scalar.value, "auth_server_url") == 0) {
                    yaml_parser_parse(&parser, &event);
                    config->auth_server_url = strdup(event.data.scalar.value);
                }
                break;

            case YAML_MAPPING_END_EVENT:
                goto done;
        }

        yaml_event_delete(&event);
    }

done:
    yaml_event_delete(&event);
    yaml_parser_delete(&parser);
    fclose(file);
}

// Initialize session manager
void initialize_session_manager(SessionManager *manager, const Config *config) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_sessions = config->initial_max_sessions;
    manager->current_sessions = 0;
    manager->sessions = malloc(sizeof(Session*) * manager->max_sessions);

    for (int i = 0; i < manager->max_sessions; ++i) {
        manager->sessions[i] = NULL;
    }
}

// Activate session
void activate_session(SessionManager *manager, const char *sid, const char *metadata) {
    pthread_mutex_lock(&manager->lock);
    if (manager->current_sessions >= manager->max_sessions) {
        log_message("Max sessions reached. Scaling up...");
        int new_max = manager->max_sessions * 2;
        Session **new_sessions = realloc(manager->sessions, sizeof(Session*) * new_max);

        for (int i = manager->max_sessions; i < new_max; ++i)
            new_sessions[i] = NULL;

        if (!new_sessions) {
            log_message("Memory allocation failed during scaling.");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->sessions = new_sessions;
        manager->max_sessions = new_max;
    }

    for (int i = 0; i < manager->max_sessions; ++i) {
        if (!manager->sessions[i]) {
            manager->sessions[i] = malloc(sizeof(Session));
            manager->sessions[i]->sid = strdup(sid);
            manager->sessions[i]->metadata = strdup(metadata);
            manager->current_sessions++;
            log_message("Session activated.");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Cleanup session
void cleanup_session(SessionManager *manager, const char *sid) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->max_sessions; ++i) {
        if (manager->sessions[i] && strcmp(manager->sessions[i]->sid, sid) == 0) {
            free(manager->sessions[i]->sid);
            free(manager->sessions[i]->metadata);
            free(manager->sessions[i]);
            manager->sessions[i] = NULL;
            manager->current_sessions--;
            log_message("Session cleaned up.");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

// Main function demonstrating usage
int main() {
    Config config;
    SessionManager manager;

    load_config("config.yaml", &config);
    initialize_session_manager(&manager, &config);

    activate_session(&manager, "session1", "metadata1");
    activate_session(&manager, "session2", "metadata2");

    cleanup_session(&manager, "session1");

    // Cleanup resources
    for (int i = 0; i < manager.max_sessions; ++i) {
        if (manager.sessions[i]) {
            free(manager.sessions[i]->sid);
            free(manager.sessions[i]->metadata);
            free(manager.sessions[i]);
        }
    }

    free(manager.sessions);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
