#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 100

typedef struct {
    int flowID;
    char sourceAddress[50];
    char destinationAddress[50];
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TrafficFlowManager;

TrafficFlowManager* initTrafficFlowManager() {
    TrafficFlowManager *manager = malloc(sizeof(TrafficFlowManager));
    manager->flows = malloc(INITIAL_CAPACITY * sizeof(TrafficFlow));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void freeTrafficFlowManager(TrafficFlowManager *manager) {
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int isDuplicate(TrafficFlowManager *manager, const char *sourceAddress, const char *destinationAddress) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].sourceAddress, sourceAddress) == 0 &&
            strcmp(manager->flows[i].destinationAddress, destinationAddress) == 0) {
            return 1;
        }
    }
    return 0;
}

void resizeIfNeeded(TrafficFlowManager *manager) {
    if (manager->count >= manager->capacity) {
        if (manager->capacity < MAX_CAPACITY) {
            size_t newCapacity = manager->capacity * 2;
            if (newCapacity > MAX_CAPACITY) newCapacity = MAX_CAPACITY;

            TrafficFlow *newFlows = realloc(manager->flows, newCapacity * sizeof(TrafficFlow));
            if (newFlows) {
                manager->flows = newFlows;
                manager->capacity = newCapacity;
            } else {
                fprintf(stderr, "Error: Unable to resize array\n");
                exit(EXIT_FAILURE);
            }
        } else {
            fprintf(stderr, "Error: Maximum capacity reached\n");
            exit(EXIT_FAILURE);
        }
    }
}

int addTrafficFlow(TrafficFlowManager *manager, int flowID, const char *sourceAddress, const char *destinationAddress) {
    pthread_mutex_lock(&manager->lock);

    if (isDuplicate(manager, sourceAddress, destinationAddress)) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Duplicate entry
    }

    resizeIfNeeded(manager);

    TrafficFlow newFlow;
    newFlow.flowID = flowID;
    strncpy(newFlow.sourceAddress, sourceAddress, sizeof(newFlow.sourceAddress) - 1);
    strncpy(newFlow.destinationAddress, destinationAddress, sizeof(newFlow.destinationAddress) - 1);

    manager->flows[manager->count++] = newFlow;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

size_t getActiveFlowsCount(TrafficFlowManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void filterTrafficFlows(const TrafficFlowManager *manager, const char *sourcePattern, const char *destinationPattern, TrafficFlow **result, size_t *resultCount) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    size_t maxMatches = manager->count;
    *result = malloc(maxMatches * sizeof(TrafficFlow));
    if (!*result) {
        fprintf(stderr, "Error: Unable to allocate memory for results\n");
        pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
        exit(EXIT_FAILURE);
    }

    size_t matchCount = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if ((sourcePattern == NULL || strstr(manager->flows[i].sourceAddress, sourcePattern)) &&
            (destinationPattern == NULL || strstr(manager->flows[i].destinationAddress, destinationPattern))) {
            (*result)[matchCount++] = manager->flows[i];
        }
    }

    *resultCount = matchCount;
    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
}

// Unit tests and integration tests should be written separately
