    int TX_POWER_LEVEL;
} TX_POWER_REPORT_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    TX_POWER_REPORT_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} PowerReportArray;

PowerReportArray* power_report_array_create() {
    PowerReportArray *arr = (PowerReportArray *)malloc(sizeof(PowerReportArray));
    arr->capacity = INITIAL_CAPACITY;
    arr->used = 0;
    arr->array = (TX_POWER_REPORT_PDU_T *)malloc(arr->capacity * sizeof(TX_POWER_REPORT_PDU_T));
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void power_report_array_resize(PowerReportArray *arr) {
    size_t new_capacity = arr->capacity * 2;
    TX_POWER_REPORT_PDU_T *new_array = (TX_POWER_REPORT_PDU_T *)realloc(arr->array, new_capacity * sizeof(TX_POWER_REPORT_PDU_T));
    if (new_array) {
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
}

void power_report_array_add(PowerReportArray *arr, int id, int level) {
    pthread_mutex_lock(&arr->lock);
    if (arr->used == arr->capacity) {
        power_report_array_resize(arr);
    }
    arr->array[arr->used].TX_POWER_ID = id;
    arr->array[arr->used].TX_POWER_LEVEL = level;
    printf("Added TX_POWER_REPORT_PDU_T: ID=%d, Level=%d\n", id, level); // Log modification
    arr->used++;
    pthread_mutex_unlock(&arr->lock);
}

void power_report_array_free(PowerReportArray *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->array);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

void simulate_network_environment(PowerReportArray *arr, int start_id, int num_reports) {
    for (int i = 0; i < num_reports; ++i) {
        int simulated_level = rand() % 100; // Simulate power level
        power_report_array_add(arr, start_id + i, simulated_level);
    }
}

void *thread_func(void *arg) {
    PowerReportArray *arr = (PowerReportArray *)arg;
    simulate_network_environment(arr, 0, 50); // Each thread simulates adding 50 reports
    return NULL;
}

int main() {
    const int num_threads = 4;
    pthread_t threads[num_threads];
    PowerReportArray *report_array = power_report_array_create();

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, report_array)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    power_report_array_free(report_array);

    return 0;
}
