#include <arpa/inet.h>  // For inet_pton

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NetworkInterfaceConfig {
    char IPAddress[INET6_ADDRSTRLEN];
    int PortNumber;
    int ConnectionStatus;
    size_t numPDU;
    NFAPI_CRC_INDICATION_PDU_T* PDUs;
    pthread_mutex_t lock;
} NetworkInterfaceConfig;

int isValidIPAddress(const char *ip) {
    struct sockaddr_in sa4;
    struct sockaddr_in6 sa6;

    if (inet_pton(AF_INET, ip, &(sa4.sin_addr)) == 1) return 1;
    if (inet_pton(AF_INET6, ip, &(sa6.sin6_addr)) == 1) return 1;

    return 0;
}

void initializeConfig(NetworkInterfaceConfig* config, const char* ipAddress, int portNumber, int connectionStatus) {
    strncpy(config->IPAddress, ipAddress, INET6_ADDRSTRLEN);
    config->PortNumber = portNumber;
    config->ConnectionStatus = connectionStatus;
    config->numPDU = 0;
    config->PDUs = NULL;
    pthread_mutex_init(&config->lock, NULL);
}

void addOrUpdateInterface(NetworkInterfaceConfig** interfaces, size_t* numInterfaces, const char* ipAddress, int portNumber) {
    if (!isValidIPAddress(ipAddress)) return;

    pthread_mutex_lock((*interfaces)[0].lock);  // Lock the entire array for thread safety

    for (size_t i = 0; i < *numInterfaces; ++i) {
        if (strcmp((*interfaces)[i].IPAddress, ipAddress) == 0) {
            (*interfaces)[i].PortNumber = portNumber;
            pthread_mutex_unlock((*interfaces)[0].lock);
            return;
        }
    }

    NetworkInterfaceConfig* newInterfaces = realloc(*interfaces, sizeof(NetworkInterfaceConfig) * (*numInterfaces + 1));
    if (!newInterfaces) {
        pthread_mutex_unlock((*interfaces)[0].lock);
        return; // Handle memory allocation failure
    }

    *interfaces = newInterfaces;
    initializeConfig(&((*interfaces)[*numInterfaces]), ipAddress, portNumber, 0);

    pthread_mutex_unlock((*interfaces)[0].lock);
}

void addPDU(NetworkInterfaceConfig* config, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    pthread_mutex_lock(config->lock);

    size_t newNumPDU = config->numPDU + 1;
    NFAPI_CRC_INDICATION_PDU_T* newPDUs = realloc(config->PDUs, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newNumPDU);
    if (!newPDUs) {
        pthread_mutex_unlock(config->lock);
        return; // Handle memory allocation failure
    }

    config->PDUs = newPDUs;
    NFAPI_CRC_INDICATION_PDU_T* pdu = &config->PDUs[newNumPDU - 1];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    config->numPDU = newNumPDU;

    pthread_mutex_unlock(config->lock);
}

void cleanUp(NetworkInterfaceConfig** interfaces, size_t numInterfaces) {
    for (size_t i = 0; i < numInterfaces; ++i) {
        pthread_mutex_destroy(&((*interfaces)[i]).lock);
        free((*interfaces)[i].PDUs);
    }
    free(*interfaces);
}
