#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures as per requirements

typedef struct {
    unsigned long ACK_ID;
    unsigned long RECEIVER_ID;
    int isPending; // 1 if pending, 0 if acknowledged
} ACK_RECORD;

typedef struct DATA_BUFFER_T_ {
    time_t timestamp;
    size_t length;
    unsigned int checksum;
    char *data;
} DATA_BUFFER_T;

typedef struct TCP_CONNECTION_RECORDS_ {
    unsigned long CONNECTION_ID;
    DATA_BUFFER_T *dataBuffer;
    struct ACK_RECORDS_ *ackRecords; // Linked list of ACK records
    struct TCP_CONNECTION_RECORDS_ *next;
} TCP_CONNECTION_RECORDS;

// Function prototypes

TCP_CONNECTION_RECORDS* createConnection(unsigned long connectionId);
void insertConnection(TCP_CONNECTION_RECORDS **head, unsigned long connectionId);
void deleteConnection(TCP_CONNECTION_RECORDS **head, unsigned long connectionId);
TCP_CONNECTION_RECORDS* getConnection(TCP_CONNECTION_RECORDS *head, unsigned long connectionId);

// Function implementations

TCP_CONNECTION_RECORDS* createConnection(unsigned long connectionId) {
    TCP_CONNECTION_RECORDS *newConn = (TCP_CONNECTION_RECORDS*)malloc(sizeof(TCP_CONNECTION_RECORDS));
    if (!newConn) return NULL;

    newConn->CONNECTION_ID = connectionId;
    newConn->dataBuffer = (DATA_BUFFER_T*)malloc(sizeof(DATA_BUFFER_T));
    if (!newConn->dataBuffer) {
        free(newConn);
        return NULL;
    }
    newConn->dataBuffer->timestamp = time(NULL);
    newConn->dataBuffer->length = 0;
    newConn->dataBuffer->checksum = 0;
    newConn->dataBuffer->data = NULL;

    newConn->ackRecords = NULL;
    newConn->next = NULL;

    return newConn;
}

void insertConnection(TCP_CONNECTION_RECORDS **head, unsigned long connectionId) {
    TCP_CONNECTION_RECORDS *newConn = createConnection(connectionId);
    if (!newConn) return;

    newConn->next = *head;
    *head = newConn;
}

void deleteConnection(TCP_CONNECTION_RECORDS **head, unsigned long connectionId) {
    TCP_CONNECTION_RECORDS *temp = *head, *prev = NULL;

    // If head node itself holds the key to be deleted
    if (temp != NULL && temp->CONNECTION_ID == connectionId) {
        *head = temp->next; // Changed head
        free(temp->dataBuffer->data);
        free(temp->dataBuffer);
        free(temp); // Free old head
        return;
    }

    // Search for the key to be deleted, keep track of the previous node
    while (temp != NULL && temp->CONNECTION_ID != connectionId) {
        prev = temp;
        temp = temp->next;
    }

    // If key was not present in linked list
    if (temp == NULL) return;

    // Unlink the node from linked list
    prev->next = temp->next;

    free(temp->dataBuffer->data);
    free(temp->dataBuffer);
    free(temp);  // Free memory
}

TCP_CONNECTION_RECORDS* getConnection(TCP_CONNECTION_RECORDS *head, unsigned long connectionId) {
    TCP_CONNECTION_RECORDS *current = head;

    while (current != NULL) {
        if (current->CONNECTION_ID == connectionId)
            return current;

        current = current->next;
    }

    return NULL; // Connection not found
}

// Example of integration with network stack
void manageConnections(TCP_CONNECTION_RECORDS **head) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Simulate a new connection establishment
    insertConnection(head, 12345);

    // Simulate a data operation or retrieval under mutex protection
    pthread_mutex_lock(&lock);
    TCP_CONNECTION_RECORDS *conn = getConnection(*head, 12345);
    if (conn) {
        printf("Connection %lu found.\n", conn->CONNECTION_ID);
    }
    pthread_mutex_unlock(&lock);

    // Simulate a connection deletion
    deleteConnection(head, 12345);

    pthread_mutex_destroy(&lock);
}
