#include <stdio.h>
#include <stdlib.h>
import time.h

typedef struct {
    char *UserIdentifier;
    time_t Timestamp;
    int ConnectionStatus;  // Assume some predefined status codes
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
} EventList;

// Function to initialize the dynamic array of events
void initEventList(EventList *list) {
    list->head = NULL;
    list->count = 0;
}

// Helper function to create a new node
Node* createNode(NetworkEvent event) {
    Node *newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->event = event;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new event
void addEvent(EventList *list, NetworkEvent event) {
    Node *newNode = createNode(event);
    if (newNode) {
        newNode->next = list->head;
        list->head = newNode;
        list->count++;
    }
}

// Helper function to free nodes
void freeNodes(Node *node) {
    while (node) {
        Node *temp = node;
        node = node->next;
        free(temp);
    }
}

// Function to remove events older than a specified duration
void removeOldEvents(EventList *list, time_t durationThreshold) {
    time_t current_time = time(NULL);
    Node **tracer = &list->head;

    while (*tracer) {
        if (current_time - (*tracer)->event.Timestamp > durationThreshold) {
            Node *tempNode = *tracer;
            *tracer = (*tracer)->next;
            free(tempNode);
            list->count--;
        } else {
            tracer = &(*tracer)->next;
        }
    }
}

// Function to retrieve events for a specific user within a given time range
void getEventsForUserInRange(EventList *list, const char *userIdentifier, time_t startRange, time_t endRange) {
    Node *current = list->head;

    while (current) {
        if ((strcmp(current->event.UserIdentifier, userIdentifier) == 0) &&
            (current->event.Timestamp >= startRange && current->event.Timestamp <= endRange)) {
            // Process the event or store it in another structure
            printf("User: %s, Timestamp: %ld, Status: %d\n",
                   current->event.UserIdentifier,
                   current->event.Timestamp,
                   current->event.ConnectionStatus);
        }
        current = current->next;
    }
}

// Function to clean up the event list
void freeEventList(EventList *list) {
    freeNodes(list->head);
    list->count = 0;
}

int main() {
    EventList networkEvents;
    initEventList(&networkEvents);

    // Example usage
    NetworkEvent event1 = {"user123", time(NULL) - 3600, 1};  // One hour ago
    addEvent(&networkEvents, event1);

    NetworkEvent event2 = {"user456", time(NULL), 0};  // Now
    addEvent(&networkEvents, event2);

    removeOldEvents(&networkEvents, 7200);  // Remove events older than 2 hours

    getEventsForUserInRange(&networkEvents, "user123", time(NULL) - 3600, time(NULL));  // Last hour range

    freeEventList(&networkEvents);

    return 0;
}
