['Below is a C implementation that fulfills the requirements of dynamically allocating and populating an array of `NFAPI_CRC_INDICATION_PDU_T` structures in a thread-safe manner, considering efficient memory management and real-time constraints.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

// Example definitions for the required structs and types.
typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint32_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables and mutex for thread safety.
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
static size_t capacity = 0;

void* reallocate_pdu_array(size_t new_capacity) {
    void* new_array = realloc(pdu_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return NULL; // Handle allocation failure.

    memset((uint8_t*)new_array + capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T),
           0,
           (new_capacity - capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)new_array;
    capacity = new_capacity;

    return pdu_array;
}

void populate_pdu_for_ue(int ue_index) {
    // Random generation for CRCFLAG. Replace with appropriate random function if needed.
    int random_flag = rand() % 2; 
    pdu_array[ue_index].RX_UE_INFORMATION_TAG = ue_index + 1;
    pdu_array[ue_index].RNTI = ue_index + 1000;
    pdu_array[ue_index].CRC_INDICATION.CRCFLAG = (uint16_t)random_flag;
}

void initialize_pdu_array(size_t initial_capacity) {
    pthread_mutex_lock(&lock);
    if (capacity < initial_capacity) {
        if (!reallocate_pdu_array(initial_capacity)) {
            fprintf(stderr, "Failed to allocate memory for PDUs\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&lock);
}

void populate_pdus(size_t num_ues) {
    pthread_mutex_lock(&lock);
    if (num_ues > capacity) {
        if (!reallocate_pdu_array(num_ues)) {
            fprintf(stderr, "Failed to reallocate memory for PDUs\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_ues; ++i) {
        populate_pdu_for_ue(i);
    }
    pthread_mutex_unlock(&lock);
}

void finalize_pdu_array() {
    pthread_mutex_lock(&lock);
    free(pdu_array);
    pdu_array = NULL;
    capacity = 0;
    pthread_mutex_unlock(&lock);
}

// Demonstrative example within a larger application.
int main() {
