// Assuming the external configuration module provides these functions/macros
extern int get_max_list_size(void);
extern void custom_error_handler(const char *message);
extern void log_creation(const NFAPI_CRC_INDICATION_PDU_T *pdu);

typedef struct {
    // Define fields here according to your structure specifications
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned long RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    int CRCFLAG; // Randomly set in this function
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LOG_SIZE 1024 * 10 // 10 KB

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) custom_error_handler("Failed to allocate memory for list");
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int is_rnti_unique(DynamicList* list, unsigned long rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crc_ind_rel8.RNTI == rnti)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

void log_to_file(const char* message) {
    static FILE* log_file = NULL;
    if (!log_file || ftell(log_file) >= MAX_LOG_SIZE) {
        if (log_file)
            fclose(log_file);
        log_file = fopen("log.txt", "w");
        if (!log_file) custom_error_handler("Failed to open log file");
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure message is written immediately
}

void add_pdu(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    int max_size = get_max_list_size();
    if (list->size >= max_size) {
        pthread_mutex_unlock(&list->mutex);
        return; // List is full
    }

    if (!is_rnti_unique(list, pdu->crc_ind_rel8.RNTI)) {
        pthread_mutex_unlock(&list->mutex);
        return; // RNTI not unique
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        custom_error_handler("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Randomly set CRCFLAG
    srand(time(NULL));
    new_node->data.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Added PDU with RNTI: %lu", pdu->crc_ind_rel8.RNTI);
    log_to_file(log_message);

    pthread_mutex_unlock(&list->mutex);
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
