#define INITIAL_CAPACITY 10

typedef struct {
    int CELL_ID;
    uint64_t TIMESTAMP;
    char PHY_MEASUREMENT_TAG[32];
    uint16_t RX_UE_INFORMATION_TAG;
    uint8_t RNTI[3]; // Assuming RNTI is a 24-bit value
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Calculated using hash function for data integrity
} LTE_PHY_MEASUREMENT_T;

typedef struct {
    LTE_PHY_MEASUREMENT_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MeasurementArray;

static inline uint32_t hash_measurement_data(const LTE_PHY_MEASUREMENT_T* measurement) {
    // Simple hash function for demonstration purposes
    return (measurement->CELL_ID + 
            (uint32_t)(measurement->TIMESTAMP >> 32) + 
            *(const uint32_t*)measurement->PHY_MEASUREMENT_TAG +
            measurement->RX_UE_INFORMATION_TAG + 
            *(const uint16_t*)(measurement->RNTI) +
            measurement->CRC_INDICATION_REL8_TAG) % 256;
}

void init_measurement_array(MeasurementArray *ma) {
    pthread_mutex_init(&ma->lock, NULL);
    ma->size = 0;
    ma->capacity = INITIAL_CAPACITY;
    ma->array = (LTE_PHY_MEASUREMENT_T*)calloc(ma->capacity, sizeof(LTE_PHY_MEASUREMENT_T));
    if (!ma->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void free_measurement_array(MeasurementArray *ma) {
    pthread_mutex_lock(&ma->lock);
    free(ma->array);
    ma->size = 0;
    ma->capacity = 0;
    pthread_mutex_unlock(&ma->lock);
    pthread_mutex_destroy(&ma->lock);
}

static inline void resize_measurement_array(MeasurementArray *ma, size_t new_capacity) {
    LTE_PHY_MEASUREMENT_T *new_array = (LTE_PHY_MEASUREMENT_T*)realloc(ma->array, new_capacity * sizeof(LTE_PHY_MEASUREMENT_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        free_measurement_array(ma);
        exit(EXIT_FAILURE);
    }
    ma->array = new_array;
    ma->capacity = new_capacity;
}

void add_measurement(MeasurementArray *ma, LTE_PHY_MEASUREMENT_T measurement) {
    pthread_mutex_lock(&ma->lock);

    if (ma->size == ma->capacity) {
        resize_measurement_array(ma, ma->capacity * 2); // Double the capacity
    }

    measurement.CRCFLAG = hash_measurement_data(&measurement);
    ma->array[ma->size++] = measurement;

    pthread_mutex_unlock(&ma->lock);
}

void update_measurement_tags(MeasurementArray *ma, const char* new_tag) {
    pthread_mutex_lock(&ma->lock);

    for (size_t i = 0; i < ma->size; ++i) {
        strncpy(ma->array[i].PHY_MEASUREMENT_TAG, new_tag, sizeof(ma->array[i].PHY_MEASUREMENT_TAG));
        ma->array[i].CRCFLAG = hash_measurement_data(&ma->array[i]);
    }

    pthread_mutex_unlock(&ma->lock);
}

// Logging function (stub for demonstration)
