#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024 // Default max size, can be adjusted at runtime

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    _Bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    size_t max_size;
} CRCList;

void init_crc_list(CRCList* list, size_t initial_max_size) {
    list->head = NULL;
    list->size = 0;
    list->max_size = initial_max_size;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    memcpy(&node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

_Bool add_crc_pdu(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    for (Node* current = list->head; current != NULL; current = current->next) {
        if (current->data.RNTI == pdu->RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

_Bool remove_crc_pdu(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free_node(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

_Bool update_crc_flag(CRCList* list, int rnti, _Bool crcflag) {
    pthread_mutex_lock(&list->lock);

    for (Node* current = list->head; current != NULL; current = current->next) {
        if (current->data.RNTI == rnti) {
            current->data.CRCFLAG = crcflag;
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

size_t serialize_crc_list(const CRCList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);

    size_t written_bytes = fwrite(&list->size, sizeof(size_t), 1, file);
    Node* current = list->head;

    while (current != NULL && written_bytes == 1) {
        written_bytes += fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return written_bytes == list->size + 1 ? written_bytes * sizeof(size_t) + list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0;
}

size_t deserialize_crc_list(CRCList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);

    size_t expected_size;
    fread(&expected_size, sizeof(size_t), 1, file);
    Node* prev = NULL;

    for (size_t i = 0; i < expected_size && !ferror(file); ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (!fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            break;
        }

        Node* new_node = create_node(&data);
        if (!new_node) {
            while (prev) { // Clean up partially filled list
                Node* temp = prev->next;
                free_node(prev);
                prev = temp;
            }
            pthread_mutex_unlock(&list->lock);
            return 0; 
        }

        new_node->next = list->head;
        if (list->head) {
            prev->next = new_node;
        } else {
            list->head = new_node;
        }
        prev = new_node;
    }

    list->size = expected_size;

    pthread_mutex_unlock(&list->lock);

    return ferror(file) ? 0 : expected_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void destroy_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free_node(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void set_max_list_size(CRCList* list, size_t new_size) {
    pthread_mutex_lock(&list->lock);

    if (new_size < list->size) {
        Node* current = list->head;
        for (size_t i = 0; i < list->size - new_size && current != NULL; ++i) {
            Node* temp = current;
            current = current->next;
            free_node(temp);
        }
        if (current) {
            while (current->next) {
                current = current->next;
            }
            current->next = list->head;
            list->head = current;
        } else {
            list->head = NULL;
        }
    }

    list->max_size = new_size;

    pthread_mutex_unlock(&list->lock);
}

