#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NETWORK_INTERFACES 50
#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *freeList;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memoryPools[MAX_NETWORK_INTERFACES];
pthread_mutex_t poolLocks[MAX_NETWORK_INTERFACES];

void initializeMemoryPool(int interfaceIndex) {
    memoryPools[interfaceIndex].freeList = NULL;
    pthread_mutex_init(&memoryPools[interfaceIndex].lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromMemoryPool(int interfaceIndex) {
    pthread_mutex_lock(&poolLocks[interfaceIndex]);

    MemoryPoolNode *node = memoryPools[interfaceIndex].freeList;
    if (node != NULL) {
        memoryPools[interfaceIndex].freeList = node->next;
    } else {
        node = malloc(sizeof(MemoryPoolNode));
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&poolLocks[interfaceIndex]);
            return NULL;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *dataPtr = &node->data;
    node->next = NULL;

    pthread_mutex_unlock(&poolLocks[interfaceIndex]);

    // Initialize the structure
    dataPtr->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    dataPtr->RNTI = rand() % 5000;                   // Example initialization
    dataPtr->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    return dataPtr;
}

void deallocateToMemoryPool(int interfaceIndex, NFAPI_CRC_INDICATION_PDU_T *dataPtr) {
    MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
    if (!node) {
        fprintf(stderr, "Failed to allocate node for garbage collection\n");
        return;
    }

    memcpy(&node->data, dataPtr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&poolLocks[interfaceIndex]);
    node->next = memoryPools[interfaceIndex].freeList;
    memoryPools[interfaceIndex].freeList = node;
    pthread_mutex_unlock(&poolLocks[interfaceIndex]);
}

void* threadFunction(void *arg) {
    int interfaceIndex = *(int*)arg;

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocateFromMemoryPool(interfaceIndex);
    if (pdu != NULL) {
        // Process the pdu
        printf("Processed PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
               pdu->RX_UE_INFORMATION_TAG,
               pdu->RNTI,
               pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);

        deallocateToMemoryPool(interfaceIndex, pdu);
    }

    return NULL;
}

void initializeSystem() {
    srand(time(NULL));
    for (int i = 0; i < MAX_NETWORK_INTERFACES; ++i) {
        initializeMemoryPool(i);
        pthread_mutex_init(&poolLocks[i], NULL);
    }
}

void manageDynamicArray() {
    // Simulate managing the dynamic array with multiple threads
    pthread_t threads[MAX_THREADS];
    int interfaceIndices[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        interfaceIndices[i] = rand() % MAX_NETWORK_INTERFACES;
        if (pthread_create(&threads[i], NULL, threadFunction, &interfaceIndices[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initializeSystem();
    manageDynamicArray();

    // Perform cleanup
    for (int i = 0; i < MAX_NETWORK_INTERFACES; ++i) {
        pthread_mutex_destroy(&poolLocks[i]);
    }

    return 0;
}
```

