void init_packet_array(PacketArray *pa, size_t initial_capacity) {
    pa->capacity = initial_capacity;
    pa->count = 0;
    pa->packets = malloc(initial_capacity * sizeof(DataPacket));
    if (!pa->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_packet_array(PacketArray *pa) {
    free(pa->packets);
    pa->packets = NULL;
    pa->capacity = 0;
    pa->count = 0;
}

int add_data_packet(PacketArray *pa, DataPacket new_packet) {
    if (new_packet.payload_length > MAX_PAYLOAD_LENGTH) {
        fprintf(stderr, "Payload length exceeds maximum allowed\n");
        return -1;
    }

    if (pa->count == pa->capacity) {
        size_t new_capacity = pa->capacity * 2;
        DataPacket *temp = realloc(pa->packets, new_capacity * sizeof(DataPacket));
        if (!temp) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        pa->packets = temp;
        pa->capacity = new_capacity;
    }

    pa->packets[pa->count++] = new_packet;
    return 0;
}

DataPacket* get_data_packet(PacketArray *pa, time_t timestamp) {
    for (size_t i = 0; i < pa->count; ++i) {
        if (pa->packets[i].timestamp == timestamp) {
            return &pa->packets[i];
        }
    }
    return NULL;
}

void update_data_packet(PacketArray *pa, time_t timestamp, DataPacket updated_packet) {
    for (size_t i = 0; i < pa->count; ++i) {
        if (pa->packets[i].timestamp == timestamp) {
            pa->packets[i] = updated_packet;
            return;
        }
    }
}

void display_usage() {
