    printf("Options:\n");
    printf("  -h, --help          Display this help message\n");
    printf("  -m, --man           Generate manpage documentation\n");
    printf("  -i INPUT_FILE       Specify input file path\n");
    printf("  -o OUTPUT_FILE      Specify output file path\n");
}

void generate_man_page() {
    printf("Manpage for program:\n");
    printf("This program manages DataPacket structures.\n");
}

int main(int argc, char *argv[]) {
    PacketArray pa;
    init_packet_array(&pa, 10);

    int opt;
    char input_file[256] = {0};
    char output_file[256] = {0};

    while ((opt = getopt(argc, argv, "hi:o:m")) != -1) {
        switch (opt) {
            case 'h':
                display_usage();
                return 0;
            case 'i':
                strncpy(input_file, optarg, sizeof(input_file));
                break;
            case 'o':
                strncpy(output_file, optarg, sizeof(output_file));
                break;
            case 'm':
                generate_man_page();
                return 0;
            default:
                display_usage();
                return EXIT_FAILURE;
        }
    }

    // Example usage of DataPacket management
    DataPacket dp = {time(NULL), 512, 12345};
    if (add_data_packet(&pa, dp) == -1) {
        fprintf(stderr, "Failed to add data packet\n");
