}

int serialize_to_file(const char *filename, NFAPI_L1_STATS_MANAGER* manager) {
    if (!manager || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    size_t count = fwrite(&manager->count, sizeof(size_t), 1, file);
    if (count != 1) goto error;

    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_L1_STATS_T* struct_data = &manager->structures[i];

        fwrite(&struct_data->ue_info_tag.tag, sizeof(struct_data->ue_info_tag.tag), 1, file);
        fwrite(&struct_data->rnti.rnti, sizeof(struct_data->rnti.rnti), 1, file);

        size_t buffer_size = struct_data->stats_rel8_tag.buffer_size;
        fwrite(&buffer_size, sizeof(buffer_size), 1, file);

        if (buffer_size > 0) {
            fwrite(struct_data->stats_rel8_tag.buffer, sizeof(float), buffer_size, file);
        }
    }

    fclose(file);
    return 0;

error:
    fclose(file);
    return -1;
}

int deserialize_from_file(const char *filename, NFAPI_L1_STATS_MANAGER* manager) {
    if (!manager || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > MAX_STRUCTURES) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
        NFAPI_L1_STATS_T* new_struct = &manager->structures[i];

        fread(&new_struct->ue_info_tag.tag, sizeof(new_struct->ue_info_tag.tag), 1, file);
        fread(&new_struct->rnti.rnti, sizeof(new_struct->rnti.rnti), 1, file);

        size_t buffer_size;
        fread(&buffer_size, sizeof(buffer_size), 1, file);

        if (buffer_size > 0) {
            new_struct->stats_rel8_tag.buffer = (float*)malloc(buffer_size * sizeof(float));
            if (!new_struct->stats_rel8_tag.buffer) {
                fclose(file);
                return -1;
            }

            fread(new_struct->stats_rel8_tag.buffer, sizeof(float), buffer_size, file);
        } else {
            new_struct->stats_rel8_tag.buffer = NULL;
        }

        new_struct->stats_rel8_tag.buffer_size = buffer_size;
    }

    manager->count = count;
    fclose(file);
    return 0;
}
