['Below is a C implementation of the LTE UE Context management system using a dynamic array and mutexes for thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int ueid;
    char *rrc_messages; // Simple representation as string
    char *session_info;
    char *qos_settings;
} RRCContext;

typedef struct {
    int ueid;
    RRCContext context;
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UECtxManager;

// Initialize the manager
UECtxManager* init_manager(size_t initial_capacity) {
    UECtxManager *manager = (UECtxManager *)malloc(sizeof(UECtxManager));
    if (!manager) return NULL;

    manager->contexts = (UEContext **)calloc(initial_capacity, sizeof(UEContext *));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Add or update a context
void add_or_update_context(UECtxManager *manager, int ueid, RRCContext context) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ueid == ueid) {
            free(manager->contexts[i]->context.rrc_messages);
            free(manager->contexts[i]->context.session_info);
            free(manager->contexts[i]->context.qos_settings);

            manager->contexts[i]->context = context;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEContext **new_contexts = (UEContext **)realloc(manager->contexts, new_capacity * sizeof(UEContext *));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    UEContext *new_ctx = (UEContext *)malloc(sizeof(UEContext));
    new_ctx->ueid = ueid;
    new_ctx->context = context;

    manager->contexts[manager->count++] = new_ctx;

    pthread_mutex_unlock(&manager->lock);
}

// Get the total number of active contexts
size_t get_active_contexts_count(const UECtxManager *manager) {
    size_t count;
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);
    count = manager->count;
    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);

    return count;
}

// Free all allocated resources
void free_manager(UECtxManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->context.rrc_messages);
        free(manager->contexts[i]->context.session_info);
        free(manager->contexts[i]->context.qos_settings);
        free(manager->contexts[i]);
    }

    free(manager->contexts);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    UECtxManager *manager = init_manager(10);

    RRCContext context1 = { .rrc_messages = strdup("RRC Msg 1"), .session_info = strdup("Session 1"), .qos_settings = strdup("QoS 1") };
    add_or_update_context(manager, 101, context1);

    printf("Active Contexts: %zu\n", get_active_contexts_count(manager));

    free_manager(manager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` ensures that operations on the dynamic array are thread-safe.
- **Dynamic Array**: The capacity of the array doubles when needed, which helps in managing a growing number of UE contexts efficiently.
- **Memory Management**: Proper allocation and deallocation prevent memory leaks. The `free_manager` function ensures all resources are freed.
- **Concurrency Considerations**: Mutexes ensure that race conditions do not occur during concurrent access or modifications.']

