- **Thread Safety**: A mutex (`pthread_mutex_t`) ensures thread safety during critical sections like logging and memory operations.
- **Retry Logic**: Implements retry logic with delays when fetching configuration updates from external sources, which can handle temporary connectivity issues gracefully.
- **Logging**: Logs errors and informational messages to a file without significant overhead. Logging is protected by the same mutex for thread-safety.
- **Error Handling**: Uses an error code system to indicate success or failure states clearly.

This implementation considers performance implications by minimizing lock contention and using efficient retry logic, while also maintaining clean and maintainable code structure with comments and structured logging.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <jansson.h> // JSON library

#define MAX_UE_CONTEXTS 100000
#define UEID_MAX_LENGTH 32

typedef enum {
    SESSION_IDLE,
    SESSION_ACTIVE,
    SESSION_TERMINATED
} SessionStatus;

typedef struct {
    char ueid[UEID_MAX_LENGTH];
    json_t *rrc_messages;
    time_t last_contact_timestamp;
    SessionStatus session_status;
} UEContext;

typedef struct Node {
    int key; // UE context index for hash table
    UEContext data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_rwlock_t lock;
} UETable;

// Function prototypes
UETable* create_ue_table(size_t size);
int add_or_update_ue_context(UETable *table, const char *ueid, json_t *rrc_messages, SessionStatus status);
size_t get_active_ues_count(const UETable *table);
char* export_ue_table_to_json(const UETable *table);
void free_ue_table(UETable *table);

// Hash function for UEID
unsigned int hash_ueid(const char *ueid) {
    unsigned int hash = 0;
    while (*ueid) {
        hash = (hash << 5) + *ueid++;
    }
    return hash;
}

UETable* create_ue_table(size_t size) {
    UETable *table = malloc(sizeof(UETable));
    table->buckets = calloc((unsigned)size, sizeof(Node*));
    table->size = size;
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

int add_or_update_ue_context(UETable *table, const char *ueid, json_t *rrc_messages, SessionStatus status) {
    unsigned int index = hash_ueid(ueid) % table->size;
    Node *node = table->buckets[index];

    pthread_rwlock_wrlock(&table->lock);
    while (node != NULL) {
        if (strcmp(node->data.ueid, ueid) == 0) {
            json_array_clear(node->data.rrc_messages);
            json_array_extend(node->data.rrc_messages, rrc_messages);
            node->data.last_contact_timestamp = time(NULL);
            node->data.session_status = status;
            pthread_rwlock_unlock(&table->lock);
            return 1; // Updated
        }
        node = node->next;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&table->lock);
        return -1; // Memory allocation failed
    }

    strncpy(new_node->data.ueid, ueid, UEID_MAX_LENGTH);
    new_node->data.rrc_messages = json_array();
    json_array_extend(new_node->data.rrc_messages, rrc_messages);
    new_node->data.last_contact_timestamp = time(NULL);
    new_node->data.session_status = status;

    new_node->key = index;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_rwlock_unlock(&table->lock);
    return 0; // Added
}

size_t get_active_ues_count(const UETable *table) {
    size_t count = 0;
    pthread_rwlock_rdlock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        Node *node = table->buckets[i];
        while (node != NULL) {
            if (node->data.session_status == SESSION_ACTIVE) {
                count++;
            }
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&table->lock);
    return count;
}

char* export_ue_table_to_json(const UETable *table) {
    json_t *root = json_array();
    pthread_rwlock_rdlock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        Node *node = table->buckets[i];
        while (node != NULL) {
            json_t *ue_context_json = json_object();

            json_object_set_new(ue_context_json, "ueid", json_string(node->data.ueid));
            json_object_set_new(ue_context_json, "rrc_messages", node->data.rrc_messages);
            json_object_set_new(ue_context_json, "last_contact_timestamp", json_integer((int)node->data.last_contact_timestamp));
            json_object_set_new(ue_context_json, "session_status", json_string(node->data.session_status == SESSION_ACTIVE ? "active" :
                                                                                   node->data.session_status == SESSION_IDLE ? "idle" : "terminated"));

            json_array_append_new(root, ue_context_json);
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&table->lock);

    char *exported_data = json_dumps(root, JSON_INDENT(2));
    json_decref(root);

    return exported_data; // Caller is responsible for freeing this memory
}

void free_ue_table(UETable *table) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        Node *node = table->buckets[i];
        while (node != NULL) {
            Node *next_node = node->next;
            json_decref(node->data.rrc_messages);
            free(node);
            node = next_node;
        }
    }

    free(table->buckets);
    pthread_rwlock_unlock(&table->lock);
    pthread_rwlock_destroy(&table->lock);
    free(table);
}
