['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_UE_CONTEXTS 10000
#define MAX_RRC_MESSAGES 100
#define RRC_MESSAGE_SIZE 512

typedef struct {
    int UEID;
    char **rrcMessages;
    size_t numRrcMessages;
    // Additional metadata such as session information and QoS settings can be added here.
} UEContext;

typedef struct {
    UEContext *contexts[MAX_UE_CONTEXTS];
    pthread_rwlock_t lock;  // Reader-writer lock for concurrent access
} ContextManager;

// Initializes the context manager
void initContextManager(ContextManager *manager) {
    memset(manager->contexts, 0, sizeof(manager->contexts));
    pthread_rwlock_init(&manager->lock, NULL);
}

// Adds a new UE context or updates an existing one
int addOrUpdateUEContext(ContextManager *manager, int ueID, char **newRrcMessages, size_t numRrcMessages) {
    pthread_rwlock_wrlock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (!manager->contexts[i] || manager->contexts[i]->UEID == ueID) {
            UEContext *context;
            if (!manager->contexts[i]) {
                context = malloc(sizeof(UEContext));
                if (!context) {
                    pthread_rwlock_unlock(&manager->lock);
                    return -1;  // Memory allocation failed
                }
                manager->contexts[i] = context;
            } else {
                context = manager->contexts[i];
            }

            context->UEID = ueID;
            free(context->rrcMessages);  // Free existing messages if updating

            // Allocate new message array and copy the messages
            context->rrcMessages = malloc(numRrcMessages * sizeof(char *));
            memcpy(context->rrcMessages, newRrcMessages, numRrcMessages * sizeof(char *));
            context->numRrcMessages = numRrcMessages;

            pthread_rwlock_unlock(&manager->lock);
            return 0;  // Success
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return -1;  // No space for new contexts
}

// Retrieves the total number of active UE contexts
int getActiveContextCount(ContextManager *manager) {
    int count = 0;
    pthread_rwlock_rdlock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (manager->contexts[i]) {
            count++;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return count;
}

// Frees all allocated resources
void freeAllResources(ContextManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (manager->contexts[i]) {
            free(manager->contexts[i]->rrcMessages);
            free(manager->contexts[i]);
            manager->contexts[i] = NULL;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

// Example usage
int main() {
    ContextManager manager;
    initContextManager(&manager);

    char *messages[2];
    messages[0] = malloc(RRC_MESSAGE_SIZE);
    strcpy(messages[0], "RRC Message 1");
    messages[1] = malloc(RRC_MESSAGE_SIZE);
    strcpy(messages[1], "RRC Message 2");

    addOrUpdateUEContext(&manager, 12345, messages, 2);

    printf("Active Contexts: %d\n", getActiveContextCount(&manager));

    freeAllResources(&manager);

    free(messages[0]);
    free(messages[1]);

    return 0;
}
```

This code defines a `ContextManager` structure that manages UE contexts using an array and uses a reader-writer lock for thread safety. It supports adding or updating UE contexts, retrieving the active context count, and freeing resources. The example demonstrates how to use these functions in a multi-threaded environment.']

