bool is_unique_RNTI(CRC_Indication_List* list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) return false;
    }
    return true;
}

uint32_t calculate_crcflag(uint8_t* data, size_t length, uint32_t polynomial) {
    // Implement CRC calculation logic here
    uint32_t crc = 0xFFFFFFFF; // Initial value for CRC-32
    for (size_t i = 0; i < length; ++i) {
        crc ^= ((uint32_t)data[i] << 24);
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80000000)
                crc = (crc << 1) ^ polynomial;
            else
                crc <<= 1;
        }
    }
    return ~crc; // Final XOR value for CRC-32
}

bool add_pdu(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu, uint32_t polynomial) {
    if (!list || !is_unique_RNTI(list, pdu.RNTI)) return false;

    if (list->size >= list->capacity && list->capacity < MAX_LIST_SIZE) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        if (new_capacity > MAX_LIST_SIZE) new_capacity = MAX_LIST_SIZE;

        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return false;

        list->data = new_data;
        list->capacity = new_capacity;
    }

    pdu.CRCFLAG = calculate_crcflag((uint8_t*)&pdu, sizeof(pdu), polynomial);
    list->data[list->size++] = pdu;
    return true;
}

int main() {
    CRC_Indication_List list;
    if (!initialize_list(&list)) {
        fprintf(stderr, "Failed to initialize list\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1234, .CRC_INDICATION_REL8_TAG = 5 };
    uint32_t polynomial = 0x04C11DB7; // Example CRC-32 polynomial

    if (!add_pdu(&list, pdu, polynomial)) {
        fprintf(stderr, "Failed to add PDU\n");
    }

    free_list(&list);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Memory Management**: The list dynamically grows as needed, up to a maximum capacity.
- **Unique RNTI Check**: Ensures each `RNTI` is unique within the list.
- **CRC Calculation**: A basic CRC-32 calculation is implemented using a specified polynomial.
- **Error Handling**: Checks for memory allocation failures and invalid inputs.
- **Modular Design**: Functions are modular, allowing easy updates and maintenance.']

