// Custom allocator structure
typedef struct {
    void** buffer;
    size_t total_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryAllocator;

MemoryAllocator mem_allocator = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void initialize_memory_allocator(size_t initial_capacity);
void* allocate_memory(size_t size);
void deallocate_memory(void* ptr, size_t size);
CRCIndicationPool* create_crc_indication_pool(size_t initial_count);
void destroy_crc_indication_pool(CRCIndicationPool* pool);
int populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu);

// Initialize memory allocator
void initialize_memory_allocator(size_t initial_capacity) {
    pthread_mutex_lock(&mem_allocator.lock);
    mem_allocator.buffer = malloc(initial_capacity * sizeof(void*));
    mem_allocator.total_size = initial_capacity;
    mem_allocator.used_size = 0;
    pthread_mutex_unlock(&mem_allocator.lock);
}

// Allocate memory with custom allocator
void* allocate_memory(size_t size) {
    pthread_mutex_lock(&mem_allocator.lock);
    if (mem_allocator.used_size + size > mem_allocator.total_size * sizeof(void*)) {
        // Resize buffer
        size_t new_total_size = mem_allocator.total_size * 2;
        void** new_buffer = realloc(mem_allocator.buffer, new_total_size * sizeof(void*));
        if (!new_buffer) {
            pthread_mutex_unlock(&mem_allocator.lock);
            return NULL; // Allocation failed
        }
        mem_allocator.buffer = new_buffer;
        mem_allocator.total_size = new_total_size;
    }

    void* ptr = malloc(size);
    if (ptr) {
        mem_allocator.buffer[mem_allocator.used_size / sizeof(void*)] = ptr;
        mem_allocator.used_size += size;
    }
    pthread_mutex_unlock(&mem_allocator.lock);
    return ptr;
}

// Deallocate memory with custom allocator
void deallocate_memory(void* ptr, size_t size) {
    if (!ptr) return;

    pthread_mutex_lock(&mem_allocator.lock);
    for (size_t i = 0; i < mem_allocator.used_size / sizeof(void*); ++i) {
        if (mem_allocator.buffer[i] == ptr) {
            free(ptr);
            mem_allocator.used_size -= size;
            // Optional: Shift remaining pointers to fill the gap
            break;
        }
    }
    pthread_mutex_unlock(&mem_allocator.lock);
}

// Create a CRC indication pool
CRCIndicationPool* create_crc_indication_pool(size_t initial_count) {
    CRCIndicationPool* pool = allocate_memory(sizeof(CRCIndicationPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->data = allocate_memory(initial_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->count = 0;
    pool->capacity = initial_count;
    return pool;
}

// Destroy a CRC indication pool
void destroy_crc_indication_pool(CRCIndicationPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        deallocate_memory(pool->data[i].lcg_config, sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));
        deallocate_memory(pool->data[i].rrc_connection_info, sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));
    }
    deallocate_memory(pool->data, pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    deallocate_memory(pool, sizeof(CRCIndicationPool));
}

// Populate a CRC indication PDU
int populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1;

    // Randomly set CRCFLAG and QFI
    srand(time(NULL));
    uint8_t crc_flag = rand() % 2;
    pdu->QFI = rand() % 256; // Example range for QFI

    // Allocate LCG_CONFIG and RRC connection information
    pdu->lcg_config = allocate_memory(sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));
    if (!pdu->lcg_config) return -1;

    pdu->rrc_connection_info = allocate_memory(sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));
    if (!pdu->rrc_connection_info) {
        deallocate_memory(pdu->lcg_config, sizeof(LTEPHY_TRANSPORT_LAYER_MESSAGE));
        return -1;
    }

    // Populate with example data
    pdu->lcg_config->RRC_Connection_ID = rand(); // Example ID
    pdu->rrc_connection_info->RRC_Connection_ID = rand(); // Example ID

    // Set PDU size
    pdu->pdu_size = rand() % 1500 + 1; // Example size range from 1 to 1500 bytes

    return 0;
}

// Main function for demonstration purposes
int main() {
    initialize_memory_allocator(1024);

    CRCIndicationPool* pool = create_crc_indication_pool(10);
    if (!pool) {
        fprintf(stderr, "Failed to create CRC indication pool.\n");
        return EXIT_FAILURE;
    }

    pthread_mutex_lock(&pool->lock);
