['Below is a C code implementation for managing a list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    time_t timestamp; // For tracking activity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} List;

// Logging function prototype
void log_event(const char* message);

List list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

int is_list_full() {
    return list.size >= MAX_LIST_SIZE;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list.mutex);

    while (is_list_full()) {
        log_event("List overflow, waiting...");
        pthread_cond_wait(&list.cond, &list.mutex);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed");
        pthread_mutex_unlock(&list.mutex);
        return;
    }

    new_node->data = pdu;
    new_node->next = list.head;
    list.head = new_node;
    list.size++;

    log_event("Successfully added to list");

    pthread_cond_signal(&list.cond);
    pthread_mutex_unlock(&list.mutex);
}

void remove_inactive_entries() {
    time_t current_time = time(NULL);
    Node *current = list.head, *prev = NULL;

    pthread_mutex_lock(&list.mutex);

    while (current) {
        if (difftime(current_time, current->data.timestamp) > 60) { // Inactive if older than 60 seconds
            Node* to_delete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                list.head = current->next;
            }
            free(to_delete);
            list.size--;
            log_event("Removed inactive entry");
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list.mutex);
}

void* cleanup_task(void* arg) {
    while (1) {
        sleep(30); // Run every 30 seconds
        remove_inactive_entries();
    }
    return NULL;
}

void initialize_list() {
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_task, NULL)) {
        log_event("Failed to create cleanup thread");
    }
}

int main() {
    initialize_list();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 100, {.CRCFLAG = rand() % 256}, time(NULL)};
    add_to_list(pdu);

    return 0;
}

void log_event(const char* message) {
    printf("%s\n", message); // Placeholder for non-blocking logging
}
```

### Key Points:
- **Thread Safety**: The list operations are protected by a mutex, and a condition variable is used to handle full-list conditions.
- **Memory Management**: Nodes are dynamically allocated and freed as needed. Proper error handling is in place for memory allocation failures.
- **Logging**: A simple logging function records events without blocking the main execution flow.
- **Cleanup Task**: Runs periodically in a background thread to remove inactive entries based on a timestamp.
- **Concurrency**: The code supports concurrent access by using pthreads for synchronization.

This implementation ensures efficient management of the list while maintaining performance and resource efficiency.']

