#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RNTI_MIN 0x00000100
#define RNTI_MAX 0x0000FFFF

typedef struct {
    uint64_t timestamp;
    int sequence_number;
    unsigned char RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t lock;
    void (*log)(const char*);
} CRCList;

void log_message(const char* message) {
#ifdef ENABLE_LOGGING
    printf("%s\n", message);
#endif
}

CRCList* create_crc_list(void (*logger)(const char*)) {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate CRCList");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->log = logger ? logger : log_message;

    return list;
}

int is_valid_rnti(uint16_t rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

void* allocate_memory(void) {
    void* memory = malloc(sizeof(Node));
    if (!memory) {
        perror("Failed to allocate Node");
        exit(EXIT_FAILURE);
    }
    return memory;
}

int add_crc_pdu(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_ELEMENTS || !is_valid_rnti(pdu->RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* node = allocate_memory();
    memcpy(&(node->data), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = list->head;
    list->head = node;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    if (list->log) {
        list->log("CRC PDU added successfully");
    }

    return 0;
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    CRCList* crc_list = create_crc_list(log_message);

    for (int i = 0; i < MAX_ELEMENTS + 1; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.timestamp = time(NULL) + i;
        pdu.sequence_number = i;
        pdu.RX_UE_INFORMATION_TAG = rand() % 256;
        pdu.RNTI = RNTI_MIN + (rand() % (RNTI_MAX - RNTI_MIN + 1));
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() % 2;

        if (add_crc_pdu(crc_list, &pdu) == -1) {
            printf("Failed to add PDU\n");
        }
    }

    free_crc_list(crc_list);
    return 0;
}
```

