#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES_PER_SECOND 10
#define SIGNAL_THRESHOLD -70

typedef struct {
    int rnti;
    char rx_ue_information_tag[32];
    int crc_flag; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int signal_strength;
    int priority; // Higher value means higher priority
    NFAPI_CRC_INDICATION_PDU_T *pdu;
} UE_Info;

// Priority queue node
typedef struct Node {
    UE_Info info;
    struct Node* next;
} Node;

// Priority Queue structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue pq = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize a new NFAPI_CRC_INDICATION_PDU_T with random CRC_FLAG
NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rnti, int signal_strength) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    snprintf(pdu->rx_ue_information_tag, sizeof(pdu->rx_ue_information_tag), "UE%d", rnti);
    pdu->rnti = rnti;
    pdu->crc_flag = (signal_strength > SIGNAL_THRESHOLD);

    return pdu;
}

// Function to insert UE_Info into the priority queue
void enqueue(UE_Info info) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->info = info;
    new_node->next = NULL;

    pthread_mutex_lock(&pq.lock);

    if (!pq.head || pq.head->info.priority < info.priority) {
        new_node->next = pq.head;
        pq.head = new_node;
    } else {
        Node* current = pq.head;
        while (current->next && current->next->info.priority >= info.priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq.lock);
}

// Function to dequeue a UE_Info from the priority queue
UE_Info dequeue() {
    if (!pq.head) return (UE_Info){0, 0, NULL};

    Node* temp = pq.head;
    UE_Info info = temp->info;

    pq.head = temp->next;
    free(temp);

    return info;
}

// Function to process UEs from the priority queue
void* process_ues(void* arg) {
    int processed_count = 0;
    time_t start_time, current_time;
    start_time = current_time = time(NULL);

    while (1) {
        pthread_mutex_lock(&pq.lock);

        if (!pq.head) {
            pthread_mutex_unlock(&pq.lock);
            break; // Exit when no more items in the queue
        }

        UE_Info ue_info = dequeue();
        processed_count++;

        if (processed_count >= MAX_STRUCTURES_PER_SECOND && difftime(current_time, start_time) < 1.0) {
            sleep(1 - difftime(current_time, start_time)); // Sleep to maintain rate limit
            processed_count = 0;
            current_time = time(NULL);
        }

        pthread_mutex_unlock(&pq.lock);

        if (ue_info.pdu) {
            printf("Processed RNTI: %d with CRC_FLAG: %d\n", ue_info.pdu->rnti, ue_info.pdu->crc_flag);
            free(ue_info.pdu);
        }
    }
}

// Main function to demonstrate the creation and processing of UEs
int main() {
    srand(time(NULL));

    // Simulate incoming UE information with random signal strengths
    for (int i = 0; i < 100; ++i) {
        int rnti = rand();
        int signal_strength = -80 + rand() % 50; // Random signal strength between -80 and -30

        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(rnti, signal_strength);
        if (pdu) {
            enqueue((UE_Info){signal_strength, signal_strength, pdu});
        } else {
            printf("Failed to allocate memory for PDU with RNTI: %d\n", rnti);
        }
    }

    // Create a thread pool
    const int num_threads = 4;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_ues, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All UEs processed.\n");

    return 0;
}
```']

