#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Define structures
typedef struct {
    uint16_t crcFlag;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint32_t rnti;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rxUeInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG_T crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define node structure for linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

// Head of the linked list and lock for thread safety
struct Node* head = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Function to create a new node with random values
struct Node* create_node() {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) return NULL;

    newNode->data.rxUeInformationTag.rnti = rand() % 0xFFFFFFFF;
    newNode->data.rnti = rand() % 0xFFFFFFFF;
    newNode->data.crcIndicationRel8Tag.crcFlag = rand() % 2; // Randomly set CRCFLAG

    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the end of the list
void append_node(struct Node* newNode) {
    pthread_rwlock_wrlock(&rwlock);

    if (head == NULL) {
        head = newNode;
    } else {
        struct Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    pthread_rwlock_unlock(&rwlock);
}

// Function to create and populate the linked list
void create_linked_list(int N) {
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < N; ++i) {
        struct Node* newNode = create_node();
        if (newNode) append_node(newNode);
    }
}

// Serialization function to write the list to a binary file
void serialize_list(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_rwlock_rdlock(&rwlock);

    struct Node* temp = head;
    while (temp != NULL) {
        fwrite(&(temp->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        temp = temp->next;
    }

    fclose(file);
    pthread_rwlock_unlock(&rwlock);
}

// Deserialization function to read the list from a binary file
void deserialize_list(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    while (!feof(file)) {
        struct Node* newNode = create_node();
        if (fread(&(newNode->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1)
            append_node(newNode);
        else
            free(newNode); // If read fails, free allocated memory
    }

    fclose(file);
}

// Function to free the linked list
void free_linked_list() {
    pthread_rwlock_wrlock(&rwlock);

    struct Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    pthread_rwlock_unlock(&rwlock);
}

// Example usage
int main() {
    int N = 1000; // Number of elements

    create_linked_list(N);

    serialize_list("nfa_crc_data.bin");
    deserialize_list("nfa_crc_data.bin");

    free_linked_list();

    return 0;
}
