#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_STRUCTS 10000
#define CACHE_LINE_SIZE 64

typedef struct {
    uint32_t rnti;
    bool crcFlag;
    time_t timestamp;
    char uniqueID[16];
} CRC_INDICATION_REL8_TAG;

typedef struct {
    // Placeholder for RX_UE_INFORMATION_TAG fields
    int ueIndex;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;
    size_t count;
} CrcIndicationList;

// Utility functions for alignment and logging
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    posix_memalign(&ptr, alignment, size);
    return ptr;
}

void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Function to initialize the list
CrcIndicationList* init_list() {
    CrcIndicationList* list = (CrcIndicationList*)aligned_alloc(CACHE_LINE_SIZE, sizeof(CrcIndicationList));
    if (!list) {
        log_error("Failed to allocate memory for CRC Indication List");
        return NULL;
    }
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    list->count = 0;
    return list;
}

// Function to add an entry
bool add_entry(CrcIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return false;

    pthread_rwlock_wrlock(&list->rwlock);

    Node* new_node = (Node*)aligned_alloc(CACHE_LINE_SIZE, sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for list node");
        pthread_rwlock_unlock(&list->rwlock);
        return false;
    }
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_rwlock_unlock(&list->rwlock);

    // Log addition
    printf("Added entry with RNTI: %u\n", pdu.rnti);

    return true;
}

// Cleanup function to remove outdated entries based on timestamp
void cleanup_list(CrcIndicationList* list, time_t threshold) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->rwlock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (difftime(time(NULL), current->data.crcIndicationRel8Tag.timestamp) > threshold) {
            Node* to_delete = current;
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free(to_delete);
            list->count--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);

    // Log cleanup completion
    printf("Cleanup completed. Remaining entries: %zu\n", list->count);
}

// Query interface for RNTI and CRCFLAG with pagination
void query_list(CrcIndicationList* list, uint32_t rnti_filter, bool crcFlag_filter, size_t page_size) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->rwlock);

    Node *current = list->head;
    size_t count = 0;

    while (current && count < page_size) {
        if ((rnti_filter == current->data.rnti || rnti_filter == 0) &&
            (crcFlag_filter == current->data.crcIndicationRel8Tag.crcFlag || !crcFlag_filter)) {

            printf("RNTI: %u, CRCFLAG: %d\n", 
                   current->data.rnti,
                   current->data.crcIndicationRel8Tag.crcFlag);
        }
        current = current->next;
        count++;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

// Serialization to JSON (pseudo-code for brevity)
void serialize_to_json(CrcIndicationList* list) {
    if (!list) return;

    printf("{\n");
