    RRC_MESSAGE_CONTAINER_T container;
    // Additional fields can be added here
} NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T;

// Node structure for the linked list
typedef struct Node {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *data;
    struct Node *next;
} Node;

// Linked list to manage dynamic collection of structures
typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;  // Mutex for thread safety
} LinkedList;

// Function prototypes
LinkedList* create_list();
void destroy_list(LinkedList *list);
int add_pdu(LinkedList *list, NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *pdu);
NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* remove_pdu(LinkedList *list, size_t index);
void iterate_list(const LinkedList *list);

// Create a new linked list
LinkedList* create_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the linked list and free memory
void destroy_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data);  // Free RRC structure
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the list
int add_pdu(LinkedList *list, NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *pdu) {
    if (!list || !pdu) return -1;

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return -1;
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);

    return 0;  // Success
}

// Remove a PDU from the list by index
NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* remove_pdu(LinkedList *list, size_t index) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    Node *previous = NULL;
    for (size_t i = 0; current && i < index; ++i) {
        previous = current;
        current = current->next;
    }

    if (!current) {  // Index out of range
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *pdu = current->data;

    if (previous) {
        previous->next = current->next;
    } else {
        list->head = current->next;  // Remove head
    }
    free(current);

    pthread_mutex_unlock(&list->lock);
    return pdu;  // Return the removed PDU
}

// Iterate over the list and print data for demonstration
void iterate_list(const LinkedList *list) {
    if (!list) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    Node *current = list->head;
    while (current) {
        // Placeholder: Add logic to process or log each pdu's message here
        current = current->next;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Unit tests and additional functionalities can be added below

int main() {
    LinkedList *list = create_list();
    if (!list) return 1;

    // Create a new PDU for demonstration
    NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *pdu = (NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T *)malloc(sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T));
    if (!pdu) {
        destroy_list(list);
        return 1;
    }

    // Add PDU to list
    add_pdu(list, pdu);

    // Iterate and process the list
    iterate_list(list);

