#define MAX_STRUCTURES 10000
#define POOL_SIZE (MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T))

static NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
static size_t available_size = 0;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool() {
    memory_pool = malloc(POOL_SIZE);
    if (memory_pool) {
        available_size = POOL_SIZE;
    }
}

int allocate_nfa_pi_crc_indic_pdu(NFAPI_CRC_INDICATION_PDU_T** pdu_array, size_t count) {
    pthread_mutex_lock(&pool_mutex);

    if (!pdu_array || count == 0 || count > MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool_mutex);
        return -1;
    }

    size_t required_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_size > available_size) {
        // Try to allocate only what's needed
        size_t allocable_size = fmin(required_size, available_size);
        count = allocable_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (!count) {  // No memory could be allocated at all
            pthread_mutex_unlock(&pool_mutex);
            return -2;
        }
    }

    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool;
    available_size -= count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    for (size_t i = 0; i < count; ++i) {
        (*pdu_array)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        // Initialize other fields as needed...
    }

    pthread_mutex_unlock(&pool_mutex);
    return 0;
}

void free_memory_pool() {
