static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
size_t list_size = 0;
size_t allocated_size = 0;

// Function to initialize the list
void init_pdu_list() {
    pthread_mutex_lock(&list_mutex);
    pdu_list = NULL;
    list_size = 0;
    allocated_size = 0;
    pthread_mutex_unlock(&list_mutex);
}

// Function to add a new PDU structure ensuring unique RNTI with minimal memory allocations
int add_pdu(RX_UE_INFORMATION_TAG_T rxUeInfoTag, int rnti) {
    pthread_mutex_lock(&list_mutex);

    // Check for existing RNTI and append sequence number if necessary
    int original_rnti = rnti;
    size_t seq_num = 1;

    while (seq_num <= list_size) {
        if (pdu_list[seq_num - 1].rnti == rnti) {
            rnti = original_rnti + seq_num; // Modify RNTI to make it unique
            ++seq_num;
        } else {
            break;
        }
    }

    // Check if we need more space in the list and reallocate if necessary
    if (list_size >= allocated_size) {
        size_t new_allocated_size = allocated_size > 0 ? allocated_size * 2 : 4;
        NFAPI_CRC_INDICATION_PDU_T* temp_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_allocated_size);
        if (!temp_list) {
            pthread_mutex_unlock(&list_mutex);
            return -1; // Allocation failed
        }
        pdu_list = temp_list;
        allocated_size = new_allocated_size;
    }

    // Populate the PDU structure and add it to the list
    CRC_INDICATION_REL8_TAG_T crc_tag = { rand() % 2 }; // Randomly set CRCFLAG
    pdu_list[list_size].rxUeInfoTag = rxUeInfoTag;
    pdu_list[list_size].rnti = rnti;
    pdu_list[list_size].crcIndicationRel8Tag = crc_tag;

    ++list_size;

    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

// Function to free allocated resources
void cleanup_pdu_list() {
    pthread_mutex_lock(&list_mutex);
    if (pdu_list != NULL) {
        free(pdu_list);
        pdu_list = NULL;
    }
    list_size = 0;
    allocated_size = 0;
    pthread_mutex_unlock(&list_mutex);
}

// Example usage
int main() {
