    RX_UE_INFORMATION_TAG_T exampleTag = { .RNTI = 12345 }; // Populate with meaningful data

    add_pdu(exampleTag, 1001);
    add_pdu(exampleTag, 1002);
    add_pdu(exampleTag, 1001); // This will be adjusted to a unique RNTI

    cleanup_pdu_list();

    return 0;
}
```

