#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    char* radio_resource_configurations; // Simplified as string for demonstration.
    int connection_status; // 0: disconnected, 1: connected
} UESession;

typedef struct {
    UESession** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionList;

SessionList* create_session_list(size_t initial_capacity) {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    if (!list) return NULL;

    list->sessions = (UESession**)calloc(initial_capacity, sizeof(UESession*));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int resize_session_list(SessionList* list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);
    UESession** temp_sessions = (UESession**)realloc(list->sessions, new_capacity * sizeof(UESession*));
    if (!temp_sessions) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->sessions = temp_sessions;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int add_session(SessionList* list, UESession* session) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2; // Double the capacity
        if (resize_session_list(list, new_capacity)) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }
    list->sessions[list->count++] = session;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int remove_session(SessionList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->sessions[i]->ue_id == ue_id) {
            free(list->sessions[i]->radio_resource_configurations); // Assuming dynamic allocation
            free(list->sessions[i]);
            list->sessions[i] = list->sessions[--list->count];
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);

    return -1; // Session not found
}

void destroy_session_list(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->sessions[i]->radio_resource_configurations);
        free(list->sessions[i]);
    }
    free(list->sessions);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Unit tests and high-load scenario simulation functions

void test_session_management() {
    // Create a session list with initial capacity
    SessionList* list = create_session_list(4);

    // Simulate adding sessions
    for (int i = 1; i <= 10; ++i) {
        UESession* session = (UESession*)malloc(sizeof(UESession));
        session->ue_id = i;
        session->radio_resource_configurations = strdup("config");
        session->connection_status = 1;

        if (add_session(list, session)) {
            printf("Failed to add session for UE ID %d\n", i);
        }
    }

    // Simulate removing a session
    remove_session(list, 5);

    // Destroy the list
    destroy_session_list(list);
}

int main() {
    test_session_management();
    return 0;
}
```

