// Function to set CRCFLAG based on parity check over UE tags
void set_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t start, size_t end) {
    int parity = 0;
    for (size_t i = start; i < end; ++i) {
        parity ^= pdu[i].RX_UE_INFORMATION_TAG & 1;
    }
    pdu[start].CRCFLAG = (parity == 1) ? 1 : 0;
}

// Thread function to process a segment of UEs
void* process_ue_segment(void *arg) {
    struct {
        NFAPI_CRC_INDICATION_PDU_T *pdu_array;
        size_t start_index;
        size_t group_size;
        size_t total_ues;
    } *params = (struct {
        NFAPI_CRC_INDICATION_PDU_T *pdu_array;
        size_t start_index;
        size_t group_size;
        size_t total_ues;
    } *)arg;

    for (size_t i = params->start_index; i < params->total_ues; i += params->group_size) {
        set_crcflag(params->pdu_array, i, MIN(i + params->group_size, params->total_ues));
    }
    return NULL;
}

// Main function to generate and populate the array
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pdu(size_t N, size_t G) {
    if (N == 0 || G == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = generate_ue_tag();
        pdu_array[i].RNTI = generate_rnti();
        pdu_array[i].CRCFLAG = 0;
    }

    pthread_t threads[MAX_THREADS];
    size_t chunk_size = (N + MAX_THREADS - 1) / MAX_THREADS;

    for (int t = 0; t < MAX_THREADS && t * chunk_size < N; ++t) {
        struct {
            NFAPI_CRC_INDICATION_PDU_T *pdu_array;
            size_t start_index;
            size_t group_size;
            size_t total_ues;
        } params = { pdu_array, t * chunk_size, G, N };

        if (pthread_create(&threads[t], NULL, process_ue_segment, &params)) {
            fprintf(stderr, "Error creating thread\n");
            free(pdu_array);
            return NULL;
        }
    }

    for (int t = 0; t < MAX_THREADS && t * chunk_size < N; ++t) {
        pthread_join(threads[t], NULL);
    }

    return pdu_array;
}
