    free(memory);
}

ERROR_FLAG generate_and_process_crc_indications(int N, unsigned long initial_seed, void (*error_handler)(int)) {
    if (N <= 0) {
        log_event("Invalid value for N");
        return FAILURE;
    }

    seed = initial_seed;
    srand(seed);

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* crc_pdus = allocate_memory(N);
    ERROR_FLAG* error_flags = (ERROR_FLAG*)calloc(N, sizeof(ERROR_FLAG));
    if (!crc_pdus || !error_flags) {
        log_event("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return FAILURE;
    }
    pthread_mutex_unlock(&mutex);

    for (int i = 0; i < N; ++i) {
        int valid_tag = 0;
        int retry_count = 0;

        while (!valid_tag && retry_count < MAX_RETRIES) {
            RX_UE_INFORMATION_TAG tag = generate_rx_ue_information_tag();
            if (tag != -1) { // Assuming -1 indicates a failure to generate
                valid_tag = 1;
                log_event("Successfully generated RX_UE_INFORMATION_TAG");
            } else {
                retry_count++;
                log_event("Failed to generate RX_UE_INFORMATION_TAG, retrying...");
            }
        }

        if (!valid_tag) {
            error_flags[i] = FAILURE;
            (*error_handler)(i);
        } else {
            RNTI rnti = generate_rnti();
            if (rnti != -1) { // Assuming -1 indicates a failure to generate
                log_event("Successfully generated RNTI");
                crc_pdus[i].tag = tag; // Assign valid values here
                error_flags[i] = SUCCESS;
            } else {
                error_flags[i] = FAILURE;
                (*error_handler)(i);
            }
        }
    }

    pthread_mutex_lock(&mutex);
    free_memory(crc_pdus);
    free(error_flags);
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}
