    if (crc_array->count >= crc_array->capacity && crc_array->capacity < MAX_ARRAY_SIZE) {
        size_t new_capacity = crc_array->capacity * 2;
        if (new_capacity > MAX_ARRAY_SIZE) {
            new_capacity = MAX_ARRAY_SIZE;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            log_error("Failed to reallocate memory for CRC array");
            return -1;
        }

        crc_array->array = new_array;
        crc_array->capacity = new_capacity;
    } else if (crc_array->count >= MAX_ARRAY_SIZE) {
        log_error("Max array size reached, dropping element");
        return -2; // Drop the element
    }

    unsigned int crc_flag = hash_function(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
    memcpy(crc_array->array[crc_array->count].CRC_INDICATION_REL8_TAG, &crc_flag, sizeof(crc_flag));

    if (!validate_structure(&pdu)) {
        log_error("Validation failed for CRC indication structure");
        return -3; // Validation failed
    }

    crc_array->array[crc_array->count++] = pdu;
    return 0; // Success
}

void free_crc_array(CRCArray *crc_array) {
    if (crc_array) {
        free(crc_array->array);
        free(crc_array);
    }
}

void iterate_reverse_async(const CRCArray *crc_array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = crc_array->count; i > 0; --i) {
        callback(crc_array->array[i - 1]);
    }
}

// Example usage
int main() {
    CRCArray *crc_array = create_crc_array(INITIAL_ARRAY_SIZE);
    if (!crc_array) return -1;

    NFAPI_CRC_INDICATION_PDU_T example_pdu = {12345, 67890, {0}};
    int result = add_crc_indication(crc_array, example_pdu);

    if (result == 0) {
        iterate_reverse_async(crc_array, [](NFAPI_CRC_INDICATION_PDU_T pdu) {
            // Process each PDU
        });
    }

    free_crc_array(crc_array);
    return 0;
}
