        exit(EXIT_FAILURE);
    }
}

void destroy_pool(MemoryPool *pool) {
    free(pool->pool);
    pool->pool = NULL;
    pool->capacity = 0;
    pool->used = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool(MemoryPool *pool) {
    if (pool->used >= pool->capacity) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = 
        (NFAPI_CRC_INDICATION_PDU_T *)(((char*)pool->pool) + (pool->used * pool->element_size));
    memset(pdu, 0, pool->element_size);
    pool->used++;
    return pdu;
}

void deallocate_pdu(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;

    // Simple strategy: mark as free and reset data
    memset(pdu, 0, pool->element_size);
    pool->used--;
}

