#define MAX_TB_ENTRIES 10000
#define VALID_TBS_MIN 0
#define VALID_TBS_MAX 1024  // Example range for valid TBS values

typedef enum {
    MCS_1,
    MCS_2,
    MCS_3,
    // Add other modulation schemes here...
} ModulationScheme;

typedef struct {
    int TB_ID;
    size_t TBS;  // Transport Block Size
    ModulationScheme MCS;  // Modulation and Coding Scheme
} TransportBlock;

typedef struct Node {
    TransportBlock tb;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EnbQueue;

EnbQueue enbQueues[MAX_TB_ENTRIES];
int global_tb_ids[MAX_TB_ENTRIES] = {0};  // Global array to track TB_IDs across eNBs
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER; 

// Custom memory pool functions assumed
void* custom_malloc(size_t size);
void custom_free(void* ptr);

// Function prototypes
int add_transport_block(EnbQueue* queue, TransportBlock tb);
int is_tb_id_valid(int TB_ID);
int check_tbs_within_range(size_t TBS);
int map_mcs_to_supported_schemes(ModulationScheme MCS);

// Add a transport block to the eNB's queue
int add_transport_block(EnbQueue* queue, TransportBlock tb) {
    if (!is_tb_id_valid(tb.TB_ID)) return -1;
    if (check_tbs_within_range(tb.TBS) == 0) return -1;
    if (map_mcs_to_supported_schemes(tb.MCS) == 0) return -1;

    pthread_mutex_lock(&queue->lock);

    // Check for duplicate TB_ID within the same eNB
    Node* current = queue->head;
    while (current != NULL) {
        if (current->tb.TB_ID == tb.TB_ID) {
            pthread_mutex_unlock(&queue->lock);
            return -1;  // Duplicate TB_ID found in this eNB
        }
        current = current->next;
    }

    Node* newNode = (Node*)custom_malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&queue->lock);
        return -1;  // Memory allocation failed
    }

    newNode->tb = tb;
    newNode->next = queue->head;
    queue->head = newNode;

    pthread_mutex_unlock(&queue->lock);

    // Check for duplicate TB_ID across different eNBs using global lock
    pthread_mutex_lock(&global_lock);
    if (global_tb_ids[tb.TB_ID] != 0) {
        custom_free(newNode);
        pthread_mutex_unlock(&global_lock);
        return -1;  // Duplicate TB_ID found globally
    }
    global_tb_ids[tb.TB_ID] = 1;
    pthread_mutex_unlock(&global_lock);

    return 0;  // Successfully added the transport block
}

// Check if a given TB_ID is valid (not used by another eNB)
int is_tb_id_valid(int TB_ID) {
    pthread_mutex_lock(&global_lock);
    int isValid = global_tb_ids[TB_ID] == 0;
    pthread_mutex_unlock(&global_lock);
    return isValid;
}

// Ensure TBS values are within acceptable ranges
int check_tbs_within_range(size_t TBS) {
    return (TBS >= VALID_TBS_MIN && TBS <= VALID_TBS_MAX);
}

// Validate the MCS against supported schemes
int map_mcs_to_supported_schemes(ModulationScheme MCS) {
    switch (MCS) {
        case MCS_1:
        case MCS_2:
        case MCS_3:
            return 1;
        default:
            return 0;  // Unsupported modulation scheme
    }
}

// Initialize an eNB queue
void init_enb_queue(EnbQueue* queue) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}
