} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool header
typedef struct MemoryPoolHeader {
    size_t size;
    struct MemoryPoolHeader* next;
    int in_use;
} MemoryPoolHeader;

// Define the list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // For synchronization
    atomic_size_t index;  // Atomic for lock-free access tracking
    MemoryPoolHeader* pool;
} CRCIndicationList;

// Function prototypes
void initializeMemoryPool(MemoryPoolHeader** pool, size_t elementSize, size_t capacity);
NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPoolHeader* pool);
void deallocateToPool(MemoryPoolHeader* pool, void* ptr);
CRCIndicationList* createList(size_t initialCapacity, MemoryPoolHeader* pool);
int addElement(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T element);
void compactAndVerifyList(CRCIndicationList* list);

// Function implementations

void initializeMemoryPool(MemoryPoolHeader** pool, size_t elementSize, size_t capacity) {
    *pool = (MemoryPoolHeader*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(MemoryPoolHeader));
    (*pool)->size = capacity;
    MemoryPoolHeader* current = *pool;

    for (size_t i = 0; i < capacity; ++i) {
        void* elementPtr = (char*)current + sizeof(MemoryPoolHeader) + i * elementSize;
        current->next = (MemoryPoolHeader*)elementPtr;
        current = current->next;
    }
    current->next = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPoolHeader* pool) {
    while (pool && !pool->in_use) {
        if (!pthread_mutex_trylock(&pool->mutex)) {
            pool->in_use = 1;
            return (NFAPI_CRC_INDICATION_PDU_T*)pool;
        }
        pool = pool->next;
    }
    return NULL; // Pool exhausted
}

void deallocateToPool(MemoryPoolHeader* pool, void* ptr) {
    if (ptr && !atomic_compare_exchange_strong(&pool->in_use, &(int){1}, 0)) {
        pthread_mutex_unlock(&((MemoryPoolHeader*)ptr)->mutex);
    }
}

CRCIndicationList* createList(size_t initialCapacity, MemoryPoolHeader* pool) {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->index, 0);
    list->pool = pool;
    return list;
}

int addElement(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(list->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!newElements) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->elements = newElements;
        list->capacity = newCapacity;
    }

    size_t index = atomic_fetch_add(&list->index, 1);
    if (index >= list->size) {
        NFAPI_CRC_INDICATION_PDU_T* newElement = allocateFromPool(list->pool);

        if (!newElement) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Pool allocation failed
        }

        memcpy(newElement, &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->elements[index] = *newElement;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* currentElement = &list->elements[index];
        if (currentElement->rnti == element.rnti) {
            pthread_mutex_unlock(&list->lock);
            return -3; // RNTI conflict
        }

        *currentElement = element;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);

    compactAndVerifyList(list);  // Periodic maintenance
    return 0;
}

void compactAndVerifyList(CRCIndicationList* list) {
    // Implementation for compaction and integrity verification...
}
