#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set CRC flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_duplicate(LinkedList* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if ((current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
             current->data.RNTI == RNTI)) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicate
}

void log_warning(const char* message) {
    fprintf(stderr, "Warning: %s\n", message);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (is_duplicate(list, data.RX_UE_INFORMATION_TAG, data.RNTI)) {
        log_warning("Duplicate RX_UE_INFORMATION_TAG and RNTI detected.");
        return 0;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        perror("Memory allocation failed");
        return -1; // Memory allocation failure
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successful insertion
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) return EXIT_FAILURE;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Example tag
        pdu.RNTI = rand() % 65535;          // Example RNTI
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRC flag

        if (insert_node(list, pdu) != 1) {
            fprintf(stderr, "Failed to insert node.\n");
        }
    }

    free_linked_list(list);
    return EXIT_SUCCESS;
}
