typedef struct {
    int BAND;
    int BWP_ID;
    int enable;
} LTE_PHY_Layer_Config;

typedef struct {
    LTE_PHY_Layer_Config *configs;
    size_t count;
} LTE_PHY_Configuration;

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to update the configuration array with new data from XML
int update_configuration(LTE_PHY_Configuration *config, const char *filename) {
    xmlDocPtr doc = NULL;
    xmlNodePtr root_element = NULL;

    // Parse the XML file
    int rc = xmlReadFile(filename, NULL, 0);
    if (rc == -1) {
        log_error("Failed to parse XML file");
        return -1;
    }
    doc = xmlDocNewDoc((const xmlChar *)"1.0");
    xmlDocCopyNodeList(doc, xmlDocGetRootElement(xmlDocCopyNodeList(NULL, xmlDocCopyElementTree(NULL, xmlReadFile(filename, NULL, 0)), NULL)));
    root_element = xmlDocGetRootElement(doc);

    // Free old configuration
    if (config->configs) {
        free(config->configs);
        config->count = 0;
    }

    // Count the number of configurations
    size_t new_count = 0;
    for (xmlNodePtr cur_node = root_element->children; cur_node; cur_node = cur_node->next) {
        if ((!xmlStrcmp(cur_node->name, (const xmlChar *)"config"))) {
            new_count++;
        }
    }

    // Allocate memory for new configurations
    config->configs = malloc(new_count * sizeof(LTE_PHY_Layer_Config));
    if (!config->configs) {
        log_error("Memory allocation failed");
        xmlFreeDoc(doc);
        return -1;
    }
    config->count = new_count;

    // Parse each configuration node and populate the array
    size_t index = 0;
    for (xmlNodePtr cur_node = root_element->children; cur_node; cur_node = cur_node->next) {
        if ((!xmlStrcmp(cur_node->name, (const xmlChar *)"config"))) {
            xmlAttr *attr_band = NULL, *attr_bwp_id = NULL, *attr_enable = NULL;

            // Extract attributes
            for (xmlAttr *cur_attr = cur_node->properties; cur_attr; cur_attr = cur_attr->next) {
                if ((!xmlStrcmp(cur_attr->name, (const xmlChar *)"BAND"))) {
                    attr_band = cur_attr;
                } else if ((!xmlStrcmp(cur_attr->name, (const xmlChar *)"BWP_ID"))) {
                    attr_bwp_id = cur_attr;
                } else if ((!xmlStrcmp(cur_attr->name, (const xmlChar *)"enable"))) {
                    attr_enable = cur_attr;
                }
            }

            // Validate and assign attributes
            if (attr_band && attr_bwp_id && attr_enable) {
                config->configs[index].BAND = atoi((char *)xmlNodeListGetString(doc, attr_band->children, 1));
                config->configs[index].BWP_ID = atoi((char *)xmlNodeListGetString(doc, attr_bwp_id->children, 1));
                config->configs[index].enable = atoi((char *)xmlNodeListGetString(doc, attr_enable->children, 1));

                index++;
            } else {
                log_error("Malformed XML entry for a configuration");
                xmlFreeDoc(doc);
                free(config->configs);
                config->count = 0;
                return -1;
            }
        }
    }

    // Clean up
    xmlFreeDoc(doc);

    return 0; // Success
}

// Function to initialize the configuration from an XML file
int init_configuration(LTE_PHY_Configuration *config, const char *filename) {
    return update_configuration(config, filename);
}

// Example usage
int main() {
    LTE_PHY_Configuration config = {NULL, 0};

    if (init_configuration(&config, "lte_config.xml") == 0) {
        // Configuration initialized successfully
        printf("Configuration loaded with %zu entries.\n", config.count);

        // Use the configuration...

        // Free allocated memory when done
        free(config.configs);
    } else {
        // Handle initialization error
        fprintf(stderr, "Failed to initialize configuration\n");
    }

    return 0;
}
