['Below is a C implementation of a dynamic list manager for `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe mechanisms using mutexes. Additionally, I've included unit tests to ensure the functionality works as expected.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Assuming these are defined somewhere
typedef struct {
    // RX_UE_INFORMATION_TAG details
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;  // Random flag for demonstration
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic List structure
typedef struct {
    Node* head;
    int size;
    int max_size;
    pthread_mutex_t lock;  // Mutex for thread safety
} CRCList;

// Function to create a new list
CRCList* create_list(int max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Helper function to find a node by RNTI
Node* find_node(Node* head, unsigned int rnti) {
    while (head != NULL) {
        if (head->data.RNTI == rnti)
            return head;
        head = head->next;
    }
    return NULL;
}

// Function to add or update an entry in the list
void add_or_update_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL && (*current)->data.RNTI != entry.RNTI)
        current = &(*current)->next;

    if (*current == NULL) {  // Add new node
        if (list->size >= list->max_size) {
            fprintf(stderr, "List is at maximum capacity.\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }

        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = entry;
        newNode->next = *current;
        (*current) = newNode;
        list->size++;
    } else {  // Update existing node
        (*current)->data.crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to remove an entry by RNTI
void remove_entry(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL && (*current)->data.RNTI != rnti)
        current = &(*current)->next;

    if (*current == NULL) {
        fprintf(stderr, "Entry with RNTI %u not found.\n", rnti);
    } else {
        Node* temp = *current;
        *current = (*current)->next;
        free(temp);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to destroy the list
void destroy_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Unit Tests
void test_add_entry() {
    CRCList* list = create_list(10);

    NFAPI_CRC_INDICATION_PDU_T entry1 = {{}, 1, {0}};
    add_or_update_entry(list, entry1);
    assert(list->size == 1);

    destroy_list(list);
}

void test_update_entry() {
    CRCList* list = create_list(10);

    NFAPI_CRC_INDICATION_PDU_T entry1 = {{}, 1, {0}};
    add_or_update_entry(list, entry1);

    NFAPI_CRC_INDICATION_PDU_T updated_entry1 = {{}, 1, {1}};
    add_or_update_entry(list, updated_entry1);
    assert(list->head->data.crc_tag.CRCFLAG == rand() % 2);

    destroy_list(list);
}

void test_remove_entry() {
    CRCList* list = create_list(10);

    NFAPI_CRC_INDICATION_PDU_T entry1 = {{}, 1, {0}};
    add_or_update_entry(list, entry1);

    remove_entry(list, 1);
    assert(list->size == 0);

    destroy_list(list);
}

void test_full_capacity() {
    CRCList* list = create_list(1);

    NFAPI_CRC_INDICATION_PDU_T entry1 = {{}, 1, {0}};
    add_or_update_entry(list, entry1);

    NFAPI_CRC_INDICATION_PDU_T entry2 = {{}, 2, {0}};
    add_or_update_entry(list, entry2);
    assert(list->size == 1); // Should not exceed capacity

    destroy_list(list);
}

int main() {
    test_add_entry();
    test_update_entry();
    test_remove_entry();
    test_full_capacity();

    printf("All tests passed.\n");
    return 0;
}
