#define MAX_LOG_FREQUENCY 10

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
} DynamicList;

void init_dynamic_list(DynamicList *list, size_t initial_capacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for dynamic list");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
}

void free_dynamic_list(DynamicList *list) {
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
}

int resize_if_needed(DynamicList *list, unsigned short new_rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == new_rnti) {
            size_t new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_data) {
                perror("Failed to reallocate memory for dynamic list");
                return -1;
            }
            list->data = new_data;
            list->capacity = new_capacity;
            // Insert at the next available position
            memmove(&list->data[i + 1], &list->data[i], (list->size - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return 0;
        }
    }
    return 1;
}

void add_pdu(DynamicList *list, unsigned int rx_tag, unsigned short rnti, unsigned char crc_ind_rel8_tag) {
    if (resize_if_needed(list, rnti) == -1) {
        fprintf(stderr, "Error resizing list for RNTI: %u\n", rnti);
        return;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory for dynamic list");
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
    pdu.CRCFLAG = rand() % 2; // Random CRCFLAG

    list->data[list->size++] = pdu;
}

void log_memory_usage(const char *filename, size_t current_capacity) {
    static int call_count = 0;
    FILE *file = fopen(filename, "a");
    if (file) {
        fprintf(file, "Memory Usage: %zu bytes\n", current_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fclose(file);
    }
    ++call_count;
    if (call_count >= MAX_LOG_FREQUENCY) {
        call_count = 0; // Reset after logging
    }
}

void manage_list(size_t N, const char *log_filename) {
    srand(time(NULL));

    DynamicList list;
    init_dynamic_list(&list, 4); // Start with an initial capacity

    for (size_t i = 0; i < N; ++i) {
