        unsigned short rnti = rand() % 1024;
        unsigned char crc_ind_rel8_tag = rand() % 256;

        add_pdu(&list, rx_tag, rnti, crc_ind_rel8_tag);

        if (i % MAX_LOG_FREQUENCY == 0) {
            log_memory_usage(log_filename, list.capacity);
        }
    }

    free_dynamic_list(&list);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <number_of_pdus> <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t N = strtoul(argv[1], NULL, 10);
