['Here's a C code implementation for managing a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures using slab allocation:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define SLAB_SIZE 64 // Define the size of each slab

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize the dynamic array
int init_dynamic_array(DynamicArray* arr) {
    if (!arr) return -1;

    arr->data = NULL;
    arr->capacity = 0;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return 0;
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    if (!arr || !arr->data) return;

    free(arr->data);
    arr->data = NULL;
    arr->capacity = 0;
    arr->count = 0;
    pthread_mutex_destroy(&arr->lock);
}

// Function to resize the dynamic array
static int resize_array(DynamicArray* arr, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(arr->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    arr->data = new_data;
    arr->capacity = new_capacity;
    return 0;
}

// Function to populate the array with N elements
int populate_array(DynamicArray* arr, size_t n) {
    if (n <= 0) return -1;

    pthread_mutex_lock(&arr->lock);

    if (arr->count + n > arr->capacity) {
        size_t new_capacity = ((arr->count + n + SLAB_SIZE - 1) / SLAB_SIZE) * SLAB_SIZE;
        if (resize_array(arr, new_capacity) != 0) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failed
        }
    }

    for (size_t i = arr->count; i < arr->count + n; ++i) {
        arr->data[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        arr->data[i].RNTI = rand() % 4294967295;
        arr->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    arr->count += n;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Example usage
int main() {
    DynamicArray arr;
    if (init_dynamic_array(&arr) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    size_t n = 100; // Number of elements to add
    if (populate_array(&arr, n) != 0) {
        fprintf(stderr, "Failed to populate array\n");
        free_dynamic_array(&arr);
        return EXIT_FAILURE;
    }

    printf("Array populated with %zu elements.\n", arr.count);

    free_dynamic_array(&arr);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: The function uses a mutex (`pthread_mutex_t`) to ensure thread safety.
- **Slab Allocation**: Memory is allocated in chunks (slabs) of size `SLAB_SIZE` to minimize fragmentation and improve cache locality.
- **Dynamic Resizing**: The array resizes itself when more elements are added, using slab sizes to determine new capacity.
- **Memory Management**: Handles memory allocation failures gracefully and ensures all allocated memory is freed.']

